insert into control_room_bible (version, book, book_num, chapter, verse, text) values
  ('BSB', 'Deuteronomy', 5, 10, 14, 'Behold, to the LORD your God belong the heavens, even the highest heavens, and the earth and everything in it.'),
  ('BSB', 'Deuteronomy', 5, 10, 15, 'Yet the LORD has set His affection on your fathers and loved them. And He has chosen you, their descendants after them, above all the peoples, even to this day.'),
  ('BSB', 'Deuteronomy', 5, 10, 16, 'Circumcise your hearts, therefore, and stiffen your necks no more.'),
  ('BSB', 'Deuteronomy', 5, 10, 17, 'For the LORD your God is God of gods and Lord of lords, the great, mighty, and awesome God, showing no partiality and accepting no bribe.'),
  ('BSB', 'Deuteronomy', 5, 10, 18, 'He executes justice for the fatherless and widow, and He loves the foreigner, giving him food and clothing.'),
  ('BSB', 'Deuteronomy', 5, 10, 19, 'So you also must love the foreigner, since you yourselves were foreigners in the land of Egypt.'),
  ('BSB', 'Deuteronomy', 5, 10, 20, 'You are to fear the LORD your God and serve Him. Hold fast to Him and take your oaths in His name.'),
  ('BSB', 'Deuteronomy', 5, 10, 21, 'He is your praise and He is your God, who has done for you these great and awesome wonders that your eyes have seen.'),
  ('BSB', 'Deuteronomy', 5, 10, 22, 'Your fathers went down to Egypt, seventy in all, and now the LORD your God has made you as numerous as the stars in the sky.'),
  ('BSB', 'Deuteronomy', 5, 11, 1, 'You shall therefore love the LORD your God and always keep His charge, His statutes, His ordinances, and His commandments.'),
  ('BSB', 'Deuteronomy', 5, 11, 2, 'Know this day that it is not your children who have known and seen the discipline of the LORD your God: His greatness, His mighty hand, and His outstretched arm;'),
  ('BSB', 'Deuteronomy', 5, 11, 3, 'the signs and works He did in Egypt to Pharaoh king of Egypt and all his land;'),
  ('BSB', 'Deuteronomy', 5, 11, 4, 'what He did to the Egyptian army and horses and chariots when He made the waters of the Red Sea engulf them as they pursued you, and how He destroyed them completely, even to this day;'),
  ('BSB', 'Deuteronomy', 5, 11, 5, 'what He did for you in the wilderness until you reached this place;'),
  ('BSB', 'Deuteronomy', 5, 11, 6, 'and what He did in the midst of all the Israelites to Dathan and Abiram, the sons of Eliab the Reubenite, when the earth opened its mouth and swallowed them, their households, their tents, and every living thing that belonged to them.'),
  ('BSB', 'Deuteronomy', 5, 11, 7, 'For it is your own eyes that have seen every great work that the LORD has done.'),
  ('BSB', 'Deuteronomy', 5, 11, 8, 'You shall therefore keep every commandment I am giving you today, so that you may have the strength to go in and possess the land that you are crossing the Jordan to possess,'),
  ('BSB', 'Deuteronomy', 5, 11, 9, 'and so that you may live long in the land that the LORD swore to your fathers to give them and their descendants, a land flowing with milk and honey.'),
  ('BSB', 'Deuteronomy', 5, 11, 10, 'For the land that you are entering to possess is not like the land of Egypt, from which you have come, where you sowed your seed and irrigated on foot, like a vegetable garden.'),
  ('BSB', 'Deuteronomy', 5, 11, 11, 'But the land that you are crossing the Jordan to possess is a land of mountains and valleys that drinks in the rain from heaven.'),
  ('BSB', 'Deuteronomy', 5, 11, 12, 'It is a land for which the LORD your God cares; the eyes of the LORD your God are always on it, from the beginning to the end of the year.'),
  ('BSB', 'Deuteronomy', 5, 11, 13, 'So if you carefully obey the commandments I am giving you today, to love the LORD your God and to serve Him with all your heart and with all your soul,'),
  ('BSB', 'Deuteronomy', 5, 11, 14, 'then I will provide rain for your land in season, the autumn and spring rains, that you may gather your grain, new wine, and oil.'),
  ('BSB', 'Deuteronomy', 5, 11, 15, 'And I will provide grass in the fields for your livestock, and you will eat and be satisfied.'),
  ('BSB', 'Deuteronomy', 5, 11, 16, 'But be careful that you are not enticed to turn aside to worship and bow down to other gods,'),
  ('BSB', 'Deuteronomy', 5, 11, 17, 'or the anger of the LORD will be kindled against you. He will shut the heavens so that there will be no rain, nor will the land yield its produce, and you will soon perish from the good land that the LORD is giving you.'),
  ('BSB', 'Deuteronomy', 5, 11, 18, 'Fix these words of mine in your hearts and minds; tie them as reminders on your hands and bind them on your foreheads.'),
  ('BSB', 'Deuteronomy', 5, 11, 19, 'Teach them to your children, speaking about them when you sit at home and when you walk along the road, when you lie down and when you get up.'),
  ('BSB', 'Deuteronomy', 5, 11, 20, 'Write them on the doorposts of your houses and on your gates,'),
  ('BSB', 'Deuteronomy', 5, 11, 21, 'so that as long as the heavens are above the earth, your days and those of your children may be multiplied in the land that the LORD swore to give your fathers.'),
  ('BSB', 'Deuteronomy', 5, 11, 22, 'For if you carefully keep all these commandments I am giving you to follow—to love the LORD your God, to walk in all His ways, and to hold fast to Him—'),
  ('BSB', 'Deuteronomy', 5, 11, 23, 'then the LORD will drive out all these nations before you, and you will dispossess nations greater and stronger than you.'),
  ('BSB', 'Deuteronomy', 5, 11, 24, 'Every place where the sole of your foot treads will be yours. Your territory will extend from the wilderness to Lebanon, and from the Euphrates River to the Western Sea.'),
  ('BSB', 'Deuteronomy', 5, 11, 25, 'No man will be able to stand against you; the LORD your God will put the fear and dread of you upon all the land, wherever you set foot, as He has promised you.'),
  ('BSB', 'Deuteronomy', 5, 11, 26, 'See, today I am setting before you a blessing and a curse—'),
  ('BSB', 'Deuteronomy', 5, 11, 27, 'a blessing if you obey the commandments of the LORD your God that I am giving you today,'),
  ('BSB', 'Deuteronomy', 5, 11, 28, 'but a curse if you disobey the commandments of the LORD your God and turn aside from the path I command you today by following other gods, which you have not known.'),
  ('BSB', 'Deuteronomy', 5, 11, 29, 'When the LORD your God brings you into the land you are entering to possess, you are to proclaim the blessing on Mount Gerizim and the curse on Mount Ebal.'),
  ('BSB', 'Deuteronomy', 5, 11, 30, 'Are not these mountains across the Jordan, west of the road toward the sunset, in the land of the Canaanites who live in the Arabah opposite Gilgal near the Oak of Moreh?'),
  ('BSB', 'Deuteronomy', 5, 11, 31, 'For you are about to cross the Jordan to enter and possess the land that the LORD your God is giving you. When you take possession of it and settle in it,'),
  ('BSB', 'Deuteronomy', 5, 11, 32, 'be careful to follow all the statutes and ordinances that I am setting before you today.'),
  ('BSB', 'Deuteronomy', 5, 12, 1, 'These are the statutes and ordinances you must be careful to follow all the days you live in the land that the LORD, the God of your fathers, has given you to possess.'),
  ('BSB', 'Deuteronomy', 5, 12, 2, 'Destroy completely all the places where the nations you are dispossessing have served their gods—atop the high mountains, on the hills, and under every green tree.'),
  ('BSB', 'Deuteronomy', 5, 12, 3, 'Tear down their altars, smash their sacred pillars, burn up their Asherah poles, cut down the idols of their gods, and wipe out their names from every place.'),
  ('BSB', 'Deuteronomy', 5, 12, 4, 'You shall not worship the LORD your God in this way.'),
  ('BSB', 'Deuteronomy', 5, 12, 5, 'Instead, you must seek the place the LORD your God will choose from among all your tribes to establish as a dwelling for His Name, and there you must go.'),
  ('BSB', 'Deuteronomy', 5, 12, 6, 'To that place you are to bring your burnt offerings and sacrifices, your tithes and heave offerings, your vow offerings and freewill offerings, as well as the firstborn of your herds and flocks.'),
  ('BSB', 'Deuteronomy', 5, 12, 7, 'There, in the presence of the LORD your God, you and your households shall eat and rejoice in all you do, because the LORD your God has blessed you.'),
  ('BSB', 'Deuteronomy', 5, 12, 8, 'You are not to do as we are doing here today, where everyone does what seems right in his own eyes.'),
  ('BSB', 'Deuteronomy', 5, 12, 9, 'For you have not yet come to the resting place and the inheritance that the LORD your God is giving you.'),
  ('BSB', 'Deuteronomy', 5, 12, 10, 'When you cross the Jordan and live in the land that the LORD your God is giving you as an inheritance, and He gives you rest from all the enemies around you and you dwell securely,'),
  ('BSB', 'Deuteronomy', 5, 12, 11, 'then the LORD your God will choose a dwelling for His Name. And there you are to bring everything I command you: your burnt offerings and sacrifices, your tithes and special gifts, and all the choice offerings you vow to the LORD.'),
  ('BSB', 'Deuteronomy', 5, 12, 12, 'And you shall rejoice before the LORD your God—you, your sons and daughters, your menservants and maidservants, and the Levite within your gates, since he has no portion or inheritance among you.'),
  ('BSB', 'Deuteronomy', 5, 12, 13, 'Be careful not to offer your burnt offerings in just any place you see;'),
  ('BSB', 'Deuteronomy', 5, 12, 14, 'you must offer them only in the place the LORD will choose in one of your tribal territories, and there you shall do all that I command you.'),
  ('BSB', 'Deuteronomy', 5, 12, 15, 'But whenever you want, you may slaughter and eat meat within any of your gates, according to the blessing the LORD your God has given you. Both the ceremonially clean and unclean may eat it as they would a gazelle or deer,'),
  ('BSB', 'Deuteronomy', 5, 12, 16, 'but you must not eat the blood; pour it on the ground like water.'),
  ('BSB', 'Deuteronomy', 5, 12, 17, 'Within your gates you must not eat the tithe of your grain or new wine or oil, the firstborn of your herds or flocks, any of the offerings that you have vowed to give, or your freewill offerings or special gifts.'),
  ('BSB', 'Deuteronomy', 5, 12, 18, 'Instead, you must eat them in the presence of the LORD your God at the place the LORD your God will choose—you, your sons and daughters, your menservants and maidservants, and the Levite within your gates. Rejoice before the LORD your God in all you do,'),
  ('BSB', 'Deuteronomy', 5, 12, 19, 'and be careful not to neglect the Levites as long as you live in your land.'),
  ('BSB', 'Deuteronomy', 5, 12, 20, 'When the LORD your God expands your territory as He has promised, and you crave meat and say, “I want to eat meat,” you may eat it whenever you want.'),
  ('BSB', 'Deuteronomy', 5, 12, 21, 'If the place where the LORD your God chooses to put His Name is too far from you, then you may slaughter any of the herd or flock He has given you, as I have commanded you, and you may eat it within your gates whenever you want.'),
  ('BSB', 'Deuteronomy', 5, 12, 22, 'Indeed, you may eat it as you would eat a gazelle or deer; both the ceremonially unclean and the clean may eat it.'),
  ('BSB', 'Deuteronomy', 5, 12, 23, 'Only be sure not to eat the blood, because the blood is the life, and you must not eat the life with the meat.'),
  ('BSB', 'Deuteronomy', 5, 12, 24, 'You must not eat the blood; pour it on the ground like water.'),
  ('BSB', 'Deuteronomy', 5, 12, 25, 'Do not eat it, so that it may go well with you and your children after you, because you will be doing what is right in the eyes of the LORD.'),
  ('BSB', 'Deuteronomy', 5, 12, 26, 'But you are to take your holy things and your vow offerings and go to the place the LORD will choose.'),
  ('BSB', 'Deuteronomy', 5, 12, 27, 'Present the meat and blood of your burnt offerings on the altar of the LORD your God. The blood of your other sacrifices must be poured out beside the altar of the LORD your God, but you may eat the meat.'),
  ('BSB', 'Deuteronomy', 5, 12, 28, 'Be careful to obey all these things I command you, so that it may always go well with you and your children after you, because you will be doing what is good and right in the eyes of the LORD your God.'),
  ('BSB', 'Deuteronomy', 5, 12, 29, 'When the LORD your God cuts off before you the nations you are entering to dispossess, and you drive them out and live in their land,'),
  ('BSB', 'Deuteronomy', 5, 12, 30, 'be careful not to be ensnared by their ways after they have been destroyed before you. Do not inquire about their gods, asking, “How do these nations serve their gods? I will do likewise.”'),
  ('BSB', 'Deuteronomy', 5, 12, 31, 'You must not worship the LORD your God in this way, because they practice for their gods every abomination which the LORD hates. They even burn their sons and daughters in the fire as sacrifices to their gods.'),
  ('BSB', 'Deuteronomy', 5, 12, 32, 'See that you do everything I command you; do not add to it or subtract from it.'),
  ('BSB', 'Deuteronomy', 5, 13, 1, 'If a prophet or dreamer of dreams arises among you and proclaims a sign or wonder to you,'),
  ('BSB', 'Deuteronomy', 5, 13, 2, 'and if the sign or wonder he has spoken to you comes about, but he says, “Let us follow other gods (which you have not known) and let us worship them,”'),
  ('BSB', 'Deuteronomy', 5, 13, 3, 'you must not listen to the words of that prophet or dreamer. For the LORD your God is testing you to find out whether you love Him with all your heart and with all your soul.'),
  ('BSB', 'Deuteronomy', 5, 13, 4, 'You are to follow the LORD your God and fear Him. Keep His commandments and listen to His voice; serve Him and hold fast to Him.'),
  ('BSB', 'Deuteronomy', 5, 13, 5, 'Such a prophet or dreamer must be put to death, because he has advocated rebellion against the LORD your God, who brought you out of the land of Egypt and redeemed you from the house of slavery; he has tried to turn you from the way in which the LORD your God has commanded you to walk. So you must purge the evil from among you.'),
  ('BSB', 'Deuteronomy', 5, 13, 6, 'If your very own brother, or your son or daughter, or the wife you embrace, or your closest friend secretly entices you, saying, “Let us go and worship other gods” (which neither you nor your fathers have known,'),
  ('BSB', 'Deuteronomy', 5, 13, 7, 'the gods of the peoples around you, whether near or far, whether from one end of the earth or the other),'),
  ('BSB', 'Deuteronomy', 5, 13, 8, 'you must not yield to him or listen to him. Show him no pity, and do not spare him or shield him.'),
  ('BSB', 'Deuteronomy', 5, 13, 9, 'Instead, you must surely kill him. Your hand must be the first against him to put him to death, and then the hands of all the people.'),
  ('BSB', 'Deuteronomy', 5, 13, 10, 'Stone him to death for trying to turn you away from the LORD your God, who brought you out of the land of Egypt, out of the house of slavery.'),
  ('BSB', 'Deuteronomy', 5, 13, 11, 'Then all Israel will hear and be afraid, and will never again do such a wicked thing among you.'),
  ('BSB', 'Deuteronomy', 5, 13, 12, 'If, regarding one of the cities the LORD your God is giving you to inhabit, you hear it said'),
  ('BSB', 'Deuteronomy', 5, 13, 13, 'that wicked men have arisen from among you and have led the people of their city astray, saying, “Let us go and serve other gods” (which you have not known),'),
  ('BSB', 'Deuteronomy', 5, 13, 14, 'then you must inquire, investigate, and interrogate thoroughly. And if it is established with certainty that this abomination has been committed among you,'),
  ('BSB', 'Deuteronomy', 5, 13, 15, 'you must surely put the inhabitants of that city to the sword. Devote to destruction all its people and livestock.'),
  ('BSB', 'Deuteronomy', 5, 13, 16, 'And you are to gather all its plunder in the middle of the public square, and completely burn the city and all its plunder as a whole burnt offering to the LORD your God. The city must remain a mound of ruins forever, never to be rebuilt.'),
  ('BSB', 'Deuteronomy', 5, 13, 17, 'Nothing devoted to destruction shall cling to your hands, so that the LORD will turn from His fierce anger, grant you mercy, show you compassion, and multiply you as He swore to your fathers,'),
  ('BSB', 'Deuteronomy', 5, 13, 18, 'because you obey the LORD your God, keeping all His commandments I am giving you today and doing what is right in the eyes of the LORD your God.'),
  ('BSB', 'Deuteronomy', 5, 14, 1, 'You are sons of the LORD your God; do not cut yourselves or shave your foreheads on behalf of the dead,'),
  ('BSB', 'Deuteronomy', 5, 14, 2, 'for you are a people holy to the LORD your God. The LORD has chosen you to be a people for His prized possession out of all the peoples on the face of the earth.'),
  ('BSB', 'Deuteronomy', 5, 14, 3, 'You must not eat any detestable thing.'),
  ('BSB', 'Deuteronomy', 5, 14, 4, 'These are the animals that you may eat: The ox, the sheep, the goat,'),
  ('BSB', 'Deuteronomy', 5, 14, 5, 'the deer, the gazelle, the roe deer, the wild goat, the ibex, the antelope, and the mountain sheep.'),
  ('BSB', 'Deuteronomy', 5, 14, 6, 'You may eat any animal that has a split hoof divided in two and that chews the cud.'),
  ('BSB', 'Deuteronomy', 5, 14, 7, 'But of those that chew the cud or have a completely divided hoof, you are not to eat the following: the camel, the rabbit, or the rock badger.'),
  ('BSB', 'Deuteronomy', 5, 14, 8, 'Although they chew the cud, they do not have a divided hoof. They are unclean for you, as well as the pig; though it has a divided hoof, it does not chew the cud. It is unclean for you. You must not eat its meat or touch its carcass.'),
  ('BSB', 'Deuteronomy', 5, 14, 9, 'Of all the creatures that live in the water, you may eat anything with fins and scales,'),
  ('BSB', 'Deuteronomy', 5, 14, 10, 'but you may not eat anything that does not have fins and scales; it is unclean for you.'),
  ('BSB', 'Deuteronomy', 5, 14, 11, 'You may eat any clean bird,'),
  ('BSB', 'Deuteronomy', 5, 14, 12, 'but these you may not eat: the eagle, the bearded vulture, the black vulture,'),
  ('BSB', 'Deuteronomy', 5, 14, 13, 'the red kite, the falcon, any kind of kite,'),
  ('BSB', 'Deuteronomy', 5, 14, 14, 'any kind of raven,'),
  ('BSB', 'Deuteronomy', 5, 14, 15, 'the ostrich, the screech owl, the gull, any kind of hawk,'),
  ('BSB', 'Deuteronomy', 5, 14, 16, 'the little owl, the great owl, the white owl,'),
  ('BSB', 'Deuteronomy', 5, 14, 17, 'the desert owl, the osprey, the cormorant,'),
  ('BSB', 'Deuteronomy', 5, 14, 18, 'the stork, any kind of heron, the hoopoe, or the bat.'),
  ('BSB', 'Deuteronomy', 5, 14, 19, 'All flying insects are unclean for you; they may not be eaten.'),
  ('BSB', 'Deuteronomy', 5, 14, 20, 'But you may eat any clean bird.'),
  ('BSB', 'Deuteronomy', 5, 14, 21, 'You are not to eat any carcass; you may give it to the foreigner residing within your gates, and he may eat it, or you may sell it to a foreigner. For you are a holy people belonging to the LORD your God. You must not cook a young goat in its mother’s milk.'),
  ('BSB', 'Deuteronomy', 5, 14, 22, 'You must be sure to set aside a tenth of all the produce brought forth each year from your fields.'),
  ('BSB', 'Deuteronomy', 5, 14, 23, 'And you are to eat a tenth of your grain, new wine, and oil, and the firstborn of your herds and flocks, in the presence of the LORD your God at the place He will choose as a dwelling for His Name, so that you may learn to fear the LORD your God always.'),
  ('BSB', 'Deuteronomy', 5, 14, 24, 'But if the distance is too great for you to carry that with which the LORD your God has blessed you, because the place where the LORD your God will choose to put His Name is too far away,'),
  ('BSB', 'Deuteronomy', 5, 14, 25, 'then exchange it for money, take the money in your hand, and go to the place the LORD your God will choose.'),
  ('BSB', 'Deuteronomy', 5, 14, 26, 'Then you may spend the money on anything you desire: cattle, sheep, wine, strong drink, or anything you wish. You are to feast there in the presence of the LORD your God and rejoice with your household.'),
  ('BSB', 'Deuteronomy', 5, 14, 27, 'And do not neglect the Levite within your gates, since he has no portion or inheritance among you.'),
  ('BSB', 'Deuteronomy', 5, 14, 28, 'At the end of every three years, bring a tenth of all your produce for that year and lay it up within your gates.'),
  ('BSB', 'Deuteronomy', 5, 14, 29, 'Then the Levite (because he has no portion or inheritance among you), the foreigner, the fatherless, and the widow within your gates may come and eat and be satisfied. And the LORD your God will bless you in all the work of your hands.'),
  ('BSB', 'Deuteronomy', 5, 15, 1, 'At the end of every seven years you must cancel debts.'),
  ('BSB', 'Deuteronomy', 5, 15, 2, 'This is the manner of remission: Every creditor shall cancel what he has loaned to his neighbor. He is not to collect anything from his neighbor or brother, because the LORD’s time of release has been proclaimed.'),
  ('BSB', 'Deuteronomy', 5, 15, 3, 'You may collect something from a foreigner, but you must forgive whatever your brother owes you.'),
  ('BSB', 'Deuteronomy', 5, 15, 4, 'There will be no poor among you, however, because the LORD will surely bless you in the land that the LORD your God is giving you to possess as an inheritance,'),
  ('BSB', 'Deuteronomy', 5, 15, 5, 'if only you obey the LORD your God and are careful to follow all these commandments I am giving you today.'),
  ('BSB', 'Deuteronomy', 5, 15, 6, 'When the LORD your God blesses you as He has promised, you will lend to many nations but borrow from none; you will rule over many nations but be ruled by none.'),
  ('BSB', 'Deuteronomy', 5, 15, 7, 'If there is a poor man among your brothers within any of the gates in the land that the LORD your God is giving you, then you are not to harden your heart or shut your hand from your poor brother.'),
  ('BSB', 'Deuteronomy', 5, 15, 8, 'Instead, you are to open your hand to him and freely loan him whatever he needs.'),
  ('BSB', 'Deuteronomy', 5, 15, 9, 'Be careful not to harbor this wicked thought in your heart: “The seventh year, the year of release, is near,” so that you look upon your poor brother begrudgingly and give him nothing. He will cry out to the LORD against you, and you will be guilty of sin.'),
  ('BSB', 'Deuteronomy', 5, 15, 10, 'Give generously to him, and do not let your heart be grieved when you do so. And because of this the LORD your God will bless you in all your work and in everything to which you put your hand.'),
  ('BSB', 'Deuteronomy', 5, 15, 11, 'For there will never cease to be poor in the land; that is why I am commanding you to open wide your hand to your brother and to the poor and needy in your land.'),
  ('BSB', 'Deuteronomy', 5, 15, 12, 'If a fellow Hebrew, a man or a woman, is sold to you and serves you six years, then in the seventh year you must set him free.'),
  ('BSB', 'Deuteronomy', 5, 15, 13, 'And when you release him, do not send him away empty-handed.'),
  ('BSB', 'Deuteronomy', 5, 15, 14, 'You are to furnish him liberally from your flock, your threshing floor, and your winepress. You shall give to him as the LORD your God has blessed you.'),
  ('BSB', 'Deuteronomy', 5, 15, 15, 'Remember that you were slaves in the land of Egypt, and the LORD your God redeemed you; that is why I am giving you this command today.'),
  ('BSB', 'Deuteronomy', 5, 15, 16, 'But if your servant says to you, ‘I do not want to leave you,’ because he loves you and your household and is well off with you,'),
  ('BSB', 'Deuteronomy', 5, 15, 17, 'then take an awl and pierce it through his ear into the door, and he will become your servant for life. And treat your maidservant the same way.'),
  ('BSB', 'Deuteronomy', 5, 15, 18, 'Do not regard it as a hardship to set your servant free, because his six years of service were worth twice the wages of a hired hand. And the LORD your God will bless you in all you do.'),
  ('BSB', 'Deuteronomy', 5, 15, 19, 'You must set apart to the LORD your God every firstborn male produced by your herds and flocks. You are not to put the firstborn of your oxen to work, nor are you to shear the firstborn of your flock.'),
  ('BSB', 'Deuteronomy', 5, 15, 20, 'Each year you and your household are to eat it before the LORD your God in the place the LORD will choose.'),
  ('BSB', 'Deuteronomy', 5, 15, 21, 'But if an animal has a defect, is lame or blind, or has any serious flaw, you must not sacrifice it to the LORD your God.'),
  ('BSB', 'Deuteronomy', 5, 15, 22, 'Eat it within your gates; both the ceremonially unclean and clean may eat it as they would a gazelle or a deer.'),
  ('BSB', 'Deuteronomy', 5, 15, 23, 'But you must not eat the blood; pour it on the ground like water.'),
  ('BSB', 'Deuteronomy', 5, 16, 1, 'Observe the month of Abib and celebrate the Passover to the LORD your God, because in the month of Abib the LORD your God brought you out of Egypt by night.'),
  ('BSB', 'Deuteronomy', 5, 16, 2, 'You are to offer to the LORD your God the Passover sacrifice from the herd or flock in the place the LORD will choose as a dwelling for His Name.'),
  ('BSB', 'Deuteronomy', 5, 16, 3, 'You must not eat leavened bread with it; for seven days you are to eat with it unleavened bread, the bread of affliction, because you left the land of Egypt in haste—so that you may remember for the rest of your life the day you left the land of Egypt.'),
  ('BSB', 'Deuteronomy', 5, 16, 4, 'No leaven is to be found in all your land for seven days, and none of the meat you sacrifice in the evening of the first day shall remain until morning.'),
  ('BSB', 'Deuteronomy', 5, 16, 5, 'You are not to sacrifice the Passover animal in any of the towns that the LORD your God is giving you.'),
  ('BSB', 'Deuteronomy', 5, 16, 6, 'You must only offer the Passover sacrifice at the place the LORD your God will choose as a dwelling for His Name. Do this in the evening as the sun sets, at the same time you departed from Egypt.'),
  ('BSB', 'Deuteronomy', 5, 16, 7, 'And you shall roast it and eat it in the place the LORD your God will choose, and in the morning you shall return to your tents.'),
  ('BSB', 'Deuteronomy', 5, 16, 8, 'For six days you must eat unleavened bread, and on the seventh day you shall hold a solemn assembly to the LORD your God, and you must not do any work.'),
  ('BSB', 'Deuteronomy', 5, 16, 9, 'You are to count off seven weeks from the time you first put the sickle to the standing grain.'),
  ('BSB', 'Deuteronomy', 5, 16, 10, 'And you shall celebrate the Feast of Weeks to the LORD your God with a freewill offering that you give in proportion to how the LORD your God has blessed you,'),
  ('BSB', 'Deuteronomy', 5, 16, 11, 'and you shall rejoice before the LORD your God in the place He will choose as a dwelling for His Name—you, your sons and daughters, your menservants and maidservants, and the Levite within your gates, as well as the foreigner, the fatherless, and the widows among you.'),
  ('BSB', 'Deuteronomy', 5, 16, 12, 'Remember that you were slaves in Egypt, and carefully follow these statutes.'),
  ('BSB', 'Deuteronomy', 5, 16, 13, 'You are to celebrate the Feast of Tabernacles for seven days after you have gathered the produce of your threshing floor and your winepress.'),
  ('BSB', 'Deuteronomy', 5, 16, 14, 'And you shall rejoice in your feast—you, your sons and daughters, your menservants and maidservants, and the Levite, as well as the foreigner, the fatherless, and the widows among you.'),
  ('BSB', 'Deuteronomy', 5, 16, 15, 'For seven days you shall celebrate a feast to the LORD your God in the place He will choose, because the LORD your God will bless you in all your produce and in all the work of your hands, so that your joy will be complete.'),
  ('BSB', 'Deuteronomy', 5, 16, 16, 'Three times a year all your men are to appear before the LORD your God in the place He will choose: at the Feast of Unleavened Bread, the Feast of Weeks, and the Feast of Tabernacles. No one should appear before the LORD empty-handed.'),
  ('BSB', 'Deuteronomy', 5, 16, 17, 'Everyone must appear with a gift as he is able, according to the blessing the LORD your God has given you.'),
  ('BSB', 'Deuteronomy', 5, 16, 18, 'You are to appoint judges and officials for your tribes in every town that the LORD your God is giving you. They are to judge the people with righteous judgment.'),
  ('BSB', 'Deuteronomy', 5, 16, 19, 'Do not deny justice or show partiality. Do not accept a bribe, for a bribe blinds the eyes of the wise and twists the words of the righteous.'),
  ('BSB', 'Deuteronomy', 5, 16, 20, 'Pursue justice, and justice alone, so that you may live, and you may possess the land that the LORD your God is giving you.'),
  ('BSB', 'Deuteronomy', 5, 16, 21, 'Do not set up any wooden Asherah pole next to the altar you will build for the LORD your God,'),
  ('BSB', 'Deuteronomy', 5, 16, 22, 'and do not set up for yourselves a sacred pillar, which the LORD your God hates.'),
  ('BSB', 'Deuteronomy', 5, 17, 1, 'You shall not sacrifice to the LORD your God an ox or a sheep with any defect or serious flaw, for that is detestable to the LORD your God.'),
  ('BSB', 'Deuteronomy', 5, 17, 2, 'If a man or woman among you in one of the towns that the LORD your God gives you is found doing evil in the sight of the LORD your God by transgressing His covenant'),
  ('BSB', 'Deuteronomy', 5, 17, 3, 'and going to worship other gods, bowing down to them or to the sun or moon or any of the host of heaven—which I have forbidden—'),
  ('BSB', 'Deuteronomy', 5, 17, 4, 'and if it is reported and you hear about it, you must investigate it thoroughly. If the report is true and such an abomination has happened in Israel,'),
  ('BSB', 'Deuteronomy', 5, 17, 5, 'you must bring out to your gates the man or woman who has done this evil thing, and you must stone that person to death.'),
  ('BSB', 'Deuteronomy', 5, 17, 6, 'On the testimony of two or three witnesses a man shall be put to death, but he shall not be executed on the testimony of a lone witness.'),
  ('BSB', 'Deuteronomy', 5, 17, 7, 'The hands of the witnesses shall be the first in putting him to death, and after that, the hands of all the people. So you must purge the evil from among you.'),
  ('BSB', 'Deuteronomy', 5, 17, 8, 'If a case is too difficult for you to judge, whether the controversy within your gates is regarding bloodshed, lawsuits, or assaults, you must go up to the place the LORD your God will choose.'),
  ('BSB', 'Deuteronomy', 5, 17, 9, 'You are to go to the Levitical priests and to the judge who presides at that time. Inquire of them, and they will give you a verdict in the case.'),
  ('BSB', 'Deuteronomy', 5, 17, 10, 'You must abide by the verdict they give you at the place the LORD will choose. Be careful to do everything they instruct you,'),
  ('BSB', 'Deuteronomy', 5, 17, 11, 'according to the terms of law they give and the verdict they proclaim. Do not turn aside to the right or to the left from the decision they declare to you.'),
  ('BSB', 'Deuteronomy', 5, 17, 12, 'But the man who acts presumptuously, refusing to listen either to the priest who stands there to serve the LORD your God, or to the judge, must be put to death. You must purge the evil from Israel.'),
  ('BSB', 'Deuteronomy', 5, 17, 13, 'Then all the people will hear and be afraid, and will no longer behave arrogantly.'),
  ('BSB', 'Deuteronomy', 5, 17, 14, 'When you enter the land that the LORD your God is giving you and have taken possession of it and settled in it, and you say, “Let us set a king over us like all the nations around us,”'),
  ('BSB', 'Deuteronomy', 5, 17, 15, 'you are to appoint over yourselves the king whom the LORD your God shall choose. Appoint a king from among your brothers; you are not to set over yourselves a foreigner who is not one of your brothers.'),
  ('BSB', 'Deuteronomy', 5, 17, 16, 'But the king must not acquire many horses for himself or send the people back to Egypt to acquire more horses, for the LORD has said, ‘You are never to go back that way again.’'),
  ('BSB', 'Deuteronomy', 5, 17, 17, 'He must not take many wives for himself, lest his heart go astray. He must not accumulate for himself large amounts of silver and gold.'),
  ('BSB', 'Deuteronomy', 5, 17, 18, 'When he is seated on his royal throne, he must write for himself a copy of this instruction on a scroll in the presence of the Levitical priests.'),
  ('BSB', 'Deuteronomy', 5, 17, 19, 'It is to remain with him, and he is to read from it all the days of his life, so that he may learn to fear the LORD his God by carefully observing all the words of this instruction and these statutes.'),
  ('BSB', 'Deuteronomy', 5, 17, 20, 'Then his heart will not be exalted above his countrymen, and he will not turn aside from the commandment, to the right or to the left, in order that he and his sons may reign many years over his kingdom in Israel.'),
  ('BSB', 'Deuteronomy', 5, 18, 1, 'The Levitical priests—indeed the whole tribe of Levi—shall have no portion or inheritance with Israel. They are to eat the offerings made by fire to the LORD; that is their inheritance.'),
  ('BSB', 'Deuteronomy', 5, 18, 2, 'Although they have no inheritance among their brothers, the LORD is their inheritance, as He promised them.'),
  ('BSB', 'Deuteronomy', 5, 18, 3, 'This shall be the priests’ share from the people who offer a sacrifice, whether a bull or a sheep: the priests are to be given the shoulder, the jowls, and the stomach.'),
  ('BSB', 'Deuteronomy', 5, 18, 4, 'You are to give them the firstfruits of your grain, new wine, and oil, and the first wool sheared from your flock.'),
  ('BSB', 'Deuteronomy', 5, 18, 5, 'For the LORD your God has chosen Levi and his sons out of all your tribes to stand and minister in His name for all time.'),
  ('BSB', 'Deuteronomy', 5, 18, 6, 'Now if a Levite moves from any town of residence throughout Israel and comes in all earnestness to the place the LORD will choose,'),
  ('BSB', 'Deuteronomy', 5, 18, 7, 'then he shall serve in the name of the LORD his God like all his fellow Levites who stand there before the LORD.'),
  ('BSB', 'Deuteronomy', 5, 18, 8, 'They shall eat equal portions, even though he has received money from the sale of his father’s estate.'),
  ('BSB', 'Deuteronomy', 5, 18, 9, 'When you enter the land that the LORD your God is giving you, do not imitate the detestable ways of the nations there.'),
  ('BSB', 'Deuteronomy', 5, 18, 10, 'Let no one be found among you who sacrifices his son or daughter in the fire, practices divination or conjury, interprets omens, practices sorcery,'),
  ('BSB', 'Deuteronomy', 5, 18, 11, 'casts spells, consults a medium or spiritist, or inquires of the dead.'),
  ('BSB', 'Deuteronomy', 5, 18, 12, 'For whoever does these things is detestable to the LORD. And because of these detestable things, the LORD your God is driving out the nations before you.'),
  ('BSB', 'Deuteronomy', 5, 18, 13, 'You must be blameless before the LORD your God.'),
  ('BSB', 'Deuteronomy', 5, 18, 14, 'Though these nations, which you will dispossess, listen to conjurers and diviners, the LORD your God has not permitted you to do so.'),
  ('BSB', 'Deuteronomy', 5, 18, 15, 'The LORD your God will raise up for you a prophet like me from among your brothers. You must listen to him.'),
  ('BSB', 'Deuteronomy', 5, 18, 16, 'This is what you asked of the LORD your God at Horeb on the day of the assembly, when you said, “Let us not hear the voice of the LORD our God or see this great fire anymore, so that we will not die!”'),
  ('BSB', 'Deuteronomy', 5, 18, 17, 'Then the LORD said to me, “They have spoken well.'),
  ('BSB', 'Deuteronomy', 5, 18, 18, 'I will raise up for them a prophet like you from among their brothers. I will put My words in his mouth, and he will tell them everything I command him.'),
  ('BSB', 'Deuteronomy', 5, 18, 19, 'And I will hold accountable anyone who does not listen to My words that the prophet speaks in My name.'),
  ('BSB', 'Deuteronomy', 5, 18, 20, 'But if any prophet dares to speak a message in My name that I have not commanded him to speak, or to speak in the name of other gods, that prophet must be put to death.”'),
  ('BSB', 'Deuteronomy', 5, 18, 21, 'You may ask in your heart, “How can we recognize a message that the LORD has not spoken?”'),
  ('BSB', 'Deuteronomy', 5, 18, 22, 'When a prophet speaks in the name of the LORD and the message does not come to pass or come true, that is a message the LORD has not spoken. The prophet has spoken presumptuously. Do not be afraid of him.'),
  ('BSB', 'Deuteronomy', 5, 19, 1, 'When the LORD your God has cut off the nations whose land He is giving you, and when you have driven them out and settled in their cities and houses,'),
  ('BSB', 'Deuteronomy', 5, 19, 2, 'then you are to set apart for yourselves three cities within the land that the LORD your God is giving you to possess.'),
  ('BSB', 'Deuteronomy', 5, 19, 3, 'You are to build roads for yourselves and divide into three regions the land that the LORD your God is giving you as an inheritance, so that any manslayer can flee to these cities.'),
  ('BSB', 'Deuteronomy', 5, 19, 4, 'Now this is the situation regarding the manslayer who flees to one of these cities to save his life, having killed his neighbor accidentally, without intending to harm him:'),
  ('BSB', 'Deuteronomy', 5, 19, 5, 'If he goes into the forest with his neighbor to cut timber and swings his axe to chop down a tree, but the blade flies off the handle and strikes and kills his neighbor, he may flee to one of these cities to save his life.'),
  ('BSB', 'Deuteronomy', 5, 19, 6, 'Otherwise, the avenger of blood might pursue the manslayer in a rage, overtake him if the distance is great, and strike him dead though he did not deserve to die, since he did not intend any harm.'),
  ('BSB', 'Deuteronomy', 5, 19, 7, 'This is why I am commanding you to set apart for yourselves three cities.'),
  ('BSB', 'Deuteronomy', 5, 19, 8, 'And if the LORD your God enlarges your territory, as He swore to your fathers, and gives you all the land He promised them,'),
  ('BSB', 'Deuteronomy', 5, 19, 9, 'and if you carefully keep all these commandments I am giving you today, loving the LORD your God and walking in His ways at all times, then you are to add three more cities to these three.'),
  ('BSB', 'Deuteronomy', 5, 19, 10, 'Thus innocent blood will not be shed in the land that the LORD your God is giving you as an inheritance, so that you will not be guilty of bloodshed.'),
  ('BSB', 'Deuteronomy', 5, 19, 11, 'If, however, a man hates his neighbor and lies in wait, attacks him and kills him, and then flees to one of these cities,'),
  ('BSB', 'Deuteronomy', 5, 19, 12, 'the elders of his city must send for him, bring him back, and hand him over to the avenger of blood to die.'),
  ('BSB', 'Deuteronomy', 5, 19, 13, 'You must show him no pity. You are to purge from Israel the guilt of shedding innocent blood, that it may go well with you.'),
  ('BSB', 'Deuteronomy', 5, 19, 14, 'You must not move your neighbor’s boundary marker, which was set up by your ancestors to mark the inheritance you shall receive in the land that the LORD your God is giving you to possess.'),
  ('BSB', 'Deuteronomy', 5, 19, 15, 'A lone witness is not sufficient to establish any wrongdoing or sin against a man, regardless of what offense he may have committed. A matter must be established by the testimony of two or three witnesses.'),
  ('BSB', 'Deuteronomy', 5, 19, 16, 'If a false witness testifies against someone, accusing him of a crime,'),
  ('BSB', 'Deuteronomy', 5, 19, 17, 'both parties to the dispute must stand in the presence of the LORD, before the priests and judges who are in office at that time.'),
  ('BSB', 'Deuteronomy', 5, 19, 18, 'The judges shall investigate thoroughly, and if the witness is proven to be a liar who has falsely accused his brother,'),
  ('BSB', 'Deuteronomy', 5, 19, 19, 'you must do to him as he intended to do to his brother. So you must purge the evil from among you.'),
  ('BSB', 'Deuteronomy', 5, 19, 20, 'Then the rest of the people will hear and be afraid, and they will never again do anything so evil among you.'),
  ('BSB', 'Deuteronomy', 5, 19, 21, 'You must show no pity: life for life, eye for eye, tooth for tooth, hand for hand, and foot for foot.'),
  ('BSB', 'Deuteronomy', 5, 20, 1, 'When you go out to war against your enemies and see horses, chariots, and an army larger than yours, do not be afraid of them; for the LORD your God, who brought you out of the land of Egypt, is with you.'),
  ('BSB', 'Deuteronomy', 5, 20, 2, 'When you are about to go into battle, the priest is to come forward and address the army,'),
  ('BSB', 'Deuteronomy', 5, 20, 3, 'saying to them, “Hear, O Israel, today you are going into battle with your enemies. Do not be fainthearted or afraid; do not be alarmed or terrified because of them.'),
  ('BSB', 'Deuteronomy', 5, 20, 4, 'For the LORD your God goes with you to fight for you against your enemies, to give you the victory.”'),
  ('BSB', 'Deuteronomy', 5, 20, 5, 'Furthermore, the officers are to address the army, saying, “Has any man built a new house and not dedicated it? Let him return home, or he may die in battle and another man dedicate it.'),
  ('BSB', 'Deuteronomy', 5, 20, 6, 'Has any man planted a vineyard and not begun to enjoy its fruit? Let him return home, or he may die in battle and another man enjoy its fruit.'),
  ('BSB', 'Deuteronomy', 5, 20, 7, 'Has any man become pledged to a woman and not married her? Let him return home, or he may die in battle and another man marry her.”'),
  ('BSB', 'Deuteronomy', 5, 20, 8, 'Then the officers shall speak further to the army, saying, “Is any man afraid or fainthearted? Let him return home, so that the hearts of his brothers will not melt like his own.”'),
  ('BSB', 'Deuteronomy', 5, 20, 9, 'When the officers have finished addressing the army, they are to appoint commanders to lead it.'),
  ('BSB', 'Deuteronomy', 5, 20, 10, 'When you approach a city to fight against it, you are to make an offer of peace.'),
  ('BSB', 'Deuteronomy', 5, 20, 11, 'If they accept your offer of peace and open their gates, all the people there will become forced laborers to serve you.'),
  ('BSB', 'Deuteronomy', 5, 20, 12, 'But if they refuse to make peace with you and wage war against you, lay siege to that city.'),
  ('BSB', 'Deuteronomy', 5, 20, 13, 'When the LORD your God has delivered it into your hand, you must put every male to the sword.'),
  ('BSB', 'Deuteronomy', 5, 20, 14, 'But the women, children, livestock, and whatever else is in the city—all its spoil—you may take as plunder, and you shall use the spoil of your enemies that the LORD your God gives you.'),
  ('BSB', 'Deuteronomy', 5, 20, 15, 'This is how you are to treat all the cities that are far away from you and do not belong to the nations nearby.'),
  ('BSB', 'Deuteronomy', 5, 20, 16, 'However, in the cities of the nations that the LORD your God is giving you as an inheritance, you must not leave alive anything that breathes.'),
  ('BSB', 'Deuteronomy', 5, 20, 17, 'For you must devote them to complete destruction—the Hittites, Amorites, Canaanites, Perizzites, Hivites, and Jebusites—as the LORD your God has commanded you,'),
  ('BSB', 'Deuteronomy', 5, 20, 18, 'so that they cannot teach you to do all the detestable things they do for their gods, and so cause you to sin against the LORD your God.'),
  ('BSB', 'Deuteronomy', 5, 20, 19, 'When you lay siege to a city for an extended time while fighting against it to capture it, you must not destroy its trees by putting an axe to them, because you can eat their fruit. You must not cut them down. Are the trees of the field human, that you should besiege them?'),
  ('BSB', 'Deuteronomy', 5, 20, 20, 'But you may destroy the trees that you know do not produce fruit. Use them to build siege works against the city that is waging war against you, until it falls.'),
  ('BSB', 'Deuteronomy', 5, 21, 1, 'If one is found slain, lying in a field in the land that the LORD your God is giving you to possess, and it is not known who killed him,'),
  ('BSB', 'Deuteronomy', 5, 21, 2, 'your elders and judges must come out and measure the distance from the victim to the neighboring cities.'),
  ('BSB', 'Deuteronomy', 5, 21, 3, 'Then the elders of the city nearest the victim shall take a heifer that has never been yoked or used for work,'),
  ('BSB', 'Deuteronomy', 5, 21, 4, 'bring the heifer to a valley with running water that has not been plowed or sown, and break its neck there by the stream.'),
  ('BSB', 'Deuteronomy', 5, 21, 5, 'And the priests, the sons of Levi, shall come forward, for the LORD your God has chosen them to serve Him and pronounce blessings in His name and to give a ruling in every dispute and case of assault.'),
  ('BSB', 'Deuteronomy', 5, 21, 6, 'Then all the elders of the city nearest the victim shall wash their hands by the stream over the heifer whose neck has been broken,'),
  ('BSB', 'Deuteronomy', 5, 21, 7, 'and they shall declare, “Our hands did not shed this blood, nor did our eyes see it.'),
  ('BSB', 'Deuteronomy', 5, 21, 8, 'Accept this atonement, O LORD, for Your people Israel whom You have redeemed, and do not hold the shedding of innocent blood against them.” And the bloodshed will be atoned for.'),
  ('BSB', 'Deuteronomy', 5, 21, 9, 'So you shall purge from among you the guilt of shedding innocent blood, since you have done what is right in the eyes of the LORD.'),
  ('BSB', 'Deuteronomy', 5, 21, 10, 'When you go to war against your enemies and the LORD your God delivers them into your hand and you take them captive,'),
  ('BSB', 'Deuteronomy', 5, 21, 11, 'if you see a beautiful woman among them, and you desire her and want to take her as your wife,'),
  ('BSB', 'Deuteronomy', 5, 21, 12, 'then you shall bring her into your house. She must shave her head, trim her nails,'),
  ('BSB', 'Deuteronomy', 5, 21, 13, 'and put aside the clothing of her captivity. After she has lived in your house a full month and mourned her father and mother, you may have relations with her and be her husband, and she shall be your wife.'),
  ('BSB', 'Deuteronomy', 5, 21, 14, 'And if you are not pleased with her, you are to let her go wherever she wishes. But you must not sell her for money or treat her as a slave, since you have dishonored her.'),
  ('BSB', 'Deuteronomy', 5, 21, 15, 'If a man has two wives, one beloved and the other unloved, and both bear him sons, but the unloved wife has the firstborn son,'),
  ('BSB', 'Deuteronomy', 5, 21, 16, 'when that man assigns his inheritance to his sons he must not appoint the son of the beloved wife as the firstborn over the son of the unloved wife.'),
  ('BSB', 'Deuteronomy', 5, 21, 17, 'Instead, he must acknowledge the firstborn, the son of his unloved wife, by giving him a double portion of all that he has. For that son is the firstfruits of his father’s strength; the right of the firstborn belongs to him.'),
  ('BSB', 'Deuteronomy', 5, 21, 18, 'If a man has a stubborn and rebellious son who does not obey his father and mother and does not listen to them when disciplined,'),
  ('BSB', 'Deuteronomy', 5, 21, 19, 'his father and mother are to lay hold of him and bring him to the elders of his city, to the gate of his hometown,'),
  ('BSB', 'Deuteronomy', 5, 21, 20, 'and say to the elders, “This son of ours is stubborn and rebellious; he does not obey us. He is a glutton and a drunkard.”'),
  ('BSB', 'Deuteronomy', 5, 21, 21, 'Then all the men of his city will stone him to death. So you must purge the evil from among you, and all Israel will hear and be afraid.'),
  ('BSB', 'Deuteronomy', 5, 21, 22, 'If a man has committed a sin worthy of death, and he is executed, and you hang his body on a tree,'),
  ('BSB', 'Deuteronomy', 5, 21, 23, 'you must not leave the body on the tree overnight, but you must be sure to bury him that day, because anyone who is hung on a tree is under God’s curse. You must not defile the land that the LORD your God is giving you as an inheritance.'),
  ('BSB', 'Deuteronomy', 5, 22, 1, 'If you see your brother’s ox or sheep straying, you must not ignore it; be sure to return it to your brother.'),
  ('BSB', 'Deuteronomy', 5, 22, 2, 'If your brother does not live near you, or if you do not know who he is, you are to take the animal home to remain with you until your brother comes seeking it; then you can return it to him.'),
  ('BSB', 'Deuteronomy', 5, 22, 3, 'And you shall do the same for his donkey, his cloak, or anything your brother has lost and you have found. You must not ignore it.'),
  ('BSB', 'Deuteronomy', 5, 22, 4, 'If you see your brother’s donkey or ox fallen on the road, you must not ignore it; you must help him lift it up.'),
  ('BSB', 'Deuteronomy', 5, 22, 5, 'A woman must not wear men’s clothing, and a man must not wear women’s clothing, for whoever does these things is detestable to the LORD your God.'),
  ('BSB', 'Deuteronomy', 5, 22, 6, 'If you come across a bird’s nest with chicks or eggs, either in a tree or on the ground along the road, and the mother is sitting on the chicks or eggs, you must not take the mother along with the young.'),
  ('BSB', 'Deuteronomy', 5, 22, 7, 'You may take the young, but be sure to let the mother go, so that it may be well with you and that you may prolong your days.'),
  ('BSB', 'Deuteronomy', 5, 22, 8, 'If you build a new house, you are to construct a railing around your roof, so that you do not bring bloodguilt on your house if someone falls from it.'),
  ('BSB', 'Deuteronomy', 5, 22, 9, 'Do not plant your vineyard with two types of seed; if you do, the entire harvest will be defiled—both the crop you plant and the fruit of your vineyard.'),
  ('BSB', 'Deuteronomy', 5, 22, 10, 'Do not plow with an ox and a donkey yoked together.'),
  ('BSB', 'Deuteronomy', 5, 22, 11, 'Do not wear clothes of wool and linen woven together.'),
  ('BSB', 'Deuteronomy', 5, 22, 12, 'You are to make tassels on the four corners of the cloak you wear.'),
  ('BSB', 'Deuteronomy', 5, 22, 13, 'Suppose a man marries a woman, has relations with her, and comes to hate her,'),
  ('BSB', 'Deuteronomy', 5, 22, 14, 'and he then accuses her of shameful conduct and gives her a bad name, saying, “I married this woman and had relations with her, but I discovered she was not a virgin.”'),
  ('BSB', 'Deuteronomy', 5, 22, 15, 'Then the young woman’s father and mother shall bring the proof of her virginity to the city elders at the gate'),
  ('BSB', 'Deuteronomy', 5, 22, 16, 'and say to the elders, “I gave my daughter in marriage to this man, but he has come to hate her.'),
  ('BSB', 'Deuteronomy', 5, 22, 17, 'And now he has accused her of shameful conduct, saying, ‘I discovered that your daughter was not a virgin.’ But here is the proof of her virginity.” And they shall spread out the cloth before the city elders.'),
  ('BSB', 'Deuteronomy', 5, 22, 18, 'Then the elders of that city shall take the man and punish him.'),
  ('BSB', 'Deuteronomy', 5, 22, 19, 'They are also to fine him a hundred shekels of silver and give them to the young woman’s father, because this man has given a virgin of Israel a bad name. And she shall remain his wife; he must not divorce her as long as he lives.'),
  ('BSB', 'Deuteronomy', 5, 22, 20, 'If, however, this accusation is true, and no proof of the young woman’s virginity can be found,'),
  ('BSB', 'Deuteronomy', 5, 22, 21, 'she shall be brought to the door of her father’s house, and there the men of her city will stone her to death. For she has committed an outrage in Israel by being promiscuous in her father’s house. So you must purge the evil from among you.'),
  ('BSB', 'Deuteronomy', 5, 22, 22, 'If a man is found lying with another man’s wife, both the man who slept with her and the woman must die. You must purge the evil from Israel.'),
  ('BSB', 'Deuteronomy', 5, 22, 23, 'If there is a virgin pledged in marriage to a man, and another man encounters her in the city and sleeps with her,'),
  ('BSB', 'Deuteronomy', 5, 22, 24, 'you must take both of them out to the gate of that city and stone them to death—the young woman because she did not cry out in the city, and the man because he has violated his neighbor’s wife. So you must purge the evil from among you.'),
  ('BSB', 'Deuteronomy', 5, 22, 25, 'But if the man encounters a betrothed woman in the open country, and he overpowers her and lies with her, only the man who has done this must die.'),
  ('BSB', 'Deuteronomy', 5, 22, 26, 'Do nothing to the young woman, because she has committed no sin worthy of death. This case is just like one in which a man attacks his neighbor and murders him.'),
  ('BSB', 'Deuteronomy', 5, 22, 27, 'When he found her in the field, the betrothed woman cried out, but there was no one to save her.'),
  ('BSB', 'Deuteronomy', 5, 22, 28, 'If a man encounters a virgin who is not pledged in marriage, and he seizes her and lies with her, and they are discovered,'),
  ('BSB', 'Deuteronomy', 5, 22, 29, 'then the man who lay with her must pay the young woman’s father fifty shekels of silver, and she must become his wife because he has violated her. He must not divorce her as long as he lives.'),
  ('BSB', 'Deuteronomy', 5, 22, 30, 'A man is not to marry his father’s wife, so that he will not dishonor his father’s marriage bed.'),
  ('BSB', 'Deuteronomy', 5, 23, 1, 'No man with crushed or severed genitals may enter the assembly of the LORD.'),
  ('BSB', 'Deuteronomy', 5, 23, 2, 'No one of illegitimate birth may enter the assembly of the LORD, nor may any of his descendants, even to the tenth generation.'),
  ('BSB', 'Deuteronomy', 5, 23, 3, 'No Ammonite or Moabite or any of their descendants may enter the assembly of the LORD, even to the tenth generation.'),
  ('BSB', 'Deuteronomy', 5, 23, 4, 'For they did not meet you with food and water on your way out of Egypt, and they hired Balaam son of Beor from Pethor in Aram-naharaim to curse you.'),
  ('BSB', 'Deuteronomy', 5, 23, 5, 'Yet the LORD your God would not listen to Balaam, and the LORD your God turned the curse into a blessing for you, because the LORD your God loves you.'),
  ('BSB', 'Deuteronomy', 5, 23, 6, 'You are not to seek peace or prosperity from them as long as you live.'),
  ('BSB', 'Deuteronomy', 5, 23, 7, 'Do not despise an Edomite, for he is your brother. Do not despise an Egyptian, because you lived as a foreigner in his land.'),
  ('BSB', 'Deuteronomy', 5, 23, 8, 'The third generation of children born to them may enter the assembly of the LORD.'),
  ('BSB', 'Deuteronomy', 5, 23, 9, 'When you are encamped against your enemies, then you shall keep yourself from every wicked thing.'),
  ('BSB', 'Deuteronomy', 5, 23, 10, 'If any man among you becomes unclean because of a nocturnal emission, he must leave the camp and stay outside.'),
  ('BSB', 'Deuteronomy', 5, 23, 11, 'When evening approaches, he must wash with water, and when the sun sets he may return to the camp.'),
  ('BSB', 'Deuteronomy', 5, 23, 12, 'You must have a place outside the camp to go and relieve yourself.'),
  ('BSB', 'Deuteronomy', 5, 23, 13, 'And you must have a digging tool in your equipment so that when you relieve yourself you can dig a hole and cover up your excrement.'),
  ('BSB', 'Deuteronomy', 5, 23, 14, 'For the LORD your God walks throughout your camp to protect you and deliver your enemies to you. Your camp must be holy, lest He see anything unclean among you and turn away from you.'),
  ('BSB', 'Deuteronomy', 5, 23, 15, 'Do not return a slave to his master if he has taken refuge with you.'),
  ('BSB', 'Deuteronomy', 5, 23, 16, 'Let him live among you wherever he chooses, in the town of his pleasing. Do not oppress him.'),
  ('BSB', 'Deuteronomy', 5, 23, 17, 'No daughter or son of Israel is to be a shrine prostitute.'),
  ('BSB', 'Deuteronomy', 5, 23, 18, 'You must not bring the wages of a prostitute, whether female or male, into the house of the LORD your God to fulfill any vow, because both are detestable to the LORD your God.'),
  ('BSB', 'Deuteronomy', 5, 23, 19, 'Do not charge your brother interest on money, food, or any other type of loan.'),
  ('BSB', 'Deuteronomy', 5, 23, 20, 'You may charge a foreigner interest, but not your brother, so that the LORD your God may bless you in everything to which you put your hand in the land that you are entering to possess.'),
  ('BSB', 'Deuteronomy', 5, 23, 21, 'If you make a vow to the LORD your God, do not be slow to keep it, because He will surely require it of you, and you will be guilty of sin.'),
  ('BSB', 'Deuteronomy', 5, 23, 22, 'But if you refrain from making a vow, you will not be guilty of sin.'),
  ('BSB', 'Deuteronomy', 5, 23, 23, 'Be careful to follow through on what comes from your lips, because you have freely vowed to the LORD your God with your own mouth.'),
  ('BSB', 'Deuteronomy', 5, 23, 24, 'When you enter your neighbor’s vineyard, you may eat your fill of grapes, but you must not put any in your basket.'),
  ('BSB', 'Deuteronomy', 5, 23, 25, 'When you enter your neighbor’s grainfield, you may pluck the heads of grain with your hand, but you must not put a sickle to your neighbor’s grain.'),
  ('BSB', 'Deuteronomy', 5, 24, 1, 'If a man marries a woman, but she becomes displeasing to him because he finds some indecency in her, he may write her a certificate of divorce, hand it to her, and send her away from his house.'),
  ('BSB', 'Deuteronomy', 5, 24, 2, 'If, after leaving his house, she goes and becomes another man’s wife,'),
  ('BSB', 'Deuteronomy', 5, 24, 3, 'and the second man hates her, writes her a certificate of divorce, hands it to her, and sends her away from his house, or if he dies,'),
  ('BSB', 'Deuteronomy', 5, 24, 4, 'then the husband who divorced her first may not remarry her after she has been defiled, for that is an abomination to the LORD. You must not bring sin upon the land that the LORD your God is giving you as an inheritance.'),
  ('BSB', 'Deuteronomy', 5, 24, 5, 'If a man is newly married, he must not be sent to war or be pressed into any duty. For one year he is free to stay at home and bring joy to the wife he has married.'),
  ('BSB', 'Deuteronomy', 5, 24, 6, 'Do not take a pair of millstones or even an upper millstone as security for a debt, because that would be taking one’s livelihood as security.'),
  ('BSB', 'Deuteronomy', 5, 24, 7, 'If a man is caught kidnapping one of his Israelite brothers, whether he treats him as a slave or sells him, the kidnapper must die. So you must purge the evil from among you.'),
  ('BSB', 'Deuteronomy', 5, 24, 8, 'In cases of infectious skin diseases, be careful to diligently follow everything the Levitical priests instruct you. Be careful to do as I have commanded them.'),
  ('BSB', 'Deuteronomy', 5, 24, 9, 'Remember what the LORD your God did to Miriam on the journey after you came out of Egypt.'),
  ('BSB', 'Deuteronomy', 5, 24, 10, 'When you lend anything to your neighbor, do not enter his house to collect security.'),
  ('BSB', 'Deuteronomy', 5, 24, 11, 'You are to stand outside while the man to whom you are lending brings the security out to you.'),
  ('BSB', 'Deuteronomy', 5, 24, 12, 'If he is a poor man, you must not go to sleep with the security in your possession;'),
  ('BSB', 'Deuteronomy', 5, 24, 13, 'be sure to return it to him by sunset, so that he may sleep in his own cloak and bless you, and this will be credited to you as righteousness before the LORD your God.'),
  ('BSB', 'Deuteronomy', 5, 24, 14, 'Do not oppress a hired hand who is poor and needy, whether he is a brother or a foreigner residing in one of your towns.'),
  ('BSB', 'Deuteronomy', 5, 24, 15, 'You are to pay his wages each day before sunset, because he is poor and depends on them. Otherwise he may cry out to the LORD against you, and you will be guilty of sin.'),
  ('BSB', 'Deuteronomy', 5, 24, 16, 'Fathers shall not be put to death for their children, nor children for their fathers; each is to die for his own sin.'),
  ('BSB', 'Deuteronomy', 5, 24, 17, 'Do not deny justice to the foreigner or the fatherless, and do not take a widow’s cloak as security.'),
  ('BSB', 'Deuteronomy', 5, 24, 18, 'Remember that you were slaves in Egypt, and the LORD your God redeemed you from that place. Therefore I am commanding you to do this.'),
  ('BSB', 'Deuteronomy', 5, 24, 19, 'If you are harvesting in your field and forget a sheaf there, do not go back to get it. It is to be left for the foreigner, the fatherless, and the widow, so that the LORD your God may bless you in all the work of your hands.'),
  ('BSB', 'Deuteronomy', 5, 24, 20, 'When you beat the olives from your trees, you must not go over the branches again. What remains will be for the foreigner, the fatherless, and the widow.'),
  ('BSB', 'Deuteronomy', 5, 24, 21, 'When you gather the grapes of your vineyard, you must not go over the vines again. What remains will be for the foreigner, the fatherless, and the widow.'),
  ('BSB', 'Deuteronomy', 5, 24, 22, 'Remember that you were slaves in the land of Egypt. Therefore I am commanding you to do this.'),
  ('BSB', 'Deuteronomy', 5, 25, 1, 'If there is a dispute between men, they are to go to court to be judged, so that the innocent may be acquitted and the guilty condemned.'),
  ('BSB', 'Deuteronomy', 5, 25, 2, 'If the guilty man deserves to be beaten, the judge shall have him lie down and be flogged in his presence with the number of lashes his crime warrants.'),
  ('BSB', 'Deuteronomy', 5, 25, 3, 'He may receive no more than forty lashes, lest your brother be beaten any more than that and be degraded in your sight.'),
  ('BSB', 'Deuteronomy', 5, 25, 4, 'Do not muzzle an ox while it is treading out the grain.'),
  ('BSB', 'Deuteronomy', 5, 25, 5, 'When brothers dwell together and one of them dies without a son, the widow must not marry outside the family. Her husband’s brother is to take her as his wife and fulfill the duty of a brother-in-law for her.'),
  ('BSB', 'Deuteronomy', 5, 25, 6, 'The first son she bears will carry on the name of the dead brother, so that his name will not be blotted out from Israel.'),
  ('BSB', 'Deuteronomy', 5, 25, 7, 'But if the man does not want to marry his brother’s widow, she is to go to the elders at the city gate and say, “My husband’s brother refuses to preserve his brother’s name in Israel. He is not willing to perform the duty of a brother-in-law for me.”'),
  ('BSB', 'Deuteronomy', 5, 25, 8, 'Then the elders of his city shall summon him and speak with him. If he persists and says, “I do not want to marry her,”'),
  ('BSB', 'Deuteronomy', 5, 25, 9, 'his brother’s widow shall go up to him in the presence of the elders, remove his sandal, spit in his face, and declare, “This is what is done to the man who will not maintain his brother’s line.”'),
  ('BSB', 'Deuteronomy', 5, 25, 10, 'And his family name in Israel will be called “The House of the Unsandaled.”'),
  ('BSB', 'Deuteronomy', 5, 25, 11, 'If two men are fighting, and the wife of one steps in to rescue her husband from the one striking him, and she reaches out her hand and grabs his genitals,'),
  ('BSB', 'Deuteronomy', 5, 25, 12, 'you are to cut off her hand. You must show her no pity.'),
  ('BSB', 'Deuteronomy', 5, 25, 13, 'You shall not have two differing weights in your bag, one heavy and one light.'),
  ('BSB', 'Deuteronomy', 5, 25, 14, 'You shall not have two differing measures in your house, one large and one small.'),
  ('BSB', 'Deuteronomy', 5, 25, 15, 'You must maintain accurate and honest weights and measures, so that you may live long in the land that the LORD your God is giving you.'),
  ('BSB', 'Deuteronomy', 5, 25, 16, 'For everyone who behaves dishonestly in regard to these things is detestable to the LORD your God.'),
  ('BSB', 'Deuteronomy', 5, 25, 17, 'Remember what the Amalekites did to you along your way from Egypt,'),
  ('BSB', 'Deuteronomy', 5, 25, 18, 'how they met you on your journey when you were tired and weary, and they attacked all your stragglers; they had no fear of God.'),
  ('BSB', 'Deuteronomy', 5, 25, 19, 'When the LORD your God gives you rest from the enemies around you in the land that He is giving you to possess as an inheritance, you are to blot out the memory of Amalek from under heaven. Do not forget!'),
  ('BSB', 'Deuteronomy', 5, 26, 1, 'When you enter the land that the LORD your God is giving you as an inheritance, and you take possession of it and settle in it,'),
  ('BSB', 'Deuteronomy', 5, 26, 2, 'you are to take some of the firstfruits of all your produce from the soil of the land that the LORD your God is giving you and put them in a basket. Then go to the place the LORD your God will choose as a dwelling for His Name,'),
  ('BSB', 'Deuteronomy', 5, 26, 3, 'to the priest who is serving at that time, and say to him, “I declare today to the LORD your God that I have entered the land that the LORD swore to our fathers to give us.”'),
  ('BSB', 'Deuteronomy', 5, 26, 4, 'Then the priest shall take the basket from your hands and place it before the altar of the LORD your God,'),
  ('BSB', 'Deuteronomy', 5, 26, 5, 'and you are to declare before the LORD your God, “My father was a wandering Aramean, and he went down to Egypt few in number and lived there and became a great nation, mighty and numerous.'),
  ('BSB', 'Deuteronomy', 5, 26, 6, 'But the Egyptians mistreated us and afflicted us, putting us to hard labor.'),
  ('BSB', 'Deuteronomy', 5, 26, 7, 'So we called out to the LORD, the God of our fathers; and the LORD heard our voice and saw our affliction, toil, and oppression.'),
  ('BSB', 'Deuteronomy', 5, 26, 8, 'Then the LORD brought us out of Egypt with a mighty hand and an outstretched arm, with great terror, signs, and wonders.'),
  ('BSB', 'Deuteronomy', 5, 26, 9, 'And He brought us to this place and gave us this land, a land flowing with milk and honey.'),
  ('BSB', 'Deuteronomy', 5, 26, 10, 'And now, behold, I have brought the firstfruits of the land that You, O LORD, have given me.” Then you are to place the basket before the LORD your God and bow down before Him.'),
  ('BSB', 'Deuteronomy', 5, 26, 11, 'So you shall rejoice—you, the Levite, and the foreigner dwelling among you—in all the good things the LORD your God has given to you and your household.'),
  ('BSB', 'Deuteronomy', 5, 26, 12, 'When you have finished laying aside a tenth of all your produce in the third year, the year of the tithe, you are to give it to the Levite, the foreigner, the fatherless, and the widow, that they may eat and be filled within your gates.'),
  ('BSB', 'Deuteronomy', 5, 26, 13, 'Then you shall declare in the presence of the LORD your God, “I have removed from my house the sacred portion and have given it to the Levite, the foreigner, the fatherless, and the widow, according to all the commandments You have given me. I have not transgressed or forgotten Your commandments.'),
  ('BSB', 'Deuteronomy', 5, 26, 14, 'I have not eaten any of the sacred portion while in mourning, or removed any of it while unclean, or offered any of it for the dead. I have obeyed the LORD my God; I have done everything You commanded me.'),
  ('BSB', 'Deuteronomy', 5, 26, 15, 'Look down from Your holy habitation, from heaven, and bless Your people Israel and the land You have given us as You swore to our fathers—a land flowing with milk and honey.”'),
  ('BSB', 'Deuteronomy', 5, 26, 16, 'The LORD your God commands you this day to follow these statutes and ordinances. You must be careful to follow them with all your heart and with all your soul.'),
  ('BSB', 'Deuteronomy', 5, 26, 17, 'Today you have proclaimed that the LORD is your God and that you will walk in His ways, keep His statutes and commandments and ordinances, and listen to His voice.'),
  ('BSB', 'Deuteronomy', 5, 26, 18, 'And today the LORD has proclaimed that you are His people and treasured possession as He promised, that you are to keep all His commandments,'),
  ('BSB', 'Deuteronomy', 5, 26, 19, 'that He will set you high in praise and name and honor above all the nations He has made, and that you will be a holy people to the LORD your God, as He has promised.'),
  ('BSB', 'Deuteronomy', 5, 27, 1, 'Then Moses and the elders of Israel commanded the people: “Keep all the commandments I am giving you today.'),
  ('BSB', 'Deuteronomy', 5, 27, 2, 'And on the day you cross the Jordan into the land that the LORD your God is giving you, set up large stones and coat them with plaster.'),
  ('BSB', 'Deuteronomy', 5, 27, 3, 'Write on them all the words of this law when you have crossed over to enter the land that the LORD your God is giving you, a land flowing with milk and honey, just as the LORD, the God of your fathers, has promised you.'),
  ('BSB', 'Deuteronomy', 5, 27, 4, 'And when you have crossed the Jordan, you are to set up these stones on Mount Ebal, as I am commanding you today, and you are to coat them with plaster.'),
  ('BSB', 'Deuteronomy', 5, 27, 5, 'Moreover, you are to build there an altar to the LORD your God, an altar of stones. You must not use any iron tool on them.'),
  ('BSB', 'Deuteronomy', 5, 27, 6, 'You shall build the altar of the LORD your God with uncut stones and offer upon it burnt offerings to the LORD your God.'),
  ('BSB', 'Deuteronomy', 5, 27, 7, 'There you are to sacrifice your peace offerings, eating them and rejoicing in the presence of the LORD your God.'),
  ('BSB', 'Deuteronomy', 5, 27, 8, 'And you shall write distinctly upon these stones all the words of this law.”'),
  ('BSB', 'Deuteronomy', 5, 27, 9, 'Then Moses and the Levitical priests spoke to all Israel: “Be silent, O Israel, and listen! This day you have become the people of the LORD your God.'),
  ('BSB', 'Deuteronomy', 5, 27, 10, 'You shall therefore obey the voice of the LORD your God and follow His commandments and statutes I am giving you today.”'),
  ('BSB', 'Deuteronomy', 5, 27, 11, 'On that day Moses commanded the people:'),
  ('BSB', 'Deuteronomy', 5, 27, 12, '“When you have crossed the Jordan, these tribes shall stand on Mount Gerizim to bless the people: Simeon, Levi, Judah, Issachar, Joseph, and Benjamin.'),
  ('BSB', 'Deuteronomy', 5, 27, 13, 'And these tribes shall stand on Mount Ebal to deliver the curse: Reuben, Gad, Asher, Zebulun, Dan, and Naphtali.'),
  ('BSB', 'Deuteronomy', 5, 27, 14, 'Then the Levites shall proclaim in a loud voice to every Israelite:');
insert into control_room_bible (version, book, book_num, chapter, verse, text) values
  ('BSB', 'Deuteronomy', 5, 27, 15, '‘Cursed is the man who makes a carved idol or molten image—an abomination to the LORD, the work of the hands of a craftsman—and sets it up in secret.’ And let all the people say, ‘Amen!’'),
  ('BSB', 'Deuteronomy', 5, 27, 16, '‘Cursed is he who dishonors his father or mother.’ And let all the people say, ‘Amen!’'),
  ('BSB', 'Deuteronomy', 5, 27, 17, '‘Cursed is he who moves his neighbor’s boundary stone.’ And let all the people say, ‘Amen!’'),
  ('BSB', 'Deuteronomy', 5, 27, 18, '‘Cursed is he who lets a blind man wander in the road.’ And let all the people say, ‘Amen!’'),
  ('BSB', 'Deuteronomy', 5, 27, 19, '‘Cursed is he who withholds justice from the foreigner, the fatherless, or the widow.’ And let all the people say, ‘Amen!’'),
  ('BSB', 'Deuteronomy', 5, 27, 20, '‘Cursed is he who sleeps with his father’s wife, for he has violated his father’s marriage bed.’ And let all the people say, ‘Amen!’'),
  ('BSB', 'Deuteronomy', 5, 27, 21, '‘Cursed is he who lies with any animal.’ And let all the people say, ‘Amen!’'),
  ('BSB', 'Deuteronomy', 5, 27, 22, '‘Cursed is he who sleeps with his sister, the daughter of his father or the daughter of his mother.’ And let all the people say, ‘Amen!’'),
  ('BSB', 'Deuteronomy', 5, 27, 23, '‘Cursed is he who sleeps with his mother-in-law.’ And let all the people say, ‘Amen!’'),
  ('BSB', 'Deuteronomy', 5, 27, 24, '‘Cursed is he who strikes down his neighbor in secret.’ And let all the people say, ‘Amen!’'),
  ('BSB', 'Deuteronomy', 5, 27, 25, '‘Cursed is he who accepts a bribe to kill an innocent person.’ And let all the people say, ‘Amen!’'),
  ('BSB', 'Deuteronomy', 5, 27, 26, '‘Cursed is he who does not put the words of this law into practice.’ And let all the people say, ‘Amen!’'),
  ('BSB', 'Deuteronomy', 5, 28, 1, '“Now if you faithfully obey the voice of the LORD your God and are careful to follow all His commandments I am giving you today, the LORD your God will set you high above all the nations of the earth.'),
  ('BSB', 'Deuteronomy', 5, 28, 2, 'And all these blessings will come upon you and overtake you, if you will obey the voice of the LORD your God:'),
  ('BSB', 'Deuteronomy', 5, 28, 3, 'You will be blessed in the city and blessed in the country.'),
  ('BSB', 'Deuteronomy', 5, 28, 4, 'The fruit of your womb will be blessed, as well as the produce of your land and the offspring of your livestock— the calves of your herds and the lambs of your flocks.'),
  ('BSB', 'Deuteronomy', 5, 28, 5, 'Your basket and kneading bowl will be blessed.'),
  ('BSB', 'Deuteronomy', 5, 28, 6, 'You will be blessed when you come in and blessed when you go out.'),
  ('BSB', 'Deuteronomy', 5, 28, 7, 'The LORD will cause the enemies who rise up against you to be defeated before you. They will march out against you in one direction but flee from you in seven.'),
  ('BSB', 'Deuteronomy', 5, 28, 8, 'The LORD will decree a blessing on your barns and on everything to which you put your hand; the LORD your God will bless you in the land He is giving you.'),
  ('BSB', 'Deuteronomy', 5, 28, 9, 'The LORD will establish you as His holy people, just as He has sworn to you, if you keep the commandments of the LORD your God and walk in His ways.'),
  ('BSB', 'Deuteronomy', 5, 28, 10, 'Then all the peoples of the earth will see that you are called by the name of the LORD, and they will stand in awe of you.'),
  ('BSB', 'Deuteronomy', 5, 28, 11, 'The LORD will make you prosper abundantly—in the fruit of your womb, the offspring of your livestock, and the produce of your land—in the land that the LORD swore to your fathers to give you.'),
  ('BSB', 'Deuteronomy', 5, 28, 12, 'The LORD will open the heavens, His abundant storehouse, to send rain on your land in season and to bless all the work of your hands. You will lend to many nations, but borrow from none.'),
  ('BSB', 'Deuteronomy', 5, 28, 13, 'The LORD will make you the head and not the tail; you will only move upward and never downward, if you hear and carefully follow the commandments of the LORD your God, which I am giving you today.'),
  ('BSB', 'Deuteronomy', 5, 28, 14, 'Do not turn aside to the right or to the left from any of the words I command you today, and do not go after other gods to serve them.'),
  ('BSB', 'Deuteronomy', 5, 28, 15, 'If, however, you do not obey the LORD your God by carefully following all His commandments and statutes I am giving you today, all these curses will come upon you and overtake you:'),
  ('BSB', 'Deuteronomy', 5, 28, 16, 'You will be cursed in the city and cursed in the country.'),
  ('BSB', 'Deuteronomy', 5, 28, 17, 'Your basket and kneading bowl will be cursed.'),
  ('BSB', 'Deuteronomy', 5, 28, 18, 'The fruit of your womb will be cursed, as well as the produce of your land, the calves of your herds, and the lambs of your flocks.'),
  ('BSB', 'Deuteronomy', 5, 28, 19, 'You will be cursed when you come in and cursed when you go out.'),
  ('BSB', 'Deuteronomy', 5, 28, 20, 'The LORD will send curses upon you, confusion and reproof in all to which you put your hand, until you are destroyed and quickly perish because of the wickedness you have committed in forsaking Him.'),
  ('BSB', 'Deuteronomy', 5, 28, 21, 'The LORD will make the plague cling to you until He has exterminated you from the land that you are entering to possess.'),
  ('BSB', 'Deuteronomy', 5, 28, 22, 'The LORD will strike you with wasting disease, with fever and inflammation, with scorching heat and drought, and with blight and mildew; these will pursue you until you perish.'),
  ('BSB', 'Deuteronomy', 5, 28, 23, 'The sky over your head will be bronze, and the earth beneath you iron.'),
  ('BSB', 'Deuteronomy', 5, 28, 24, 'The LORD will turn the rain of your land into dust and powder; it will descend on you from the sky until you are destroyed.'),
  ('BSB', 'Deuteronomy', 5, 28, 25, 'The LORD will cause you to be defeated before your enemies. You will march out against them in one direction but flee from them in seven. You will be an object of horror to all the kingdoms of the earth.'),
  ('BSB', 'Deuteronomy', 5, 28, 26, 'Your corpses will be food for all the birds of the air and beasts of the earth, with no one to scare them away.'),
  ('BSB', 'Deuteronomy', 5, 28, 27, 'The LORD will afflict you with the boils of Egypt, with tumors and scabs and itch from which you cannot be cured.'),
  ('BSB', 'Deuteronomy', 5, 28, 28, 'The LORD will afflict you with madness, blindness, and confusion of mind,'),
  ('BSB', 'Deuteronomy', 5, 28, 29, 'and at noon you will grope about like a blind man in the darkness. You will not prosper in your ways. Day after day you will be oppressed and plundered, with no one to save you.'),
  ('BSB', 'Deuteronomy', 5, 28, 30, 'You will be pledged in marriage to a woman, but another man will violate her. You will build a house but will not live in it. You will plant a vineyard but will not enjoy its fruit.'),
  ('BSB', 'Deuteronomy', 5, 28, 31, 'Your ox will be slaughtered before your eyes, but you will not eat any of it. Your donkey will be taken away and not returned to you. Your flock will be given to your enemies, and no one will save you.'),
  ('BSB', 'Deuteronomy', 5, 28, 32, 'Your sons and daughters will be given to another nation, while your eyes grow weary looking for them day after day, with no power in your hand.'),
  ('BSB', 'Deuteronomy', 5, 28, 33, 'A people you do not know will eat the produce of your land and of all your toil. All your days you will be oppressed and crushed.'),
  ('BSB', 'Deuteronomy', 5, 28, 34, 'You will be driven mad by the sights you see.'),
  ('BSB', 'Deuteronomy', 5, 28, 35, 'The LORD will afflict you with painful, incurable boils on your knees and thighs, from the soles of your feet to the top of your head.'),
  ('BSB', 'Deuteronomy', 5, 28, 36, 'The LORD will bring you and the king you appoint to a nation neither you nor your fathers have known, and there you will worship other gods—gods of wood and stone.'),
  ('BSB', 'Deuteronomy', 5, 28, 37, 'You will become an object of horror, scorn, and ridicule among all the nations to which the LORD will drive you.'),
  ('BSB', 'Deuteronomy', 5, 28, 38, 'You will sow much seed in the field but harvest little, because the locusts will consume it.'),
  ('BSB', 'Deuteronomy', 5, 28, 39, 'You will plant and cultivate vineyards, but will neither drink the wine nor gather the grapes, because worms will eat them.'),
  ('BSB', 'Deuteronomy', 5, 28, 40, 'You will have olive trees throughout your territory but will never anoint yourself with oil, because the olives will drop off.'),
  ('BSB', 'Deuteronomy', 5, 28, 41, 'You will father sons and daughters, but they will not remain yours, because they will go into captivity.'),
  ('BSB', 'Deuteronomy', 5, 28, 42, 'Swarms of locusts will consume all your trees and the produce of your land.'),
  ('BSB', 'Deuteronomy', 5, 28, 43, 'The foreigner living among you will rise higher and higher above you, while you sink down lower and lower.'),
  ('BSB', 'Deuteronomy', 5, 28, 44, 'He will lend to you, but you will not lend to him. He will be the head, and you will be the tail.'),
  ('BSB', 'Deuteronomy', 5, 28, 45, 'All these curses will come upon you. They will pursue you and overtake you until you are destroyed, since you did not obey the LORD your God and keep the commandments and statutes He gave you.'),
  ('BSB', 'Deuteronomy', 5, 28, 46, 'These curses will be a sign and a wonder upon you and your descendants forever.'),
  ('BSB', 'Deuteronomy', 5, 28, 47, 'Because you did not serve the LORD your God with joy and gladness of heart in all your abundance,'),
  ('BSB', 'Deuteronomy', 5, 28, 48, 'you will serve your enemies the LORD will send against you in famine, thirst, nakedness, and destitution. He will place an iron yoke on your neck until He has destroyed you.'),
  ('BSB', 'Deuteronomy', 5, 28, 49, 'The LORD will bring a nation from afar, from the ends of the earth, to swoop down upon you like an eagle—a nation whose language you will not understand,'),
  ('BSB', 'Deuteronomy', 5, 28, 50, 'a ruthless nation with no respect for the old and no pity for the young.'),
  ('BSB', 'Deuteronomy', 5, 28, 51, 'They will eat the offspring of your livestock and the produce of your land until you are destroyed. They will leave you no grain or new wine or oil, no calves of your herds or lambs of your flocks, until they have caused you to perish.'),
  ('BSB', 'Deuteronomy', 5, 28, 52, 'They will besiege all the cities throughout your land, until the high and fortified walls in which you trust have fallen. They will besiege all your cities throughout the land that the LORD your God has given you.'),
  ('BSB', 'Deuteronomy', 5, 28, 53, 'Then you will eat the fruit of your womb, the flesh of the sons and daughters whom the LORD your God has given you, in the siege and distress that your enemy will inflict on you.'),
  ('BSB', 'Deuteronomy', 5, 28, 54, 'The most gentle and refined man among you will begrudge his brother, the wife he embraces, and the rest of his children who have survived,'),
  ('BSB', 'Deuteronomy', 5, 28, 55, 'refusing to share with any of them the flesh of his children he will eat because he has nothing left in the siege and distress that your enemy will inflict on you within all your gates.'),
  ('BSB', 'Deuteronomy', 5, 28, 56, 'The most gentle and refined woman among you, so gentle and refined she would not venture to set the sole of her foot on the ground, will begrudge the husband she embraces and her son and daughter'),
  ('BSB', 'Deuteronomy', 5, 28, 57, 'the afterbirth that comes from between her legs and the children she bears, because she will secretly eat them for lack of anything else in the siege and distress that your enemy will inflict on you within your gates.'),
  ('BSB', 'Deuteronomy', 5, 28, 58, 'If you are not careful to observe all the words of this law which are written in this book, that you may fear this glorious and awesome name—the LORD your God—'),
  ('BSB', 'Deuteronomy', 5, 28, 59, 'He will bring upon you and your descendants extraordinary disasters, severe and lasting plagues, and terrible and chronic sicknesses.'),
  ('BSB', 'Deuteronomy', 5, 28, 60, 'He will afflict you again with all the diseases you dreaded in Egypt, and they will cling to you.'),
  ('BSB', 'Deuteronomy', 5, 28, 61, 'The LORD will also bring upon you every sickness and plague not recorded in this Book of the Law, until you are destroyed.'),
  ('BSB', 'Deuteronomy', 5, 28, 62, 'You who were as numerous as the stars in the sky will be left few in number, because you would not obey the voice of the LORD your God.'),
  ('BSB', 'Deuteronomy', 5, 28, 63, 'Just as it pleased the LORD to make you prosper and multiply, so also it will please Him to annihilate you and destroy you. And you will be uprooted from the land you are entering to possess.'),
  ('BSB', 'Deuteronomy', 5, 28, 64, 'Then the LORD will scatter you among all the nations, from one end of the earth to the other, and there you will worship other gods, gods of wood and stone, which neither you nor your fathers have known.'),
  ('BSB', 'Deuteronomy', 5, 28, 65, 'Among those nations you will find no repose, not even a resting place for the sole of your foot. There the LORD will give you a trembling heart, failing eyes, and a despairing soul.'),
  ('BSB', 'Deuteronomy', 5, 28, 66, 'So your life will hang in doubt before you, and you will be afraid night and day, never certain of survival.'),
  ('BSB', 'Deuteronomy', 5, 28, 67, 'In the morning you will say, ‘If only it were evening!’ and in the evening you will say, ‘If only it were morning!’—because of the dread in your hearts of the terrifying sights you will see.'),
  ('BSB', 'Deuteronomy', 5, 28, 68, 'The LORD will return you to Egypt in ships by a route that I said you should never see again. There you will sell yourselves to your enemies as male and female slaves, but no one will buy you.”'),
  ('BSB', 'Deuteronomy', 5, 29, 1, 'These are the words of the covenant that the LORD commanded Moses to make with the Israelites in the land of Moab, in addition to the covenant He had made with them at Horeb.'),
  ('BSB', 'Deuteronomy', 5, 29, 2, 'Moses summoned all Israel and proclaimed to them, “You have seen with your own eyes everything the LORD did in Egypt to Pharaoh, to all his officials, and to all his land.'),
  ('BSB', 'Deuteronomy', 5, 29, 3, 'You saw with your own eyes the great trials, and those miraculous signs and wonders.'),
  ('BSB', 'Deuteronomy', 5, 29, 4, 'Yet to this day the LORD has not given you a mind to understand, eyes to see, or ears to hear.'),
  ('BSB', 'Deuteronomy', 5, 29, 5, 'For forty years I led you in the wilderness, yet your clothes and sandals did not wear out.'),
  ('BSB', 'Deuteronomy', 5, 29, 6, 'You ate no bread and drank no wine or strong drink, so that you might know that I am the LORD your God.'),
  ('BSB', 'Deuteronomy', 5, 29, 7, 'When you reached this place, Sihon king of Heshbon and Og king of Bashan came out against us in battle, but we defeated them.'),
  ('BSB', 'Deuteronomy', 5, 29, 8, 'We took their land and gave it as an inheritance to the Reubenites, the Gadites, and the half-tribe of Manasseh.'),
  ('BSB', 'Deuteronomy', 5, 29, 9, 'So keep and follow the words of this covenant, that you may prosper in all you do.'),
  ('BSB', 'Deuteronomy', 5, 29, 10, 'All of you are standing today before the LORD your God—you leaders of tribes, elders, officials, and all the men of Israel,'),
  ('BSB', 'Deuteronomy', 5, 29, 11, 'your children and wives, and the foreigners in your camps who cut your wood and draw your water—'),
  ('BSB', 'Deuteronomy', 5, 29, 12, 'so that you may enter into the covenant of the LORD your God, which He is making with you today, and into His oath,'),
  ('BSB', 'Deuteronomy', 5, 29, 13, 'and so that He may establish you today as His people, and He may be your God as He promised you and as He swore to your fathers, to Abraham, Isaac, and Jacob.'),
  ('BSB', 'Deuteronomy', 5, 29, 14, 'I am making this covenant and this oath not only with you,'),
  ('BSB', 'Deuteronomy', 5, 29, 15, 'but also with those who are standing here with us today in the presence of the LORD our God, as well as with those who are not here today.'),
  ('BSB', 'Deuteronomy', 5, 29, 16, 'For you yourselves know how we lived in the land of Egypt and how we passed through the nations on the way here.'),
  ('BSB', 'Deuteronomy', 5, 29, 17, 'You saw the abominations and idols among them made of wood and stone, of silver and gold.'),
  ('BSB', 'Deuteronomy', 5, 29, 18, 'Make sure there is no man or woman, clan or tribe among you today whose heart turns away from the LORD our God to go and worship the gods of those nations. Make sure there is no root among you that bears such poisonous and bitter fruit,'),
  ('BSB', 'Deuteronomy', 5, 29, 19, 'because when such a person hears the words of this oath, he invokes a blessing on himself, saying, ‘I will have peace, even though I walk in the stubbornness of my own heart.’ This will bring disaster on the watered land as well as the dry.'),
  ('BSB', 'Deuteronomy', 5, 29, 20, 'The LORD will never be willing to forgive him. Instead, His anger and jealousy will burn against that man, and every curse written in this book will fall upon him. The LORD will blot out his name from under heaven'),
  ('BSB', 'Deuteronomy', 5, 29, 21, 'and single him out from all the tribes of Israel for disaster, according to all the curses of the covenant written in this Book of the Law.'),
  ('BSB', 'Deuteronomy', 5, 29, 22, 'Then the generation to come—your sons who follow you and the foreigner who comes from a distant land—will see the plagues of the land and the sicknesses the LORD has inflicted on it.'),
  ('BSB', 'Deuteronomy', 5, 29, 23, 'All its soil will be a burning waste of sulfur and salt, unsown and unproductive, with no plant growing on it, just like the destruction of Sodom and Gomorrah, Admah and Zeboiim, which the LORD overthrew in His fierce anger.'),
  ('BSB', 'Deuteronomy', 5, 29, 24, 'So all the nations will ask, ‘Why has the LORD done such a thing to this land? Why this great outburst of anger?’'),
  ('BSB', 'Deuteronomy', 5, 29, 25, 'And the people will answer, ‘It is because they abandoned the covenant of the LORD, the God of their fathers, which He made with them when He brought them out of the land of Egypt.'),
  ('BSB', 'Deuteronomy', 5, 29, 26, 'They went and served other gods, and they worshiped gods they had not known—gods that the LORD had not given to them.'),
  ('BSB', 'Deuteronomy', 5, 29, 27, 'Therefore the anger of the LORD burned against this land, and He brought upon it every curse written in this book.'),
  ('BSB', 'Deuteronomy', 5, 29, 28, 'The LORD uprooted them from their land in His anger, rage, and great wrath, and He cast them into another land, where they are today.’'),
  ('BSB', 'Deuteronomy', 5, 29, 29, 'The secret things belong to the LORD our God, but the things revealed belong to us and to our children forever, so that we may follow all the words of this law.'),
  ('BSB', 'Deuteronomy', 5, 30, 1, '“When all these things come upon you—the blessings and curses I have set before you—and you call them to mind in all the nations to which the LORD your God has banished you,'),
  ('BSB', 'Deuteronomy', 5, 30, 2, 'and when you and your children return to the LORD your God and obey His voice with all your heart and all your soul according to everything I am giving you today,'),
  ('BSB', 'Deuteronomy', 5, 30, 3, 'then He will restore you from captivity and have compassion on you and gather you from all the nations to which the LORD your God has scattered you.'),
  ('BSB', 'Deuteronomy', 5, 30, 4, 'Even if you have been banished to the farthest horizon, He will gather you and return you from there.'),
  ('BSB', 'Deuteronomy', 5, 30, 5, 'And the LORD your God will bring you into the land your fathers possessed, and you will take possession of it. He will cause you to prosper and multiply more than your fathers.'),
  ('BSB', 'Deuteronomy', 5, 30, 6, 'The LORD your God will circumcise your hearts and the hearts of your descendants, and you will love Him with all your heart and with all your soul, so that you may live.'),
  ('BSB', 'Deuteronomy', 5, 30, 7, 'Then the LORD your God will put all these curses upon your enemies who hate you and persecute you.'),
  ('BSB', 'Deuteronomy', 5, 30, 8, 'And you will again obey the voice of the LORD and follow all His commandments I am giving you today.'),
  ('BSB', 'Deuteronomy', 5, 30, 9, 'So the LORD your God will make you abound in all the work of your hands and in the fruit of your womb, the offspring of your livestock, and the produce of your land. Indeed, the LORD will again delight in your goodness, as He delighted in that of your fathers,'),
  ('BSB', 'Deuteronomy', 5, 30, 10, 'if you obey the LORD your God by keeping His commandments and statutes that are written in this Book of the Law, and if you turn to Him with all your heart and with all your soul.'),
  ('BSB', 'Deuteronomy', 5, 30, 11, 'For this commandment I give you today is not too difficult for you or beyond your reach.'),
  ('BSB', 'Deuteronomy', 5, 30, 12, 'It is not in heaven, that you should need to ask, ‘Who will ascend into heaven to get it for us and proclaim it, that we may obey it?’'),
  ('BSB', 'Deuteronomy', 5, 30, 13, 'And it is not beyond the sea, that you should need to ask, ‘Who will cross the sea to get it for us and proclaim it, that we may obey it?’'),
  ('BSB', 'Deuteronomy', 5, 30, 14, 'But the word is very near you; it is in your mouth and in your heart, so that you may obey it.'),
  ('BSB', 'Deuteronomy', 5, 30, 15, 'See, I have set before you today life and goodness, as well as death and disaster.'),
  ('BSB', 'Deuteronomy', 5, 30, 16, 'For I am commanding you today to love the LORD your God, to walk in His ways, and to keep His commandments, statutes, and ordinances, so that you may live and increase, and the LORD your God may bless you in the land that you are entering to possess.'),
  ('BSB', 'Deuteronomy', 5, 30, 17, 'But if your heart turns away and you do not listen, but are drawn away to bow down to other gods and worship them,'),
  ('BSB', 'Deuteronomy', 5, 30, 18, 'I declare to you today that you will surely perish; you shall not prolong your days in the land that you are crossing the Jordan to possess.'),
  ('BSB', 'Deuteronomy', 5, 30, 19, 'I call heaven and earth as witnesses against you today that I have set before you life and death, blessing and cursing. Therefore choose life, so that you and your descendants may live,'),
  ('BSB', 'Deuteronomy', 5, 30, 20, 'and that you may love the LORD your God, obey Him, and hold fast to Him. For He is your life, and He will prolong your life in the land that the LORD swore to give to your fathers, to Abraham, Isaac, and Jacob.”'),
  ('BSB', 'Deuteronomy', 5, 31, 1, 'When Moses had finished speaking these words to all Israel,'),
  ('BSB', 'Deuteronomy', 5, 31, 2, 'he said to them, “I am now a hundred and twenty years old; I am no longer able to come and go, and the LORD has said to me, ‘You shall not cross the Jordan.’'),
  ('BSB', 'Deuteronomy', 5, 31, 3, 'The LORD your God Himself will cross over ahead of you. He will destroy these nations before you, and you will dispossess them. Joshua will cross ahead of you, as the LORD has said.'),
  ('BSB', 'Deuteronomy', 5, 31, 4, 'And the LORD will do to them as He did to Sihon and Og, the kings of the Amorites, when He destroyed them along with their land.'),
  ('BSB', 'Deuteronomy', 5, 31, 5, 'The LORD will deliver them over to you, and you must do to them exactly as I have commanded you.'),
  ('BSB', 'Deuteronomy', 5, 31, 6, 'Be strong and courageous; do not be afraid or terrified of them, for it is the LORD your God who goes with you; He will never leave you nor forsake you.”'),
  ('BSB', 'Deuteronomy', 5, 31, 7, 'Then Moses called for Joshua and said to him in the presence of all Israel, “Be strong and courageous, for you will go with this people into the land that the LORD swore to their fathers to give them, and you shall give it to them as an inheritance.'),
  ('BSB', 'Deuteronomy', 5, 31, 8, 'The LORD Himself goes before you; He will be with you. He will never leave you nor forsake you. Do not be afraid or discouraged.”'),
  ('BSB', 'Deuteronomy', 5, 31, 9, 'So Moses wrote down this law and gave it to the priests, the sons of Levi, who carried the ark of the covenant of the LORD, and to all the elders of Israel.'),
  ('BSB', 'Deuteronomy', 5, 31, 10, 'Then Moses commanded them, “At the end of every seven years, at the appointed time in the year of remission of debt, during the Feast of Tabernacles,'),
  ('BSB', 'Deuteronomy', 5, 31, 11, 'when all Israel comes before the LORD your God at the place He will choose, you are to read this law in the hearing of all Israel.'),
  ('BSB', 'Deuteronomy', 5, 31, 12, 'Assemble the people—men, women, children, and the foreigners within your gates—so that they may listen and learn to fear the LORD your God and to follow carefully all the words of this law.'),
  ('BSB', 'Deuteronomy', 5, 31, 13, 'Then their children who do not know the law will listen and learn to fear the LORD your God, as long as you live in the land that you are crossing the Jordan to possess.”'),
  ('BSB', 'Deuteronomy', 5, 31, 14, 'Then the LORD said to Moses, “Behold, the time of your death is near. Call Joshua and present yourselves at the Tent of Meeting, so that I may commission him.” So Moses and Joshua went and presented themselves at the Tent of Meeting.'),
  ('BSB', 'Deuteronomy', 5, 31, 15, 'Then the LORD appeared at the tent in a pillar of cloud, and the cloud stood over the entrance to the tent.'),
  ('BSB', 'Deuteronomy', 5, 31, 16, 'And the LORD said to Moses, “You will soon rest with your fathers, and these people will rise up and prostitute themselves with the foreign gods of the land they are entering. They will forsake Me and break the covenant I have made with them.'),
  ('BSB', 'Deuteronomy', 5, 31, 17, 'On that day My anger will burn against them, and I will abandon them and hide My face from them, so that they will be consumed, and many troubles and afflictions will befall them. On that day they will say, ‘Have not these disasters come upon us because our God is no longer with us?’'),
  ('BSB', 'Deuteronomy', 5, 31, 18, 'And on that day I will surely hide My face because of all the evil they have done by turning to other gods.'),
  ('BSB', 'Deuteronomy', 5, 31, 19, 'Now therefore, write down for yourselves this song and teach it to the Israelites; have them recite it, so that it may be a witness for Me against them.'),
  ('BSB', 'Deuteronomy', 5, 31, 20, 'When I have brought them into the land that I swore to give their fathers, a land flowing with milk and honey, they will eat their fill and prosper. Then they will turn to other gods and worship them, and they will reject Me and break My covenant.'),
  ('BSB', 'Deuteronomy', 5, 31, 21, 'And when many troubles and afflictions have come upon them, this song will testify against them, because it will not be forgotten from the lips of their descendants. For I know their inclination, even before I bring them into the land that I swore to give them.”'),
  ('BSB', 'Deuteronomy', 5, 31, 22, 'So that very day Moses wrote down this song and taught it to the Israelites.'),
  ('BSB', 'Deuteronomy', 5, 31, 23, 'Then the LORD commissioned Joshua son of Nun and said, “Be strong and courageous, for you will bring the Israelites into the land that I swore to give them, and I will be with you.”'),
  ('BSB', 'Deuteronomy', 5, 31, 24, 'When Moses had finished writing in a book the words of this law from beginning to end,'),
  ('BSB', 'Deuteronomy', 5, 31, 25, 'he gave this command to the Levites who carried the ark of the covenant of the LORD:'),
  ('BSB', 'Deuteronomy', 5, 31, 26, '“Take this Book of the Law and place it beside the ark of the covenant of the LORD your God, so that it may remain there as a witness against you.'),
  ('BSB', 'Deuteronomy', 5, 31, 27, 'For I know how rebellious and stiff-necked you are. If you are already rebelling against the LORD while I am still alive, how much more will you rebel after my death!'),
  ('BSB', 'Deuteronomy', 5, 31, 28, 'Assemble before me all the elders of your tribes and all your officers so that I may speak these words in their hearing and call heaven and earth to witness against them.'),
  ('BSB', 'Deuteronomy', 5, 31, 29, 'For I know that after my death you will become utterly corrupt and turn from the path I have commanded you. And in the days to come, disaster will befall you because you will do evil in the sight of the LORD to provoke Him to anger by the work of your hands.”'),
  ('BSB', 'Deuteronomy', 5, 31, 30, 'Then Moses recited aloud to the whole assembly of Israel the words of this song from beginning to end:'),
  ('BSB', 'Deuteronomy', 5, 32, 1, 'Give ear, O heavens, and I will speak; hear, O earth, the words of my mouth.'),
  ('BSB', 'Deuteronomy', 5, 32, 2, 'Let my teaching fall like rain and my speech settle like dew, like gentle rain on new grass, like showers on tender plants.'),
  ('BSB', 'Deuteronomy', 5, 32, 3, 'For I will proclaim the name of the LORD. Ascribe greatness to our God!'),
  ('BSB', 'Deuteronomy', 5, 32, 4, 'He is the Rock, His work is perfect; all His ways are just. A God of faithfulness without injustice, righteous and upright is He.'),
  ('BSB', 'Deuteronomy', 5, 32, 5, 'His people have acted corruptly toward Him; the spot on them is not that of His children, but of a perverse and crooked generation.'),
  ('BSB', 'Deuteronomy', 5, 32, 6, 'Is this how you repay the LORD, O foolish and senseless people? Is He not your Father and Creator? Has He not made you and established you?'),
  ('BSB', 'Deuteronomy', 5, 32, 7, 'Remember the days of old; consider the years long past. Ask your father, and he will tell you, your elders, and they will inform you.'),
  ('BSB', 'Deuteronomy', 5, 32, 8, 'When the Most High gave the nations their inheritance, when He divided the sons of man, He set the boundaries of the peoples according to the number of the sons of God.'),
  ('BSB', 'Deuteronomy', 5, 32, 9, 'But the LORD’s portion is His people, Jacob His allotted inheritance.'),
  ('BSB', 'Deuteronomy', 5, 32, 10, 'He found him in a desert land, in a barren, howling wilderness; He surrounded him, He instructed him, He guarded him as the apple of His eye.'),
  ('BSB', 'Deuteronomy', 5, 32, 11, 'As an eagle stirs up its nest and hovers over its young, He spread His wings to catch them and carried them on His pinions.'),
  ('BSB', 'Deuteronomy', 5, 32, 12, 'The LORD alone led him, and no foreign god was with him.'),
  ('BSB', 'Deuteronomy', 5, 32, 13, 'He made him ride on the heights of the land and fed him the produce of the field. He nourished him with honey from the rock and oil from the flinty crag,'),
  ('BSB', 'Deuteronomy', 5, 32, 14, 'with curds from the herd and milk from the flock, with the fat of lambs, with rams from Bashan, and goats, with the choicest grains of wheat. From the juice of the finest grapes you drank the wine.'),
  ('BSB', 'Deuteronomy', 5, 32, 15, 'But Jeshurun grew fat and kicked— becoming fat, bloated, and gorged. He abandoned the God who made him and scorned the Rock of his salvation.'),
  ('BSB', 'Deuteronomy', 5, 32, 16, 'They provoked His jealousy with foreign gods; they enraged Him with abominations.'),
  ('BSB', 'Deuteronomy', 5, 32, 17, 'They sacrificed to demons, not to God, to gods they had not known, to newly arrived gods, which your fathers did not fear.'),
  ('BSB', 'Deuteronomy', 5, 32, 18, 'You ignored the Rock who brought you forth; you forgot the God who gave you birth.'),
  ('BSB', 'Deuteronomy', 5, 32, 19, 'When the LORD saw this, He rejected them, provoked to anger by His sons and daughters.'),
  ('BSB', 'Deuteronomy', 5, 32, 20, 'He said: “I will hide My face from them; I will see what will be their end. For they are a perverse generation— children of unfaithfulness.'),
  ('BSB', 'Deuteronomy', 5, 32, 21, 'They have provoked My jealousy by that which is not God; they have enraged Me with their worthless idols. So I will make them jealous by those who are not a people; I will make them angry by a nation without understanding.'),
  ('BSB', 'Deuteronomy', 5, 32, 22, 'For a fire has been kindled by My anger, and it burns to the depths of Sheol; it consumes the earth and its produce, and scorches the foundations of the mountains.'),
  ('BSB', 'Deuteronomy', 5, 32, 23, 'I will heap disasters upon them; I will spend My arrows against them.'),
  ('BSB', 'Deuteronomy', 5, 32, 24, 'They will be wasted from hunger and ravaged by pestilence and bitter plague; I will send the fangs of wild beasts against them, with the venom of vipers that slither in the dust.'),
  ('BSB', 'Deuteronomy', 5, 32, 25, 'Outside, the sword will take their children, and inside, terror will strike the young man and the young woman, the infant and the gray-haired man.'),
  ('BSB', 'Deuteronomy', 5, 32, 26, 'I would have said that I would cut them to pieces and blot out their memory from mankind,'),
  ('BSB', 'Deuteronomy', 5, 32, 27, 'if I had not dreaded the taunt of the enemy, lest their adversaries misunderstand and say: ‘Our own hand has prevailed; it was not the LORD who did all this.’”'),
  ('BSB', 'Deuteronomy', 5, 32, 28, 'Israel is a nation devoid of counsel, with no understanding among them.'),
  ('BSB', 'Deuteronomy', 5, 32, 29, 'If only they were wise, they would understand it; they would comprehend their fate.'),
  ('BSB', 'Deuteronomy', 5, 32, 30, 'How could one man pursue a thousand, or two put ten thousand to flight, unless their Rock had sold them, unless the LORD had given them up?'),
  ('BSB', 'Deuteronomy', 5, 32, 31, 'For their rock is not like our Rock, even our enemies concede.'),
  ('BSB', 'Deuteronomy', 5, 32, 32, 'But their vine is from the vine of Sodom and from the fields of Gomorrah. Their grapes are poisonous; their clusters are bitter.'),
  ('BSB', 'Deuteronomy', 5, 32, 33, 'Their wine is the venom of serpents, the deadly poison of cobras.'),
  ('BSB', 'Deuteronomy', 5, 32, 34, '“Have I not stored up these things, sealed up within My vaults?'),
  ('BSB', 'Deuteronomy', 5, 32, 35, 'Vengeance is Mine; I will repay. In due time their foot will slip; for their day of disaster is near, and their doom is coming quickly.”'),
  ('BSB', 'Deuteronomy', 5, 32, 36, 'For the LORD will vindicate His people and have compassion on His servants when He sees that their strength is gone and no one remains, slave or free.'),
  ('BSB', 'Deuteronomy', 5, 32, 37, 'He will say: “Where are their gods, the rock in which they took refuge,'),
  ('BSB', 'Deuteronomy', 5, 32, 38, 'which ate the fat of their sacrifices and drank the wine of their drink offerings? Let them rise up and help you; let them give you shelter!'),
  ('BSB', 'Deuteronomy', 5, 32, 39, 'See now that I am He; there is no God besides Me. I bring death and I give life; I wound and I heal, and there is no one who can deliver from My hand.'),
  ('BSB', 'Deuteronomy', 5, 32, 40, 'For I lift up My hand to heaven and declare: As surely as I live forever,'),
  ('BSB', 'Deuteronomy', 5, 32, 41, 'when I sharpen My flashing sword, and My hand grasps it in judgment, I will take vengeance on My adversaries and repay those who hate Me.'),
  ('BSB', 'Deuteronomy', 5, 32, 42, 'I will make My arrows drunk with blood, while My sword devours flesh— the blood of the slain and captives, the heads of the enemy leaders.”'),
  ('BSB', 'Deuteronomy', 5, 32, 43, 'Rejoice, O heavens, with Him, and let all God’s angels worship Him. Rejoice, O nations, with His people; for He will avenge the blood of His children. He will take vengeance on His adversaries and repay those who hate Him; He will cleanse His land and His people.'),
  ('BSB', 'Deuteronomy', 5, 32, 44, 'Then Moses came with Joshua son of Nun and recited all the words of this song in the hearing of the people.'),
  ('BSB', 'Deuteronomy', 5, 32, 45, 'When Moses had finished reciting all these words to all Israel,'),
  ('BSB', 'Deuteronomy', 5, 32, 46, 'he said to them, “Take to heart all these words I testify among you today, so that you may command your children to carefully follow all the words of this law.'),
  ('BSB', 'Deuteronomy', 5, 32, 47, 'For they are not idle words to you, because they are your life, and by them you will live long in the land that you are crossing the Jordan to possess.”'),
  ('BSB', 'Deuteronomy', 5, 32, 48, 'On that same day the LORD said to Moses,'),
  ('BSB', 'Deuteronomy', 5, 32, 49, '“Go up into the Abarim Range to Mount Nebo, in the land of Moab across from Jericho, and view the land of Canaan, which I am giving to the Israelites as their own possession.'),
  ('BSB', 'Deuteronomy', 5, 32, 50, 'And there on the mountain that you climb, you will die and be gathered to your people, just as your brother Aaron died on Mount Hor and was gathered to his people.'),
  ('BSB', 'Deuteronomy', 5, 32, 51, 'For at the waters of Meribah-kadesh in the Wilderness of Zin, both of you broke faith with Me among the Israelites by failing to treat Me as holy in their presence.'),
  ('BSB', 'Deuteronomy', 5, 32, 52, 'Although you shall see from a distance the land that I am giving the Israelites, you shall not enter it.”'),
  ('BSB', 'Deuteronomy', 5, 33, 1, 'This is the blessing that Moses the man of God pronounced upon the Israelites before his death.'),
  ('BSB', 'Deuteronomy', 5, 33, 2, 'He said: “The LORD came from Sinai and dawned upon us from Seir; He shone forth from Mount Paran and came with myriads of holy ones, with flaming fire at His right hand.'),
  ('BSB', 'Deuteronomy', 5, 33, 3, 'Surely You love the people; all the holy ones are in Your hand, and they sit down at Your feet; each receives Your words—'),
  ('BSB', 'Deuteronomy', 5, 33, 4, 'the law that Moses gave us, the possession of the assembly of Jacob.'),
  ('BSB', 'Deuteronomy', 5, 33, 5, 'So the LORD became King in Jeshurun when the leaders of the people gathered, when the tribes of Israel came together.'),
  ('BSB', 'Deuteronomy', 5, 33, 6, 'Let Reuben live and not die, nor his men be few.”'),
  ('BSB', 'Deuteronomy', 5, 33, 7, 'And concerning Judah he said: “O LORD, hear the cry of Judah and bring him to his people. With his own hands he defends his cause, but may You be a help against his foes.”'),
  ('BSB', 'Deuteronomy', 5, 33, 8, 'Concerning Levi he said: “Give Your Thummim to Levi and Your Urim to Your godly one, whom You tested at Massah and contested at the waters of Meribah.'),
  ('BSB', 'Deuteronomy', 5, 33, 9, 'He said of his father and mother, ‘I do not consider them.’ He disregarded his brothers and did not know his own sons, for he kept Your word and maintained Your covenant.'),
  ('BSB', 'Deuteronomy', 5, 33, 10, 'He will teach Your ordinances to Jacob and Your law to Israel; he will set incense before You and whole burnt offerings on Your altar.'),
  ('BSB', 'Deuteronomy', 5, 33, 11, 'Bless his substance, O LORD, and accept the work of his hands. Smash the loins of those who rise against him, and of his foes so they can rise no more.”'),
  ('BSB', 'Deuteronomy', 5, 33, 12, 'Concerning Benjamin he said: “May the beloved of the LORD rest secure in Him; God shields him all day long, and upon His shoulders he rests.”'),
  ('BSB', 'Deuteronomy', 5, 33, 13, 'Concerning Joseph he said: “May his land be blessed by the LORD with the precious dew from heaven above and the deep waters that lie beneath,'),
  ('BSB', 'Deuteronomy', 5, 33, 14, 'with the bountiful harvest from the sun and the abundant yield of the seasons,'),
  ('BSB', 'Deuteronomy', 5, 33, 15, 'with the best of the ancient mountains and the bounty of the everlasting hills,'),
  ('BSB', 'Deuteronomy', 5, 33, 16, 'with the choice gifts of the land and everything in it, and with the favor of Him who dwelt in the burning bush. May these rest on the head of Joseph and crown the brow of the prince of his brothers.'),
  ('BSB', 'Deuteronomy', 5, 33, 17, 'His majesty is like a firstborn bull, and his horns are like those of a wild ox. With them he will gore the nations, even to the ends of the earth. Such are the myriads of Ephraim, and such are the thousands of Manasseh.”'),
  ('BSB', 'Deuteronomy', 5, 33, 18, 'Concerning Zebulun he said: “Rejoice, Zebulun, in your journeys, and Issachar, in your tents.'),
  ('BSB', 'Deuteronomy', 5, 33, 19, 'They will call the peoples to a mountain; there they will offer sacrifices of righteousness. For they will feast on the abundance of the seas and the hidden treasures of the sand.”'),
  ('BSB', 'Deuteronomy', 5, 33, 20, 'Concerning Gad he said: “Blessed is he who enlarges the domain of Gad! He lies down like a lion and tears off an arm or a head.'),
  ('BSB', 'Deuteronomy', 5, 33, 21, 'He chose the best land for himself, because a ruler’s portion was reserved for him there. He came with the leaders of the people; he administered the LORD’s justice and His ordinances for Israel.”'),
  ('BSB', 'Deuteronomy', 5, 33, 22, 'Concerning Dan he said: “Dan is a lion’s cub, leaping out of Bashan.”'),
  ('BSB', 'Deuteronomy', 5, 33, 23, 'Concerning Naphtali he said: “Naphtali is abounding with favor, full of the blessing of the LORD; he shall take possession of the sea and the south.”'),
  ('BSB', 'Deuteronomy', 5, 33, 24, 'And concerning Asher he said: “May Asher be the most blessed of sons; may he be the most favored among his brothers and dip his foot in oil.'),
  ('BSB', 'Deuteronomy', 5, 33, 25, 'May the bolts of your gate be iron and bronze, and may your strength match your days.”'),
  ('BSB', 'Deuteronomy', 5, 33, 26, '“There is none like the God of Jeshurun, who rides the heavens to your aid, and the clouds in His majesty.'),
  ('BSB', 'Deuteronomy', 5, 33, 27, 'The eternal God is your dwelling place, and underneath are the everlasting arms. He drives out the enemy before you, giving the command, ‘Destroy him!’'),
  ('BSB', 'Deuteronomy', 5, 33, 28, 'So Israel dwells securely; the fountain of Jacob lives untroubled in a land of grain and new wine, where even the heavens drip with dew.'),
  ('BSB', 'Deuteronomy', 5, 33, 29, 'Blessed are you, O Israel! Who is like you, a people saved by the LORD? He is the shield that protects you, the sword in which you boast. Your enemies will cower before you, and you shall trample their high places.”'),
  ('BSB', 'Deuteronomy', 5, 34, 1, 'Then Moses went up from the plains of Moab to Mount Nebo, to the top of Pisgah, which faces Jericho. And the LORD showed him the whole land—from Gilead as far as Dan,'),
  ('BSB', 'Deuteronomy', 5, 34, 2, 'all of Naphtali, the land of Ephraim and Manasseh, all the land of Judah as far as the Western Sea,'),
  ('BSB', 'Deuteronomy', 5, 34, 3, 'the Negev, and the region from the Valley of Jericho (the City of Palms) all the way to Zoar.'),
  ('BSB', 'Deuteronomy', 5, 34, 4, 'And the LORD said to him, “This is the land that I swore to give Abraham, Isaac, and Jacob when I said, ‘I will give it to your descendants.’ I have let you see it with your own eyes, but you will not cross into it.”'),
  ('BSB', 'Deuteronomy', 5, 34, 5, 'So Moses the servant of the LORD died there in the land of Moab, as the LORD had said.'),
  ('BSB', 'Deuteronomy', 5, 34, 6, 'And He buried him in a valley in the land of Moab facing Beth-peor, and no one to this day knows the location of his grave.'),
  ('BSB', 'Deuteronomy', 5, 34, 7, 'Moses was a hundred and twenty years old when he died, yet his eyes were not weak, and his vitality had not diminished.'),
  ('BSB', 'Deuteronomy', 5, 34, 8, 'The Israelites grieved for Moses in the plains of Moab thirty days, until the time of weeping and mourning for Moses came to an end.'),
  ('BSB', 'Deuteronomy', 5, 34, 9, 'Now Joshua son of Nun was filled with the spirit of wisdom because Moses had laid his hands on him. So the Israelites obeyed him and did as the LORD had commanded Moses.'),
  ('BSB', 'Deuteronomy', 5, 34, 10, 'Since that time, no prophet has risen in Israel like Moses, whom the LORD knew face to face—'),
  ('BSB', 'Deuteronomy', 5, 34, 11, 'no prophet who did all the signs and wonders that the LORD sent Moses to do in the land of Egypt to Pharaoh and to all his officials and all his land,'),
  ('BSB', 'Deuteronomy', 5, 34, 12, 'and no prophet who performed all the mighty acts of power and awesome deeds that Moses did in the sight of all Israel.'),
  ('BSB', 'Joshua', 6, 1, 1, 'Now after the death of His servant Moses, the LORD spoke to Joshua son of Nun, Moses’ assistant, saying,'),
  ('BSB', 'Joshua', 6, 1, 2, '“Moses My servant is dead. Now therefore arise, you and all these people, and cross over the Jordan into the land that I am giving to the children of Israel.'),
  ('BSB', 'Joshua', 6, 1, 3, 'I have given you every place where the sole of your foot will tread, just as I promised to Moses.'),
  ('BSB', 'Joshua', 6, 1, 4, 'Your territory shall extend from the wilderness and Lebanon to the great River Euphrates—all the land of the Hittites—and west as far as the Great Sea.'),
  ('BSB', 'Joshua', 6, 1, 5, 'No one shall stand against you all the days of your life. As I was with Moses, so will I be with you; I will never leave you nor forsake you.'),
  ('BSB', 'Joshua', 6, 1, 6, 'Be strong and courageous, for you shall give these people the inheritance of the land that I swore to their fathers I would give them.'),
  ('BSB', 'Joshua', 6, 1, 7, 'Above all, be strong and very courageous. Be careful to observe all the law that My servant Moses commanded you. Do not turn from it to the right or to the left, so that you may prosper wherever you go.'),
  ('BSB', 'Joshua', 6, 1, 8, 'This Book of the Law must not depart from your mouth; meditate on it day and night, so that you may be careful to do everything written in it. For then you will prosper and succeed in all you do.'),
  ('BSB', 'Joshua', 6, 1, 9, 'Have I not commanded you to be strong and courageous? Do not be afraid; do not be discouraged, for the LORD your God is with you wherever you go.”'),
  ('BSB', 'Joshua', 6, 1, 10, 'Then Joshua commanded the officers of the people:'),
  ('BSB', 'Joshua', 6, 1, 11, '“Go through the camp and tell the people, ‘Prepare your provisions, for within three days you will cross the Jordan to go in and take possession of the land that the LORD your God is giving you to possess.’”'),
  ('BSB', 'Joshua', 6, 1, 12, 'But to the Reubenites, the Gadites, and the half-tribe of Manasseh, Joshua said,'),
  ('BSB', 'Joshua', 6, 1, 13, '“Remember what Moses the servant of the LORD commanded you when he said, ‘The LORD your God will give you rest, and He will give you this land.’'),
  ('BSB', 'Joshua', 6, 1, 14, 'Your wives, your young children, and your livestock may remain in the land that Moses gave you on this side of the Jordan. But all your mighty men of valor must be armed for battle to cross over ahead of your brothers and help them,'),
  ('BSB', 'Joshua', 6, 1, 15, 'until the LORD gives them rest as He has done for you, and your brothers also possess the land that the LORD your God is giving them. Then you may return to the land of your inheritance and take possession of that which Moses the servant of the LORD gave you on the east side of the Jordan.”'),
  ('BSB', 'Joshua', 6, 1, 16, 'So they answered Joshua, “Everything you have commanded us we will do, and everywhere you send us we will go.'),
  ('BSB', 'Joshua', 6, 1, 17, 'Just as we obeyed Moses in all things, so we will obey you. And may the LORD your God be with you, as He was with Moses.'),
  ('BSB', 'Joshua', 6, 1, 18, 'Anyone who rebels against your order and does not obey your words, all that you command him, will be put to death. Above all, be strong and courageous!”'),
  ('BSB', 'Joshua', 6, 2, 1, 'Then Joshua son of Nun secretly sent two spies from Shittim, saying, “Go, inspect the land, especially Jericho.” So they went and entered the house of a prostitute named Rahab and stayed there.'),
  ('BSB', 'Joshua', 6, 2, 2, 'And it was reported to the king of Jericho: “Behold, some men of Israel have come here tonight to spy out the land.”'),
  ('BSB', 'Joshua', 6, 2, 3, 'So the king of Jericho sent to Rahab and said, “Bring out the men who came to you and entered your house, for they have come to spy out the whole land.”'),
  ('BSB', 'Joshua', 6, 2, 4, 'But the woman had taken the two men and hidden them. So she said, “Yes, the men did come to me, but I did not know where they had come from.'),
  ('BSB', 'Joshua', 6, 2, 5, 'At dusk, when the gate was about to close, the men went out, and I do not know which way they went. Pursue them quickly, and you may catch them!”'),
  ('BSB', 'Joshua', 6, 2, 6, '(But Rahab had taken them up to the roof and hidden them among the stalks of flax that she had laid out there.)'),
  ('BSB', 'Joshua', 6, 2, 7, 'So the king’s men set out in pursuit of the spies along the road to the fords of the Jordan, and as soon as they had gone out, the gate was shut.'),
  ('BSB', 'Joshua', 6, 2, 8, 'Before the spies lay down for the night, Rahab went up on the roof'),
  ('BSB', 'Joshua', 6, 2, 9, 'and said to them, “I know that the LORD has given you this land and that the fear of you has fallen on us, so that all who dwell in the land are melting in fear of you.'),
  ('BSB', 'Joshua', 6, 2, 10, 'For we have heard how the LORD dried up the waters of the Red Sea before you when you came out of Egypt, and what you did to Sihon and Og, the two kings of the Amorites across the Jordan, whom you devoted to destruction.'),
  ('BSB', 'Joshua', 6, 2, 11, 'When we heard this, our hearts melted and everyone’s courage failed because of you, for the LORD your God is God in the heavens above and on the earth below.'),
  ('BSB', 'Joshua', 6, 2, 12, 'Now therefore, please swear to me by the LORD that you will indeed show kindness to my family, because I showed kindness to you. Give me a sure sign'),
  ('BSB', 'Joshua', 6, 2, 13, 'that you will spare the lives of my father and mother, my brothers and sisters, and all who belong to them, and that you will deliver us from death.”'),
  ('BSB', 'Joshua', 6, 2, 14, '“Our lives for your lives!” the men agreed. “If you do not report our mission, we will show you kindness and faithfulness when the LORD gives us the land.”'),
  ('BSB', 'Joshua', 6, 2, 15, 'Then Rahab let them down by a rope through the window, since the house where she lived was built into the wall of the city.'),
  ('BSB', 'Joshua', 6, 2, 16, '“Go to the hill country,” she said, “so that your pursuers will not find you. Hide yourselves there for three days until they have returned; then go on your way.”'),
  ('BSB', 'Joshua', 6, 2, 17, 'The men said to her, “We will not be bound by this oath you made us swear'),
  ('BSB', 'Joshua', 6, 2, 18, 'unless, when we enter the land, you have tied this scarlet cord in the window through which you let us down, and unless you have brought your father and mother and brothers and all your family into your house.'),
  ('BSB', 'Joshua', 6, 2, 19, 'If anyone goes out the door of your house into the street, his blood will be on his own head, and we will be innocent. But if a hand is laid on anyone with you in the house, his blood will be on our heads.'),
  ('BSB', 'Joshua', 6, 2, 20, 'And if you report our mission, we will be released from the oath you made us swear.”'),
  ('BSB', 'Joshua', 6, 2, 21, '“Let it be as you say,” she replied, and she sent them away. And when they had gone, she tied the scarlet cord in the window.'),
  ('BSB', 'Joshua', 6, 2, 22, 'So the spies went out into the hill country and stayed there three days, until their pursuers had returned without finding them, having searched all along the road.'),
  ('BSB', 'Joshua', 6, 2, 23, 'Then the two men started back, came down from the hill country, and crossed the river. So they came to Joshua son of Nun and reported all that had happened to them.'),
  ('BSB', 'Joshua', 6, 2, 24, '“The LORD has surely delivered the entire land into our hands,” they said to Joshua. “Indeed, all who dwell in the land are melting in fear of us.”'),
  ('BSB', 'Joshua', 6, 3, 1, 'Early the next morning Joshua got up and left Shittim with all the Israelites. They went as far as the Jordan, where they camped before crossing over.'),
  ('BSB', 'Joshua', 6, 3, 2, 'After three days the officers went through the camp'),
  ('BSB', 'Joshua', 6, 3, 3, 'and commanded the people: “When you see the ark of the covenant of the LORD your God being carried by the Levitical priests, you are to set out from your positions and follow it.'),
  ('BSB', 'Joshua', 6, 3, 4, 'But keep a distance of about two thousand cubits between yourselves and the ark. Do not go near it, so that you can see the way to go, since you have never traveled this way before.”'),
  ('BSB', 'Joshua', 6, 3, 5, 'Then Joshua told the people, “Consecrate yourselves, for tomorrow the LORD will do wonders among you.”'),
  ('BSB', 'Joshua', 6, 3, 6, 'And he said to the priests, “Take the ark of the covenant and go on ahead of the people.” So they carried the ark of the covenant and went ahead of them.'),
  ('BSB', 'Joshua', 6, 3, 7, 'Now the LORD said to Joshua, “Today I will begin to exalt you in the sight of all Israel, so they may know that I am with you just as I was with Moses.'),
  ('BSB', 'Joshua', 6, 3, 8, 'Command the priests carrying the ark of the covenant: ‘When you reach the edge of the waters, stand in the Jordan.’”'),
  ('BSB', 'Joshua', 6, 3, 9, 'So Joshua told the Israelites, “Come here and listen to the words of the LORD your God.”'),
  ('BSB', 'Joshua', 6, 3, 10, 'He continued, “This is how you will know that the living God is among you and that He will surely drive out before you the Canaanites, Hittites, Hivites, Perizzites, Girgashites, Amorites, and Jebusites.'),
  ('BSB', 'Joshua', 6, 3, 11, 'Behold, the ark of the covenant of the Lord of all the earth will go ahead of you into the Jordan.'),
  ('BSB', 'Joshua', 6, 3, 12, 'Now choose twelve men from the tribes of Israel, one from each tribe.'),
  ('BSB', 'Joshua', 6, 3, 13, 'When the feet of the priests who carry the ark of the LORD—the Lord of all the earth—touch down in the waters of the Jordan, its flowing waters will be cut off and will stand up in a heap.”'),
  ('BSB', 'Joshua', 6, 3, 14, 'So when the people broke camp to cross the Jordan, the priests carried the ark of the covenant ahead of them.'),
  ('BSB', 'Joshua', 6, 3, 15, 'Now the Jordan overflows its banks throughout the harvest season. But as soon as the priests carrying the ark reached the Jordan and their feet touched the water’s edge,'),
  ('BSB', 'Joshua', 6, 3, 16, 'the flowing water stood still. It backed up as far upstream as Adam, a city in the area of Zarethan, while the water flowing toward the Sea of the Arabah (the Salt Sea) was completely cut off. So the people crossed over opposite Jericho.'),
  ('BSB', 'Joshua', 6, 3, 17, 'The priests carrying the ark of the covenant of the LORD stood firm on dry ground in the middle of the Jordan, while all Israel crossed over the dry ground, until the entire nation had crossed the Jordan.'),
  ('BSB', 'Joshua', 6, 4, 1, 'When the whole nation had finished crossing the Jordan, the LORD said to Joshua,'),
  ('BSB', 'Joshua', 6, 4, 2, '“Choose twelve men from among the people, one from each tribe,'),
  ('BSB', 'Joshua', 6, 4, 3, 'and command them: ‘Take up for yourselves twelve stones from the middle of the Jordan where the priests were standing, carry them with you, and set them down in the place where you spend the night.’”'),
  ('BSB', 'Joshua', 6, 4, 4, 'So Joshua summoned the twelve men he had appointed from the Israelites, one from each tribe,'),
  ('BSB', 'Joshua', 6, 4, 5, 'and said to them, “Cross over before the ark of the LORD your God into the middle of the Jordan. Each of you is to take a stone upon his shoulder, according to the number of the tribes of Israel,'),
  ('BSB', 'Joshua', 6, 4, 6, 'to serve as a sign among you. In the future, when your children ask, ‘What do these stones mean to you?’'),
  ('BSB', 'Joshua', 6, 4, 7, 'you are to tell them, ‘The waters of the Jordan were cut off before the ark of the covenant of the LORD. When it crossed the Jordan, the waters were cut off.’ Therefore these stones will be a memorial to the Israelites forever.”'),
  ('BSB', 'Joshua', 6, 4, 8, 'Thus the Israelites did as Joshua had commanded them. They took up twelve stones from the middle of the Jordan, one for each tribe of Israel, just as the LORD had told Joshua; and they carried them to the camp, where they set them down.'),
  ('BSB', 'Joshua', 6, 4, 9, 'Joshua also set up twelve stones in the middle of the Jordan, in the place where the priests who carried the ark of the covenant stood. And the stones are there to this day.'),
  ('BSB', 'Joshua', 6, 4, 10, 'Now the priests who carried the ark remained standing in the middle of the Jordan until the people had completed everything the LORD had commanded Joshua to tell them, just as Moses had directed Joshua. The people hurried across,'),
  ('BSB', 'Joshua', 6, 4, 11, 'and after everyone had finished crossing, the priests with the ark of the LORD crossed in the sight of the people.'),
  ('BSB', 'Joshua', 6, 4, 12, 'The Reubenites, the Gadites, and the half-tribe of Manasseh crossed over before the Israelites, armed for battle as Moses had instructed them.'),
  ('BSB', 'Joshua', 6, 4, 13, 'About 40,000 troops armed for battle crossed over before the LORD into the plains of Jericho.'),
  ('BSB', 'Joshua', 6, 4, 14, 'On that day the LORD exalted Joshua in the sight of all Israel, and they revered him all the days of his life, just as they had revered Moses.'),
  ('BSB', 'Joshua', 6, 4, 15, 'Then the LORD said to Joshua,'),
  ('BSB', 'Joshua', 6, 4, 16, '“Command the priests who carry the ark of the Testimony to come up from the Jordan.”'),
  ('BSB', 'Joshua', 6, 4, 17, 'So Joshua commanded the priests, “Come up from the Jordan.”'),
  ('BSB', 'Joshua', 6, 4, 18, 'When the priests carrying the ark of the covenant of the LORD came up out of the Jordan and their feet touched the dry land, the waters of the Jordan returned to their course and overflowed all the banks as before.'),
  ('BSB', 'Joshua', 6, 4, 19, 'On the tenth day of the first month the people went up from the Jordan and camped at Gilgal on the eastern border of Jericho.'),
  ('BSB', 'Joshua', 6, 4, 20, 'And there at Gilgal Joshua set up the twelve stones they had taken from the Jordan.'),
  ('BSB', 'Joshua', 6, 4, 21, 'Then Joshua said to the Israelites, “In the future, when your children ask their fathers, ‘What is the meaning of these stones?’'),
  ('BSB', 'Joshua', 6, 4, 22, 'you are to tell them, ‘Israel crossed the Jordan on dry ground.’'),
  ('BSB', 'Joshua', 6, 4, 23, 'For the LORD your God dried up the waters of the Jordan before you until you had crossed over, just as He did to the Red Sea, which He dried up before us until we had crossed over.'),
  ('BSB', 'Joshua', 6, 4, 24, 'He did this so that all the peoples of the earth may know that the hand of the LORD is mighty, and so that you may always fear the LORD your God.”'),
  ('BSB', 'Joshua', 6, 5, 1, 'Now when all the Amorite kings west of the Jordan and all the Canaanite kings along the coast heard how the LORD had dried up the waters of the Jordan before the Israelites until they had crossed over, their hearts melted and their spirits failed for fear of the Israelites.'),
  ('BSB', 'Joshua', 6, 5, 2, 'At that time the LORD said to Joshua, “Make flint knives and circumcise the sons of Israel once again.”'),
  ('BSB', 'Joshua', 6, 5, 3, 'So Joshua made flint knives and circumcised the sons of Israel at Gibeath-haaraloth.'),
  ('BSB', 'Joshua', 6, 5, 4, 'Now this is why Joshua circumcised them: All those who came out of Egypt—all the men of war—had died on the journey in the wilderness after they had left Egypt.'),
  ('BSB', 'Joshua', 6, 5, 5, 'Though all who had come out were circumcised, none of those born in the wilderness on the journey from Egypt had been circumcised.'),
  ('BSB', 'Joshua', 6, 5, 6, 'For the Israelites had wandered in the wilderness forty years, until all the nation’s men of war who had come out of Egypt had died, since they did not obey the LORD. So the LORD vowed never to let them see the land He had sworn to their fathers to give us, a land flowing with milk and honey.'),
  ('BSB', 'Joshua', 6, 5, 7, 'And Joshua raised up their sons in their place, and these were the ones he circumcised. Until this time they were still uncircumcised, since they had not been circumcised along the way.'),
  ('BSB', 'Joshua', 6, 5, 8, 'And after all the nation had been circumcised, they stayed there in the camp until they were healed.'),
  ('BSB', 'Joshua', 6, 5, 9, 'Then the LORD said to Joshua, “Today I have rolled away the reproach of Egypt from you.” So that place has been called Gilgal to this day.'),
  ('BSB', 'Joshua', 6, 5, 10, 'On the evening of the fourteenth day of the month, while the Israelites were camped at Gilgal on the plains of Jericho, they kept the Passover.'),
  ('BSB', 'Joshua', 6, 5, 11, 'The day after the Passover, on that very day, they ate unleavened bread and roasted grain from the produce of the land.'),
  ('BSB', 'Joshua', 6, 5, 12, 'And the day after they had eaten from the produce of the land, the manna ceased. There was no more manna for the Israelites, so that year they began to eat the crops of the land of Canaan.'),
  ('BSB', 'Joshua', 6, 5, 13, 'Now when Joshua was near Jericho, he looked up and saw a man standing in front of him with a drawn sword in His hand. Joshua approached Him and asked, “Are You for us or for our enemies?”'),
  ('BSB', 'Joshua', 6, 5, 14, '“Neither,” He replied. “I have now come as Commander of the LORD’s army.” Then Joshua fell facedown in reverence and asked Him, “What does my Lord have to say to His servant?”'),
  ('BSB', 'Joshua', 6, 5, 15, 'The Commander of the LORD’s army replied, “Take off your sandals, for the place where you are standing is holy.” And Joshua did so.'),
  ('BSB', 'Joshua', 6, 6, 1, 'Now Jericho was tightly shut up because of the Israelites. No one went out and no one came in.'),
  ('BSB', 'Joshua', 6, 6, 2, 'And the LORD said to Joshua, “Behold, I have delivered Jericho into your hand, along with its king and its mighty men of valor.'),
  ('BSB', 'Joshua', 6, 6, 3, 'March around the city with all the men of war, circling the city one time. Do this for six days.'),
  ('BSB', 'Joshua', 6, 6, 4, 'Have seven priests carry seven rams’ horns in front of the ark. Then on the seventh day, march around the city seven times, while the priests blow the horns.'),
  ('BSB', 'Joshua', 6, 6, 5, 'And when there is a long blast of the ram’s horn and you hear its sound, have all the people give a mighty shout. Then the wall of the city will collapse and all your people will charge straight into the city.”'),
  ('BSB', 'Joshua', 6, 6, 6, 'So Joshua son of Nun summoned the priests and said, “Take up the ark of the covenant and have seven priests carry seven rams’ horns in front of the ark of the LORD.”'),
  ('BSB', 'Joshua', 6, 6, 7, 'And he told the people, “Advance and march around the city, with the armed troops going ahead of the ark of the LORD.”'),
  ('BSB', 'Joshua', 6, 6, 8, 'After Joshua had spoken to the people, seven priests carrying seven rams’ horns before the LORD advanced and blew the horns, and the ark of the covenant of the LORD followed them.'),
  ('BSB', 'Joshua', 6, 6, 9, 'While the horns continued to sound, the armed troops marched ahead of the priests who blew the horns, and the rear guard followed the ark.'),
  ('BSB', 'Joshua', 6, 6, 10, 'But Joshua had commanded the people: “Do not give a battle cry or let your voice be heard; do not let one word come out of your mouth until the day I tell you to shout. Then you are to shout!”'),
  ('BSB', 'Joshua', 6, 6, 11, 'So he had the ark of the LORD carried around the city, circling it once. And the people returned to the camp and spent the night there.'),
  ('BSB', 'Joshua', 6, 6, 12, 'Joshua got up early the next morning, and the priests took the ark of the LORD.'),
  ('BSB', 'Joshua', 6, 6, 13, 'And the seven priests carrying seven rams’ horns kept marching ahead of the ark of the LORD and blowing the horns. The armed troops went in front of them and the rear guard followed the ark of the LORD, while the horns kept sounding.'),
  ('BSB', 'Joshua', 6, 6, 14, 'So on the second day they marched around the city once and returned to the camp. They did this for six days.'),
  ('BSB', 'Joshua', 6, 6, 15, 'Then on the seventh day, they got up at dawn and marched around the city seven times in the same manner. That was the only day they circled the city seven times.'),
  ('BSB', 'Joshua', 6, 6, 16, 'After the seventh time around, the priests blew the horns, and Joshua commanded the people, “Shout! For the LORD has given you the city!'),
  ('BSB', 'Joshua', 6, 6, 17, 'Now the city and everything in it must be devoted to the LORD for destruction. Only Rahab the prostitute and all those with her in her house will live, because she hid the spies we sent.'),
  ('BSB', 'Joshua', 6, 6, 18, 'But keep away from the things devoted to destruction, lest you yourself be set apart for destruction. If you take any of these, you will set apart the camp of Israel for destruction and bring disaster upon it.'),
  ('BSB', 'Joshua', 6, 6, 19, 'For all the silver and gold and all the articles of bronze and iron are holy to the LORD; they must go into His treasury.”'),
  ('BSB', 'Joshua', 6, 6, 20, 'So when the rams’ horns sounded, the people shouted. When they heard the blast of the horn, the people gave a great shout, and the wall collapsed. Then all the people charged straight into the city and captured it.'),
  ('BSB', 'Joshua', 6, 6, 21, 'At the edge of the sword they devoted to destruction everything in the city—man and woman, young and old, oxen, sheep, and donkeys.'),
  ('BSB', 'Joshua', 6, 6, 22, 'Meanwhile, Joshua told the two men who had spied out the land, “Go into the house of the prostitute and bring out the woman and all who are with her, just as you promised her.”'),
  ('BSB', 'Joshua', 6, 6, 23, 'So the young spies went in and brought out Rahab, her father and mother and brothers, and all who belonged to her. They brought out her whole family and settled them outside the camp of Israel.'),
  ('BSB', 'Joshua', 6, 6, 24, 'Then the Israelites burned up the city and everything in it. However, they put the silver and gold and articles of bronze and iron into the treasury of the LORD’s house.'),
  ('BSB', 'Joshua', 6, 6, 25, 'And Joshua spared Rahab the prostitute, with her father’s household and all who belonged to her, because she hid the men Joshua had sent to spy out Jericho. So she has lived among the Israelites to this day.'),
  ('BSB', 'Joshua', 6, 6, 26, 'At that time Joshua invoked this solemn oath: “Cursed before the LORD is the man who rises up and rebuilds this city, Jericho; at the cost of his firstborn he will lay its foundations; at the cost of his youngest he will set up its gates.”'),
  ('BSB', 'Joshua', 6, 6, 27, 'So the LORD was with Joshua, and his fame spread throughout the land.'),
  ('BSB', 'Joshua', 6, 7, 1, 'The Israelites, however, acted unfaithfully regarding the things devoted to destruction. Achan son of Carmi, the son of Zabdi, the son of Zerah, of the tribe of Judah, took some of what was set apart. So the anger of the LORD burned against the Israelites.'),
  ('BSB', 'Joshua', 6, 7, 2, 'Meanwhile, Joshua sent men from Jericho to Ai, which is near Beth-aven to the east of Bethel, and told them, “Go up and spy out the land.” So the men went up and spied out Ai.'),
  ('BSB', 'Joshua', 6, 7, 3, 'On returning to Joshua, they reported, “There is no need to send all the people; two or three thousand men are enough to go up and attack Ai. Since the people of Ai are so few, you need not wear out all our people there.”'),
  ('BSB', 'Joshua', 6, 7, 4, 'So about three thousand men went up, but they fled before the men of Ai.'),
  ('BSB', 'Joshua', 6, 7, 5, 'And the men of Ai struck down about thirty-six of them, chasing them from the gate as far as the quarries and striking them down on the slopes. So the hearts of the people melted and became like water.'),
  ('BSB', 'Joshua', 6, 7, 6, 'Then Joshua tore his clothes and fell facedown before the ark of the LORD until evening, as did the elders of Israel; and they all sprinkled dust on their heads.'),
  ('BSB', 'Joshua', 6, 7, 7, '“O, Lord GOD,” Joshua said, “why did You ever bring this people across the Jordan to deliver us into the hand of the Amorites to be destroyed? If only we had been content to stay on the other side of the Jordan!'),
  ('BSB', 'Joshua', 6, 7, 8, 'O Lord, what can I say, now that Israel has turned its back and run from its enemies?'),
  ('BSB', 'Joshua', 6, 7, 9, 'When the Canaanites and all who live in the land hear about this, they will surround us and wipe out our name from the earth. Then what will You do for Your great name?”'),
  ('BSB', 'Joshua', 6, 7, 10, 'But the LORD said to Joshua, “Stand up! Why have you fallen on your face?'),
  ('BSB', 'Joshua', 6, 7, 11, 'Israel has sinned; they have transgressed My covenant that I commanded them, and they have taken some of what was devoted to destruction. Indeed, they have stolen and lied, and they have put these things with their own possessions.'),
  ('BSB', 'Joshua', 6, 7, 12, 'This is why the Israelites cannot stand against their enemies. They will turn their backs and run from their enemies, because they themselves have been set apart for destruction. I will no longer be with you unless you remove from among you whatever is devoted to destruction.'),
  ('BSB', 'Joshua', 6, 7, 13, 'Get up and consecrate the people, saying, ‘Consecrate yourselves for tomorrow, for this is what the LORD, the God of Israel, says: Among you, O Israel, there are things devoted to destruction. You cannot stand against your enemies until you remove them.'),
  ('BSB', 'Joshua', 6, 7, 14, 'In the morning you must present yourselves tribe by tribe. The tribe that the LORD selects shall come forward clan by clan, and the clan that the LORD selects shall come forward family by family, and the family that the LORD selects shall come forward man by man.'),
  ('BSB', 'Joshua', 6, 7, 15, 'The one who is caught with the things devoted to destruction must be burned, along with all that belongs to him, because he has transgressed the covenant of the LORD and committed an outrage in Israel.’”'),
  ('BSB', 'Joshua', 6, 7, 16, 'So Joshua arose early the next morning and had Israel come forward tribe by tribe, and the tribe of Judah was selected.'),
  ('BSB', 'Joshua', 6, 7, 17, 'He had the clans of Judah come forward, and the clan of the Zerahites was selected. He had the clan of the Zerahites come forward, and the family of Zabdi was selected.'),
  ('BSB', 'Joshua', 6, 7, 18, 'And he had the family of Zabdi come forward man by man, and Achan son of Carmi, the son of Zabdi, the son of Zerah, of the tribe of Judah, was selected.'),
  ('BSB', 'Joshua', 6, 7, 19, 'So Joshua said to Achan, “My son, give glory to the LORD, the God of Israel, and make a confession to Him. I urge you to tell me what you have done; do not hide it from me.”'),
  ('BSB', 'Joshua', 6, 7, 20, '“It is true,” Achan replied, “I have sinned against the LORD, the God of Israel. This is what I did:'),
  ('BSB', 'Joshua', 6, 7, 21, 'When I saw among the spoils a beautiful cloak from Shinar, two hundred shekels of silver, and a bar of gold weighing fifty shekels, I coveted them and took them. They are hidden in the ground inside my tent, with the silver underneath.”'),
  ('BSB', 'Joshua', 6, 7, 22, 'So Joshua sent messengers who ran to the tent, and there it all was, hidden in his tent, with the silver underneath.'),
  ('BSB', 'Joshua', 6, 7, 23, 'They took the things from inside the tent, brought them to Joshua and all the Israelites, and spread them out before the LORD.');
insert into control_room_bible (version, book, book_num, chapter, verse, text) values
  ('BSB', 'Joshua', 6, 7, 24, 'Then Joshua, together with all Israel, took Achan son of Zerah, the silver, the cloak, the bar of gold, his sons and daughters, his oxen and donkeys and sheep, his tent, and everything else he owned, and brought them to the Valley of Achor.'),
  ('BSB', 'Joshua', 6, 7, 25, '“Why have you brought this trouble upon us?” said Joshua. “Today the LORD will bring trouble upon you!” And all Israel stoned him to death. Then they stoned the others and burned their bodies.'),
  ('BSB', 'Joshua', 6, 7, 26, 'And they heaped over Achan a large pile of rocks that remains to this day. So the LORD turned from His burning anger. Therefore that place is called the Valley of Achor to this day.'),
  ('BSB', 'Joshua', 6, 8, 1, 'Then the LORD said to Joshua, “Do not be afraid or discouraged. Take the whole army with you, and go up and attack Ai. See, I have delivered into your hand the king of Ai, his people, his city, and his land.'),
  ('BSB', 'Joshua', 6, 8, 2, 'And you shall do to Ai and its king as you did to Jericho and its king, except that you may carry off their plunder and livestock for yourselves. Set up an ambush behind the city.”'),
  ('BSB', 'Joshua', 6, 8, 3, 'So Joshua and the whole army set out to attack Ai. Joshua chose 30,000 mighty men of valor and sent them out at night'),
  ('BSB', 'Joshua', 6, 8, 4, 'with these orders: “Pay attention. You are to lie in ambush behind the city, not too far from it. All of you must be ready.'),
  ('BSB', 'Joshua', 6, 8, 5, 'Then I and all the troops with me will advance on the city. When they come out against us as they did the first time, we will flee from them.'),
  ('BSB', 'Joshua', 6, 8, 6, 'They will pursue us until we have drawn them away from the city, for they will say, ‘The Israelites are running away from us as they did before.’ So as we flee from them,'),
  ('BSB', 'Joshua', 6, 8, 7, 'you are to rise from the ambush and seize the city, for the LORD your God will deliver it into your hand.'),
  ('BSB', 'Joshua', 6, 8, 8, 'And when you have taken the city, set it on fire. Do as the LORD has commanded! See, I have given you orders.”'),
  ('BSB', 'Joshua', 6, 8, 9, 'So Joshua sent them out, and they went to the place of ambush and lay in wait between Bethel and Ai, to the west of Ai. But Joshua spent that night among the people.'),
  ('BSB', 'Joshua', 6, 8, 10, 'Joshua got up early the next morning and mobilized his men, and he and the elders of Israel marched before them up to Ai.'),
  ('BSB', 'Joshua', 6, 8, 11, 'Then all the troops who were with him marched up and approached the city. They arrived in front of Ai and camped to the north of it, with the valley between them and the city.'),
  ('BSB', 'Joshua', 6, 8, 12, 'Now Joshua had taken about five thousand men and set up an ambush between Bethel and Ai, to the west of the city.'),
  ('BSB', 'Joshua', 6, 8, 13, 'So the forces were stationed with the main camp to the north of the city and the rear guard to the west of the city. And that night Joshua went into the valley.'),
  ('BSB', 'Joshua', 6, 8, 14, 'When the king of Ai saw the Israelites, he hurried out early in the morning with the men of the city to engage them in battle at an appointed place overlooking the Arabah. But he did not know that an ambush had been set up against him behind the city.'),
  ('BSB', 'Joshua', 6, 8, 15, 'Joshua and all Israel let themselves be beaten back before them, and they fled toward the wilderness.'),
  ('BSB', 'Joshua', 6, 8, 16, 'Then all the men of Ai were summoned to pursue them, and they followed Joshua and were drawn away from the city.'),
  ('BSB', 'Joshua', 6, 8, 17, 'Not a man was left in Ai or Bethel who did not go out after Israel, leaving the city wide open while they pursued Israel.'),
  ('BSB', 'Joshua', 6, 8, 18, 'Then the LORD said to Joshua, “Hold out your battle lance toward Ai, for into your hand I will deliver the city.” So Joshua held out his battle lance toward Ai,'),
  ('BSB', 'Joshua', 6, 8, 19, 'and as soon as he did so, the men in ambush rose quickly from their position. They rushed forward, entered the city, captured it, and immediately set it on fire.'),
  ('BSB', 'Joshua', 6, 8, 20, 'When the men of Ai turned and looked back, the smoke of the city was rising into the sky. They could not escape in any direction, and the troops who had fled to the wilderness now became the pursuers.'),
  ('BSB', 'Joshua', 6, 8, 21, 'When Joshua and all Israel saw that the men in ambush had captured the city and that smoke was rising from it, they turned around and struck down the men of Ai.'),
  ('BSB', 'Joshua', 6, 8, 22, 'Meanwhile, those in the ambush came out of the city against them, and the men of Ai were trapped between the Israelite forces on both sides. So Israel struck them down until no survivor or fugitive remained.'),
  ('BSB', 'Joshua', 6, 8, 23, 'But they took the king of Ai alive and brought him to Joshua.'),
  ('BSB', 'Joshua', 6, 8, 24, 'When Israel had finished killing all the men of Ai who had pursued them into the field and wilderness, and when every last one of them had fallen by the sword, all the Israelites returned to Ai and put it to the sword as well.'),
  ('BSB', 'Joshua', 6, 8, 25, 'A total of twelve thousand men and women fell that day—all the people of Ai.'),
  ('BSB', 'Joshua', 6, 8, 26, 'Joshua did not draw back the hand that held his battle lance until he had devoted to destruction all who lived in Ai.'),
  ('BSB', 'Joshua', 6, 8, 27, 'Israel took for themselves only the cattle and plunder of that city, as the LORD had commanded Joshua.'),
  ('BSB', 'Joshua', 6, 8, 28, 'So Joshua burned Ai and made it a permanent heap of ruins, a desolation to this day.'),
  ('BSB', 'Joshua', 6, 8, 29, 'He hung the king of Ai on a tree until evening, and at sunset Joshua commanded that they take down the body from the tree and throw it down at the entrance of the city gate. And over it they raised a large pile of rocks, which remains to this day.'),
  ('BSB', 'Joshua', 6, 8, 30, 'At that time Joshua built an altar on Mount Ebal to the LORD, the God of Israel,'),
  ('BSB', 'Joshua', 6, 8, 31, 'just as Moses the servant of the LORD had commanded the Israelites. He built it according to what is written in the Book of the Law of Moses: “an altar of uncut stones on which no iron tool has been used.” And on it they offered burnt offerings to the LORD, and they sacrificed peace offerings.'),
  ('BSB', 'Joshua', 6, 8, 32, 'And there in the presence of the Israelites, Joshua inscribed on the stones a copy of the law of Moses, which he had written.'),
  ('BSB', 'Joshua', 6, 8, 33, 'All Israel, foreigners and citizens alike, with their elders, officers, and judges, stood on both sides of the ark of the covenant of the LORD facing the Levitical priests who carried it. Half of the people stood in front of Mount Gerizim and half of them in front of Mount Ebal, as Moses the servant of the LORD had commanded earlier, to bless the people of Israel.'),
  ('BSB', 'Joshua', 6, 8, 34, 'Afterward, Joshua read aloud all the words of the law—the blessings and the curses—according to all that is written in the Book of the Law.'),
  ('BSB', 'Joshua', 6, 8, 35, 'There was not a word of all that Moses had commanded that Joshua failed to read before the whole assembly of Israel, including the women, the little ones, and the foreigners who lived among them.'),
  ('BSB', 'Joshua', 6, 9, 1, 'Now when news of this reached all the kings west of the Jordan—those in the hill country, the foothills, and all along the coast of the Great Sea toward Lebanon (the Hittites, Amorites, Canaanites, Perizzites, Hivites, and Jebusites)—'),
  ('BSB', 'Joshua', 6, 9, 2, 'they came together to wage war against Joshua and Israel.'),
  ('BSB', 'Joshua', 6, 9, 3, 'But the people of Gibeon, having heard what Joshua had done to Jericho and Ai,'),
  ('BSB', 'Joshua', 6, 9, 4, 'acted deceptively and set out as envoys, carrying on their donkeys worn-out sacks and old wineskins, cracked and mended.'),
  ('BSB', 'Joshua', 6, 9, 5, 'They put worn, patched sandals on their feet and threadbare clothing on their bodies, and their whole supply of bread was dry and moldy.'),
  ('BSB', 'Joshua', 6, 9, 6, 'They went to Joshua in the camp at Gilgal and said to him and the men of Israel, “We have come from a distant land; please make a treaty with us.”'),
  ('BSB', 'Joshua', 6, 9, 7, 'But the men of Israel said to the Hivites, “Perhaps you dwell near us. How can we make a treaty with you?”'),
  ('BSB', 'Joshua', 6, 9, 8, '“We are your servants,” they said to Joshua. Then Joshua asked them, “Who are you and where have you come from?”'),
  ('BSB', 'Joshua', 6, 9, 9, '“Your servants have come from a very distant land,” they replied, “because of the fame of the LORD your God. For we have heard the reports about Him: all that He did in Egypt,'),
  ('BSB', 'Joshua', 6, 9, 10, 'and all that He did to the two kings of the Amorites beyond the Jordan—Sihon king of Heshbon and Og king of Bashan, who reigned in Ashtaroth.'),
  ('BSB', 'Joshua', 6, 9, 11, 'So the elders and inhabitants of our land told us, ‘Take provisions for your journey; go to meet them and say to them: We are your servants. Please make a treaty with us.’'),
  ('BSB', 'Joshua', 6, 9, 12, 'This bread of ours was warm when we packed it at home on the day we left to come to you. But take a look, it is now dry and moldy.'),
  ('BSB', 'Joshua', 6, 9, 13, 'These wineskins were new when we filled them, but look, they are cracked. And these clothes and sandals are worn out from our very long journey.”'),
  ('BSB', 'Joshua', 6, 9, 14, 'Then the men of Israel sampled their provisions, but did not seek the counsel of the LORD.'),
  ('BSB', 'Joshua', 6, 9, 15, 'And Joshua made a treaty of peace with them to let them live, and the leaders of the congregation swore an oath to them.'),
  ('BSB', 'Joshua', 6, 9, 16, 'Three days after they had made the treaty with the Gibeonites, the Israelites learned that they were neighbors, living among them.'),
  ('BSB', 'Joshua', 6, 9, 17, 'So the Israelites set out and on the third day arrived at their cities—Gibeon, Chephirah, Beeroth, and Kiriath-jearim.'),
  ('BSB', 'Joshua', 6, 9, 18, 'But the Israelites did not attack them, because the leaders of the congregation had sworn an oath to them by the LORD, the God of Israel. And the whole congregation grumbled against the leaders.'),
  ('BSB', 'Joshua', 6, 9, 19, 'All the leaders answered, “We have sworn an oath to them by the LORD, the God of Israel, and now we cannot touch them.'),
  ('BSB', 'Joshua', 6, 9, 20, 'This is how we will treat them: We will let them live, so that no wrath will fall on us because of the oath we swore to them.”'),
  ('BSB', 'Joshua', 6, 9, 21, 'They continued, “Let them live, but let them be woodcutters and water carriers for the whole congregation.” So the leaders kept their promise.'),
  ('BSB', 'Joshua', 6, 9, 22, 'Then Joshua summoned the Gibeonites and said, “Why did you deceive us by telling us you live far away from us, when in fact you live among us?'),
  ('BSB', 'Joshua', 6, 9, 23, 'Now therefore you are under a curse and will perpetually serve as woodcutters and water carriers for the house of my God.”'),
  ('BSB', 'Joshua', 6, 9, 24, 'The Gibeonites answered, “Your servants were told clearly that the LORD your God had commanded His servant Moses to give you all the land and wipe out all its inhabitants before you. So we greatly feared for our lives because of you, and that is why we have done this.'),
  ('BSB', 'Joshua', 6, 9, 25, 'Now we are in your hands. Do to us whatever seems good and right to you.”'),
  ('BSB', 'Joshua', 6, 9, 26, 'So Joshua did this and delivered them from the hands of the Israelites, and they did not kill the Gibeonites.'),
  ('BSB', 'Joshua', 6, 9, 27, 'On that day he made them woodcutters and water carriers, as they are to this day for the congregation of the LORD and for the altar at the place He would choose.'),
  ('BSB', 'Joshua', 6, 10, 1, 'Now Adoni-zedek king of Jerusalem heard that Joshua had captured Ai and devoted it to destruction—doing to Ai and its king as he had done to Jericho and its king—and that the people of Gibeon had made peace with Israel and were living near them.'),
  ('BSB', 'Joshua', 6, 10, 2, 'So Adoni-zedek and his people were greatly alarmed, because Gibeon was a great city, like one of the royal cities; it was larger than Ai, and all its men were mighty.'),
  ('BSB', 'Joshua', 6, 10, 3, 'Therefore Adoni-zedek king of Jerusalem sent word to Hoham king of Hebron, Piram king of Jarmuth, Japhia king of Lachish, and Debir king of Eglon, saying,'),
  ('BSB', 'Joshua', 6, 10, 4, '“Come up and help me. We will attack Gibeon, because they have made peace with Joshua and the Israelites.”'),
  ('BSB', 'Joshua', 6, 10, 5, 'So the five kings of the Amorites—the kings of Jerusalem, Hebron, Jarmuth, Lachish, and Eglon—joined forces and advanced with all their armies. They camped before Gibeon and made war against it.'),
  ('BSB', 'Joshua', 6, 10, 6, 'Then the men of Gibeon sent word to Joshua in the camp at Gilgal: “Do not abandon your servants. Come quickly and save us! Help us, because all the kings of the Amorites from the hill country have joined forces against us.”'),
  ('BSB', 'Joshua', 6, 10, 7, 'So Joshua and his whole army, including all the mighty men of valor, came from Gilgal.'),
  ('BSB', 'Joshua', 6, 10, 8, 'The LORD said to Joshua, “Do not be afraid of them, for I have delivered them into your hand. Not one of them shall stand against you.”'),
  ('BSB', 'Joshua', 6, 10, 9, 'After marching all night from Gilgal, Joshua caught them by surprise.'),
  ('BSB', 'Joshua', 6, 10, 10, 'And the LORD threw them into confusion before Israel, who defeated them in a great slaughter at Gibeon, pursued them along the ascent to Beth-horon, and struck them down as far as Azekah and Makkedah.'),
  ('BSB', 'Joshua', 6, 10, 11, 'As they fled before Israel along the descent from Beth-horon to Azekah, the LORD cast down on them large hailstones from the sky, and more of them were killed by the hailstones than by the swords of the Israelites.'),
  ('BSB', 'Joshua', 6, 10, 12, 'On the day that the LORD gave the Amorites over to the Israelites, Joshua spoke to the LORD in the presence of Israel: “O sun, stand still over Gibeon, O moon, over the Valley of Aijalon.”'),
  ('BSB', 'Joshua', 6, 10, 13, 'So the sun stood still and the moon stopped until the nation took vengeance upon its enemies. Is this not written in the Book of Jashar? “So the sun stopped in the middle of the sky and delayed going down about a full day.”'),
  ('BSB', 'Joshua', 6, 10, 14, 'There has been no day like it before or since, when the LORD listened to the voice of a man, because the LORD fought for Israel.'),
  ('BSB', 'Joshua', 6, 10, 15, 'Then Joshua returned with all Israel to the camp at Gilgal.'),
  ('BSB', 'Joshua', 6, 10, 16, 'Now the five kings had fled and hidden in the cave at Makkedah.'),
  ('BSB', 'Joshua', 6, 10, 17, 'And Joshua was informed: “The five kings have been found; they are hiding in the cave at Makkedah.”'),
  ('BSB', 'Joshua', 6, 10, 18, 'So Joshua said, “Roll large stones against the mouth of the cave, and post men there to guard them.'),
  ('BSB', 'Joshua', 6, 10, 19, 'But you, do not stop there. Pursue your enemies and attack them from behind. Do not let them reach their cities, for the LORD your God has delivered them into your hand.”'),
  ('BSB', 'Joshua', 6, 10, 20, 'So Joshua and the Israelites continued to inflict a terrible slaughter until they had finished them off, and the remaining survivors retreated to the fortified cities.'),
  ('BSB', 'Joshua', 6, 10, 21, 'The whole army returned safely to Joshua in the camp at Makkedah, and no one dared to utter a word against the Israelites.'),
  ('BSB', 'Joshua', 6, 10, 22, 'Then Joshua said, “Open the mouth of the cave and bring those five kings out to me.”'),
  ('BSB', 'Joshua', 6, 10, 23, 'So they brought the five kings out of the cave—the kings of Jerusalem, Hebron, Jarmuth, Lachish, and Eglon.'),
  ('BSB', 'Joshua', 6, 10, 24, 'When they had brought the kings to Joshua, he summoned all the men of Israel and said to the army commanders who had accompanied him, “Come here and put your feet on the necks of these kings.” So the commanders came forward and put their feet on their necks.'),
  ('BSB', 'Joshua', 6, 10, 25, '“Do not be afraid or discouraged,” Joshua said. “Be strong and courageous, for the LORD will do this to all the enemies you fight.”'),
  ('BSB', 'Joshua', 6, 10, 26, 'After this, Joshua struck down and killed the kings, and he hung their bodies on five trees and left them there until evening.'),
  ('BSB', 'Joshua', 6, 10, 27, 'At sunset Joshua ordered that they be taken down from the trees and thrown into the cave in which they had hidden. Then large stones were placed against the mouth of the cave, and the stones are there to this day.'),
  ('BSB', 'Joshua', 6, 10, 28, 'On that day Joshua captured Makkedah and put it to the sword, along with its king. He devoted to destruction everyone in the city, leaving no survivors. So he did to the king of Makkedah as he had done to the king of Jericho.'),
  ('BSB', 'Joshua', 6, 10, 29, 'Then Joshua and all Israel with him moved on from Makkedah to Libnah and fought against Libnah.'),
  ('BSB', 'Joshua', 6, 10, 30, 'And the LORD also delivered that city and its king into the hand of Israel, and Joshua put all the people to the sword, leaving no survivors. And he did to the king of Libnah as he had done to the king of Jericho.'),
  ('BSB', 'Joshua', 6, 10, 31, 'And Joshua and all Israel with him moved on from Libnah to Lachish. They laid siege to it and fought against it.'),
  ('BSB', 'Joshua', 6, 10, 32, 'And the LORD delivered Lachish into the hand of Israel, and Joshua captured it on the second day. He put all the people to the sword, just as he had done to Libnah.'),
  ('BSB', 'Joshua', 6, 10, 33, 'At that time Horam king of Gezer went to help Lachish, but Joshua struck him down along with his people, leaving no survivors.'),
  ('BSB', 'Joshua', 6, 10, 34, 'So Joshua moved on from Lachish to Eglon, and all Israel with him. They laid siege to it and fought against it.'),
  ('BSB', 'Joshua', 6, 10, 35, 'That day they captured Eglon and put it to the sword, and Joshua devoted to destruction everyone in the city, just as he had done to Lachish.'),
  ('BSB', 'Joshua', 6, 10, 36, 'Then Joshua and all Israel with him went up from Eglon to Hebron and fought against it.'),
  ('BSB', 'Joshua', 6, 10, 37, 'They captured it and put to the sword its king, all its villages, and all the people. Joshua left no survivors, just as he had done at Eglon; he devoted to destruction Hebron and everyone in it.'),
  ('BSB', 'Joshua', 6, 10, 38, 'Finally Joshua and all Israel with him turned toward Debir and fought against it.'),
  ('BSB', 'Joshua', 6, 10, 39, 'And they captured Debir, its king, and all its villages. They put them to the sword and devoted to destruction everyone in the city, leaving no survivors. Joshua did to Debir and its king as he had done to Hebron and as he had done to Libnah and its king.'),
  ('BSB', 'Joshua', 6, 10, 40, 'So Joshua conquered the whole region—the hill country, the Negev, the foothills, and the slopes, together with all their kings—leaving no survivors. He devoted to destruction everything that breathed, just as the LORD, the God of Israel, had commanded.'),
  ('BSB', 'Joshua', 6, 10, 41, 'Joshua conquered the area from Kadesh-barnea to Gaza, and the whole region of Goshen as far as Gibeon.'),
  ('BSB', 'Joshua', 6, 10, 42, 'And because the LORD, the God of Israel, fought for Israel, Joshua captured all these kings and their land in one campaign.'),
  ('BSB', 'Joshua', 6, 10, 43, 'Then Joshua returned with all Israel to the camp at Gilgal.'),
  ('BSB', 'Joshua', 6, 11, 1, 'Now when Jabin king of Hazor heard about these things, he sent word to Jobab king of Madon; to the kings of Shimron and Achshaph;'),
  ('BSB', 'Joshua', 6, 11, 2, 'to the kings of the north in the mountains, in the Arabah south of Chinnereth, in the foothills, and in Naphoth-dor to the west;'),
  ('BSB', 'Joshua', 6, 11, 3, 'to the Canaanites in the east and west; to the Amorites, Hittites, Perizzites, and Jebusites in the hill country; and to the Hivites at the foot of Hermon in the land of Mizpah.'),
  ('BSB', 'Joshua', 6, 11, 4, 'So these kings came out with all their armies, a multitude as numerous as the sand on the seashore, along with a great number of horses and chariots.'),
  ('BSB', 'Joshua', 6, 11, 5, 'All these kings joined forces and encamped at the waters of Merom to fight against Israel.'),
  ('BSB', 'Joshua', 6, 11, 6, 'Then the LORD said to Joshua, “Do not be afraid of them, for by this time tomorrow I will deliver all of them slain before Israel. You are to hamstring their horses and burn up their chariots.”'),
  ('BSB', 'Joshua', 6, 11, 7, 'So by the waters of Merom, Joshua and his whole army came upon them suddenly and attacked them,'),
  ('BSB', 'Joshua', 6, 11, 8, 'and the LORD delivered them into the hand of Israel, who struck them down and pursued them all the way to Greater Sidon and Misrephoth-maim, and eastward as far as the Valley of Mizpeh. They struck them down, leaving no survivors.'),
  ('BSB', 'Joshua', 6, 11, 9, 'Joshua treated them as the LORD had told him; he hamstrung their horses and burned up their chariots.'),
  ('BSB', 'Joshua', 6, 11, 10, 'At that time Joshua turned back and captured Hazor and put its king to the sword, because Hazor was formerly the head of all these kingdoms.'),
  ('BSB', 'Joshua', 6, 11, 11, 'The Israelites put everyone in Hazor to the sword, devoting them to destruction. Nothing that breathed remained, and Joshua burned down Hazor itself.'),
  ('BSB', 'Joshua', 6, 11, 12, 'Joshua captured all these kings and their cities and put them to the sword. He devoted them to destruction, as Moses the LORD’s servant had commanded.'),
  ('BSB', 'Joshua', 6, 11, 13, 'Yet Israel did not burn any of the cities built on their mounds, except Hazor, which Joshua burned.'),
  ('BSB', 'Joshua', 6, 11, 14, 'The Israelites took for themselves all the plunder and livestock of these cities, but they put all the people to the sword until they had completely destroyed them, not sparing anyone who breathed.'),
  ('BSB', 'Joshua', 6, 11, 15, 'As the LORD had commanded His servant Moses, so Moses commanded Joshua. That is what Joshua did, leaving nothing undone of all that the LORD had commanded Moses.'),
  ('BSB', 'Joshua', 6, 11, 16, 'So Joshua took this entire region: the hill country, all the Negev, all the land of Goshen, the western foothills, the Arabah, and the mountains of Israel and their foothills,'),
  ('BSB', 'Joshua', 6, 11, 17, 'from Mount Halak, which rises toward Seir, as far as Baal-gad in the Valley of Lebanon at the foot of Mount Hermon. He captured all their kings and struck them down, putting them to death.'),
  ('BSB', 'Joshua', 6, 11, 18, 'Joshua waged war against all these kings for a long period of time.'),
  ('BSB', 'Joshua', 6, 11, 19, 'No city made peace with the Israelites except the Hivites living in Gibeon; all others were taken in battle.'),
  ('BSB', 'Joshua', 6, 11, 20, 'For it was of the LORD to harden their hearts to engage Israel in battle, so that they would be set apart for destruction and would receive no mercy, being annihilated as the LORD had commanded Moses.'),
  ('BSB', 'Joshua', 6, 11, 21, 'At that time Joshua proceeded to eliminate the Anakim from the hill country of Hebron, Debir, and Anab, and from all the hill country of Judah and of Israel. Joshua devoted them to destruction, along with their cities.'),
  ('BSB', 'Joshua', 6, 11, 22, 'No Anakim were left in the land of the Israelites; only in Gaza, Gath, and Ashdod did any survive.'),
  ('BSB', 'Joshua', 6, 11, 23, 'So Joshua took the entire land, in keeping with all that the LORD had spoken to Moses. And Joshua gave it as an inheritance to Israel according to the allotments to their tribes. Then the land had rest from war.'),
  ('BSB', 'Joshua', 6, 12, 1, 'Now these are the kings of the land whom the Israelites struck down and whose lands they took beyond the Jordan to the east, from the Arnon Valley to Mount Hermon, including all the Arabah eastward:'),
  ('BSB', 'Joshua', 6, 12, 2, 'Sihon king of the Amorites, who lived in Heshbon. He ruled from Aroer on the rim of the Arnon Valley, along the middle of the valley, up to the Jabbok River (the border of the Ammonites), that is, half of Gilead,'),
  ('BSB', 'Joshua', 6, 12, 3, 'as well as the Arabah east of the Sea of Chinnereth to the Sea of the Arabah (the Salt Sea), eastward through Beth-jeshimoth, and southward below the slopes of Pisgah.'),
  ('BSB', 'Joshua', 6, 12, 4, 'And Og king of Bashan, one of the remnant of the Rephaim, who lived in Ashtaroth and Edrei.'),
  ('BSB', 'Joshua', 6, 12, 5, 'He ruled over Mount Hermon, Salecah, all of Bashan up to the border of the Geshurites and Maacathites, and half of Gilead to the border of Sihon king of Heshbon.'),
  ('BSB', 'Joshua', 6, 12, 6, 'Moses, the servant of the LORD, and the Israelites had struck them down and given their land as an inheritance to the Reubenites, the Gadites, and the half-tribe of Manasseh.'),
  ('BSB', 'Joshua', 6, 12, 7, 'And these are the kings of the land that Joshua and the Israelites conquered beyond the Jordan to the west, from Baal-gad in the Valley of Lebanon to Mount Halak, which rises toward Seir (according to the allotments to the tribes of Israel, Joshua gave them as an inheritance'),
  ('BSB', 'Joshua', 6, 12, 8, 'the hill country, the foothills, the Arabah, the slopes, the wilderness, and the Negev—the lands of the Hittites, Amorites, Canaanites, Perizzites, Hivites, and Jebusites):'),
  ('BSB', 'Joshua', 6, 12, 9, 'the king of Jericho, one; the king of Ai, which is near Bethel, one;'),
  ('BSB', 'Joshua', 6, 12, 10, 'the king of Jerusalem, one; the king of Hebron, one;'),
  ('BSB', 'Joshua', 6, 12, 11, 'the king of Jarmuth, one; the king of Lachish, one;'),
  ('BSB', 'Joshua', 6, 12, 12, 'the king of Eglon, one; the king of Gezer, one;'),
  ('BSB', 'Joshua', 6, 12, 13, 'the king of Debir, one; the king of Geder, one;'),
  ('BSB', 'Joshua', 6, 12, 14, 'the king of Hormah, one; the king of Arad, one;'),
  ('BSB', 'Joshua', 6, 12, 15, 'the king of Libnah, one; the king of Adullam, one;'),
  ('BSB', 'Joshua', 6, 12, 16, 'the king of Makkedah, one; the king of Bethel, one;'),
  ('BSB', 'Joshua', 6, 12, 17, 'the king of Tappuah, one; the king of Hepher, one;'),
  ('BSB', 'Joshua', 6, 12, 18, 'the king of Aphek, one; the king of Lasharon, one;'),
  ('BSB', 'Joshua', 6, 12, 19, 'the king of Madon, one; the king of Hazor, one;'),
  ('BSB', 'Joshua', 6, 12, 20, 'the king of Shimron-meron, one; the king of Achshaph, one;'),
  ('BSB', 'Joshua', 6, 12, 21, 'the king of Taanach, one; the king of Megiddo, one;'),
  ('BSB', 'Joshua', 6, 12, 22, 'the king of Kedesh, one; the king of Jokneam in Carmel, one;'),
  ('BSB', 'Joshua', 6, 12, 23, 'the king of Dor in Naphath-dor, one; the king of Goiim in Gilgal, one;'),
  ('BSB', 'Joshua', 6, 12, 24, 'and the king of Tirzah, one. So there were thirty-one kings in all.'),
  ('BSB', 'Joshua', 6, 13, 1, 'Now Joshua was old and well along in years, and the LORD said to him, “You are old and well along in years, but very much of the land remains to be possessed.'),
  ('BSB', 'Joshua', 6, 13, 2, 'This is the land that remains:'),
  ('BSB', 'Joshua', 6, 13, 3, 'All the territory of the Philistines and the Geshurites, from the Shihor east of Egypt to the territory of Ekron on the north (considered to be Canaanite territory)—that of the five Philistine rulers of Gaza, Ashdod, Ashkelon, Gath, and Ekron, as well as that of the Avvites;'),
  ('BSB', 'Joshua', 6, 13, 4, 'to the south, all the land of the Canaanites, from Mearah of the Sidonians to Aphek, as far as the border of the Amorites;'),
  ('BSB', 'Joshua', 6, 13, 5, 'the land of the Gebalites; and all Lebanon to the east, from Baal-gad below Mount Hermon to Lebo-hamath.'),
  ('BSB', 'Joshua', 6, 13, 6, 'All the inhabitants of the hill country from Lebanon to Misrephoth-maim—all the Sidonians—I Myself will drive out before the Israelites. Be sure to divide it by lot as an inheritance to Israel, as I have commanded you.'),
  ('BSB', 'Joshua', 6, 13, 7, 'Now therefore divide this land as an inheritance to the nine tribes and the half-tribe of Manasseh.”'),
  ('BSB', 'Joshua', 6, 13, 8, 'The other half of Manasseh, along with the Reubenites and Gadites, had received the inheritance Moses had given them beyond the Jordan to the east, just as Moses the servant of the LORD had assigned to them:'),
  ('BSB', 'Joshua', 6, 13, 9, 'The area from Aroer on the rim of the Arnon Valley, along with the city in the middle of the valley, the whole plateau of Medeba as far as Dibon,'),
  ('BSB', 'Joshua', 6, 13, 10, 'and all the cities of Sihon king of the Amorites who reigned in Heshbon, as far as the border of the Ammonites;'),
  ('BSB', 'Joshua', 6, 13, 11, 'also Gilead and the territory of the Geshurites and Maacathites, all of Mount Hermon, and all Bashan as far as Salecah—'),
  ('BSB', 'Joshua', 6, 13, 12, 'the whole kingdom of Og in Bashan, who had reigned in Ashtaroth and Edrei and had remained as a remnant of the Rephaim. Moses had struck them down and dispossessed them,'),
  ('BSB', 'Joshua', 6, 13, 13, 'but the Israelites did not drive out the Geshurites or the Maacathites. So Geshur and Maacath dwell among the Israelites to this day.'),
  ('BSB', 'Joshua', 6, 13, 14, 'To the tribe of Levi, however, Moses had given no inheritance. The offerings made by fire to the LORD, the God of Israel, are their inheritance, just as He had promised them.'),
  ('BSB', 'Joshua', 6, 13, 15, 'This is what Moses had given to the clans of the tribe of Reuben:'),
  ('BSB', 'Joshua', 6, 13, 16, 'The territory from Aroer on the rim of the Arnon Valley, along with the city in the middle of the valley, to the whole plateau beyond Medeba,'),
  ('BSB', 'Joshua', 6, 13, 17, 'to Heshbon and all its cities on the plateau, including Dibon, Bamoth-baal, Beth-baal-meon,'),
  ('BSB', 'Joshua', 6, 13, 18, 'Jahaz, Kedemoth, Mephaath,'),
  ('BSB', 'Joshua', 6, 13, 19, 'Kiriathaim, Sibmah, Zereth-shahar on the hill in the valley,'),
  ('BSB', 'Joshua', 6, 13, 20, 'Beth-peor, the slopes of Pisgah, and Beth-jeshimoth—'),
  ('BSB', 'Joshua', 6, 13, 21, 'all the cities of the plateau and all the kingdom of Sihon king of the Amorites, who reigned in Heshbon until Moses killed him and the chiefs of Midian (Evi, Rekem, Zur, Hur, and Reba), the princes of Sihon who lived in the land.'),
  ('BSB', 'Joshua', 6, 13, 22, 'The Israelites also killed the diviner Balaam son of Beor along with the others they put to the sword.'),
  ('BSB', 'Joshua', 6, 13, 23, 'And the border of the Reubenites was the bank of the Jordan. This was the inheritance of the clans of the Reubenites, including the cities and villages.'),
  ('BSB', 'Joshua', 6, 13, 24, 'This is what Moses had given to the clans of the tribe of Gad:'),
  ('BSB', 'Joshua', 6, 13, 25, 'The territory of Jazer, all the cities of Gilead, and half the land of the Ammonites as far as Aroer, near Rabbah;'),
  ('BSB', 'Joshua', 6, 13, 26, 'the territory from Heshbon to Ramath-mizpeh and Betonim, and from Mahanaim to the border of Debir;'),
  ('BSB', 'Joshua', 6, 13, 27, 'and in the valley, Beth-haram, Beth-nimrah, Succoth, and Zaphon, with the rest of the kingdom of Sihon king of Heshbon (the territory on the east side of the Jordan up to the edge of the Sea of Chinnereth).'),
  ('BSB', 'Joshua', 6, 13, 28, 'This was the inheritance of the clans of the Gadites, including the cities and villages.'),
  ('BSB', 'Joshua', 6, 13, 29, 'This is what Moses had given to the clans of the half-tribe of Manasseh, that is, to half the tribe of the descendants of Manasseh:'),
  ('BSB', 'Joshua', 6, 13, 30, 'The territory from Mahanaim through all Bashan—all the kingdom of Og king of Bashan, including all the towns of Jair that are in Bashan, sixty cities;'),
  ('BSB', 'Joshua', 6, 13, 31, 'half of Gilead; and Ashtaroth and Edrei, the royal cities of Og in Bashan. All this was for the clans of the descendants of Machir son of Manasseh, that is, half of the descendants of Machir.'),
  ('BSB', 'Joshua', 6, 13, 32, 'These were the portions Moses had given them on the plains of Moab beyond the Jordan, east of Jericho.'),
  ('BSB', 'Joshua', 6, 13, 33, 'To the tribe of Levi, however, Moses had given no inheritance. The LORD, the God of Israel, is their inheritance, just as He had promised them.'),
  ('BSB', 'Joshua', 6, 14, 1, 'Now these are the portions that the Israelites inherited in the land of Canaan, as distributed by Eleazar the priest, Joshua son of Nun, and the heads of the families of the tribes of Israel.'),
  ('BSB', 'Joshua', 6, 14, 2, 'Their inheritance was assigned by lot for the nine and a half tribes, as the LORD had commanded through Moses.'),
  ('BSB', 'Joshua', 6, 14, 3, 'For Moses had given the inheritance east of the Jordan to the other two and a half tribes. But he granted no inheritance among them to the Levites.'),
  ('BSB', 'Joshua', 6, 14, 4, 'The descendants of Joseph became two tribes, Manasseh and Ephraim. And no portion of the land was given to the Levites, except for cities in which to live, along with pasturelands for their flocks and herds.'),
  ('BSB', 'Joshua', 6, 14, 5, 'So the Israelites did as the LORD had commanded Moses, and they divided the land.'),
  ('BSB', 'Joshua', 6, 14, 6, 'Then the sons of Judah approached Joshua at Gilgal, and Caleb son of Jephunneh the Kenizzite said to him, “You know what the LORD said to Moses the man of God at Kadesh-barnea about you and me.'),
  ('BSB', 'Joshua', 6, 14, 7, 'I was forty years old when Moses the servant of the LORD sent me from Kadesh-barnea to spy out the land, and I brought back to him an honest report.'),
  ('BSB', 'Joshua', 6, 14, 8, 'Although my brothers who went with me made the hearts of the people melt with fear, I remained loyal to the LORD my God.'),
  ('BSB', 'Joshua', 6, 14, 9, 'On that day Moses swore to me, saying, ‘Surely the land on which you have set foot will be an inheritance to you and your children forever, because you have wholly followed the LORD my God.’'),
  ('BSB', 'Joshua', 6, 14, 10, 'Now behold, as the LORD promised, He has kept me alive these forty-five years since He spoke this word to Moses, while Israel wandered in the wilderness. So here I am today, eighty-five years old,'),
  ('BSB', 'Joshua', 6, 14, 11, 'still as strong today as I was the day Moses sent me out. As my strength was then, so it is now for war, for going out, and for coming in.'),
  ('BSB', 'Joshua', 6, 14, 12, 'Now therefore give me this hill country that the LORD promised me on that day, for you yourself heard then that the Anakim were there, with great and fortified cities. Perhaps with the LORD’s help I will drive them out, as the LORD has spoken.”'),
  ('BSB', 'Joshua', 6, 14, 13, 'Then Joshua blessed Caleb son of Jephunneh and gave him Hebron as his inheritance.'),
  ('BSB', 'Joshua', 6, 14, 14, 'Therefore Hebron belongs to Caleb son of Jephunneh the Kenizzite as an inheritance to this day, because he wholly followed the LORD, the God of Israel.'),
  ('BSB', 'Joshua', 6, 14, 15, '(Hebron used to be called Kiriath-arba, after Arba, the greatest man among the Anakim.) Then the land had rest from war.'),
  ('BSB', 'Joshua', 6, 15, 1, 'Now the allotment for the clans of the tribe of Judah extended to the border of Edom, to the Wilderness of Zin at the extreme southern boundary:'),
  ('BSB', 'Joshua', 6, 15, 2, 'Their southern border started at the bay on the southern tip of the Salt Sea,'),
  ('BSB', 'Joshua', 6, 15, 3, 'proceeded south of the Ascent of Akrabbim, continued on to Zin, went over to the south of Kadesh-barnea, ran past Hezron up to Addar, and curved toward Karka.'),
  ('BSB', 'Joshua', 6, 15, 4, 'It proceeded to Azmon, joined the Brook of Egypt, and ended at the Sea. This was their southern border.'),
  ('BSB', 'Joshua', 6, 15, 5, 'The eastern border was the Salt Sea as far as the mouth of the Jordan.'),
  ('BSB', 'Joshua', 6, 15, 6, 'The northern border started from the bay of the sea at the mouth of the Jordan, went up to Beth-hoglah, proceeded north of Beth-arabah, and went up to the Stone of Bohan son of Reuben.'),
  ('BSB', 'Joshua', 6, 15, 7, 'Then the border went up to Debir from the Valley of Achor, turning north to Gilgal, which faces the Ascent of Adummim south of the ravine. It continued along the waters of En-shemesh and came out at En-rogel.'),
  ('BSB', 'Joshua', 6, 15, 8, 'From there the border went up the Valley of Hinnom along the southern slope of the Jebusites (that is, Jerusalem) and ascended to the top of the hill that faces the Valley of Hinnom on the west, at the northern end of the Valley of Rephaim.'),
  ('BSB', 'Joshua', 6, 15, 9, 'From the hilltop the border curved to the spring of the Waters of Nephtoah, proceeded to the cities of Mount Ephron, and then bent around toward Baalah (that is, Kiriath-jearim).'),
  ('BSB', 'Joshua', 6, 15, 10, 'The border curled westward from Baalah to Mount Seir, ran along the northern slope of Mount Jearim (that is, Chesalon), went down to Beth-shemesh, and crossed to Timnah.'),
  ('BSB', 'Joshua', 6, 15, 11, 'Then it went out to the northern slope of Ekron, curved toward Shikkeron, proceeded to Mount Baalah, went on to Jabneel, and ended at the Sea.'),
  ('BSB', 'Joshua', 6, 15, 12, 'And the western border was the coastline of the Great Sea. These are the boundaries around the clans of the descendants of Judah.'),
  ('BSB', 'Joshua', 6, 15, 13, 'According to the LORD’s command to him, Joshua gave Caleb son of Jephunneh a portion among the sons of Judah—Kiriath-arba, that is, Hebron. (Arba was the forefather of Anak.)'),
  ('BSB', 'Joshua', 6, 15, 14, 'And Caleb drove out from there the three sons of Anak—the descendants of Sheshai, Ahiman, and Talmai, the children of Anak.'),
  ('BSB', 'Joshua', 6, 15, 15, 'From there he marched against the inhabitants of Debir (formerly known as Kiriath-sepher).'),
  ('BSB', 'Joshua', 6, 15, 16, 'And Caleb said, “To the man who strikes down Kiriath-sepher and captures it, I will give my daughter Acsah in marriage.”'),
  ('BSB', 'Joshua', 6, 15, 17, 'So Othniel son of Caleb’s brother Kenaz captured the city, and Caleb gave his daughter Acsah to him in marriage.'),
  ('BSB', 'Joshua', 6, 15, 18, 'One day Acsah came to Othniel and urged him to ask her father for a field. When she got off her donkey, Caleb asked her, “What do you desire?”'),
  ('BSB', 'Joshua', 6, 15, 19, '“Give me a blessing,” she answered. “Since you have given me land in the Negev, give me springs of water as well.” So Caleb gave her both the upper and lower springs.'),
  ('BSB', 'Joshua', 6, 15, 20, 'This is the inheritance of the clans of the tribe of Judah.'),
  ('BSB', 'Joshua', 6, 15, 21, 'These were the southernmost cities of the tribe of Judah in the Negev toward the border of Edom:'),
  ('BSB', 'Joshua', 6, 15, 22, 'Kabzeel, Eder, Jagur, Kinah, Dimonah, Adadah,'),
  ('BSB', 'Joshua', 6, 15, 23, 'Kedesh, Hazor, Ithnan,'),
  ('BSB', 'Joshua', 6, 15, 24, 'Ziph, Telem, Bealoth,'),
  ('BSB', 'Joshua', 6, 15, 25, 'Hazor-hadattah, Kerioth-hezron (that is, Hazor),'),
  ('BSB', 'Joshua', 6, 15, 26, 'Amam, Shema, Moladah,'),
  ('BSB', 'Joshua', 6, 15, 27, 'Hazar-gaddah, Heshmon, Beth-pelet,'),
  ('BSB', 'Joshua', 6, 15, 28, 'Hazar-shual, Beersheba, Biziothiah,'),
  ('BSB', 'Joshua', 6, 15, 29, 'Baalah, Iim, Ezem,'),
  ('BSB', 'Joshua', 6, 15, 30, 'Eltolad, Chesil, Hormah,'),
  ('BSB', 'Joshua', 6, 15, 31, 'Ziklag, Madmannah, Sansannah,'),
  ('BSB', 'Joshua', 6, 15, 32, 'Lebaoth, Shilhim, Ain, and Rimmon—twenty-nine cities in all, along with their villages.'),
  ('BSB', 'Joshua', 6, 15, 33, 'These were in the foothills:'),
  ('BSB', 'Joshua', 6, 15, 34, 'Eshtaol, Zorah, Ashnah, Zanoah, En-gannim, Tappuah, Enam,'),
  ('BSB', 'Joshua', 6, 15, 35, 'Jarmuth, Adullam, Socoh, Azekah,'),
  ('BSB', 'Joshua', 6, 15, 36, 'Shaaraim, Adithaim, and Gederah (or Gederothaim)—fourteen cities, along with their villages.'),
  ('BSB', 'Joshua', 6, 15, 37, 'Zenan, Hadashah, Migdal-gad,'),
  ('BSB', 'Joshua', 6, 15, 38, 'Dilan, Mizpeh, Joktheel,'),
  ('BSB', 'Joshua', 6, 15, 39, 'Lachish, Bozkath, Eglon,'),
  ('BSB', 'Joshua', 6, 15, 40, 'Cabbon, Lahmas, Chitlish,'),
  ('BSB', 'Joshua', 6, 15, 41, 'Gederoth, Beth-dagon, Naamah, and Makkedah—sixteen cities, along with their villages.'),
  ('BSB', 'Joshua', 6, 15, 42, 'Libnah, Ether, Ashan,'),
  ('BSB', 'Joshua', 6, 15, 43, 'Iphtah, Ashnah, Nezib,'),
  ('BSB', 'Joshua', 6, 15, 44, 'Keilah, Achzib, and Mareshah—nine cities, along with their villages.'),
  ('BSB', 'Joshua', 6, 15, 45, 'Ekron, with its towns and villages;'),
  ('BSB', 'Joshua', 6, 15, 46, 'from Ekron to the sea, all the cities near Ashdod, along with their villages;'),
  ('BSB', 'Joshua', 6, 15, 47, 'Ashdod, with its towns and villages; Gaza, with its towns and villages, as far as the Brook of Egypt and the coastline of the Great Sea.'),
  ('BSB', 'Joshua', 6, 15, 48, 'These were in the hill country:'),
  ('BSB', 'Joshua', 6, 15, 49, 'Shamir, Jattir, Socoh, Dannah, Kiriath-sannah (that is, Debir),'),
  ('BSB', 'Joshua', 6, 15, 50, 'Anab, Eshtemoh, Anim,'),
  ('BSB', 'Joshua', 6, 15, 51, 'Goshen, Holon, and Giloh—eleven cities, along with their villages.'),
  ('BSB', 'Joshua', 6, 15, 52, 'Arab, Dumah, Eshan,'),
  ('BSB', 'Joshua', 6, 15, 53, 'Janim, Beth-tappuah, Aphekah,'),
  ('BSB', 'Joshua', 6, 15, 54, 'Humtah, Kiriath-arba (that is, Hebron), and Zior—nine cities, along with their villages.'),
  ('BSB', 'Joshua', 6, 15, 55, 'Maon, Carmel, Ziph, Juttah,'),
  ('BSB', 'Joshua', 6, 15, 56, 'Jezreel, Jokdeam, Zanoah,'),
  ('BSB', 'Joshua', 6, 15, 57, 'Kain, Gibeah, and Timnah—ten cities, along with their villages.'),
  ('BSB', 'Joshua', 6, 15, 58, 'Halhul, Beth-zur, Gedor,'),
  ('BSB', 'Joshua', 6, 15, 59, 'Maarath, Beth-anoth, and Eltekon—six cities, along with their villages.'),
  ('BSB', 'Joshua', 6, 15, 60, 'Kiriath-baal (that is, Kiriath-jearim), and Rabbah—two cities, along with their villages.'),
  ('BSB', 'Joshua', 6, 15, 61, 'These were in the wilderness:'),
  ('BSB', 'Joshua', 6, 15, 62, 'Beth-arabah, Middin, Secacah, Nibshan, the City of Salt, and En-gedi—six cities, along with their villages.'),
  ('BSB', 'Joshua', 6, 15, 63, 'But the descendants of Judah could not drive out the Jebusites living in Jerusalem. So to this day the Jebusites live there among the descendants of Judah.'),
  ('BSB', 'Joshua', 6, 16, 1, 'The allotment for the descendants of Joseph extended from the Jordan at Jericho to the waters of Jericho on the east, through the wilderness that goes up from Jericho into the hill country of Bethel.'),
  ('BSB', 'Joshua', 6, 16, 2, 'It went on from Bethel (that is, Luz) and proceeded to the border of the Archites in Ataroth.'),
  ('BSB', 'Joshua', 6, 16, 3, 'Then it descended westward to the border of the Japhletites as far as the border of Lower Beth-horon and on to Gezer, and it ended at the Sea.'),
  ('BSB', 'Joshua', 6, 16, 4, 'So Ephraim and Manasseh, the sons of Joseph, received their inheritance.'),
  ('BSB', 'Joshua', 6, 16, 5, 'This was the territory of the descendants of Ephraim by their clans: The border of their inheritance went from Ataroth-addar in the east to Upper Beth-horon'),
  ('BSB', 'Joshua', 6, 16, 6, 'and out toward the Sea. From Michmethath on the north it turned eastward toward Taanath-shiloh and passed by it to Janoah on the east.'),
  ('BSB', 'Joshua', 6, 16, 7, 'From Janoah it went down to Ataroth and Naarah, and then reached Jericho and came out at the Jordan.'),
  ('BSB', 'Joshua', 6, 16, 8, 'From Tappuah the border went westward to the Brook of Kanah and ended at the Sea. This was the inheritance of the clans of the tribe of Ephraim,'),
  ('BSB', 'Joshua', 6, 16, 9, 'along with all the cities and villages set apart for the descendants of Ephraim within the inheritance of Manasseh.'),
  ('BSB', 'Joshua', 6, 16, 10, 'But they did not drive out the Canaanites who lived in Gezer. So the Canaanites dwell among the Ephraimites to this day, but they are forced laborers.'),
  ('BSB', 'Joshua', 6, 17, 1, 'Now this was the allotment for the tribe of Manasseh as Joseph’s firstborn son, namely for Machir the firstborn of Manasseh and father of the Gileadites, who had received Gilead and Bashan because Machir was a man of war.'),
  ('BSB', 'Joshua', 6, 17, 2, 'So this allotment was for the rest of the descendants of Manasseh—the clans of Abiezer, Helek, Asriel, Shechem, Hepher, and Shemida. These are the other male descendants of the clans of Manasseh son of Joseph.'),
  ('BSB', 'Joshua', 6, 17, 3, 'But Zelophehad son of Hepher (the son of Gilead, the son of Machir, the son of Manasseh) had no sons but only daughters. These are the names of his daughters: Mahlah, Noah, Hoglah, Milcah, and Tirzah.'),
  ('BSB', 'Joshua', 6, 17, 4, 'They approached Eleazar the priest, Joshua son of Nun, and the leaders, and said, “The LORD commanded Moses to give us an inheritance among our brothers.” So Joshua gave them an inheritance among their father’s brothers, in keeping with the command of the LORD.'),
  ('BSB', 'Joshua', 6, 17, 5, 'Thus ten shares fell to Manasseh, in addition to the land of Gilead and Bashan beyond the Jordan,'),
  ('BSB', 'Joshua', 6, 17, 6, 'because the daughters of Manasseh received an inheritance among his sons. And the land of Gilead belonged to the rest of the sons of Manasseh.'),
  ('BSB', 'Joshua', 6, 17, 7, 'Now the border of Manasseh went from Asher to Michmethath near Shechem, then southward to include the inhabitants of En-tappuah.'),
  ('BSB', 'Joshua', 6, 17, 8, 'The region of Tappuah belonged to Manasseh, but Tappuah itself, on the border of Manasseh, belonged to Ephraim.'),
  ('BSB', 'Joshua', 6, 17, 9, 'From there the border continued southward to the Brook of Kanah. There were cities belonging to Ephraim among the cities of Manasseh, but the border of Manasseh was on the north side of the brook and ended at the Sea.'),
  ('BSB', 'Joshua', 6, 17, 10, 'Ephraim’s territory was to the south, and Manasseh’s was to the north, having the Sea as its border and adjoining Asher on the north and Issachar on the east.'),
  ('BSB', 'Joshua', 6, 17, 11, 'Within Issachar and Asher, Manasseh was assigned Beth-shean, Ibleam, Dor (that is, Naphath), Endor, Taanach, and Megiddo, each with their surrounding settlements.'),
  ('BSB', 'Joshua', 6, 17, 12, 'But the descendants of Manasseh were unable to occupy these cities, because the Canaanites were determined to stay in this land.'),
  ('BSB', 'Joshua', 6, 17, 13, 'However, when the Israelites grew stronger, they put the Canaanites to forced labor; but they failed to drive them out completely.'),
  ('BSB', 'Joshua', 6, 17, 14, 'Then the sons of Joseph said to Joshua, “Why have you given us only one portion as an inheritance? We have many people, because the LORD has blessed us abundantly.”'),
  ('BSB', 'Joshua', 6, 17, 15, 'Joshua answered them, “If you have so many people that the hill country of Ephraim is too small for you, go to the forest and clear for yourself an area in the land of the Perizzites and the Rephaim.”'),
  ('BSB', 'Joshua', 6, 17, 16, '“The hill country is not enough for us,” they replied, “and all the Canaanites who live in the valley have iron chariots, both in Beth-shean with its towns and in the Valley of Jezreel.”'),
  ('BSB', 'Joshua', 6, 17, 17, 'So Joshua said to the house of Joseph—to Ephraim and Manasseh—“You have many people and great strength. You shall not have just one allotment,'),
  ('BSB', 'Joshua', 6, 17, 18, 'because the hill country will be yours as well. It is a forest; clear it, and its farthest limits will be yours. Although the Canaanites have iron chariots and although they are strong, you can drive them out.”'),
  ('BSB', 'Joshua', 6, 18, 1, 'Then the whole congregation of Israel assembled at Shiloh and set up the Tent of Meeting there. And though the land was subdued before them,'),
  ('BSB', 'Joshua', 6, 18, 2, 'there were still seven tribes of Israel who had not yet received their inheritance.'),
  ('BSB', 'Joshua', 6, 18, 3, 'So Joshua said to the Israelites, “How long will you put off entering and possessing the land that the LORD, the God of your fathers, has given you?'),
  ('BSB', 'Joshua', 6, 18, 4, 'Appoint three men from each tribe, and I will send them out to survey the land and map it out, according to the inheritance of each. Then they will return to me'),
  ('BSB', 'Joshua', 6, 18, 5, 'and divide the land into seven portions. Judah shall remain in their territory in the south, and the house of Joseph shall remain in their territory in the north.'),
  ('BSB', 'Joshua', 6, 18, 6, 'When you have mapped out the seven portions of land and brought it to me, I will cast lots for you here in the presence of the LORD our God.'),
  ('BSB', 'Joshua', 6, 18, 7, 'The Levites, however, have no portion among you, because their inheritance is the priesthood of the LORD. And Gad, Reuben, and half the tribe of Manasseh have already received the inheritance that Moses the servant of the LORD gave them beyond the Jordan to the east.”'),
  ('BSB', 'Joshua', 6, 18, 8, 'As the men got up to go out, Joshua commanded them to map out the land, saying, “Go and survey the land, map it out, and return to me. Then I will cast lots for you here in Shiloh in the presence of the LORD.”'),
  ('BSB', 'Joshua', 6, 18, 9, 'So the men departed and went throughout the land, mapping it city by city into seven portions. Then they returned with the document to Joshua at the camp in Shiloh.'),
  ('BSB', 'Joshua', 6, 18, 10, 'And Joshua cast lots for them in the presence of the LORD at Shiloh, where he distributed the land to the Israelites according to their divisions.'),
  ('BSB', 'Joshua', 6, 18, 11, 'The first lot came up for the clans of the tribe of Benjamin. Their allotted territory lay between the tribes of Judah and Joseph:'),
  ('BSB', 'Joshua', 6, 18, 12, 'On the north side their border began at the Jordan, went up past the northern slope of Jericho, headed west through the hill country, and came out at the wilderness of Beth-aven.'),
  ('BSB', 'Joshua', 6, 18, 13, 'From there the border crossed over to the southern slope of Luz (that is, Bethel) and went down to Ataroth-addar on the hill south of Lower Beth-horon.'),
  ('BSB', 'Joshua', 6, 18, 14, 'On the west side the border curved southward from the hill facing Beth-horon on the south and came out at Kiriath-baal (that is, Kiriath-jearim), a city of the sons of Judah. This was the western side.'),
  ('BSB', 'Joshua', 6, 18, 15, 'On the south side the border began at the outskirts of Kiriath-jearim and extended westward to the spring at the Waters of Nephtoah.'),
  ('BSB', 'Joshua', 6, 18, 16, 'Then it went down to the foot of the hill that faces the Valley of Hinnom at the northern end of the Valley of Rephaim and ran down the Valley of Hinnom toward the southern slope of the Jebusites and downward to En-rogel.'),
  ('BSB', 'Joshua', 6, 18, 17, 'From there it curved northward and proceeded to En-shemesh and on to Geliloth facing the Ascent of Adummim, and continued down to the Stone of Bohan son of Reuben.'),
  ('BSB', 'Joshua', 6, 18, 18, 'Then it went on to the northern slope of Beth-arabah and went down into the valley.'),
  ('BSB', 'Joshua', 6, 18, 19, 'The border continued to the northern slope of Beth-hoglah and came out at the northern bay of the Salt Sea, at the mouth of the Jordan. This was the southern border.'),
  ('BSB', 'Joshua', 6, 18, 20, 'On the east side the border was the Jordan. These were the borders around the inheritance of the clans of the tribe of Benjamin.'),
  ('BSB', 'Joshua', 6, 18, 21, 'These were the cities of the clans of the tribe of Benjamin:'),
  ('BSB', 'Joshua', 6, 18, 22, 'Jericho, Beth-hoglah, Emek-keziz, Beth-arabah, Zemaraim, Bethel,'),
  ('BSB', 'Joshua', 6, 18, 23, 'Avvim, Parah, Ophrah,'),
  ('BSB', 'Joshua', 6, 18, 24, 'Chephar-ammoni, Ophni, and Geba—twelve cities, along with their villages.'),
  ('BSB', 'Joshua', 6, 18, 25, 'Gibeon, Ramah, Beeroth,'),
  ('BSB', 'Joshua', 6, 18, 26, 'Mizpeh, Chephirah, Mozah,'),
  ('BSB', 'Joshua', 6, 18, 27, 'Rekem, Irpeel, Taralah,'),
  ('BSB', 'Joshua', 6, 18, 28, 'Zelah, Haeleph, Jebus (that is, Jerusalem), Gibeah, and Kiriath-jearim—fourteen cities, along with their villages. This was the inheritance of the clans of the tribe of Benjamin.'),
  ('BSB', 'Joshua', 6, 19, 1, 'The second lot came out for the clans of the tribe of Simeon:'),
  ('BSB', 'Joshua', 6, 19, 2, 'Their inheritance lay within the territory of Judah and included Beersheba (or Sheba), Moladah,'),
  ('BSB', 'Joshua', 6, 19, 3, 'Hazar-shual, Balah, Ezem,'),
  ('BSB', 'Joshua', 6, 19, 4, 'Eltolad, Bethul, Hormah,'),
  ('BSB', 'Joshua', 6, 19, 5, 'Ziklag, Beth-marcaboth, Hazar-susah,'),
  ('BSB', 'Joshua', 6, 19, 6, 'Beth-lebaoth, and Sharuhen—thirteen cities, along with their villages.'),
  ('BSB', 'Joshua', 6, 19, 7, 'Ain, Rimmon, Ether, and Ashan—four cities, along with their villages,'),
  ('BSB', 'Joshua', 6, 19, 8, 'and all the villages surrounding these cities as far as Baalath-beer (Ramah of the Negev). This was the inheritance of the clans of the tribe of Simeon.'),
  ('BSB', 'Joshua', 6, 19, 9, 'The inheritance of the Simeonites was taken from the territory of Judah, because the share for Judah’s descendants was too large for them. So the Simeonites received an inheritance within Judah’s portion.'),
  ('BSB', 'Joshua', 6, 19, 10, 'The third lot came up for the clans of the tribe of Zebulun:'),
  ('BSB', 'Joshua', 6, 19, 11, 'The border of their inheritance stretched as far as Sarid. It went up westward to Maralah, reached Dabbesheth, and met the brook east of Jokneam.'),
  ('BSB', 'Joshua', 6, 19, 12, 'From Sarid it turned eastward along the border of Chisloth-tabor and went on to Daberath and up to Japhia.'),
  ('BSB', 'Joshua', 6, 19, 13, 'From there it crossed eastward to Gath-hepher and to Eth-kazin; it extended to Rimmon and curved around toward Neah.'),
  ('BSB', 'Joshua', 6, 19, 14, 'Then the border circled around the north side of Neah to Hannathon and ended at the Valley of Iphtah-el.'),
  ('BSB', 'Joshua', 6, 19, 15, 'It also included Kattath, Nahalal, Shimron, Idalah, and Bethlehem. There were twelve cities, along with their villages.'),
  ('BSB', 'Joshua', 6, 19, 16, 'This was the inheritance of the clans of the tribe of Zebulun, including these cities and their villages.'),
  ('BSB', 'Joshua', 6, 19, 17, 'The fourth lot came out for the clans of the tribe of Issachar:'),
  ('BSB', 'Joshua', 6, 19, 18, 'Their territory included Jezreel, Chesulloth, Shunem,'),
  ('BSB', 'Joshua', 6, 19, 19, 'Hapharaim, Shion, Anaharath,'),
  ('BSB', 'Joshua', 6, 19, 20, 'Rabbith, Kishion, Ebez,'),
  ('BSB', 'Joshua', 6, 19, 21, 'Remeth, En-gannim, En-haddah, and Beth-pazzez.'),
  ('BSB', 'Joshua', 6, 19, 22, 'The border reached Tabor, Shahazumah, and Beth-shemesh, and ended at the Jordan. There were sixteen cities, along with their villages.'),
  ('BSB', 'Joshua', 6, 19, 23, 'This was the inheritance of the clans of the tribe of Issachar, including these cities and their villages.'),
  ('BSB', 'Joshua', 6, 19, 24, 'The fifth lot came out for the clans of the tribe of Asher:'),
  ('BSB', 'Joshua', 6, 19, 25, 'Their territory included Helkath, Hali, Beten, Achshaph,'),
  ('BSB', 'Joshua', 6, 19, 26, 'Allammelech, Amad, and Mishal. On the west the border touched Carmel and Shihor-libnath,'),
  ('BSB', 'Joshua', 6, 19, 27, 'then turned eastward toward Beth-dagon, touched Zebulun and the Valley of Iphtah-el, and went north to Beth-emek and Neiel, passing Cabul on the left.'),
  ('BSB', 'Joshua', 6, 19, 28, 'It went on to Ebron, Rehob, Hammon, and Kanah, as far as Greater Sidon.'),
  ('BSB', 'Joshua', 6, 19, 29, 'The border then turned back toward Ramah as far as the fortified city of Tyre, turned toward Hosah, and came out at the Sea in the region of Achzib,'),
  ('BSB', 'Joshua', 6, 19, 30, 'Ummah, Aphek, and Rehob. There were twenty-two cities, along with their villages.'),
  ('BSB', 'Joshua', 6, 19, 31, 'This was the inheritance of the clans of the tribe of Asher, including these cities and their villages.'),
  ('BSB', 'Joshua', 6, 19, 32, 'The sixth lot came out for the clans of the tribe of Naphtali:'),
  ('BSB', 'Joshua', 6, 19, 33, 'Their border started at Heleph and the great tree of Zaanannim, passing Adami-nekeb and Jabneel as far as Lakkum and ending at the Jordan.'),
  ('BSB', 'Joshua', 6, 19, 34, 'Then the border turned westward to Aznoth-tabor and ran from there to Hukkok, touching Zebulun on the south side, Asher on the west, and Judah at the Jordan on the east.'),
  ('BSB', 'Joshua', 6, 19, 35, 'The fortified cities were Ziddim, Zer, Hammath, Rakkath, Chinnereth,'),
  ('BSB', 'Joshua', 6, 19, 36, 'Adamah, Ramah, Hazor,'),
  ('BSB', 'Joshua', 6, 19, 37, 'Kedesh, Edrei, En-hazor,'),
  ('BSB', 'Joshua', 6, 19, 38, 'Iron, Migdal-el, Horem, Beth-anath, and Beth-shemesh. There were nineteen cities, along with their villages.'),
  ('BSB', 'Joshua', 6, 19, 39, 'This was the inheritance of the clans of the tribe of Naphtali, including these cities and their villages.'),
  ('BSB', 'Joshua', 6, 19, 40, 'The seventh lot came out for the clans of the tribe of Dan:'),
  ('BSB', 'Joshua', 6, 19, 41, 'The territory of their inheritance included Zorah, Eshtaol, Ir-shemesh,'),
  ('BSB', 'Joshua', 6, 19, 42, 'Shaalabbin, Aijalon, Ithlah,'),
  ('BSB', 'Joshua', 6, 19, 43, 'Elon, Timnah, Ekron,'),
  ('BSB', 'Joshua', 6, 19, 44, 'Eltekeh, Gibbethon, Baalath,'),
  ('BSB', 'Joshua', 6, 19, 45, 'Jehud, Bene-berak, Gath-rimmon,'),
  ('BSB', 'Joshua', 6, 19, 46, 'Me-jarkon, and Rakkon, including the territory across from Joppa.'),
  ('BSB', 'Joshua', 6, 19, 47, '(Later, when the territory of the Danites was lost to them, they went up and fought against Leshem, captured it, and put it to the sword. So they took possession of Leshem, settled there, and renamed it after their father Dan.)'),
  ('BSB', 'Joshua', 6, 19, 48, 'This was the inheritance of the clans of the tribe of Dan, including these cities and their villages.'),
  ('BSB', 'Joshua', 6, 19, 49, 'When they had finished distributing the land into its territories, the Israelites gave Joshua son of Nun an inheritance among them,'),
  ('BSB', 'Joshua', 6, 19, 50, 'as the LORD had commanded. They gave him the city of Timnath-serah in the hill country of Ephraim, as he requested. He rebuilt the city and settled in it.'),
  ('BSB', 'Joshua', 6, 19, 51, 'These are the inheritances that Eleazar the priest, Joshua son of Nun, and the heads of the families distributed by lot to the tribes of Israel at Shiloh before the LORD at the entrance to the Tent of Meeting. So they finished dividing up the land.'),
  ('BSB', 'Joshua', 6, 20, 1, 'Then the LORD said to Joshua,'),
  ('BSB', 'Joshua', 6, 20, 2, '“Tell the Israelites to designate the cities of refuge, as I instructed you through Moses,'),
  ('BSB', 'Joshua', 6, 20, 3, 'so that anyone who kills another unintentionally or accidentally may flee there. These will be your refuge from the avenger of blood.'),
  ('BSB', 'Joshua', 6, 20, 4, 'When someone flees to one of these cities, stands at the entrance of the city gate, and states his case before its elders, they are to bring him into the city and give him a place to live among them.'),
  ('BSB', 'Joshua', 6, 20, 5, 'Now if the avenger of blood pursues him, they must not surrender the manslayer into his hand, because that man killed his neighbor accidentally without prior malice.'),
  ('BSB', 'Joshua', 6, 20, 6, 'He is to stay in that city until he stands trial before the assembly and until the death of the high priest serving at that time. Then the manslayer may return to his own home in the city from which he fled.”'),
  ('BSB', 'Joshua', 6, 20, 7, 'So they set apart Kedesh in Galilee in the hill country of Naphtali, Shechem in the hill country of Ephraim, and Kiriath-arba (that is, Hebron) in the hill country of Judah.'),
  ('BSB', 'Joshua', 6, 20, 8, 'And beyond the Jordan, east of Jericho, they designated Bezer on the wilderness plateau from the tribe of Reuben, Ramoth in Gilead from the tribe of Gad, and Golan in Bashan from the tribe of Manasseh.'),
  ('BSB', 'Joshua', 6, 20, 9, 'These are the cities appointed for all the Israelites and foreigners among them, so that anyone who kills a person unintentionally may flee there and not die by the hand of the avenger of blood prior to standing trial before the assembly.'),
  ('BSB', 'Joshua', 6, 21, 1, 'Now the family heads of the Levites approached Eleazar the priest, Joshua son of Nun, and the heads of the other tribes of Israel'),
  ('BSB', 'Joshua', 6, 21, 2, 'at Shiloh in the land of Canaan and said to them, “The LORD commanded through Moses that we be given cities in which to live, together with pasturelands for our livestock.”'),
  ('BSB', 'Joshua', 6, 21, 3, 'So by the command of the LORD, the Israelites gave the Levites these cities and their pasturelands out of their own inheritance:'),
  ('BSB', 'Joshua', 6, 21, 4, 'The first lot came out for the Kohathite clans. The Levites who were descendants of Aaron the priest received thirteen cities by lot from the tribes of Judah, Simeon, and Benjamin.'),
  ('BSB', 'Joshua', 6, 21, 5, 'The remaining descendants of Kohath received ten cities by lot from the tribes of Ephraim, Dan, and the half-tribe of Manasseh.'),
  ('BSB', 'Joshua', 6, 21, 6, 'The descendants of Gershon received thirteen cities by lot from the tribes of Issachar, Asher, Naphtali, and the half-tribe of Manasseh in Bashan.'),
  ('BSB', 'Joshua', 6, 21, 7, 'And the descendants of Merari received twelve cities from the tribes of Reuben, Gad, and Zebulun.'),
  ('BSB', 'Joshua', 6, 21, 8, 'So the Israelites allotted to the Levites these cities, together with their pasturelands, as the LORD had commanded through Moses.'),
  ('BSB', 'Joshua', 6, 21, 9, 'From the tribes of Judah and Simeon, they designated these cities by name'),
  ('BSB', 'Joshua', 6, 21, 10, 'to the descendants of Aaron from the Kohathite clans of the Levites, because the first lot fell to them:'),
  ('BSB', 'Joshua', 6, 21, 11, 'They gave them Kiriath-arba (that is, Hebron), with its surrounding pasturelands, in the hill country of Judah. (Arba was the father of Anak.)'),
  ('BSB', 'Joshua', 6, 21, 12, 'But they had given the fields and villages around the city to Caleb son of Jephunneh as his possession.'),
  ('BSB', 'Joshua', 6, 21, 13, 'So to the descendants of Aaron the priest they gave these cities, together with their pasturelands: Hebron, a city of refuge for the manslayer, Libnah,'),
  ('BSB', 'Joshua', 6, 21, 14, 'Jattir, Eshtemoa,'),
  ('BSB', 'Joshua', 6, 21, 15, 'Holon, Debir,'),
  ('BSB', 'Joshua', 6, 21, 16, 'Ain, Juttah, and Beth-shemesh—nine cities from these two tribes, together with their pasturelands.'),
  ('BSB', 'Joshua', 6, 21, 17, 'And from the tribe of Benjamin they gave them Gibeon, Geba,'),
  ('BSB', 'Joshua', 6, 21, 18, 'Anathoth, and Almon—four cities, together with their pasturelands.');
insert into control_room_bible (version, book, book_num, chapter, verse, text) values
  ('BSB', 'Joshua', 6, 21, 19, 'In all, thirteen cities, together with their pasturelands, were given to the priests, the descendants of Aaron.'),
  ('BSB', 'Joshua', 6, 21, 20, 'The remaining Kohathite clans of the Levites were allotted these cities:'),
  ('BSB', 'Joshua', 6, 21, 21, 'From the tribe of Ephraim they were given Shechem in the hill country of Ephraim (a city of refuge for the manslayer), Gezer,'),
  ('BSB', 'Joshua', 6, 21, 22, 'Kibzaim, and Beth-horon—four cities, together with their pasturelands.'),
  ('BSB', 'Joshua', 6, 21, 23, 'From the tribe of Dan they were given Elteke, Gibbethon,'),
  ('BSB', 'Joshua', 6, 21, 24, 'Aijalon, and Gath-rimmon—four cities, together with their pasturelands.'),
  ('BSB', 'Joshua', 6, 21, 25, 'And from the half-tribe of Manasseh they were given Taanach and Gath-rimmon—two cities, together with their pasturelands.'),
  ('BSB', 'Joshua', 6, 21, 26, 'In all, ten cities, together with their pasturelands, were given to the rest of the Kohathite clans.'),
  ('BSB', 'Joshua', 6, 21, 27, 'This is what the Levite clans of the Gershonites were given: From the half-tribe of Manasseh they were given Golan in Bashan, a city of refuge for the manslayer, and Beeshterah—two cities, together with their pasturelands.'),
  ('BSB', 'Joshua', 6, 21, 28, 'From the tribe of Issachar they were given Kishion, Daberath,'),
  ('BSB', 'Joshua', 6, 21, 29, 'Jarmuth, and En-gannim—four cities, together with their pasturelands.'),
  ('BSB', 'Joshua', 6, 21, 30, 'From the tribe of Asher they were given Mishal, Abdon,'),
  ('BSB', 'Joshua', 6, 21, 31, 'Helkath, and Rehob—four cities, together with their pasturelands.'),
  ('BSB', 'Joshua', 6, 21, 32, 'And from the tribe of Naphtali they were given Kedesh in Galilee (a city of refuge for the manslayer), Hammoth-dor, and Kartan—three cities, together with their pasturelands.'),
  ('BSB', 'Joshua', 6, 21, 33, 'In all, thirteen cities, together with their pasturelands, were given to the Gershonite clans.'),
  ('BSB', 'Joshua', 6, 21, 34, 'This is what the Merarite clan (the rest of the Levites) were given:'),
  ('BSB', 'Joshua', 6, 21, 35, 'From the tribe of Zebulun they were given Jokneam, Kartah, Dimnah, and Nahalal—four cities, together with their pasturelands.'),
  ('BSB', 'Joshua', 6, 21, 36, 'From the tribe of Reuben they were given Bezer, Jahaz,'),
  ('BSB', 'Joshua', 6, 21, 37, 'Kedemoth, and Mephaath—four cities, together with their pasturelands.'),
  ('BSB', 'Joshua', 6, 21, 38, 'And from the tribe of Gad they were given Ramoth in Gilead, a city of refuge for the manslayer, Mahanaim,'),
  ('BSB', 'Joshua', 6, 21, 39, 'Heshbon, and Jazer—four cities in all, together with their pasturelands.'),
  ('BSB', 'Joshua', 6, 21, 40, 'In all, twelve cities were allotted to the clans of Merari, the remaining Levite clans.'),
  ('BSB', 'Joshua', 6, 21, 41, 'For the Levites, then, there were forty-eight cities in all, together with their pasturelands, within the territory of the Israelites.'),
  ('BSB', 'Joshua', 6, 21, 42, 'Each of these cities had its own surrounding pasturelands; this was true for all the cities.'),
  ('BSB', 'Joshua', 6, 21, 43, 'Thus the LORD gave Israel all the land He had sworn to give their fathers, and they took possession of it and settled in it.'),
  ('BSB', 'Joshua', 6, 21, 44, 'And the LORD gave them rest on every side, just as He had sworn to their fathers. None of their enemies could stand against them, for the LORD delivered all their enemies into their hand.'),
  ('BSB', 'Joshua', 6, 21, 45, 'Not one of all the LORD’s good promises to the house of Israel had failed; everything was fulfilled.'),
  ('BSB', 'Joshua', 6, 22, 1, 'Then Joshua summoned the Reubenites, the Gadites, and the half-tribe of Manasseh'),
  ('BSB', 'Joshua', 6, 22, 2, 'and told them, “You have done all that Moses the servant of the LORD commanded you, and you have obeyed my voice in all that I commanded you.'),
  ('BSB', 'Joshua', 6, 22, 3, 'All this time you have not deserted your brothers, up to this very day, but have kept the charge given you by the LORD your God.'),
  ('BSB', 'Joshua', 6, 22, 4, 'And now that the LORD your God has given your brothers rest as He promised them, you may return to your homes in the land that Moses the servant of the LORD gave you across the Jordan.'),
  ('BSB', 'Joshua', 6, 22, 5, 'But be very careful to observe the commandment and the law that Moses the servant of the LORD gave you: to love the LORD your God, to walk in all His ways, to keep His commandments, to hold fast to Him, and to serve Him with all your heart and with all your soul.”'),
  ('BSB', 'Joshua', 6, 22, 6, 'So Joshua blessed them and sent them on their way, and they went to their homes.'),
  ('BSB', 'Joshua', 6, 22, 7, '(To the half-tribe of Manasseh Moses had given land in Bashan, and to the other half Joshua gave land on the west side of the Jordan among their brothers.) When Joshua sent them to their homes he blessed them,'),
  ('BSB', 'Joshua', 6, 22, 8, 'saying, “Return to your homes with your great wealth, with immense herds of livestock, with silver, gold, bronze, iron, and very many clothes. Divide with your brothers the spoil of your enemies.”'),
  ('BSB', 'Joshua', 6, 22, 9, 'So the Reubenites, the Gadites, and the half-tribe of Manasseh left the Israelites at Shiloh in the land of Canaan to return to their own land of Gilead, which they had acquired according to the command of the LORD through Moses.'),
  ('BSB', 'Joshua', 6, 22, 10, 'And when they came to Geliloth near the Jordan in the land of Canaan, the Reubenites, the Gadites, and the half-tribe of Manasseh built an imposing altar there by the Jordan.'),
  ('BSB', 'Joshua', 6, 22, 11, 'Then the Israelites received the report: “Behold, the Reubenites, the Gadites, and the half-tribe of Manasseh have built an altar on the border of the land of Canaan, at Geliloth near the Jordan on the Israelite side.”'),
  ('BSB', 'Joshua', 6, 22, 12, 'And when they heard this, the whole congregation of Israel assembled at Shiloh to go to war against them.'),
  ('BSB', 'Joshua', 6, 22, 13, 'The Israelites sent Phinehas son of Eleazar the priest to the land of Gilead, to the Reubenites, the Gadites, and the half-tribe of Manasseh.'),
  ('BSB', 'Joshua', 6, 22, 14, 'With him they sent ten chiefs—one family leader from each tribe of Israel, each the head of a family among the clans of Israel.'),
  ('BSB', 'Joshua', 6, 22, 15, 'They went to the Reubenites, the Gadites, and the half-tribe of Manasseh in the land of Gilead and said to them,'),
  ('BSB', 'Joshua', 6, 22, 16, '“This is what the whole congregation of the LORD says: ‘What is this breach of faith you have committed today against the God of Israel by turning away from the LORD and building for yourselves an altar, that you might rebel against the LORD this day?'),
  ('BSB', 'Joshua', 6, 22, 17, 'Was not the sin of Peor enough for us, from which we have not cleansed ourselves to this day? It even brought a plague upon the congregation of the LORD.'),
  ('BSB', 'Joshua', 6, 22, 18, 'And now, would you turn away from the LORD? If you rebel today against the LORD, tomorrow He will be angry with the whole congregation of Israel.'),
  ('BSB', 'Joshua', 6, 22, 19, 'If indeed the land of your inheritance is unclean, then cross over to the land of the LORD’s possession, where the LORD’s tabernacle stands, and take possession of it among us. But do not rebel against the LORD or against us by building for yourselves an altar other than the altar of the LORD our God.'),
  ('BSB', 'Joshua', 6, 22, 20, 'Was not Achan son of Zerah unfaithful regarding what was set apart for destruction, bringing wrath upon the whole congregation of Israel? Yet it was not only Achan who perished because of his sin!’”'),
  ('BSB', 'Joshua', 6, 22, 21, 'Then the Reubenites, the Gadites, and the half-tribe of Manasseh answered the leaders of the clans of Israel:'),
  ('BSB', 'Joshua', 6, 22, 22, '“The LORD, the Mighty One, is God! The LORD, the Mighty One, is God! He knows, and may Israel also know. If this was in rebellion or breach of faith against the LORD, do not spare us today.'),
  ('BSB', 'Joshua', 6, 22, 23, 'If we have built for ourselves an altar to turn away from Him and to offer burnt offerings and grain offerings on it, or to sacrifice fellowship offerings on it, may the LORD Himself hold us accountable.'),
  ('BSB', 'Joshua', 6, 22, 24, 'But in fact we have done this for fear that in the future your descendants might say to ours, ‘What have you to do with the LORD, the God of Israel?'),
  ('BSB', 'Joshua', 6, 22, 25, 'For the LORD has made the Jordan a border between us and you Reubenites and Gadites. You have no share in the LORD!’ So your descendants could cause ours to stop fearing the LORD.'),
  ('BSB', 'Joshua', 6, 22, 26, 'That is why we said, ‘Let us take action and build an altar for ourselves, but not for burnt offerings or sacrifices.'),
  ('BSB', 'Joshua', 6, 22, 27, 'Rather, let it be a witness between us and you and the generations to come, that we will worship the LORD in His presence with our burnt offerings, sacrifices, and peace offerings.’ Then in the future, your descendants cannot say to ours, ‘You have no share in the LORD!’'),
  ('BSB', 'Joshua', 6, 22, 28, 'Therefore we said, ‘If they ever say this to us or to our descendants, we will answer: Look at the replica of the altar of the LORD that our fathers made, not for burnt offerings or sacrifices, but as a witness between us and you.’'),
  ('BSB', 'Joshua', 6, 22, 29, 'Far be it from us to rebel against the LORD and turn away from Him today by building an altar for burnt offerings, grain offerings, or sacrifices, other than the altar of the LORD our God, which stands before His tabernacle.”'),
  ('BSB', 'Joshua', 6, 22, 30, 'When Phinehas the priest and the chiefs of the congregation—the heads of Israel’s clans who were with him—heard what the descendants of Reuben, Gad, and Manasseh had to say, they were satisfied.'),
  ('BSB', 'Joshua', 6, 22, 31, 'Phinehas son of Eleazar the priest said to the descendants of Reuben, Gad, and Manasseh, “Today we know that the LORD is among us, because you have not committed this breach of faith against Him. Consequently, you have delivered the Israelites from the hand of the LORD.”'),
  ('BSB', 'Joshua', 6, 22, 32, 'Then Phinehas son of Eleazar the priest, together with the other leaders, returned to the Israelites in the land of Canaan and brought back a report regarding the Reubenites and Gadites in the land of Gilead.'),
  ('BSB', 'Joshua', 6, 22, 33, 'The Israelites were satisfied with the report, and they blessed God and spoke no more about going to war against them to destroy the land where the Reubenites and Gadites lived.'),
  ('BSB', 'Joshua', 6, 22, 34, 'So the Reubenites and Gadites named the altar Witness, for they said, “It is a witness between us that the LORD is God.”'),
  ('BSB', 'Joshua', 6, 23, 1, 'A long time after the LORD had given Israel rest from all the enemies around them, when Joshua was old and well along in years,'),
  ('BSB', 'Joshua', 6, 23, 2, 'he summoned all Israel, including its elders, leaders, judges, and officers. “I am old and well along in years,” he said,'),
  ('BSB', 'Joshua', 6, 23, 3, '“and you have seen everything that the LORD your God has done to all these nations for your sake, because it was the LORD your God who fought for you.'),
  ('BSB', 'Joshua', 6, 23, 4, 'See, I have allotted as an inheritance to your tribes these remaining nations, including all the nations I have already cut off, from the Jordan westward to the Great Sea.'),
  ('BSB', 'Joshua', 6, 23, 5, 'The LORD your God will push them out of your way and drive them out before you, so that you can take possession of their land, as the LORD your God promised you.'),
  ('BSB', 'Joshua', 6, 23, 6, 'Be very strong, then, so that you can keep and obey all that is written in the Book of the Law of Moses, not turning aside from it to the right or to the left.'),
  ('BSB', 'Joshua', 6, 23, 7, 'So you are not to associate with these nations that remain among you. You must not call on the names of their gods or swear by them, and you must not serve them or bow down to them.'),
  ('BSB', 'Joshua', 6, 23, 8, 'Instead, you shall hold fast to the LORD your God, as you have done to this day.'),
  ('BSB', 'Joshua', 6, 23, 9, 'The LORD has driven out great and powerful nations before you, and to this day no one can stand against you.'),
  ('BSB', 'Joshua', 6, 23, 10, 'One of you can put a thousand to flight, because the LORD your God fights for you, just as He promised.'),
  ('BSB', 'Joshua', 6, 23, 11, 'Therefore watch yourselves carefully, that you love the LORD your God.'),
  ('BSB', 'Joshua', 6, 23, 12, 'For if you turn away and cling to the rest of these nations that remain among you, and if you intermarry and associate with them,'),
  ('BSB', 'Joshua', 6, 23, 13, 'know for sure that the LORD your God will no longer drive out these nations before you. Instead, they will become for you a snare and a trap, a scourge in your sides and thorns in your eyes, until you perish from this good land that the LORD your God has given you.'),
  ('BSB', 'Joshua', 6, 23, 14, 'Now behold, today I am going the way of all the earth, and you know with all your heart and soul that not one of the good promises the LORD your God made to you has failed. Everything was fulfilled for you; not one promise has failed.'),
  ('BSB', 'Joshua', 6, 23, 15, 'But just as every good thing the LORD your God promised you has come to pass, likewise the LORD will bring upon you the calamity He has threatened, until He has destroyed you from this good land He has given you.'),
  ('BSB', 'Joshua', 6, 23, 16, 'If you transgress the covenant of the LORD your God, which He commanded you, and go and serve other gods and bow down to them, then the anger of the LORD will burn against you, and you will quickly perish from this good land He has given you.”'),
  ('BSB', 'Joshua', 6, 24, 1, 'Then Joshua assembled all the tribes of Israel at Shechem. He summoned the elders, leaders, judges, and officers of Israel, and they presented themselves before God.'),
  ('BSB', 'Joshua', 6, 24, 2, 'And Joshua said to all the people, “This is what the LORD, the God of Israel, says: ‘Long ago your fathers, including Terah the father of Abraham and Nahor, lived beyond the Euphrates and worshiped other gods.'),
  ('BSB', 'Joshua', 6, 24, 3, 'But I took your father Abraham from beyond the Euphrates and led him through all the land of Canaan, and I multiplied his descendants. I gave him Isaac,'),
  ('BSB', 'Joshua', 6, 24, 4, 'and to Isaac I gave Jacob and Esau. I gave Esau Mount Seir to possess, but Jacob and his sons went down to Egypt.'),
  ('BSB', 'Joshua', 6, 24, 5, 'Then I sent Moses and Aaron, and I afflicted the Egyptians by what I did there, and afterward I brought you out.'),
  ('BSB', 'Joshua', 6, 24, 6, 'When I brought your fathers out of Egypt and you reached the Red Sea, the Egyptians pursued them with chariots and horsemen as far as the Red Sea.'),
  ('BSB', 'Joshua', 6, 24, 7, 'So your fathers cried out to the LORD, and He put darkness between you and the Egyptians, over whom He brought the sea and engulfed them. Your very eyes saw what I did to the Egyptians. Then you lived in the wilderness for a long time.'),
  ('BSB', 'Joshua', 6, 24, 8, 'Later, I brought you to the land of the Amorites who lived beyond the Jordan. They fought against you, but I delivered them into your hand, that you should possess their land when I destroyed them before you.'),
  ('BSB', 'Joshua', 6, 24, 9, 'Then Balak son of Zippor, the king of Moab, set out to fight against Israel. He sent for Balaam son of Beor to curse you,'),
  ('BSB', 'Joshua', 6, 24, 10, 'but I would not listen to Balaam. So he blessed you again and again, and I delivered you from his hand.'),
  ('BSB', 'Joshua', 6, 24, 11, 'After this, you crossed the Jordan and came to Jericho. The people of Jericho fought against you, as did the Amorites, Perizzites, Canaanites, Hittites, Girgashites, Hivites, and Jebusites, and I delivered them into your hand.'),
  ('BSB', 'Joshua', 6, 24, 12, 'I sent the hornet ahead of you, and it drove out the two Amorite kings before you, but not by your own sword or bow.'),
  ('BSB', 'Joshua', 6, 24, 13, 'So I gave you a land on which you did not toil and cities that you did not build, and now you live in them and eat from vineyards and olive groves that you did not plant.’'),
  ('BSB', 'Joshua', 6, 24, 14, 'Now, therefore, fear the LORD and serve Him in sincerity and truth; cast aside the gods your fathers served beyond the Euphrates and in Egypt, and serve the LORD.'),
  ('BSB', 'Joshua', 6, 24, 15, 'But if it is unpleasing in your sight to serve the LORD, then choose for yourselves this day whom you will serve, whether the gods your fathers served beyond the Euphrates, or the gods of the Amorites in whose land you are living. As for me and my house, we will serve the LORD!”'),
  ('BSB', 'Joshua', 6, 24, 16, 'The people replied, “Far be it from us to forsake the LORD to serve other gods!'),
  ('BSB', 'Joshua', 6, 24, 17, 'For the LORD our God brought us and our fathers out of the land of Egypt, out of the house of slavery, and performed these great signs before our eyes. He also protected us throughout our journey and among all the nations through which we traveled.'),
  ('BSB', 'Joshua', 6, 24, 18, 'And the LORD drove out before us all the nations, including the Amorites who lived in the land. We too will serve the LORD, because He is our God!”'),
  ('BSB', 'Joshua', 6, 24, 19, 'But Joshua said to the people, “You are not able to serve the LORD, for He is a holy God; He is a jealous God; He will not forgive your rebellion or your sins.'),
  ('BSB', 'Joshua', 6, 24, 20, 'If you forsake the LORD and serve foreign gods, He will turn and bring disaster on you and consume you, even after He has been good to you.”'),
  ('BSB', 'Joshua', 6, 24, 21, '“No!” replied the people. “We will serve the LORD!”'),
  ('BSB', 'Joshua', 6, 24, 22, 'Then Joshua told them, “You are witnesses against yourselves that you have chosen to serve the LORD.” “We are witnesses!” they said.'),
  ('BSB', 'Joshua', 6, 24, 23, '“Now, therefore,” he said, “get rid of the foreign gods among you and incline your hearts to the LORD, the God of Israel.”'),
  ('BSB', 'Joshua', 6, 24, 24, 'So the people said to Joshua, “We will serve the LORD our God and obey His voice.”'),
  ('BSB', 'Joshua', 6, 24, 25, 'On that day Joshua made a covenant for the people, and there at Shechem he established for them a statute and ordinance.'),
  ('BSB', 'Joshua', 6, 24, 26, 'Joshua recorded these things in the Book of the Law of God. Then he took a large stone and set it up there under the oak that was near the sanctuary of the LORD.'),
  ('BSB', 'Joshua', 6, 24, 27, 'And Joshua said to all the people, “You see this stone. It will be a witness against us, for it has heard all the words the LORD has spoken to us, and it will be a witness against you if you ever deny your God.”'),
  ('BSB', 'Joshua', 6, 24, 28, 'Then Joshua sent the people away, each to his own inheritance.'),
  ('BSB', 'Joshua', 6, 24, 29, 'Some time later, Joshua son of Nun, the servant of the LORD, died at the age of 110.'),
  ('BSB', 'Joshua', 6, 24, 30, 'And they buried him in the land of his inheritance, at Timnath-serah in the hill country of Ephraim, north of Mount Gaash.'),
  ('BSB', 'Joshua', 6, 24, 31, 'Israel had served the LORD throughout the days of Joshua and of the elders who outlived him and who had experienced all the works that the LORD had done for Israel.'),
  ('BSB', 'Joshua', 6, 24, 32, 'And the bones of Joseph, which the Israelites had brought up out of Egypt, were buried at Shechem in the plot of land that Jacob had purchased from the sons of Hamor, Shechem’s father, for a hundred pieces of silver. So it became an inheritance for Joseph’s descendants.'),
  ('BSB', 'Joshua', 6, 24, 33, 'Eleazar son of Aaron also died, and they buried him at Gibeah, which had been given to his son Phinehas in the hill country of Ephraim.'),
  ('BSB', 'Judges', 7, 1, 1, 'After the death of Joshua, the Israelites inquired of the LORD, “Who will be the first to go up and fight for us against the Canaanites?”'),
  ('BSB', 'Judges', 7, 1, 2, '“Judah shall go up,” answered the LORD. “Indeed, I have delivered the land into their hands.”'),
  ('BSB', 'Judges', 7, 1, 3, 'Then the men of Judah said to their brothers the Simeonites, “Come up with us to our allotted territory, and let us fight against the Canaanites. And we likewise will go with you to your territory.” So the Simeonites went with them.'),
  ('BSB', 'Judges', 7, 1, 4, 'When Judah attacked, the LORD delivered the Canaanites and Perizzites into their hands, and they struck down ten thousand men at Bezek.'),
  ('BSB', 'Judges', 7, 1, 5, 'And there they found Adoni-bezek and fought against him, striking down the Canaanites and Perizzites.'),
  ('BSB', 'Judges', 7, 1, 6, 'As Adoni-bezek fled, they pursued him, seized him, and cut off his thumbs and big toes.'),
  ('BSB', 'Judges', 7, 1, 7, 'Then Adoni-bezek said, “Seventy kings with their thumbs and big toes cut off have gathered the scraps under my table. As I have done to them, so God has repaid me.” And they brought him to Jerusalem, where he died.'),
  ('BSB', 'Judges', 7, 1, 8, 'Then the men of Judah fought against Jerusalem and captured it. They put the city to the sword and set it on fire.'),
  ('BSB', 'Judges', 7, 1, 9, 'Afterward, the men of Judah marched down to fight against the Canaanites living in the hill country, in the Negev, and in the foothills.'),
  ('BSB', 'Judges', 7, 1, 10, 'Judah also marched against the Canaanites who were living in Hebron (formerly known as Kiriath-arba), and they struck down Sheshai, Ahiman, and Talmai.'),
  ('BSB', 'Judges', 7, 1, 11, 'From there they marched against the inhabitants of Debir (formerly known as Kiriath-sepher).'),
  ('BSB', 'Judges', 7, 1, 12, 'And Caleb said, “To the man who strikes down Kiriath-sepher and captures it, I will give my daughter Acsah in marriage.”'),
  ('BSB', 'Judges', 7, 1, 13, 'So Othniel son of Caleb’s younger brother Kenaz captured the city, and Caleb gave his daughter Acsah to him in marriage.'),
  ('BSB', 'Judges', 7, 1, 14, 'One day Acsah came to Othniel and urged him to ask her father for a field. When she got off her donkey, Caleb asked her, “What do you desire?”'),
  ('BSB', 'Judges', 7, 1, 15, '“Give me a blessing,” she answered. “Since you have given me land in the Negev, give me springs of water as well.” So Caleb gave her both the upper and lower springs.'),
  ('BSB', 'Judges', 7, 1, 16, 'Now the descendants of Moses’ father-in-law, the Kenite, went up with the men of Judah from the City of Palms to the Wilderness of Judah in the Negev near Arad. They went to live among the people.'),
  ('BSB', 'Judges', 7, 1, 17, 'Then the men of Judah went with their brothers the Simeonites, attacked the Canaanites living in Zephath, and devoted the city to destruction. So it was called Hormah.'),
  ('BSB', 'Judges', 7, 1, 18, 'And Judah also captured Gaza, Ashkelon, and Ekron—each with its territory.'),
  ('BSB', 'Judges', 7, 1, 19, 'The LORD was with Judah, and they took possession of the hill country; but they could not drive out the inhabitants of the plains because they had chariots of iron.'),
  ('BSB', 'Judges', 7, 1, 20, 'Just as Moses had promised, Judah gave Hebron to Caleb, who drove out the descendants of the three sons of Anak.'),
  ('BSB', 'Judges', 7, 1, 21, 'The Benjamites, however, failed to drive out the Jebusites living in Jerusalem. So to this day the Jebusites live there among the Benjamites.'),
  ('BSB', 'Judges', 7, 1, 22, 'The house of Joseph also attacked Bethel, and the LORD was with them.'),
  ('BSB', 'Judges', 7, 1, 23, 'They sent spies to Bethel (formerly known as Luz),'),
  ('BSB', 'Judges', 7, 1, 24, 'and when the spies saw a man coming out of the city, they said to him, “Please show us how to get into the city, and we will treat you kindly.”'),
  ('BSB', 'Judges', 7, 1, 25, 'So the man showed them the entrance to the city, and they put the city to the sword but released that man and all his family.'),
  ('BSB', 'Judges', 7, 1, 26, 'And the man went to the land of the Hittites, built a city, and called it Luz, which is its name to this day.'),
  ('BSB', 'Judges', 7, 1, 27, 'At that time Manasseh failed to drive out the inhabitants of Beth-shean, Taanach, Dor, Ibleam, Megiddo, and their villages; for the Canaanites were determined to dwell in that land.'),
  ('BSB', 'Judges', 7, 1, 28, 'When Israel became stronger, they pressed the Canaanites into forced labor, but they never drove them out completely.'),
  ('BSB', 'Judges', 7, 1, 29, 'Ephraim also failed to drive out the Canaanites living in Gezer; so the Canaanites continued to dwell among them in Gezer.'),
  ('BSB', 'Judges', 7, 1, 30, 'Zebulun failed to drive out the inhabitants of Kitron and Nahalol; so the Canaanites lived among them and served as forced laborers.'),
  ('BSB', 'Judges', 7, 1, 31, 'Asher failed to drive out the inhabitants of Acco, Sidon, Ahlab, Achzib, Helbah, Aphik, and Rehob.'),
  ('BSB', 'Judges', 7, 1, 32, 'So the Asherites lived among the Canaanite inhabitants of the land, because they did not drive them out.'),
  ('BSB', 'Judges', 7, 1, 33, 'Naphtali failed to drive out the inhabitants of Beth-shemesh and Beth-anath. So the Naphtalites also lived among the Canaanite inhabitants of the land, but the inhabitants of Beth-shemesh and Beth-anath served them as forced laborers.'),
  ('BSB', 'Judges', 7, 1, 34, 'The Amorites forced the Danites into the hill country and did not allow them to come down into the plain.'),
  ('BSB', 'Judges', 7, 1, 35, 'And the Amorites were determined to dwell in Mount Heres, Aijalon, and Shaalbim. But when the house of Joseph grew in strength, they pressed the Amorites into forced labor.'),
  ('BSB', 'Judges', 7, 1, 36, 'And the border of the Amorites extended from the Ascent of Akrabbim to Sela and beyond.'),
  ('BSB', 'Judges', 7, 2, 1, 'Now the angel of the LORD went up from Gilgal to Bochim and said, “I brought you up out of Egypt and led you into the land that I had promised to your fathers, and I said, ‘I will never break My covenant with you,'),
  ('BSB', 'Judges', 7, 2, 2, 'and you are not to make a covenant with the people of this land, but you shall tear down their altars.’ Yet you have not obeyed My voice. What is this you have done?'),
  ('BSB', 'Judges', 7, 2, 3, 'So now I tell you that I will not drive out these people before you; they will be thorns in your sides, and their gods will be a snare to you.”'),
  ('BSB', 'Judges', 7, 2, 4, 'When the angel of the LORD had spoken these words to all the Israelites, the people lifted up their voices and wept.'),
  ('BSB', 'Judges', 7, 2, 5, 'So they called that place Bochim and offered sacrifices there to the LORD.'),
  ('BSB', 'Judges', 7, 2, 6, 'After Joshua had dismissed the people, the Israelites went out to take possession of the land, each to his own inheritance.'),
  ('BSB', 'Judges', 7, 2, 7, 'And the people served the LORD throughout the days of Joshua and of the elders who outlived him, who had seen all the great works that the LORD had done for Israel.'),
  ('BSB', 'Judges', 7, 2, 8, 'And Joshua son of Nun, the servant of the LORD, died at the age of 110.'),
  ('BSB', 'Judges', 7, 2, 9, 'They buried him in the land of his inheritance, at Timnath-heres in the hill country of Ephraim, north of Mount Gaash.'),
  ('BSB', 'Judges', 7, 2, 10, 'After that whole generation had also been gathered to their fathers, another generation rose up who did not know the LORD or the works that He had done for Israel.'),
  ('BSB', 'Judges', 7, 2, 11, 'And the Israelites did evil in the sight of the LORD and served the Baals.'),
  ('BSB', 'Judges', 7, 2, 12, 'Thus they forsook the LORD, the God of their fathers, who had brought them out of the land of Egypt, and they followed after various gods of the peoples around them. They bowed down to them and provoked the LORD to anger,'),
  ('BSB', 'Judges', 7, 2, 13, 'for they forsook Him and served Baal and the Ashtoreths.'),
  ('BSB', 'Judges', 7, 2, 14, 'Then the anger of the LORD burned against Israel, and He delivered them into the hands of those who plundered them. He sold them into the hands of their enemies all around, whom they were no longer able to resist.'),
  ('BSB', 'Judges', 7, 2, 15, 'Wherever Israel marched out, the hand of the LORD was against them to bring calamity, just as He had sworn to them. So they were greatly distressed.'),
  ('BSB', 'Judges', 7, 2, 16, 'Then the LORD raised up judges, who saved them from the hands of those who plundered them.'),
  ('BSB', 'Judges', 7, 2, 17, 'Israel, however, did not listen to their judges. Instead, they prostituted themselves with other gods and bowed down to them. They quickly turned from the way of their fathers, who had walked in obedience to the LORD’s commandments; they did not do as their fathers had done.'),
  ('BSB', 'Judges', 7, 2, 18, 'Whenever the LORD raised up a judge for the Israelites, He was with that judge and saved them from the hands of their enemies while the judge was still alive; for the LORD was moved to pity by their groaning under those who oppressed them and afflicted them.'),
  ('BSB', 'Judges', 7, 2, 19, 'But when the judge died, the Israelites became even more corrupt than their fathers, going after other gods to serve them and bow down to them. They would not give up their evil practices and stubborn ways.'),
  ('BSB', 'Judges', 7, 2, 20, 'So the anger of the LORD burned against Israel, and He said, “Because this nation has transgressed the covenant I laid down for their fathers and has not heeded My voice,'),
  ('BSB', 'Judges', 7, 2, 21, 'I will no longer drive out before them any of the nations Joshua left when he died.'),
  ('BSB', 'Judges', 7, 2, 22, 'In this way I will test whether Israel will keep the way of the LORD by walking in it as their fathers did.”'),
  ('BSB', 'Judges', 7, 2, 23, 'That is why the LORD had left those nations in place and had not driven them out immediately by delivering them into the hand of Joshua.'),
  ('BSB', 'Judges', 7, 3, 1, 'These are the nations that the LORD left to test all the Israelites who had not known any of the wars in Canaan,'),
  ('BSB', 'Judges', 7, 3, 2, 'if only to teach warfare to the subsequent generations of Israel, especially to those who had not known it formerly:'),
  ('BSB', 'Judges', 7, 3, 3, 'the five rulers of the Philistines, all the Canaanites, the Sidonians, and the Hivites who lived in the mountains of Lebanon from Mount Baal-hermon to Lebo-hamath.'),
  ('BSB', 'Judges', 7, 3, 4, 'These nations were left to test the Israelites, to find out whether they would keep the commandments of the LORD, which He had given their fathers through Moses.'),
  ('BSB', 'Judges', 7, 3, 5, 'Thus the Israelites continued to live among the Canaanites, Hittites, Amorites, Perizzites, Hivites, and Jebusites.'),
  ('BSB', 'Judges', 7, 3, 6, 'And they took the daughters of these people in marriage, gave their own daughters to their sons, and served their gods.'),
  ('BSB', 'Judges', 7, 3, 7, 'So the Israelites did evil in the sight of the LORD; they forgot the LORD their God and served the Baals and the Asherahs.'),
  ('BSB', 'Judges', 7, 3, 8, 'Then the anger of the LORD burned against Israel, and He sold them into the hand of Cushan-rishathaim king of Aram-naharaim, and the Israelites served him eight years.'),
  ('BSB', 'Judges', 7, 3, 9, 'But when the Israelites cried out to the LORD, He raised up Othniel son of Caleb’s younger brother Kenaz as a deliverer to save them.'),
  ('BSB', 'Judges', 7, 3, 10, 'The Spirit of the LORD came upon him, and he became Israel’s judge and went out to war. And the LORD delivered Cushan-rishathaim king of Aram into the hand of Othniel, who prevailed against him.'),
  ('BSB', 'Judges', 7, 3, 11, 'So the land had rest for forty years, until Othniel son of Kenaz died.'),
  ('BSB', 'Judges', 7, 3, 12, 'Once again the Israelites did evil in the sight of the LORD. So He gave Eglon king of Moab power over Israel, because they had done evil in the sight of the LORD.'),
  ('BSB', 'Judges', 7, 3, 13, 'After enlisting the Ammonites and Amalekites to join forces with him, Eglon attacked and defeated Israel, taking possession of the City of Palms.'),
  ('BSB', 'Judges', 7, 3, 14, 'The Israelites served Eglon king of Moab eighteen years.'),
  ('BSB', 'Judges', 7, 3, 15, 'And again they cried out to the LORD, and He raised up Ehud son of Gera, a left-handed Benjamite, as their deliverer. So they sent him with tribute to Eglon king of Moab.'),
  ('BSB', 'Judges', 7, 3, 16, 'Now Ehud had made for himself a double-edged sword a cubit long. He strapped it to his right thigh under his cloak'),
  ('BSB', 'Judges', 7, 3, 17, 'and brought the tribute to Eglon king of Moab, who was an obese man.'),
  ('BSB', 'Judges', 7, 3, 18, 'After Ehud had finished presenting the tribute, he ushered out those who had carried it.'),
  ('BSB', 'Judges', 7, 3, 19, 'But upon reaching the idols near Gilgal, he himself turned back and said, “I have a secret message for you, O king.” “Silence,” said the king, and all his attendants left him.'),
  ('BSB', 'Judges', 7, 3, 20, 'Then Ehud approached him while he was sitting alone in the coolness of his upper room. “I have a word from God for you,” Ehud said, and the king rose from his seat.'),
  ('BSB', 'Judges', 7, 3, 21, 'And Ehud reached with his left hand, pulled the sword from his right thigh, and plunged it into Eglon’s belly.'),
  ('BSB', 'Judges', 7, 3, 22, 'Even the handle sank in after the blade, and Eglon’s fat closed in over it, so that Ehud did not withdraw the sword from his belly. And Eglon’s bowels emptied.'),
  ('BSB', 'Judges', 7, 3, 23, 'Then Ehud went out through the porch, closing and locking the doors of the upper room behind him.'),
  ('BSB', 'Judges', 7, 3, 24, 'After Ehud was gone, Eglon’s servants came in and found the doors of the upper room locked. “He must be relieving himself in the cool room,” they said.'),
  ('BSB', 'Judges', 7, 3, 25, 'So they waited until they became worried and saw that he had still not opened the doors of the upper room. Then they took the key and opened the doors—and there was their lord lying dead on the floor.'),
  ('BSB', 'Judges', 7, 3, 26, 'Ehud, however, had escaped while the servants waited. He passed by the idols and escaped to Seirah.'),
  ('BSB', 'Judges', 7, 3, 27, 'On arriving in Seirah, he blew the ram’s horn throughout the hill country of Ephraim. The Israelites came down with him from the hills, and he became their leader.'),
  ('BSB', 'Judges', 7, 3, 28, '“Follow me,” he told them, “for the LORD has delivered your enemies the Moabites into your hand.” So they followed him down and seized the fords of the Jordan leading to Moab, and did not allow anyone to cross over.'),
  ('BSB', 'Judges', 7, 3, 29, 'At that time they struck down about ten thousand Moabites, all robust and valiant men. Not one of them escaped.'),
  ('BSB', 'Judges', 7, 3, 30, 'So Moab was subdued under the hand of Israel that day, and the land had rest for eighty years.'),
  ('BSB', 'Judges', 7, 3, 31, 'After Ehud came Shamgar son of Anath. And he too saved Israel, striking down six hundred Philistines with an oxgoad.'),
  ('BSB', 'Judges', 7, 4, 1, 'After Ehud died, the Israelites again did evil in the sight of the LORD.'),
  ('BSB', 'Judges', 7, 4, 2, 'So the LORD sold them into the hand of Jabin king of Canaan, who reigned in Hazor. The commander of his forces was Sisera, who lived in Harosheth-hagoyim.'),
  ('BSB', 'Judges', 7, 4, 3, 'Then the Israelites cried out to the LORD, because Jabin had nine hundred chariots of iron, and he had harshly oppressed the Israelites for twenty years.'),
  ('BSB', 'Judges', 7, 4, 4, 'Now Deborah, a prophetess, the wife of Lappidoth, was judging Israel at that time.'),
  ('BSB', 'Judges', 7, 4, 5, 'And she would sit under the Palm of Deborah between Ramah and Bethel in the hill country of Ephraim, where the Israelites would go up to her for judgment.'),
  ('BSB', 'Judges', 7, 4, 6, 'She summoned Barak son of Abinoam from Kedesh in Naphtali and said to him, “Surely the LORD, the God of Israel, is commanding you: ‘Go and march to Mount Tabor, taking with you ten thousand men of Naphtali and Zebulun.'),
  ('BSB', 'Judges', 7, 4, 7, 'And I will draw out Sisera the commander of Jabin’s army, his chariots, and his troops to the River Kishon, and I will deliver him into your hand.’”'),
  ('BSB', 'Judges', 7, 4, 8, 'Barak said to her, “If you will go with me, I will go; but if you will not go with me, I will not go.”'),
  ('BSB', 'Judges', 7, 4, 9, '“I will certainly go with you,” Deborah replied, “but the road you are taking will bring you no honor, because the LORD will be selling Sisera into the hand of a woman.” So Deborah got up and went with Barak to Kedesh,'),
  ('BSB', 'Judges', 7, 4, 10, 'where he summoned Zebulun and Naphtali. Ten thousand men followed him, and Deborah also went with him.'),
  ('BSB', 'Judges', 7, 4, 11, 'Now Heber the Kenite had moved away from the Kenites, the descendants of Hobab the father-in-law of Moses, and had pitched his tent by the great tree of Zaanannim, which was near Kedesh.'),
  ('BSB', 'Judges', 7, 4, 12, 'When Sisera was told that Barak son of Abinoam had gone up Mount Tabor,'),
  ('BSB', 'Judges', 7, 4, 13, 'he summoned all nine hundred of his iron chariots and all the men with him, from Harosheth-hagoyim to the River Kishon.'),
  ('BSB', 'Judges', 7, 4, 14, 'Then Deborah said to Barak, “Arise, for this is the day that the LORD has delivered Sisera into your hand. Has not the LORD gone before you?” So Barak came down from Mount Tabor with ten thousand men following him.'),
  ('BSB', 'Judges', 7, 4, 15, 'And in front of him the LORD routed with the sword Sisera, all his charioteers, and all his army. Sisera abandoned his chariot and fled on foot.'),
  ('BSB', 'Judges', 7, 4, 16, 'Then Barak pursued the chariots and army as far as Harosheth-hagoyim, and the whole army of Sisera fell by the sword; not a single man was left.'),
  ('BSB', 'Judges', 7, 4, 17, 'Meanwhile, Sisera had fled on foot to the tent of Jael, the wife of Heber the Kenite, because there was peace between Jabin king of Hazor and the house of Heber the Kenite.'),
  ('BSB', 'Judges', 7, 4, 18, 'Jael went out to greet Sisera and said to him, “Come in, my lord. Come in with me. Do not be afraid.” So he entered her tent, and she covered him with a blanket.'),
  ('BSB', 'Judges', 7, 4, 19, 'Sisera said to her, “Please give me a little water to drink, for I am thirsty.” So she opened a container of milk, gave him a drink, and covered him again.'),
  ('BSB', 'Judges', 7, 4, 20, '“Stand at the entrance to the tent,” he said, “and if anyone comes and asks you, ‘Is there a man here?’ say, ‘No.’”'),
  ('BSB', 'Judges', 7, 4, 21, 'But as he lay sleeping from exhaustion, Heber’s wife Jael took a tent peg, grabbed a hammer, and went silently to Sisera. She drove the peg through his temple and into the ground, and he died.'),
  ('BSB', 'Judges', 7, 4, 22, 'When Barak arrived in pursuit of Sisera, Jael went out to greet him and said to him, “Come, and I will show you the man you are seeking.” So he went in with her, and there lay Sisera dead, with a tent peg through his temple.'),
  ('BSB', 'Judges', 7, 4, 23, 'On that day God subdued Jabin king of Canaan before the Israelites.'),
  ('BSB', 'Judges', 7, 4, 24, 'And the hand of the Israelites grew stronger and stronger against Jabin king of Canaan until they destroyed him.'),
  ('BSB', 'Judges', 7, 5, 1, 'On that day Deborah and Barak son of Abinoam sang this song:'),
  ('BSB', 'Judges', 7, 5, 2, '“When the princes take the lead in Israel, when the people volunteer, bless the LORD.'),
  ('BSB', 'Judges', 7, 5, 3, 'Listen, O kings! Give ear, O princes! I will sing to the LORD; I will sing praise to the LORD, the God of Israel.'),
  ('BSB', 'Judges', 7, 5, 4, 'O LORD, when You went out from Seir, when You marched from the land of Edom, the earth trembled, the heavens poured out rain, and the clouds poured down water.'),
  ('BSB', 'Judges', 7, 5, 5, 'The mountains quaked before the LORD, the One of Sinai, before the LORD, the God of Israel.'),
  ('BSB', 'Judges', 7, 5, 6, 'In the days of Shamgar son of Anath, in the days of Jael, the highways were deserted and the travelers took the byways.'),
  ('BSB', 'Judges', 7, 5, 7, 'Life in the villages ceased; it ended in Israel, until I, Deborah, arose, a mother in Israel.'),
  ('BSB', 'Judges', 7, 5, 8, 'When they chose new gods, then war came to their gates. Not a shield or spear was found among forty thousand in Israel.'),
  ('BSB', 'Judges', 7, 5, 9, 'My heart is with the princes of Israel, with the volunteers among the people. Bless the LORD!'),
  ('BSB', 'Judges', 7, 5, 10, 'You who ride white donkeys, who sit on saddle blankets, and you who travel the road, ponder'),
  ('BSB', 'Judges', 7, 5, 11, 'the voices of the singers at the watering places. There they shall recount the righteous acts of the LORD, the righteous deeds of His villagers in Israel. Then the people of the LORD went down to the gates:'),
  ('BSB', 'Judges', 7, 5, 12, '‘Awake, awake, O Deborah! Awake, awake, sing a song! Arise, O Barak, and take hold of your captives, O son of Abinoam!’'),
  ('BSB', 'Judges', 7, 5, 13, 'Then the survivors came down to the nobles; the people of the LORD came down to me against the mighty.'),
  ('BSB', 'Judges', 7, 5, 14, 'Some came from Ephraim, with their roots in Amalek; Benjamin came with your people after you. The commanders came down from Machir, the bearers of the marshal’s staff from Zebulun.'),
  ('BSB', 'Judges', 7, 5, 15, 'The princes of Issachar were with Deborah, and Issachar was with Barak, rushing into the valley at his heels. In the clans of Reuben there was great indecision.'),
  ('BSB', 'Judges', 7, 5, 16, 'Why did you sit among the sheepfolds to hear the whistling for the flocks? In the clans of Reuben there was great indecision.'),
  ('BSB', 'Judges', 7, 5, 17, 'Gilead remained beyond the Jordan. Dan, why did you linger by the ships? Asher stayed at the coast and remained in his harbors.'),
  ('BSB', 'Judges', 7, 5, 18, 'Zebulun was a people who risked their lives; Naphtali, too, on the heights of the battlefield.'),
  ('BSB', 'Judges', 7, 5, 19, 'Kings came and fought; then the kings of Canaan fought at Taanach by the waters of Megiddo, but they took no plunder of silver.'),
  ('BSB', 'Judges', 7, 5, 20, 'From the heavens the stars fought; from their courses they fought against Sisera.'),
  ('BSB', 'Judges', 7, 5, 21, 'The River Kishon swept them away, the ancient river, the River Kishon. March on, O my soul, in strength!'),
  ('BSB', 'Judges', 7, 5, 22, 'Then the hooves of horses thundered— the mad galloping of his stallions.'),
  ('BSB', 'Judges', 7, 5, 23, '‘Curse Meroz,’ says the angel of the LORD. ‘Bitterly curse her inhabitants; for they did not come to help the LORD, to help the LORD against the mighty.’'),
  ('BSB', 'Judges', 7, 5, 24, 'Most blessed among women is Jael, the wife of Heber the Kenite, most blessed of tent-dwelling women.'),
  ('BSB', 'Judges', 7, 5, 25, 'He asked for water, and she gave him milk. In a magnificent bowl she brought him curds.'),
  ('BSB', 'Judges', 7, 5, 26, 'She reached for the tent peg, her right hand for the workman’s hammer. She struck Sisera and crushed his skull; she shattered and pierced his temple.'),
  ('BSB', 'Judges', 7, 5, 27, 'At her feet he collapsed, he fell, there he lay still; at her feet he collapsed, he fell; where he collapsed, there he fell dead.'),
  ('BSB', 'Judges', 7, 5, 28, 'Sisera’s mother looked through the window; she peered through the lattice and lamented: ‘Why is his chariot so long in coming? What has delayed the clatter of his chariots?’'),
  ('BSB', 'Judges', 7, 5, 29, 'Her wisest ladies answer; indeed she keeps telling herself,'),
  ('BSB', 'Judges', 7, 5, 30, '‘Are they not finding and dividing the spoil— a girl or two for each warrior, a plunder of dyed garments for Sisera, the spoil of embroidered garments for the neck of the looter?’'),
  ('BSB', 'Judges', 7, 5, 31, 'So may all Your enemies perish, O LORD! But may those who love You shine like the sun at its brightest.” And the land had rest for forty years.'),
  ('BSB', 'Judges', 7, 6, 1, 'Again the Israelites did evil in the sight of the LORD; so He delivered them into the hand of Midian for seven years,'),
  ('BSB', 'Judges', 7, 6, 2, 'and the hand of Midian prevailed against Israel. Because of the Midianites, the Israelites prepared shelters for themselves in the mountains, caves, and strongholds.'),
  ('BSB', 'Judges', 7, 6, 3, 'Whenever the Israelites would plant their crops, the Midianites, Amalekites, and other people of the east would come up and invade them,'),
  ('BSB', 'Judges', 7, 6, 4, 'encamping against them as far as Gaza and destroying the produce of the land. They left Israel with no sustenance, neither sheep nor oxen nor donkeys.'),
  ('BSB', 'Judges', 7, 6, 5, 'For the Midianites came with their livestock and their tents like a great swarm of locusts. They and their camels were innumerable, and they entered the land to ravage it.'),
  ('BSB', 'Judges', 7, 6, 6, 'Israel was greatly impoverished by Midian, and the Israelites cried out to the LORD.'),
  ('BSB', 'Judges', 7, 6, 7, 'Now when the Israelites cried out to the LORD because of Midian,'),
  ('BSB', 'Judges', 7, 6, 8, 'He sent them a prophet, who told them, “This is what the LORD, the God of Israel, says: I brought you up out of Egypt, out of the house of slavery.'),
  ('BSB', 'Judges', 7, 6, 9, 'I delivered you out of the hands of Egypt and all your oppressors. I drove them out before you and gave you their land.'),
  ('BSB', 'Judges', 7, 6, 10, 'And I said to you: ‘I am the LORD your God. You must not fear the gods of the Amorites, in whose land you dwell.’ But you did not obey Me.”'),
  ('BSB', 'Judges', 7, 6, 11, 'Then the angel of the LORD came and sat down under the oak in Ophrah that belonged to Joash the Abiezrite, where his son Gideon was threshing wheat in a winepress to hide it from the Midianites.'),
  ('BSB', 'Judges', 7, 6, 12, 'And the angel of the LORD appeared to Gideon and said, “The LORD is with you, O mighty man of valor.”'),
  ('BSB', 'Judges', 7, 6, 13, '“Please, my Lord,” Gideon replied, “if the LORD is with us, why has all this happened to us? And where are all His wonders of which our fathers told us, saying, ‘Has not the LORD brought us up out of Egypt?’ But now the LORD has forsaken us and delivered us into the hand of Midian.”'),
  ('BSB', 'Judges', 7, 6, 14, 'The LORD turned to him and said, “Go in the strength you have and save Israel from the hand of Midian. Am I not sending you?”'),
  ('BSB', 'Judges', 7, 6, 15, '“Please, my Lord,” Gideon replied, “how can I save Israel? Indeed, my clan is the weakest in Manasseh, and I am the youngest in my father’s house.”'),
  ('BSB', 'Judges', 7, 6, 16, '“Surely I will be with you,” the LORD replied, “and you will strike down all the Midianites as one man.”'),
  ('BSB', 'Judges', 7, 6, 17, 'Gideon answered, “If I have found favor in Your sight, give me a sign that it is You speaking with me.'),
  ('BSB', 'Judges', 7, 6, 18, 'Please do not depart from this place until I return to You. Let me bring my offering and set it before You.” And the LORD said, “I will stay until you return.”'),
  ('BSB', 'Judges', 7, 6, 19, 'So Gideon went in and prepared a young goat and unleavened bread and an ephah of flour. He placed the meat in a basket and the broth in a pot and brought them out to present to Him under the oak.'),
  ('BSB', 'Judges', 7, 6, 20, 'And the angel of God said to him, “Take the meat and the unleavened bread, lay them on this rock, and pour out the broth.” And Gideon did so.'),
  ('BSB', 'Judges', 7, 6, 21, 'Then the angel of the LORD extended the tip of the staff that was in his hand and touched the meat and the unleavened bread. And fire flared from the rock and consumed the meat and the unleavened bread. Then the angel of the LORD vanished from his sight.'),
  ('BSB', 'Judges', 7, 6, 22, 'When Gideon realized that it was the angel of the LORD, he said, “Oh no, Lord GOD! I have seen the angel of the LORD face to face!”'),
  ('BSB', 'Judges', 7, 6, 23, 'But the LORD said to him, “Peace be with you. Do not be afraid, for you will not die.”'),
  ('BSB', 'Judges', 7, 6, 24, 'So Gideon built an altar to the LORD there and called it The LORD Is Peace. To this day it stands in Ophrah of the Abiezrites.'),
  ('BSB', 'Judges', 7, 6, 25, 'On that very night the LORD said to Gideon, “Take your father’s young bull and a second bull seven years old, tear down your father’s altar to Baal, and cut down the Asherah pole beside it.'),
  ('BSB', 'Judges', 7, 6, 26, 'Then build a proper altar to the LORD your God on the top of this stronghold. And with the wood of the Asherah pole you cut down, take the second bull and offer it as a burnt offering.”'),
  ('BSB', 'Judges', 7, 6, 27, 'So Gideon took ten of his servants and did as the LORD had told him. But because he was too afraid of his father’s household and the men of the city, he did it by night rather than in the daytime.'),
  ('BSB', 'Judges', 7, 6, 28, 'When the men of the city got up in the morning, there was Baal’s altar torn down, with the Asherah pole cut down beside it and the second bull offered up on the newly built altar.'),
  ('BSB', 'Judges', 7, 6, 29, '“Who did this?” they said to one another. And after they had investigated thoroughly, they were told, “Gideon son of Joash did it.”'),
  ('BSB', 'Judges', 7, 6, 30, 'Then the men of the city said to Joash, “Bring out your son. He must die, because he has torn down Baal’s altar and cut down the Asherah pole beside it.”'),
  ('BSB', 'Judges', 7, 6, 31, 'But Joash said to all who stood against him, “Are you contending for Baal? Are you trying to save him? Whoever pleads his case will be put to death by morning! If Baal is a god, let him contend for himself with the one who has torn down his altar.”'),
  ('BSB', 'Judges', 7, 6, 32, 'So on that day Gideon was called Jerubbaal, that is to say, “Let Baal contend with him,” because he had torn down Baal’s altar.'),
  ('BSB', 'Judges', 7, 6, 33, 'Then all the Midianites, Amalekites, and other people of the east gathered together, crossed over the Jordan, and camped in the Valley of Jezreel.'),
  ('BSB', 'Judges', 7, 6, 34, 'So the Spirit of the LORD came upon Gideon, who blew the ram’s horn and rallied the Abiezrites behind him.'),
  ('BSB', 'Judges', 7, 6, 35, 'Calling them to arms, Gideon sent messengers throughout Manasseh, as well as Asher, Zebulun, and Naphtali, so that they came up to meet him.'),
  ('BSB', 'Judges', 7, 6, 36, 'Then Gideon said to God, “If You are going to save Israel by my hand, as You have said,'),
  ('BSB', 'Judges', 7, 6, 37, 'then behold, I will place a fleece of wool on the threshing floor. If there is dew only on the fleece and all the ground is dry, then I will know that You are going to save Israel by my hand, as You have said.”'),
  ('BSB', 'Judges', 7, 6, 38, 'And that is what happened. When Gideon arose the next morning, he squeezed the fleece and wrung out the dew—a bowlful of water.'),
  ('BSB', 'Judges', 7, 6, 39, 'Then Gideon said to God, “Do not be angry with me; let me speak one more time. Please allow me one more test with the fleece. This time let it be dry, and the ground covered with dew.”'),
  ('BSB', 'Judges', 7, 6, 40, 'And that night God did so. Only the fleece was dry, and dew covered the ground.'),
  ('BSB', 'Judges', 7, 7, 1, 'Early in the morning Jerubbaal (that is, Gideon) and all the men with him camped beside the spring of Harod. And the camp of Midian was north of them in the valley near the hill of Moreh.'),
  ('BSB', 'Judges', 7, 7, 2, 'Then the LORD said to Gideon, “You have too many people for Me to deliver Midian into their hands, lest Israel glorify themselves over Me, saying, ‘My own hand has saved me.’'),
  ('BSB', 'Judges', 7, 7, 3, 'Now, therefore, proclaim in the hearing of the people: ‘Whoever is fearful and trembling may turn back and leave Mount Gilead.’” So twenty-two thousand of them turned back, but ten thousand remained.'),
  ('BSB', 'Judges', 7, 7, 4, 'Then the LORD said to Gideon, “There are still too many people. Take them down to the water, and I will sift them for you there. If I say to you, ‘This one shall go with you,’ he shall go. But if I say, ‘This one shall not go with you,’ he shall not go.”'),
  ('BSB', 'Judges', 7, 7, 5, 'So Gideon brought the people down to the water, and the LORD said to him, “Separate those who lap the water with their tongues like a dog from those who kneel to drink.”'),
  ('BSB', 'Judges', 7, 7, 6, 'And the number of those who lapped the water with their hands to their mouths was three hundred men; all the others knelt to drink.'),
  ('BSB', 'Judges', 7, 7, 7, 'Then the LORD said to Gideon, “With the three hundred men who lapped the water I will save you and deliver the Midianites into your hand. But all the others are to go home.”'),
  ('BSB', 'Judges', 7, 7, 8, 'So Gideon sent the rest of the Israelites to their tents but kept the three hundred men, who took charge of the provisions and rams’ horns of the others. And the camp of Midian lay below him in the valley.'),
  ('BSB', 'Judges', 7, 7, 9, 'That night the LORD said to Gideon, “Get up and go down against the camp, for I have delivered it into your hand.'),
  ('BSB', 'Judges', 7, 7, 10, 'But if you are afraid to do so, then go down to the camp with your servant Purah'),
  ('BSB', 'Judges', 7, 7, 11, 'and listen to what they are saying. Then your hands will be strengthened to attack the camp.” So he went with Purah his servant to the outposts where armed men were guarding the camp.'),
  ('BSB', 'Judges', 7, 7, 12, 'Now the Midianites, Amalekites, and all the other people of the east had settled in the valley like a swarm of locusts, and their camels were as countless as the sand on the seashore.'),
  ('BSB', 'Judges', 7, 7, 13, 'And as Gideon arrived, a man was telling his friend about a dream. “Behold, I had a dream,” he said, “and I saw a loaf of barley bread come tumbling into the Midianite camp. It struck the tent so hard that the tent overturned and collapsed.”'),
  ('BSB', 'Judges', 7, 7, 14, 'His friend replied: “This is nothing less than the sword of Gideon son of Joash, the Israelite. God has delivered Midian and the whole camp into his hand.”'),
  ('BSB', 'Judges', 7, 7, 15, 'When Gideon heard the dream and its interpretation, he bowed in worship. He returned to the camp of Israel and said, “Get up, for the LORD has delivered the camp of Midian into your hand.”'),
  ('BSB', 'Judges', 7, 7, 16, 'And he divided the three hundred men into three companies and gave each man a ram’s horn in one hand and a large jar in the other, containing a torch.'),
  ('BSB', 'Judges', 7, 7, 17, '“Watch me and do as I do,” Gideon said. “When I come to the outskirts of the camp, do exactly as I do.'),
  ('BSB', 'Judges', 7, 7, 18, 'When I and all who are with me blow our horns, then you are also to blow your horns from all around the camp and shout, ‘For the LORD and for Gideon!’”'),
  ('BSB', 'Judges', 7, 7, 19, 'Gideon and the hundred men with him reached the outskirts of the camp at the beginning of the middle watch, just after the changing of the guard. They blew their horns and broke the jars that were in their hands.'),
  ('BSB', 'Judges', 7, 7, 20, 'The three companies blew their horns and shattered their jars. Holding the torches in their left hands and the horns in their right hands, they shouted, “A sword for the LORD and for Gideon!”'),
  ('BSB', 'Judges', 7, 7, 21, 'Each Israelite took his position around the camp, and the entire Midianite army fled, crying out as they ran.'),
  ('BSB', 'Judges', 7, 7, 22, 'And when the three hundred rams’ horns sounded, the LORD set all the men in the camp against one another with their swords. The army fled to Beth-shittah toward Zererah as far as the border of Abel-meholah near Tabbath.'),
  ('BSB', 'Judges', 7, 7, 23, 'Then the men of Israel were called out from Naphtali, Asher, and all Manasseh, and they pursued the Midianites.'),
  ('BSB', 'Judges', 7, 7, 24, 'Gideon sent messengers throughout the hill country of Ephraim to say, “Come down against the Midianites and seize the waters of the Jordan ahead of them as far as Beth-barah.” So all the men of Ephraim were called out, and they captured the waters of the Jordan as far as Beth-barah.'),
  ('BSB', 'Judges', 7, 7, 25, 'They also captured Oreb and Zeeb, the two princes of Midian; and they killed Oreb at the rock of Oreb and Zeeb at the winepress of Zeeb. So they pursued the Midianites and brought the heads of Oreb and Zeeb to Gideon on the other side of the Jordan.'),
  ('BSB', 'Judges', 7, 8, 1, 'Then the men of Ephraim said to Gideon, “Why have you done this to us? Why did you fail to call us when you went to fight against Midian?” And they contended with him violently.'),
  ('BSB', 'Judges', 7, 8, 2, 'But Gideon answered them, “Now what have I accomplished compared to you? Are not the gleanings of Ephraim better than the grape harvest of Abiezer?'),
  ('BSB', 'Judges', 7, 8, 3, 'God has delivered Oreb and Zeeb, the two princes of Midian, into your hand. What was I able to do compared to you?” When he had said this, their anger against him subsided.'),
  ('BSB', 'Judges', 7, 8, 4, 'Then Gideon and his three hundred men came to the Jordan and crossed it, exhausted yet still in pursuit.'),
  ('BSB', 'Judges', 7, 8, 5, 'So Gideon said to the men of Succoth, “Please give my troops some bread, for they are exhausted, and I am still pursuing Zebah and Zalmunna, the kings of Midian.”'),
  ('BSB', 'Judges', 7, 8, 6, 'But the leaders of Succoth asked, “Are the hands of Zebah and Zalmunna already in your possession, that we should give bread to your army?”'),
  ('BSB', 'Judges', 7, 8, 7, '“Very well,” Gideon replied, “when the LORD has delivered Zebah and Zalmunna into my hand, I will tear your flesh with the thorns and briers of the wilderness!”'),
  ('BSB', 'Judges', 7, 8, 8, 'From there he went up to Penuel and asked the same from them, but the men of Penuel gave the same response as the men of Succoth.'),
  ('BSB', 'Judges', 7, 8, 9, 'So Gideon told the men of Penuel, “When I return in triumph, I will tear down this tower!”'),
  ('BSB', 'Judges', 7, 8, 10, 'Now Zebah and Zalmunna were in Karkor with their army of about fifteen thousand men—all that were left of the armies of the people of the east. A hundred and twenty thousand swordsmen had already fallen.'),
  ('BSB', 'Judges', 7, 8, 11, 'And Gideon went up by way of the caravan route east of Nobah and Jogbehah, and he attacked their army, taking them by surprise.'),
  ('BSB', 'Judges', 7, 8, 12, 'When Zebah and Zalmunna fled, Gideon pursued and captured these two kings of Midian, routing their entire army.'),
  ('BSB', 'Judges', 7, 8, 13, 'After this, Gideon son of Joash returned from the battle along the Ascent of Heres.'),
  ('BSB', 'Judges', 7, 8, 14, 'There he captured a young man of Succoth and interrogated him. The young man wrote down for him the names of the seventy-seven leaders and elders of Succoth.'),
  ('BSB', 'Judges', 7, 8, 15, 'And Gideon went to the men of Succoth and said, “Here are Zebah and Zalmunna, about whom you taunted me, saying, ‘Are the hands of Zebah and Zalmunna already in your possession, that we should give bread to your weary men?’”'),
  ('BSB', 'Judges', 7, 8, 16, 'Then he took the elders of the city, and using the thorns and briers of the wilderness, he disciplined the men of Succoth.'),
  ('BSB', 'Judges', 7, 8, 17, 'He also pulled down the tower of Penuel and killed the men of the city.'),
  ('BSB', 'Judges', 7, 8, 18, 'Next, Gideon asked Zebah and Zalmunna, “What kind of men did you kill at Tabor?” “Men like you,” they answered, “each one resembling the son of a king.”'),
  ('BSB', 'Judges', 7, 8, 19, '“They were my brothers,” Gideon replied, “the sons of my mother! As surely as the LORD lives, if you had let them live, I would not kill you.”'),
  ('BSB', 'Judges', 7, 8, 20, 'So he said to Jether, his firstborn, “Get up and kill them.” But the young man did not draw his sword; he was fearful because he was still a youth.'),
  ('BSB', 'Judges', 7, 8, 21, 'Then Zebah and Zalmunna said, “Get up and kill us yourself, for as the man is, so is his strength.” So Gideon got up and killed Zebah and Zalmunna, and he took the crescent ornaments from the necks of their camels.'),
  ('BSB', 'Judges', 7, 8, 22, 'Then the Israelites said to Gideon, “Rule over us—you and your son and grandson—for you have saved us from the hand of Midian.”'),
  ('BSB', 'Judges', 7, 8, 23, 'But Gideon replied, “I will not rule over you, nor will my son. The LORD shall rule over you.”'),
  ('BSB', 'Judges', 7, 8, 24, 'Then he added, “Let me make a request of you, that each of you give me an earring from his plunder.” (For the enemies had gold earrings because they were Ishmaelites.)'),
  ('BSB', 'Judges', 7, 8, 25, '“We will give them gladly,” they replied. So they spread out a garment, and each man threw an earring from his plunder onto it.'),
  ('BSB', 'Judges', 7, 8, 26, 'The weight of the gold earrings he had requested was 1,700 shekels, in addition to the crescent ornaments, the pendants, the purple garments of the kings of Midian, and the chains from the necks of their camels.'),
  ('BSB', 'Judges', 7, 8, 27, 'From all this Gideon made an ephod, which he placed in Ophrah, his hometown. But soon all Israel prostituted themselves by worshiping it there, and it became a snare to Gideon and his household.'),
  ('BSB', 'Judges', 7, 8, 28, 'In this way Midian was subdued before the Israelites and did not raise its head again. So the land had rest for forty years in the days of Gideon,'),
  ('BSB', 'Judges', 7, 8, 29, 'and he—Jerubbaal son of Joash—returned home and settled down.'),
  ('BSB', 'Judges', 7, 8, 30, 'Gideon had seventy sons of his own, since he had many wives.'),
  ('BSB', 'Judges', 7, 8, 31, 'His concubine, who dwelt in Shechem, also bore him a son, and he named him Abimelech.'),
  ('BSB', 'Judges', 7, 8, 32, 'Later, Gideon son of Joash died at a ripe old age and was buried in the tomb of his father Joash in Ophrah of the Abiezrites.'),
  ('BSB', 'Judges', 7, 8, 33, 'And as soon as Gideon was dead, the Israelites turned and prostituted themselves with the Baals, and they set up Baal-berith as their god.'),
  ('BSB', 'Judges', 7, 8, 34, 'The Israelites failed to remember the LORD their God who had delivered them from the hands of all their enemies on every side.'),
  ('BSB', 'Judges', 7, 8, 35, 'They did not show kindness to the house of Jerubbaal (that is, Gideon) for all the good things he had done for Israel.'),
  ('BSB', 'Judges', 7, 9, 1, 'Now Abimelech son of Jerubbaal went to his mother’s brothers at Shechem and said to them and to all the clan of his mother,'),
  ('BSB', 'Judges', 7, 9, 2, '“Please ask all the leaders of Shechem, ‘Is it better for you that seventy men, all the sons of Jerubbaal, rule over you, or just one man?’ Remember that I am your own flesh and blood.”'),
  ('BSB', 'Judges', 7, 9, 3, 'And when his mother’s brothers spoke all these words about him in the presence of all the leaders of Shechem, their hearts were inclined to follow Abimelech, for they said, “He is our brother.”'),
  ('BSB', 'Judges', 7, 9, 4, 'So they gave him seventy shekels of silver from the temple of Baal-berith, with which Abimelech hired some worthless and reckless men to follow him.'),
  ('BSB', 'Judges', 7, 9, 5, 'He went to his father’s house in Ophrah, and on one stone murdered his seventy brothers, the sons of Jerubbaal. But Jotham, the youngest son of Jerubbaal, survived, because he hid himself.'),
  ('BSB', 'Judges', 7, 9, 6, 'Then all the leaders of Shechem and Beth-millo gathered beside the oak at the pillar in Shechem and proceeded to make Abimelech their king.'),
  ('BSB', 'Judges', 7, 9, 7, 'When this was reported to Jotham, he climbed to the top of Mount Gerizim, raised his voice, and cried out: “Listen to me, O leaders of Shechem, and may God listen to you.'),
  ('BSB', 'Judges', 7, 9, 8, 'One day the trees set out to anoint a king for themselves. They said to the olive tree, ‘Reign over us.’'),
  ('BSB', 'Judges', 7, 9, 9, 'But the olive tree replied, ‘Should I stop giving my oil that honors both God and man, to hold sway over the trees?’'),
  ('BSB', 'Judges', 7, 9, 10, 'Then the trees said to the fig tree, ‘Come and reign over us.’'),
  ('BSB', 'Judges', 7, 9, 11, 'But the fig tree replied, ‘Should I stop giving my sweetness and my good fruit, to hold sway over the trees?’'),
  ('BSB', 'Judges', 7, 9, 12, 'Then the trees said to the grapevine, ‘Come and reign over us.’'),
  ('BSB', 'Judges', 7, 9, 13, 'But the grapevine replied, ‘Should I stop giving my wine that cheers both God and man, to hold sway over the trees?’'),
  ('BSB', 'Judges', 7, 9, 14, 'Finally all the trees said to the thornbush, ‘Come and reign over us.’'),
  ('BSB', 'Judges', 7, 9, 15, 'But the thornbush replied, ‘If you really are anointing me as king over you, come and find refuge in my shade. But if not, may fire come out of the thornbush and consume the cedars of Lebanon.’'),
  ('BSB', 'Judges', 7, 9, 16, 'Now if you have acted faithfully and honestly in making Abimelech king, if you have done well by Jerubbaal and his family, and if you have done to him as he deserves—'),
  ('BSB', 'Judges', 7, 9, 17, 'for my father fought for you and risked his life to deliver you from the hand of Midian,'),
  ('BSB', 'Judges', 7, 9, 18, 'but you have risen up against my father’s house this day and killed his seventy sons on a single stone, and you have made Abimelech, the son of his maidservant, king over the leaders of Shechem because he is your brother—'),
  ('BSB', 'Judges', 7, 9, 19, 'if you have acted faithfully and honestly toward Jerubbaal and his house this day, then may you rejoice in Abimelech, and he in you.'),
  ('BSB', 'Judges', 7, 9, 20, 'But if not, may fire come from Abimelech and consume the leaders of Shechem and Beth-millo, and may fire come from the leaders of Shechem and Beth-millo and consume Abimelech.”'),
  ('BSB', 'Judges', 7, 9, 21, 'Then Jotham ran away, escaping to Beer, and he lived there for fear of his brother Abimelech.'),
  ('BSB', 'Judges', 7, 9, 22, 'After Abimelech had reigned over Israel for three years,'),
  ('BSB', 'Judges', 7, 9, 23, 'God sent a spirit of animosity between Abimelech and the leaders of Shechem and caused them to treat Abimelech deceitfully,'),
  ('BSB', 'Judges', 7, 9, 24, 'in order that the crime against the seventy sons of Jerubbaal might come to justice and their blood be avenged on their brother Abimelech and on the leaders of Shechem, who had helped him murder his brothers.'),
  ('BSB', 'Judges', 7, 9, 25, 'The leaders of Shechem set up an ambush against Abimelech on the hilltops, and they robbed all who passed by them on the road. So this was reported to Abimelech.'),
  ('BSB', 'Judges', 7, 9, 26, 'Meanwhile, Gaal son of Ebed came with his brothers and crossed into Shechem, and the leaders of Shechem put their confidence in him.'),
  ('BSB', 'Judges', 7, 9, 27, 'And after they had gone out into the fields, gathered grapes from their vineyards, and trodden them, they held a festival and went into the house of their god; and as they ate and drank, they cursed Abimelech.'),
  ('BSB', 'Judges', 7, 9, 28, 'Then Gaal son of Ebed said, “Who is Abimelech, and who is Shechem, that we should serve him? Is he not the son of Jerubbaal, and is not Zebul his officer? You are to serve the men of Hamor, the father of Shechem. Why should we serve Abimelech?'),
  ('BSB', 'Judges', 7, 9, 29, 'If only this people were under my authority, I would remove Abimelech; I would say to him, ‘Muster your army and come out!’”'),
  ('BSB', 'Judges', 7, 9, 30, 'When Zebul the governor of the city heard the words of Gaal son of Ebed, he burned with anger.'),
  ('BSB', 'Judges', 7, 9, 31, 'So he covertly sent messengers to Abimelech to say, “Look, Gaal son of Ebed and his brothers have come to Shechem and are stirring up the city against you.'),
  ('BSB', 'Judges', 7, 9, 32, 'Now then, tonight you and the people with you are to come and lie in wait in the fields.'),
  ('BSB', 'Judges', 7, 9, 33, 'And in the morning at sunrise, get up and advance against the city. When Gaal and his men come out against you, do to them whatever you are able.”'),
  ('BSB', 'Judges', 7, 9, 34, 'So Abimelech and all his troops set out by night and lay in wait against Shechem in four companies.'),
  ('BSB', 'Judges', 7, 9, 35, 'Now Gaal son of Ebed went out and stood at the entrance of the city gate just as Abimelech and his men came out from their hiding places.'),
  ('BSB', 'Judges', 7, 9, 36, 'When Gaal saw the people, he said to Zebul, “Look, people are coming down from the mountains!” But Zebul replied, “The shadows of the mountains look like men to you.”'),
  ('BSB', 'Judges', 7, 9, 37, 'Then Gaal spoke up again, “Look, people are coming down from the center of the land, and one company is coming by way of the Diviners’ Oak.”'),
  ('BSB', 'Judges', 7, 9, 38, '“Where is your gloating now?” Zebul replied. “You said, ‘Who is Abimelech that we should serve him?’ Are these not the people you ridiculed? Go out now and fight them!”'),
  ('BSB', 'Judges', 7, 9, 39, 'So Gaal went out before the leaders of Shechem and fought against Abimelech,'),
  ('BSB', 'Judges', 7, 9, 40, 'but Abimelech pursued him, and Gaal fled before him. And many Shechemites fell wounded all the way to the entrance of the gate.'),
  ('BSB', 'Judges', 7, 9, 41, 'Abimelech stayed in Arumah, and Zebul drove Gaal and his brothers out of Shechem.'),
  ('BSB', 'Judges', 7, 9, 42, 'The next day the people of Shechem went out into the fields, and this was reported to Abimelech.'),
  ('BSB', 'Judges', 7, 9, 43, 'So he took his men, divided them into three companies, and lay in wait in the fields. When he saw the people coming out of the city, he rose up against them and attacked them.'),
  ('BSB', 'Judges', 7, 9, 44, 'Then Abimelech and the companies with him rushed forward and took their stand at the entrance of the city gate. The other two companies rushed against all who were in the fields and struck them down.'),
  ('BSB', 'Judges', 7, 9, 45, 'And all that day Abimelech fought against the city until he had captured it and killed its people. Then he demolished the city and sowed it with salt.');
insert into control_room_bible (version, book, book_num, chapter, verse, text) values
  ('BSB', 'Judges', 7, 9, 46, 'On hearing of this, all the leaders in the tower of Shechem entered the inner chamber of the temple of El-berith.'),
  ('BSB', 'Judges', 7, 9, 47, 'And when Abimelech was told that all the leaders in the tower of Shechem were gathered there,'),
  ('BSB', 'Judges', 7, 9, 48, 'he and all his men went up to Mount Zalmon. Abimelech took his axe in his hand and cut a branch from the trees, which he lifted to his shoulder, saying to his men, “Hurry and do what you have seen me do.”'),
  ('BSB', 'Judges', 7, 9, 49, 'So each man also cut his own branch and followed Abimelech. Then they piled the branches against the inner chamber and set it on fire above them, killing everyone in the tower of Shechem, about a thousand men and women.'),
  ('BSB', 'Judges', 7, 9, 50, 'Then Abimelech went to Thebez, encamped against it, and captured it.'),
  ('BSB', 'Judges', 7, 9, 51, 'But there was a strong tower inside the city, and all the men, women, and leaders of the city fled there. They locked themselves in and went up to the roof of the tower.'),
  ('BSB', 'Judges', 7, 9, 52, 'When Abimelech came to attack the tower, he approached its entrance to set it on fire.'),
  ('BSB', 'Judges', 7, 9, 53, 'But a woman dropped an upper millstone on Abimelech’s head, crushing his skull.'),
  ('BSB', 'Judges', 7, 9, 54, 'He quickly called his armor-bearer, saying, “Draw your sword and kill me, lest they say of me, ‘A woman killed him.’” So Abimelech’s armor-bearer ran his sword through him, and he died.'),
  ('BSB', 'Judges', 7, 9, 55, 'And when the Israelites saw that Abimelech was dead, they all went home.'),
  ('BSB', 'Judges', 7, 9, 56, 'In this way God repaid the wickedness that Abimelech had done to his father in murdering his seventy brothers.'),
  ('BSB', 'Judges', 7, 9, 57, 'And God also brought all the wickedness of the men of Shechem back upon their own heads. So the curse of Jotham son of Jerubbaal came upon them.'),
  ('BSB', 'Judges', 7, 10, 1, 'After the time of Abimelech, a man of Issachar, Tola son of Puah, the son of Dodo, rose up to save Israel. He lived in Shamir, in the hill country of Ephraim.'),
  ('BSB', 'Judges', 7, 10, 2, 'Tola judged Israel twenty-three years, and when he died, he was buried in Shamir.'),
  ('BSB', 'Judges', 7, 10, 3, 'Tola was followed by Jair the Gileadite, who judged Israel twenty-two years.'),
  ('BSB', 'Judges', 7, 10, 4, 'He had thirty sons who rode on thirty donkeys. And they had thirty towns in the land of Gilead, which to this day are called Havvoth-jair.'),
  ('BSB', 'Judges', 7, 10, 5, 'When Jair died, he was buried in Kamon.'),
  ('BSB', 'Judges', 7, 10, 6, 'And again the Israelites did evil in the sight of the LORD. They served the Baals, the Ashtoreths, the gods of Aram, Sidon, and Moab, and the gods of the Ammonites and Philistines. Thus they forsook the LORD and did not serve Him.'),
  ('BSB', 'Judges', 7, 10, 7, 'So the anger of the LORD burned against Israel, and He sold them into the hands of the Philistines and Ammonites,'),
  ('BSB', 'Judges', 7, 10, 8, 'who that very year harassed and oppressed the Israelites, and did so for eighteen years to all the Israelites on the other side of the Jordan in Gilead, the land of the Amorites.'),
  ('BSB', 'Judges', 7, 10, 9, 'The Ammonites also crossed the Jordan to fight against Judah, Benjamin, and the house of Ephraim, and Israel was in deep distress.'),
  ('BSB', 'Judges', 7, 10, 10, 'Then the Israelites cried out to the LORD, saying, “We have sinned against You, for we have indeed forsaken our God and served the Baals.”'),
  ('BSB', 'Judges', 7, 10, 11, 'The LORD replied, “When the Egyptians, Amorites, Ammonites, Philistines,'),
  ('BSB', 'Judges', 7, 10, 12, 'Sidonians, Amalekites, and Maonites oppressed you and you cried out to Me, did I not save you from their hands?'),
  ('BSB', 'Judges', 7, 10, 13, 'But you have forsaken Me and served other gods, so I will no longer save you.'),
  ('BSB', 'Judges', 7, 10, 14, 'Go and cry out to the gods you have chosen. Let them save you in your time of trouble.”'),
  ('BSB', 'Judges', 7, 10, 15, '“We have sinned,” the Israelites said to the LORD. “Deal with us as You see fit; but please deliver us today!”'),
  ('BSB', 'Judges', 7, 10, 16, 'So they put away the foreign gods from among them and served the LORD, and He could no longer bear the misery of Israel.'),
  ('BSB', 'Judges', 7, 10, 17, 'Then the Ammonites were called to arms and camped in Gilead, and the Israelites assembled and camped at Mizpah.'),
  ('BSB', 'Judges', 7, 10, 18, 'And the rulers of Gilead said to one another, “Whoever will launch the attack against the Ammonites will be the head of all who live in Gilead.”'),
  ('BSB', 'Judges', 7, 11, 1, 'Now Jephthah the Gileadite was a mighty man of valor; he was the son of a prostitute, and Gilead was his father.'),
  ('BSB', 'Judges', 7, 11, 2, 'And Gilead’s wife bore him sons who grew up, drove Jephthah out, and said to him, “You shall have no inheritance in our father’s house, because you are the son of another woman.”'),
  ('BSB', 'Judges', 7, 11, 3, 'So Jephthah fled from his brothers and settled in the land of Tob, where worthless men gathered around him and traveled with him.'),
  ('BSB', 'Judges', 7, 11, 4, 'Some time later, when the Ammonites fought against Israel'),
  ('BSB', 'Judges', 7, 11, 5, 'and made war with them, the elders of Gilead went to get Jephthah from the land of Tob.'),
  ('BSB', 'Judges', 7, 11, 6, '“Come,” they said, “be our commander, so that we can fight against the Ammonites.”'),
  ('BSB', 'Judges', 7, 11, 7, 'Jephthah replied to the elders of Gilead, “Did you not hate me and expel me from my father’s house? Why then have you come to me now, when you are in distress?”'),
  ('BSB', 'Judges', 7, 11, 8, 'They answered Jephthah, “This is why we now turn to you, that you may go with us, fight the Ammonites, and become leader over all of us who live in Gilead.”'),
  ('BSB', 'Judges', 7, 11, 9, 'But Jephthah asked them, “If you take me back to fight the Ammonites and the LORD gives them to me, will I really be your leader?”'),
  ('BSB', 'Judges', 7, 11, 10, 'And the elders of Gilead said to Jephthah, “The LORD is our witness if we do not do as you say.”'),
  ('BSB', 'Judges', 7, 11, 11, 'So Jephthah went with the elders of Gilead, and the people made him their leader and commander. And Jephthah repeated all his terms in the presence of the LORD at Mizpah.'),
  ('BSB', 'Judges', 7, 11, 12, 'Then Jephthah sent messengers to the king of the Ammonites, saying, “What do you have against me that you have come to fight against my land?”'),
  ('BSB', 'Judges', 7, 11, 13, 'The king of the Ammonites answered Jephthah’s messengers, “When Israel came up out of Egypt, they seized my land, from the Arnon to the Jabbok and all the way to the Jordan. Now, therefore, restore it peaceably.”'),
  ('BSB', 'Judges', 7, 11, 14, 'Jephthah again sent messengers to the king of the Ammonites'),
  ('BSB', 'Judges', 7, 11, 15, 'to tell him, “This is what Jephthah says: Israel did not take away the land of Moab or of the Ammonites.'),
  ('BSB', 'Judges', 7, 11, 16, 'But when Israel came up out of Egypt, they traveled through the wilderness to the Red Sea and came to Kadesh.'),
  ('BSB', 'Judges', 7, 11, 17, 'Then Israel sent messengers to the king of Edom, saying, ‘Please let us pass through your land,’ but the king of Edom would not listen. They also sent messengers to the king of Moab, but he would not consent. So Israel stayed in Kadesh.'),
  ('BSB', 'Judges', 7, 11, 18, 'Then Israel traveled through the wilderness and bypassed the lands of Edom and Moab. They came to the east side of the land of Moab and camped on the other side of the Arnon. But they did not enter the territory of Moab, since the Arnon was its border.'),
  ('BSB', 'Judges', 7, 11, 19, 'And Israel sent messengers to Sihon king of the Amorites, who ruled in Heshbon, and said to him, ‘Please let us pass through your land into our own place.’'),
  ('BSB', 'Judges', 7, 11, 20, 'But Sihon would not trust Israel to pass through his territory. So he gathered all his people, encamped in Jahaz, and fought with Israel.'),
  ('BSB', 'Judges', 7, 11, 21, 'Then the LORD, the God of Israel, delivered Sihon and all his people into the hand of Israel, who defeated them. So Israel took possession of all the land of the Amorites who inhabited that country,'),
  ('BSB', 'Judges', 7, 11, 22, 'seizing all the land from the Arnon to the Jabbok and from the wilderness to the Jordan.'),
  ('BSB', 'Judges', 7, 11, 23, 'Now since the LORD, the God of Israel, has driven out the Amorites from before His people Israel, should you now possess it?'),
  ('BSB', 'Judges', 7, 11, 24, 'Do you not possess whatever your god Chemosh grants you? So also, we possess whatever the LORD our God has granted us.'),
  ('BSB', 'Judges', 7, 11, 25, 'Are you now so much better than Balak son of Zippor, king of Moab? Did he ever contend with Israel or fight against them?'),
  ('BSB', 'Judges', 7, 11, 26, 'For three hundred years Israel has lived in Heshbon, Aroer, and their villages, as well as all the cities along the banks of the Arnon. Why did you not take them back during that time?'),
  ('BSB', 'Judges', 7, 11, 27, 'I have not sinned against you, but you have done me wrong by waging war against me. May the LORD, the Judge, decide today between the Israelites and the Ammonites.”'),
  ('BSB', 'Judges', 7, 11, 28, 'But the king of the Ammonites paid no heed to the message Jephthah sent him.'),
  ('BSB', 'Judges', 7, 11, 29, 'Then the Spirit of the LORD came upon Jephthah, and he passed through Gilead and Manasseh, then through Mizpah of Gilead. And from there he advanced against the Ammonites.'),
  ('BSB', 'Judges', 7, 11, 30, 'Jephthah made this vow to the LORD: “If indeed You will deliver the Ammonites into my hand,'),
  ('BSB', 'Judges', 7, 11, 31, 'then whatever comes out the door of my house to greet me on my triumphant return from the Ammonites will belong to the LORD, and I will offer it up as a burnt offering.”'),
  ('BSB', 'Judges', 7, 11, 32, 'So Jephthah crossed over to the Ammonites to fight against them, and the LORD delivered them into his hand.'),
  ('BSB', 'Judges', 7, 11, 33, 'With a great blow he devastated twenty cities from Aroer to the vicinity of Minnith, as far as Abel-keramim. So the Ammonites were subdued before the Israelites.'),
  ('BSB', 'Judges', 7, 11, 34, 'And when Jephthah returned home to Mizpah, there was his daughter coming out to meet him with tambourines and dancing! She was his only child; he had no son or daughter besides her.'),
  ('BSB', 'Judges', 7, 11, 35, 'As soon as Jephthah saw her, he tore his clothes and said, “No! Not my daughter! You have brought me to my knees! You have brought great misery upon me, for I have given my word to the LORD and cannot take it back.”'),
  ('BSB', 'Judges', 7, 11, 36, '“My father,” she replied, “you have given your word to the LORD. Do to me as you have said, for the LORD has avenged you of your enemies, the Ammonites.”'),
  ('BSB', 'Judges', 7, 11, 37, 'She also said to her father, “Let me do this one thing: Let me wander for two months through the mountains with my friends and mourn my virginity.”'),
  ('BSB', 'Judges', 7, 11, 38, '“Go,” he said. And he sent her away for two months. So she left with her friends and mourned her virginity upon the mountains.'),
  ('BSB', 'Judges', 7, 11, 39, 'After two months, she returned to her father, and he did to her as he had vowed. And she had never had relations with a man. So it has become a custom in Israel'),
  ('BSB', 'Judges', 7, 11, 40, 'that each year the young women of Israel go out for four days to lament the daughter of Jephthah the Gileadite.'),
  ('BSB', 'Judges', 7, 12, 1, 'Then the men of Ephraim assembled and crossed the Jordan to Zaphon. They said to Jephthah, “Why have you crossed over to fight the Ammonites without calling us to go with you? We will burn your house down with you inside!”'),
  ('BSB', 'Judges', 7, 12, 2, 'But Jephthah replied, “My people and I had a serious conflict with the Ammonites, and when I called, you did not save me out of their hands.'),
  ('BSB', 'Judges', 7, 12, 3, 'When I saw that you would not save me, I risked my life and crossed over to the Ammonites, and the LORD delivered them into my hand. Why then have you come today to fight against me?”'),
  ('BSB', 'Judges', 7, 12, 4, 'Jephthah then gathered all the men of Gilead and fought against Ephraim. And the men of Gilead struck them down because the Ephraimites had said, “You Gileadites are fugitives in Ephraim, living in the territories of Ephraim and Manasseh.”'),
  ('BSB', 'Judges', 7, 12, 5, 'The Gileadites captured the fords of the Jordan leading to Ephraim, and whenever a fugitive from Ephraim would say, “Let me cross over,” the Gileadites would ask him, “Are you an Ephraimite?” If he answered, “No,”'),
  ('BSB', 'Judges', 7, 12, 6, 'they told him, “Please say Shibboleth.” If he said, “Sibboleth,” because he could not pronounce it correctly, they seized him and killed him at the fords of the Jordan. So at that time 42,000 Ephraimites were killed.'),
  ('BSB', 'Judges', 7, 12, 7, 'Jephthah judged Israel six years, and when he died, he was buried in one of the cities of Gilead.'),
  ('BSB', 'Judges', 7, 12, 8, 'After Jephthah, Ibzan of Bethlehem judged Israel.'),
  ('BSB', 'Judges', 7, 12, 9, 'He had thirty sons, as well as thirty daughters whom he gave in marriage to men outside his clan; and for his sons he brought back thirty wives from elsewhere. Ibzan judged Israel seven years.'),
  ('BSB', 'Judges', 7, 12, 10, 'Then Ibzan died, and he was buried in Bethlehem.'),
  ('BSB', 'Judges', 7, 12, 11, 'After Ibzan, Elon the Zebulunite judged Israel ten years.'),
  ('BSB', 'Judges', 7, 12, 12, 'Then Elon the Zebulunite died, and he was buried in Aijalon in the land of Zebulun.'),
  ('BSB', 'Judges', 7, 12, 13, 'After Elon, Abdon son of Hillel, from Pirathon, judged Israel.'),
  ('BSB', 'Judges', 7, 12, 14, 'He had forty sons and thirty grandsons, who rode on seventy donkeys. And he judged Israel eight years.'),
  ('BSB', 'Judges', 7, 12, 15, 'Then Abdon son of Hillel, from Pirathon, died, and he was buried at Pirathon in Ephraim, in the hill country of the Amalekites.'),
  ('BSB', 'Judges', 7, 13, 1, 'Again the Israelites did evil in the sight of the LORD, so He delivered them into the hand of the Philistines for forty years.'),
  ('BSB', 'Judges', 7, 13, 2, 'Now there was a man from Zorah named Manoah, from the clan of the Danites, whose wife was barren and had no children.'),
  ('BSB', 'Judges', 7, 13, 3, 'The angel of the LORD appeared to the woman and said to her, “It is true that you are barren and have no children; but you will conceive and give birth to a son.'),
  ('BSB', 'Judges', 7, 13, 4, 'Now please be careful not to drink wine or strong drink, and not to eat anything unclean.'),
  ('BSB', 'Judges', 7, 13, 5, 'For behold, you will conceive and give birth to a son. And no razor shall come over his head, because the boy will be a Nazirite to God from the womb, and he will begin the deliverance of Israel from the hand of the Philistines.”'),
  ('BSB', 'Judges', 7, 13, 6, 'So the woman went and told her husband, “A man of God came to me. His appearance was like the angel of God, exceedingly awesome. I did not ask him where he came from, and he did not tell me his name.'),
  ('BSB', 'Judges', 7, 13, 7, 'But he said to me, ‘Behold, you will conceive and give birth to a son. Now, therefore, do not drink wine or strong drink, and do not eat anything unclean, because the boy will be a Nazirite to God from the womb until the day of his death.’”'),
  ('BSB', 'Judges', 7, 13, 8, 'Then Manoah prayed to the LORD, “Please, O Lord, let the man of God You sent us come to us again to teach us how to raise the boy who is to be born.”'),
  ('BSB', 'Judges', 7, 13, 9, 'And God listened to the voice of Manoah, and the angel of God returned to the woman as she was sitting in the field; but her husband Manoah was not with her.'),
  ('BSB', 'Judges', 7, 13, 10, 'The woman ran quickly to tell her husband, “Behold, the man who came to me the other day has reappeared!”'),
  ('BSB', 'Judges', 7, 13, 11, 'So Manoah got up and followed his wife. When he came to the man, he asked, “Are you the man who spoke to my wife?” “I am,” he said.'),
  ('BSB', 'Judges', 7, 13, 12, 'Then Manoah asked, “When your words come to pass, what will be the boy’s rule of life and mission?”'),
  ('BSB', 'Judges', 7, 13, 13, 'So the angel of the LORD answered Manoah, “Your wife is to do everything I told her.'),
  ('BSB', 'Judges', 7, 13, 14, 'She must not eat anything that comes from the vine, nor drink any wine or strong drink, nor eat anything unclean. She must do everything I have commanded her.”'),
  ('BSB', 'Judges', 7, 13, 15, '“Please stay here,” Manoah said to the angel of the LORD, “and we will prepare a young goat for you.”'),
  ('BSB', 'Judges', 7, 13, 16, 'And the angel of the LORD replied, “Even if I stay, I will not eat your food. But if you prepare a burnt offering, offer it to the LORD.” For Manoah did not know that it was the angel of the LORD.'),
  ('BSB', 'Judges', 7, 13, 17, 'Then Manoah said to the angel of the LORD, “What is your name, so that we may honor you when your word comes to pass?”'),
  ('BSB', 'Judges', 7, 13, 18, '“Why do you ask my name,” said the angel of the LORD, “since it is beyond comprehension?”'),
  ('BSB', 'Judges', 7, 13, 19, 'Then Manoah took a young goat and a grain offering and offered them on a rock to the LORD. And as Manoah and his wife looked on, the LORD did a marvelous thing.'),
  ('BSB', 'Judges', 7, 13, 20, 'When the flame went up from the altar to the sky, the angel of the LORD ascended in the flame. When Manoah and his wife saw this, they fell facedown to the ground.'),
  ('BSB', 'Judges', 7, 13, 21, 'And when the angel of the LORD did not appear again to Manoah and his wife, Manoah realized that it had been the angel of the LORD.'),
  ('BSB', 'Judges', 7, 13, 22, '“We are going to die,” he said to his wife, “for we have seen God!”'),
  ('BSB', 'Judges', 7, 13, 23, 'But his wife replied, “If the LORD had intended to kill us, He would not have accepted the burnt offering and the grain offering from our hands, nor would He have shown us all these things or spoken to us this way.”'),
  ('BSB', 'Judges', 7, 13, 24, 'So the woman gave birth to a son and named him Samson. The boy grew, and the LORD blessed him.'),
  ('BSB', 'Judges', 7, 13, 25, 'And the Spirit of the LORD began to stir him at Mahaneh-dan, between Zorah and Eshtaol.'),
  ('BSB', 'Judges', 7, 14, 1, 'One day Samson went down to Timnah, where he saw a young Philistine woman.'),
  ('BSB', 'Judges', 7, 14, 2, 'So he returned and told his father and mother, “I have seen a daughter of the Philistines in Timnah. Now get her for me as a wife.”'),
  ('BSB', 'Judges', 7, 14, 3, 'But his father and mother replied, “Can’t you find a young woman among your relatives or among any of our people? Must you go to the uncircumcised Philistines to get a wife?” But Samson told his father, “Get her for me, for she is pleasing to my eyes.”'),
  ('BSB', 'Judges', 7, 14, 4, '(Now his father and mother did not know this was from the LORD, who was seeking an occasion to move against the Philistines; for at that time the Philistines were ruling over Israel.)'),
  ('BSB', 'Judges', 7, 14, 5, 'Then Samson went down to Timnah with his father and mother and came to the vineyards of Timnah. Suddenly a young lion came roaring at him,'),
  ('BSB', 'Judges', 7, 14, 6, 'and the Spirit of the LORD came powerfully upon him, and he tore the lion apart with his bare hands as one would tear a young goat. But he did not tell his father or mother what he had done.'),
  ('BSB', 'Judges', 7, 14, 7, 'Then Samson continued on his way down and spoke to the woman, because she was pleasing to his eyes.'),
  ('BSB', 'Judges', 7, 14, 8, 'When Samson returned later to take her, he left the road to see the lion’s carcass, and in it was a swarm of bees, along with their honey.'),
  ('BSB', 'Judges', 7, 14, 9, 'So he scooped some honey into his hands and ate it as he went along. And when he returned to his father and mother, he gave some to them and they ate it. But he did not tell them that he had taken the honey from the lion’s carcass.'),
  ('BSB', 'Judges', 7, 14, 10, 'Then his father went to visit the woman, and Samson prepared a feast there, as was customary for the bridegroom.'),
  ('BSB', 'Judges', 7, 14, 11, 'And when the Philistines saw him, they selected thirty men to accompany him.'),
  ('BSB', 'Judges', 7, 14, 12, '“Let me tell you a riddle,” Samson said to them. “If you can solve it for me within the seven days of the feast, I will give you thirty linen garments and thirty sets of clothes.'),
  ('BSB', 'Judges', 7, 14, 13, 'But if you cannot solve it, you must give me thirty linen garments and thirty sets of clothes.” “Tell us your riddle,” they replied. “Let us hear it.”'),
  ('BSB', 'Judges', 7, 14, 14, 'So he said to them: “Out of the eater came something to eat, and out of the strong came something sweet.” For three days they were unable to explain the riddle.'),
  ('BSB', 'Judges', 7, 14, 15, 'So on the fourth day they said to Samson’s wife, “Entice your husband to explain the riddle to us, or we will burn you and your father’s household to death. Did you invite us here to rob us?”'),
  ('BSB', 'Judges', 7, 14, 16, 'Then Samson’s wife came to him, weeping, and said, “You hate me! You do not really love me! You have posed to my people a riddle, but have not explained it to me.” “Look,” he said, “I have not even explained it to my father or mother, so why should I explain it to you?”'),
  ('BSB', 'Judges', 7, 14, 17, 'She wept the whole seven days of the feast, and finally on the seventh day, because she had pressed him so much, he told her the answer. And in turn she explained the riddle to her people.'),
  ('BSB', 'Judges', 7, 14, 18, 'Before sunset on the seventh day, the men of the city said to Samson: “What is sweeter than honey? And what is stronger than a lion?” So he said to them: “If you had not plowed with my heifer, you would not have solved my riddle!”'),
  ('BSB', 'Judges', 7, 14, 19, 'Then the Spirit of the LORD came mightily upon him, and he went down to Ashkelon, killed thirty of their men, took their apparel, and gave their clothes to those who had solved the riddle. And burning with anger, Samson returned to his father’s house,'),
  ('BSB', 'Judges', 7, 14, 20, 'and his wife was given to one of the men who had accompanied him.'),
  ('BSB', 'Judges', 7, 15, 1, 'Later on, at the time of the wheat harvest, Samson took a young goat and went to visit his wife. “I want to go to my wife in her room,” he said. But her father would not let him enter.'),
  ('BSB', 'Judges', 7, 15, 2, '“I was sure that you thoroughly hated her,” said her father, “so I gave her to one of the men who accompanied you. Is not her younger sister more beautiful than she? Please take her instead.”'),
  ('BSB', 'Judges', 7, 15, 3, 'Samson said to them, “This time I will be blameless in doing harm to the Philistines.”'),
  ('BSB', 'Judges', 7, 15, 4, 'Then Samson went out and caught three hundred foxes. And he took torches, turned the foxes tail-to-tail, and fastened a torch between each pair of tails.'),
  ('BSB', 'Judges', 7, 15, 5, 'Then he lit the torches and released the foxes into the standing grain of the Philistines, burning up the piles of grain and the standing grain, as well as the vineyards and olive groves.'),
  ('BSB', 'Judges', 7, 15, 6, '“Who did this?” the Philistines demanded. “It was Samson, the son-in-law of the Timnite,” they were told. “For his wife was given to his companion.” So the Philistines went up and burned her and her father to death.'),
  ('BSB', 'Judges', 7, 15, 7, 'And Samson told them, “Because you have done this, I will not rest until I have taken vengeance upon you.”'),
  ('BSB', 'Judges', 7, 15, 8, 'And he struck them ruthlessly with a great slaughter, and then went down and stayed in the cave at the rock of Etam.'),
  ('BSB', 'Judges', 7, 15, 9, 'Then the Philistines went up, camped in Judah, and deployed themselves near the town of Lehi.'),
  ('BSB', 'Judges', 7, 15, 10, '“Why have you attacked us?” said the men of Judah. The Philistines replied, “We have come to arrest Samson and pay him back for what he has done to us.”'),
  ('BSB', 'Judges', 7, 15, 11, 'In response, three thousand men of Judah went to the cave at the rock of Etam, and they asked Samson, “Do you not realize that the Philistines rule over us? What have you done to us?” “I have done to them what they did to me,” he replied.'),
  ('BSB', 'Judges', 7, 15, 12, 'But they said to him, “We have come down to arrest you and hand you over to the Philistines.” Samson replied, “Swear to me that you will not kill me yourselves.”'),
  ('BSB', 'Judges', 7, 15, 13, '“No,” they answered, “we will not kill you, but we will tie you up securely and hand you over to them.” So they bound him with two new ropes and led him up from the rock.'),
  ('BSB', 'Judges', 7, 15, 14, 'When Samson arrived in Lehi, the Philistines came out shouting against him. And the Spirit of the LORD came mightily upon him. The ropes on his arms became like burnt flax, and the bonds broke loose from his hands.'),
  ('BSB', 'Judges', 7, 15, 15, 'He found the fresh jawbone of a donkey, reached out his hand and took it, and struck down a thousand men.'),
  ('BSB', 'Judges', 7, 15, 16, 'Then Samson said: “With the jawbone of a donkey I have piled them into heaps. With the jawbone of a donkey I have slain a thousand men.”'),
  ('BSB', 'Judges', 7, 15, 17, 'And when Samson had finished speaking, he cast the jawbone from his hand; and he named that place Ramath-lehi.'),
  ('BSB', 'Judges', 7, 15, 18, 'And being very thirsty, Samson cried out to the LORD, “You have accomplished this great deliverance through Your servant. Must I now die of thirst and fall into the hands of the uncircumcised?”'),
  ('BSB', 'Judges', 7, 15, 19, 'So God opened up the hollow place in Lehi, and water came out of it. When Samson drank, his strength returned, and he was revived. That is why he named it En-hakkore, and it remains in Lehi to this day.'),
  ('BSB', 'Judges', 7, 15, 20, 'And Samson judged Israel for twenty years in the days of the Philistines.'),
  ('BSB', 'Judges', 7, 16, 1, 'One day Samson went to Gaza, where he saw a prostitute and went in to spend the night with her.'),
  ('BSB', 'Judges', 7, 16, 2, 'When the Gazites heard that Samson was there, they surrounded that place and lay in wait for him all night at the city gate. They were quiet throughout the night, saying, “Let us wait until dawn; then we will kill him.”'),
  ('BSB', 'Judges', 7, 16, 3, 'But Samson lay there only until midnight, when he got up, took hold of the doors of the city gate and both gateposts, and pulled them out, bar and all. Then he put them on his shoulders and took them to the top of the mountain overlooking Hebron.'),
  ('BSB', 'Judges', 7, 16, 4, 'Some time later, Samson fell in love with a woman in the Valley of Sorek, whose name was Delilah.'),
  ('BSB', 'Judges', 7, 16, 5, 'The lords of the Philistines went to her and said, “Entice him and find out the source of his great strength and how we can overpower him to tie him up and subdue him. Then each one of us will give you eleven hundred shekels of silver.”'),
  ('BSB', 'Judges', 7, 16, 6, 'So Delilah said to Samson, “Please tell me the source of your great strength and how you can be tied up and subdued.”'),
  ('BSB', 'Judges', 7, 16, 7, 'Samson told her, “If they tie me up with seven fresh bowstrings that have not been dried, I will become as weak as any other man.”'),
  ('BSB', 'Judges', 7, 16, 8, 'So the lords of the Philistines brought her seven fresh bowstrings that had not been dried, and she tied him up with them.'),
  ('BSB', 'Judges', 7, 16, 9, 'While the men were hidden in her room, she called out, “Samson, the Philistines are here!” But he snapped the bowstrings like a strand of yarn seared by a flame. So the source of his strength remained unknown.'),
  ('BSB', 'Judges', 7, 16, 10, 'Then Delilah said to Samson, “You have mocked me and lied to me! Now please tell me how you can be tied up.”'),
  ('BSB', 'Judges', 7, 16, 11, 'He replied, “If they tie me up with new ropes that have never been used, I will become as weak as any other man.”'),
  ('BSB', 'Judges', 7, 16, 12, 'So Delilah took new ropes, tied him up with them, and called out, “Samson, the Philistines are here!” But while the men were hidden in her room, he snapped the ropes off his arms like they were threads.'),
  ('BSB', 'Judges', 7, 16, 13, 'Then Delilah said to Samson, “You have mocked me and lied to me all along! Tell me how you can be tied up.” He told her, “If you weave the seven braids of my head into the web of a loom and tighten it with a pin, I will become as weak as any other man.”'),
  ('BSB', 'Judges', 7, 16, 14, 'So while he slept, Delilah took the seven braids of his hair and wove them into the web.Then she tightened it with a pin and called to him, “Samson, the Philistines are here!” But he awoke from his sleep and pulled out the pin with the loom and the web.'),
  ('BSB', 'Judges', 7, 16, 15, '“How can you say, ‘I love you,’” she asked, “when your heart is not with me? This is the third time you have mocked me and failed to reveal to me the source of your great strength!”'),
  ('BSB', 'Judges', 7, 16, 16, 'Finally, after she had pressed him daily with her words and pleaded until he was sick to death,'),
  ('BSB', 'Judges', 7, 16, 17, 'Samson told her all that was in his heart: “My hair has never been cut, because I have been a Nazirite to God from my mother’s womb. If I am shaved, my strength will leave me, and I will become as weak as any other man.”'),
  ('BSB', 'Judges', 7, 16, 18, 'When Delilah realized that he had revealed to her all that was in his heart, she sent this message to the lords of the Philistines: “Come up once more, for he has revealed to me all that is in his heart.” Then the lords of the Philistines came to her, bringing the money in their hands.'),
  ('BSB', 'Judges', 7, 16, 19, 'And having lulled him to sleep on her lap, she called a man to shave off the seven braids of his head. In this way she began to subdue him, and his strength left him.'),
  ('BSB', 'Judges', 7, 16, 20, 'Then she called out, “Samson, the Philistines are here!” When Samson awoke from his sleep, he thought, “I will escape as I did before and shake myself free.” But he did not know that the LORD had departed from him.'),
  ('BSB', 'Judges', 7, 16, 21, 'Then the Philistines seized him, gouged out his eyes, and brought him down to Gaza, where he was bound with bronze shackles and forced to grind grain in the prison.'),
  ('BSB', 'Judges', 7, 16, 22, 'However, the hair of his head began to grow back after it had been shaved.'),
  ('BSB', 'Judges', 7, 16, 23, 'Now the lords of the Philistines gathered together to offer a great sacrifice to their god Dagon. They rejoiced and said, “Our god has delivered Samson our enemy into our hands.”'),
  ('BSB', 'Judges', 7, 16, 24, 'And when the people saw him, they praised their god, saying: “Our god has delivered into our hands our enemy who destroyed our land and multiplied our dead.”'),
  ('BSB', 'Judges', 7, 16, 25, 'And while their hearts were merry, they said, “Call for Samson to entertain us.” So they called Samson out of the prison to entertain them. And they stationed him between the pillars.'),
  ('BSB', 'Judges', 7, 16, 26, 'Samson said to the servant who held his hand, “Lead me where I can feel the pillars supporting the temple, so I can lean against them.”'),
  ('BSB', 'Judges', 7, 16, 27, 'Now the temple was full of men and women; all the lords of the Philistines were there, and about three thousand men and women were on the roof watching Samson entertain them.'),
  ('BSB', 'Judges', 7, 16, 28, 'Then Samson called out to the LORD: “O Lord GOD, please remember me. Strengthen me, O God, just once more, so that with one vengeful blow I may pay back the Philistines for my two eyes.”'),
  ('BSB', 'Judges', 7, 16, 29, 'And Samson reached out for the two central pillars supporting the temple. Bracing himself against them with his right hand on one pillar and his left hand on the other,'),
  ('BSB', 'Judges', 7, 16, 30, 'Samson said, “Let me die with the Philistines.” Then he pushed with all his might, and the temple fell on the lords and all the people in it. So in his death he killed more than he had killed in his life.'),
  ('BSB', 'Judges', 7, 16, 31, 'Then Samson’s brothers and his father’s family came down, carried him back, and buried him between Zorah and Eshtaol in the tomb of his father Manoah. And he had judged Israel twenty years.'),
  ('BSB', 'Judges', 7, 17, 1, 'Now a man named Micah from the hill country of Ephraim'),
  ('BSB', 'Judges', 7, 17, 2, 'said to his mother, “The eleven hundred shekels of silver that were taken from you and about which I heard you utter a curse—I have the silver here with me; I took it.” Then his mother said, “Blessed be my son by the LORD!”'),
  ('BSB', 'Judges', 7, 17, 3, 'And when he had returned the eleven hundred shekels of silver to his mother, she said, “I wholly dedicate the silver to the LORD for my son’s benefit, to make a graven image and a molten idol. Therefore I will now return it to you.”'),
  ('BSB', 'Judges', 7, 17, 4, 'So he returned the silver to his mother, and she took two hundred shekels of silver and gave them to a silversmith, who made them into a graven image and a molten idol. And they were placed in the house of Micah.'),
  ('BSB', 'Judges', 7, 17, 5, 'Now this man Micah had a shrine, and he made an ephod and some household idols, and ordained one of his sons as his priest.'),
  ('BSB', 'Judges', 7, 17, 6, 'In those days there was no king in Israel; everyone did what was right in his own eyes.'),
  ('BSB', 'Judges', 7, 17, 7, 'And there was a young Levite from Bethlehem in Judah who had been residing within the clan of Judah.'),
  ('BSB', 'Judges', 7, 17, 8, 'This man left the city of Bethlehem in Judah to settle where he could find a place. And as he traveled, he came to Micah’s house in the hill country of Ephraim.'),
  ('BSB', 'Judges', 7, 17, 9, '“Where are you from?” Micah asked him. “I am a Levite from Bethlehem in Judah,” he replied, “and I am on my way to settle wherever I can find a place.”'),
  ('BSB', 'Judges', 7, 17, 10, '“Stay with me,” Micah said to him, “and be my father and priest, and I will give you ten shekels of silver per year, a suit of clothes, and your provisions.” So the Levite went in'),
  ('BSB', 'Judges', 7, 17, 11, 'and agreed to stay with him, and the young man became like a son to Micah.'),
  ('BSB', 'Judges', 7, 17, 12, 'Micah ordained the Levite, and the young man became his priest and lived in his house.'),
  ('BSB', 'Judges', 7, 17, 13, 'Then Micah said, “Now I know that the LORD will be good to me, because a Levite has become my priest.”'),
  ('BSB', 'Judges', 7, 18, 1, 'In those days there was no king in Israel, and the tribe of the Danites was looking for territory to occupy. For up to that time they had not come into an inheritance among the tribes of Israel.'),
  ('BSB', 'Judges', 7, 18, 2, 'So the Danites sent out five men from their clans, men of valor from Zorah and Eshtaol, to spy out the land and explore it. “Go and explore the land,” they told them. The men entered the hill country of Ephraim and came to the house of Micah, where they spent the night.'),
  ('BSB', 'Judges', 7, 18, 3, 'And while they were near Micah’s house, they recognized the voice of the young Levite; so they went over and asked him, “Who brought you here? What are you doing in this place? Why are you here?”'),
  ('BSB', 'Judges', 7, 18, 4, '“Micah has done this and that for me,” he replied, “and he has hired me to be his priest.”'),
  ('BSB', 'Judges', 7, 18, 5, 'Then they said to him, “Please inquire of God to determine whether we will have a successful journey.”'),
  ('BSB', 'Judges', 7, 18, 6, 'And the priest told them, “Go in peace. The LORD is watching over your journey.”'),
  ('BSB', 'Judges', 7, 18, 7, 'So the five men departed and came to Laish, where they saw that the people were living securely, like the Sidonians, tranquil and unsuspecting. There was nothing lacking in the land and no oppressive ruler. And they were far away from the Sidonians and had no alliance with anyone.'),
  ('BSB', 'Judges', 7, 18, 8, 'When the men returned to Zorah and Eshtaol, their brothers asked them, “What did you find?”'),
  ('BSB', 'Judges', 7, 18, 9, 'They answered, “Come on, let us go up against them, for we have seen the land, and it is very good. Why would you fail to act? Do not hesitate to go there and take possession of the land!'),
  ('BSB', 'Judges', 7, 18, 10, 'When you enter, you will come to an unsuspecting people and a spacious land, for God has delivered it into your hand. It is a place where nothing on earth is lacking.”'),
  ('BSB', 'Judges', 7, 18, 11, 'So six hundred Danites departed from Zorah and Eshtaol, armed with weapons of war.'),
  ('BSB', 'Judges', 7, 18, 12, 'They went up and camped at Kiriath-jearim in Judah. That is why the place west of Kiriath-jearim is called Mahaneh-dan to this day.'),
  ('BSB', 'Judges', 7, 18, 13, 'And from there they traveled to the hill country of Ephraim and came to Micah’s house.'),
  ('BSB', 'Judges', 7, 18, 14, 'Then the five men who had gone to spy out the land of Laish said to their brothers, “Did you know that one of these houses has an ephod, household gods, a graven image, and a molten idol? Now think about what you should do.”'),
  ('BSB', 'Judges', 7, 18, 15, 'So they turned aside there and went to the home of the young Levite, the house of Micah, and greeted him.'),
  ('BSB', 'Judges', 7, 18, 16, 'The six hundred Danites stood at the entrance of the gate, armed with their weapons of war.'),
  ('BSB', 'Judges', 7, 18, 17, 'And the five men who had gone to spy out the land went inside and took the graven image, the ephod, the household idols, and the molten idol, while the priest stood at the entrance of the gate with the six hundred armed men.'),
  ('BSB', 'Judges', 7, 18, 18, 'When they entered Micah’s house and took the graven image, the ephod, the household idols, and the molten idol, the priest said to them, “What are you doing?”'),
  ('BSB', 'Judges', 7, 18, 19, '“Be quiet,” they told him. “Put your hand over your mouth and come with us and be a father and a priest to us. Is it better for you to be a priest for the house of one person or a priest for a tribe and family in Israel?”'),
  ('BSB', 'Judges', 7, 18, 20, 'So the priest was glad and took the ephod, the household idols, and the graven image, and went with the people.'),
  ('BSB', 'Judges', 7, 18, 21, 'Putting their small children, their livestock, and their possessions in front of them, they turned and departed.'),
  ('BSB', 'Judges', 7, 18, 22, 'After they were some distance from Micah’s house, the men in the houses near Micah’s house mobilized and overtook the Danites.'),
  ('BSB', 'Judges', 7, 18, 23, 'When they called out after them, the Danites turned to face them and said to Micah, “What is the matter with you that you have called out such a company?”'),
  ('BSB', 'Judges', 7, 18, 24, 'He replied, “You took the gods I had made, and my priest, and went away. What else do I have? How can you say to me, ‘What is the matter with you?’”'),
  ('BSB', 'Judges', 7, 18, 25, 'The Danites said to him, “Do not raise your voice against us, or angry men will attack you, and you and your family will lose your lives.”'),
  ('BSB', 'Judges', 7, 18, 26, 'So the Danites went on their way, and Micah turned to go back home, because he saw that they were too strong for him.'),
  ('BSB', 'Judges', 7, 18, 27, 'After they had taken Micah’s idols and his priest, they went to Laish, to a tranquil and unsuspecting people, and they struck them with their swords and burned down the city.'),
  ('BSB', 'Judges', 7, 18, 28, 'There was no one to deliver them, because the city was far from Sidon and had no alliance with anyone; it was in a valley near Beth-rehob. And the Danites rebuilt the city and lived there.'),
  ('BSB', 'Judges', 7, 18, 29, 'They named it Dan, after their forefather Dan, who was born to Israel—though the city was formerly named Laish.'),
  ('BSB', 'Judges', 7, 18, 30, 'The Danites set up idols for themselves, and Jonathan son of Gershom, the son of Moses, and his sons were priests for the tribe of Dan until the day of the captivity of the land.'),
  ('BSB', 'Judges', 7, 18, 31, 'So they set up for themselves Micah’s graven image, and it was there the whole time the house of God was in Shiloh.'),
  ('BSB', 'Judges', 7, 19, 1, 'Now in those days, when there was no king in Israel, a Levite who lived in the remote hill country of Ephraim took for himself a concubine from Bethlehem in Judah.'),
  ('BSB', 'Judges', 7, 19, 2, 'But she was unfaithful to him and left him to return to her father’s house in Bethlehem in Judah. After she had been there four months,'),
  ('BSB', 'Judges', 7, 19, 3, 'her husband got up and went after her to speak kindly to her and bring her back, taking his servant and a pair of donkeys. So the girl brought him into her father’s house, and when her father saw him, he gladly welcomed him.'),
  ('BSB', 'Judges', 7, 19, 4, 'His father-in-law, the girl’s father, persuaded him to stay, so he remained with him three days, eating, drinking, and lodging there.'),
  ('BSB', 'Judges', 7, 19, 5, 'On the fourth day, they got up early in the morning and prepared to depart, but the girl’s father said to his son-in-law, “Refresh your heart with a morsel of bread, and then you can go.”'),
  ('BSB', 'Judges', 7, 19, 6, 'So they sat down and the two of them ate and drank together. Then the girl’s father said to the man, “Please agree to stay overnight and let your heart be merry.”'),
  ('BSB', 'Judges', 7, 19, 7, 'The man got up to depart, but his father-in-law persuaded him, so he stayed there that night.'),
  ('BSB', 'Judges', 7, 19, 8, 'On the fifth day, he got up early in the morning to depart, but the girl’s father said, “Please refresh your heart.” So they waited until late afternoon and the two of them ate.'),
  ('BSB', 'Judges', 7, 19, 9, 'When the man got up to depart with his concubine and his servant, his father-in-law, the girl’s father, said to him, “Look, the day is drawing to a close. Please spend the night. See, the day is almost over. Spend the night here, that your heart may be merry. Then you can get up early tomorrow for your journey home.”'),
  ('BSB', 'Judges', 7, 19, 10, 'But the man was unwilling to spend the night. He got up and departed, and arrived opposite Jebus (that is, Jerusalem), with his two saddled donkeys and his concubine.'),
  ('BSB', 'Judges', 7, 19, 11, 'When they were near Jebus and the day was almost gone, the servant said to his master, “Please, let us stop at this Jebusite city and spend the night here.”'),
  ('BSB', 'Judges', 7, 19, 12, 'But his master replied, “We will not turn aside to the city of foreigners, where there are no Israelites. We will go on to Gibeah.”'),
  ('BSB', 'Judges', 7, 19, 13, 'He continued, “Come, let us try to reach one of these towns to spend the night in Gibeah or Ramah.”'),
  ('BSB', 'Judges', 7, 19, 14, 'So they continued on their journey, and the sun set as they neared Gibeah in Benjamin.'),
  ('BSB', 'Judges', 7, 19, 15, 'They stopped to go in and lodge in Gibeah. The Levite went in and sat down in the city square, but no one would take them into his home for the night.'),
  ('BSB', 'Judges', 7, 19, 16, 'That evening an old man from the hill country of Ephraim, who was residing in Gibeah (the men of that place were Benjamites), came in from his work in the field.'),
  ('BSB', 'Judges', 7, 19, 17, 'When he looked up and saw the traveler in the city square, the old man asked, “Where are you going, and where have you come from?”'),
  ('BSB', 'Judges', 7, 19, 18, 'The Levite replied, “We are traveling from Bethlehem in Judah to the remote hill country of Ephraim, where I am from. I went to Bethlehem in Judah, and now I am going to the house of the LORD; but no one has taken me into his home,'),
  ('BSB', 'Judges', 7, 19, 19, 'even though there is both straw and feed for our donkeys, and bread and wine for me and the maidservant and young man with me. There is nothing that we, your servants, lack.”'),
  ('BSB', 'Judges', 7, 19, 20, '“Peace to you,” said the old man. “Let me supply everything you need. Only do not spend the night in the square.”'),
  ('BSB', 'Judges', 7, 19, 21, 'So he brought him to his house and fed his donkeys. And they washed their feet and ate and drank.'),
  ('BSB', 'Judges', 7, 19, 22, 'While they were enjoying themselves, suddenly the wicked men of the city surrounded the house. Pounding on the door, they said to the old man who owned the house, “Bring out the man who came to your house, so we can have relations with him!”'),
  ('BSB', 'Judges', 7, 19, 23, 'The owner of the house went out and said to them, “No, my brothers, do not do this wicked thing! After all, this man is a guest in my house. Do not commit this outrage.'),
  ('BSB', 'Judges', 7, 19, 24, 'Look, let me bring out my virgin daughter and the man’s concubine, and you can use them and do with them as you wish. But do not do such a vile thing to this man.”'),
  ('BSB', 'Judges', 7, 19, 25, 'But the men would not listen to him. So the Levite took his concubine and sent her outside to them, and they raped her and abused her throughout the night, and at dawn they let her go.'),
  ('BSB', 'Judges', 7, 19, 26, 'Early that morning, the woman went back to the house where her master was staying, collapsed at the doorway, and lay there until it was light.'),
  ('BSB', 'Judges', 7, 19, 27, 'In the morning, when her master got up and opened the doors of the house to go out on his journey, there was his concubine, collapsed in the doorway of the house, with her hands on the threshold.'),
  ('BSB', 'Judges', 7, 19, 28, '“Get up,” he told her. “Let us go.” But there was no response. So the man put her on his donkey and set out for home.'),
  ('BSB', 'Judges', 7, 19, 29, 'When he reached his house, he picked up a knife, took hold of his concubine, cut her limb by limb into twelve pieces, and sent her throughout the territory of Israel.'),
  ('BSB', 'Judges', 7, 19, 30, 'And everyone who saw it said, “Nothing like this has been seen or done from the day the Israelites came out of the land of Egypt until this day. Think it over, take counsel, and speak up!”'),
  ('BSB', 'Judges', 7, 20, 1, 'Then all the Israelites from Dan to Beersheba and from the land of Gilead came out, and the congregation assembled as one man before the LORD at Mizpah.'),
  ('BSB', 'Judges', 7, 20, 2, 'The leaders of all the people and all the tribes of Israel presented themselves in the assembly of God’s people: 400,000 men on foot, armed with swords.'),
  ('BSB', 'Judges', 7, 20, 3, '(Meanwhile the Benjamites heard that the Israelites had gone up to Mizpah.) And the Israelites asked, “Tell us, how did this wicked thing happen?”'),
  ('BSB', 'Judges', 7, 20, 4, 'So the Levite, the husband of the murdered woman, answered: “I and my concubine came to Gibeah in Benjamin to spend the night.'),
  ('BSB', 'Judges', 7, 20, 5, 'And during the night, the men of Gibeah rose up against me and surrounded the house. They intended to kill me, but they abused my concubine, and she died.'),
  ('BSB', 'Judges', 7, 20, 6, 'Then I took my concubine, cut her into pieces, and sent her throughout the land of Israel’s inheritance, because they had committed a lewd and disgraceful act in Israel.'),
  ('BSB', 'Judges', 7, 20, 7, 'Behold, all you Israelites, give your advice and verdict here and now.”'),
  ('BSB', 'Judges', 7, 20, 8, 'Then all the people stood as one man and said, “Not one of us will return to his tent or to his house.'),
  ('BSB', 'Judges', 7, 20, 9, 'Now this is what we will do to Gibeah: We will go against it as the lot dictates.'),
  ('BSB', 'Judges', 7, 20, 10, 'We will take ten men out of every hundred from all the tribes of Israel, and a hundred out of every thousand, and a thousand out of every ten thousand, to supply provisions for the army when they go to Gibeah in Benjamin to punish them for the atrocity they have committed in Israel.”'),
  ('BSB', 'Judges', 7, 20, 11, 'So all the men of Israel gathered as one man, united against the city.'),
  ('BSB', 'Judges', 7, 20, 12, 'And the tribes of Israel sent men throughout the tribe of Benjamin, saying, “What is this wickedness that has occurred among you?'),
  ('BSB', 'Judges', 7, 20, 13, 'Hand over the wicked men of Gibeah so we can put them to death and purge Israel of this evil.” But the Benjamites refused to heed the voice of their fellow Israelites.'),
  ('BSB', 'Judges', 7, 20, 14, 'And from their cities they came together at Gibeah to go out and fight against the Israelites.'),
  ('BSB', 'Judges', 7, 20, 15, 'On that day the Benjamites mobilized 26,000 swordsmen from their cities, in addition to the 700 select men of Gibeah.'),
  ('BSB', 'Judges', 7, 20, 16, 'Among all these soldiers there were 700 select left-handers, each of whom could sling a stone at a hair without missing.'),
  ('BSB', 'Judges', 7, 20, 17, 'The Israelites, apart from Benjamin, mobilized 400,000 swordsmen, each one an experienced warrior.'),
  ('BSB', 'Judges', 7, 20, 18, 'The Israelites set out, went up to Bethel, and inquired of God, “Who of us shall go up first to fight against the Benjamites?” “Judah will be first,” the LORD replied.'),
  ('BSB', 'Judges', 7, 20, 19, 'The next morning the Israelites set out and camped near Gibeah.'),
  ('BSB', 'Judges', 7, 20, 20, 'And the men of Israel went out to fight against Benjamin and took up their battle positions at Gibeah.'),
  ('BSB', 'Judges', 7, 20, 21, 'And the Benjamites came out of Gibeah and cut down 22,000 Israelites on the battlefield that day.'),
  ('BSB', 'Judges', 7, 20, 22, 'But the Israelite army took courage and again took their battle positions in the same place where they had arrayed themselves on the first day.'),
  ('BSB', 'Judges', 7, 20, 23, 'They went up and wept before the LORD until evening, inquiring of Him, “Should we again draw near for battle against our brothers the Benjamites?” And the LORD answered, “Go up against them.”'),
  ('BSB', 'Judges', 7, 20, 24, 'On the second day the Israelites advanced against the Benjamites.'),
  ('BSB', 'Judges', 7, 20, 25, 'That same day the Benjamites came out against them from Gibeah and cut down another 18,000 Israelites, all of them armed with swords.'),
  ('BSB', 'Judges', 7, 20, 26, 'Then the Israelites, all the people, went up to Bethel, where they sat weeping before the LORD. That day they fasted until evening and presented burnt offerings and peace offerings to the LORD.'),
  ('BSB', 'Judges', 7, 20, 27, 'And the Israelites inquired of the LORD. (In those days the ark of the covenant of God was there,'),
  ('BSB', 'Judges', 7, 20, 28, 'and Phinehas son of Eleazar, the son of Aaron, served before it.) The Israelites asked, “Should we again go out to battle against our brothers the Benjamites, or should we stop?” The LORD answered, “Fight, for tomorrow I will deliver them into your hand.”'),
  ('BSB', 'Judges', 7, 20, 29, 'So Israel set up an ambush around Gibeah.'),
  ('BSB', 'Judges', 7, 20, 30, 'On the third day the Israelites went up against the Benjamites and arrayed themselves against Gibeah as they had done before.'),
  ('BSB', 'Judges', 7, 20, 31, 'The Benjamites came out against them and were drawn away from the city. They began to attack the people as before, killing about thirty men of Israel in the fields and on the roads, one of which led up to Bethel and the other to Gibeah.'),
  ('BSB', 'Judges', 7, 20, 32, '“We are defeating them as before,” said the Benjamites. But the Israelites said, “Let us retreat and draw them away from the city onto the roads.”'),
  ('BSB', 'Judges', 7, 20, 33, 'So all the men of Israel got up from their places and arrayed themselves at Baal-tamar, and the Israelites in ambush charged from their positions west of Gibeah.'),
  ('BSB', 'Judges', 7, 20, 34, 'Then 10,000 select men from all Israel made a frontal assault against Gibeah, and the battle was fierce. But the Benjamites did not realize that disaster was upon them.'),
  ('BSB', 'Judges', 7, 20, 35, 'The LORD defeated Benjamin in the presence of Israel, and on that day the Israelites slaughtered 25,100 Benjamites, all armed with swords.'),
  ('BSB', 'Judges', 7, 20, 36, 'Then the Benjamites realized they had been defeated. Now the men of Israel had retreated before Benjamin because they were relying on the ambush they had set against Gibeah.'),
  ('BSB', 'Judges', 7, 20, 37, 'The men in ambush rushed suddenly against Gibeah; they advanced and put the whole city to the sword.'),
  ('BSB', 'Judges', 7, 20, 38, 'The men of Israel had arranged a signal with the men in ambush: When they sent up a great cloud of smoke from the city,'),
  ('BSB', 'Judges', 7, 20, 39, 'the men of Israel would turn in the battle. When the Benjamites had begun to strike them down, killing about thirty men of Israel, they said, “They are defeated before us as in the first battle.”'),
  ('BSB', 'Judges', 7, 20, 40, 'But when the column of smoke began to go up from the city, the Benjamites looked behind them and saw the whole city going up in smoke.'),
  ('BSB', 'Judges', 7, 20, 41, 'Then the men of Israel turned back on them, and the men of Benjamin were terrified when they realized that disaster had come upon them.'),
  ('BSB', 'Judges', 7, 20, 42, 'So they fled before the men of Israel toward the wilderness, but the battle overtook them, and the men coming out of the cities struck them down there.'),
  ('BSB', 'Judges', 7, 20, 43, 'They surrounded the Benjamites, pursued them, and easily overtook them in the vicinity of Gibeah on the east.'),
  ('BSB', 'Judges', 7, 20, 44, 'And 18,000 Benjamites fell, all men of valor.'),
  ('BSB', 'Judges', 7, 20, 45, 'Then the Benjamites turned and fled toward the wilderness to the rock of Rimmon, and Israel cut down 5,000 men on the roads. And they overtook them at Gidom and struck down 2,000 more.'),
  ('BSB', 'Judges', 7, 20, 46, 'That day 25,000 Benjamite swordsmen fell, all men of valor.'),
  ('BSB', 'Judges', 7, 20, 47, 'But 600 men turned and fled into the wilderness to the rock of Rimmon, where they stayed four months.'),
  ('BSB', 'Judges', 7, 20, 48, 'And the men of Israel turned back against the other Benjamites and put to the sword all the cities, including the animals and everything else they found. And they burned down all the cities in their path.'),
  ('BSB', 'Judges', 7, 21, 1, 'Now the men of Israel had sworn an oath at Mizpah, saying, “Not one of us will give his daughter in marriage to a Benjamite.”'),
  ('BSB', 'Judges', 7, 21, 2, 'So the people came to Bethel and sat there before God until evening, lifting up their voices and weeping bitterly.'),
  ('BSB', 'Judges', 7, 21, 3, '“Why, O LORD God of Israel,” they cried out, “has this happened in Israel? Today in Israel one tribe is missing!”'),
  ('BSB', 'Judges', 7, 21, 4, 'The next day the people got up early, built an altar there, and presented burnt offerings and peace offerings.'),
  ('BSB', 'Judges', 7, 21, 5, 'The Israelites asked, “Who among all the tribes of Israel did not come to the assembly before the LORD?” For they had taken a solemn oath that anyone who failed to come up before the LORD at Mizpah would surely be put to death.'),
  ('BSB', 'Judges', 7, 21, 6, 'And the Israelites grieved for their brothers, the Benjamites, and said, “Today a tribe is cut off from Israel.'),
  ('BSB', 'Judges', 7, 21, 7, 'What should we do about wives for the survivors, since we have sworn by the LORD not to give them our daughters in marriage?”'),
  ('BSB', 'Judges', 7, 21, 8, 'So they asked, “Which one of the tribes of Israel failed to come up before the LORD at Mizpah?” And, in fact, no one from Jabesh-gilead had come to the camp for the assembly.'),
  ('BSB', 'Judges', 7, 21, 9, 'For when the people were counted, none of the residents of Jabesh-gilead were there.'),
  ('BSB', 'Judges', 7, 21, 10, 'So the congregation sent 12,000 of their most valiant men and commanded them: “Go and put to the sword those living in Jabesh-gilead, including women and children.'),
  ('BSB', 'Judges', 7, 21, 11, 'This is what you are to do: Devote to destruction every male, as well as every female who has had relations with a man.”'),
  ('BSB', 'Judges', 7, 21, 12, 'So they found among the inhabitants of Jabesh-gilead four hundred young women who had not had relations with a man, and they brought them to the camp at Shiloh in the land of Canaan.'),
  ('BSB', 'Judges', 7, 21, 13, 'Then the whole congregation sent a message of peace to the Benjamites who were at the rock of Rimmon.'),
  ('BSB', 'Judges', 7, 21, 14, 'And at that time the Benjamites returned and were given the women who were spared from Jabesh-gilead. But there were not enough women for all of them.'),
  ('BSB', 'Judges', 7, 21, 15, 'The people grieved for Benjamin, because the LORD had made a void in the tribes of Israel.'),
  ('BSB', 'Judges', 7, 21, 16, 'Then the elders of the congregation said, “What should we do about wives for those who remain, since the women of Benjamin have been destroyed?”'),
  ('BSB', 'Judges', 7, 21, 17, 'They added, “There must be heirs for the survivors of Benjamin, so that a tribe of Israel will not be wiped out.'),
  ('BSB', 'Judges', 7, 21, 18, 'But we cannot give them our daughters as wives.” For the Israelites had sworn, “Cursed is he who gives a wife to a Benjamite.”'),
  ('BSB', 'Judges', 7, 21, 19, '“But look,” they said, “there is a yearly feast to the LORD in Shiloh, which is north of Bethel east of the road that goes up from Bethel to Shechem, and south of Lebonah.”'),
  ('BSB', 'Judges', 7, 21, 20, 'So they commanded the Benjamites: “Go, hide in the vineyards'),
  ('BSB', 'Judges', 7, 21, 21, 'and watch. When you see the daughters of Shiloh come out to perform their dances, each of you is to come out of the vineyards, catch for himself a wife from the daughters of Shiloh, and go to the land of Benjamin.'),
  ('BSB', 'Judges', 7, 21, 22, 'When their fathers or brothers come to us to complain, we will tell them, ‘Do us a favor by helping them, since we did not get wives for each of them in the war. Since you did not actually give them your daughters, you have no guilt.’”'),
  ('BSB', 'Judges', 7, 21, 23, 'The Benjamites did as instructed and carried away the number of women they needed from the dancers they caught. They went back to their own inheritance, rebuilt their cities, and settled in them.'),
  ('BSB', 'Judges', 7, 21, 24, 'And at that time, each of the Israelites returned from there to his own tribe and clan, each to his own inheritance.'),
  ('BSB', 'Judges', 7, 21, 25, 'In those days there was no king in Israel; everyone did what was right in his own eyes.'),
  ('BSB', 'Ruth', 8, 1, 1, 'In the days when the judges ruled, there was a famine in the land. And a certain man from Bethlehem in Judah, with his wife and two sons, went to reside in the land of Moab.'),
  ('BSB', 'Ruth', 8, 1, 2, 'The man’s name was Elimelech, his wife’s name was Naomi, and the names of his two sons were Mahlon and Chilion. They were Ephrathites from Bethlehem in Judah, and they entered the land of Moab and settled there.'),
  ('BSB', 'Ruth', 8, 1, 3, 'Then Naomi’s husband Elimelech died, and she was left with her two sons,'),
  ('BSB', 'Ruth', 8, 1, 4, 'who took Moabite women as their wives, one named Orpah and the other named Ruth. And after they had lived in Moab about ten years,'),
  ('BSB', 'Ruth', 8, 1, 5, 'both Mahlon and Chilion also died, and Naomi was left without her two sons and without her husband.'),
  ('BSB', 'Ruth', 8, 1, 6, 'When Naomi heard in Moab that the LORD had attended to His people by providing them with food, she and her daughters-in-law prepared to leave the land of Moab.'),
  ('BSB', 'Ruth', 8, 1, 7, 'Accompanied by her two daughters-in-law, she left the place where she had been living and set out on the road leading back to the land of Judah.'),
  ('BSB', 'Ruth', 8, 1, 8, 'Then Naomi said to her two daughters-in-law, “Go back, each of you to your mother’s home. May the LORD show you loving devotion, as you have shown to your dead and to me.'),
  ('BSB', 'Ruth', 8, 1, 9, 'May the LORD enable each of you to find rest in the home of your new husband.” And she kissed them as they wept aloud'),
  ('BSB', 'Ruth', 8, 1, 10, 'and said, “Surely we will return with you to your people.”'),
  ('BSB', 'Ruth', 8, 1, 11, 'But Naomi replied, “Return home, my daughters. Why would you go with me? Are there still sons in my womb to become your husbands?'),
  ('BSB', 'Ruth', 8, 1, 12, 'Return home, my daughters. Go on, for I am too old to have another husband. Even if I thought there was hope for me to have a husband tonight and to bear sons,'),
  ('BSB', 'Ruth', 8, 1, 13, 'would you wait for them to grow up? Would you refrain from having husbands? No, my daughters, it grieves me very much for your sakes that the hand of the LORD has gone out against me.”'),
  ('BSB', 'Ruth', 8, 1, 14, 'Again they wept aloud, and Orpah kissed her mother-in-law goodbye, but Ruth clung to her.'),
  ('BSB', 'Ruth', 8, 1, 15, '“Look,” said Naomi, “your sister-in-law has gone back to her people and her gods; follow her back home.”'),
  ('BSB', 'Ruth', 8, 1, 16, 'But Ruth replied: “Do not urge me to leave you or to turn from following you. For wherever you go, I will go, and wherever you live, I will live; your people will be my people, and your God will be my God.'),
  ('BSB', 'Ruth', 8, 1, 17, 'Where you die, I will die, and there I will be buried. May the LORD punish me, and ever so severely, if anything but death separates you and me.”'),
  ('BSB', 'Ruth', 8, 1, 18, 'When Naomi saw that Ruth was determined to go with her, she stopped trying to persuade her.'),
  ('BSB', 'Ruth', 8, 1, 19, 'So Naomi and Ruth traveled until they came to Bethlehem. When they entered Bethlehem, the whole city was stirred because of them, and the women of the city exclaimed, “Can this be Naomi?”'),
  ('BSB', 'Ruth', 8, 1, 20, '“Do not call me Naomi,” she replied. “Call me Mara, because the Almighty has dealt quite bitterly with me.'),
  ('BSB', 'Ruth', 8, 1, 21, 'I went away full, but the LORD has brought me back empty. Why call me Naomi? After all, the LORD has testified against me, and the Almighty has afflicted me.”'),
  ('BSB', 'Ruth', 8, 1, 22, 'So Naomi returned from the land of Moab with her daughter-in-law Ruth the Moabitess. And they arrived in Bethlehem at the beginning of the barley harvest.'),
  ('BSB', 'Ruth', 8, 2, 1, 'Now Naomi had a relative on her husband’s side, a prominent man of noble character from the clan of Elimelech, whose name was Boaz.'),
  ('BSB', 'Ruth', 8, 2, 2, 'And Ruth the Moabitess said to Naomi, “Please let me go into the fields and glean heads of grain after someone in whose sight I may find favor.” “Go ahead, my daughter,” Naomi replied.'),
  ('BSB', 'Ruth', 8, 2, 3, 'So Ruth departed and went out into the field and gleaned after the harvesters. And she happened to come to the part of the field belonging to Boaz, who was from the clan of Elimelech.'),
  ('BSB', 'Ruth', 8, 2, 4, 'Just then Boaz arrived from Bethlehem and said to the harvesters, “The LORD be with you.” “The LORD bless you,” they replied.'),
  ('BSB', 'Ruth', 8, 2, 5, 'And Boaz asked the foreman of his harvesters, “Whose young woman is this?”'),
  ('BSB', 'Ruth', 8, 2, 6, 'The foreman answered, “She is the Moabitess who returned with Naomi from the land of Moab.'),
  ('BSB', 'Ruth', 8, 2, 7, 'She has said, ‘Please let me glean and gather among the sheaves after the harvesters.’ So she came out and has continued from morning until now, except that she rested a short time in the shelter.”'),
  ('BSB', 'Ruth', 8, 2, 8, 'Then Boaz said to Ruth, “Listen, my daughter. Do not go and glean in another field, and do not go away from this place, but stay here close to my servant girls.'),
  ('BSB', 'Ruth', 8, 2, 9, 'Let your eyes be on the field they are harvesting, and follow along after these girls. Indeed, I have ordered the young men not to touch you. And when you are thirsty, go and drink from the jars the young men have filled.”'),
  ('BSB', 'Ruth', 8, 2, 10, 'At this, she fell on her face, bowing low to the ground, and said to him, “Why have I found such favor in your eyes that you should take notice of me, even though I am a foreigner?”'),
  ('BSB', 'Ruth', 8, 2, 11, 'Boaz replied, “I have been made fully aware of all you have done for your mother-in-law since the death of your husband, how you left your father and mother and the land of your birth, and how you came to a people you did not know before.'),
  ('BSB', 'Ruth', 8, 2, 12, 'May the LORD repay your work, and may you receive a rich reward from the LORD, the God of Israel, under whose wings you have taken refuge.”'),
  ('BSB', 'Ruth', 8, 2, 13, '“My lord,” she said, “may I continue to find favor in your eyes, for you have comforted and spoken kindly to your maidservant, though I am not like one of your servant girls.”'),
  ('BSB', 'Ruth', 8, 2, 14, 'At mealtime Boaz said to her, “Come over here; have some bread and dip it into the vinegar sauce.” So she sat down beside the harvesters, and he offered her roasted grain, and she ate and was satisfied and had some left over.'),
  ('BSB', 'Ruth', 8, 2, 15, 'When Ruth got up to glean, Boaz ordered his young men, “Even if she gathers among the sheaves, do not insult her.'),
  ('BSB', 'Ruth', 8, 2, 16, 'Rather, pull out for her some stalks from the bundles and leave them for her to gather. Do not rebuke her.”'),
  ('BSB', 'Ruth', 8, 2, 17, 'So Ruth gathered grain in the field until evening. And when she beat out what she had gleaned, it was about an ephah of barley.'),
  ('BSB', 'Ruth', 8, 2, 18, 'She picked up the grain and went into the town, where her mother-in-law saw what she had gleaned. And she brought out what she had saved from her meal and gave it to Naomi.'),
  ('BSB', 'Ruth', 8, 2, 19, 'Then her mother-in-law asked her, “Where did you glean today, and where did you work? Blessed be the man who noticed you.” So she told her mother-in-law where she had worked. “The name of the man I worked with today is Boaz,” she said.'),
  ('BSB', 'Ruth', 8, 2, 20, 'Then Naomi said to her daughter-in-law, “May he be blessed by the LORD, who has not withdrawn His kindness from the living or the dead.” Naomi continued, “The man is a close relative. He is one of our kinsman-redeemers.”'),
  ('BSB', 'Ruth', 8, 2, 21, 'Then Ruth the Moabitess said, “He also told me, ‘Stay with my young men until they have finished gathering all my harvest.’”'),
  ('BSB', 'Ruth', 8, 2, 22, 'And Naomi said to her daughter-in-law Ruth, “My daughter, it is good for you to work with his young women, so that nothing will happen to you in another field.”'),
  ('BSB', 'Ruth', 8, 2, 23, 'So Ruth stayed close to the servant girls of Boaz to glean grain until the barley and wheat harvests were finished. And she lived with her mother-in-law.'),
  ('BSB', 'Ruth', 8, 3, 1, 'One day Ruth’s mother-in-law Naomi said to her, “My daughter, should I not seek a resting place for you, that it may be well with you?'),
  ('BSB', 'Ruth', 8, 3, 2, 'Now is not Boaz, with whose servant girls you have been working, a relative of ours? In fact, tonight he is winnowing barley on the threshing floor.'),
  ('BSB', 'Ruth', 8, 3, 3, 'Therefore wash yourself, put on perfume, and wear your best clothes. Go down to the threshing floor, but do not let the man know you are there until he has finished eating and drinking.'),
  ('BSB', 'Ruth', 8, 3, 4, 'When he lies down, note the place where he lies. Then go in and uncover his feet, and lie down, and he will explain to you what you should do.”'),
  ('BSB', 'Ruth', 8, 3, 5, '“I will do everything you say,” Ruth answered.'),
  ('BSB', 'Ruth', 8, 3, 6, 'So she went down to the threshing floor and did everything her mother-in-law had instructed her to do.'),
  ('BSB', 'Ruth', 8, 3, 7, 'After Boaz had finished eating and drinking and was in good spirits, he went to lie down at the end of the heap of grain. Then Ruth went in secretly, uncovered his feet, and lay down.'),
  ('BSB', 'Ruth', 8, 3, 8, 'At midnight, Boaz was startled, turned over, and there lying at his feet was a woman!'),
  ('BSB', 'Ruth', 8, 3, 9, '“Who are you?” he asked. “I am your servant Ruth,” she replied. “Spread the corner of your garment over me, for you are a kinsman-redeemer.”'),
  ('BSB', 'Ruth', 8, 3, 10, 'Then Boaz said, “May the LORD bless you, my daughter. You have shown more kindness now than before, because you have not run after the younger men, whether rich or poor.'),
  ('BSB', 'Ruth', 8, 3, 11, 'And now do not be afraid, my daughter. I will do for you whatever you request, since all my fellow townspeople know that you are a woman of noble character.'),
  ('BSB', 'Ruth', 8, 3, 12, 'Yes, it is true that I am a kinsman-redeemer, but there is a redeemer nearer than I.'),
  ('BSB', 'Ruth', 8, 3, 13, 'Stay here tonight, and in the morning, if he wants to redeem you, good. Let him redeem you. But if he does not want to redeem you, as surely as the LORD lives, I will. Now lie here until morning.”'),
  ('BSB', 'Ruth', 8, 3, 14, 'So she lay down at his feet until morning, but she got up before anyone else could recognize her. Then Boaz said, “Do not let it be known that a woman came to the threshing floor.”'),
  ('BSB', 'Ruth', 8, 3, 15, 'And he told her, “Bring the shawl you are wearing and hold it out.” When she did so, he shoveled six measures of barley into her shawl. Then he went into the city.'),
  ('BSB', 'Ruth', 8, 3, 16, 'When Ruth returned to her mother-in-law, Naomi asked her, “How did it go, my daughter?” Then Ruth told her all that Boaz had done for her.'),
  ('BSB', 'Ruth', 8, 3, 17, 'And she said, “He gave me these six measures of barley, for he said, ‘Do not go back to your mother-in-law empty-handed.’”'),
  ('BSB', 'Ruth', 8, 3, 18, '“Wait, my daughter,” said Naomi, “until you find out how things go, for he will not rest unless he has resolved the matter today.”'),
  ('BSB', 'Ruth', 8, 4, 1, 'Meanwhile, Boaz went to the gate and sat down there. Soon the kinsman-redeemer of whom he had spoken came along, and Boaz said, “Come over here, my friend, and sit down.” So he went over and sat down.'),
  ('BSB', 'Ruth', 8, 4, 2, 'Then Boaz took ten of the elders of the city and said, “Sit here,” and they did so.'),
  ('BSB', 'Ruth', 8, 4, 3, 'And he said to the kinsman-redeemer, “Naomi, who has returned from the land of Moab, is selling the piece of land that belonged to our brother Elimelech.'),
  ('BSB', 'Ruth', 8, 4, 4, 'I thought I should inform you that you may buy it back in the presence of those seated here and in the presence of the elders of my people. If you want to redeem it, do so. But if you will not redeem it, tell me so I may know, because there is no one but you to redeem it, and I am next after you.” “I will redeem it,” he replied.'),
  ('BSB', 'Ruth', 8, 4, 5, 'Then Boaz said, “On the day you buy the land from Naomi and also from Ruth the Moabitess, you must also acquire the widow of the deceased in order to raise up the name of the deceased on his inheritance.”'),
  ('BSB', 'Ruth', 8, 4, 6, 'The kinsman-redeemer replied, “I cannot redeem it myself, or I would jeopardize my own inheritance. Take my right of redemption, because I cannot redeem it.”'),
  ('BSB', 'Ruth', 8, 4, 7, 'Now in former times in Israel, concerning the redemption or exchange of property, to make any matter legally binding a man would remove his sandal and give it to the other party, and this was a confirmation in Israel.'),
  ('BSB', 'Ruth', 8, 4, 8, 'So the kinsman-redeemer removed his sandal and said to Boaz, “Buy it for yourself.”'),
  ('BSB', 'Ruth', 8, 4, 9, 'At this, Boaz said to the elders and all the people, “You are witnesses today that I am buying from Naomi all that belonged to Elimelech, Chilion, and Mahlon.');
insert into control_room_bible (version, book, book_num, chapter, verse, text) values
  ('BSB', 'Ruth', 8, 4, 10, 'Moreover, I have acquired Ruth the Moabitess, Mahlon’s widow, as my wife, to raise up the name of the deceased through his inheritance, so that his name will not disappear from among his brothers or from the gate of his home. You are witnesses today.”'),
  ('BSB', 'Ruth', 8, 4, 11, '“We are witnesses,” said the elders and all the people at the gate. “May the LORD make the woman entering your home like Rachel and Leah, who together built up the house of Israel. May you be prosperous in Ephrathah and famous in Bethlehem.'),
  ('BSB', 'Ruth', 8, 4, 12, 'And may your house become like the house of Perez, whom Tamar bore to Judah, because of the offspring the LORD will give you by this young woman.”'),
  ('BSB', 'Ruth', 8, 4, 13, 'So Boaz took Ruth, and she became his wife. And when he had relations with her, the LORD enabled her to conceive, and she gave birth to a son.'),
  ('BSB', 'Ruth', 8, 4, 14, 'Then the women said to Naomi, “Blessed be the LORD, who has not left you this day without a kinsman-redeemer. May his name become famous in Israel.'),
  ('BSB', 'Ruth', 8, 4, 15, 'He will renew your life and sustain you in your old age. For your daughter-in-law, who loves you and is better to you than seven sons, has given him birth.”'),
  ('BSB', 'Ruth', 8, 4, 16, 'And Naomi took the child, placed him on her lap, and became a nurse to him.'),
  ('BSB', 'Ruth', 8, 4, 17, 'The neighbor women said, “A son has been born to Naomi,” and they named him Obed. He became the father of Jesse, the father of David.'),
  ('BSB', 'Ruth', 8, 4, 18, 'Now these are the generations of Perez: Perez was the father of Hezron,'),
  ('BSB', 'Ruth', 8, 4, 19, 'Hezron was the father of Ram, Ram was the father of Amminadab,'),
  ('BSB', 'Ruth', 8, 4, 20, 'Amminadab was the father of Nahshon, Nahshon was the father of Salmon,'),
  ('BSB', 'Ruth', 8, 4, 21, 'Salmon was the father of Boaz, Boaz was the father of Obed,'),
  ('BSB', 'Ruth', 8, 4, 22, 'Obed was the father of Jesse, and Jesse was the father of David.'),
  ('BSB', '1 Samuel', 9, 1, 1, 'Now there was a man named Elkanah who was from Ramathaim-zophim in the hill country of Ephraim. He was the son of Jeroham, the son of Elihu, the son of Tohu, the son of Zuph, an Ephraimite.'),
  ('BSB', '1 Samuel', 9, 1, 2, 'He had two wives, one named Hannah and the other Peninnah. And Peninnah had children, but Hannah had none.'),
  ('BSB', '1 Samuel', 9, 1, 3, 'Year after year Elkanah would go up from his city to worship and sacrifice to the LORD of Hosts at Shiloh, where Eli’s two sons, Hophni and Phinehas, were priests to the LORD.'),
  ('BSB', '1 Samuel', 9, 1, 4, 'And whenever the day came for Elkanah to present his sacrifice, he would give portions to his wife Peninnah and to all her sons and daughters.'),
  ('BSB', '1 Samuel', 9, 1, 5, 'But to Hannah he would give a double portion, for he loved her even though the LORD had closed her womb.'),
  ('BSB', '1 Samuel', 9, 1, 6, 'Because the LORD had closed Hannah’s womb, her rival would provoke her and taunt her viciously.'),
  ('BSB', '1 Samuel', 9, 1, 7, 'And this went on year after year. Whenever Hannah went up to the house of the LORD, her rival taunted her until she wept and would not eat.'),
  ('BSB', '1 Samuel', 9, 1, 8, '“Hannah, why are you crying?” her husband Elkanah asked. “Why won’t you eat? Why is your heart so grieved? Am I not better to you than ten sons?”'),
  ('BSB', '1 Samuel', 9, 1, 9, 'So after they had finished eating and drinking in Shiloh, Hannah stood up. Now Eli the priest was sitting on a chair by the doorpost of the temple of the LORD.'),
  ('BSB', '1 Samuel', 9, 1, 10, 'In her bitter distress, Hannah prayed to the LORD and wept with many tears.'),
  ('BSB', '1 Samuel', 9, 1, 11, 'And she made a vow, pleading, “O LORD of Hosts, if only You will look upon the affliction of Your maidservant and remember me, not forgetting Your maidservant but giving her a son, then I will dedicate him to the LORD all the days of his life, and no razor shall ever come over his head.”'),
  ('BSB', '1 Samuel', 9, 1, 12, 'As Hannah kept on praying before the LORD, Eli watched her mouth.'),
  ('BSB', '1 Samuel', 9, 1, 13, 'Hannah was praying in her heart, and though her lips were moving, her voice could not be heard. So Eli thought she was drunk'),
  ('BSB', '1 Samuel', 9, 1, 14, 'and said to her, “How long will you be drunk? Put away your wine!”'),
  ('BSB', '1 Samuel', 9, 1, 15, '“No, my lord,” Hannah replied. “I am a woman oppressed in spirit. I have not had any wine or strong drink, but I have poured out my soul before the LORD.'),
  ('BSB', '1 Samuel', 9, 1, 16, 'Do not take your servant for a wicked woman; for all this time I have been praying out of the depth of my anguish and grief.”'),
  ('BSB', '1 Samuel', 9, 1, 17, '“Go in peace,” Eli replied, “and may the God of Israel grant the petition you have asked of Him.”'),
  ('BSB', '1 Samuel', 9, 1, 18, '“May your maidservant find favor with you,” said Hannah. Then she went on her way, and she began eating again, and her face was no longer downcast.'),
  ('BSB', '1 Samuel', 9, 1, 19, 'The next morning Elkanah and Hannah got up early to bow in worship before the LORD, and then returned home to Ramah. And Elkanah had relations with his wife Hannah, and the LORD remembered her.'),
  ('BSB', '1 Samuel', 9, 1, 20, 'So in the course of time, Hannah conceived and gave birth to a son. She named him Samuel, saying, “Because I have asked for him from the LORD.”'),
  ('BSB', '1 Samuel', 9, 1, 21, 'Then Elkanah and all his house went up to make the annual sacrifice to the LORD and to fulfill his vow,'),
  ('BSB', '1 Samuel', 9, 1, 22, 'but Hannah did not go. “After the boy is weaned,” she said to her husband, “I will take him to appear before the LORD and to stay there permanently.”'),
  ('BSB', '1 Samuel', 9, 1, 23, '“Do what you think is best,” her husband Elkanah replied, “and stay here until you have weaned him. Only may the LORD confirm His word.” So Hannah stayed and nursed her son until she had weaned him.'),
  ('BSB', '1 Samuel', 9, 1, 24, 'Once she had weaned him, Hannah took the boy with her, along with a three-year-old bull, an ephah of flour, and a skin of wine. Though the boy was still young, she brought him to the house of the LORD at Shiloh.'),
  ('BSB', '1 Samuel', 9, 1, 25, 'And when they had slaughtered the bull, they brought the boy to Eli.'),
  ('BSB', '1 Samuel', 9, 1, 26, '“Please, my lord,” said Hannah, “as surely as you live, my lord, I am the woman who stood here beside you praying to the LORD.'),
  ('BSB', '1 Samuel', 9, 1, 27, 'I prayed for this boy, and since the LORD has granted me what I asked of Him,'),
  ('BSB', '1 Samuel', 9, 1, 28, 'I now dedicate the boy to the LORD. For as long as he lives, he is dedicated to the LORD.” So they worshiped the LORD there.'),
  ('BSB', '1 Samuel', 9, 2, 1, 'At that time Hannah prayed: “My heart rejoices in the LORD in whom my horn is exalted. My mouth speaks boldly against my enemies, for I rejoice in Your salvation.'),
  ('BSB', '1 Samuel', 9, 2, 2, 'There is no one holy like the LORD. Indeed, there is no one besides You! And there is no Rock like our God.'),
  ('BSB', '1 Samuel', 9, 2, 3, 'Do not boast so proudly, or let arrogance come from your mouth, for the LORD is a God who knows, and by Him actions are weighed.'),
  ('BSB', '1 Samuel', 9, 2, 4, 'The bows of the mighty are broken, but the feeble are equipped with strength.'),
  ('BSB', '1 Samuel', 9, 2, 5, 'The well-fed hire themselves out for food, but the starving hunger no more. The barren woman gives birth to seven, but she who has many sons pines away.'),
  ('BSB', '1 Samuel', 9, 2, 6, 'The LORD brings death and gives life; He brings down to Sheol and raises up.'),
  ('BSB', '1 Samuel', 9, 2, 7, 'The LORD sends poverty and wealth; He humbles and He exalts.'),
  ('BSB', '1 Samuel', 9, 2, 8, 'He raises the poor from the dust and lifts the needy from the ash heap. He seats them among princes and bestows on them a throne of honor. For the foundations of the earth are the LORD’s, and upon them He has set the world.'),
  ('BSB', '1 Samuel', 9, 2, 9, 'He guards the steps of His faithful ones, but the wicked perish in darkness; for by his own strength shall no man prevail.'),
  ('BSB', '1 Samuel', 9, 2, 10, 'Those who oppose the LORD will be shattered. He will thunder from heaven against them. The LORD will judge the ends of the earth and will give power to His king. He will exalt the horn of His anointed.”'),
  ('BSB', '1 Samuel', 9, 2, 11, 'Then Elkanah went home to Ramah, but the boy began ministering to the LORD before Eli the priest.'),
  ('BSB', '1 Samuel', 9, 2, 12, 'Now the sons of Eli were wicked men; they had no regard for the LORD'),
  ('BSB', '1 Samuel', 9, 2, 13, 'or for the custom of the priests with the people. When any man offered a sacrifice, the servant of the priest would come with a three-pronged meat fork while the meat was boiling'),
  ('BSB', '1 Samuel', 9, 2, 14, 'and plunge it into the pan or kettle or cauldron or cooking pot. And the priest would claim for himself whatever the meat fork brought up. This is how they treated all the Israelites who came to Shiloh.'),
  ('BSB', '1 Samuel', 9, 2, 15, 'Even before the fat was burned, the servant of the priest would come and say to the man who was sacrificing, “Give the priest some meat to roast, because he will not accept boiled meat from you, but only raw.”'),
  ('BSB', '1 Samuel', 9, 2, 16, 'And if any man said to him, “The fat must be burned first; then you may take whatever you want,” the servant would reply, “No, you must give it to me right now. If you refuse, I will take it by force!”'),
  ('BSB', '1 Samuel', 9, 2, 17, 'Thus the sin of these young men was severe in the sight of the LORD, for they were treating the LORD’s offering with contempt.'),
  ('BSB', '1 Samuel', 9, 2, 18, 'Now Samuel was ministering before the LORD—a boy wearing a linen ephod.'),
  ('BSB', '1 Samuel', 9, 2, 19, 'Each year his mother would make him a little robe and bring it to him when she went with her husband to offer the annual sacrifice.'),
  ('BSB', '1 Samuel', 9, 2, 20, 'And Eli would bless Elkanah and his wife, saying, “May the LORD give you children by this woman in place of the one she dedicated to the LORD.” Then they would go home.'),
  ('BSB', '1 Samuel', 9, 2, 21, 'So the LORD attended to Hannah, and she conceived and gave birth to three sons and two daughters. Meanwhile, the boy Samuel grew up in the presence of the LORD.'),
  ('BSB', '1 Samuel', 9, 2, 22, 'Now Eli was very old, and he heard about everything his sons were doing to all Israel and how they were sleeping with the women who served at the entrance to the Tent of Meeting.'),
  ('BSB', '1 Samuel', 9, 2, 23, '“Why are you doing these things?” Eli said to his sons. “I hear about your wicked deeds from all these people.'),
  ('BSB', '1 Samuel', 9, 2, 24, 'No, my sons; it is not a good report I hear circulating among the LORD’s people.'),
  ('BSB', '1 Samuel', 9, 2, 25, 'If a man sins against another man, God can intercede for him; but if a man sins against the LORD, who can intercede for him?” But they would not listen to their father, since the LORD intended to put them to death.'),
  ('BSB', '1 Samuel', 9, 2, 26, 'And the boy Samuel continued to grow in stature and in favor with the LORD and with man.'),
  ('BSB', '1 Samuel', 9, 2, 27, 'Then a man of God came to Eli and told him, “This is what the LORD says: ‘Did I not clearly reveal Myself to your father’s house when they were in Egypt under Pharaoh’s house?'),
  ('BSB', '1 Samuel', 9, 2, 28, 'And out of all the tribes of Israel I selected your father to be My priest, to offer sacrifices on My altar, to burn incense, and to wear an ephod in My presence. I also gave to the house of your father all the offerings of the Israelites made by fire.'),
  ('BSB', '1 Samuel', 9, 2, 29, 'Why then do you kick at My sacrifice and offering that I have prescribed for My dwelling place? You have honored your sons more than Me by fattening yourselves with the best of all the offerings of My people Israel.’'),
  ('BSB', '1 Samuel', 9, 2, 30, 'Therefore, the LORD, the God of Israel, declares: ‘I did indeed say that your house and the house of your father would walk before Me forever. But now the LORD declares: Far be it from Me! For I will honor those who honor Me, but those who despise Me will be disdained.'),
  ('BSB', '1 Samuel', 9, 2, 31, 'Behold, the days are coming when I will cut off your strength and the strength of your father’s house, so that no older man will be left in your house.'),
  ('BSB', '1 Samuel', 9, 2, 32, 'You will see distress in My dwelling place. Despite all that is good in Israel, no one in your house will ever again reach old age.'),
  ('BSB', '1 Samuel', 9, 2, 33, 'And every one of you that I do not cut off from My altar, your eyes will fail and your heart will grieve. All your descendants will die by the sword of men.'),
  ('BSB', '1 Samuel', 9, 2, 34, 'And this sign shall come to you concerning your two sons Hophni and Phinehas: They will both die on the same day.'),
  ('BSB', '1 Samuel', 9, 2, 35, 'Then I will raise up for Myself a faithful priest. He will do whatever is in My heart and mind. And I will build for him an enduring house, and he will walk before My anointed one for all time.'),
  ('BSB', '1 Samuel', 9, 2, 36, 'And everyone left in your house will come and bow down to him for a piece of silver or a morsel of bread, pleading, “Please appoint me to some priestly office so that I can eat a piece of bread.”’”'),
  ('BSB', '1 Samuel', 9, 3, 1, 'And the boy Samuel ministered to the LORD before Eli. Now in those days the word of the LORD was rare and visions were scarce.'),
  ('BSB', '1 Samuel', 9, 3, 2, 'And at that time Eli, whose eyesight had grown so dim that he could not see, was lying in his room.'),
  ('BSB', '1 Samuel', 9, 3, 3, 'Before the lamp of God had gone out, Samuel was lying down in the temple of the LORD, where the ark of God was located.'),
  ('BSB', '1 Samuel', 9, 3, 4, 'Then the LORD called to Samuel, and he answered, “Here I am.”'),
  ('BSB', '1 Samuel', 9, 3, 5, 'He ran to Eli and said, “Here I am, for you have called me.” “I did not call,” Eli replied. “Go back and lie down.” So he went and lay down.'),
  ('BSB', '1 Samuel', 9, 3, 6, 'Once again the LORD called, “Samuel!” So Samuel got up, went to Eli, and said, “Here I am, for you have called me.” “My son, I did not call,” Eli replied. “Go back and lie down.”'),
  ('BSB', '1 Samuel', 9, 3, 7, 'Now Samuel did not yet know the LORD, because the word of the LORD had not yet been revealed to him.'),
  ('BSB', '1 Samuel', 9, 3, 8, 'Once again, for the third time, the LORD called to Samuel. He got up, went to Eli, and said, “Here I am, for you have called me.” Then Eli realized that it was the LORD who was calling the boy.'),
  ('BSB', '1 Samuel', 9, 3, 9, '“Go and lie down,” he said to Samuel, “and if He calls you, say, ‘Speak, LORD, for Your servant is listening.’” So Samuel went and lay down in his place.'),
  ('BSB', '1 Samuel', 9, 3, 10, 'Then the LORD came and stood there, calling as before, “Samuel! Samuel!” And Samuel answered, “Speak, for Your servant is listening.”'),
  ('BSB', '1 Samuel', 9, 3, 11, 'Then the LORD said to Samuel, “I am about to do something in Israel at which the ears of all who hear it will tingle.'),
  ('BSB', '1 Samuel', 9, 3, 12, 'On that day I will carry out against Eli everything I have spoken about his family, from beginning to end.'),
  ('BSB', '1 Samuel', 9, 3, 13, 'I told him that I would judge his house forever for the iniquity of which he knows, because his sons blasphemed God and he did not restrain them.'),
  ('BSB', '1 Samuel', 9, 3, 14, 'Therefore I have sworn to the house of Eli, ‘The iniquity of Eli’s house shall never be atoned for by sacrifice or offering.’”'),
  ('BSB', '1 Samuel', 9, 3, 15, 'Samuel lay down until the morning; then he opened the doors of the house of the LORD. He was afraid to tell Eli the vision,'),
  ('BSB', '1 Samuel', 9, 3, 16, 'but Eli called to him and said, “Samuel, my son.” “Here I am,” answered Samuel.'),
  ('BSB', '1 Samuel', 9, 3, 17, '“What was the message He gave you?” Eli asked. “Do not hide it from me. May God punish you, and ever so severely, if you hide from me anything He said to you.”'),
  ('BSB', '1 Samuel', 9, 3, 18, 'So Samuel told him everything and did not hide a thing from him. “He is the LORD,” replied Eli. “Let Him do what is good in His eyes.”'),
  ('BSB', '1 Samuel', 9, 3, 19, 'And Samuel grew, and the LORD was with him, and He let none of Samuel’s words fall to the ground.'),
  ('BSB', '1 Samuel', 9, 3, 20, 'So all Israel from Dan to Beersheba knew that Samuel was confirmed as a prophet of the LORD.'),
  ('BSB', '1 Samuel', 9, 3, 21, 'And the LORD continued to appear at Shiloh, because there He revealed Himself to Samuel by His word.'),
  ('BSB', '1 Samuel', 9, 4, 1, 'Thus the word of Samuel came to all Israel. Now the Israelites went out to meet the Philistines in battle and camped at Ebenezer, while the Philistines camped at Aphek.'),
  ('BSB', '1 Samuel', 9, 4, 2, 'The Philistines arrayed themselves against Israel, and as the battle spread, Israel was defeated by the Philistines, who struck down about four thousand men on the battlefield.'),
  ('BSB', '1 Samuel', 9, 4, 3, 'When the troops returned to the camp, the elders of Israel asked, “Why has the LORD brought defeat on us before the Philistines today? Let us bring the ark of the covenant of the LORD from Shiloh, so that it may go with us to save us from the hand of our enemies.”'),
  ('BSB', '1 Samuel', 9, 4, 4, 'So the people sent men to Shiloh, and they brought back the ark of the covenant of the LORD of Hosts, who sits enthroned between the cherubim. And the two sons of Eli, Hophni and Phinehas, were there with the ark of the covenant of God.'),
  ('BSB', '1 Samuel', 9, 4, 5, 'When the ark of the covenant of the LORD entered the camp, all the Israelites raised such a great shout that it shook the ground.'),
  ('BSB', '1 Samuel', 9, 4, 6, 'On hearing the noise of the shout, the Philistines asked, “What is this loud shouting in the camp of the Hebrews?” And when they realized that the ark of the LORD had entered the camp,'),
  ('BSB', '1 Samuel', 9, 4, 7, 'the Philistines were afraid. “The gods have entered their camp!” they said. “Woe to us, for nothing like this has happened before.'),
  ('BSB', '1 Samuel', 9, 4, 8, 'Woe to us! Who will deliver us from the hand of these mighty gods? These are the gods who struck the Egyptians with all kinds of plagues in the wilderness.'),
  ('BSB', '1 Samuel', 9, 4, 9, 'Take courage and be men, O Philistines! Otherwise, you will serve the Hebrews just as they served you. Now be men and fight!”'),
  ('BSB', '1 Samuel', 9, 4, 10, 'So the Philistines fought, and Israel was defeated, and each man fled to his tent. The slaughter was very great—thirty thousand foot soldiers of Israel fell.'),
  ('BSB', '1 Samuel', 9, 4, 11, 'The ark of God was captured, and Eli’s two sons, Hophni and Phinehas, died.'),
  ('BSB', '1 Samuel', 9, 4, 12, 'That same day a Benjamite ran from the battle line all the way to Shiloh, with his clothes torn and dirt on his head.'),
  ('BSB', '1 Samuel', 9, 4, 13, 'When he arrived, there was Eli, sitting on his chair beside the road and watching, because his heart trembled for the ark of God. When the man entered the city to give a report, the whole city cried out.'),
  ('BSB', '1 Samuel', 9, 4, 14, 'Eli heard the outcry and asked, “Why this commotion?” So the man hurried over and reported to Eli.'),
  ('BSB', '1 Samuel', 9, 4, 15, 'Now Eli was ninety-eight years old, and his gaze was fixed because he could not see.'),
  ('BSB', '1 Samuel', 9, 4, 16, '“I have just come from the battle,” the man said to Eli. “I fled from there today.” “What happened, my son?” Eli asked.'),
  ('BSB', '1 Samuel', 9, 4, 17, 'The messenger answered, “Israel has fled before the Philistines, and there has been a great slaughter among the people. Your two sons, Hophni and Phinehas, are both dead, and the ark of God has been captured.”'),
  ('BSB', '1 Samuel', 9, 4, 18, 'As soon as the ark of God was mentioned, Eli fell backward from his chair by the city gate, and being old and heavy, he broke his neck and died. And Eli had judged Israel forty years.'),
  ('BSB', '1 Samuel', 9, 4, 19, 'Now Eli’s daughter-in-law, the wife of Phinehas, was pregnant and about to give birth. When she heard the news of the capture of God’s ark and the deaths of her father-in-law and her husband, she collapsed and gave birth, for her labor pains overtook her.'),
  ('BSB', '1 Samuel', 9, 4, 20, 'As she was dying, the women attending to her said, “Do not be afraid, for you have given birth to a son!” But she did not respond or pay any heed.'),
  ('BSB', '1 Samuel', 9, 4, 21, 'And she named the boy Ichabod, saying, “The glory has departed from Israel,” because the ark of God had been captured and her father-in-law and her husband had been killed.'),
  ('BSB', '1 Samuel', 9, 4, 22, '“The glory has departed from Israel,” she said, “for the ark of God has been captured.”'),
  ('BSB', '1 Samuel', 9, 5, 1, 'After the Philistines had captured the ark of God, they took it from Ebenezer to Ashdod,'),
  ('BSB', '1 Samuel', 9, 5, 2, 'carried it into the temple of Dagon, and set it beside his statue.'),
  ('BSB', '1 Samuel', 9, 5, 3, 'When the people of Ashdod got up early the next morning, there was Dagon, fallen on his face before the ark of the LORD. So they took Dagon and returned him to his place.'),
  ('BSB', '1 Samuel', 9, 5, 4, 'But when they got up early the next morning, there was Dagon, fallen on his face before the ark of the LORD, with his head and his hands broken off and lying on the threshold. Only the torso remained.'),
  ('BSB', '1 Samuel', 9, 5, 5, 'That is why, to this day, the priests of Dagon and all who enter the temple of Dagon in Ashdod do not step on the threshold.'),
  ('BSB', '1 Samuel', 9, 5, 6, 'Now the hand of the LORD was heavy on the people of Ashdod and its vicinity, ravaging them and afflicting them with tumors.'),
  ('BSB', '1 Samuel', 9, 5, 7, 'And when the men of Ashdod saw what was happening, they said, “The ark of the God of Israel must not stay here with us, because His hand is heavy upon us and upon our god Dagon.”'),
  ('BSB', '1 Samuel', 9, 5, 8, 'So they called together all the rulers of the Philistines and asked, “What shall we do with the ark of the God of Israel?” “It must be moved to Gath,” they replied. So they carried away the ark of the God of Israel.'),
  ('BSB', '1 Samuel', 9, 5, 9, 'But after they had moved the ark to Gath, the LORD’s hand was also against that city, throwing it into great confusion and afflicting the men of the city, both young and old, with an outbreak of tumors.'),
  ('BSB', '1 Samuel', 9, 5, 10, 'So they sent the ark of God to Ekron, but as it arrived, the Ekronites cried out, “They have brought us the ark of the God of Israel in order to kill us and our people!”'),
  ('BSB', '1 Samuel', 9, 5, 11, 'Then the Ekronites assembled all the rulers of the Philistines and said, “Send away the ark of the God of Israel. It must return to its place, so that it will not kill us and our people!” For a deadly confusion had pervaded the city; the hand of God was heavy upon it.'),
  ('BSB', '1 Samuel', 9, 5, 12, 'Those who did not die were afflicted with tumors, and the outcry of the city went up to heaven.'),
  ('BSB', '1 Samuel', 9, 6, 1, 'When the ark of the LORD had been in the land of the Philistines seven months,'),
  ('BSB', '1 Samuel', 9, 6, 2, 'the Philistines summoned the priests and diviners, saying, “What shall we do with the ark of the LORD? Tell us how to send it back to its place.”'),
  ('BSB', '1 Samuel', 9, 6, 3, 'They replied, “If you return the ark of the God of Israel, do not send it away empty, but by all means return it to Him with a guilt offering. Then you will be healed, and you will understand why His hand has not been lifted from you.”'),
  ('BSB', '1 Samuel', 9, 6, 4, '“What guilt offering should we send back to Him?” asked the Philistines. “Five gold tumors and five gold rats,” they said, “according to the number of rulers of the Philistines, since the same plague has struck both you and your rulers.'),
  ('BSB', '1 Samuel', 9, 6, 5, 'Make images of your tumors and of the rats that are ravaging the land. Give glory to the God of Israel, and perhaps He will lift His hand from you and your gods and your land.'),
  ('BSB', '1 Samuel', 9, 6, 6, 'Why harden your hearts as the Egyptians and Pharaoh hardened theirs? When He afflicted them, did they not send the people on their way as they departed?'),
  ('BSB', '1 Samuel', 9, 6, 7, 'Now, therefore, prepare one new cart with two milk cows that have never been yoked. Hitch the cows to the cart, but take their calves away and pen them up.'),
  ('BSB', '1 Samuel', 9, 6, 8, 'Take the ark of the LORD, set it on the cart, and in a chest beside it put the gold objects you are sending Him as a guilt offering. Then send the ark on its way,'),
  ('BSB', '1 Samuel', 9, 6, 9, 'but keep watching it. If it goes up the road to its homeland, toward Beth-shemesh, it is the LORD who has brought on us this great disaster. But if it does not, then we will know that it was not His hand that punished us and that it happened by chance.”'),
  ('BSB', '1 Samuel', 9, 6, 10, 'So the men did as instructed. They took two milk cows, hitched them to the cart, and penned up their calves.'),
  ('BSB', '1 Samuel', 9, 6, 11, 'Then they put the ark of the LORD on the cart, along with the chest containing the gold rats and the images of the tumors.'),
  ('BSB', '1 Samuel', 9, 6, 12, 'And the cows headed straight up the road toward Beth-shemesh, staying on that one highway and lowing as they went, never straying to the right or to the left. The rulers of the Philistines followed behind them to the border of Beth-shemesh.'),
  ('BSB', '1 Samuel', 9, 6, 13, 'Now the people of Beth-shemesh were harvesting wheat in the valley, and when they looked up and saw the ark, they were overjoyed at the sight.'),
  ('BSB', '1 Samuel', 9, 6, 14, 'The cart came to the field of Joshua of Beth-shemesh and stopped there near a large rock. The people chopped up the cart and offered the cows as a burnt offering to the LORD.'),
  ('BSB', '1 Samuel', 9, 6, 15, 'And the Levites took down the ark of the LORD and the chest containing the gold objects, and they placed them on the large rock. That day the men of Beth-shemesh offered burnt offerings and made sacrifices to the LORD.'),
  ('BSB', '1 Samuel', 9, 6, 16, 'And when the five rulers of the Philistines saw this, they returned to Ekron that same day.'),
  ('BSB', '1 Samuel', 9, 6, 17, 'As a guilt offering to the LORD, the Philistines had sent back one gold tumor for each city: Ashdod, Gaza, Ashkelon, Gath, and Ekron.'),
  ('BSB', '1 Samuel', 9, 6, 18, 'The number of gold rats also corresponded to the number of Philistine cities belonging to the five rulers—the fortified cities and their outlying villages. And the large rock on which they placed the ark of the LORD stands to this day in the field of Joshua of Beth-shemesh.'),
  ('BSB', '1 Samuel', 9, 6, 19, 'But God struck down some of the people of Beth-shemesh because they looked inside the ark of the LORD. He struck down seventy men, and the people mourned because the LORD had struck them with a great slaughter.'),
  ('BSB', '1 Samuel', 9, 6, 20, 'The men of Beth-shemesh asked, “Who can stand in the presence of the LORD, this holy God? To whom should the ark go up from here?”'),
  ('BSB', '1 Samuel', 9, 6, 21, 'So they sent messengers to the people of Kiriath-jearim, saying, “The Philistines have returned the ark of the LORD. Come down and take it up with you.”'),
  ('BSB', '1 Samuel', 9, 7, 1, 'Then the men of Kiriath-jearim came for the ark of the LORD and took it into Abinadab’s house on the hill. And they consecrated his son Eleazar to guard the ark of the LORD.'),
  ('BSB', '1 Samuel', 9, 7, 2, 'And from that day a long time passed, twenty years in all, as the ark remained at Kiriath-jearim. And all the house of Israel mourned and sought after the LORD.'),
  ('BSB', '1 Samuel', 9, 7, 3, 'Then Samuel said to all the house of Israel, “If you are returning to the LORD with all your hearts, then rid yourselves of the foreign gods and Ashtoreths among you, prepare your hearts for the LORD, and serve Him only. And He will deliver you from the hand of the Philistines.”'),
  ('BSB', '1 Samuel', 9, 7, 4, 'So the Israelites put away the Baals and Ashtoreths and served only the LORD.'),
  ('BSB', '1 Samuel', 9, 7, 5, 'Then Samuel said, “Gather all Israel to Mizpah, and I will pray to the LORD on your behalf.”'),
  ('BSB', '1 Samuel', 9, 7, 6, 'When they had gathered at Mizpah, they drew water and poured it out before the LORD. On that day they fasted, and there they confessed, “We have sinned against the LORD.” And Samuel judged the Israelites at Mizpah.'),
  ('BSB', '1 Samuel', 9, 7, 7, 'When the Philistines heard that the Israelites had gathered at Mizpah, their rulers marched up toward Israel. And when the Israelites learned of this, they feared the Philistines'),
  ('BSB', '1 Samuel', 9, 7, 8, 'and said to Samuel, “Do not stop crying out to the LORD our God for us, that He may save us from the hand of the Philistines.”'),
  ('BSB', '1 Samuel', 9, 7, 9, 'Then Samuel took a suckling lamb and offered it as a whole burnt offering to the LORD. He cried out to the LORD on behalf of Israel, and the LORD answered him.'),
  ('BSB', '1 Samuel', 9, 7, 10, 'As the Philistines drew near to fight against Israel, Samuel was sacrificing the burnt offering. But that day the LORD thundered loudly against the Philistines and threw them into such confusion that they fled before Israel.'),
  ('BSB', '1 Samuel', 9, 7, 11, 'Then the men of Israel charged out of Mizpah and pursued the Philistines, striking them down all the way to an area below Beth-car.'),
  ('BSB', '1 Samuel', 9, 7, 12, 'Afterward, Samuel took a stone and set it up between Mizpah and Shen. He named it Ebenezer, saying, “Thus far the LORD has helped us.”'),
  ('BSB', '1 Samuel', 9, 7, 13, 'So the Philistines were subdued, and they stopped invading the territory of Israel. And the hand of the LORD was against the Philistines all the days of Samuel.'),
  ('BSB', '1 Samuel', 9, 7, 14, 'The cities from Ekron to Gath, which the Philistines had taken, were restored to Israel, who also delivered the surrounding territory from the hand of the Philistines. And there was peace between the Israelites and the Amorites.'),
  ('BSB', '1 Samuel', 9, 7, 15, 'So Samuel judged Israel all the days of his life.'),
  ('BSB', '1 Samuel', 9, 7, 16, 'Every year he would go on a circuit from Bethel to Gilgal to Mizpah, judging Israel in all these places.'),
  ('BSB', '1 Samuel', 9, 7, 17, 'Then he would return to Ramah because his home was there, and there he judged Israel and built an altar to the LORD.'),
  ('BSB', '1 Samuel', 9, 8, 1, 'When Samuel grew old, he appointed his sons as judges over Israel.'),
  ('BSB', '1 Samuel', 9, 8, 2, 'The name of his firstborn son was Joel, and the name of his second was Abijah. They were judges in Beersheba.'),
  ('BSB', '1 Samuel', 9, 8, 3, 'But his sons did not walk in his ways; they turned aside toward dishonest gain, accepting bribes and perverting justice.'),
  ('BSB', '1 Samuel', 9, 8, 4, 'So all the elders of Israel gathered together and came to Samuel at Ramah.'),
  ('BSB', '1 Samuel', 9, 8, 5, '“Look,” they said, “you are old, and your sons do not walk in your ways. Now appoint a king to judge us like all the other nations.”'),
  ('BSB', '1 Samuel', 9, 8, 6, 'But when they said, “Give us a king to judge us,” their demand was displeasing in the sight of Samuel; so he prayed to the LORD.'),
  ('BSB', '1 Samuel', 9, 8, 7, 'And the LORD said to Samuel, “Listen to the voice of the people in all that they say to you. For it is not you they have rejected, but they have rejected Me as their king.'),
  ('BSB', '1 Samuel', 9, 8, 8, 'Just as they have done from the day I brought them up out of Egypt until this day, forsaking Me and serving other gods, so they are doing to you.'),
  ('BSB', '1 Samuel', 9, 8, 9, 'Now listen to them, but you must solemnly warn them and show them the manner of the king who will reign over them.”'),
  ('BSB', '1 Samuel', 9, 8, 10, 'So Samuel spoke all the words of the LORD to the people who were asking him for a king.'),
  ('BSB', '1 Samuel', 9, 8, 11, 'He said, “This will be the manner of the king who will reign over you: He will take your sons and appoint them to his own chariots and horses, to run in front of his chariots.'),
  ('BSB', '1 Samuel', 9, 8, 12, 'He will appoint some for himself as commanders of thousands and of fifties, and others to plow his ground, to reap his harvest, to make his weapons of war, and to equip his chariots.'),
  ('BSB', '1 Samuel', 9, 8, 13, 'And he will take your daughters to be perfumers, cooks, and bakers.'),
  ('BSB', '1 Samuel', 9, 8, 14, 'He will take the best of your fields and vineyards and olive groves and give them to his servants.'),
  ('BSB', '1 Samuel', 9, 8, 15, 'He will take a tenth of your grain and grape harvest and give it to his officials and servants.'),
  ('BSB', '1 Samuel', 9, 8, 16, 'And he will take your menservants and maidservants and your best cattle and donkeys and put them to his own use.'),
  ('BSB', '1 Samuel', 9, 8, 17, 'He will take a tenth of your flocks, and you yourselves will become his slaves.'),
  ('BSB', '1 Samuel', 9, 8, 18, 'When that day comes, you will beg for relief from the king you have chosen, but the LORD will not answer you on that day.”'),
  ('BSB', '1 Samuel', 9, 8, 19, 'Nevertheless, the people refused to listen to Samuel. “No!” they said. “We must have a king over us.'),
  ('BSB', '1 Samuel', 9, 8, 20, 'Then we will be like all the other nations, with a king to judge us, to go out before us, and to fight our battles.”'),
  ('BSB', '1 Samuel', 9, 8, 21, 'Samuel listened to all the words of the people and repeated them in the hearing of the LORD.'),
  ('BSB', '1 Samuel', 9, 8, 22, '“Listen to their voice,” the LORD said to Samuel. “Appoint a king for them.” Then Samuel told the men of Israel, “Everyone must go back to his city.”'),
  ('BSB', '1 Samuel', 9, 9, 1, 'Now there was a Benjamite, a powerful man, whose name was Kish son of Abiel, the son of Zeror, the son of Becorath, the son of Aphiah of Benjamin.'),
  ('BSB', '1 Samuel', 9, 9, 2, 'And he had a son named Saul, choice and handsome, without equal among the Israelites—a head taller than any of the people.'),
  ('BSB', '1 Samuel', 9, 9, 3, 'One day the donkeys of Saul’s father Kish wandered off, and Kish said to his son Saul, “Take one of the servants and go look for the donkeys.”'),
  ('BSB', '1 Samuel', 9, 9, 4, 'So Saul passed through the hill country of Ephraim and then through the land of Shalishah, but did not find the donkeys. He and the servant went through the region of Shaalim, but they were not there. Then they went through the land of Benjamin, and still they did not find them.'),
  ('BSB', '1 Samuel', 9, 9, 5, 'When they reached the land of Zuph, Saul said to his servant, “Come, let us go back, or my father will stop worrying about the donkeys and start worrying about us.”'),
  ('BSB', '1 Samuel', 9, 9, 6, '“Look,” said the servant, “in this city there is a man of God who is highly respected; everything he says surely comes to pass. Let us go there now. Perhaps he will tell us which way to go.”'),
  ('BSB', '1 Samuel', 9, 9, 7, '“If we do go,” Saul replied, “what can we give the man? For the bread in our packs is gone, and there is no gift to take to the man of God. What do we have?”'),
  ('BSB', '1 Samuel', 9, 9, 8, 'The servant answered him again. “Look,” he said, “I have here in my hand a quarter shekel of silver. I will give it to the man of God, and he will tell us our way.”'),
  ('BSB', '1 Samuel', 9, 9, 9, '(Formerly in Israel, a man on his way to inquire of God would say, “Come, let us go to the seer.” For the prophet of today was formerly called the seer.)'),
  ('BSB', '1 Samuel', 9, 9, 10, '“Good,” said Saul to his servant. “Come, let us go.” So they set out for the city where the man of God was.'),
  ('BSB', '1 Samuel', 9, 9, 11, 'And as they were climbing the hill to the city, they met some young women coming out to draw water and asked, “Is the seer here?”'),
  ('BSB', '1 Samuel', 9, 9, 12, '“Yes, he is ahead of you,” they answered. “Hurry now, for today he has come to the city because the people have a sacrifice on the high place.'),
  ('BSB', '1 Samuel', 9, 9, 13, 'As soon as you enter the city, you will find him before he goes up to the high place to eat. The people will not eat until he comes, because he must bless the sacrifice; after that, the guests will eat. Go up at once; you will find him.”'),
  ('BSB', '1 Samuel', 9, 9, 14, 'So Saul and his servant went up toward the city, and as they were entering it, there was Samuel coming toward them on his way up to the high place.'),
  ('BSB', '1 Samuel', 9, 9, 15, 'Now on the day before Saul’s arrival, the LORD had revealed to Samuel,'),
  ('BSB', '1 Samuel', 9, 9, 16, '“At this time tomorrow I will send you a man from the land of Benjamin, and you are to anoint him leader over My people Israel; he will save them from the hand of the Philistines. For I have looked upon My people, because their cry has come to Me.”'),
  ('BSB', '1 Samuel', 9, 9, 17, 'When Samuel saw Saul, the LORD told him, “Here is the man of whom I spoke; he shall rule over My people.”'),
  ('BSB', '1 Samuel', 9, 9, 18, 'Saul approached Samuel in the gateway and asked, “Would you please tell me where the seer’s house is?”'),
  ('BSB', '1 Samuel', 9, 9, 19, '“I am the seer,” Samuel replied. “Go up before me to the high place, for you shall eat with me today. And when I send you off in the morning, I will tell you all that is in your heart.'),
  ('BSB', '1 Samuel', 9, 9, 20, 'As for the donkeys you lost three days ago, do not worry about them, for they have been found. And upon whom is all the desire of Israel, if not upon you and all your father’s house?”'),
  ('BSB', '1 Samuel', 9, 9, 21, 'Saul replied, “Am I not a Benjamite from the smallest tribe of Israel, and is not my clan the least of all the clans of Benjamin? So why would you say such a thing to me?”'),
  ('BSB', '1 Samuel', 9, 9, 22, 'Then Samuel took Saul and his servant, brought them into the hall, and seated them in the place of honor among those who were invited—about thirty in all.'),
  ('BSB', '1 Samuel', 9, 9, 23, 'And Samuel said to the cook, “Bring the portion I gave you and told you to set aside.”'),
  ('BSB', '1 Samuel', 9, 9, 24, 'So the cook picked up the leg and what was attached to it and set it before Saul. Then Samuel said, “Here is what was kept back. It was set apart for you. Eat, for it has been kept for you for this occasion, from the time I said, ‘I have invited the people.’” So Saul dined with Samuel that day.'),
  ('BSB', '1 Samuel', 9, 9, 25, 'And after they had come down from the high place into the city, Samuel spoke with Saul on the roof of his house.'),
  ('BSB', '1 Samuel', 9, 9, 26, 'They got up early in the morning, and just before dawn Samuel called to Saul on the roof, “Get ready, and I will send you on your way!” So Saul arose, and both he and Samuel went outside together.'),
  ('BSB', '1 Samuel', 9, 9, 27, 'As they were going down to the edge of the city, Samuel said to Saul, “Tell the servant to go on ahead of us, but you stay for a while, and I will reveal to you the word of God.” So the servant went on.'),
  ('BSB', '1 Samuel', 9, 10, 1, 'Then Samuel took a flask of oil, poured it on Saul’s head, kissed him, and said, “Has not the LORD anointed you ruler over His inheritance?'),
  ('BSB', '1 Samuel', 9, 10, 2, 'When you leave me today, you will find two men at Rachel’s tomb in Zelzah on the border of Benjamin. They will say to you, ‘The donkeys you seek have been found, and now your father has stopped worrying about the donkeys and started worrying about you, asking, “What should I do about my son?”’'),
  ('BSB', '1 Samuel', 9, 10, 3, 'Then you will go on from there until you come to the Oak of Tabor. Three men going up to God at Bethel will meet you there, one carrying three young goats, another carrying three loaves of bread, and another carrying a skin of wine.'),
  ('BSB', '1 Samuel', 9, 10, 4, 'They will greet you and give you two loaves of bread, which you will accept from their hands.'),
  ('BSB', '1 Samuel', 9, 10, 5, 'After that you will come to Gibeah of God, where the Philistines have an outpost. As you approach the city, you will meet a group of prophets coming down from the high place, preceded by harps, tambourines, flutes, and lyres, and they will be prophesying.'),
  ('BSB', '1 Samuel', 9, 10, 6, 'Then the Spirit of the LORD will rush upon you, and you will prophesy with them; and you will be transformed into a different person.'),
  ('BSB', '1 Samuel', 9, 10, 7, 'When these signs have come, do as the occasion demands, for God is with you.'),
  ('BSB', '1 Samuel', 9, 10, 8, 'And you shall go before me to Gilgal, and surely I will come to you to offer burnt offerings and to sacrifice peace offerings. Wait seven days until I come to you and show you what you are to do.”'),
  ('BSB', '1 Samuel', 9, 10, 9, 'As Saul turned to leave Samuel, God changed Saul’s heart, and all the signs came to pass that day.'),
  ('BSB', '1 Samuel', 9, 10, 10, 'When Saul and his servant arrived at Gibeah, a group of prophets met him. Then the Spirit of God rushed upon him, and he prophesied along with them.'),
  ('BSB', '1 Samuel', 9, 10, 11, 'All those who had formerly known Saul and saw him prophesying with the prophets asked one another, “What has happened to the son of Kish? Is Saul also among the prophets?”'),
  ('BSB', '1 Samuel', 9, 10, 12, 'Then a man who lived there replied, “And who is their father?” So the saying became a proverb: “Is Saul also among the prophets?”'),
  ('BSB', '1 Samuel', 9, 10, 13, 'And when Saul had finished prophesying, he went up to the high place.'),
  ('BSB', '1 Samuel', 9, 10, 14, 'Now Saul’s uncle asked him and his servant, “Where did you go?” “To look for the donkeys,” Saul replied. “When we saw they were not to be found, we went to Samuel.”'),
  ('BSB', '1 Samuel', 9, 10, 15, '“Tell me,” Saul’s uncle asked, “what did Samuel say to you?”'),
  ('BSB', '1 Samuel', 9, 10, 16, 'And Saul replied, “He assured us that the donkeys had been found.” But Saul did not tell his uncle what Samuel had said about the kingship.'),
  ('BSB', '1 Samuel', 9, 10, 17, 'After this, Samuel summoned the people to the LORD at Mizpah'),
  ('BSB', '1 Samuel', 9, 10, 18, 'and said to the Israelites, “This is what the LORD, the God of Israel, says: ‘I brought Israel up out of Egypt, and I rescued you from the hands of the Egyptians and of all the kingdoms that oppressed you.’'),
  ('BSB', '1 Samuel', 9, 10, 19, 'But today you have rejected your God, who saves you from all your troubles and afflictions, and you have said to Him, ‘No, set a king over us.’ Now therefore present yourselves before the LORD by your tribes and clans.”'),
  ('BSB', '1 Samuel', 9, 10, 20, 'Thus Samuel had all the tribes of Israel come forward, and the tribe of Benjamin was selected.'),
  ('BSB', '1 Samuel', 9, 10, 21, 'Then he had the tribe of Benjamin come forward by its clans, and the clan of Matri was selected. Finally, Saul son of Kish was selected. But when they looked for him, they could not find him.'),
  ('BSB', '1 Samuel', 9, 10, 22, 'So again they inquired of the LORD, “Has the man come here yet?” And the LORD replied, “Behold, he has hidden himself among the baggage.”'),
  ('BSB', '1 Samuel', 9, 10, 23, 'So they ran and brought Saul, and when he stood among the people, he was a head taller than any of the others.'),
  ('BSB', '1 Samuel', 9, 10, 24, 'Samuel said to all the people, “Do you see the one the LORD has chosen? There is no one like him among all the people.” And all the people shouted, “Long live the king!”'),
  ('BSB', '1 Samuel', 9, 10, 25, 'Then Samuel explained to the people the rights of kingship. He wrote them on a scroll and laid it up before the LORD. And Samuel sent all the people away, each to his own home.'),
  ('BSB', '1 Samuel', 9, 10, 26, 'Saul also went to his home in Gibeah, and the men of valor whose hearts God had touched went with him.'),
  ('BSB', '1 Samuel', 9, 10, 27, 'But some worthless men said, “How can this man save us?” So they despised him and brought him no gifts; but Saul remained silent about it.'),
  ('BSB', '1 Samuel', 9, 11, 1, 'Soon Nahash the Ammonite came up and laid siege to Jabesh-gilead. All the men of Jabesh said to him, “Make a treaty with us, and we will serve you.”'),
  ('BSB', '1 Samuel', 9, 11, 2, 'But Nahash the Ammonite replied, “I will make a treaty with you on one condition, that I may put out everyone’s right eye and bring reproach upon all Israel.”'),
  ('BSB', '1 Samuel', 9, 11, 3, '“Hold off for seven days,” replied the elders of Jabesh, “and let us send messengers throughout Israel. If there is no one to save us, we will surrender to you.”'),
  ('BSB', '1 Samuel', 9, 11, 4, 'When the messengers came to Gibeah of Saul and relayed these words in the hearing of the people, they all wept aloud.'),
  ('BSB', '1 Samuel', 9, 11, 5, 'Just then Saul was returning from the field, behind his oxen. “What troubles the people?” asked Saul. “Why are they weeping?” And they relayed to him the words of the men from Jabesh.'),
  ('BSB', '1 Samuel', 9, 11, 6, 'When Saul heard their words, the Spirit of God rushed upon him, and he burned with great anger.'),
  ('BSB', '1 Samuel', 9, 11, 7, 'He took a pair of oxen, cut them into pieces, and sent them by messengers throughout the land of Israel, proclaiming, “This is what will be done to the oxen of anyone who does not march behind Saul and Samuel.” Then the terror of the LORD fell upon the people, and they turned out as one man.'),
  ('BSB', '1 Samuel', 9, 11, 8, 'And when Saul numbered them at Bezek, there were 300,000 Israelites and 30,000 men of Judah.'),
  ('BSB', '1 Samuel', 9, 11, 9, 'So they said to the messengers who had come, “Tell the men of Jabesh-gilead: ‘Deliverance will be yours tomorrow by the time the sun is hot.’” And when the messengers relayed this to the men of Jabesh, they rejoiced.'),
  ('BSB', '1 Samuel', 9, 11, 10, 'Then the men of Jabesh said to Nahash, “Tomorrow we will come out, and you can do with us whatever seems good to you.”'),
  ('BSB', '1 Samuel', 9, 11, 11, 'The next day Saul organized the troops into three divisions, and during the morning watch they invaded the camp of the Ammonites and slaughtered them, until the hottest part of the day. And the survivors were so scattered that no two of them were left together.'),
  ('BSB', '1 Samuel', 9, 11, 12, 'Then the people said to Samuel, “Who said that Saul should not reign over us? Bring those men here so we can kill them!”'),
  ('BSB', '1 Samuel', 9, 11, 13, 'But Saul ordered, “No one shall be put to death this day, for today the LORD has worked salvation in Israel.”'),
  ('BSB', '1 Samuel', 9, 11, 14, 'Then Samuel said to the people, “Come, let us go to Gilgal and renew the kingship there.”'),
  ('BSB', '1 Samuel', 9, 11, 15, 'So all the people went to Gilgal and confirmed Saul as king in the presence of the LORD. There they sacrificed peace offerings before the LORD, and Saul and all the Israelites rejoiced greatly.'),
  ('BSB', '1 Samuel', 9, 12, 1, 'Then Samuel said to all Israel, “I have listened to your voice in all that you have said to me, and I have set over you a king.'),
  ('BSB', '1 Samuel', 9, 12, 2, 'Now here is the king walking before you, and I am old and gray, and my sons are here with you. I have walked before you from my youth until this day.'),
  ('BSB', '1 Samuel', 9, 12, 3, 'Here I am. Bear witness against me before the LORD and before His anointed: Whose ox or donkey have I taken? Whom have I cheated or oppressed? From whose hand have I accepted a bribe and closed my eyes? Tell me, and I will restore it to you.”'),
  ('BSB', '1 Samuel', 9, 12, 4, '“You have not wronged us or oppressed us,” they replied, “nor have you taken anything from the hand of man.”'),
  ('BSB', '1 Samuel', 9, 12, 5, 'Samuel said to them, “The LORD is a witness against you, and His anointed is a witness today, that you have not found anything in my hand.” “He is a witness,” they replied.'),
  ('BSB', '1 Samuel', 9, 12, 6, 'Then Samuel said to the people, “The LORD is the One who appointed Moses and Aaron, and who brought your fathers up out of the land of Egypt.'),
  ('BSB', '1 Samuel', 9, 12, 7, 'Now present yourselves, so that I may confront you before the LORD with all the righteous acts He has done for you and your fathers.'),
  ('BSB', '1 Samuel', 9, 12, 8, 'When Jacob went to Egypt, your fathers cried out to the LORD, and He sent them Moses and Aaron, who brought your fathers out of Egypt and settled them in this place.'),
  ('BSB', '1 Samuel', 9, 12, 9, 'But they forgot the LORD their God, and He sold them into the hand of Sisera the commander of the army of Hazor, and into the hands of the Philistines and the king of Moab, who fought against them.'),
  ('BSB', '1 Samuel', 9, 12, 10, 'Then they cried out to the LORD and said, ‘We have sinned, for we have forsaken the LORD and served the Baals and Ashtoreths. Now deliver us from the hands of our enemies, that we may serve You.’'),
  ('BSB', '1 Samuel', 9, 12, 11, 'So the LORD sent Jerubbaal, Barak, Jephthah, and Samuel, and He delivered you from the hands of your enemies on every side, and you dwelt securely.'),
  ('BSB', '1 Samuel', 9, 12, 12, 'But when you saw that Nahash king of the Ammonites was moving against you, you said to me, ‘No, we must have a king to rule over us’—even though the LORD your God was your king.'),
  ('BSB', '1 Samuel', 9, 12, 13, 'Now here is the king you have chosen, the one you requested. Behold, the LORD has placed a king over you.'),
  ('BSB', '1 Samuel', 9, 12, 14, 'If you fear the LORD and serve Him and obey His voice, and if you do not rebel against the command of the LORD, and if both you and the king who reigns over you follow the LORD your God, then all will be well.'),
  ('BSB', '1 Samuel', 9, 12, 15, 'But if you disobey the LORD and rebel against His command, then the hand of the LORD will be against you as it was against your fathers.'),
  ('BSB', '1 Samuel', 9, 12, 16, 'Now, therefore, stand and see this great thing that the LORD will do before your eyes.'),
  ('BSB', '1 Samuel', 9, 12, 17, 'Is it not the wheat harvest today? I will call on the LORD to send thunder and rain, so that you will know and see what a great evil you have committed in the sight of the LORD by asking for a king.”'),
  ('BSB', '1 Samuel', 9, 12, 18, 'So Samuel called to the LORD, and on that day the LORD sent thunder and rain. As a result, all the people greatly feared the LORD and Samuel.'),
  ('BSB', '1 Samuel', 9, 12, 19, 'They pleaded with Samuel, “Pray to the LORD your God for your servants so that we will not die! For we have added to all our sins the evil of asking for a king.”'),
  ('BSB', '1 Samuel', 9, 12, 20, '“Do not be afraid,” Samuel replied. “Even though you have committed all this evil, do not turn aside from following the LORD, but serve the LORD with all your heart.'),
  ('BSB', '1 Samuel', 9, 12, 21, 'Do not turn aside after worthless things that cannot profit you or deliver you, for they are empty.'),
  ('BSB', '1 Samuel', 9, 12, 22, 'Indeed, for the sake of His great name, the LORD will not abandon His people, because He was pleased to make you His own.'),
  ('BSB', '1 Samuel', 9, 12, 23, 'As for me, far be it from me that I should sin against the LORD by ceasing to pray for you. And I will continue to teach you the good and right way.'),
  ('BSB', '1 Samuel', 9, 12, 24, 'Above all, fear the LORD and serve Him faithfully with all your heart; consider what great things He has done for you.'),
  ('BSB', '1 Samuel', 9, 12, 25, 'But if you persist in doing evil, both you and your king will be swept away.”'),
  ('BSB', '1 Samuel', 9, 13, 1, 'Saul was thirty years old when he became king, and he reigned over Israel forty-two years.'),
  ('BSB', '1 Samuel', 9, 13, 2, 'He chose for himself three thousand men of Israel: Two thousand were with Saul at Michmash and in the hill country of Bethel, and a thousand were with Jonathan in Gibeah of Benjamin. And the rest of the troops he sent away, each to his own home.'),
  ('BSB', '1 Samuel', 9, 13, 3, 'Then Jonathan attacked the Philistine outpost at Geba, and the Philistines heard about it. So Saul blew the ram’s horn throughout the land, saying, “Let the Hebrews hear!”'),
  ('BSB', '1 Samuel', 9, 13, 4, 'And all Israel heard the news: “Saul has attacked an outpost of the Philistines, and now Israel has become a stench to the Philistines!” Then the people were summoned to join Saul at Gilgal.'),
  ('BSB', '1 Samuel', 9, 13, 5, 'Now the Philistines assembled to fight against Israel with three thousand chariots, six thousand horsemen, and troops as numerous as the sand on the seashore. They went up and camped at Michmash, east of Beth-aven.'),
  ('BSB', '1 Samuel', 9, 13, 6, 'Seeing that they were in danger because their troops were hard-pressed, the men of Israel hid in caves and thickets, among the rocks, and in cellars and cisterns.'),
  ('BSB', '1 Samuel', 9, 13, 7, 'Some Hebrews even crossed the Jordan into the land of Gad and Gilead. Saul, however, remained at Gilgal, and all his troops were quaking in fear.'),
  ('BSB', '1 Samuel', 9, 13, 8, 'And Saul waited seven days for the time appointed by Samuel, but Samuel did not come to Gilgal, and the troops began to desert Saul.'),
  ('BSB', '1 Samuel', 9, 13, 9, 'So he said, “Bring me the burnt offering and the peace offerings.” And he offered up the burnt offering.'),
  ('BSB', '1 Samuel', 9, 13, 10, 'Just as he finished offering the burnt offering, Samuel arrived, and Saul went out to greet him.'),
  ('BSB', '1 Samuel', 9, 13, 11, '“What have you done?” Samuel asked. And Saul replied, “When I saw that the troops were deserting me, and that you did not come at the appointed time and the Philistines were gathering at Michmash,'),
  ('BSB', '1 Samuel', 9, 13, 12, 'I thought, ‘Now the Philistines will descend upon me at Gilgal, and I have not sought the favor of the LORD.’ So I felt compelled to offer the burnt offering.”'),
  ('BSB', '1 Samuel', 9, 13, 13, '“You have acted foolishly,” Samuel declared. “You have not kept the command that the LORD your God gave you; if you had, the LORD would have established your kingdom over Israel for all time.'),
  ('BSB', '1 Samuel', 9, 13, 14, 'But now your kingdom will not endure; the LORD has sought a man after His own heart and appointed him ruler over His people, because you have not kept the command of the LORD.”'),
  ('BSB', '1 Samuel', 9, 13, 15, 'Then Samuel set out from Gilgal and went up to Gibeah in Benjamin. And Saul numbered the troops who were with him, about six hundred men.'),
  ('BSB', '1 Samuel', 9, 13, 16, 'Now Saul and Jonathan his son and the troops with them were staying in Geba of Benjamin, while the Philistines camped at Michmash.'),
  ('BSB', '1 Samuel', 9, 13, 17, 'And raiders went out of the Philistine camp in three divisions. One headed toward Ophrah in the land of Shual,'),
  ('BSB', '1 Samuel', 9, 13, 18, 'another toward Beth-horon, and the third down the border road overlooking the Valley of Zeboim facing the wilderness.'),
  ('BSB', '1 Samuel', 9, 13, 19, 'And no blacksmith could be found in all the land of Israel, because the Philistines had said, “The Hebrews must not be allowed to make swords or spears.”'),
  ('BSB', '1 Samuel', 9, 13, 20, 'Instead, all the Israelites would go down to the Philistines to sharpen their plowshares, mattocks, axes, and sickles.'),
  ('BSB', '1 Samuel', 9, 13, 21, 'The charge was a pim for sharpening a plowshare or mattock, a third of a shekel for sharpening a pitchfork or an axe, and a third of a shekel for repointing an oxgoad.'),
  ('BSB', '1 Samuel', 9, 13, 22, 'So on the day of battle not a sword or spear could be found in the hands of the troops with Saul and Jonathan; only Saul and his son Jonathan had weapons.'),
  ('BSB', '1 Samuel', 9, 13, 23, 'And a garrison of the Philistines had gone out to the pass at Michmash.'),
  ('BSB', '1 Samuel', 9, 14, 1, 'One day Jonathan son of Saul said to the young man bearing his armor, “Come, let us cross over to the Philistine outpost on the other side.” But Jonathan did not tell his father.'),
  ('BSB', '1 Samuel', 9, 14, 2, 'Meanwhile, Saul was staying under the pomegranate tree in Migron on the outskirts of Gibeah. And the troops who were with him numbered about six hundred men,'),
  ('BSB', '1 Samuel', 9, 14, 3, 'including Ahijah, who was wearing an ephod. He was the son of Ichabod’s brother Ahitub son of Phinehas, the son of Eli the priest of the LORD in Shiloh. But the troops did not know that Jonathan had left.'),
  ('BSB', '1 Samuel', 9, 14, 4, 'Now there were cliffs on both sides of the pass that Jonathan intended to cross to reach the Philistine outpost. One was named Bozez and the other Seneh.'),
  ('BSB', '1 Samuel', 9, 14, 5, 'One cliff stood to the north toward Michmash, and the other to the south toward Geba.'),
  ('BSB', '1 Samuel', 9, 14, 6, 'Jonathan said to the young man bearing his armor, “Come, let us cross over to the outpost of these uncircumcised men. Perhaps the LORD will work on our behalf. Nothing can hinder the LORD from saving, whether by many or by few.”'),
  ('BSB', '1 Samuel', 9, 14, 7, 'His armor-bearer replied, “Do all that is in your heart. Go ahead; I am with you heart and soul.”'),
  ('BSB', '1 Samuel', 9, 14, 8, '“Very well,” said Jonathan, “we will cross over toward these men and show ourselves to them.'),
  ('BSB', '1 Samuel', 9, 14, 9, 'If they say, ‘Wait until we come to you,’ then we will stay where we are and will not go up to them.'),
  ('BSB', '1 Samuel', 9, 14, 10, 'But if they say, ‘Come on up,’ then we will go up, because this will be our sign that the LORD has delivered them into our hands.”'),
  ('BSB', '1 Samuel', 9, 14, 11, 'So the two of them showed themselves to the outpost of the Philistines, who exclaimed, “Look, the Hebrews are coming out of the holes in which they were hiding!”'),
  ('BSB', '1 Samuel', 9, 14, 12, 'So the men of the outpost called out to Jonathan and his armor-bearer, “Come on up, and we will teach you a lesson!” “Follow me,” Jonathan told his armor-bearer, “for the LORD has delivered them into the hand of Israel.”'),
  ('BSB', '1 Samuel', 9, 14, 13, 'So Jonathan climbed up on his hands and feet, with his armor-bearer behind him. And the Philistines fell before Jonathan, and his armor-bearer followed and finished them off.'),
  ('BSB', '1 Samuel', 9, 14, 14, 'In that first assault, Jonathan and his armor-bearer struck down about twenty men over half an acre of land.'),
  ('BSB', '1 Samuel', 9, 14, 15, 'Then terror struck the Philistines in the camp, in the field, and among all the people. Even those in the outposts and raiding parties trembled. Indeed, the earth quaked and panic spread from God.'),
  ('BSB', '1 Samuel', 9, 14, 16, 'Now when Saul’s watchmen at Gibeah in Benjamin looked and saw the troops melting away and scattering in every direction,'),
  ('BSB', '1 Samuel', 9, 14, 17, 'Saul said to the troops who were with him, “Call the roll and see who has left us.” And when they had called the roll, they saw that Jonathan and his armor-bearer were not there.'),
  ('BSB', '1 Samuel', 9, 14, 18, 'Then Saul said to Ahijah, “Bring the ark of God.” (For at that time it was with the Israelites.)'),
  ('BSB', '1 Samuel', 9, 14, 19, 'While Saul was talking to the priest, the commotion in the Philistine camp continued to increase. So Saul said to the priest, “Withdraw your hand.”'),
  ('BSB', '1 Samuel', 9, 14, 20, 'Then Saul and all his troops assembled and marched to the battle, and they found the Philistines in total confusion, with each man wielding the sword against his neighbor.'),
  ('BSB', '1 Samuel', 9, 14, 21, 'And the Hebrews who had previously gone up into the surrounding camps of the Philistines now went over to the Israelites who were with Saul and Jonathan.'),
  ('BSB', '1 Samuel', 9, 14, 22, 'When all the Israelites who had been hiding in the hill country of Ephraim heard that the Philistines were fleeing, they also joined Saul and Jonathan in the battle.'),
  ('BSB', '1 Samuel', 9, 14, 23, 'So the LORD saved Israel that day, and the battle moved on beyond Beth-aven.'),
  ('BSB', '1 Samuel', 9, 14, 24, 'Now the men of Israel were in distress that day, for Saul had placed the troops under an oath, saying, “Cursed is the man who eats any food before evening, before I have taken vengeance on my enemies.” So none of the troops tasted any food.'),
  ('BSB', '1 Samuel', 9, 14, 25, 'Then all the troops entered the forest, and there was honey on the ground.'),
  ('BSB', '1 Samuel', 9, 14, 26, 'And when they entered the forest and saw the flowing honey, not one of them put his hand to his mouth, because they feared the oath.'),
  ('BSB', '1 Samuel', 9, 14, 27, 'Jonathan, however, had not heard that his father had charged the people with the oath. So he reached out the end of the staff in his hand, dipped it into the honeycomb, and put his hand to his mouth; and his eyes brightened.'),
  ('BSB', '1 Samuel', 9, 14, 28, 'Then one of the soldiers told him, “Your father bound the troops with a solemn oath, saying, ‘Cursed is the man who eats food today.’ That is why the people are faint.”'),
  ('BSB', '1 Samuel', 9, 14, 29, '“My father has brought trouble to the land,” Jonathan replied. “Just look at how my eyes have brightened because I tasted a little of this honey.'),
  ('BSB', '1 Samuel', 9, 14, 30, 'How much better it would have been if the troops had eaten freely today from the plunder they took from their enemies! Would not the slaughter of the Philistines have been much greater?”'),
  ('BSB', '1 Samuel', 9, 14, 31, 'That day, after the Israelites had struck down the Philistines from Michmash to Aijalon, the people were very faint.'),
  ('BSB', '1 Samuel', 9, 14, 32, 'So they rushed greedily to the plunder, taking sheep, cattle, and calves. They slaughtered them on the ground and ate meat with the blood still in it.'),
  ('BSB', '1 Samuel', 9, 14, 33, 'Then someone reported to Saul: “Look, the troops are sinning against the LORD by eating meat with the blood still in it.” “You have broken faith,” said Saul. “Roll a large stone over here at once.”'),
  ('BSB', '1 Samuel', 9, 14, 34, 'Then he said, “Go among the troops and tell them, ‘Each man must bring me his ox or his sheep, slaughter them in this place, and then eat. Do not sin against the LORD by eating meat with the blood still in it.’” So that night everyone brought his ox and slaughtered it there.'),
  ('BSB', '1 Samuel', 9, 14, 35, 'Then Saul built an altar to the LORD; it was the first time he had built an altar to the LORD.'),
  ('BSB', '1 Samuel', 9, 14, 36, 'And Saul said, “Let us go down after the Philistines by night and plunder them until dawn, leaving no man alive!” “Do what seems good to you,” the troops replied. But the priest said, “We must consult God here.”'),
  ('BSB', '1 Samuel', 9, 14, 37, 'So Saul inquired of God, “Shall I go down after the Philistines? Will You give them into the hand of Israel?” But God did not answer him that day.'),
  ('BSB', '1 Samuel', 9, 14, 38, 'Therefore Saul said, “Come here, all you leaders of the troops, and let us investigate how this sin has occurred today.'),
  ('BSB', '1 Samuel', 9, 14, 39, 'As surely as the LORD who saves Israel lives, even if it is my son Jonathan, he must die!” But not one of the troops said a word.'),
  ('BSB', '1 Samuel', 9, 14, 40, 'Then Saul said to all Israel, “You stand on one side, and I and my son Jonathan will stand on the other side.” “Do what seems good to you,” the troops replied.'),
  ('BSB', '1 Samuel', 9, 14, 41, 'So Saul said to the LORD, the God of Israel, “Why have You not answered Your servant this day? If the fault is with me or my son Jonathan, respond with Urim; but if the fault is with the men of Israel, respond with Thummim.” And Jonathan and Saul were selected, but the people were cleared of the charge.'),
  ('BSB', '1 Samuel', 9, 14, 42, 'Then Saul said, “Cast the lot between me and my son Jonathan.” And Jonathan was selected.'),
  ('BSB', '1 Samuel', 9, 14, 43, '“Tell me what you have done,” Saul commanded him. So Jonathan told him, “I only tasted a little honey with the end of the staff that was in my hand. And now I must die?”'),
  ('BSB', '1 Samuel', 9, 14, 44, 'And Saul declared, “May God punish me, and ever so severely, if you, Jonathan, do not surely die!”'),
  ('BSB', '1 Samuel', 9, 14, 45, 'But the people said to Saul, “Must Jonathan die—he who accomplished such a great deliverance for Israel? Never! As surely as the LORD lives, not a hair of his head will fall to the ground, for with God’s help he has accomplished this today.” So the people rescued Jonathan, and he did not die.'),
  ('BSB', '1 Samuel', 9, 14, 46, 'Then Saul gave up his pursuit of the Philistines, and the Philistines returned to their own land.'),
  ('BSB', '1 Samuel', 9, 14, 47, 'After Saul had assumed the kingship over Israel, he fought against all his enemies on every side—the Moabites, the Ammonites, the Edomites, the kings of Zobah, and the Philistines. Wherever he turned, he routed them.'),
  ('BSB', '1 Samuel', 9, 14, 48, 'He fought valiantly and defeated the Amalekites, delivering Israel from the hands of its plunderers.'),
  ('BSB', '1 Samuel', 9, 14, 49, 'Now the sons of Saul were Jonathan, Ishvi, and Malchishua. His two daughters were named Merab (his firstborn) and Michal (his younger daughter).'),
  ('BSB', '1 Samuel', 9, 14, 50, 'His wife’s name was Ahinoam daughter of Ahimaaz. The name of the commander of his army was Abner, the son of Saul’s uncle Ner.'),
  ('BSB', '1 Samuel', 9, 14, 51, 'Saul’s father Kish and Abner’s father Ner were sons of Abiel.'),
  ('BSB', '1 Samuel', 9, 14, 52, 'And the war with the Philistines was fierce for all the days of Saul. So whenever he noticed any strong or brave man, Saul would enlist him.'),
  ('BSB', '1 Samuel', 9, 15, 1, 'Then Samuel said to Saul, “The LORD sent me to anoint you king over His people Israel. Now therefore, listen to the words of the LORD.'),
  ('BSB', '1 Samuel', 9, 15, 2, 'This is what the LORD of Hosts says: ‘I witnessed what the Amalekites did to the Israelites when they ambushed them on their way up from Egypt.'),
  ('BSB', '1 Samuel', 9, 15, 3, 'Now go and attack the Amalekites and devote to destruction all that belongs to them. Do not spare them, but put to death men and women, children and infants, oxen and sheep, camels and donkeys.’”'),
  ('BSB', '1 Samuel', 9, 15, 4, 'So Saul summoned the troops and numbered them at Telaim—200,000 foot soldiers and 10,000 men of Judah.'),
  ('BSB', '1 Samuel', 9, 15, 5, 'Saul came to the city of Amalek and lay in wait in the valley.'),
  ('BSB', '1 Samuel', 9, 15, 6, 'And he warned the Kenites, “Since you showed kindness to all the Israelites when they came up out of Egypt, go on and get away from the Amalekites. Otherwise I will sweep you away with them.” So the Kenites moved away from the Amalekites.'),
  ('BSB', '1 Samuel', 9, 15, 7, 'Then Saul struck down the Amalekites all the way from Havilah to Shur, which is east of Egypt.'),
  ('BSB', '1 Samuel', 9, 15, 8, 'He captured Agag king of Amalek alive, but devoted all the others to destruction with the sword.'),
  ('BSB', '1 Samuel', 9, 15, 9, 'Saul and his troops spared Agag, along with the best of the sheep and cattle, the fat calves and lambs, and the best of everything else. They were unwilling to destroy them, but they devoted to destruction all that was despised and worthless.'),
  ('BSB', '1 Samuel', 9, 15, 10, 'Then the word of the LORD came to Samuel, saying,'),
  ('BSB', '1 Samuel', 9, 15, 11, '“I regret that I have made Saul king, for he has turned away from following Me and has not carried out My instructions.” And Samuel was distressed and cried out to the LORD all that night.'),
  ('BSB', '1 Samuel', 9, 15, 12, 'Early in the morning Samuel got up to confront Saul, but he was told, “Saul has gone to Carmel, and behold, he has set up a monument for himself and has turned and gone down to Gilgal.”'),
  ('BSB', '1 Samuel', 9, 15, 13, 'When Samuel reached him, Saul said to him, “May the LORD bless you. I have carried out the LORD’s instructions.”'),
  ('BSB', '1 Samuel', 9, 15, 14, 'But Samuel replied, “Then what is this bleating of sheep and lowing of cattle that I hear?”'),
  ('BSB', '1 Samuel', 9, 15, 15, 'Saul answered, “The troops brought them from the Amalekites; they spared the best sheep and cattle to sacrifice to the LORD your God, but the rest we devoted to destruction.”'),
  ('BSB', '1 Samuel', 9, 15, 16, '“Stop!” exclaimed Samuel. “Let me tell you what the LORD said to me last night.” “Tell me,” Saul replied.'),
  ('BSB', '1 Samuel', 9, 15, 17, 'And Samuel said, “Although you were once small in your own eyes, have you not become the head of the tribes of Israel? The LORD anointed you king over Israel'),
  ('BSB', '1 Samuel', 9, 15, 18, 'and sent you on a mission, saying, ‘Go and devote to destruction the sinful Amalekites. Fight against them until you have wiped them out.’'),
  ('BSB', '1 Samuel', 9, 15, 19, 'So why did you not obey the LORD? Why did you rush upon the plunder and do evil in the sight of the LORD?”'),
  ('BSB', '1 Samuel', 9, 15, 20, '“But I did obey the LORD,” Saul replied. “I went on the mission that the LORD gave me. I brought back Agag king of Amalek and devoted the Amalekites to destruction.'),
  ('BSB', '1 Samuel', 9, 15, 21, 'The troops took sheep and cattle from the plunder, the best of the things devoted to destruction, in order to sacrifice them to the LORD your God at Gilgal.”'),
  ('BSB', '1 Samuel', 9, 15, 22, 'But Samuel declared: “Does the LORD delight in burnt offerings and sacrifices as much as in obedience to His voice? Behold, obedience is better than sacrifice, and attentiveness is better than the fat of rams.'),
  ('BSB', '1 Samuel', 9, 15, 23, 'For rebellion is like the sin of divination, and arrogance is like the wickedness of idolatry. Because you have rejected the word of the LORD, He has rejected you as king.”'),
  ('BSB', '1 Samuel', 9, 15, 24, 'Then Saul said to Samuel, “I have sinned; I have transgressed the LORD’s commandment and your instructions, because I feared the people and obeyed their voice.'),
  ('BSB', '1 Samuel', 9, 15, 25, 'Now therefore, please forgive my sin and return with me so I can worship the LORD.”'),
  ('BSB', '1 Samuel', 9, 15, 26, '“I will not return with you,” Samuel replied. “For you have rejected the word of the LORD, and He has rejected you as king over Israel.”'),
  ('BSB', '1 Samuel', 9, 15, 27, 'As Samuel turned to go, Saul grabbed the hem of his robe, and it tore.'),
  ('BSB', '1 Samuel', 9, 15, 28, 'So Samuel said to him, “The LORD has torn the kingdom of Israel from you today and has given it to your neighbor who is better than you.'),
  ('BSB', '1 Samuel', 9, 15, 29, 'Moreover, the Glory of Israel does not lie or change His mind, for He is not a man, that He should change His mind.”'),
  ('BSB', '1 Samuel', 9, 15, 30, '“I have sinned,” Saul replied. “Please honor me now before the elders of my people and before Israel. Come back with me, so that I may worship the LORD your God.”'),
  ('BSB', '1 Samuel', 9, 15, 31, 'So Samuel went back with Saul, and Saul worshiped the LORD.'),
  ('BSB', '1 Samuel', 9, 15, 32, 'Then Samuel said, “Bring me Agag king of the Amalekites.” Agag came to him cheerfully, for he thought, “Surely the bitterness of death is past.”'),
  ('BSB', '1 Samuel', 9, 15, 33, 'But Samuel declared: “As your sword has made women childless, so your mother will be childless among women.” And Samuel hacked Agag to pieces before the LORD at Gilgal.'),
  ('BSB', '1 Samuel', 9, 15, 34, 'Then Samuel went to Ramah, but Saul went up to his home in Gibeah of Saul.'),
  ('BSB', '1 Samuel', 9, 15, 35, 'And to the day of his death, Samuel never again visited Saul. Samuel mourned for Saul, and the LORD regretted that He had made Saul king over Israel.'),
  ('BSB', '1 Samuel', 9, 16, 1, 'Now the LORD said to Samuel, “How long are you going to mourn for Saul, since I have rejected him as king over Israel? Fill your horn with oil and go. I am sending you to Jesse of Bethlehem, for I have selected from his sons a king for Myself.”'),
  ('BSB', '1 Samuel', 9, 16, 2, '“How can I go?” Samuel asked. “Saul will hear of it and kill me!” The LORD answered, “Take a heifer with you and say, ‘I have come to sacrifice to the LORD.’'),
  ('BSB', '1 Samuel', 9, 16, 3, 'Then invite Jesse to the sacrifice, and I will show you what you are to do. You are to anoint for Me the one I indicate.”'),
  ('BSB', '1 Samuel', 9, 16, 4, 'So Samuel did what the LORD had said and went to Bethlehem. When the elders of the town met him, they trembled and asked, “Do you come in peace?”');
insert into control_room_bible (version, book, book_num, chapter, verse, text) values
  ('BSB', '1 Samuel', 9, 16, 5, '“In peace,” he replied. “I have come to sacrifice to the LORD. Consecrate yourselves and come with me to the sacrifice.” Then he consecrated Jesse and his sons and invited them to the sacrifice.'),
  ('BSB', '1 Samuel', 9, 16, 6, 'When they arrived, Samuel saw Eliab and said, “Surely here before the LORD is His anointed.”'),
  ('BSB', '1 Samuel', 9, 16, 7, 'But the LORD said to Samuel, “Do not consider his appearance or height, for I have rejected him; the LORD does not see as man does. For man sees the outward appearance, but the LORD sees the heart.”'),
  ('BSB', '1 Samuel', 9, 16, 8, 'Then Jesse called Abinadab and presented him to Samuel, who said, “The LORD has not chosen this one either.”'),
  ('BSB', '1 Samuel', 9, 16, 9, 'Next Jesse presented Shammah, but Samuel said, “The LORD has not chosen this one either.”'),
  ('BSB', '1 Samuel', 9, 16, 10, 'Thus Jesse made seven of his sons pass before Samuel, but Samuel told him, “The LORD has not chosen any of these.”'),
  ('BSB', '1 Samuel', 9, 16, 11, 'And Samuel asked him, “Are these all the sons you have?” “There is still the youngest,” Jesse replied, “but he is tending the sheep.” “Send for him,” Samuel replied. “For we will not sit down to eat until he arrives.”'),
  ('BSB', '1 Samuel', 9, 16, 12, 'So Jesse sent for his youngest son and brought him in. He was ruddy, with beautiful eyes and a handsome appearance. And the LORD said, “Rise and anoint him, for he is the one.”'),
  ('BSB', '1 Samuel', 9, 16, 13, 'So Samuel took the horn of oil and anointed him in the presence of his brothers, and the Spirit of the LORD rushed upon David from that day forward. Then Samuel set out and went to Ramah.'),
  ('BSB', '1 Samuel', 9, 16, 14, 'After the Spirit of the LORD had departed from Saul, a spirit of distress from the LORD began to torment him.'),
  ('BSB', '1 Samuel', 9, 16, 15, 'Saul’s servants said to him, “Surely a spirit of distress from God is tormenting you.'),
  ('BSB', '1 Samuel', 9, 16, 16, 'Let our lord command your servants here to seek out someone who can skillfully play the harp. Whenever the spirit of distress from God is upon you, he is to play it, and you will be well.”'),
  ('BSB', '1 Samuel', 9, 16, 17, 'And Saul commanded his servants, “Find me someone who plays well, and bring him to me.”'),
  ('BSB', '1 Samuel', 9, 16, 18, 'One of the servants answered, “I have seen a son of Jesse of Bethlehem who knows how to play the harp. He is a mighty man of valor, a warrior, eloquent and handsome, and the LORD is with him.”'),
  ('BSB', '1 Samuel', 9, 16, 19, 'So Saul sent messengers to Jesse and said, “Send me your son David, who is with the sheep.”'),
  ('BSB', '1 Samuel', 9, 16, 20, 'And Jesse took a donkey loaded with bread, a skin of wine, and one young goat, and sent them to Saul with his son David.'),
  ('BSB', '1 Samuel', 9, 16, 21, 'When David came to Saul and entered his service, Saul admired him greatly, and David became his armor-bearer.'),
  ('BSB', '1 Samuel', 9, 16, 22, 'Then Saul sent word to Jesse, saying, “Let David remain in my service, for I am pleased with him.”'),
  ('BSB', '1 Samuel', 9, 16, 23, 'And whenever the spirit from God came upon Saul, David would pick up his harp and play, and Saul would become well, and the spirit of distress would depart from him.'),
  ('BSB', '1 Samuel', 9, 17, 1, 'Now the Philistines gathered their forces for war at Socoh in Judah, and they camped between Socoh and Azekah in Ephes-dammim.'),
  ('BSB', '1 Samuel', 9, 17, 2, 'Saul and the men of Israel assembled and camped in the Valley of Elah, arraying themselves for battle against the Philistines.'),
  ('BSB', '1 Samuel', 9, 17, 3, 'The Philistines stood on one hill and the Israelites stood on another, with the valley between them.'),
  ('BSB', '1 Samuel', 9, 17, 4, 'Then a champion named Goliath, who was from Gath, came out from the Philistine camp. He was six cubits and a span in height,'),
  ('BSB', '1 Samuel', 9, 17, 5, 'and he had a bronze helmet on his head. He wore a bronze coat of mail weighing five thousand shekels,'),
  ('BSB', '1 Samuel', 9, 17, 6, 'and he had armor of bronze on his legs and a javelin of bronze slung between his shoulders.'),
  ('BSB', '1 Samuel', 9, 17, 7, 'The shaft of his spear was like a weaver’s beam, and its iron point weighed six hundred shekels. In addition, his shield bearer went before him.'),
  ('BSB', '1 Samuel', 9, 17, 8, 'And Goliath stood and shouted to the ranks of Israel, “Why do you come out and array yourselves for battle? Am I not a Philistine, and are you not servants of Saul? Choose one of your men and have him come down against me.'),
  ('BSB', '1 Samuel', 9, 17, 9, 'If he is able to fight me and kill me, then we will be your servants. But if I prevail against him and kill him, then you shall be our servants and labor for us.”'),
  ('BSB', '1 Samuel', 9, 17, 10, 'Then the Philistine said, “I defy the ranks of Israel this day! Give me a man to fight!”'),
  ('BSB', '1 Samuel', 9, 17, 11, 'On hearing the words of the Philistine, Saul and all the Israelites were dismayed and greatly afraid.'),
  ('BSB', '1 Samuel', 9, 17, 12, 'Now David was the son of a man named Jesse, an Ephrathite from Bethlehem of Judah who had eight sons in the days of Saul. And Jesse was old and well along in years.'),
  ('BSB', '1 Samuel', 9, 17, 13, 'The three older sons of Jesse had followed Saul into battle: The firstborn was Eliab, the second was Abinadab, and the third was Shammah.'),
  ('BSB', '1 Samuel', 9, 17, 14, 'And David was the youngest. The three oldest had followed Saul,'),
  ('BSB', '1 Samuel', 9, 17, 15, 'but David went back and forth from Saul to tend his father’s sheep in Bethlehem.'),
  ('BSB', '1 Samuel', 9, 17, 16, 'For forty days the Philistine came forward every morning and evening to take his stand.'),
  ('BSB', '1 Samuel', 9, 17, 17, 'One day Jesse said to his son David, “Take this ephah of roasted grain and these ten loaves of bread for your brothers and hurry to their camp.'),
  ('BSB', '1 Samuel', 9, 17, 18, 'Take also these ten portions of cheese to the commander of their unit. Check on the welfare of your brothers and bring back an assurance from them.'),
  ('BSB', '1 Samuel', 9, 17, 19, 'They are with Saul and all the men of Israel in the Valley of Elah, fighting against the Philistines.”'),
  ('BSB', '1 Samuel', 9, 17, 20, 'So David got up early in the morning, left the flock with a keeper, loaded up, and set out as Jesse had instructed him. He reached the camp as the army was marching out to its position and shouting the battle cry.'),
  ('BSB', '1 Samuel', 9, 17, 21, 'And Israel and the Philistines arrayed in formation against each other.'),
  ('BSB', '1 Samuel', 9, 17, 22, 'Then David left his supplies in the care of the quartermaster and ran to the battle line. When he arrived, he asked his brothers how they were doing.'),
  ('BSB', '1 Samuel', 9, 17, 23, 'And as he was speaking with them, suddenly the champion named Goliath, the Philistine from Gath, came forward from the Philistines and shouted his usual words, which David also heard.'),
  ('BSB', '1 Samuel', 9, 17, 24, 'When all the men of Israel saw Goliath, they fled from him in great fear.'),
  ('BSB', '1 Samuel', 9, 17, 25, 'Now the men of Israel had been saying, “Do you see this man who keeps coming out to defy Israel? To the man who kills him the king will give great riches. And he will give him his daughter in marriage and exempt his father’s house from taxation in Israel.”'),
  ('BSB', '1 Samuel', 9, 17, 26, 'David asked the men who were standing with him, “What will be done for the man who kills this Philistine and removes this disgrace from Israel? Just who is this uncircumcised Philistine, that he should defy the armies of the living God?”'),
  ('BSB', '1 Samuel', 9, 17, 27, 'The people told him about the offer, saying, “That is what will be done for the man who kills him.”'),
  ('BSB', '1 Samuel', 9, 17, 28, 'Now when David’s oldest brother Eliab heard him speaking to the men, his anger burned against David. “Why have you come down here?” he asked. “And with whom did you leave those few sheep in the wilderness? I know your pride and wickedness of heart—you have come down to see the battle!”'),
  ('BSB', '1 Samuel', 9, 17, 29, '“What have I done now?” said David. “Was it not just a question?”'),
  ('BSB', '1 Samuel', 9, 17, 30, 'Then he turned from him toward another and asked about the offer, and those people answered him just as the first ones had answered.'),
  ('BSB', '1 Samuel', 9, 17, 31, 'Now David’s words were overheard and reported to Saul, who called for him.'),
  ('BSB', '1 Samuel', 9, 17, 32, 'And David said to Saul, “Let no man’s heart fail on account of this Philistine. Your servant will go and fight him!”'),
  ('BSB', '1 Samuel', 9, 17, 33, 'But Saul replied, “You cannot go out against this Philistine to fight him. You are just a boy, and he has been a warrior from his youth.”'),
  ('BSB', '1 Samuel', 9, 17, 34, 'David replied, “Your servant has been tending his father’s sheep, and whenever a lion or a bear came and carried off a lamb from the flock,'),
  ('BSB', '1 Samuel', 9, 17, 35, 'I went after it, struck it down, and delivered the lamb from its mouth. If it reared up against me, I would grab it by its fur, strike it down, and kill it.'),
  ('BSB', '1 Samuel', 9, 17, 36, 'Your servant has killed lions and bears; this uncircumcised Philistine will be like one of them, for he has defied the armies of the living God.”'),
  ('BSB', '1 Samuel', 9, 17, 37, 'David added, “The LORD, who delivered me from the claws of the lion and the bear, will deliver me from the hand of this Philistine.” “Go,” said Saul, “and may the LORD be with you.”'),
  ('BSB', '1 Samuel', 9, 17, 38, 'Then Saul clothed David in his own tunic, put a bronze helmet on his head, and dressed him in armor.'),
  ('BSB', '1 Samuel', 9, 17, 39, 'David strapped his sword over the tunic and tried to walk, but he was not accustomed to them. “I cannot walk in these,” David said to Saul. “I am not accustomed to them.” So David took them off.'),
  ('BSB', '1 Samuel', 9, 17, 40, 'And David took his staff in his hand, selected five smooth stones from the brook, and put them in the pouch of his shepherd’s bag. And with his sling in hand, he approached the Philistine.'),
  ('BSB', '1 Samuel', 9, 17, 41, 'Now the Philistine came closer and closer to David, with his shield-bearer before him.'),
  ('BSB', '1 Samuel', 9, 17, 42, 'When the Philistine looked and saw David, he despised him because he was just a boy, ruddy and handsome.'),
  ('BSB', '1 Samuel', 9, 17, 43, '“Am I a dog,” he said to David, “that you come at me with sticks?” And the Philistine cursed David by his gods.'),
  ('BSB', '1 Samuel', 9, 17, 44, '“Come here,” he called to David, “and I will give your flesh to the birds of the air and the beasts of the field!”'),
  ('BSB', '1 Samuel', 9, 17, 45, 'But David said to the Philistine, “You come against me with sword and spear and javelin, but I come against you in the name of the LORD of Hosts, the God of the armies of Israel, whom you have defied.'),
  ('BSB', '1 Samuel', 9, 17, 46, 'This day the LORD will deliver you into my hand. This day I will strike you down, cut off your head, and give the carcasses of the Philistines to the birds of the air and the creatures of the earth. Then the whole world will know that there is a God in Israel.'),
  ('BSB', '1 Samuel', 9, 17, 47, 'And all those assembled here will know that it is not by sword or spear that the LORD saves; for the battle is the LORD’s, and He will give all of you into our hands.”'),
  ('BSB', '1 Samuel', 9, 17, 48, 'As the Philistine started forward to attack him, David ran quickly toward the battle line to meet him.'),
  ('BSB', '1 Samuel', 9, 17, 49, 'Then David reached into his bag, took out a stone, and slung it, striking the Philistine on the forehead. The stone sank into his forehead, and he fell facedown on the ground.'),
  ('BSB', '1 Samuel', 9, 17, 50, 'Thus David prevailed over the Philistine with a sling and a stone; without a sword in his hand he struck down the Philistine and killed him.'),
  ('BSB', '1 Samuel', 9, 17, 51, 'David ran and stood over him. He grabbed the Philistine’s sword and pulled it from its sheath and killed him; and he cut off his head with the sword. When the Philistines saw that their hero was dead, they turned and ran.'),
  ('BSB', '1 Samuel', 9, 17, 52, 'Then the men of Israel and Judah charged forward with a shout and pursued the Philistines to the entrance of Gath and to the gates of Ekron. And the bodies of the Philistines were strewn along the Shaaraim road to Gath and Ekron.'),
  ('BSB', '1 Samuel', 9, 17, 53, 'When the Israelites returned from their pursuit of the Philistines, they plundered their camps.'),
  ('BSB', '1 Samuel', 9, 17, 54, 'David took the head of the Philistine and brought it to Jerusalem, and he put Goliath’s weapons in his own tent.'),
  ('BSB', '1 Samuel', 9, 17, 55, 'As Saul had watched David going out to confront the Philistine, he said to Abner the commander of the army, “Abner, whose son is this young man?” “As surely as you live, O king,” Abner replied, “I do not know.”'),
  ('BSB', '1 Samuel', 9, 17, 56, '“Find out whose son this young man is!” said the king.'),
  ('BSB', '1 Samuel', 9, 17, 57, 'So when David returned from killing the Philistine, still holding his head in his hand, Abner took him and brought him before Saul.'),
  ('BSB', '1 Samuel', 9, 17, 58, '“Whose son are you, young man?” asked Saul. “I am the son of your servant Jesse of Bethlehem,” David replied.'),
  ('BSB', '1 Samuel', 9, 18, 1, 'After David had finished speaking with Saul, the souls of Jonathan and David were knit together, and Jonathan loved him as himself.'),
  ('BSB', '1 Samuel', 9, 18, 2, 'And from that day Saul kept David with him and did not let him return to his father’s house.'),
  ('BSB', '1 Samuel', 9, 18, 3, 'Then Jonathan made a covenant with David because he loved him as himself.'),
  ('BSB', '1 Samuel', 9, 18, 4, 'And Jonathan removed the robe he was wearing and gave it to David, along with his tunic, his sword, his bow, and his belt.'),
  ('BSB', '1 Samuel', 9, 18, 5, 'So David marched out and prospered in everything Saul sent him to do, and Saul set him over the men of war. And this was pleasing in the sight of all the people, and of Saul’s officers as well.'),
  ('BSB', '1 Samuel', 9, 18, 6, 'As the troops were returning home after David had killed the Philistine, the women came out of all the cities of Israel to meet King Saul with singing and dancing, with joyful songs, and with tambourines and other instruments.'),
  ('BSB', '1 Samuel', 9, 18, 7, 'And as the women danced, they sang out: “Saul has slain his thousands, and David his tens of thousands.”'),
  ('BSB', '1 Samuel', 9, 18, 8, 'And Saul was furious and resented this song. “They have ascribed tens of thousands to David,” he said, “but only thousands to me. What more can he have but the kingdom?”'),
  ('BSB', '1 Samuel', 9, 18, 9, 'And from that day forward Saul kept a jealous eye on David.'),
  ('BSB', '1 Samuel', 9, 18, 10, 'The next day a spirit of distress sent from God came upon Saul, and he prophesied inside the house while David played the harp as usual. Now Saul was holding a spear,'),
  ('BSB', '1 Samuel', 9, 18, 11, 'and he hurled it, thinking, “I will pin David to the wall.” But David eluded him twice.'),
  ('BSB', '1 Samuel', 9, 18, 12, 'So Saul was afraid of David, because the LORD was with David but had departed from Saul.'),
  ('BSB', '1 Samuel', 9, 18, 13, 'Therefore Saul sent David away and gave him command of a thousand men. David led the troops out to battle and back,'),
  ('BSB', '1 Samuel', 9, 18, 14, 'and he continued to prosper in all his ways, because the LORD was with him.'),
  ('BSB', '1 Samuel', 9, 18, 15, 'When Saul saw that David was very successful, he was afraid of him.'),
  ('BSB', '1 Samuel', 9, 18, 16, 'But all Israel and Judah loved David, because he was leading them out to battle and back.'),
  ('BSB', '1 Samuel', 9, 18, 17, 'Then Saul said to David, “Here is my older daughter Merab. I will give her to you in marriage. Only be valiant for me and fight the LORD’s battles.” But Saul was thinking, “I need not raise my hand against him; let the hand of the Philistines be against him.”'),
  ('BSB', '1 Samuel', 9, 18, 18, 'And David said to Saul, “Who am I, and what is my family or my father’s clan in Israel, that I should become the son-in-law of the king?”'),
  ('BSB', '1 Samuel', 9, 18, 19, 'So when it was time to give Saul’s daughter Merab to David, she was given in marriage to Adriel of Meholah.'),
  ('BSB', '1 Samuel', 9, 18, 20, 'Now Saul’s daughter Michal loved David, and when this was reported to Saul, it pleased him.'),
  ('BSB', '1 Samuel', 9, 18, 21, '“I will give her to David,” Saul thought, “so that she may be a snare to him, and the hand of the Philistines may be against him.” So Saul said to David, “For a second time now you can be my son-in-law.”'),
  ('BSB', '1 Samuel', 9, 18, 22, 'Then Saul ordered his servants, “Speak to David privately and tell him, ‘Behold, the king is pleased with you, and all his servants love you. Now therefore, become his son-in-law.’”'),
  ('BSB', '1 Samuel', 9, 18, 23, 'But when Saul’s servants relayed these words to David, he replied, “Does it seem trivial in your sight to be the son-in-law of the king? I am a poor man and lightly esteemed.”'),
  ('BSB', '1 Samuel', 9, 18, 24, 'And the servants told Saul what David had said.'),
  ('BSB', '1 Samuel', 9, 18, 25, 'Saul replied, “Say to David, ‘The king desires no other dowry but a hundred Philistine foreskins as revenge on his enemies.’” But Saul intended to cause David’s death at the hands of the Philistines.'),
  ('BSB', '1 Samuel', 9, 18, 26, 'When the servants reported these terms to David, he was pleased to become the king’s son-in-law. Before the wedding day arrived,'),
  ('BSB', '1 Samuel', 9, 18, 27, 'David and his men went out and killed two hundred Philistines. He brought their foreskins and presented them as payment in full to become the king’s son-in-law. Then Saul gave his daughter Michal to David in marriage.'),
  ('BSB', '1 Samuel', 9, 18, 28, 'When Saul realized that the LORD was with David and that his daughter Michal loved David,'),
  ('BSB', '1 Samuel', 9, 18, 29, 'he grew even more afraid of David. So from then on Saul was David’s enemy.'),
  ('BSB', '1 Samuel', 9, 18, 30, 'Every time the Philistine commanders came out for battle, David was more successful than all of Saul’s officers, so that his name was highly esteemed.'),
  ('BSB', '1 Samuel', 9, 19, 1, 'Then Saul ordered his son Jonathan and all his servants to kill David. But Jonathan delighted greatly in David,'),
  ('BSB', '1 Samuel', 9, 19, 2, 'so he warned David, saying, “My father Saul intends to kill you. Be on your guard in the morning; find a secret place and hide there.'),
  ('BSB', '1 Samuel', 9, 19, 3, 'I will go out and stand beside my father in the field where you are, so I can ask about you. And if I find out anything, I will tell you.”'),
  ('BSB', '1 Samuel', 9, 19, 4, 'Then Jonathan spoke well of David to his father Saul and said to him, “The king should not sin against his servant David; he has not sinned against you. In fact, his actions have been highly beneficial to you.'),
  ('BSB', '1 Samuel', 9, 19, 5, 'He took his life in his hands when he struck down the Philistine, and the LORD worked a great salvation for all Israel. You saw it and rejoiced, so why would you sin against innocent blood by killing David for no reason?”'),
  ('BSB', '1 Samuel', 9, 19, 6, 'Saul listened to the voice of Jonathan and swore an oath: “As surely as the LORD lives, David will not be put to death.”'),
  ('BSB', '1 Samuel', 9, 19, 7, 'So Jonathan summoned David and told him all these things. Then Jonathan brought David to Saul to serve him as he had before.'),
  ('BSB', '1 Samuel', 9, 19, 8, 'When war broke out again, David went out and fought the Philistines and struck them with such a mighty blow that they fled before him.'),
  ('BSB', '1 Samuel', 9, 19, 9, 'But as Saul was sitting in his house with his spear in his hand, a spirit of distress from the LORD came upon him. While David was playing the harp,'),
  ('BSB', '1 Samuel', 9, 19, 10, 'Saul tried to pin him to the wall with his spear. But the spear struck the wall and David eluded him, ran away, and escaped that night.'),
  ('BSB', '1 Samuel', 9, 19, 11, 'Then Saul sent messengers to David’s house to watch him and kill him in the morning. But David’s wife Michal warned him, “If you do not run for your life tonight, tomorrow you will be dead!”'),
  ('BSB', '1 Samuel', 9, 19, 12, 'So Michal lowered David from the window, and he ran away and escaped.'),
  ('BSB', '1 Samuel', 9, 19, 13, 'Then Michal took a household idol and laid it in the bed, placed some goat hair on its head, and covered it with a garment.'),
  ('BSB', '1 Samuel', 9, 19, 14, 'When Saul sent the messengers to seize David, Michal said, “He is ill.”'),
  ('BSB', '1 Samuel', 9, 19, 15, 'But Saul sent the messengers back to see David and told them, “Bring him up to me in his bed so I can kill him.”'),
  ('BSB', '1 Samuel', 9, 19, 16, 'And when the messengers entered, there was the idol in the bed with the quilt of goats’ hair on its head.'),
  ('BSB', '1 Samuel', 9, 19, 17, 'And Saul said to Michal, “Why did you deceive me like this? You sent my enemy away and he has escaped!” Michal replied, “He said to me, ‘Help me get away, or I will kill you!’”'),
  ('BSB', '1 Samuel', 9, 19, 18, 'So David ran away and escaped. And he went to Samuel at Ramah and told him all that Saul had done to him. Then he and Samuel went to Naioth and stayed there.'),
  ('BSB', '1 Samuel', 9, 19, 19, 'When Saul was told that David was at Naioth in Ramah,'),
  ('BSB', '1 Samuel', 9, 19, 20, 'he sent messengers to capture him. But when they saw the group of prophets prophesying, with Samuel leading them, the Spirit of God came upon them, and Saul’s messengers also began to prophesy.'),
  ('BSB', '1 Samuel', 9, 19, 21, 'When this was reported to Saul, he sent more messengers, but they began to prophesy as well. So Saul tried again and sent messengers a third time, and even they began to prophesy.'),
  ('BSB', '1 Samuel', 9, 19, 22, 'Finally, Saul himself left for Ramah and came to the large cistern at Secu, where he asked, “Where are Samuel and David?” “At Naioth in Ramah,” he was told.'),
  ('BSB', '1 Samuel', 9, 19, 23, 'So Saul went to Naioth in Ramah. But the Spirit of God came upon even Saul, and he walked along prophesying until he came to Naioth in Ramah.'),
  ('BSB', '1 Samuel', 9, 19, 24, 'Then Saul stripped off his robes and also prophesied before Samuel. And he collapsed and lay naked all that day and night. That is why it is said, “Is Saul also among the prophets?”'),
  ('BSB', '1 Samuel', 9, 20, 1, 'Then David fled from Naioth in Ramah. He came to Jonathan and asked, “What have I done? What is my iniquity? How have I sinned against your father, that he wants to take my life?”'),
  ('BSB', '1 Samuel', 9, 20, 2, '“Far from it!” Jonathan replied. “You will not die. Indeed, my father does nothing, great or small, without telling me. So why would he hide this matter from me? This cannot be true!”'),
  ('BSB', '1 Samuel', 9, 20, 3, 'But David again vowed, “Your father knows very well that I have found favor in your eyes, and he has said, ‘Jonathan must not know of this, or he will be grieved.’ As surely as the LORD lives and as you yourself live, there is but a step between me and death.”'),
  ('BSB', '1 Samuel', 9, 20, 4, 'Then Jonathan said to David, “Whatever you desire, I will do for you.”'),
  ('BSB', '1 Samuel', 9, 20, 5, 'So David told him, “Look, tomorrow is the New Moon, and I am supposed to dine with the king. Instead, let me go and hide in the field until the third evening from now.'),
  ('BSB', '1 Samuel', 9, 20, 6, 'If your father misses me at all, tell him, ‘David urgently requested my permission to hurry to Bethlehem, his hometown, because there is an annual sacrifice for his whole clan.’'),
  ('BSB', '1 Samuel', 9, 20, 7, 'If he says, ‘Good,’ then your servant is safe, but if he is enraged, you will know he has evil intentions.'),
  ('BSB', '1 Samuel', 9, 20, 8, 'Therefore deal faithfully with your servant, for you have brought me into a covenant with you before the LORD. If there is iniquity in me, then kill me yourself; why should you bring me to your father?”'),
  ('BSB', '1 Samuel', 9, 20, 9, '“Never!” Jonathan replied. “If I ever found out that my father had evil intentions against you, would I not tell you?”'),
  ('BSB', '1 Samuel', 9, 20, 10, 'Then David asked Jonathan, “Who will tell me if your father answers you harshly?”'),
  ('BSB', '1 Samuel', 9, 20, 11, '“Come,” he replied, “let us go out to the field.” So the two of them went out into the field,'),
  ('BSB', '1 Samuel', 9, 20, 12, 'and Jonathan said, “By the LORD, the God of Israel, I will sound out my father by this time tomorrow or the next day. If he is favorable toward you, will I not send for you and tell you?'),
  ('BSB', '1 Samuel', 9, 20, 13, 'But if my father intends to bring evil on you, then may the LORD punish me, and ever so severely, if I do not tell you and send you on your way in safety. May the LORD be with you, just as He has been with my father.'),
  ('BSB', '1 Samuel', 9, 20, 14, 'And as long as I live, treat me with the LORD’s loving devotion, that I may not die,'),
  ('BSB', '1 Samuel', 9, 20, 15, 'and do not ever cut off your loving devotion from my household—not even when the LORD cuts off every one of David’s enemies from the face of the earth.”'),
  ('BSB', '1 Samuel', 9, 20, 16, 'So Jonathan made a covenant with the house of David, saying, “May the LORD hold David’s enemies accountable.”'),
  ('BSB', '1 Samuel', 9, 20, 17, 'And Jonathan had David reaffirm his vow out of love for him, for Jonathan loved David as he loved himself.'),
  ('BSB', '1 Samuel', 9, 20, 18, 'Then Jonathan said to David, “Tomorrow is the New Moon, and you will be missed if your seat is empty.'),
  ('BSB', '1 Samuel', 9, 20, 19, 'When you have stayed three days, hurry down to the place you hid on the day this trouble began, and remain beside the stone Ezel.'),
  ('BSB', '1 Samuel', 9, 20, 20, 'I will shoot three arrows to the side of it, as if I were aiming at a target.'),
  ('BSB', '1 Samuel', 9, 20, 21, 'Then I will send a boy and say, ‘Go, find the arrows!’ Now, if I expressly say to him, ‘Look, the arrows are on this side of you; bring them,’ then come, because as surely as the LORD lives, it is safe for you and there is no danger.'),
  ('BSB', '1 Samuel', 9, 20, 22, 'But if I say to the young man, ‘Look, the arrows are beyond you,’ then you must go, for the LORD has sent you away.'),
  ('BSB', '1 Samuel', 9, 20, 23, 'And as for the matter you and I have discussed, the LORD is a witness between you and me forever.”'),
  ('BSB', '1 Samuel', 9, 20, 24, 'So David hid in the field, and when the New Moon had come, the king sat down to eat.'),
  ('BSB', '1 Samuel', 9, 20, 25, 'He sat in his usual place by the wall, opposite Jonathan and beside Abner, but David’s place was empty.'),
  ('BSB', '1 Samuel', 9, 20, 26, 'Saul said nothing that day because he thought, “Something has happened to David to make him ceremonially unclean—surely he is unclean.”'),
  ('BSB', '1 Samuel', 9, 20, 27, 'But on the day after the New Moon, the second day, David’s place was still empty, and Saul asked his son Jonathan, “Why hasn’t the son of Jesse come to the meal either yesterday or today?”'),
  ('BSB', '1 Samuel', 9, 20, 28, 'Jonathan answered, “David urgently requested my permission to go to Bethlehem,'),
  ('BSB', '1 Samuel', 9, 20, 29, 'saying, ‘Please let me go, because our clan is holding a sacrifice in the city, and my brother has told me to be there. So now, if I have found favor in your eyes, please let me go and see my brothers.’ That is why he did not come to the king’s table.”'),
  ('BSB', '1 Samuel', 9, 20, 30, 'Then Saul’s anger burned against Jonathan, and he said to him, “You son of a perverse and rebellious woman! Do I not know that you have chosen the son of Jesse to your own shame and to the disgrace of the mother who bore you?'),
  ('BSB', '1 Samuel', 9, 20, 31, 'For as long as the son of Jesse lives on this earth, neither you nor your kingship shall be established. Now send for him and bring him to me, for he must surely die!”'),
  ('BSB', '1 Samuel', 9, 20, 32, '“Why must he be put to death?” Jonathan replied. “What has he done?”'),
  ('BSB', '1 Samuel', 9, 20, 33, 'Then Saul hurled his spear at Jonathan to kill him; so Jonathan knew that his father was determined to kill David.'),
  ('BSB', '1 Samuel', 9, 20, 34, 'Jonathan got up from the table in fierce anger and did not eat any food that second day of the month, for he was grieved by his father’s shameful treatment of David.'),
  ('BSB', '1 Samuel', 9, 20, 35, 'In the morning Jonathan went out to the field for the appointment with David, and a small boy was with him.'),
  ('BSB', '1 Samuel', 9, 20, 36, 'He said to the boy, “Run and find the arrows I shoot.” And as the boy ran, Jonathan shot an arrow beyond him.'),
  ('BSB', '1 Samuel', 9, 20, 37, 'When the boy reached the place where Jonathan’s arrow had fallen, Jonathan called to him, “Isn’t the arrow beyond you?”'),
  ('BSB', '1 Samuel', 9, 20, 38, 'Then Jonathan cried out, “Hurry! Make haste! Do not delay!” So the boy picked up the arrow and returned to his master.'),
  ('BSB', '1 Samuel', 9, 20, 39, 'But the boy did not know anything; only Jonathan and David knew the arrangement.'),
  ('BSB', '1 Samuel', 9, 20, 40, 'Then Jonathan gave his equipment to the boy and said, “Go, take it back to the city.”'),
  ('BSB', '1 Samuel', 9, 20, 41, 'When the young man had gone, David got up from the south side of the stone, fell facedown, and bowed three times. Then he and Jonathan kissed each other and wept together—though David wept more.'),
  ('BSB', '1 Samuel', 9, 20, 42, 'And Jonathan said to David, “Go in peace, for the two of us have sworn in the name of the LORD, saying, ‘May the LORD be a witness between you and me, and between your descendants and mine forever.’” Then David got up and departed, and Jonathan went back into the city.'),
  ('BSB', '1 Samuel', 9, 21, 1, 'Then David came to Nob, to Ahimelech the priest. And when Ahimelech met David, he trembled and asked him, “Why are you alone? Why is no one with you?”'),
  ('BSB', '1 Samuel', 9, 21, 2, '“The king has given me a mission,” David replied. “He told me no one is to know about the mission or charge. And I have directed my young men to meet me at a certain place.'),
  ('BSB', '1 Samuel', 9, 21, 3, 'Now then, what do you have on hand? Give me five loaves of bread, or whatever can be found.”'),
  ('BSB', '1 Samuel', 9, 21, 4, '“There is no common bread on hand,” the priest replied, “but there is some consecrated bread—provided that the young men have kept themselves from women.”'),
  ('BSB', '1 Samuel', 9, 21, 5, 'David answered, “Women have indeed been kept from us, as is usual when I set out. And the equipment of the young men is holy, as it is even on common missions, and all the more at this time.”'),
  ('BSB', '1 Samuel', 9, 21, 6, 'So the priest gave him the consecrated bread, since there was no bread there but the Bread of the Presence, which had been removed from before the LORD and replaced with hot bread on the day it was taken away.'),
  ('BSB', '1 Samuel', 9, 21, 7, 'Now one of Saul’s servants was there that day, detained before the LORD. And his name was Doeg the Edomite, the chief shepherd for Saul.'),
  ('BSB', '1 Samuel', 9, 21, 8, 'Then David asked Ahimelech, “Is there not a spear or sword on hand here? For I have brought neither my sword nor my weapons with me, because the king’s business was urgent.”'),
  ('BSB', '1 Samuel', 9, 21, 9, 'The priest replied, “The sword of Goliath the Philistine, whom you killed in the Valley of Elah, is here; it is wrapped in a cloth behind the ephod. If you want, you may take it. For there is no other but this one.” And David said, “There is none like it; give it to me.”'),
  ('BSB', '1 Samuel', 9, 21, 10, 'That day David fled from Saul and went to Achish king of Gath.'),
  ('BSB', '1 Samuel', 9, 21, 11, 'But the servants of Achish said to him, “Is this not David, the king of the land? Did they not sing about him in their dances, saying: ‘Saul has slain his thousands, and David his tens of thousands’?”'),
  ('BSB', '1 Samuel', 9, 21, 12, 'Now David took these words to heart and was very much afraid of Achish the king of Gath.'),
  ('BSB', '1 Samuel', 9, 21, 13, 'So he changed his behavior before them and feigned madness in their hands; he scratched on the doors of the gate and let his saliva run down his beard.'),
  ('BSB', '1 Samuel', 9, 21, 14, 'Then Achish said to his servants, “Look, you can see that the man is insane! Why have you brought him to me?'),
  ('BSB', '1 Samuel', 9, 21, 15, 'Am I in need of madmen, that you have brought this man to rave in my presence? Must this man come into my house?”'),
  ('BSB', '1 Samuel', 9, 22, 1, 'So David left Gath and took refuge in the cave of Adullam. When his brothers and the rest of his father’s household heard about it, they went down to him there.'),
  ('BSB', '1 Samuel', 9, 22, 2, 'And all who were distressed or indebted or discontented rallied around him, and he became their leader. About four hundred men were with him.'),
  ('BSB', '1 Samuel', 9, 22, 3, 'From there David went to Mizpeh of Moab, where he said to the king of Moab, “Please let my father and mother stay with you until I learn what God will do for me.”'),
  ('BSB', '1 Samuel', 9, 22, 4, 'So he left them in the care of the king of Moab, and they stayed with him the whole time David was in the stronghold.'),
  ('BSB', '1 Samuel', 9, 22, 5, 'Then the prophet Gad said to David, “Do not stay in the stronghold. Depart and go into the land of Judah.” So David left and went to the forest of Hereth.'),
  ('BSB', '1 Samuel', 9, 22, 6, 'Soon Saul learned that David and his men had been discovered. At that time Saul was in Gibeah, sitting under the tamarisk tree on the hill at Gibeah, with his spear in hand and all his servants standing around him.'),
  ('BSB', '1 Samuel', 9, 22, 7, 'Then Saul said to his servants, “Listen, men of Benjamin! Is the son of Jesse giving all of you fields and vineyards and making you commanders of thousands or hundreds?'),
  ('BSB', '1 Samuel', 9, 22, 8, 'Is that why all of you have conspired against me? Not one of you told me that my own son had made a covenant with the son of Jesse. Not one of you has shown concern for me or revealed to me that my son has stirred up my own servant to lie in wait against me, as is the case today.”'),
  ('BSB', '1 Samuel', 9, 22, 9, 'But Doeg the Edomite, who had stationed himself with Saul’s servants, answered: “I saw the son of Jesse come to Ahimelech son of Ahitub at Nob.'),
  ('BSB', '1 Samuel', 9, 22, 10, 'Ahimelech inquired of the LORD for him and gave him provisions. He also gave him the sword of Goliath the Philistine.”'),
  ('BSB', '1 Samuel', 9, 22, 11, 'Then the king sent messengers to summon Ahimelech the priest, the son of Ahitub, and his father’s whole family, who were priests at Nob. And all of them came to the king.'),
  ('BSB', '1 Samuel', 9, 22, 12, '“Listen now, son of Ahitub,” said Saul. “Here I am, my lord,” he replied.'),
  ('BSB', '1 Samuel', 9, 22, 13, 'And Saul asked him, “Why have you and the son of Jesse conspired against me? You gave him bread and a sword and inquired of God for him so that he could rise up against me to lie in wait, as he is doing today.”'),
  ('BSB', '1 Samuel', 9, 22, 14, 'Ahimelech answered the king, “Who among all your servants is as faithful as David, the king’s son-in-law, the captain of your bodyguard who is honored in your house?'),
  ('BSB', '1 Samuel', 9, 22, 15, 'Was that day the first time I inquired of God for him? Far be it from me! Let not the king accuse your servant or any of my father’s household, for your servant knew nothing of this whole affair—not in part or in whole.”'),
  ('BSB', '1 Samuel', 9, 22, 16, 'But the king replied, “You will surely die, Ahimelech, you and all your father’s house!”'),
  ('BSB', '1 Samuel', 9, 22, 17, 'Then the king ordered the guards at his side, “Turn and kill the priests of the LORD, because they too sided with David. For they knew he was fleeing, but they did not tell me.” But the king’s servants would not lift a hand to strike the priests of the LORD.'),
  ('BSB', '1 Samuel', 9, 22, 18, 'So the king ordered Doeg, “You turn and strike down the priests!” And Doeg the Edomite turned and struck down the priests himself. On that day he killed eighty-five men who wore the linen ephod.'),
  ('BSB', '1 Samuel', 9, 22, 19, 'He also put to the sword Nob, the city of the priests, with its men and women, children and infants, oxen, donkeys, and sheep.'),
  ('BSB', '1 Samuel', 9, 22, 20, 'But one of the sons of Ahimelech son of Ahitub escaped. His name was Abiathar, and he fled to David.'),
  ('BSB', '1 Samuel', 9, 22, 21, 'And Abiathar told David that Saul had killed the priests of the LORD.'),
  ('BSB', '1 Samuel', 9, 22, 22, 'Then David said to Abiathar, “I knew that Doeg the Edomite was there that day, and that he was sure to tell Saul. I myself am responsible for the lives of everyone in your father’s house.'),
  ('BSB', '1 Samuel', 9, 22, 23, 'Stay with me; do not be afraid, for he who seeks your life is seeking mine as well. You will be safe with me.”'),
  ('BSB', '1 Samuel', 9, 23, 1, 'Now it was reported to David, “Look, the Philistines are fighting against Keilah and looting the threshing floors.”'),
  ('BSB', '1 Samuel', 9, 23, 2, 'So David inquired of the LORD, “Should I go and attack these Philistines?” And the LORD said to David, “Go and attack the Philistines and save Keilah.”'),
  ('BSB', '1 Samuel', 9, 23, 3, 'But David’s men said to him, “Look, we are afraid here in Judah; how much more if we go to Keilah against the armies of the Philistines?”'),
  ('BSB', '1 Samuel', 9, 23, 4, 'Once again, David inquired of the LORD, and the LORD answered him: “Go at once to Keilah, for I will deliver the Philistines into your hand.”'),
  ('BSB', '1 Samuel', 9, 23, 5, 'Then David and his men went to Keilah, fought against the Philistines, and carried off their livestock, striking them with a mighty blow. So David saved the people of Keilah.'),
  ('BSB', '1 Samuel', 9, 23, 6, '(Now Abiathar son of Ahimelech had brought the ephod with him when he fled to David at Keilah.)'),
  ('BSB', '1 Samuel', 9, 23, 7, 'When Saul was told that David had gone to Keilah, he said, “God has delivered him into my hand, for he has trapped himself by entering a town with gates and bars.”'),
  ('BSB', '1 Samuel', 9, 23, 8, 'Then Saul summoned all his troops to go to war at Keilah and besiege David and his men.'),
  ('BSB', '1 Samuel', 9, 23, 9, 'When David learned that Saul was plotting evil against him, he said to Abiathar the priest, “Bring the ephod.”'),
  ('BSB', '1 Samuel', 9, 23, 10, 'And David said, “O LORD, God of Israel, Your servant has heard that Saul intends to come to Keilah and destroy the city on my account.'),
  ('BSB', '1 Samuel', 9, 23, 11, 'Will the citizens of Keilah surrender me into his hand? Will Saul come down, as Your servant has heard? O LORD, God of Israel, please tell Your servant.” “He will,” said the LORD.'),
  ('BSB', '1 Samuel', 9, 23, 12, 'So David asked, “Will the citizens of Keilah surrender me and my men into the hand of Saul?” “They will,” said the LORD.'),
  ('BSB', '1 Samuel', 9, 23, 13, 'Then David and his men, about six hundred strong, set out and departed from Keilah, moving from place to place. When Saul was told that David had escaped from Keilah, he declined to go forth.'),
  ('BSB', '1 Samuel', 9, 23, 14, 'And David stayed in the wilderness strongholds and in the hill country of the Wilderness of Ziph. Day after day Saul searched for him, but God would not deliver David into his hand.'),
  ('BSB', '1 Samuel', 9, 23, 15, 'While David was in Horesh in the Wilderness of Ziph, he saw that Saul had come out to take his life.'),
  ('BSB', '1 Samuel', 9, 23, 16, 'And Saul’s son Jonathan came to David in Horesh and strengthened his hand in God,'),
  ('BSB', '1 Samuel', 9, 23, 17, 'saying, “Do not be afraid, for my father Saul will never lay a hand on you. And you will be king over Israel, and I will be your second-in-command. Even my father Saul knows this is true.”'),
  ('BSB', '1 Samuel', 9, 23, 18, 'So the two of them made a covenant before the LORD. And David remained in Horesh, while Jonathan went home.'),
  ('BSB', '1 Samuel', 9, 23, 19, 'Then the Ziphites came up to Saul at Gibeah and said, “Is not David hiding among us in the strongholds at Horesh, on the hill of Hachilah south of Jeshimon?'),
  ('BSB', '1 Samuel', 9, 23, 20, 'Now, O king, come down whenever your soul desires, and we will be responsible for delivering him into your hand.”'),
  ('BSB', '1 Samuel', 9, 23, 21, '“May you be blessed by the LORD,” replied Saul, “for you have had compassion on me.'),
  ('BSB', '1 Samuel', 9, 23, 22, 'Please go and prepare further. Investigate and watch carefully where he goes and who has seen him there, for I am told that he is extremely cunning.'),
  ('BSB', '1 Samuel', 9, 23, 23, 'Observe and find out all the places where he hides. Then come back to me with certainty, and I will go with you. If he is in the land, I will search him out among all the clans of Judah.”'),
  ('BSB', '1 Samuel', 9, 23, 24, 'So they set out and went to Ziph ahead of Saul. Now David and his men were in the Wilderness of Maon in the Arabah south of Jeshimon,'),
  ('BSB', '1 Samuel', 9, 23, 25, 'and Saul and his men went to seek him. When David was told about it, he went down to the rock and stayed in the Wilderness of Maon. And when Saul heard of this, he pursued David there.'),
  ('BSB', '1 Samuel', 9, 23, 26, 'Saul was proceeding along one side of the mountain, and David and his men along the other side. Even though David was hurrying to get away, Saul and his men were closing in on David and his men to capture them.'),
  ('BSB', '1 Samuel', 9, 23, 27, 'Then a messenger came to Saul, saying, “Come quickly, for the Philistines have raided the land!”'),
  ('BSB', '1 Samuel', 9, 23, 28, 'So Saul broke off his pursuit of David and went to meet the Philistines. That is why that place is called Sela-hammahlekoth.'),
  ('BSB', '1 Samuel', 9, 23, 29, 'And David went up from there and lived in the strongholds of En-gedi.'),
  ('BSB', '1 Samuel', 9, 24, 1, 'After Saul had returned from pursuing the Philistines, he was told, “David is in the wilderness of En-gedi.”'),
  ('BSB', '1 Samuel', 9, 24, 2, 'So Saul took three thousand chosen men from all Israel and went to look for David and his men in the region of the Rocks of the Wild Goats.'),
  ('BSB', '1 Samuel', 9, 24, 3, 'Soon Saul came to the sheepfolds along the road, where there was a cave, and he went in to relieve himself. And David and his men were hiding in the recesses of the cave.'),
  ('BSB', '1 Samuel', 9, 24, 4, 'So David’s men said to him, “This is the day about which the LORD said to you, ‘Behold, I will deliver your enemy into your hand, that you may do with him as you wish.’” Then David crept up secretly and cut off a corner of Saul’s robe.'),
  ('BSB', '1 Samuel', 9, 24, 5, 'Afterward, David’s conscience was stricken because he had cut off the corner of Saul’s robe.'),
  ('BSB', '1 Samuel', 9, 24, 6, 'So he said to his men, “The LORD forbid that I should do such a thing to my master, the LORD’s anointed. May I never lift my hand against him, since he is the LORD’s anointed.”'),
  ('BSB', '1 Samuel', 9, 24, 7, 'With these words David restrained his men, and he did not let them rise up against Saul. Then Saul left the cave and went on his way.'),
  ('BSB', '1 Samuel', 9, 24, 8, 'After that, David got up, went out of the cave, and called out to Saul, “My lord the king!” When Saul looked behind him, David bowed facedown in reverence'),
  ('BSB', '1 Samuel', 9, 24, 9, 'and said to Saul, “Why do you listen to the words of men who say, ‘Look, David intends to harm you’?'),
  ('BSB', '1 Samuel', 9, 24, 10, 'Behold, this day you have seen with your own eyes that the LORD delivered you into my hand in the cave. I was told to kill you, but I spared you and said, ‘I will not lift my hand against my lord, since he is the LORD’s anointed.’'),
  ('BSB', '1 Samuel', 9, 24, 11, 'See, my father, look at the corner of your robe in my hand. For I cut it off, but I did not kill you. See and know that there is no evil or rebellion in my hands. I have not sinned against you, even though you are hunting me down to take my life.'),
  ('BSB', '1 Samuel', 9, 24, 12, 'May the LORD judge between you and me, and may the LORD take vengeance on you, but my hand will never be against you.'),
  ('BSB', '1 Samuel', 9, 24, 13, 'As the old proverb says, ‘Wickedness proceeds from the wicked.’ But my hand will never be against you.'),
  ('BSB', '1 Samuel', 9, 24, 14, 'Against whom has the king of Israel come out? Whom are you pursuing? A dead dog? A flea?'),
  ('BSB', '1 Samuel', 9, 24, 15, 'May the LORD be our judge and decide between you and me. May He take notice and plead my case and deliver me from your hand.”'),
  ('BSB', '1 Samuel', 9, 24, 16, 'When David had finished saying these things, Saul called back, “Is that your voice, David my son?” Then Saul wept aloud'),
  ('BSB', '1 Samuel', 9, 24, 17, 'and said to David, “You are more righteous than I, for you have rewarded me with good, though I have rewarded you with evil.'),
  ('BSB', '1 Samuel', 9, 24, 18, 'And you have shown this day how well you have dealt with me; for when the LORD delivered me into your hand, you did not kill me.'),
  ('BSB', '1 Samuel', 9, 24, 19, 'When a man finds his enemy, does he let him go away unharmed? May the LORD reward you with good for what you have done for me this day.'),
  ('BSB', '1 Samuel', 9, 24, 20, 'Now I know for sure that you will be king, and that the kingdom of Israel will be established in your hands.'),
  ('BSB', '1 Samuel', 9, 24, 21, 'So now, swear to me by the LORD that you will not cut off my descendants or wipe out my name from my father’s house.”'),
  ('BSB', '1 Samuel', 9, 24, 22, 'So David gave his oath to Saul. Then Saul returned home, but David and his men went up to the stronghold.'),
  ('BSB', '1 Samuel', 9, 25, 1, 'When Samuel died, all Israel gathered to mourn for him; and they buried him at his home in Ramah. Then David set out and went down to the Wilderness of Paran.'),
  ('BSB', '1 Samuel', 9, 25, 2, 'Now there was a man in Maon whose business was in Carmel. He was a very wealthy man with a thousand goats and three thousand sheep, which he was shearing in Carmel.'),
  ('BSB', '1 Samuel', 9, 25, 3, 'His name was Nabal, and his wife’s name was Abigail. She was an intelligent and beautiful woman, but her husband, a Calebite, was harsh and evil in his dealings.'),
  ('BSB', '1 Samuel', 9, 25, 4, 'While David was in the wilderness, he heard that Nabal was shearing sheep.'),
  ('BSB', '1 Samuel', 9, 25, 5, 'So David sent ten young men and instructed them, “Go up to Nabal at Carmel. Greet him in my name'),
  ('BSB', '1 Samuel', 9, 25, 6, 'and say to him, ‘Long life to you, and peace to you and your house and to all that belongs to you.'),
  ('BSB', '1 Samuel', 9, 25, 7, 'Now I hear that it is time for shearing. When your shepherds were with us, we did not harass them, and nothing of theirs was missing the whole time they were in Carmel.'),
  ('BSB', '1 Samuel', 9, 25, 8, 'Ask your young men, and they will tell you. So let my young men find favor with you, for we have come on the day of a feast. Please give whatever you can afford to your servants and to your son David.’”'),
  ('BSB', '1 Samuel', 9, 25, 9, 'When David’s young men arrived, they relayed all these words to Nabal on behalf of David. Then they waited.'),
  ('BSB', '1 Samuel', 9, 25, 10, 'But Nabal asked them, “Who is David? Who is this son of Jesse? Many servants these days are breaking away from their masters.'),
  ('BSB', '1 Samuel', 9, 25, 11, 'Why should I take my bread and water and the meat I have slaughtered for my shearers, and give them to these men whose origin I do not know?”'),
  ('BSB', '1 Samuel', 9, 25, 12, 'So David’s men turned around and went back, and they relayed to him all these words.'),
  ('BSB', '1 Samuel', 9, 25, 13, 'And David said to his men, “Strap on your swords!” So David and all his men put on their swords, and about four hundred men followed David, while two hundred stayed with the supplies.'),
  ('BSB', '1 Samuel', 9, 25, 14, 'Meanwhile, one of Nabal’s young men informed Nabal’s wife Abigail, “Look, David sent messengers from the wilderness to greet our master, but he scolded them.'),
  ('BSB', '1 Samuel', 9, 25, 15, 'Yet these men were very good to us. When we were in the field, we were not harassed, and nothing of ours went missing the whole time we lived among them.'),
  ('BSB', '1 Samuel', 9, 25, 16, 'They were a wall around us, both day and night, the whole time we were herding our sheep near them.'),
  ('BSB', '1 Samuel', 9, 25, 17, 'Now consider carefully what you must do, because disaster looms over our master and all his household. For he is such a scoundrel that nobody can speak to him!”'),
  ('BSB', '1 Samuel', 9, 25, 18, 'Then Abigail hurried and took two hundred loaves of bread, two skins of wine, five butchered sheep, five seahs of roasted grain, a hundred clusters of raisins, and two hundred cakes of figs. She loaded them on donkeys'),
  ('BSB', '1 Samuel', 9, 25, 19, 'and said to her young men, “Go ahead of me. I will be right behind you.” But she did not tell her husband Nabal.'),
  ('BSB', '1 Samuel', 9, 25, 20, 'As Abigail came riding her donkey into a mountain ravine, she saw David and his men coming down toward her, and she met them.'),
  ('BSB', '1 Samuel', 9, 25, 21, 'Now David had just finished saying, “In vain I have protected all that belonged to this man in the wilderness. Nothing that belongs to him has gone missing, yet he has paid me back evil for good.'),
  ('BSB', '1 Samuel', 9, 25, 22, 'May God punish David, and ever so severely, if I let one of Nabal’s men survive until morning.”'),
  ('BSB', '1 Samuel', 9, 25, 23, 'When Abigail saw David, she quickly got off the donkey, fell facedown, and bowed before him.'),
  ('BSB', '1 Samuel', 9, 25, 24, 'She fell at his feet and said, “My lord, may the blame be on me alone, but please let your servant speak to you; hear the words of your servant.'),
  ('BSB', '1 Samuel', 9, 25, 25, 'My lord should pay no attention to this scoundrel Nabal, for he lives up to his name: His name means Fool, and folly accompanies him. I, your servant, did not see my lord’s young men whom you sent.'),
  ('BSB', '1 Samuel', 9, 25, 26, 'Now, my lord, as surely as the LORD lives and you yourself live, the LORD has held you back from coming to bloodshed and avenging yourself with your own hand. May your enemies and those who seek harm for my lord be like Nabal.'),
  ('BSB', '1 Samuel', 9, 25, 27, 'Now let this gift your servant has brought to my lord be given to the young men who follow you.'),
  ('BSB', '1 Samuel', 9, 25, 28, 'Please forgive your servant’s offense, for the LORD will surely make a lasting dynasty for my lord, because he fights the LORD’s battles. May no evil be found in you as long as you live.'),
  ('BSB', '1 Samuel', 9, 25, 29, 'And should someone pursue you and seek your life, then the life of my lord will be bound securely by the LORD your God in the bundle of the living. But He shall fling away the lives of your enemies like stones from a sling.'),
  ('BSB', '1 Samuel', 9, 25, 30, 'When the LORD has done for my lord all the good He promised, and when He has appointed you ruler over Israel,'),
  ('BSB', '1 Samuel', 9, 25, 31, 'then my lord will have no remorse or guilt of conscience over needless bloodshed and revenge. And when the LORD has dealt well with my lord, may you remember your maidservant.”'),
  ('BSB', '1 Samuel', 9, 25, 32, 'Then David said to Abigail, “Blessed be the LORD, the God of Israel, who sent you to meet me this day!'),
  ('BSB', '1 Samuel', 9, 25, 33, 'Blessed is your discernment, and blessed are you, because today you kept me from bloodshed and from avenging myself by my own hand.'),
  ('BSB', '1 Samuel', 9, 25, 34, 'Otherwise, as surely as the LORD, the God of Israel, lives, who has restrained me from harming you, if you had not come quickly to meet me, then surely no male belonging to Nabal would have been left alive by morning light.”'),
  ('BSB', '1 Samuel', 9, 25, 35, 'Then David accepted from her hand what she had brought him, and he said to her, “Go home in peace. See, I have heeded your voice and granted your request.”'),
  ('BSB', '1 Samuel', 9, 25, 36, 'When Abigail returned to Nabal, there he was in the house, holding a feast fit for a king, in high spirits and very drunk. So she told him nothing until morning light.'),
  ('BSB', '1 Samuel', 9, 25, 37, 'In the morning when Nabal was sober, his wife told him about these events, and his heart failed within him and he became like a stone.'),
  ('BSB', '1 Samuel', 9, 25, 38, 'About ten days later, the LORD struck Nabal dead.'),
  ('BSB', '1 Samuel', 9, 25, 39, 'On hearing that Nabal was dead, David said, “Blessed be the LORD, who has upheld my cause against the reproach of Nabal and has restrained His servant from evil. For the LORD has brought the wickedness of Nabal down upon his own head.” Then David sent word to Abigail, asking for her in marriage.'),
  ('BSB', '1 Samuel', 9, 25, 40, 'When his servants came to Abigail at Carmel, they said, “David has sent us to take you as his wife.”'),
  ('BSB', '1 Samuel', 9, 25, 41, 'She arose, then bowed facedown and said, “Here is your maidservant, ready to serve and to wash the feet of my lord’s servants.”'),
  ('BSB', '1 Samuel', 9, 25, 42, 'So Abigail hurried and got on a donkey, and attended by five of her maidens, she followed David’s messengers and became his wife.'),
  ('BSB', '1 Samuel', 9, 25, 43, 'David had also married Ahinoam of Jezreel. So she and Abigail were both his wives.'),
  ('BSB', '1 Samuel', 9, 25, 44, 'But Saul had given his daughter Michal, David’s wife, to Palti son of Laish, who was from Gallim.'),
  ('BSB', '1 Samuel', 9, 26, 1, 'Then the Ziphites came to Saul at Gibeah and said, “Is not David hiding on the hill of Hachilah, opposite Jeshimon?”'),
  ('BSB', '1 Samuel', 9, 26, 2, 'So Saul, accompanied by three thousand chosen men of Israel, went down to the Wilderness of Ziph to search for David there.'),
  ('BSB', '1 Samuel', 9, 26, 3, 'Saul camped beside the road at the hill of Hachilah opposite Jeshimon, but David was living in the wilderness. When he realized that Saul had followed him there,'),
  ('BSB', '1 Samuel', 9, 26, 4, 'David sent out spies to verify that Saul had arrived.'),
  ('BSB', '1 Samuel', 9, 26, 5, 'Then David set out and went to the place where Saul had camped. He saw the place where Saul and Abner son of Ner, the general of his army, had lain down. Saul was lying inside the inner circle of the camp, with the troops camped around him.'),
  ('BSB', '1 Samuel', 9, 26, 6, 'And David asked Ahimelech the Hittite and Abishai son of Zeruiah, Joab’s brother, “Who will go down with me to Saul in the camp?” “I will go with you,” answered Abishai.'),
  ('BSB', '1 Samuel', 9, 26, 7, 'That night David and Abishai came to the troops, and Saul was lying there asleep in the inner circle of the camp, with his spear stuck in the ground by his head. And Abner and the troops were lying around him.'),
  ('BSB', '1 Samuel', 9, 26, 8, 'Abishai said to David, “Today God has delivered your enemy into your hand. Now, therefore, please let me thrust the spear through him into the ground with one stroke. I will not need to strike him twice!”'),
  ('BSB', '1 Samuel', 9, 26, 9, 'But David said to Abishai, “Do not destroy him, for who can lift a hand against the LORD’s anointed and be guiltless?”'),
  ('BSB', '1 Samuel', 9, 26, 10, 'David added, “As surely as the LORD lives, the LORD Himself will strike him down; either his day will come and he will die, or he will go into battle and perish.'),
  ('BSB', '1 Samuel', 9, 26, 11, 'But the LORD forbid that I should stretch out my hand against the LORD’s anointed. Instead, take the spear and water jug by his head, and let us go.”'),
  ('BSB', '1 Samuel', 9, 26, 12, 'So David took the spear and water jug by Saul’s head, and they departed. No one saw them or knew about it, nor did anyone wake up; they all remained asleep, because a deep sleep from the LORD had fallen on them.'),
  ('BSB', '1 Samuel', 9, 26, 13, 'Then David crossed to the other side and stood atop the mountain at a distance; there was a wide gulf between them.'),
  ('BSB', '1 Samuel', 9, 26, 14, 'And David shouted to the troops and to Abner son of Ner, “Will you not answer me, Abner?” “Who calls to the king?” Abner replied.'),
  ('BSB', '1 Samuel', 9, 26, 15, 'So David said to Abner, “You are a man, aren’t you? And who in Israel is your equal? Why then did you not protect your lord the king when one of the people came to destroy him?'),
  ('BSB', '1 Samuel', 9, 26, 16, 'This thing you have done is not good. As surely as the LORD lives, all of you deserve to die, since you did not protect your lord, the LORD’s anointed. Now look around. Where are the king’s spear and water jug that were by his head?”'),
  ('BSB', '1 Samuel', 9, 26, 17, 'Then Saul recognized David’s voice and asked, “Is that your voice, David my son?” “It is my voice, my lord and king,” David said.'),
  ('BSB', '1 Samuel', 9, 26, 18, 'And he continued, “Why is my lord pursuing his servant? What have I done? What evil is in my hand?'),
  ('BSB', '1 Samuel', 9, 26, 19, 'Now please, may my lord the king hear the words of his servant: If the LORD has stirred you up against me, then may He accept an offering. But if men have done it, may they be cursed in the presence of the LORD! For today they have driven me away from sharing in the inheritance of the LORD, saying, ‘Go, serve other gods.’'),
  ('BSB', '1 Samuel', 9, 26, 20, 'So do not let my blood fall to the ground far from the presence of the LORD. For the king of Israel has come out to look for a flea, like one who hunts a partridge in the mountains.”'),
  ('BSB', '1 Samuel', 9, 26, 21, 'Then Saul replied, “I have sinned. Come back, David my son. I will never harm you again, because today you considered my life precious. I have played the fool and have committed a grave error!”'),
  ('BSB', '1 Samuel', 9, 26, 22, '“Here is the king’s spear,” David answered. “Let one of the young men come over and get it.'),
  ('BSB', '1 Samuel', 9, 26, 23, 'May the LORD repay every man for his righteousness and faithfulness. For the LORD delivered you into my hand today, but I would not stretch out my hand against the LORD’s anointed.'),
  ('BSB', '1 Samuel', 9, 26, 24, 'As surely as I valued your life today, so may the LORD value my life and rescue me from all trouble.”'),
  ('BSB', '1 Samuel', 9, 26, 25, 'Saul said to him, “May you be blessed, David my son. You will accomplish great things and will surely prevail.” So David went on his way, and Saul returned home.'),
  ('BSB', '1 Samuel', 9, 27, 1, 'David, however, said to himself, “One of these days now I will be swept away by the hand of Saul. There is nothing better for me than to escape to the land of the Philistines. Then Saul will stop searching for me all over Israel, and I will slip out of his hand.”'),
  ('BSB', '1 Samuel', 9, 27, 2, 'So David set out with his six hundred men and went to Achish son of Maoch, the king of Gath.'),
  ('BSB', '1 Samuel', 9, 27, 3, 'David and his men settled in Gath with Achish. Each man had his family with him, and David had his two wives: Ahinoam of Jezreel and Abigail of Carmel, the widow of Nabal.'),
  ('BSB', '1 Samuel', 9, 27, 4, 'And when Saul learned that David had fled to Gath, he no longer searched for him.'),
  ('BSB', '1 Samuel', 9, 27, 5, 'Then David said to Achish, “If I have found favor in your eyes, let me be assigned a place in one of the outlying towns, so I can live there. For why should your servant live in the royal city with you?”'),
  ('BSB', '1 Samuel', 9, 27, 6, 'That day Achish gave him Ziklag, and to this day it still belongs to the kings of Judah.'),
  ('BSB', '1 Samuel', 9, 27, 7, 'And the time that David lived in Philistine territory amounted to a year and four months.'),
  ('BSB', '1 Samuel', 9, 27, 8, 'Now David and his men went up and raided the Geshurites, the Girzites, and the Amalekites. (From ancient times these people had inhabited the land extending to Shur and Egypt.)'),
  ('BSB', '1 Samuel', 9, 27, 9, 'Whenever David attacked a territory, he did not leave a man or woman alive, but he took the flocks and herds, the donkeys, camels, and clothing. Then he would return to Achish,'),
  ('BSB', '1 Samuel', 9, 27, 10, 'who would ask him, “What have you raided today?” And David would reply, “The Negev of Judah,” or “The Negev of Jerahmeel,” or “The Negev of the Kenites.”'),
  ('BSB', '1 Samuel', 9, 27, 11, 'David did not leave a man or woman alive to be brought to Gath, for he said, “Otherwise they will report us, saying, ‘This is what David did.’” And this was David’s custom the whole time he lived in Philistine territory.'),
  ('BSB', '1 Samuel', 9, 27, 12, 'So Achish trusted David, thinking, “Since he has made himself an utter stench to his people Israel, he will be my servant forever.”'),
  ('BSB', '1 Samuel', 9, 28, 1, 'Now in those days the Philistines gathered their forces for warfare against Israel. So Achish said to David, “You must understand that you and your men are to go out to battle with me.”'),
  ('BSB', '1 Samuel', 9, 28, 2, 'David replied, “Then you will come to know what your servant can do.” “Very well,” said Achish. “I will make you my bodyguard for life.”'),
  ('BSB', '1 Samuel', 9, 28, 3, 'Now by this time Samuel had died, and all Israel had mourned for him and buried him in Ramah, his own city. And Saul had removed the mediums and spiritists from the land.'),
  ('BSB', '1 Samuel', 9, 28, 4, 'The Philistines came together and camped at Shunem, while Saul gathered all Israel and camped at Gilboa.'),
  ('BSB', '1 Samuel', 9, 28, 5, 'When Saul saw the Philistine army, he was afraid and trembled violently.'),
  ('BSB', '1 Samuel', 9, 28, 6, 'He inquired of the LORD, but the LORD did not answer him by dreams or Urim or prophets.'),
  ('BSB', '1 Samuel', 9, 28, 7, 'Then Saul said to his servants, “Find me a woman who is a medium, so I can go and consult her.” “There is a medium at Endor,” his servants replied.'),
  ('BSB', '1 Samuel', 9, 28, 8, 'So Saul disguised himself by putting on different clothes, and he set out with two of his men. They came to the woman at night, and Saul said, “Consult a spirit for me. Bring up for me the one I name.”'),
  ('BSB', '1 Samuel', 9, 28, 9, 'But the woman replied, “Surely you know what Saul has done, how he has killed the mediums and spiritists in the land. Why have you set a trap to get me killed?”'),
  ('BSB', '1 Samuel', 9, 28, 10, 'Then Saul swore to her by the LORD: “As surely as the LORD lives, no punishment shall come upon you for this.”'),
  ('BSB', '1 Samuel', 9, 28, 11, '“Whom shall I bring up for you?” the woman asked. “Bring up Samuel,” he replied.'),
  ('BSB', '1 Samuel', 9, 28, 12, 'But when the woman saw Samuel, she cried out in a loud voice and said to Saul, “Why have you deceived me? You are Saul!”'),
  ('BSB', '1 Samuel', 9, 28, 13, '“Do not be afraid,” the king replied. “What do you see?” “I see a god coming up out of the earth,” the woman answered.'),
  ('BSB', '1 Samuel', 9, 28, 14, '“What does he look like?” asked Saul. “An old man is coming up,” she replied. “And he is wearing a robe.” So Saul knew that it was Samuel, and he bowed facedown in reverence.'),
  ('BSB', '1 Samuel', 9, 28, 15, 'Then Samuel said to Saul, “Why have you disturbed me by bringing me up?” “I am deeply distressed,” replied Saul. “The Philistines are fighting against me, and God has turned away from me. He no longer answers me, either by prophets or by dreams. So I have called on you to tell me what to do.”'),
  ('BSB', '1 Samuel', 9, 28, 16, '“Why do you consult me,” asked Samuel, “since the LORD has turned away from you and become your enemy?'),
  ('BSB', '1 Samuel', 9, 28, 17, 'He has done exactly what He spoke through me: The LORD has torn the kingship out of your hand and given it to your neighbor David.'),
  ('BSB', '1 Samuel', 9, 28, 18, 'Because you did not obey the LORD or carry out His burning anger against Amalek, the LORD has done this to you today.'),
  ('BSB', '1 Samuel', 9, 28, 19, 'Moreover, the LORD will deliver Israel with you into the hand of the Philistines, and tomorrow you and your sons will be with me. And the LORD will deliver the army of Israel into the hand of the Philistines.”'),
  ('BSB', '1 Samuel', 9, 28, 20, 'Immediately Saul fell flat on the ground, terrified by the words of Samuel. And his strength was gone, because he had not eaten anything all that day and night.'),
  ('BSB', '1 Samuel', 9, 28, 21, 'When the woman came to Saul and saw how distraught he was, she said to him, “Look, your maidservant has obeyed your voice. I took my life in my hands and did as you told me.'),
  ('BSB', '1 Samuel', 9, 28, 22, 'Now please listen to your servant and let me set a morsel of bread before you so you may eat and have the strength to go on your way.”'),
  ('BSB', '1 Samuel', 9, 28, 23, 'Saul refused, saying, “I will not eat.” But his servants joined the woman in urging him, and he heeded their voice. He got up from the ground and sat on the bed.'),
  ('BSB', '1 Samuel', 9, 28, 24, 'The woman had a fattened calf at her house, and she quickly slaughtered it. She also took flour, kneaded it, and baked unleavened bread.'),
  ('BSB', '1 Samuel', 9, 28, 25, 'She served it to Saul and his servants, and they ate. And that night they got up and left.'),
  ('BSB', '1 Samuel', 9, 29, 1, 'Now the Philistines brought all their forces together at Aphek, while Israel camped by the spring in Jezreel.'),
  ('BSB', '1 Samuel', 9, 29, 2, 'As the Philistine leaders marched out their units of hundreds and thousands, David and his men marched behind them with Achish.'),
  ('BSB', '1 Samuel', 9, 29, 3, 'Then the commanders of the Philistines asked, “What about these Hebrews?” Achish replied, “Is this not David, the servant of King Saul of Israel? He has been with me all these days, even years, and from the day he defected until today I have found no fault in him.”'),
  ('BSB', '1 Samuel', 9, 29, 4, 'But the commanders of the Philistines were angry with Achish and told him, “Send that man back and let him return to the place you assigned him. He must not go down with us into battle only to become our adversary during the war. What better way for him to regain the favor of his master than with the heads of our men?'),
  ('BSB', '1 Samuel', 9, 29, 5, 'Is this not the David about whom they sing in their dances: ‘Saul has slain his thousands, and David his tens of thousands’?”'),
  ('BSB', '1 Samuel', 9, 29, 6, 'So Achish summoned David and told him, “As surely as the LORD lives, you have been upright in my sight, and it seems right that you should march in and out with me in the army, because I have found no fault in you from the day you came to me until this day. But you have no favor in the sight of the leaders.'),
  ('BSB', '1 Samuel', 9, 29, 7, 'Therefore turn back now and go in peace, so that you will not do anything to displease the leaders of the Philistines.”'),
  ('BSB', '1 Samuel', 9, 29, 8, '“But what have I done?” David replied. “What have you found against your servant, from the day I came to you until today, to keep me from going along to fight against the enemies of my lord the king?”'),
  ('BSB', '1 Samuel', 9, 29, 9, 'Achish replied, “I know that you are as pleasing in my sight as an angel of God. But the commanders of the Philistines have said, ‘He must not go into battle with us.’'),
  ('BSB', '1 Samuel', 9, 29, 10, 'Now then, get up early in the morning, along with your master’s servants who came with you, and go as soon as it is light.”'),
  ('BSB', '1 Samuel', 9, 29, 11, 'So David and his men got up early in the morning to return to the land of the Philistines. And the Philistines went up to Jezreel.'),
  ('BSB', '1 Samuel', 9, 30, 1, 'On the third day David and his men arrived in Ziklag, and the Amalekites had raided the Negev, attacked Ziklag, and burned it down.'),
  ('BSB', '1 Samuel', 9, 30, 2, 'They had taken captive the women and all who were there, both young and old. They had not killed anyone, but had carried them off as they went on their way.'),
  ('BSB', '1 Samuel', 9, 30, 3, 'When David and his men came to the city, they found it burned down and their wives and sons and daughters taken captive.'),
  ('BSB', '1 Samuel', 9, 30, 4, 'So David and the troops with him lifted up their voices and wept until they had no strength left to weep.'),
  ('BSB', '1 Samuel', 9, 30, 5, 'David’s two wives, Ahinoam of Jezreel and Abigail the widow of Nabal of Carmel, had been taken captive.'),
  ('BSB', '1 Samuel', 9, 30, 6, 'And David was greatly distressed because the people spoke of stoning him, because the soul of every man grieved for his sons and daughters. But David found strength in the LORD his God.'),
  ('BSB', '1 Samuel', 9, 30, 7, 'Then David said to Abiathar the priest, the son of Ahimelech, “Bring me the ephod.” So Abiathar brought it to him,'),
  ('BSB', '1 Samuel', 9, 30, 8, 'and David inquired of the LORD: “Should I pursue these raiders? Will I overtake them?” “Pursue them,” the LORD replied, “for you will surely overtake them and rescue the captives.”'),
  ('BSB', '1 Samuel', 9, 30, 9, 'So David and his six hundred men went to the Brook of Besor, where some stayed behind'),
  ('BSB', '1 Samuel', 9, 30, 10, 'because two hundred men were too exhausted to cross the brook. But David and four hundred men continued in pursuit.'),
  ('BSB', '1 Samuel', 9, 30, 11, 'Now his men found an Egyptian in the field and brought him to David. They gave the man water to drink and food to eat—'),
  ('BSB', '1 Samuel', 9, 30, 12, 'a piece of a fig cake and two clusters of raisins. So he ate and was revived, for he had not had any food or water for three days and three nights.'),
  ('BSB', '1 Samuel', 9, 30, 13, 'Then David asked him, “To whom do you belong, and where are you from?” “I am an Egyptian,” he replied, “the slave of an Amalekite. My master abandoned me three days ago when I fell ill.'),
  ('BSB', '1 Samuel', 9, 30, 14, 'We raided the Negev of the Cherethites, the territory of Judah, and the Negev of Caleb, and we burned down Ziklag.”'),
  ('BSB', '1 Samuel', 9, 30, 15, '“Will you lead me to these raiders?” David asked. And the man replied, “Swear to me by God that you will not kill me or deliver me into the hand of my master, and I will lead you to them.”'),
  ('BSB', '1 Samuel', 9, 30, 16, 'So he led David down, and there were the Amalekites spread out over all the land, eating, drinking, and celebrating the great amount of plunder they had taken from the land of the Philistines and the land of Judah.'),
  ('BSB', '1 Samuel', 9, 30, 17, 'And David struck them down from twilight until the evening of the next day. Not a man escaped, except four hundred young men who fled, riding off on camels.'),
  ('BSB', '1 Samuel', 9, 30, 18, 'So David recovered everything the Amalekites had taken, including his two wives.'),
  ('BSB', '1 Samuel', 9, 30, 19, 'Nothing was missing, young or old, son or daughter, or any of the plunder the Amalekites had taken. David brought everything back.'),
  ('BSB', '1 Samuel', 9, 30, 20, 'And he recovered all the flocks and herds, which his men drove ahead of the other livestock, calling out, “This is David’s plunder!”'),
  ('BSB', '1 Samuel', 9, 30, 21, 'When David came to the two hundred men who had been too exhausted to follow him from the Brook of Besor, they came out to meet him and the troops with him. As David approached the men, he greeted them,');
insert into control_room_bible (version, book, book_num, chapter, verse, text) values
  ('BSB', '1 Samuel', 9, 30, 22, 'but all the wicked and worthless men among those who had gone with David said, “Because they did not go with us, we will not share with them the plunder we recovered, except for each man’s wife and children. They may take them and go.”'),
  ('BSB', '1 Samuel', 9, 30, 23, 'But David said, “My brothers, you must not do this with what the LORD has given us. He has protected us and delivered into our hands the raiders who came against us.'),
  ('BSB', '1 Samuel', 9, 30, 24, 'Who will listen to your proposal? The share of the one who went to battle will match the share of the one who stayed with the supplies. They will share alike.”'),
  ('BSB', '1 Samuel', 9, 30, 25, 'And so it has been from that day forward. David established this statute as an ordinance for Israel to this very day.'),
  ('BSB', '1 Samuel', 9, 30, 26, 'When David arrived in Ziklag, he sent some of the plunder to his friends, the elders of Judah, saying, “Here is a gift for you from the plunder of the LORD’s enemies.”'),
  ('BSB', '1 Samuel', 9, 30, 27, 'He sent gifts to those in Bethel, Ramoth Negev, and Jattir;'),
  ('BSB', '1 Samuel', 9, 30, 28, 'to those in Aroer, Siphmoth, and Eshtemoa;'),
  ('BSB', '1 Samuel', 9, 30, 29, 'to those in Racal and in the cities of the Jerahmeelites and Kenites;'),
  ('BSB', '1 Samuel', 9, 30, 30, 'to those in Hormah, Bor-ashan, and Athach;'),
  ('BSB', '1 Samuel', 9, 30, 31, 'and to those in Hebron and in all the places where David and his men had roamed.'),
  ('BSB', '1 Samuel', 9, 31, 1, 'Now the Philistines fought against Israel, and the men of Israel fled before them, and many fell slain on Mount Gilboa.'),
  ('BSB', '1 Samuel', 9, 31, 2, 'The Philistines followed hard after Saul and his sons, and they killed Saul’s sons Jonathan, Abinadab, and Malchishua.'),
  ('BSB', '1 Samuel', 9, 31, 3, 'When the battle intensified against Saul, the archers overtook him and wounded him critically.'),
  ('BSB', '1 Samuel', 9, 31, 4, 'Then Saul said to his armor-bearer, “Draw your sword and run it through me, or these uncircumcised men will come and run me through and torture me!” But his armor-bearer was terrified and refused to do it. So Saul took his own sword and fell on it.'),
  ('BSB', '1 Samuel', 9, 31, 5, 'When his armor-bearer saw that Saul was dead, he too fell on his own sword and died with him.'),
  ('BSB', '1 Samuel', 9, 31, 6, 'So Saul, his three sons, his armor-bearer, and all his men died together that same day.'),
  ('BSB', '1 Samuel', 9, 31, 7, 'When the Israelites along the valley and those on the other side of the Jordan saw that the army of Israel had fled and that Saul and his sons had died, they abandoned their cities and ran away. So the Philistines came and occupied their cities.'),
  ('BSB', '1 Samuel', 9, 31, 8, 'The next day, when the Philistines came to strip the dead, they found Saul and his three sons fallen on Mount Gilboa.'),
  ('BSB', '1 Samuel', 9, 31, 9, 'They cut off Saul’s head, stripped off his armor, and sent messengers throughout the land of the Philistines to proclaim the news in the temples of their idols and among their people.'),
  ('BSB', '1 Samuel', 9, 31, 10, 'They put his armor in the temple of the Ashtoreths and hung his body on the wall of Beth-shan.'),
  ('BSB', '1 Samuel', 9, 31, 11, 'When the people of Jabesh-gilead heard what the Philistines had done to Saul,'),
  ('BSB', '1 Samuel', 9, 31, 12, 'all their men of valor set out, journeyed all night, and retrieved the bodies of Saul and his sons from the wall of Beth-shan. When they arrived at Jabesh, they burned the bodies there.'),
  ('BSB', '1 Samuel', 9, 31, 13, 'Then they took their bones and buried them under the tamarisk tree in Jabesh, and they fasted seven days.'),
  ('BSB', '2 Samuel', 10, 1, 1, 'After the death of Saul, David returned from the slaughter of the Amalekites and stayed in Ziklag two days.'),
  ('BSB', '2 Samuel', 10, 1, 2, 'On the third day a man with torn clothes and dust on his head arrived from Saul’s camp. When he came to David, he fell to the ground to pay him homage.'),
  ('BSB', '2 Samuel', 10, 1, 3, '“Where have you come from?” David asked. “I have escaped from the Israelite camp,” he replied.'),
  ('BSB', '2 Samuel', 10, 1, 4, '“What was the outcome?” David asked. “Please tell me.” “The troops fled from the battle,” he replied. “Many of them fell and died. And Saul and his son Jonathan are also dead.”'),
  ('BSB', '2 Samuel', 10, 1, 5, 'Then David asked the young man who had brought him the report, “How do you know that Saul and his son Jonathan are dead?”'),
  ('BSB', '2 Samuel', 10, 1, 6, '“I happened to be on Mount Gilboa,” he replied, “and there was Saul, leaning on his spear, with the chariots and the cavalry closing in on him.'),
  ('BSB', '2 Samuel', 10, 1, 7, 'When he turned around and saw me, he called out and I answered, ‘Here I am!’'),
  ('BSB', '2 Samuel', 10, 1, 8, '‘Who are you?’ he asked. So I told him, ‘I am an Amalekite.’'),
  ('BSB', '2 Samuel', 10, 1, 9, 'Then he begged me, ‘Stand over me and kill me, for agony has seized me, but my life still lingers.’'),
  ('BSB', '2 Samuel', 10, 1, 10, 'So I stood over him and killed him, because I knew that after he had fallen he could not survive. And I took the crown that was on his head and the band that was on his arm, and I have brought them here to my lord.”'),
  ('BSB', '2 Samuel', 10, 1, 11, 'Then David took hold of his own clothes and tore them, and all the men who were with him did the same.'),
  ('BSB', '2 Samuel', 10, 1, 12, 'They mourned and wept and fasted until evening for Saul and his son Jonathan, and for the people of the LORD and the house of Israel, because they had fallen by the sword.'),
  ('BSB', '2 Samuel', 10, 1, 13, 'And David inquired of the young man who had brought him the report, “Where are you from?” “I am the son of a foreigner,” he answered. “I am an Amalekite.”'),
  ('BSB', '2 Samuel', 10, 1, 14, 'So David asked him, “Why were you not afraid to lift your hand to destroy the LORD’s anointed?”'),
  ('BSB', '2 Samuel', 10, 1, 15, 'Then David summoned one of the young men and said, “Go, execute him!” So the young man struck him down, and he died.'),
  ('BSB', '2 Samuel', 10, 1, 16, 'For David had said to the Amalekite, “Your blood be on your own head because your own mouth has testified against you, saying, ‘I killed the LORD’s anointed.’”'),
  ('BSB', '2 Samuel', 10, 1, 17, 'Then David took up this lament for Saul and his son Jonathan,'),
  ('BSB', '2 Samuel', 10, 1, 18, 'and he ordered that the sons of Judah be taught the Song of the Bow. It is written in the Book of Jashar:'),
  ('BSB', '2 Samuel', 10, 1, 19, '“Your glory, O Israel, lies slain on your heights. How the mighty have fallen!'),
  ('BSB', '2 Samuel', 10, 1, 20, 'Tell it not in Gath; proclaim it not in the streets of Ashkelon, lest the daughters of the Philistines rejoice, and the daughters of the uncircumcised exult.'),
  ('BSB', '2 Samuel', 10, 1, 21, 'O mountains of Gilboa, may you have no dew or rain, no fields yielding offerings of grain. For there the shield of the mighty was defiled, the shield of Saul, no longer anointed with oil.'),
  ('BSB', '2 Samuel', 10, 1, 22, 'From the blood of the slain, from the fat of the mighty, the bow of Jonathan did not retreat, and the sword of Saul did not return empty.'),
  ('BSB', '2 Samuel', 10, 1, 23, 'Saul and Jonathan, beloved and delightful in life, were not divided in death. They were swifter than eagles, they were stronger than lions.'),
  ('BSB', '2 Samuel', 10, 1, 24, 'O daughters of Israel, weep for Saul, who clothed you in scarlet and luxury, who decked your garments with ornaments of gold.'),
  ('BSB', '2 Samuel', 10, 1, 25, 'How the mighty have fallen in the thick of battle! Jonathan lies slain on your heights.'),
  ('BSB', '2 Samuel', 10, 1, 26, 'I grieve for you, Jonathan, my brother. You were delightful to me; your love to me was extraordinary, surpassing the love of women.'),
  ('BSB', '2 Samuel', 10, 1, 27, 'How the mighty have fallen and the weapons of war have perished!”'),
  ('BSB', '2 Samuel', 10, 2, 1, 'Some time later, David inquired of the LORD, “Should I go up to one of the towns of Judah?” “Go up,” the LORD answered. Then David asked, “Where should I go?” “To Hebron,” replied the LORD.'),
  ('BSB', '2 Samuel', 10, 2, 2, 'So David went there with his two wives, Ahinoam of Jezreel and Abigail the widow of Nabal of Carmel.'),
  ('BSB', '2 Samuel', 10, 2, 3, 'David also took the men who were with him, each with his household, and they settled in the towns near Hebron.'),
  ('BSB', '2 Samuel', 10, 2, 4, 'Then the men of Judah came to Hebron, and there they anointed David king over the house of Judah. And they told David, “It was the men of Jabesh-gilead who buried Saul.”'),
  ('BSB', '2 Samuel', 10, 2, 5, 'So David sent messengers to the men of Jabesh-gilead to tell them, “The LORD bless you, because you showed this kindness to Saul your lord when you buried him.'),
  ('BSB', '2 Samuel', 10, 2, 6, 'Now may the LORD show you loving devotion and faithfulness, and I will also show you the same favor because you have done this.'),
  ('BSB', '2 Samuel', 10, 2, 7, 'Now then, be strong and courageous, for though Saul your lord is dead, the house of Judah has anointed me as their king.”'),
  ('BSB', '2 Samuel', 10, 2, 8, 'Meanwhile, Abner son of Ner, the commander of Saul’s army, took Saul’s son Ish-bosheth, moved him to Mahanaim,'),
  ('BSB', '2 Samuel', 10, 2, 9, 'and made him king over Gilead, Asher, Jezreel, Ephraim, and Benjamin—over all Israel.'),
  ('BSB', '2 Samuel', 10, 2, 10, 'Saul’s son Ish-bosheth was forty years old when he began to reign over Israel, and he reigned for two years. The house of Judah, however, followed David.'),
  ('BSB', '2 Samuel', 10, 2, 11, 'And the length of time that David was king in Hebron over the house of Judah was seven years and six months.'),
  ('BSB', '2 Samuel', 10, 2, 12, 'One day Abner son of Ner and the servants of Ish-bosheth son of Saul marched out from Mahanaim to Gibeon.'),
  ('BSB', '2 Samuel', 10, 2, 13, 'So Joab son of Zeruiah, along with the servants of David, marched out and met them by the pool of Gibeon. And the two camps took up positions on opposite sides of the pool.'),
  ('BSB', '2 Samuel', 10, 2, 14, 'Then Abner said to Joab, “Let us have the young men get up and compete before us.” “Let them get up,” Joab replied.'),
  ('BSB', '2 Samuel', 10, 2, 15, 'So they got up and were counted off—twelve for Benjamin and Ish-bosheth son of Saul, and twelve for David.'),
  ('BSB', '2 Samuel', 10, 2, 16, 'Then each man grabbed his opponent by the head and thrust his sword into his opponent’s side, and they all fell together. So this place, which is in Gibeon, is called Helkath-hazzurim.'),
  ('BSB', '2 Samuel', 10, 2, 17, 'The battle that day was intense, and Abner and the men of Israel were defeated by the servants of David.'),
  ('BSB', '2 Samuel', 10, 2, 18, 'The three sons of Zeruiah were there: Joab, Abishai, and Asahel. Now Asahel was fleet of foot like a wild gazelle,'),
  ('BSB', '2 Samuel', 10, 2, 19, 'and he chased Abner, not turning to the right or to the left in his pursuit.'),
  ('BSB', '2 Samuel', 10, 2, 20, 'And Abner glanced back and said, “Is that you, Asahel?” “It is,” Asahel replied.'),
  ('BSB', '2 Samuel', 10, 2, 21, 'So Abner told him, “Turn to your right or to your left, seize one of the young men, and take his equipment for yourself.” But Asahel would not stop chasing him.'),
  ('BSB', '2 Samuel', 10, 2, 22, 'Once again, Abner warned Asahel, “Stop chasing me. Why should I strike you to the ground? How could I show my face to your brother Joab?”'),
  ('BSB', '2 Samuel', 10, 2, 23, 'But Asahel refused to turn away; so Abner thrust the butt of his spear into his stomach, and it came out his back, and he fell dead on the spot. And every man paused when he came to the place where Asahel had fallen and died.'),
  ('BSB', '2 Samuel', 10, 2, 24, 'But Joab and Abishai pursued Abner. By sunset, they had gone as far as the hill of Ammah opposite Giah on the way to the wilderness of Gibeon.'),
  ('BSB', '2 Samuel', 10, 2, 25, 'The Benjamites rallied to Abner, formed a single unit, and took their stand atop a hill.'),
  ('BSB', '2 Samuel', 10, 2, 26, 'Then Abner called out to Joab: “Must the sword devour forever? Do you not realize that this will only end in bitterness? How long before you tell the troops to stop pursuing their brothers?”'),
  ('BSB', '2 Samuel', 10, 2, 27, '“As surely as God lives,” Joab replied, “if you had not spoken up, the troops would have continued pursuing their brothers until morning.”'),
  ('BSB', '2 Samuel', 10, 2, 28, 'So Joab blew the ram’s horn, and all the troops stopped; they no longer pursued Israel or continued to fight.'),
  ('BSB', '2 Samuel', 10, 2, 29, 'And all that night Abner and his men marched through the Arabah. They crossed the Jordan, marched all morning, and arrived at Mahanaim.'),
  ('BSB', '2 Samuel', 10, 2, 30, 'When Joab returned from pursuing Abner, he gathered all the troops. In addition to Asahel, nineteen of David’s servants were missing,'),
  ('BSB', '2 Samuel', 10, 2, 31, 'but they had struck down 360 Benjamites who were with Abner.'),
  ('BSB', '2 Samuel', 10, 2, 32, 'Later, they took Asahel and buried him in his father’s tomb in Bethlehem. Then Joab and his men marched all night and reached Hebron at daybreak.'),
  ('BSB', '2 Samuel', 10, 3, 1, 'Now the war between the house of Saul and the house of David was protracted. And David grew stronger and stronger, while the house of Saul grew weaker and weaker.'),
  ('BSB', '2 Samuel', 10, 3, 2, 'And sons were born to David in Hebron: His firstborn was Amnon, by Ahinoam of Jezreel;'),
  ('BSB', '2 Samuel', 10, 3, 3, 'his second was Chileab, by Abigail the widow of Nabal of Carmel; his third was Absalom, the son of Maacah daughter of King Talmai of Geshur;'),
  ('BSB', '2 Samuel', 10, 3, 4, 'his fourth was Adonijah, the son of Haggith; his fifth was Shephatiah, the son of Abital;'),
  ('BSB', '2 Samuel', 10, 3, 5, 'and his sixth was Ithream, by David’s wife Eglah. These sons were born to David in Hebron.'),
  ('BSB', '2 Samuel', 10, 3, 6, 'During the war between the house of Saul and the house of David, Abner had continued to strengthen his position in the house of Saul.'),
  ('BSB', '2 Samuel', 10, 3, 7, 'Meanwhile, Saul had a concubine named Rizpah, the daughter of Aiah. So Ish-bosheth questioned Abner, “Why did you sleep with my father’s concubine?”'),
  ('BSB', '2 Samuel', 10, 3, 8, 'Abner was furious over Ish-bosheth’s accusation. “Am I the head of a dog that belongs to Judah?” he asked. “All this time I have been loyal to the house of your father Saul, to his brothers, and to his friends. I have not delivered you into the hand of David, but now you accuse me of wrongdoing with this woman!'),
  ('BSB', '2 Samuel', 10, 3, 9, 'May God punish Abner, and ever so severely, if I do not do for David what the LORD has sworn to him:'),
  ('BSB', '2 Samuel', 10, 3, 10, 'to transfer the kingdom from the house of Saul and to establish the throne of David over Israel and Judah, from Dan to Beersheba.”'),
  ('BSB', '2 Samuel', 10, 3, 11, 'And for fear of Abner, Ish-bosheth did not dare to say another word to him.'),
  ('BSB', '2 Samuel', 10, 3, 12, 'Then Abner sent messengers in his place to say to David, “To whom does the land belong? Make your covenant with me, and surely my hand will be with you to bring all Israel over to you.”'),
  ('BSB', '2 Samuel', 10, 3, 13, '“Good,” replied David, “I will make a covenant with you. But there is one thing I require of you: Do not appear before me unless you bring Saul’s daughter Michal when you come to see me.”'),
  ('BSB', '2 Samuel', 10, 3, 14, 'Then David sent messengers to say to Ish-bosheth son of Saul, “Give me back my wife, Michal, whom I betrothed to myself for a hundred Philistine foreskins.”'),
  ('BSB', '2 Samuel', 10, 3, 15, 'So Ish-bosheth sent and took Michal from her husband Paltiel son of Laish.'),
  ('BSB', '2 Samuel', 10, 3, 16, 'Her husband followed her, weeping all the way to Bahurim. Then Abner said to him, “Go back.” So he returned home.'),
  ('BSB', '2 Samuel', 10, 3, 17, 'Now Abner conferred with the elders of Israel and said, “In the past you sought David as your king.'),
  ('BSB', '2 Samuel', 10, 3, 18, 'Now take action, because the LORD has said to David, ‘Through My servant David I will save My people Israel from the hands of the Philistines and of all their enemies.’”'),
  ('BSB', '2 Samuel', 10, 3, 19, 'Abner also spoke to the Benjamites and went to Hebron to tell David all that seemed good to Israel and to the whole house of Benjamin.'),
  ('BSB', '2 Samuel', 10, 3, 20, 'When Abner and twenty of his men came to David at Hebron, David held a feast for them.'),
  ('BSB', '2 Samuel', 10, 3, 21, 'Then Abner said to David, “Let me go at once, and I will gather all Israel to my lord the king, that they may make a covenant with you, and that you may rule over all that your heart desires.” So David dismissed Abner, and he went in peace.'),
  ('BSB', '2 Samuel', 10, 3, 22, 'Just then David’s soldiers and Joab returned from a raid, bringing with them a great plunder. But Abner was not with David in Hebron because David had sent him on his way in peace.'),
  ('BSB', '2 Samuel', 10, 3, 23, 'When Joab and all his troops arrived, he was informed, “Abner son of Ner came to see the king, who sent him on his way in peace.”'),
  ('BSB', '2 Samuel', 10, 3, 24, 'So Joab went to the king and said, “What have you done? Look, Abner came to you. Why did you dismiss him? Now he is getting away!'),
  ('BSB', '2 Samuel', 10, 3, 25, 'Surely you realize that Abner son of Ner came to deceive you and to track your movements and all that you are doing.”'),
  ('BSB', '2 Samuel', 10, 3, 26, 'As soon as Joab had left David, he sent messengers after Abner, who brought him back from the well of Sirah; but David was unaware of it.'),
  ('BSB', '2 Samuel', 10, 3, 27, 'When Abner returned to Hebron, Joab pulled him aside into the gateway, as if to speak to him privately, and there Joab stabbed him in the stomach. So Abner died on account of the blood of Joab’s brother Asahel.'),
  ('BSB', '2 Samuel', 10, 3, 28, 'Afterward, David heard about this and said, “I and my kingdom are forever guiltless before the LORD concerning the blood of Abner son of Ner.'),
  ('BSB', '2 Samuel', 10, 3, 29, 'May it whirl over the heads of Joab and the entire house of his father, and may the house of Joab never be without one having a discharge or skin disease, or one who leans on a staff or falls by the sword or lacks food.”'),
  ('BSB', '2 Samuel', 10, 3, 30, '(Joab and his brother Abishai murdered Abner because he had killed their brother Asahel in the battle at Gibeon.)'),
  ('BSB', '2 Samuel', 10, 3, 31, 'Then David ordered Joab and all the people with him, “Tear your clothes, put on sackcloth, and mourn before Abner.” And King David himself walked behind the funeral bier.'),
  ('BSB', '2 Samuel', 10, 3, 32, 'When they buried Abner in Hebron, the king wept aloud at Abner’s tomb, and all the people wept.'),
  ('BSB', '2 Samuel', 10, 3, 33, 'And the king sang this lament for Abner: “Should Abner die the death of a fool?'),
  ('BSB', '2 Samuel', 10, 3, 34, 'Your hands were not bound, your feet were not fettered. As a man falls before the wicked, so also you fell.” And all the people wept over him even more.'),
  ('BSB', '2 Samuel', 10, 3, 35, 'Then all the people came and urged David to eat something while it was still day, but David took an oath, saying, “May God punish me, and ever so severely, if I taste bread or anything else before the sun sets!”'),
  ('BSB', '2 Samuel', 10, 3, 36, 'All the people took note and were pleased. In fact, everything the king did pleased them.'),
  ('BSB', '2 Samuel', 10, 3, 37, 'So on that day all the troops and all Israel were convinced that the king had no part in the murder of Abner son of Ner.'),
  ('BSB', '2 Samuel', 10, 3, 38, 'Then the king said to his servants, “Do you not realize that a great prince has fallen today in Israel?'),
  ('BSB', '2 Samuel', 10, 3, 39, 'And I am weak this day, though anointed as king, and these men, the sons of Zeruiah, are too fierce for me. May the LORD repay the evildoer according to his evil!”'),
  ('BSB', '2 Samuel', 10, 4, 1, 'Now when Ish-bosheth son of Saul heard that Abner had died in Hebron, he lost courage, and all Israel was dismayed.'),
  ('BSB', '2 Samuel', 10, 4, 2, 'Saul’s son had two men who were leaders of raiding parties. One was named Baanah and the other Rechab; they were sons of Rimmon the Beerothite of the tribe of Benjamin—Beeroth is considered part of Benjamin,'),
  ('BSB', '2 Samuel', 10, 4, 3, 'because the Beerothites fled to Gittaim and have lived there as foreigners to this day.'),
  ('BSB', '2 Samuel', 10, 4, 4, 'And Jonathan son of Saul had a son who was lame in his feet. He was five years old when the report about Saul and Jonathan came from Jezreel. His nurse picked him up and fled, but as she was hurrying to escape, he fell and became lame. His name was Mephibosheth.'),
  ('BSB', '2 Samuel', 10, 4, 5, 'Now Rechab and Baanah, the sons of Rimmon the Beerothite, set out and arrived at the house of Ish-bosheth in the heat of the day, while the king was taking his midday nap.'),
  ('BSB', '2 Samuel', 10, 4, 6, 'They entered the interior of the house as if to get some wheat, and they stabbed him in the stomach. Then Rechab and his brother Baanah slipped away.'),
  ('BSB', '2 Samuel', 10, 4, 7, 'They had entered the house while Ish-bosheth was lying on his bed, and having stabbed and killed him, they beheaded him, took his head, and traveled all night by way of the Arabah.'),
  ('BSB', '2 Samuel', 10, 4, 8, 'They brought the head of Ish-bosheth to David at Hebron and said to the king, “Here is the head of Ish-bosheth son of Saul, your enemy who sought your life. Today the LORD has granted vengeance to my lord the king against Saul and his offspring.”'),
  ('BSB', '2 Samuel', 10, 4, 9, 'But David answered Rechab and his brother Baanah, the sons of Rimmon the Beerothite, “As surely as the LORD lives, who has redeemed my life from all distress,'),
  ('BSB', '2 Samuel', 10, 4, 10, 'when someone told me, ‘Look, Saul is dead,’ and thought he was a bearer of good news, I seized him and put him to death at Ziklag. That was his reward for his news!'),
  ('BSB', '2 Samuel', 10, 4, 11, 'How much more, when wicked men kill a righteous man in his own house and on his own bed, shall I not now require his blood from your hands and remove you from the earth!”'),
  ('BSB', '2 Samuel', 10, 4, 12, 'So David commanded his young men, and they killed Rechab and Baanah. They cut off their hands and feet and hung their bodies by the pool in Hebron, but they took the head of Ish-bosheth and buried it in Abner’s tomb in Hebron.'),
  ('BSB', '2 Samuel', 10, 5, 1, 'Then all the tribes of Israel came to David at Hebron and said, “Here we are, your own flesh and blood.'),
  ('BSB', '2 Samuel', 10, 5, 2, 'Even in times past, while Saul was king over us, you were the one who led Israel out and brought them back. And to you the LORD said, ‘You will shepherd My people Israel, and you will be ruler over them.’”'),
  ('BSB', '2 Samuel', 10, 5, 3, 'So all the elders of Israel came to the king at Hebron, where King David made with them a covenant before the LORD. And they anointed him king over Israel.'),
  ('BSB', '2 Samuel', 10, 5, 4, 'David was thirty years old when he became king, and he reigned forty years.'),
  ('BSB', '2 Samuel', 10, 5, 5, 'In Hebron he reigned over Judah seven years and six months, and in Jerusalem he reigned thirty-three years over all Israel and Judah.'),
  ('BSB', '2 Samuel', 10, 5, 6, 'Now the king and his men marched to Jerusalem against the Jebusites who inhabited the land. The Jebusites said to David: “You will never get in here. Even the blind and lame can repel you.” For they thought, “David cannot get in here.”'),
  ('BSB', '2 Samuel', 10, 5, 7, 'Nevertheless, David captured the fortress of Zion (that is, the City of David).'),
  ('BSB', '2 Samuel', 10, 5, 8, 'On that day he said, “Whoever attacks the Jebusites must use the water shaft to reach the lame and blind who are despised by David.” That is why it is said, “The blind and the lame will never enter the palace.”'),
  ('BSB', '2 Samuel', 10, 5, 9, 'So David took up residence in the fortress and called it the City of David. He built it up all the way around, from the supporting terraces inward.'),
  ('BSB', '2 Samuel', 10, 5, 10, 'And David became greater and greater, for the LORD God of Hosts was with him.'),
  ('BSB', '2 Samuel', 10, 5, 11, 'Now Hiram king of Tyre sent envoys to David, along with cedar logs, carpenters, and stonemasons, and they built a palace for David.'),
  ('BSB', '2 Samuel', 10, 5, 12, 'And David realized that the LORD had established him as king over Israel and had exalted his kingdom for the sake of His people Israel.'),
  ('BSB', '2 Samuel', 10, 5, 13, 'After he had arrived from Hebron, David took more concubines and wives from Jerusalem, and more sons and daughters were born to him.'),
  ('BSB', '2 Samuel', 10, 5, 14, 'These are the names of the children born to him in Jerusalem: Shammua, Shobab, Nathan, Solomon,'),
  ('BSB', '2 Samuel', 10, 5, 15, 'Ibhar, Elishua, Nepheg, Japhia,'),
  ('BSB', '2 Samuel', 10, 5, 16, 'Elishama, Eliada, and Eliphelet.'),
  ('BSB', '2 Samuel', 10, 5, 17, 'When the Philistines heard that David had been anointed king over Israel, they all went in search of him; but David learned of this and went down to the stronghold.'),
  ('BSB', '2 Samuel', 10, 5, 18, 'Now the Philistines had come and spread out in the Valley of Rephaim.'),
  ('BSB', '2 Samuel', 10, 5, 19, 'So David inquired of the LORD, “Should I go up against the Philistines? Will You deliver them into my hand?” “Go,” replied the LORD, “for I will surely deliver the Philistines into your hand.”'),
  ('BSB', '2 Samuel', 10, 5, 20, 'So David went to Baal-perazim, where he defeated the Philistines and said, “Like a bursting flood, the LORD has burst out against my enemies before me.” So he called that place Baal-perazim.'),
  ('BSB', '2 Samuel', 10, 5, 21, 'There the Philistines abandoned their idols, and David and his men carried them away.'),
  ('BSB', '2 Samuel', 10, 5, 22, 'Once again the Philistines came up and spread out in the Valley of Rephaim.'),
  ('BSB', '2 Samuel', 10, 5, 23, 'So David inquired of the LORD, who answered, “Do not march straight up, but circle around behind them and attack them in front of the balsam trees.'),
  ('BSB', '2 Samuel', 10, 5, 24, 'As soon as you hear the sound of marching in the tops of the balsam trees, move quickly, because this will mean that the LORD has marched out before you to strike the camp of the Philistines.”'),
  ('BSB', '2 Samuel', 10, 5, 25, 'So David did as the LORD had commanded him, and he struck down the Philistines all the way from Gibeon to Gezer.'),
  ('BSB', '2 Samuel', 10, 6, 1, 'David again assembled the chosen men of Israel, thirty thousand in all.'),
  ('BSB', '2 Samuel', 10, 6, 2, 'And he and all his troops set out for Baale of Judah to bring up from there the ark of God, which is called by the Name— the name of the LORD of Hosts, who is enthroned between the cherubim that are on it.'),
  ('BSB', '2 Samuel', 10, 6, 3, 'They set the ark of God on a new cart and brought it from the house of Abinadab, which was on the hill. Uzzah and Ahio, the sons of Abinadab, were guiding the new cart,'),
  ('BSB', '2 Samuel', 10, 6, 4, 'bringing with it the ark of God. And Ahio was walking in front of the ark.'),
  ('BSB', '2 Samuel', 10, 6, 5, 'David and all the house of Israel were celebrating before the LORD with all kinds of wood instruments, harps, stringed instruments, tambourines, sistrums, and cymbals.'),
  ('BSB', '2 Samuel', 10, 6, 6, 'When they came to the threshing floor of Nacon, Uzzah reached out and took hold of the ark of God, because the oxen had stumbled.'),
  ('BSB', '2 Samuel', 10, 6, 7, 'And the anger of the LORD burned against Uzzah, and God struck him down on the spot for his irreverence, and he died there beside the ark of God.'),
  ('BSB', '2 Samuel', 10, 6, 8, 'Then David became angry because the LORD had burst forth against Uzzah; so he named that place Perez-uzzah, as it is called to this day.'),
  ('BSB', '2 Samuel', 10, 6, 9, 'That day David feared the LORD and asked, “How can the ark of the LORD ever come to me?”'),
  ('BSB', '2 Samuel', 10, 6, 10, 'So he was unwilling to move the ark of the LORD to the City of David; instead, he took it aside to the house of Obed-edom the Gittite.'),
  ('BSB', '2 Samuel', 10, 6, 11, 'Thus the ark of the LORD remained in the house of Obed-edom the Gittite for three months, and the LORD blessed him and all his household.'),
  ('BSB', '2 Samuel', 10, 6, 12, 'Now it was reported to King David, “The LORD has blessed the house of Obed-edom and all that belongs to him, because of the ark of God.” So David went and had the ark of God brought up from the house of Obed-edom into the City of David with rejoicing.'),
  ('BSB', '2 Samuel', 10, 6, 13, 'When those carrying the ark of the LORD had advanced six paces, he sacrificed an ox and a fattened calf.'),
  ('BSB', '2 Samuel', 10, 6, 14, 'And David, wearing a linen ephod, danced with all his might before the LORD,'),
  ('BSB', '2 Samuel', 10, 6, 15, 'while he and all the house of Israel brought up the ark of the LORD with shouting and the sounding of the ram’s horn.'),
  ('BSB', '2 Samuel', 10, 6, 16, 'As the ark of the LORD was entering the City of David, Saul’s daughter Michal looked down from a window and saw King David leaping and dancing before the LORD, and she despised him in her heart.'),
  ('BSB', '2 Samuel', 10, 6, 17, 'So they brought the ark of the LORD and set it in its place inside the tent that David had pitched for it. Then David offered burnt offerings and peace offerings before the LORD.'),
  ('BSB', '2 Samuel', 10, 6, 18, 'When David had finished sacrificing the burnt offerings and peace offerings, he blessed the people in the name of the LORD of Hosts.'),
  ('BSB', '2 Samuel', 10, 6, 19, 'Then he distributed to every man and woman among the multitude of Israel a loaf of bread, a date cake, and a raisin cake. And all the people departed, each for his own home.'),
  ('BSB', '2 Samuel', 10, 6, 20, 'As soon as David returned home to bless his own household, Saul’s daughter Michal came out to meet him. “How the king of Israel has distinguished himself today!” she said. “He has uncovered himself today in the sight of the maidservants of his subjects, like a vulgar person would do.”'),
  ('BSB', '2 Samuel', 10, 6, 21, 'But David said to Michal, “I was dancing before the LORD, who chose me over your father and all his house when He appointed me ruler over the LORD’s people Israel. I will celebrate before the LORD,'),
  ('BSB', '2 Samuel', 10, 6, 22, 'and I will humiliate and humble myself even more than this. Yet I will be honored by the maidservants of whom you have spoken.”'),
  ('BSB', '2 Samuel', 10, 6, 23, 'And Michal the daughter of Saul had no children to the day of her death.'),
  ('BSB', '2 Samuel', 10, 7, 1, 'After the king had settled into his palace and the LORD had given him rest from all his enemies around him,'),
  ('BSB', '2 Samuel', 10, 7, 2, 'he said to Nathan the prophet, “Here I am, living in a house of cedar, while the ark of God remains in a tent.”'),
  ('BSB', '2 Samuel', 10, 7, 3, 'And Nathan replied to the king, “Go and do all that is in your heart, for the LORD is with you.”'),
  ('BSB', '2 Samuel', 10, 7, 4, 'But that night the word of the LORD came to Nathan, saying,'),
  ('BSB', '2 Samuel', 10, 7, 5, '“Go and tell My servant David that this is what the LORD says: Are you the one to build for Me a house to dwell in?'),
  ('BSB', '2 Samuel', 10, 7, 6, 'For I have not dwelt in a house from the day I brought the Israelites up out of Egypt until this day, but I have moved about with a tent as My dwelling.'),
  ('BSB', '2 Samuel', 10, 7, 7, 'In all My journeys with all the Israelites, have I ever asked any of the leaders I appointed to shepherd My people Israel, ‘Why haven’t you built Me a house of cedar?’'),
  ('BSB', '2 Samuel', 10, 7, 8, 'Now then, you are to tell My servant David that this is what the LORD of Hosts says: I took you from the pasture, from following the flock, to be the ruler over My people Israel.'),
  ('BSB', '2 Samuel', 10, 7, 9, 'I have been with you wherever you have gone, and I have cut off all your enemies from before you. Now I will make for you a name like the greatest in the land.'),
  ('BSB', '2 Samuel', 10, 7, 10, 'And I will provide a place for My people Israel and will plant them so that they may dwell in a place of their own and be disturbed no more. No longer will the sons of wickedness oppress them as they did at the beginning'),
  ('BSB', '2 Samuel', 10, 7, 11, 'and have done since the day I appointed judges over My people Israel. I will give you rest from all your enemies. The LORD declares to you that He Himself will establish a house for you.'),
  ('BSB', '2 Samuel', 10, 7, 12, 'And when your days are fulfilled and you rest with your fathers, I will raise up your descendant after you, who will come from your own body, and I will establish his kingdom.'),
  ('BSB', '2 Samuel', 10, 7, 13, 'He will build a house for My Name, and I will establish the throne of his kingdom forever.'),
  ('BSB', '2 Samuel', 10, 7, 14, 'I will be his Father, and he will be My son. When he does wrong, I will discipline him with the rod of men and with the blows of the sons of men.'),
  ('BSB', '2 Samuel', 10, 7, 15, 'But My loving devotion will never be removed from him as I removed it from Saul, whom I moved out of your way.'),
  ('BSB', '2 Samuel', 10, 7, 16, 'Your house and kingdom will endure forever before Me, and your throne will be established forever.”'),
  ('BSB', '2 Samuel', 10, 7, 17, 'So Nathan relayed to David all the words of this entire vision.'),
  ('BSB', '2 Samuel', 10, 7, 18, 'Then King David went in, sat before the LORD, and said, “Who am I, O Lord GOD, and what is my house, that You have brought me this far?'),
  ('BSB', '2 Samuel', 10, 7, 19, 'And as if this was a small thing in Your eyes, O Lord GOD, You have also spoken about the future of the house of Your servant. Is this Your custom with man, O Lord GOD?'),
  ('BSB', '2 Samuel', 10, 7, 20, 'What more can David say to You? For You know Your servant, O Lord GOD.'),
  ('BSB', '2 Samuel', 10, 7, 21, 'For the sake of Your word and according to Your own heart, You have accomplished this great thing and revealed it to Your servant.'),
  ('BSB', '2 Samuel', 10, 7, 22, 'How great You are, O Lord GOD! For there is none like You, and there is no God but You, according to everything we have heard with our own ears.'),
  ('BSB', '2 Samuel', 10, 7, 23, 'And who is like Your people Israel—the one nation on earth whom God went out to redeem as a people for Himself and to make a name for Himself? You performed great and awesome wonders by driving out nations and their gods from before Your people, whom You redeemed for Yourself from Egypt.'),
  ('BSB', '2 Samuel', 10, 7, 24, 'For You have established Your people Israel as Your very own forever, and You, O LORD, have become their God.'),
  ('BSB', '2 Samuel', 10, 7, 25, 'And now, O LORD God, confirm forever the word You have spoken concerning Your servant and his house. Do as You have promised,'),
  ('BSB', '2 Samuel', 10, 7, 26, 'so that Your name will be magnified forever when it is said, ‘The LORD of Hosts is God over Israel.’ And the house of Your servant David will be established before You.'),
  ('BSB', '2 Samuel', 10, 7, 27, 'For You, O LORD of Hosts, the God of Israel, have revealed this to Your servant when You said, ‘I will build a house for you.’ Therefore Your servant has found the courage to offer this prayer to You.'),
  ('BSB', '2 Samuel', 10, 7, 28, 'And now, O Lord GOD, You are God! Your words are true, and You have promised this goodness to Your servant.'),
  ('BSB', '2 Samuel', 10, 7, 29, 'Now therefore, may it please You to bless the house of Your servant, that it may continue forever before You. For You, O Lord GOD, have spoken, and with Your blessing the house of Your servant will be blessed forever.”'),
  ('BSB', '2 Samuel', 10, 8, 1, 'Some time later, David defeated the Philistines, subdued them, and took Metheg-ammah from the hand of the Philistines.'),
  ('BSB', '2 Samuel', 10, 8, 2, 'David also defeated the Moabites, made them lie down on the ground, and measured them off with a cord. He measured off with two lengths those to be put to death, and with one length those to be spared. So the Moabites became subject to David and brought him tribute.'),
  ('BSB', '2 Samuel', 10, 8, 3, 'David also defeated Hadadezer son of Rehob, king of Zobah, who had marched out to restore his dominion along the Euphrates River.'),
  ('BSB', '2 Samuel', 10, 8, 4, 'David captured from him a thousand chariots, seven thousand charioteers, and twenty thousand foot soldiers, and he hamstrung all the horses except a hundred he kept for the chariots.'),
  ('BSB', '2 Samuel', 10, 8, 5, 'When the Arameans of Damascus came to help King Hadadezer of Zobah, David struck down twenty-two thousand men.'),
  ('BSB', '2 Samuel', 10, 8, 6, 'Then he placed garrisons in Aram of Damascus, and the Arameans became subject to David and brought him tribute. So the LORD made David victorious wherever he went.'),
  ('BSB', '2 Samuel', 10, 8, 7, 'And David took the gold shields that belonged to the officers of Hadadezer and brought them to Jerusalem.'),
  ('BSB', '2 Samuel', 10, 8, 8, 'And from Betah and Berothai, cities of Hadadezer, King David took a large amount of bronze.'),
  ('BSB', '2 Samuel', 10, 8, 9, 'When King Toi of Hamath heard that David had defeated the entire army of Hadadezer,'),
  ('BSB', '2 Samuel', 10, 8, 10, 'he sent his son Joram to greet King David and bless him for fighting and defeating Hadadezer, who had been at war with Toi. Joram brought with him articles of silver and gold and bronze,'),
  ('BSB', '2 Samuel', 10, 8, 11, 'and King David dedicated these to the LORD, along with the silver and gold he had dedicated from all the nations he had subdued—'),
  ('BSB', '2 Samuel', 10, 8, 12, 'from Edom and Moab, from the Ammonites and Philistines and Amalekites, and from the spoil of Hadadezer son of Rehob, king of Zobah.'),
  ('BSB', '2 Samuel', 10, 8, 13, 'And David made a name for himself when he returned from striking down eighteen thousand Edomites in the Valley of Salt.'),
  ('BSB', '2 Samuel', 10, 8, 14, 'He placed garrisons throughout Edom, and all the Edomites were subject to David. So the LORD made David victorious wherever he went.'),
  ('BSB', '2 Samuel', 10, 8, 15, 'Thus David reigned over all Israel and administered justice and righteousness for all his people:'),
  ('BSB', '2 Samuel', 10, 8, 16, 'Joab son of Zeruiah was over the army; Jehoshaphat son of Ahilud was the recorder;'),
  ('BSB', '2 Samuel', 10, 8, 17, 'Zadok son of Ahitub and Ahimelech son of Abiathar were priests; Seraiah was the scribe;'),
  ('BSB', '2 Samuel', 10, 8, 18, 'Benaiah son of Jehoiada was over the Cherethites and Pelethites; and David’s sons were priestly leaders.'),
  ('BSB', '2 Samuel', 10, 9, 1, 'Then David asked, “Is there anyone left from the house of Saul to whom I can show kindness for the sake of Jonathan?”'),
  ('BSB', '2 Samuel', 10, 9, 2, 'And there was a servant of Saul’s family named Ziba. They summoned him to David, and the king inquired, “Are you Ziba?” “I am your servant,” he replied.'),
  ('BSB', '2 Samuel', 10, 9, 3, 'So the king asked, “Is there anyone left of Saul’s family to whom I can show the kindness of God?” Ziba answered, “There is still Jonathan’s son, who is lame in both feet.”'),
  ('BSB', '2 Samuel', 10, 9, 4, '“Where is he?” replied the king. And Ziba said, “Indeed, he is in Lo-debar at the house of Machir son of Ammiel.”'),
  ('BSB', '2 Samuel', 10, 9, 5, 'So King David had him brought from the house of Machir son of Ammiel in Lo-debar.'),
  ('BSB', '2 Samuel', 10, 9, 6, 'And when Mephibosheth son of Jonathan, the son of Saul, came to David, he fell facedown in reverence. Then David said, “Mephibosheth!” “I am your servant,” he replied.'),
  ('BSB', '2 Samuel', 10, 9, 7, '“Do not be afraid,” said David, “for surely I will show you kindness for the sake of your father Jonathan. I will restore to you all the land of your grandfather Saul, and you will always eat at my table.”'),
  ('BSB', '2 Samuel', 10, 9, 8, 'Mephibosheth bowed down and said, “What is your servant, that you should show regard for a dead dog like me?”'),
  ('BSB', '2 Samuel', 10, 9, 9, 'Then the king summoned Saul’s servant Ziba and said to him, “I have given to your master’s grandson all that belonged to Saul and to all his house.'),
  ('BSB', '2 Samuel', 10, 9, 10, 'You and your sons and servants are to work the ground for him and bring in the harvest, so that your master’s grandson may have food to eat. But Mephibosheth, your master’s grandson, is always to eat at my table.” Now Ziba had fifteen sons and twenty servants.'),
  ('BSB', '2 Samuel', 10, 9, 11, 'And Ziba said to the king, “Your servant will do all that my lord the king has commanded.” So Mephibosheth ate at David’s table like one of the king’s own sons.'),
  ('BSB', '2 Samuel', 10, 9, 12, 'And Mephibosheth had a young son named Mica, and all who dwelt in the house of Ziba were servants of Mephibosheth.'),
  ('BSB', '2 Samuel', 10, 9, 13, 'So Mephibosheth lived in Jerusalem, because he always ate at the king’s table, and he was lame in both feet.'),
  ('BSB', '2 Samuel', 10, 10, 1, 'Some time later, the king of the Ammonites died and was succeeded by his son Hanun.'),
  ('BSB', '2 Samuel', 10, 10, 2, 'And David said, “I will show kindness to Hanun son of Nahash, just as his father showed kindness to me.” So David sent some of his servants to console Hanun concerning his father. But when they arrived in the land of the Ammonites,'),
  ('BSB', '2 Samuel', 10, 10, 3, 'the princes of the Ammonites said to Hanun their lord, “Just because David has sent you comforters, do you really believe he is showing respect for your father? Has not David instead sent his servants to explore the city, spy it out, and overthrow it?”'),
  ('BSB', '2 Samuel', 10, 10, 4, 'So Hanun took David’s servants, shaved off half of each man’s beard, cut off their garments at the hips, and sent them away.'),
  ('BSB', '2 Samuel', 10, 10, 5, 'When this was reported to David, he sent messengers to meet the men, since they had been thoroughly humiliated. The king told them, “Stay in Jericho until your beards have grown back, and then return.”'),
  ('BSB', '2 Samuel', 10, 10, 6, 'When the Ammonites realized that they had become a stench to David, they hired twenty thousand Aramean foot soldiers from Beth-rehob and Zoba, as well as a thousand men from the king of Maacah and twelve thousand men from Tob.'),
  ('BSB', '2 Samuel', 10, 10, 7, 'On hearing this, David sent Joab and the entire army of mighty men.'),
  ('BSB', '2 Samuel', 10, 10, 8, 'The Ammonites marched out and arrayed themselves for battle at the entrance of the city gate, while the Arameans of Zobah and Rehob and the men of Tob and Maacah were by themselves in the open country.'),
  ('BSB', '2 Samuel', 10, 10, 9, 'When Joab saw the battle lines before him and behind him, he selected some of the best men of Israel and arrayed them against the Arameans.'),
  ('BSB', '2 Samuel', 10, 10, 10, 'And he placed the rest of the forces under the command of his brother Abishai, who arrayed them against the Ammonites.'),
  ('BSB', '2 Samuel', 10, 10, 11, '“If the Arameans are too strong for me,” said Joab, “then you will come to my rescue. And if the Ammonites are too strong for you, then I will come to your rescue.'),
  ('BSB', '2 Samuel', 10, 10, 12, 'Be strong and let us fight bravely for our people and for the cities of our God. May the LORD do what is good in His sight.”'),
  ('BSB', '2 Samuel', 10, 10, 13, 'So Joab and his troops advanced to fight the Arameans, who fled before him.'),
  ('BSB', '2 Samuel', 10, 10, 14, 'When the Ammonites saw that the Arameans had fled, they too fled before Abishai, and they entered the city. So Joab returned from fighting against the Ammonites and came to Jerusalem.'),
  ('BSB', '2 Samuel', 10, 10, 15, 'When the Arameans saw that they had been defeated by Israel, they regrouped.'),
  ('BSB', '2 Samuel', 10, 10, 16, 'Hadadezer sent messengers to bring more Arameans from beyond the Euphrates, and they came to Helam with Shobach the commander of Hadadezer’s army leading them.'),
  ('BSB', '2 Samuel', 10, 10, 17, 'When this was reported to David, he gathered all Israel, crossed the Jordan, and went to Helam. Then the Arameans arrayed themselves against David and fought against him.'),
  ('BSB', '2 Samuel', 10, 10, 18, 'But the Arameans fled before Israel, and David killed seven hundred charioteers and forty thousand foot soldiers. He also struck down Shobach the commander of their army, who died there.'),
  ('BSB', '2 Samuel', 10, 10, 19, 'When all the kings who were subject to Hadadezer saw that they had been defeated by Israel, they made peace with Israel and became subject to them. So the Arameans were afraid to help the Ammonites anymore.'),
  ('BSB', '2 Samuel', 10, 11, 1, 'In the spring, at the time when kings march out to war, David sent out Joab and his servants with the whole army of Israel. They destroyed the Ammonites and besieged Rabbah, but David remained in Jerusalem.'),
  ('BSB', '2 Samuel', 10, 11, 2, 'One evening David got up from his bed and strolled around on the roof of the palace. And from the roof he saw a woman bathing—a very beautiful woman.'),
  ('BSB', '2 Samuel', 10, 11, 3, 'So David sent and inquired about the woman, and he was told, “This is Bathsheba, the daughter of Eliam and the wife of Uriah the Hittite.”'),
  ('BSB', '2 Samuel', 10, 11, 4, 'Then David sent messengers to get her, and when she came to him, he slept with her. (Now she had just purified herself from her uncleanness.) Then she returned home.'),
  ('BSB', '2 Samuel', 10, 11, 5, 'And the woman conceived and sent word to David, saying, “I am pregnant.”'),
  ('BSB', '2 Samuel', 10, 11, 6, 'At this, David sent orders to Joab: “Send me Uriah the Hittite.” So Joab sent him to David.'),
  ('BSB', '2 Samuel', 10, 11, 7, 'When Uriah came to him, David asked how Joab and the troops were doing with the war.'),
  ('BSB', '2 Samuel', 10, 11, 8, 'Then he said to Uriah, “Go down to your house and wash your feet.” So Uriah left the palace, and a gift from the king followed him.'),
  ('BSB', '2 Samuel', 10, 11, 9, 'But Uriah slept at the door of the palace with all his master’s servants; he did not go down to his house.'),
  ('BSB', '2 Samuel', 10, 11, 10, 'And David was told, “Uriah did not go home.” “Haven’t you just arrived from a journey?” David asked Uriah. “Why didn’t you go home?”'),
  ('BSB', '2 Samuel', 10, 11, 11, 'Uriah answered, “The ark and Israel and Judah are dwelling in tents, and my master Joab and his soldiers are camped in the open field. How can I go to my house to eat and drink and sleep with my wife? As surely as you live, and as your soul lives, I will not do such a thing!”'),
  ('BSB', '2 Samuel', 10, 11, 12, '“Stay here one more day,” David said to Uriah, “and tomorrow I will send you back.” So Uriah stayed in Jerusalem that day and the next.'),
  ('BSB', '2 Samuel', 10, 11, 13, 'Then David invited Uriah to eat and drink with him, and he got Uriah drunk. And in the evening Uriah went out to lie down on his cot with his master’s servants, but he did not go home.'),
  ('BSB', '2 Samuel', 10, 11, 14, 'The next morning David wrote a letter to Joab and sent it with Uriah.'),
  ('BSB', '2 Samuel', 10, 11, 15, 'In the letter he wrote: “Put Uriah at the front of the fiercest battle; then withdraw from him, so that he may be struck down and killed.”'),
  ('BSB', '2 Samuel', 10, 11, 16, 'So as Joab besieged the city, he assigned Uriah to a place where he saw the strongest enemy soldiers.'),
  ('BSB', '2 Samuel', 10, 11, 17, 'And when the men of the city came out and fought against Joab, some of David’s servants fell, and Uriah the Hittite also died.'),
  ('BSB', '2 Samuel', 10, 11, 18, 'Joab sent to David a full account of the battle'),
  ('BSB', '2 Samuel', 10, 11, 19, 'and instructed the messenger, “When you have finished giving the king all the details of the battle,'),
  ('BSB', '2 Samuel', 10, 11, 20, 'if the king’s anger flares, he may ask you, ‘Why did you get so close to the city to fight? Did you not realize they would shoot from atop the wall?'),
  ('BSB', '2 Samuel', 10, 11, 21, 'Who was the one to strike Abimelech son of Jerubbesheth? Was it not a woman who dropped an upper millstone on him from the wall, so that he died in Thebez? Why did you get so close to the wall?’ If so, then you are to say, ‘Your servant Uriah the Hittite is dead as well.’”'),
  ('BSB', '2 Samuel', 10, 11, 22, 'So the messenger set out and reported to David all that Joab had sent him to say.'),
  ('BSB', '2 Samuel', 10, 11, 23, 'The messenger said to David, “The men overpowered us and came out against us in the field, but we drove them back to the entrance of the gate.'),
  ('BSB', '2 Samuel', 10, 11, 24, 'Then the archers shot at your servants from the wall, and some of the king’s servants were killed. And your servant Uriah the Hittite is dead as well.”'),
  ('BSB', '2 Samuel', 10, 11, 25, 'Then David told the messenger, “Say this to Joab: ‘Do not let this matter upset you, for the sword devours one as well as another. Strengthen your attack against the city and demolish it.’ Encourage him with these words.”'),
  ('BSB', '2 Samuel', 10, 11, 26, 'When Uriah’s wife heard that her husband was dead, she mourned for him.'),
  ('BSB', '2 Samuel', 10, 11, 27, 'And when the time of mourning was over, David had her brought to his house, and she became his wife and bore him a son. But the thing that David had done was evil in the sight of the LORD.'),
  ('BSB', '2 Samuel', 10, 12, 1, 'Then the LORD sent Nathan to David, and when he arrived, he said, “There were two men in a certain city, one rich and the other poor.'),
  ('BSB', '2 Samuel', 10, 12, 2, 'The rich man had a great number of sheep and cattle,'),
  ('BSB', '2 Samuel', 10, 12, 3, 'but the poor man had nothing except one small ewe lamb that he had bought. He raised it, and it grew up with him and his children. It shared his food and drank from his cup; it slept in his arms and was like a daughter to him.'),
  ('BSB', '2 Samuel', 10, 12, 4, 'Now a traveler came to the rich man, who refrained from taking one of his own sheep or cattle to prepare for the traveler who had come to him. Instead, he took the poor man’s lamb and prepared it for his guest.”'),
  ('BSB', '2 Samuel', 10, 12, 5, 'David burned with anger against the man and said to Nathan: “As surely as the LORD lives, the man who did this deserves to die!'),
  ('BSB', '2 Samuel', 10, 12, 6, 'Because he has done this thing and has shown no pity, he must pay for the lamb four times over.”'),
  ('BSB', '2 Samuel', 10, 12, 7, 'Then Nathan said to David, “You are that man! This is what the LORD, the God of Israel, says: ‘I anointed you king over Israel, and I delivered you from the hand of Saul.'),
  ('BSB', '2 Samuel', 10, 12, 8, 'I gave your master’s house to you and your master’s wives into your arms. I gave you the house of Israel and Judah, and if that was not enough, I would have given you even more.'),
  ('BSB', '2 Samuel', 10, 12, 9, 'Why then have you despised the command of the LORD by doing evil in His sight? You put Uriah the Hittite to the sword and took his wife as your own, for you have slain him with the sword of the Ammonites.'),
  ('BSB', '2 Samuel', 10, 12, 10, 'Now, therefore, the sword will never depart from your house, because you have despised Me and have taken the wife of Uriah the Hittite to be your own.’'),
  ('BSB', '2 Samuel', 10, 12, 11, 'This is what the LORD says: ‘I will raise up adversity against you from your own house. Before your very eyes I will take your wives and give them to another, and he will lie with them in broad daylight.'),
  ('BSB', '2 Samuel', 10, 12, 12, 'You have acted in secret, but I will do this thing in broad daylight before all Israel.’”'),
  ('BSB', '2 Samuel', 10, 12, 13, 'Then David said to Nathan, “I have sinned against the LORD.” “The LORD has taken away your sin,” Nathan replied. “You will not die.'),
  ('BSB', '2 Samuel', 10, 12, 14, 'Nevertheless, because by this deed you have shown utter contempt for the word of the LORD, the son born to you will surely die.”'),
  ('BSB', '2 Samuel', 10, 12, 15, 'After Nathan had gone home, the LORD struck the child that Uriah’s wife had borne to David, and he became ill.'),
  ('BSB', '2 Samuel', 10, 12, 16, 'David pleaded with God for the boy. He fasted and went into his house and spent the night lying in sackcloth on the ground.'),
  ('BSB', '2 Samuel', 10, 12, 17, 'The elders of his household stood beside him to help him up from the ground, but he was unwilling and would not eat anything with them.'),
  ('BSB', '2 Samuel', 10, 12, 18, 'On the seventh day the child died. But David’s servants were afraid to tell him that the child was dead, for they said, “Look, while the child was alive, we spoke to him, and he would not listen to us. So how can we tell him the child is dead? He may even harm himself.”'),
  ('BSB', '2 Samuel', 10, 12, 19, 'When David saw that his servants were whispering to one another, he perceived that the child was dead. So he asked his servants, “Is the child dead?” “He is dead,” they replied.'),
  ('BSB', '2 Samuel', 10, 12, 20, 'Then David got up from the ground, washed and anointed himself, changed his clothes, and went into the house of the LORD and worshiped. Then he went to his own house, and at his request they set food before him, and he ate.'),
  ('BSB', '2 Samuel', 10, 12, 21, '“What is this you have done?” his servants asked. “While the child was alive, you fasted and wept, but when he died, you got up and ate.”'),
  ('BSB', '2 Samuel', 10, 12, 22, 'David answered, “While the child was alive, I fasted and wept, for I said, ‘Who knows? The LORD may be gracious to me and let him live.’'),
  ('BSB', '2 Samuel', 10, 12, 23, 'But now that he is dead, why should I fast? Can I bring him back again? I will go to him, but he will not return to me.”'),
  ('BSB', '2 Samuel', 10, 12, 24, 'Then David comforted his wife Bathsheba, and he went to her and lay with her. So she gave birth to a son, and they named him Solomon. Now the LORD loved the child'),
  ('BSB', '2 Samuel', 10, 12, 25, 'and sent word through Nathan the prophet to name him Jedidiah because the LORD loved him.'),
  ('BSB', '2 Samuel', 10, 12, 26, 'Meanwhile, Joab fought against Rabbah of the Ammonites and captured the royal fortress.'),
  ('BSB', '2 Samuel', 10, 12, 27, 'Then Joab sent messengers to David to say, “I have fought against Rabbah and have captured the water supply of the city.'),
  ('BSB', '2 Samuel', 10, 12, 28, 'Now, therefore, assemble the rest of the troops, lay siege to the city, and capture it. Otherwise I will capture the city, and it will be named after me.”'),
  ('BSB', '2 Samuel', 10, 12, 29, 'So David assembled all the troops and went to Rabbah; and he fought against it and captured it.'),
  ('BSB', '2 Samuel', 10, 12, 30, 'Then he took the crown from the head of their king. It weighed a talent of gold and was set with precious stones, and it was placed on David’s head. And David took a great amount of plunder from the city.'),
  ('BSB', '2 Samuel', 10, 12, 31, 'David brought out the people who were there and put them to work with saws, iron picks, and axes, and he made them work at the brick kilns. He did the same to all the Ammonite cities. Then David and all his troops returned to Jerusalem.'),
  ('BSB', '2 Samuel', 10, 13, 1, 'After some time, David’s son Amnon fell in love with Tamar, the beautiful sister of David’s son Absalom.'),
  ('BSB', '2 Samuel', 10, 13, 2, 'Amnon was sick with frustration over his sister Tamar, for she was a virgin, and it seemed implausible for him to do anything to her.'),
  ('BSB', '2 Samuel', 10, 13, 3, 'Now Amnon had a friend named Jonadab, the son of David’s brother Shimeah. Jonadab was a very shrewd man,'),
  ('BSB', '2 Samuel', 10, 13, 4, 'so he asked Amnon, “Why are you, the son of the king, so depressed morning after morning? Won’t you tell me?” Amnon replied, “I am in love with Tamar, my brother Absalom’s sister.”'),
  ('BSB', '2 Samuel', 10, 13, 5, 'Jonadab told him, “Lie down on your bed and pretend you are ill. When your father comes to see you, say to him, ‘Please let my sister Tamar come and give me something to eat. Let her prepare it in my sight so I may watch her and eat it from her hand.’”'),
  ('BSB', '2 Samuel', 10, 13, 6, 'So Amnon lay down and feigned illness. When the king came to see him, Amnon said, “Please let my sister Tamar come and make a couple of cakes in my sight, so that I may eat from her hand.”'),
  ('BSB', '2 Samuel', 10, 13, 7, 'Then David sent word to Tamar at the palace: “Please go to the house of Amnon your brother and prepare a meal for him.”'),
  ('BSB', '2 Samuel', 10, 13, 8, 'So Tamar went to the house of her brother Amnon, who was lying down. She took some dough, kneaded it, made cakes in his sight, and baked them.'),
  ('BSB', '2 Samuel', 10, 13, 9, 'Then she brought the pan and set it down before him, but he refused to eat. “Send everyone away!” said Amnon. And everyone went out.'),
  ('BSB', '2 Samuel', 10, 13, 10, 'Then Amnon said to Tamar, “Bring the food into the bedroom, so that I may eat it from your hand.” Tamar took the cakes she had made and went to her brother Amnon’s bedroom.'),
  ('BSB', '2 Samuel', 10, 13, 11, 'And when she had brought them to him to eat, he took hold of her and said, “Come lie with me, my sister!”'),
  ('BSB', '2 Samuel', 10, 13, 12, '“No, my brother!” she cried. “Do not humiliate me, for such a thing should never be done in Israel. Do not do this disgraceful thing!'),
  ('BSB', '2 Samuel', 10, 13, 13, 'Where could I ever take my shame? And you would be like one of the fools in Israel! Please speak to the king, for he will not withhold me from you.”'),
  ('BSB', '2 Samuel', 10, 13, 14, 'But Amnon refused to listen to her, and being stronger, he violated her and lay with her.'),
  ('BSB', '2 Samuel', 10, 13, 15, 'Then Amnon hated Tamar with such intensity that his hatred was greater than the love he previously had. “Get up!” he said to her. “Be gone!”'),
  ('BSB', '2 Samuel', 10, 13, 16, '“No,” she replied, “sending me away is worse than this great wrong you have already done to me!” But he refused to listen to her.'),
  ('BSB', '2 Samuel', 10, 13, 17, 'Instead, he called to his attendant and said, “Throw this woman out and bolt the door behind her!”'),
  ('BSB', '2 Samuel', 10, 13, 18, 'So Amnon’s attendant threw her out and bolted the door behind her. Now Tamar was wearing a robe of many colors, because this is what the king’s virgin daughters wore.'),
  ('BSB', '2 Samuel', 10, 13, 19, 'And Tamar put ashes on her head and tore her robe. And putting her hand on her head, she went away crying bitterly.'),
  ('BSB', '2 Samuel', 10, 13, 20, 'Her brother Absalom said to her, “Has your brother Amnon been with you? Be quiet for now, my sister. He is your brother. Do not take this thing to heart.” So Tamar lived as a desolate woman in the house of her brother Absalom.'),
  ('BSB', '2 Samuel', 10, 13, 21, 'When King David heard all this, he was furious.'),
  ('BSB', '2 Samuel', 10, 13, 22, 'And Absalom never said a word to Amnon, either good or bad, because he hated Amnon for disgracing his sister Tamar.'),
  ('BSB', '2 Samuel', 10, 13, 23, 'Two years later, when Absalom’s sheepshearers were at Baal-hazor near Ephraim, he invited all the sons of the king.'),
  ('BSB', '2 Samuel', 10, 13, 24, 'And he went to the king and said, “Your servant has just hired shearers. Will the king and his servants please come with me?”'),
  ('BSB', '2 Samuel', 10, 13, 25, '“No, my son,” the king replied, “we should not all go, or we would be a burden to you.” Although Absalom urged him, he was not willing to go, but gave him his blessing.'),
  ('BSB', '2 Samuel', 10, 13, 26, '“If not,” said Absalom, “please let my brother Amnon go with us.” “Why should he go with you?” the king asked.'),
  ('BSB', '2 Samuel', 10, 13, 27, 'But Absalom urged him, so the king sent Amnon and the rest of his sons.'),
  ('BSB', '2 Samuel', 10, 13, 28, 'Now Absalom had ordered his young men, “Watch Amnon until his heart is merry with wine, and when I order you to strike Amnon down, you are to kill him. Do not be afraid. Have I not commanded you? Be courageous and valiant!”'),
  ('BSB', '2 Samuel', 10, 13, 29, 'So Absalom’s young men did to Amnon just as Absalom had ordered. Then all the other sons of the king got up, and each one fled on his mule.'),
  ('BSB', '2 Samuel', 10, 13, 30, 'While they were on the way, a report reached David: “Absalom has struck down all the sons of the king; not one of them is left!”'),
  ('BSB', '2 Samuel', 10, 13, 31, 'Then the king stood up, tore his clothes, and lay down on the ground; and all his servants stood by with their clothes torn.'),
  ('BSB', '2 Samuel', 10, 13, 32, 'But Jonadab, the son of David’s brother Shimeah, spoke up: “My lord must not think they have killed all the sons of the king, for only Amnon is dead. In fact, Absalom has planned this since the day Amnon violated his sister Tamar.'),
  ('BSB', '2 Samuel', 10, 13, 33, 'So now, my lord the king, do not take to heart the report that all the sons of the king are dead. Only Amnon is dead.”'),
  ('BSB', '2 Samuel', 10, 13, 34, 'Meanwhile, Absalom had fled. When the young man standing watch looked up, he saw many people coming down the road west of him, along the side of the hill. And the watchman went and reported to the king, “I see men coming from the direction of Horonaim, along the side of the hill.”'),
  ('BSB', '2 Samuel', 10, 13, 35, 'So Jonadab said to the king, “Look, the sons of the king have arrived! It is just as your servant said.”'),
  ('BSB', '2 Samuel', 10, 13, 36, 'And as he finished speaking, the sons of the king came in, wailing loudly. Then the king and all his servants also wept very bitterly.'),
  ('BSB', '2 Samuel', 10, 13, 37, 'Now Absalom fled and went to Talmai son of Ammihud, the king of Geshur. But David mourned for his son every day.'),
  ('BSB', '2 Samuel', 10, 13, 38, 'After Absalom had fled and gone to Geshur, he stayed there three years.'),
  ('BSB', '2 Samuel', 10, 13, 39, 'And King David longed to go to Absalom, for he had been consoled over Amnon’s death.'),
  ('BSB', '2 Samuel', 10, 14, 1, 'Now Joab son of Zeruiah perceived that the king’s heart longed for Absalom.'),
  ('BSB', '2 Samuel', 10, 14, 2, 'So Joab sent to Tekoa to bring a wise woman from there. He told her, “Please pretend to be a mourner; put on clothes for mourning and do not anoint yourself with oil. Act like a woman who has mourned for the dead a long time.'),
  ('BSB', '2 Samuel', 10, 14, 3, 'Then go to the king and speak these words to him.” And Joab put the words in her mouth.'),
  ('BSB', '2 Samuel', 10, 14, 4, 'When the woman from Tekoa went to the king, she fell facedown in homage and said, “Help me, O king!”'),
  ('BSB', '2 Samuel', 10, 14, 5, '“What troubles you?” the king asked her. “Indeed,” she said, “I am a widow, for my husband is dead.'),
  ('BSB', '2 Samuel', 10, 14, 6, 'And your maidservant had two sons who were fighting in the field with no one to separate them, and one struck the other and killed him.'),
  ('BSB', '2 Samuel', 10, 14, 7, 'Now the whole clan has risen up against your maidservant and said, ‘Hand over the one who struck down his brother, that we may put him to death for the life of the brother whom he killed. Then we will cut off the heir as well!’ So they would extinguish my one remaining ember by not preserving my husband’s name or posterity on the earth.”'),
  ('BSB', '2 Samuel', 10, 14, 8, '“Go home,” the king said to the woman, “and I will give orders on your behalf.”'),
  ('BSB', '2 Samuel', 10, 14, 9, 'But the woman of Tekoa said to the king, “My lord the king, may any blame be on me and on my father’s house, and may the king and his throne be guiltless.”'),
  ('BSB', '2 Samuel', 10, 14, 10, '“If anyone speaks to you,” said the king, “bring him to me, and he will not trouble you again!”'),
  ('BSB', '2 Samuel', 10, 14, 11, '“Please,” she replied, “may the king invoke the LORD your God to prevent the avenger of blood from increasing the devastation, so that my son may not be destroyed!” “As surely as the LORD lives,” he vowed, “not a hair of your son’s head will fall to the ground.”'),
  ('BSB', '2 Samuel', 10, 14, 12, 'Then the woman said, “Please, may your servant speak a word to my lord the king?” “Speak,” he replied.'),
  ('BSB', '2 Samuel', 10, 14, 13, 'The woman asked, “Why have you devised a thing like this against the people of God? When the king says this, does he not convict himself, since he has not brought back his own banished son?'),
  ('BSB', '2 Samuel', 10, 14, 14, 'For surely we will die and be like water poured out on the ground, which cannot be recovered. Yet God does not take away a life; but He devises ways that the banished one may not be cast out from Him.'),
  ('BSB', '2 Samuel', 10, 14, 15, 'Now therefore, I have come to present this matter to my lord the king because the people have made me afraid. Your servant thought, ‘I will speak to the king. Perhaps he will grant the request of his maidservant.'),
  ('BSB', '2 Samuel', 10, 14, 16, 'For the king will hear and deliver his maidservant from the hand of the man who would cut off both me and my son from God’s inheritance.’'),
  ('BSB', '2 Samuel', 10, 14, 17, 'And now your servant says, ‘May the word of my lord the king bring me rest, for my lord the king is able to discern good and evil, just like the angel of God. May the LORD your God be with you.’”'),
  ('BSB', '2 Samuel', 10, 14, 18, 'Then the king said to the woman, “I am going to ask you something; do not conceal it from me!” “Let my lord the king speak,” she replied.'),
  ('BSB', '2 Samuel', 10, 14, 19, 'So the king asked, “Is the hand of Joab behind all this?” The woman answered, “As surely as you live, my lord the king, no one can turn to the right or to the left from anything that my lord the king says. Yes, your servant Joab is the one who gave me orders; he told your maidservant exactly what to say.'),
  ('BSB', '2 Samuel', 10, 14, 20, 'Joab your servant has done this to bring about this change of affairs, but my lord has wisdom like the wisdom of the angel of God, to know everything that happens in the land.”'),
  ('BSB', '2 Samuel', 10, 14, 21, 'Then the king said to Joab, “I hereby grant this request. Go, bring back the young man Absalom.”'),
  ('BSB', '2 Samuel', 10, 14, 22, 'Joab fell facedown in homage and blessed the king. “Today,” said Joab, “your servant knows that he has found favor with you, my lord the king, because the king has granted his request.”'),
  ('BSB', '2 Samuel', 10, 14, 23, 'So Joab got up, went to Geshur, and brought Absalom to Jerusalem.'),
  ('BSB', '2 Samuel', 10, 14, 24, 'But the king added, “He may return to his house, but he must not see my face.” So Absalom returned to his own house, but he did not see the king.'),
  ('BSB', '2 Samuel', 10, 14, 25, 'Now there was not a man in all Israel as handsome and highly praised as Absalom. From the sole of his foot to the top of his head, he did not have a single flaw.'),
  ('BSB', '2 Samuel', 10, 14, 26, 'And when he cut the hair of his head—he shaved it every year because his hair got so heavy—he would weigh it out to be two hundred shekels, according to the royal standard.'),
  ('BSB', '2 Samuel', 10, 14, 27, 'Three sons were born to Absalom, and a daughter named Tamar, who was a beautiful woman.'),
  ('BSB', '2 Samuel', 10, 14, 28, 'Now Absalom lived in Jerusalem two years without seeing the face of the king.'),
  ('BSB', '2 Samuel', 10, 14, 29, 'Then he sent for Joab to send him to the king, but Joab refused to come to him. So Absalom sent a second time, but Joab still would not come.'),
  ('BSB', '2 Samuel', 10, 14, 30, 'Then Absalom said to his servants, “Look, Joab’s field is next to mine, and he has barley there. Go and set it on fire!” And Absalom’s servants set the field on fire.'),
  ('BSB', '2 Samuel', 10, 14, 31, 'Then Joab came to Absalom’s house and demanded, “Why did your servants set my field on fire?”'),
  ('BSB', '2 Samuel', 10, 14, 32, '“Look,” said Absalom, “I sent for you and said, ‘Come here. I want to send you to the king to ask: Why have I come back from Geshur? It would be better for me if I were still there.’ So now, let me see the king’s face, and if there is iniquity in me, let him kill me.”'),
  ('BSB', '2 Samuel', 10, 14, 33, 'So Joab went and told the king, and David summoned Absalom, who came to him and bowed facedown before him. Then the king kissed Absalom.'),
  ('BSB', '2 Samuel', 10, 15, 1, 'Some time later, Absalom provided for himself a chariot with horses and fifty men to run ahead of him.'),
  ('BSB', '2 Samuel', 10, 15, 2, 'He would get up early and stand beside the road leading to the city gate. Whenever anyone had a grievance to bring before the king for a decision, Absalom would call out and ask, “What city are you from?” And if he replied, “Your servant is from one of the tribes of Israel,”'),
  ('BSB', '2 Samuel', 10, 15, 3, 'Absalom would say, “Look, your claims are good and right, but the king has no deputy to hear you.”'),
  ('BSB', '2 Samuel', 10, 15, 4, 'And he would add, “If only someone would appoint me judge in the land, then everyone with a grievance or dispute could come to me, and I would give him justice.”'),
  ('BSB', '2 Samuel', 10, 15, 5, 'Also, when anyone approached to bow down to him, Absalom would reach out his hand, take hold of him, and kiss him.'),
  ('BSB', '2 Samuel', 10, 15, 6, 'Absalom did this to all the Israelites who came to the king for justice. In this way he stole the hearts of the men of Israel.'),
  ('BSB', '2 Samuel', 10, 15, 7, 'After four years had passed, Absalom said to the king, “Please let me go to Hebron to fulfill a vow I have made to the LORD.'),
  ('BSB', '2 Samuel', 10, 15, 8, 'For your servant made a vow while dwelling in Geshur of Aram, saying: ‘If indeed the LORD brings me back to Jerusalem, I will worship the LORD in Hebron.’”'),
  ('BSB', '2 Samuel', 10, 15, 9, '“Go in peace,” said the king. So Absalom got up and went to Hebron.'),
  ('BSB', '2 Samuel', 10, 15, 10, 'Then Absalom sent spies throughout the tribes of Israel with this message: “When you hear the sound of the horn, you are to say, ‘Absalom reigns in Hebron!’”');
insert into control_room_bible (version, book, book_num, chapter, verse, text) values
  ('BSB', '2 Samuel', 10, 15, 11, 'Two hundred men from Jerusalem accompanied Absalom. They had been invited as guests and they went along innocently, for they knew nothing about the matter.'),
  ('BSB', '2 Samuel', 10, 15, 12, 'While Absalom was offering the sacrifices, he sent for Ahithophel the Gilonite, David’s counselor, to come from his hometown of Giloh. So the conspiracy gained strength, and Absalom’s following kept increasing.'),
  ('BSB', '2 Samuel', 10, 15, 13, 'Then a messenger came to David and reported, “The hearts of the men of Israel are with Absalom.”'),
  ('BSB', '2 Samuel', 10, 15, 14, 'And David said to all the servants with him in Jerusalem, “Arise and let us flee, or we will not escape from Absalom! We must leave quickly, or he will soon overtake us, heap disaster on us, and put the city to the sword.”'),
  ('BSB', '2 Samuel', 10, 15, 15, 'The king’s servants replied, “Whatever our lord the king decides, we are your servants.”'),
  ('BSB', '2 Samuel', 10, 15, 16, 'Then the king set out, and his entire household followed him. But he left behind ten concubines to take care of the palace.'),
  ('BSB', '2 Samuel', 10, 15, 17, 'So the king set out with all the people following him. He stopped at the last house,'),
  ('BSB', '2 Samuel', 10, 15, 18, 'and all his servants marched past him—all the Cherethites and Pelethites, and six hundred Gittites who had followed him from Gath.'),
  ('BSB', '2 Samuel', 10, 15, 19, 'Then the king said to Ittai the Gittite, “Why should you also go with us? Go back and stay with the new king, since you are both a foreigner and an exile from your homeland.'),
  ('BSB', '2 Samuel', 10, 15, 20, 'In fact, you arrived only yesterday; should I make you wander around with us today while I do not know where I am going? Go back and take your brothers with you. May the LORD show you loving devotion and faithfulness.”'),
  ('BSB', '2 Samuel', 10, 15, 21, 'But Ittai answered the king, “As surely as the LORD lives, and as my lord the king lives, wherever my lord the king may be, whether it means life or death, there will your servant be!”'),
  ('BSB', '2 Samuel', 10, 15, 22, '“March on then,” said David to Ittai. So Ittai the Gittite marched past with all his men and all the little ones who were with him.'),
  ('BSB', '2 Samuel', 10, 15, 23, 'Everyone in the countryside was weeping loudly as all the people passed by. And as the king crossed the Kidron Valley, all the people also passed toward the way of the wilderness.'),
  ('BSB', '2 Samuel', 10, 15, 24, 'Zadok was also there, and all the Levites with him were carrying the ark of the covenant of God. And they set down the ark of God, and Abiathar offered sacrifices until the people had passed out of the city.'),
  ('BSB', '2 Samuel', 10, 15, 25, 'Then the king said to Zadok, “Return the ark of God to the city. If I find favor in the eyes of the LORD, He will bring me back and let me see both it and His dwelling place again.'),
  ('BSB', '2 Samuel', 10, 15, 26, 'But if He should say, ‘I do not delight in you,’ then here I am; let Him do to me whatever seems good to Him.”'),
  ('BSB', '2 Samuel', 10, 15, 27, 'The king also said to Zadok the priest, “Are you not a seer? Return to the city in peace—you with your son Ahimaaz, and Abiathar with his son Jonathan.'),
  ('BSB', '2 Samuel', 10, 15, 28, 'See, I will wait at the fords of the wilderness until word comes from you to inform me.”'),
  ('BSB', '2 Samuel', 10, 15, 29, 'So Zadok and Abiathar returned the ark of God to Jerusalem and stayed there.'),
  ('BSB', '2 Samuel', 10, 15, 30, 'But David continued up the Mount of Olives, weeping as he went up. His head was covered, and he was walking barefoot. And all the people with him covered their heads and went up, weeping as they went.'),
  ('BSB', '2 Samuel', 10, 15, 31, 'Now someone told David: “Ahithophel is among the conspirators with Absalom.” So David pleaded, “O LORD, please turn the counsel of Ahithophel into foolishness!”'),
  ('BSB', '2 Samuel', 10, 15, 32, 'When David came to the summit, where he used to worship God, Hushai the Archite was there to meet him with his robe torn and dust on his head.'),
  ('BSB', '2 Samuel', 10, 15, 33, 'David said to him, “If you go on with me, you will be a burden to me.'),
  ('BSB', '2 Samuel', 10, 15, 34, 'But you can thwart the counsel of Ahithophel for me if you return to the city and say to Absalom: ‘I will be your servant, my king; in the past I was your father’s servant, but now I will be your servant.’'),
  ('BSB', '2 Samuel', 10, 15, 35, 'Will not Zadok and Abiathar the priests be there with you? Report to them everything you hear from the king’s palace.'),
  ('BSB', '2 Samuel', 10, 15, 36, 'Indeed, their two sons, Ahimaaz son of Zadok and Jonathan son of Abiathar, are there with them. Send them to me with everything you hear.”'),
  ('BSB', '2 Samuel', 10, 15, 37, 'So David’s friend Hushai arrived in Jerusalem just as Absalom was entering the city.'),
  ('BSB', '2 Samuel', 10, 16, 1, 'When David had gone a little beyond the summit, Ziba the servant of Mephibosheth was there to meet him. He had a pair of saddled donkeys loaded with two hundred loaves of bread, a hundred clusters of raisins, a hundred summer fruits, and a skin of wine.'),
  ('BSB', '2 Samuel', 10, 16, 2, '“Why do you have these?” asked the king. Ziba replied, “The donkeys are for the king’s household to ride, the bread and summer fruit are for the young men to eat, and the wine is to refresh those who become exhausted in the wilderness.”'),
  ('BSB', '2 Samuel', 10, 16, 3, '“Where is your master’s grandson?” asked the king. And Ziba answered, “Indeed, he is staying in Jerusalem, for he has said, ‘Today, the house of Israel will restore to me the kingdom of my grandfather.’”'),
  ('BSB', '2 Samuel', 10, 16, 4, 'So the king said to Ziba, “All that belongs to Mephibosheth is now yours!” “I humbly bow before you,” said Ziba. “May I find favor in your eyes, my lord the king!”'),
  ('BSB', '2 Samuel', 10, 16, 5, 'As King David approached Bahurim, a man from the family of the house of Saul was just coming out. His name was Shimei son of Gera, and as he approached, he kept yelling out curses.'),
  ('BSB', '2 Samuel', 10, 16, 6, 'He threw stones at David and at all the servants of the king, though the troops and all the mighty men were on David’s right and left.'),
  ('BSB', '2 Samuel', 10, 16, 7, 'And as he yelled curses, Shimei said, “Get out, get out, you worthless man of bloodshed!'),
  ('BSB', '2 Samuel', 10, 16, 8, 'The LORD has paid you back for all the blood of the house of Saul, in whose place you have reigned, and the LORD has delivered the kingdom into the hand of your son Absalom. See, you have come to ruin because you are a man of bloodshed!”'),
  ('BSB', '2 Samuel', 10, 16, 9, 'Then Abishai son of Zeruiah said to the king, “Why should this dead dog curse my lord the king? Let me go over and cut off his head!”'),
  ('BSB', '2 Samuel', 10, 16, 10, 'But the king replied, “What have I to do with you, O sons of Zeruiah? If he curses me because the LORD told him, ‘Curse David,’ who can ask, ‘Why did you do this?’”'),
  ('BSB', '2 Samuel', 10, 16, 11, 'Then David said to Abishai and to all his servants, “Behold, my own son, my own flesh and blood, seeks my life. How much more, then, this Benjamite! Leave him alone and let him curse me, for the LORD has told him so.'),
  ('BSB', '2 Samuel', 10, 16, 12, 'Perhaps the LORD will see my affliction and repay me with good for the cursing I receive today.”'),
  ('BSB', '2 Samuel', 10, 16, 13, 'So David and his men proceeded along the road as Shimei went along the ridge of the hill opposite him. As Shimei went, he yelled curses, threw stones, and flung dust at David.'),
  ('BSB', '2 Samuel', 10, 16, 14, 'Finally, the king and all the people with him arrived, exhausted. And there he refreshed himself.'),
  ('BSB', '2 Samuel', 10, 16, 15, 'Then Absalom and all the men of Israel came to Jerusalem, and Ahithophel was with him.'),
  ('BSB', '2 Samuel', 10, 16, 16, 'And David’s friend Hushai the Archite went to Absalom and said to him, “Long live the king! Long live the king!”'),
  ('BSB', '2 Samuel', 10, 16, 17, '“Is this the loyalty you show your friend?” Absalom replied. “Why did you not go with your friend?”'),
  ('BSB', '2 Samuel', 10, 16, 18, '“Not at all,” Hushai answered. “For the one chosen by the LORD, by the people, and by all the men of Israel—his I will be, and with him I will remain.'),
  ('BSB', '2 Samuel', 10, 16, 19, 'Furthermore, whom should I serve if not the son? As I served in your father’s presence, so also I will serve in yours.”'),
  ('BSB', '2 Samuel', 10, 16, 20, 'Then Absalom said to Ahithophel, “Give me counsel. What should we do?”'),
  ('BSB', '2 Samuel', 10, 16, 21, 'Ahithophel replied, “Sleep with your father’s concubines, whom he has left to keep the palace. When all Israel hears that you have become a stench to your father, then the hands of all who are with you will be strengthened.”'),
  ('BSB', '2 Samuel', 10, 16, 22, 'So they pitched a tent for Absalom on the roof, and he slept with his father’s concubines in the sight of all Israel.'),
  ('BSB', '2 Samuel', 10, 16, 23, 'Now in those days the advice of Ahithophel was like the consultation of the word of God. Such was the regard that both David and Absalom had for Ahithophel’s advice.'),
  ('BSB', '2 Samuel', 10, 17, 1, 'Furthermore, Ahithophel said to Absalom, “Let me choose twelve thousand men and set out tonight in pursuit of David.'),
  ('BSB', '2 Samuel', 10, 17, 2, 'I will attack him while he is weak and weary; I will throw him into a panic, and all the people with him will flee; I will strike down only the king'),
  ('BSB', '2 Samuel', 10, 17, 3, 'and bring all the people back to you as a bride returning to her husband. You seek the life of only one man; then all the people will be at peace.”'),
  ('BSB', '2 Samuel', 10, 17, 4, 'This proposal seemed good to Absalom and all the elders of Israel.'),
  ('BSB', '2 Samuel', 10, 17, 5, 'Then Absalom said, “Summon Hushai the Archite as well, and let us hear what he too has to say.”'),
  ('BSB', '2 Samuel', 10, 17, 6, 'So Hushai came to Absalom, who told him, “Ahithophel has spoken this proposal. Should we carry it out? If not, what do you say?”'),
  ('BSB', '2 Samuel', 10, 17, 7, 'Hushai replied, “This time the advice of Ahithophel is not sound.”'),
  ('BSB', '2 Samuel', 10, 17, 8, 'He continued, “You know your father and his men. They are mighty men, and as fierce as a wild bear robbed of her cubs. Moreover, your father is a man of war who will not spend the night with the troops.'),
  ('BSB', '2 Samuel', 10, 17, 9, 'Surely by now he is hiding in a cave or some other location. If some of your troops fall first, whoever hears of it will say, ‘There has been a slaughter among the troops who follow Absalom.’'),
  ('BSB', '2 Samuel', 10, 17, 10, 'Then even the most valiant soldier with the heart of a lion will melt with fear, because all Israel knows that your father is a mighty man who has valiant men with him.'),
  ('BSB', '2 Samuel', 10, 17, 11, 'Instead, I advise that all Israel from Dan to Beersheba—a multitude like the sand on the seashore—be gathered to you, and that you yourself lead them into battle.'),
  ('BSB', '2 Samuel', 10, 17, 12, 'Then we will attack David wherever we find him, and we will descend on him like dew on the ground. And of all the men with him, not even one will remain.'),
  ('BSB', '2 Samuel', 10, 17, 13, 'If he retreats to a city, all Israel will bring ropes to that city, and we will drag it down to the valley until not even a pebble can be found.”'),
  ('BSB', '2 Samuel', 10, 17, 14, 'Then Absalom and all the men of Israel said, “The advice of Hushai the Archite is better than that of Ahithophel.” For the LORD had purposed to thwart the good counsel of Ahithophel in order to bring disaster on Absalom.'),
  ('BSB', '2 Samuel', 10, 17, 15, 'So Hushai told Zadok and Abiathar, the priests, “This is what Ahithophel has advised Absalom and the elders of Israel, and this is what I have advised.'),
  ('BSB', '2 Samuel', 10, 17, 16, 'Now send quickly and tell David, ‘Do not spend the night at the fords of the wilderness, but be sure to cross over. Otherwise the king and all the people with him will be swallowed up.’”'),
  ('BSB', '2 Samuel', 10, 17, 17, 'Now Jonathan and Ahimaaz were staying at En-rogel, where a servant girl would come and pass along information to them. They in turn would go and inform King David, for they dared not be seen entering the city.'),
  ('BSB', '2 Samuel', 10, 17, 18, 'But a young man did see them and told Absalom. So the two left quickly and came to the house of a man in Bahurim. He had a well in his courtyard, and they climbed down into it.'),
  ('BSB', '2 Samuel', 10, 17, 19, 'Then the man’s wife took a covering and spread it over the mouth of the well, scattering grain over it so nobody would know a thing.'),
  ('BSB', '2 Samuel', 10, 17, 20, 'When Absalom’s servants came to the woman at the house, they asked, “Where are Ahimaaz and Jonathan?” “They have crossed over the brook,” she replied. The men searched but did not find them, so they returned to Jerusalem.'),
  ('BSB', '2 Samuel', 10, 17, 21, 'After the men had gone, Ahimaaz and Jonathan climbed up out of the well and went to inform King David, saying, “Get up and cross over the river at once, for Ahithophel has given this advice against you.”'),
  ('BSB', '2 Samuel', 10, 17, 22, 'So David and all the people with him got up and crossed the Jordan. By daybreak, there was no one left who had not crossed the Jordan.'),
  ('BSB', '2 Samuel', 10, 17, 23, 'When Ahithophel saw that his advice had not been followed, he saddled his donkey and set out for his house in his hometown. He put his affairs in order and hanged himself. So he died and was buried in his father’s tomb.'),
  ('BSB', '2 Samuel', 10, 17, 24, 'Then David went to Mahanaim, and Absalom crossed the Jordan with all the men of Israel.'),
  ('BSB', '2 Samuel', 10, 17, 25, 'Absalom had appointed Amasa over the army in place of Joab. Amasa was the son of a man named Ithra, the Ishmaelite who had married Abigail, the daughter of Nahash and sister of Zeruiah the mother of Joab.'),
  ('BSB', '2 Samuel', 10, 17, 26, 'So the Israelites and Absalom camped in the land of Gilead.'),
  ('BSB', '2 Samuel', 10, 17, 27, 'When David came to Mahanaim, he was met by Shobi son of Nahash from Rabbah of the Ammonites, Machir son of Ammiel from Lo-debar, and Barzillai the Gileadite from Rogelim.'),
  ('BSB', '2 Samuel', 10, 17, 28, 'They brought beds, basins, and earthen vessels, as well as wheat, barley, flour, roasted grain, beans, lentils,'),
  ('BSB', '2 Samuel', 10, 17, 29, 'honey, curds, sheep, and cheese from the herd for David and his people to eat. For they said, “The people have become hungry, exhausted, and thirsty in the wilderness.”'),
  ('BSB', '2 Samuel', 10, 18, 1, 'Then David reviewed his troops and appointed over them commanders of hundreds and of thousands.'),
  ('BSB', '2 Samuel', 10, 18, 2, 'He sent out the troops, a third under Joab, a third under Joab’s brother Abishai son of Zeruiah, and a third under Ittai the Gittite. And the king said to the troops, “I will surely march out with you as well.”'),
  ('BSB', '2 Samuel', 10, 18, 3, 'But the people pleaded, “You must not go out! For if we have to flee, they will pay no attention to us. Even if half of us die, they will not care; but you are worth ten thousand of us. It is better for now if you support us from the city.”'),
  ('BSB', '2 Samuel', 10, 18, 4, '“I will do whatever seems best to you,” the king replied. So he stood beside the gate, while all the troops marched out by hundreds and by thousands.'),
  ('BSB', '2 Samuel', 10, 18, 5, 'Now the king had commanded Joab, Abishai, and Ittai, “Treat the young man Absalom gently for my sake.” And all the people heard the king’s orders to each of the commanders regarding Absalom.'),
  ('BSB', '2 Samuel', 10, 18, 6, 'So David’s army marched into the field to engage Israel in the battle, which took place in the forest of Ephraim.'),
  ('BSB', '2 Samuel', 10, 18, 7, 'There the people of Israel were defeated by David’s servants, and the slaughter was great that day—twenty thousand men.'),
  ('BSB', '2 Samuel', 10, 18, 8, 'The battle spread over the whole countryside, and that day the forest devoured more people than the sword.'),
  ('BSB', '2 Samuel', 10, 18, 9, 'Now Absalom was riding on his mule when he met the servants of David, and as the mule went under the thick branches of a large oak, Absalom’s head was caught fast in the tree. The mule under him kept going, so that he was suspended in midair.'),
  ('BSB', '2 Samuel', 10, 18, 10, 'When one of the men saw this, he told Joab, “I just saw Absalom hanging in an oak tree!”'),
  ('BSB', '2 Samuel', 10, 18, 11, '“You just saw him!” Joab exclaimed. “Why did you not strike him to the ground right there? I would have given you ten shekels of silver and a warrior’s belt!”'),
  ('BSB', '2 Samuel', 10, 18, 12, 'The man replied, “Even if a thousand shekels of silver were weighed out into my hands, I would not raise my hand against the son of the king. For we heard the king command you and Abishai and Ittai, ‘Protect the young man Absalom for my sake.’'),
  ('BSB', '2 Samuel', 10, 18, 13, 'If I had jeopardized my own life—and nothing is hidden from the king—you would have abandoned me.”'),
  ('BSB', '2 Samuel', 10, 18, 14, 'But Joab declared, “I am not going to wait like this with you!” And he took three spears in his hand and thrust them through the heart of Absalom while he was still alive in the oak tree.'),
  ('BSB', '2 Samuel', 10, 18, 15, 'And ten young men who carried Joab’s armor surrounded Absalom, struck him, and killed him.'),
  ('BSB', '2 Samuel', 10, 18, 16, 'Then Joab blew the ram’s horn, and the troops broke off their pursuit of Israel because Joab had restrained them.'),
  ('BSB', '2 Samuel', 10, 18, 17, 'They took Absalom, cast him into a large pit in the forest, and piled a huge mound of stones over him. Meanwhile, all the Israelites fled, each to his home.'),
  ('BSB', '2 Samuel', 10, 18, 18, 'During his lifetime, Absalom had set up for himself a pillar in the King’s Valley, for he had said, “I have no son to preserve the memory of my name.” So he gave the pillar his name, and to this day it is called Absalom’s Monument.'),
  ('BSB', '2 Samuel', 10, 18, 19, 'Then Ahimaaz son of Zadok said, “Please let me run and tell the king the good news that the LORD has avenged him of his enemies.”'),
  ('BSB', '2 Samuel', 10, 18, 20, 'But Joab replied, “You are not the man to take good news today. You may do it another day, but you must not do so today, because the king’s son is dead.”'),
  ('BSB', '2 Samuel', 10, 18, 21, 'So Joab said to a Cushite, “Go, tell the king what you have seen.” The Cushite bowed to Joab and took off running.'),
  ('BSB', '2 Samuel', 10, 18, 22, 'Ahimaaz son of Zadok, however, persisted and said to Joab, “Regardless of whatever may happen, please let me also run behind the Cushite!” “My son,” Joab replied, “why do you want to run, since you will not receive a reward?”'),
  ('BSB', '2 Samuel', 10, 18, 23, '“No matter what, I want to run!” he replied. “Then run!” Joab told him. So Ahimaaz ran by way of the plain and outran the Cushite.'),
  ('BSB', '2 Samuel', 10, 18, 24, 'Now David was sitting between the two gates when the watchman went up to the roof of the gateway by the wall, looked out, and saw a man running alone.'),
  ('BSB', '2 Samuel', 10, 18, 25, 'So he called out and told the king. “If he is alone,” the king replied, “he bears good news.” As the first runner drew near,'),
  ('BSB', '2 Samuel', 10, 18, 26, 'the watchman saw another man running, and he called out to the gatekeeper, “Look! Another man is running alone!” “This one also brings good news,” said the king.'),
  ('BSB', '2 Samuel', 10, 18, 27, 'The watchman said, “The first man appears to me to be running like Ahimaaz son of Zadok.” “This is a good man,” said the king. “He comes with good news.”'),
  ('BSB', '2 Samuel', 10, 18, 28, 'Then Ahimaaz called out to the king, “All is well!” And he bowed facedown before the king. He continued, “Blessed be the LORD your God! He has delivered up the men who raised their hands against my lord the king.”'),
  ('BSB', '2 Samuel', 10, 18, 29, 'The king asked, “Is the young man Absalom all right?” And Ahimaaz replied, “When Joab sent the king’s servant and your servant, I saw a great tumult, but I do not know what it was.”'),
  ('BSB', '2 Samuel', 10, 18, 30, '“Move aside,” said the king, “and stand here.” So he stepped aside.'),
  ('BSB', '2 Samuel', 10, 18, 31, 'Just then the Cushite came and said, “May my lord the king hear the good news: Today the LORD has avenged you of all who rose up against you!”'),
  ('BSB', '2 Samuel', 10, 18, 32, 'The king asked the Cushite, “Is the young man Absalom all right?” And the Cushite replied, “May what has become of the young man happen to the enemies of my lord the king and to all who rise up against you to harm you.”'),
  ('BSB', '2 Samuel', 10, 18, 33, 'The king was shaken and went up to the gate chamber and wept. And as he walked, he cried out, “O my son Absalom! My son, my son Absalom! If only I had died instead of you, O Absalom, my son, my son!”'),
  ('BSB', '2 Samuel', 10, 19, 1, 'Then it was reported to Joab, “The king is weeping and mourning over Absalom.”'),
  ('BSB', '2 Samuel', 10, 19, 2, 'And that day’s victory was turned into mourning for all the people, because on that day they were told, “The king is grieving over his son.”'),
  ('BSB', '2 Samuel', 10, 19, 3, 'So they returned to the city quietly that day, as people steal away in humiliation after fleeing a battle.'),
  ('BSB', '2 Samuel', 10, 19, 4, 'But the king covered his face and cried out at the top of his voice, “O my son Absalom! O Absalom, my son, my son!”'),
  ('BSB', '2 Samuel', 10, 19, 5, 'Then Joab went into the house and said to the king, “Today you have disgraced all your servants who have saved your life and the lives of your sons and daughters, of your wives, and of your concubines.'),
  ('BSB', '2 Samuel', 10, 19, 6, 'You love those who hate you and hate those who love you! For you have made it clear today that the commanders and soldiers mean nothing to you. I know today that if Absalom were alive and all of us were dead, it would have pleased you!'),
  ('BSB', '2 Samuel', 10, 19, 7, 'Now therefore get up! Go out and speak comfort to your servants, for I swear by the LORD that if you do not go out, not a man will remain with you tonight. This will be worse for you than all the adversity that has befallen you from your youth until now!”'),
  ('BSB', '2 Samuel', 10, 19, 8, 'So the king got up and sat in the gate, and all the people were told: “Behold, the king is sitting in the gate.” So they all came before the king. Meanwhile, the Israelites had fled, each man to his home.'),
  ('BSB', '2 Samuel', 10, 19, 9, 'And all the people throughout the tribes of Israel were arguing, “The king rescued us from the hand of our enemies and delivered us from the hand of the Philistines, but now he has fled the land because of Absalom.'),
  ('BSB', '2 Samuel', 10, 19, 10, 'But Absalom, the man we anointed over us, has died in battle. So why do you say nothing about restoring the king?”'),
  ('BSB', '2 Samuel', 10, 19, 11, 'Then King David sent this message to Zadok and Abiathar, the priests: “Say to the elders of Judah, ‘Why should you be the last to restore the king to his palace, since the talk of all Israel has reached the king at his quarters?'),
  ('BSB', '2 Samuel', 10, 19, 12, 'You are my brothers, my own flesh and blood. So why should you be the last to restore the king?’'),
  ('BSB', '2 Samuel', 10, 19, 13, 'And say to Amasa, ‘Aren’t you my flesh and blood? May God punish me, and ever so severely, if from this time you are not the commander of my army in place of Joab!’”'),
  ('BSB', '2 Samuel', 10, 19, 14, 'So he swayed the hearts of all the men of Judah as though they were one man, and they sent word to the king: “Return, you and all your servants.”'),
  ('BSB', '2 Samuel', 10, 19, 15, 'So the king returned, and when he arrived at the Jordan, the men of Judah came to Gilgal to meet him and escort him across the Jordan.'),
  ('BSB', '2 Samuel', 10, 19, 16, 'Then Shimei son of Gera, a Benjamite from Bahurim, hurried down with the men of Judah to meet King David,'),
  ('BSB', '2 Samuel', 10, 19, 17, 'along with a thousand men of Benjamin, as well as Ziba the steward of the house of Saul and his fifteen sons and twenty servants. They rushed down to the Jordan before the king'),
  ('BSB', '2 Samuel', 10, 19, 18, 'and crossed at the ford to carry over the king’s household and to do what was good in his sight. When Shimei son of Gera crossed the Jordan, he fell down before the king'),
  ('BSB', '2 Samuel', 10, 19, 19, 'and said, “My lord, do not hold me guilty, and do not remember your servant’s wrongdoing on the day my lord the king left Jerusalem. May the king not take it to heart.'),
  ('BSB', '2 Samuel', 10, 19, 20, 'For your servant knows that I have sinned, so here I am today as the first of all the house of Joseph to come down to meet my lord the king.”'),
  ('BSB', '2 Samuel', 10, 19, 21, 'But Abishai son of Zeruiah said, “Shouldn’t Shimei be put to death for this, because he cursed the LORD’s anointed?”'),
  ('BSB', '2 Samuel', 10, 19, 22, 'And David replied, “Sons of Zeruiah, what have I to do with you, that you should be my adversaries today? Should any man be put to death in Israel today? Am I not indeed aware that today I am king over Israel?”'),
  ('BSB', '2 Samuel', 10, 19, 23, 'So the king said to Shimei, “You shall not die.” And the king swore an oath to him.'),
  ('BSB', '2 Samuel', 10, 19, 24, 'Then Mephibosheth, Saul’s grandson, went down to meet the king. He had not cared for his feet or trimmed his mustache or washed his clothes from the day the king had left until the day he returned safely.'),
  ('BSB', '2 Samuel', 10, 19, 25, 'And he came from Jerusalem to meet the king, who asked him, “Mephibosheth, why did you not go with me?”'),
  ('BSB', '2 Samuel', 10, 19, 26, '“My lord the king,” he replied, “because I am lame, I said, ‘I will have my donkey saddled so that I may ride on it and go with the king.’ But my servant Ziba deceived me,'),
  ('BSB', '2 Samuel', 10, 19, 27, 'and he has slandered your servant to my lord the king. Yet my lord the king is like the angel of God, so do what is good in your eyes.'),
  ('BSB', '2 Samuel', 10, 19, 28, 'For all the house of my grandfather deserves death from my lord the king, yet you have set your servant among those who eat at your table. What further right, then, do I have to keep appealing to the king?”'),
  ('BSB', '2 Samuel', 10, 19, 29, 'The king replied, “Why say any more? I hereby declare that you and Ziba are to divide the land.”'),
  ('BSB', '2 Samuel', 10, 19, 30, 'And Mephibosheth said to the king, “Instead, since my lord the king has safely come to his own house, let Ziba take it all!”'),
  ('BSB', '2 Samuel', 10, 19, 31, 'Now Barzillai the Gileadite had come down from Rogelim to cross the Jordan with the king and send him on his way from there.'),
  ('BSB', '2 Samuel', 10, 19, 32, 'Barzillai was quite old, eighty years of age, and since he was a very wealthy man, he had provided for the king while he stayed in Mahanaim.'),
  ('BSB', '2 Samuel', 10, 19, 33, 'The king said to Barzillai, “Cross over with me, and I will provide for you at my side in Jerusalem.”'),
  ('BSB', '2 Samuel', 10, 19, 34, 'But Barzillai replied, “How many years of my life remain, that I should go up to Jerusalem with the king?'),
  ('BSB', '2 Samuel', 10, 19, 35, 'I am now eighty years old. Can I discern what is good and what is not? Can your servant taste what he eats or drinks? Can I still hear the voice of singing men and women? Why should your servant be an added burden to my lord the king?'),
  ('BSB', '2 Samuel', 10, 19, 36, 'Your servant could go with the king only a short distance past the Jordan; why should the king repay me with such a reward?'),
  ('BSB', '2 Samuel', 10, 19, 37, 'Please let your servant return, that I may die in my own city near the tomb of my father and mother. But here is your servant Chimham. Let him cross over with my lord the king, and do for him what is good in your sight.”'),
  ('BSB', '2 Samuel', 10, 19, 38, 'The king replied, “Chimham will cross over with me, and I will do for him what seems good in your sight, and I will do for you whatever you desire of me.”'),
  ('BSB', '2 Samuel', 10, 19, 39, 'So all the people crossed the Jordan, and then the king crossed over. The king kissed Barzillai and blessed him, and Barzillai returned home.'),
  ('BSB', '2 Samuel', 10, 19, 40, 'Then the king went on to Gilgal, and Chimham crossed over with him. All the troops of Judah and half the troops of Israel escorted the king.'),
  ('BSB', '2 Samuel', 10, 19, 41, 'Soon all the men of Israel came to the king and asked, “Why did our brothers, the men of Judah, take you away secretly and bring the king and his household across the Jordan, together with all of David’s men?”'),
  ('BSB', '2 Samuel', 10, 19, 42, 'And all the men of Judah replied to the men of Israel, “We did this because the king is our relative. Why does this anger you? Have we ever eaten at the king’s expense or received anything for ourselves?”'),
  ('BSB', '2 Samuel', 10, 19, 43, '“We have ten shares in the king,” answered the men of Israel, “so we have more claim to David than you. Why then do you despise us? Were we not the first to speak of restoring our king?” But the men of Judah pressed even harder than the men of Israel.'),
  ('BSB', '2 Samuel', 10, 20, 1, 'Now a worthless man named Sheba son of Bichri, a Benjamite, happened to be there, and he blew the ram’s horn and shouted: “We have no share in David, no inheritance in Jesse’s son. Every man to his tent, O Israel!”'),
  ('BSB', '2 Samuel', 10, 20, 2, 'So all the men of Israel deserted David to follow Sheba son of Bichri. But the men of Judah stayed by their king all the way from the Jordan to Jerusalem.'),
  ('BSB', '2 Samuel', 10, 20, 3, 'When David returned to his palace in Jerusalem, he took the ten concubines he had left to care for the palace, and he placed them in a house under guard. He provided for them, but he no longer slept with them. They were confined until the day of their death, living as widows.'),
  ('BSB', '2 Samuel', 10, 20, 4, 'Then the king said to Amasa, “Summon the men of Judah to come to me within three days, and be here yourself.”'),
  ('BSB', '2 Samuel', 10, 20, 5, 'So Amasa went to summon Judah, but he took longer than the time allotted him.'),
  ('BSB', '2 Samuel', 10, 20, 6, 'And David said to Abishai, “Now Sheba the son of Bichri will do us more harm than Absalom. Take your lord’s servants and pursue him, or he will find fortified cities and elude us.”'),
  ('BSB', '2 Samuel', 10, 20, 7, 'So Joab’s men, along with the Cherethites, the Pelethites, and all the mighty men, marched out of Jerusalem in pursuit of Sheba son of Bichri.'),
  ('BSB', '2 Samuel', 10, 20, 8, 'And while they were at the great stone in Gibeon, Amasa joined them. Now Joab was dressed in military attire, with a dagger strapped to his belt. And as he stepped forward, he slipped the dagger from its sheath.'),
  ('BSB', '2 Samuel', 10, 20, 9, '“Are you well, my brother?” Joab asked Amasa. And with his right hand Joab grabbed Amasa by the beard to kiss him.'),
  ('BSB', '2 Samuel', 10, 20, 10, 'Amasa was not on guard against the dagger in Joab’s hand, and Joab stabbed him in the stomach and spilled out his intestines on the ground. And Joab did not need to strike him again, for Amasa was dead. Then Joab and his brother Abishai pursued Sheba son of Bichri.'),
  ('BSB', '2 Samuel', 10, 20, 11, 'One of Joab’s young men stood near Amasa and said, “Whoever favors Joab, and whoever is for David, let him follow Joab!”'),
  ('BSB', '2 Samuel', 10, 20, 12, 'But Amasa wallowed in his blood in the middle of the road, and when the man saw that all the troops were stopping there, he dragged the body off the road into a field and threw a garment over it.'),
  ('BSB', '2 Samuel', 10, 20, 13, 'As soon as Amasa’s body was removed from the road, all the men went on with Joab to pursue Sheba son of Bichri.'),
  ('BSB', '2 Samuel', 10, 20, 14, 'Sheba passed through all the tribes of Israel to Abel-beth-maacah and through the entire region of the Berites, who gathered together and followed him.'),
  ('BSB', '2 Samuel', 10, 20, 15, 'And Joab’s troops came and besieged Sheba in Abel-beth-maacah and built a siege ramp against the outer rampart of the city. As all the troops with Joab were battering the wall to topple it,'),
  ('BSB', '2 Samuel', 10, 20, 16, 'a wise woman called out from the city, “Listen! Listen! Please tell Joab to come here so that I may speak with him.”'),
  ('BSB', '2 Samuel', 10, 20, 17, 'When he had come near to her, the woman asked, “Are you Joab?” “I am,” he replied. “Listen to the words of your servant,” she said. “I am listening,” he answered.'),
  ('BSB', '2 Samuel', 10, 20, 18, 'Then the woman said, “Long ago they used to say, ‘Seek counsel at Abel,’ and that is how disputes were settled.'),
  ('BSB', '2 Samuel', 10, 20, 19, 'I am among the peaceable and faithful in Israel, but you are trying to destroy a city that is a mother in Israel. Why would you swallow up the LORD’s inheritance?”'),
  ('BSB', '2 Samuel', 10, 20, 20, '“Far be it!” Joab declared. “Far be it from me to swallow up or destroy!'),
  ('BSB', '2 Samuel', 10, 20, 21, 'That is not the case. But a man named Sheba son of Bichri, from the hill country of Ephraim, has lifted up his hand against the king, against David. Deliver him alone, and I will depart from the city.” “Look,” the woman replied, “his head will be thrown to you over the wall.”'),
  ('BSB', '2 Samuel', 10, 20, 22, 'Then the woman went to all the people with her wise counsel, and they cut off the head of Sheba son of Bichri and threw it to Joab. So he blew the ram’s horn and his men dispersed from the city, each to his own home. And Joab returned to the king in Jerusalem.'),
  ('BSB', '2 Samuel', 10, 20, 23, 'Now Joab was over the whole army of Israel; Benaiah son of Jehoiada was over the Cherethites and Pelethites;'),
  ('BSB', '2 Samuel', 10, 20, 24, 'Adoram was in charge of the forced labor; Jehoshaphat son of Ahilud was the recorder;'),
  ('BSB', '2 Samuel', 10, 20, 25, 'Sheva was the scribe; Zadok and Abiathar were priests;'),
  ('BSB', '2 Samuel', 10, 20, 26, 'and Ira the Jairite was David’s priest.'),
  ('BSB', '2 Samuel', 10, 21, 1, 'During the reign of David there was a famine for three successive years, and David sought the face of the LORD. And the LORD said, “It is because of the blood shed by Saul and his family, because he killed the Gibeonites.”'),
  ('BSB', '2 Samuel', 10, 21, 2, 'At this, David summoned the Gibeonites and spoke to them. (Now the Gibeonites were not Israelites, but a remnant of the Amorites. The Israelites had taken an oath concerning them, but in his zeal for Israel and Judah, Saul had sought to kill them.)'),
  ('BSB', '2 Samuel', 10, 21, 3, 'So David asked the Gibeonites, “What shall I do for you? How can I make amends so that you may bless the inheritance of the LORD?”'),
  ('BSB', '2 Samuel', 10, 21, 4, 'The Gibeonites said to him, “We need no silver or gold from Saul or his house, nor should you put to death anyone in Israel for us.” “Whatever you ask, I will do for you,” he replied.'),
  ('BSB', '2 Samuel', 10, 21, 5, 'And they answered the king, “As for the man who consumed us and plotted against us to exterminate us from existing within any border of Israel,'),
  ('BSB', '2 Samuel', 10, 21, 6, 'let seven of his male descendants be delivered to us so that we may hang them before the LORD at Gibeah of Saul, the chosen of the LORD.” “I will give them to you,” said the king.'),
  ('BSB', '2 Samuel', 10, 21, 7, 'Now the king spared Mephibosheth son of Jonathan, the son of Saul, because of the oath before the LORD between David and Jonathan son of Saul.'),
  ('BSB', '2 Samuel', 10, 21, 8, 'But the king took Armoni and Mephibosheth, the two sons whom Rizpah daughter of Aiah had borne to Saul, as well as the five sons whom Merab daughter of Saul had borne to Adriel son of Barzillai the Meholathite.'),
  ('BSB', '2 Samuel', 10, 21, 9, 'And he delivered them into the hands of the Gibeonites, and they hanged them on the hill before the LORD. So all seven of them fell together; they were put to death in the first days of the harvest, at the beginning of the barley harvest.'),
  ('BSB', '2 Samuel', 10, 21, 10, 'And Rizpah the daughter of Aiah took sackcloth and spread it out for herself on a rock. From the beginning of the harvest until the rain from heaven poured down on the bodies, she did not allow the birds of the air to rest on them by day, nor the beasts of the field by night.'),
  ('BSB', '2 Samuel', 10, 21, 11, 'When David was told what Saul’s concubine Rizpah, daughter of Aiah, had done,'),
  ('BSB', '2 Samuel', 10, 21, 12, 'he went and took the bones of Saul and his son Jonathan from the men of Jabesh-gilead, who had stolen them from the public square of Beth-shan where the Philistines had hung the bodies after they had struck down Saul at Gilboa.'),
  ('BSB', '2 Samuel', 10, 21, 13, 'So David had the bones of Saul and his son Jonathan brought from there, along with the bones of those who had been hanged.'),
  ('BSB', '2 Samuel', 10, 21, 14, 'And they buried the bones of Saul and his son Jonathan in Zela in the land of Benjamin, in the tomb of Saul’s father Kish. After they had done everything the king had commanded, God answered their prayers for the land.'),
  ('BSB', '2 Samuel', 10, 21, 15, 'Once again the Philistines waged war against Israel, and David and his servants went down and fought against the Philistines; but David became exhausted.'),
  ('BSB', '2 Samuel', 10, 21, 16, 'Then Ishbi-benob, a descendant of Rapha, whose bronze spear weighed three hundred shekels and who was bearing a new sword, resolved to kill David.'),
  ('BSB', '2 Samuel', 10, 21, 17, 'But Abishai son of Zeruiah came to his aid, struck the Philistine, and killed him. Then David’s men swore to him, “You must never again go out with us to battle, so that the lamp of Israel may not be extinguished.”'),
  ('BSB', '2 Samuel', 10, 21, 18, 'Some time later at Gob, there was another battle with the Philistines. At that time Sibbecai the Hushathite killed Saph, one of the descendants of Rapha.'),
  ('BSB', '2 Samuel', 10, 21, 19, 'Once again there was a battle with the Philistines at Gob, and Elhanan son of Jair the Bethlehemite killed the brother of Goliath the Gittite, the shaft of whose spear was like a weaver’s beam.'),
  ('BSB', '2 Samuel', 10, 21, 20, 'And there was still another battle at Gath, where there was a man of great stature with six fingers on each hand and six toes on each foot—twenty-four in all. He too was descended from Rapha,'),
  ('BSB', '2 Samuel', 10, 21, 21, 'and when he taunted Israel, Jonathan the son of David’s brother Shimei killed him.'),
  ('BSB', '2 Samuel', 10, 21, 22, 'So these four descendants of Rapha in Gath fell at the hands of David and his servants.'),
  ('BSB', '2 Samuel', 10, 22, 1, 'And David sang this song to the LORD on the day the LORD had delivered him from the hand of all his enemies and from the hand of Saul.'),
  ('BSB', '2 Samuel', 10, 22, 2, 'He said: “The LORD is my rock, my fortress, and my deliverer.'),
  ('BSB', '2 Samuel', 10, 22, 3, 'My God is my rock, in whom I take refuge, my shield, and the horn of my salvation. My stronghold, my refuge, and my Savior, You save me from violence.'),
  ('BSB', '2 Samuel', 10, 22, 4, 'I will call upon the LORD, who is worthy to be praised; so shall I be saved from my enemies.'),
  ('BSB', '2 Samuel', 10, 22, 5, 'For the waves of death engulfed me; the torrents of chaos overwhelmed me.'),
  ('BSB', '2 Samuel', 10, 22, 6, 'The cords of Sheol entangled me; the snares of death confronted me.'),
  ('BSB', '2 Samuel', 10, 22, 7, 'In my distress I called upon the LORD; I cried out to my God. And from His temple He heard my voice, and my cry for help reached His ears.'),
  ('BSB', '2 Samuel', 10, 22, 8, 'Then the earth shook and quaked; the foundations of the heavens trembled; they were shaken because He burned with anger.'),
  ('BSB', '2 Samuel', 10, 22, 9, 'Smoke rose from His nostrils, and consuming fire came from His mouth; glowing coals blazed forth.'),
  ('BSB', '2 Samuel', 10, 22, 10, 'He parted the heavens and came down with dark clouds beneath His feet.'),
  ('BSB', '2 Samuel', 10, 22, 11, 'He mounted a cherub and flew; He soared on the wings of the wind.'),
  ('BSB', '2 Samuel', 10, 22, 12, 'He made darkness a canopy around Him, a gathering of water and thick clouds.'),
  ('BSB', '2 Samuel', 10, 22, 13, 'From the brightness of His presence coals of fire blazed forth.'),
  ('BSB', '2 Samuel', 10, 22, 14, 'The LORD thundered from heaven; the voice of the Most High resounded.'),
  ('BSB', '2 Samuel', 10, 22, 15, 'He shot His arrows and scattered the foes; He hurled lightning and routed them.'),
  ('BSB', '2 Samuel', 10, 22, 16, 'The channels of the sea appeared, and the foundations of the world were exposed at the rebuke of the LORD, at the blast of the breath of His nostrils.'),
  ('BSB', '2 Samuel', 10, 22, 17, 'He reached down from on high and took hold of me; He drew me out of deep waters.'),
  ('BSB', '2 Samuel', 10, 22, 18, 'He rescued me from my powerful enemy, from foes too mighty for me.'),
  ('BSB', '2 Samuel', 10, 22, 19, 'They confronted me in my day of calamity, but the LORD was my support.'),
  ('BSB', '2 Samuel', 10, 22, 20, 'He brought me out into the open; He rescued me because He delighted in me.'),
  ('BSB', '2 Samuel', 10, 22, 21, 'The LORD has rewarded me according to my righteousness; He has repaid me according to the cleanness of my hands.'),
  ('BSB', '2 Samuel', 10, 22, 22, 'For I have kept the ways of the LORD and have not wickedly departed from my God.'),
  ('BSB', '2 Samuel', 10, 22, 23, 'For all His ordinances are before me; I have not disregarded His statutes.'),
  ('BSB', '2 Samuel', 10, 22, 24, 'And I have been blameless before Him and kept myself from iniquity.'),
  ('BSB', '2 Samuel', 10, 22, 25, 'So the LORD has repaid me according to my righteousness, according to my cleanness in His sight.'),
  ('BSB', '2 Samuel', 10, 22, 26, 'To the faithful You show Yourself faithful, to the blameless You show Yourself blameless;'),
  ('BSB', '2 Samuel', 10, 22, 27, 'to the pure You show Yourself pure, but to the crooked You show Yourself shrewd.'),
  ('BSB', '2 Samuel', 10, 22, 28, 'You save an afflicted people, but Your eyes are on the haughty to bring them down.'),
  ('BSB', '2 Samuel', 10, 22, 29, 'For You, O LORD, are my lamp; the LORD lights up my darkness.'),
  ('BSB', '2 Samuel', 10, 22, 30, 'For in You I can charge an army; with my God I can scale a wall.'),
  ('BSB', '2 Samuel', 10, 22, 31, 'As for God, His way is perfect; the word of the LORD is flawless. He is a shield to all who take refuge in Him.'),
  ('BSB', '2 Samuel', 10, 22, 32, 'For who is God besides the LORD? And who is the Rock except our God?'),
  ('BSB', '2 Samuel', 10, 22, 33, 'God is my strong fortress and He makes my way clear.'),
  ('BSB', '2 Samuel', 10, 22, 34, 'He makes my feet like those of a deer and stations me upon the heights.'),
  ('BSB', '2 Samuel', 10, 22, 35, 'He trains my hands for battle; my arms can bend a bow of bronze.'),
  ('BSB', '2 Samuel', 10, 22, 36, 'You have given me Your shield of salvation, and Your gentleness exalts me.'),
  ('BSB', '2 Samuel', 10, 22, 37, 'You broaden the path beneath me so that my ankles do not give way.'),
  ('BSB', '2 Samuel', 10, 22, 38, 'I pursued my enemies and destroyed them; I did not turn back until they were consumed.'),
  ('BSB', '2 Samuel', 10, 22, 39, 'I devoured and crushed them so they could not rise; they have fallen under my feet.'),
  ('BSB', '2 Samuel', 10, 22, 40, 'You have armed me with strength for battle; You have subdued my foes beneath me.'),
  ('BSB', '2 Samuel', 10, 22, 41, 'You have made my enemies retreat before me; I put an end to those who hated me.'),
  ('BSB', '2 Samuel', 10, 22, 42, 'They looked, but there was no one to save them— to the LORD, but He did not answer.'),
  ('BSB', '2 Samuel', 10, 22, 43, 'I ground them as the dust of the earth; I crushed and trampled them like mud in the streets.'),
  ('BSB', '2 Samuel', 10, 22, 44, 'You have delivered me from the strife of my people; You have preserved me as the head of nations; a people I had not known shall serve me.'),
  ('BSB', '2 Samuel', 10, 22, 45, 'Foreigners cower before me; when they hear me, they obey me.'),
  ('BSB', '2 Samuel', 10, 22, 46, 'Foreigners lose heart and come trembling from their strongholds.'),
  ('BSB', '2 Samuel', 10, 22, 47, 'The LORD lives, and blessed be my Rock! And may God, the Rock of my salvation, be exalted—'),
  ('BSB', '2 Samuel', 10, 22, 48, 'the God who avenges me and brings down nations beneath me,'),
  ('BSB', '2 Samuel', 10, 22, 49, 'who frees me from my enemies. You exalt me above my foes; You rescue me from violent men.'),
  ('BSB', '2 Samuel', 10, 22, 50, 'Therefore I will praise You, O LORD, among the nations; I will sing praises to Your name.'),
  ('BSB', '2 Samuel', 10, 22, 51, 'Great salvation He brings to His king. He shows loving devotion to His anointed, to David and his descendants forever.”'),
  ('BSB', '2 Samuel', 10, 23, 1, 'These are the last words of David: “The oracle of David son of Jesse, the oracle of the man raised on high, the one anointed by the God of Jacob, and the sweet psalmist of Israel:'),
  ('BSB', '2 Samuel', 10, 23, 2, 'The Spirit of the LORD spoke through me; His word was on my tongue.'),
  ('BSB', '2 Samuel', 10, 23, 3, 'The God of Israel spoke; the Rock of Israel said to me, ‘He who rules the people with justice, who rules in the fear of God,'),
  ('BSB', '2 Samuel', 10, 23, 4, 'is like the light of the morning at sunrise of a cloudless dawn, the glistening after the rain on the sprouting grass of the earth.’'),
  ('BSB', '2 Samuel', 10, 23, 5, 'Is not my house right with God? For He has established with me an everlasting covenant, ordered and secured in every part. Will He not bring about my full salvation and my every desire?'),
  ('BSB', '2 Samuel', 10, 23, 6, 'But the worthless are all like thorns raked aside, for they can never be gathered by hand.'),
  ('BSB', '2 Samuel', 10, 23, 7, 'The man who touches them must be armed with iron or with the shaft of a spear. The fire burns them to ashes in the place where they lie.”'),
  ('BSB', '2 Samuel', 10, 23, 8, 'These are the names of David’s mighty men: Josheb-basshebeth the Tahchemonite was chief of the Three. He wielded his spear against eight hundred men, whom he killed at one time.'),
  ('BSB', '2 Samuel', 10, 23, 9, 'Next in command was Eleazar son of Dodo the Ahohite. As one of the three mighty men, he went with David to taunt the Philistines who had gathered for battle at Pas-dammim. The men of Israel retreated,'),
  ('BSB', '2 Samuel', 10, 23, 10, 'but Eleazar stood his ground and struck the Philistines until his hand grew weary and stuck to his sword. The LORD brought about a great victory that day. Then the troops returned to him, but only to plunder the dead.'),
  ('BSB', '2 Samuel', 10, 23, 11, 'And after him was Shammah son of Agee the Hararite. When the Philistines had banded together near a field full of lentils, Israel’s troops fled from them.'),
  ('BSB', '2 Samuel', 10, 23, 12, 'But Shammah took his stand in the middle of the field, defended it, and struck down the Philistines. So the LORD brought about a great victory.'),
  ('BSB', '2 Samuel', 10, 23, 13, 'At harvest time, three of the thirty chief men went down to David at the cave of Adullam, while a company of Philistines was encamped in the Valley of Rephaim.'),
  ('BSB', '2 Samuel', 10, 23, 14, 'At that time David was in the stronghold, and the garrison of the Philistines was at Bethlehem.'),
  ('BSB', '2 Samuel', 10, 23, 15, 'David longed for water and said, “Oh, that someone would get me a drink of water from the well near the gate of Bethlehem!”'),
  ('BSB', '2 Samuel', 10, 23, 16, 'So the three mighty men broke through the Philistine camp, drew water from the well near the gate of Bethlehem, and brought it back to David. But he refused to drink it; instead, he poured it out to the LORD,'),
  ('BSB', '2 Samuel', 10, 23, 17, 'saying, “Far be it from me, O LORD, to do this! Is this not the blood of the men who risked their lives?” So he refused to drink it. Such were the exploits of the three mighty men.'),
  ('BSB', '2 Samuel', 10, 23, 18, 'Now Abishai, the brother of Joab and son of Zeruiah, was chief of the Three, and he lifted his spear against three hundred men, killed them, and won a name along with the Three.'),
  ('BSB', '2 Samuel', 10, 23, 19, 'Was he not more honored than the Three? And he became their commander, even though he was not included among the Three.'),
  ('BSB', '2 Samuel', 10, 23, 20, 'And Benaiah son of Jehoiada was a man of valor from Kabzeel, a man of many exploits. He struck down two champions of Moab, and on a snowy day he went down into a pit and killed a lion.'),
  ('BSB', '2 Samuel', 10, 23, 21, 'He also killed an Egyptian, a huge man. Although the Egyptian had a spear in his hand, Benaiah went against him with a club, snatched the spear from his hand, and killed the Egyptian with his own spear.'),
  ('BSB', '2 Samuel', 10, 23, 22, 'These were the exploits of Benaiah son of Jehoiada, who won a name alongside the three mighty men.'),
  ('BSB', '2 Samuel', 10, 23, 23, 'He was most honored among the Thirty, but he did not become one of the Three. And David appointed him over his guard.'),
  ('BSB', '2 Samuel', 10, 23, 24, 'Now these were members of the Thirty: Asahel the brother of Joab, Elhanan son of Dodo of Bethlehem,'),
  ('BSB', '2 Samuel', 10, 23, 25, 'Shammah the Harodite, Elika the Harodite,'),
  ('BSB', '2 Samuel', 10, 23, 26, 'Helez the Paltite, Ira son of Ikkesh the Tekoite,'),
  ('BSB', '2 Samuel', 10, 23, 27, 'Abiezer the Anathothite, Mebunnai the Hushathite,'),
  ('BSB', '2 Samuel', 10, 23, 28, 'Zalmon the Ahohite, Maharai the Netophathite,'),
  ('BSB', '2 Samuel', 10, 23, 29, 'Heled son of Baanah the Netophathite, Ittai son of Ribai from Gibeah of the Benjamites,'),
  ('BSB', '2 Samuel', 10, 23, 30, 'Benaiah the Pirathonite, Hiddai from the brooks of Gaash,'),
  ('BSB', '2 Samuel', 10, 23, 31, 'Abi-albon the Arbathite, Azmaveth the Barhumite,'),
  ('BSB', '2 Samuel', 10, 23, 32, 'Eliahba the Shaalbonite, the sons of Jashen,'),
  ('BSB', '2 Samuel', 10, 23, 33, 'Jonathan son of Shammah the Hararite, Ahiam son of Sharar the Hararite,'),
  ('BSB', '2 Samuel', 10, 23, 34, 'Eliphelet son of Ahasbai the Maacathite, Eliam son of Ahithophel the Gilonite,'),
  ('BSB', '2 Samuel', 10, 23, 35, 'Hezro the Carmelite, Paarai the Arbite,'),
  ('BSB', '2 Samuel', 10, 23, 36, 'Igal son of Nathan of Zobah, Bani the Gadite,'),
  ('BSB', '2 Samuel', 10, 23, 37, 'Zelek the Ammonite, Naharai the Beerothite, the armor-bearer of Joab son of Zeruiah,'),
  ('BSB', '2 Samuel', 10, 23, 38, 'Ira the Ithrite, Gareb the Ithrite,'),
  ('BSB', '2 Samuel', 10, 23, 39, 'and Uriah the Hittite. There were thirty-seven in all.'),
  ('BSB', '2 Samuel', 10, 24, 1, 'Again the anger of the LORD burned against Israel, and He stirred up David against them, saying, “Go and take a census of Israel and Judah.”'),
  ('BSB', '2 Samuel', 10, 24, 2, 'So the king said to Joab the commander of his army, who was with him, “Go now throughout the tribes of Israel from Dan to Beersheba and register the troops, so that I may know their number.”'),
  ('BSB', '2 Samuel', 10, 24, 3, 'But Joab replied to the king, “May the LORD your God multiply the troops a hundred times over, and may the eyes of my lord the king see it. But why does my lord the king want to do such a thing?”'),
  ('BSB', '2 Samuel', 10, 24, 4, 'Nevertheless, the king’s word prevailed against Joab and against the commanders of the army. So Joab and the commanders of the army departed from the presence of the king to count the troops of Israel.'),
  ('BSB', '2 Samuel', 10, 24, 5, 'They crossed the Jordan and camped near Aroer, south of the town in the middle of the valley, and proceeded toward Gad and Jazer.'),
  ('BSB', '2 Samuel', 10, 24, 6, 'Then they went to Gilead and the land of Tahtim-hodshi, and on to Dan-jaan and around to Sidon.'),
  ('BSB', '2 Samuel', 10, 24, 7, 'They went toward the fortress of Tyre and all the cities of the Hivites and Canaanites. Finally, they went on to the Negev of Judah, to Beersheba.'),
  ('BSB', '2 Samuel', 10, 24, 8, 'At the end of nine months and twenty days, having gone through the whole land, they returned to Jerusalem.'),
  ('BSB', '2 Samuel', 10, 24, 9, 'And Joab reported to the king the total number of the troops. In Israel there were 800,000 men of valor who drew the sword, and in Judah there were 500,000.'),
  ('BSB', '2 Samuel', 10, 24, 10, 'After David had numbered the troops, his conscience was stricken and he said to the LORD, “I have sinned greatly in what I have done. Now, O LORD, I beg You to take away the iniquity of Your servant, for I have acted very foolishly.”'),
  ('BSB', '2 Samuel', 10, 24, 11, 'When David got up in the morning, a revelation from the LORD had come to Gad the prophet, David’s seer:'),
  ('BSB', '2 Samuel', 10, 24, 12, '“Go and tell David that this is what the LORD says: ‘I am offering you three options. Choose one of them, and I will carry it out against you.’”'),
  ('BSB', '2 Samuel', 10, 24, 13, 'So Gad went and said to David, “Do you choose to endure three years of famine in your land, three months of fleeing the pursuit of your enemies, or three days of plague upon your land? Now then, think it over and decide how I should reply to Him who sent me.”'),
  ('BSB', '2 Samuel', 10, 24, 14, 'David answered Gad, “I am deeply distressed. Please, let us fall into the hand of the LORD, for His mercies are great; but do not let me fall into the hands of men.”'),
  ('BSB', '2 Samuel', 10, 24, 15, 'So the LORD sent a plague upon Israel from that morning until the appointed time, and seventy thousand of the people from Dan to Beersheba died.'),
  ('BSB', '2 Samuel', 10, 24, 16, 'But when the angel stretched out his hand to destroy Jerusalem, the LORD relented from the calamity and said to the angel who was destroying the people, “Enough! Withdraw your hand now!” At that time the angel of the LORD was by the threshing floor of Araunah the Jebusite.'),
  ('BSB', '2 Samuel', 10, 24, 17, 'When David saw the angel striking down the people, he said to the LORD, “Surely I, the shepherd, have sinned and acted wickedly. But these sheep, what have they done? Please, let Your hand fall upon me and my father’s house.”'),
  ('BSB', '2 Samuel', 10, 24, 18, 'And that day Gad came to David and said to him, “Go up and build an altar to the LORD on the threshing floor of Araunah the Jebusite.”'),
  ('BSB', '2 Samuel', 10, 24, 19, 'So David went up at the word of Gad, just as the LORD had commanded.'),
  ('BSB', '2 Samuel', 10, 24, 20, 'When Araunah looked out and saw the king and his servants coming toward him, he went out and bowed facedown before the king.'),
  ('BSB', '2 Samuel', 10, 24, 21, '“Why has my lord the king come to his servant?” Araunah said. “To buy your threshing floor,” David replied, “that I may build an altar to the LORD, so that the plague upon the people may be halted.”'),
  ('BSB', '2 Samuel', 10, 24, 22, 'Araunah said to David, “My lord the king may take whatever seems good and offer it up. Here are the oxen for a burnt offering and the threshing sledges and ox yokes for the wood.'),
  ('BSB', '2 Samuel', 10, 24, 23, 'O king, Araunah gives all these to the king.” He also said to the king, “May the LORD your God accept you.”'),
  ('BSB', '2 Samuel', 10, 24, 24, '“No,” replied the king, “I insist on paying a price, for I will not offer to the LORD my God burnt offerings that cost me nothing.” So David bought the threshing floor and the oxen for fifty shekels of silver.'),
  ('BSB', '2 Samuel', 10, 24, 25, 'And there he built an altar to the LORD and offered burnt offerings and peace offerings. Then the LORD answered the prayers on behalf of the land, and the plague upon Israel was halted.'),
  ('BSB', '1 Kings', 11, 1, 1, 'Now King David was old and well along in years, and though they covered him with blankets, he could not keep warm.'),
  ('BSB', '1 Kings', 11, 1, 2, 'So his servants said to him, “Let us search for a young virgin for our lord the king, to attend to him and care for him and lie by his side to keep him warm.”'),
  ('BSB', '1 Kings', 11, 1, 3, 'Then they searched throughout Israel for a beautiful girl, and they found Abishag the Shunammite and brought her to the king.'),
  ('BSB', '1 Kings', 11, 1, 4, 'The girl was unsurpassed in beauty; she cared for the king and served him, but he had no relations with her.'),
  ('BSB', '1 Kings', 11, 1, 5, 'At that time Adonijah, David’s son by Haggith, began to exalt himself, saying, “I will be king!” And he acquired chariots and horsemen and fifty men to run ahead of him.'),
  ('BSB', '1 Kings', 11, 1, 6, '(His father had never once reprimanded him by saying, “Why do you act this way?” Adonijah was also very handsome, born next after Absalom.)'),
  ('BSB', '1 Kings', 11, 1, 7, 'So Adonijah conferred with Joab son of Zeruiah and with Abiathar the priest, who supported him.'),
  ('BSB', '1 Kings', 11, 1, 8, 'But Zadok the priest, Benaiah son of Jehoiada, Nathan the prophet, Shimei, Rei, and David’s mighty men would not join Adonijah.'),
  ('BSB', '1 Kings', 11, 1, 9, 'And Adonijah sacrificed sheep, oxen, and fattened calves near the stone of Zoheleth, which is next to En-rogel. He invited all his royal brothers and all the men of Judah who were servants of the king.'),
  ('BSB', '1 Kings', 11, 1, 10, 'But he did not invite Nathan the prophet, Benaiah, the mighty men, or his brother Solomon.'),
  ('BSB', '1 Kings', 11, 1, 11, 'Then Nathan said to Bathsheba the mother of Solomon, “Have you not heard that Adonijah son of Haggith has become king, and our lord David does not know it?'),
  ('BSB', '1 Kings', 11, 1, 12, 'Now please, come and let me advise you. Save your own life and the life of your son Solomon.'),
  ('BSB', '1 Kings', 11, 1, 13, 'Go at once to King David and say, ‘My lord the king, did you not swear to your maidservant, “Surely your son Solomon will reign after me, and he will sit on my throne”? Why then has Adonijah become king?’'),
  ('BSB', '1 Kings', 11, 1, 14, 'Then, while you are still there speaking with the king, I will come in after you and confirm your words.”'),
  ('BSB', '1 Kings', 11, 1, 15, 'So Bathsheba went to see the king in his bedroom. Since the king was very old, Abishag the Shunammite was serving him.'),
  ('BSB', '1 Kings', 11, 1, 16, 'And Bathsheba bowed down in homage to the king, who asked, “What is your desire?”'),
  ('BSB', '1 Kings', 11, 1, 17, '“My lord,” she replied, “you yourself swore to your maidservant by the LORD your God: ‘Surely your son Solomon will reign after me, and he will sit on my throne.’'),
  ('BSB', '1 Kings', 11, 1, 18, 'But now, behold, Adonijah has become king, and you, my lord the king, did not know it.'),
  ('BSB', '1 Kings', 11, 1, 19, 'And he has sacrificed an abundance of oxen, fattened calves, and sheep, and has invited all the other sons of the king, as well as Abiathar the priest and Joab the commander of the army. But he did not invite your servant Solomon.'),
  ('BSB', '1 Kings', 11, 1, 20, 'And as for you, my lord the king, the eyes of all Israel are upon you to tell them who will sit on the throne of my lord the king after him.'),
  ('BSB', '1 Kings', 11, 1, 21, 'Otherwise, when my lord the king rests with his fathers, I and my son Solomon will be counted as criminals.”'),
  ('BSB', '1 Kings', 11, 1, 22, 'And just then, while Bathsheba was still speaking with the king, Nathan the prophet arrived.'),
  ('BSB', '1 Kings', 11, 1, 23, 'So the king was told, “Nathan the prophet is here.” And Nathan went in and bowed facedown before the king.'),
  ('BSB', '1 Kings', 11, 1, 24, '“My lord the king,” said Nathan, “did you say, ‘Adonijah will reign after me, and he will sit on my throne’?'),
  ('BSB', '1 Kings', 11, 1, 25, 'For today he has gone down and sacrificed an abundance of oxen, fattened calves, and sheep, and has invited all the sons of the king, the commanders of the army, and Abiathar the priest. And behold, they are eating and drinking before him, saying, ‘Long live King Adonijah!’'),
  ('BSB', '1 Kings', 11, 1, 26, 'But me your servant he did not invite, nor Zadok the priest, nor Benaiah son of Jehoiada, nor your servant Solomon.'),
  ('BSB', '1 Kings', 11, 1, 27, 'Has my lord the king let this happen without informing your servant who should sit on the throne after my lord the king?”'),
  ('BSB', '1 Kings', 11, 1, 28, 'Then King David said, “Call in Bathsheba for me.” So she came into the king’s presence and stood before him.'),
  ('BSB', '1 Kings', 11, 1, 29, 'And the king swore an oath, saying, “As surely as the LORD lives, who has redeemed my life from all distress,'),
  ('BSB', '1 Kings', 11, 1, 30, 'I will carry out this very day exactly what I swore to you by the LORD, the God of Israel: Surely your son Solomon will reign after me, and he will sit on my throne in my place.”'),
  ('BSB', '1 Kings', 11, 1, 31, 'Bathsheba bowed facedown in homage to the king and said, “May my lord King David live forever!”'),
  ('BSB', '1 Kings', 11, 1, 32, 'Then King David said, “Call in for me Zadok the priest, Nathan the prophet, and Benaiah son of Jehoiada.” So they came before the king.'),
  ('BSB', '1 Kings', 11, 1, 33, '“Take my servants with you,” said the king. “Set my son Solomon on my own mule and take him down to Gihon.'),
  ('BSB', '1 Kings', 11, 1, 34, 'There Zadok the priest and Nathan the prophet are to anoint him king over Israel. You are to blow the ram’s horn and declare, ‘Long live King Solomon!’'),
  ('BSB', '1 Kings', 11, 1, 35, 'Then you shall go up with him, and he is to come and sit on my throne and reign in my place. For I have appointed him ruler over Israel and Judah.”'),
  ('BSB', '1 Kings', 11, 1, 36, '“Amen,” replied Benaiah son of Jehoiada. “May the LORD, the God of my lord the king, so declare it.'),
  ('BSB', '1 Kings', 11, 1, 37, 'Just as the LORD was with my lord the king, so may He be with Solomon and make his throne even greater than that of my lord King David.”'),
  ('BSB', '1 Kings', 11, 1, 38, 'Then Zadok the priest, Nathan the prophet, and Benaiah son of Jehoiada, along with the Cherethites and Pelethites, went down and set Solomon on King David’s mule, and they escorted him to Gihon.'),
  ('BSB', '1 Kings', 11, 1, 39, 'Zadok the priest took the horn of oil from the tabernacle and anointed Solomon. Then they blew the ram’s horn, and all the people proclaimed, “Long live King Solomon!”'),
  ('BSB', '1 Kings', 11, 1, 40, 'All the people followed him, playing flutes and rejoicing with such a great joy that the earth was split by the sound.'),
  ('BSB', '1 Kings', 11, 1, 41, 'Now Adonijah and all his guests were finishing their feast when they heard the sound of the ram’s horn. “Why is the city in such a loud uproar?” asked Joab.'),
  ('BSB', '1 Kings', 11, 1, 42, 'As he was speaking, suddenly Jonathan the son of Abiathar the priest arrived. “Come in,” said Adonijah, “for you are a man of valor. You must be bringing good news.”'),
  ('BSB', '1 Kings', 11, 1, 43, '“Not at all,” Jonathan replied. “Our lord King David has made Solomon king.'),
  ('BSB', '1 Kings', 11, 1, 44, 'And with Solomon, the king has sent Zadok the priest, Nathan the prophet, and Benaiah son of Jehoiada, along with the Cherethites and Pelethites, and they have set him on the king’s mule.'),
  ('BSB', '1 Kings', 11, 1, 45, 'Zadok the priest and Nathan the prophet have anointed him king at Gihon, and they have gone up from there with rejoicing that rings out in the city. That is the noise you hear.'),
  ('BSB', '1 Kings', 11, 1, 46, 'Moreover, Solomon has taken his seat on the royal throne.'),
  ('BSB', '1 Kings', 11, 1, 47, 'The king’s servants have also gone to congratulate our lord King David, saying, ‘May your God make the name of Solomon more famous than your own name, and may He make his throne greater than your throne.’ And the king has bowed in worship on his bed,'),
  ('BSB', '1 Kings', 11, 1, 48, 'saying, ‘Blessed be the LORD, the God of Israel! Today He has provided one to sit on my throne, and my eyes have seen it.’”'),
  ('BSB', '1 Kings', 11, 1, 49, 'At this, all the guests of Adonijah arose in terror and scattered.'),
  ('BSB', '1 Kings', 11, 1, 50, 'But Adonijah, in fear of Solomon, got up and went to take hold of the horns of the altar.'),
  ('BSB', '1 Kings', 11, 1, 51, 'It was reported to Solomon: “Behold, Adonijah fears King Solomon, and he has taken hold of the horns of the altar, saying, ‘Let King Solomon first swear to me not to put his servant to the sword.’”'),
  ('BSB', '1 Kings', 11, 1, 52, 'And Solomon replied, “If he is a man of character, not a single hair of his will fall to the ground. But if evil is found in him, he will die.”'),
  ('BSB', '1 Kings', 11, 1, 53, 'So King Solomon summoned Adonijah down from the altar, and he came and bowed down before King Solomon, who said to him, “Go to your home.”'),
  ('BSB', '1 Kings', 11, 2, 1, 'As the time drew near for David to die, he charged his son Solomon,'),
  ('BSB', '1 Kings', 11, 2, 2, '“I am about to go the way of all the earth. So be strong and prove yourself a man.'),
  ('BSB', '1 Kings', 11, 2, 3, 'And keep the charge of the LORD your God to walk in His ways and to keep His statutes, commandments, ordinances, and decrees, as is written in the Law of Moses, so that you may prosper in all you do and wherever you turn,'),
  ('BSB', '1 Kings', 11, 2, 4, 'and so that the LORD may fulfill His promise to me: ‘If your descendants take heed to walk faithfully before Me with all their heart and soul, you will never fail to have a man on the throne of Israel.’'),
  ('BSB', '1 Kings', 11, 2, 5, 'Moreover, you know what Joab son of Zeruiah did to me—what he did to Abner son of Ner and Amasa son of Jether, the two commanders of the armies of Israel. He killed them in peacetime to avenge the blood of war. He stained with the blood of war the belt around his waist and the sandals on his feet.'),
  ('BSB', '1 Kings', 11, 2, 6, 'So act according to your wisdom, and do not let his gray head go down to Sheol in peace.'),
  ('BSB', '1 Kings', 11, 2, 7, 'But show loving devotion to the sons of Barzillai the Gileadite, and let them be among those who eat at your table, because they stood by me when I fled from your brother Absalom.'),
  ('BSB', '1 Kings', 11, 2, 8, 'Keep an eye on Shimei the son of Gera, the Benjamite from Bahurim who is with you. He called down bitter curses against me on the day I went to Mahanaim, but when he came down to meet me at the Jordan, I swore to him by the LORD: ‘I will never put you to the sword.’'),
  ('BSB', '1 Kings', 11, 2, 9, 'Now therefore, do not hold him guiltless, for you are a wise man. You know what you ought to do to him to bring his gray head down to Sheol in blood.”'),
  ('BSB', '1 Kings', 11, 2, 10, 'Then David rested with his fathers and was buried in the City of David.'),
  ('BSB', '1 Kings', 11, 2, 11, 'The length of David’s reign over Israel was forty years—seven years in Hebron and thirty-three years in Jerusalem.'),
  ('BSB', '1 Kings', 11, 2, 12, 'So Solomon sat on the throne of his father David, and his kingdom was firmly established.'),
  ('BSB', '1 Kings', 11, 2, 13, 'Now Adonijah son of Haggith went to Bathsheba the mother of Solomon, and she asked, “Do you come in peace?” “Yes, in peace,” he replied.'),
  ('BSB', '1 Kings', 11, 2, 14, 'Then he said, “I have something to tell you.” “Say it,” she answered.'),
  ('BSB', '1 Kings', 11, 2, 15, '“You know that the kingship was mine,” he said. “All Israel expected that I should reign, but the kingship has turned to my brother, for it has come to him from the LORD.'),
  ('BSB', '1 Kings', 11, 2, 16, 'So now I have just one request of you; do not deny me.” “State your request,” she told him.'),
  ('BSB', '1 Kings', 11, 2, 17, 'Adonijah replied, “Please speak to King Solomon, since he will not turn you down. Let him give me Abishag the Shunammite as my wife.”'),
  ('BSB', '1 Kings', 11, 2, 18, '“Very well,” Bathsheba replied. “I will speak to the king for you.”'),
  ('BSB', '1 Kings', 11, 2, 19, 'So Bathsheba went to King Solomon to speak to him for Adonijah. The king stood up to greet her, bowed to her, and sat down on his throne. Then the king had a throne brought for his mother, who sat down at his right hand.'),
  ('BSB', '1 Kings', 11, 2, 20, '“I have just one small request of you,” she said. “Do not deny me.” “Make your request, my mother,” the king replied, “for I will not deny you.”'),
  ('BSB', '1 Kings', 11, 2, 21, 'So Bathsheba said, “Let Abishag the Shunammite be given to your brother Adonijah as his wife.”'),
  ('BSB', '1 Kings', 11, 2, 22, 'King Solomon answered his mother, “Why do you request Abishag the Shunammite for Adonijah? Since he is my older brother, you might as well request the kingdom for him and for Abiathar the priest and for Joab son of Zeruiah!”'),
  ('BSB', '1 Kings', 11, 2, 23, 'Then King Solomon swore by the LORD: “May God punish me, and ever so severely, if Adonijah has not made this request at the expense of his life.'),
  ('BSB', '1 Kings', 11, 2, 24, 'And now, as surely as the LORD lives—the One who established me, who set me on the throne of my father David, and who founded for me a dynasty as He promised—surely Adonijah shall be put to death today!”'),
  ('BSB', '1 Kings', 11, 2, 25, 'So King Solomon sent the order to Benaiah son of Jehoiada, who struck down Adonijah, and he died.'),
  ('BSB', '1 Kings', 11, 2, 26, 'Then the king said to Abiathar the priest, “Go back to your fields in Anathoth. Even though you deserve to die, I will not put you to death at this time, since you carried the ark of the Lord GOD before my father David, and you suffered through all that my father suffered.”'),
  ('BSB', '1 Kings', 11, 2, 27, 'So Solomon banished Abiathar from the priesthood of the LORD and thus fulfilled the word that the LORD had spoken at Shiloh against the house of Eli.'),
  ('BSB', '1 Kings', 11, 2, 28, 'When the news reached Joab, who had conspired with Adonijah but not with Absalom, he fled to the tent of the LORD and took hold of the horns of the altar.'),
  ('BSB', '1 Kings', 11, 2, 29, 'It was reported to King Solomon: “Joab has fled to the tent of the LORD and is now beside the altar.” So Solomon sent Benaiah son of Jehoiada, saying, “Go, strike him down!”');
insert into control_room_bible (version, book, book_num, chapter, verse, text) values
  ('BSB', '1 Kings', 11, 2, 30, 'And Benaiah entered the tent of the LORD and said to Joab, “The king says, ‘Come out!’” But Joab replied, “No, I will die here.” So Benaiah relayed the message to the king, saying, “This is how Joab answered me.”'),
  ('BSB', '1 Kings', 11, 2, 31, 'And the king replied, “Do just as he says. Strike him down and bury him, and so remove from me and from the house of my father the innocent blood that Joab shed.'),
  ('BSB', '1 Kings', 11, 2, 32, 'The LORD will bring his bloodshed back upon his own head, for without the knowledge of my father David he struck down two men more righteous and better than he when he put to the sword Abner son of Ner, commander of Israel’s army, and Amasa son of Jether, commander of Judah’s army.'),
  ('BSB', '1 Kings', 11, 2, 33, 'Their blood will come back upon the heads of Joab and his descendants forever; but for David, his descendants, his house, and his throne, there shall be peace from the LORD forever.”'),
  ('BSB', '1 Kings', 11, 2, 34, 'So Benaiah son of Jehoiada went up, struck down Joab, and killed him. He was buried at his own home in the wilderness.'),
  ('BSB', '1 Kings', 11, 2, 35, 'And the king appointed Benaiah son of Jehoiada in Joab’s place over the army, and he appointed Zadok the priest in Abiathar’s place.'),
  ('BSB', '1 Kings', 11, 2, 36, 'Then the king summoned Shimei and said to him, “Build a house for yourself in Jerusalem and live there, but do not go anywhere else.'),
  ('BSB', '1 Kings', 11, 2, 37, 'On the day you go out and cross the Kidron Valley, know for sure that you will die; your blood will be on your own head.”'),
  ('BSB', '1 Kings', 11, 2, 38, '“The sentence is fair,” Shimei replied. “Your servant will do as my lord the king has spoken.” And Shimei lived in Jerusalem for a long time.'),
  ('BSB', '1 Kings', 11, 2, 39, 'After three years, however, two of Shimei’s slaves ran away to Achish son of Maacah, king of Gath. And Shimei was told, “Look, your slaves are in Gath.”'),
  ('BSB', '1 Kings', 11, 2, 40, 'So Shimei saddled his donkey and set out to Achish at Gath in search of his slaves, and he brought them back from Gath.'),
  ('BSB', '1 Kings', 11, 2, 41, 'When Solomon was told that Shimei had gone from Jerusalem to Gath and had returned,'),
  ('BSB', '1 Kings', 11, 2, 42, 'the king summoned Shimei and said to him, “Did I not make you swear by the LORD and warn you, ‘On the day you leave and go elsewhere, know for sure that you will die’? And you told me, ‘The sentence is fair; I will comply.’'),
  ('BSB', '1 Kings', 11, 2, 43, 'So why have you not kept your oath to the LORD and the command that I gave you?”'),
  ('BSB', '1 Kings', 11, 2, 44, 'The king also said, “You know in your heart all the evil that you did to my father David. Therefore the LORD will bring your evil back upon your head.'),
  ('BSB', '1 Kings', 11, 2, 45, 'But King Solomon will be blessed and David’s throne will remain secure before the LORD forever.”'),
  ('BSB', '1 Kings', 11, 2, 46, 'Then the king commanded Benaiah son of Jehoiada, and he went out and struck Shimei down, and he died. Thus the kingdom was firmly established in the hand of Solomon.'),
  ('BSB', '1 Kings', 11, 3, 1, 'Later, Solomon formed an alliance with Pharaoh king of Egypt by marrying his daughter. Solomon brought her to the City of David until he had finished building his palace and the house of the LORD, as well as the wall around Jerusalem.'),
  ('BSB', '1 Kings', 11, 3, 2, 'The people, however, were still sacrificing on the high places because a house for the Name of the LORD had not yet been built.'),
  ('BSB', '1 Kings', 11, 3, 3, 'And Solomon loved the LORD and walked in the statutes of his father David, except that he sacrificed and burned incense on the high places.'),
  ('BSB', '1 Kings', 11, 3, 4, 'Now the king went to Gibeon to sacrifice there, for it was the great high place. Solomon offered a thousand burnt offerings on the altar there.'),
  ('BSB', '1 Kings', 11, 3, 5, 'One night at Gibeon the LORD appeared to Solomon in a dream, and God said, “Ask, and I will give it to you!”'),
  ('BSB', '1 Kings', 11, 3, 6, 'Solomon replied, “You have shown much loving devotion to Your servant, my father David, because he walked before You in faithfulness, righteousness, and uprightness of heart. And You have maintained this loving devotion by giving him a son to sit on his throne this very day.'),
  ('BSB', '1 Kings', 11, 3, 7, 'And now, O LORD my God, You have made Your servant king in my father David’s place. But I am only a little child, not knowing how to go out or come in.'),
  ('BSB', '1 Kings', 11, 3, 8, 'Your servant is here among the people You have chosen, a people too numerous to count or number.'),
  ('BSB', '1 Kings', 11, 3, 9, 'Therefore give Your servant an understanding heart to judge Your people and to discern between good and evil. For who is able to govern this great people of Yours?”'),
  ('BSB', '1 Kings', 11, 3, 10, 'Now it pleased the Lord that Solomon had made this request.'),
  ('BSB', '1 Kings', 11, 3, 11, 'So God said to him, “Since you have asked for this instead of requesting long life or wealth for yourself or death for your enemies—but you have asked for discernment to administer justice—'),
  ('BSB', '1 Kings', 11, 3, 12, 'behold, I will do what you have asked. I will give you a wise and discerning heart, so that there has never been nor will ever be another like you.'),
  ('BSB', '1 Kings', 11, 3, 13, 'Moreover, I will give you what you did not request—both riches and honor—so that during all your days no man in any kingdom will be your equal.'),
  ('BSB', '1 Kings', 11, 3, 14, 'So if you walk in My ways and keep My statutes and commandments, just as your father David did, I will prolong your days.”'),
  ('BSB', '1 Kings', 11, 3, 15, 'Then Solomon awoke, and indeed it had been a dream. So he returned to Jerusalem, stood before the ark of the covenant of the Lord, and offered burnt offerings and peace offerings. Then he held a feast for all his servants.'),
  ('BSB', '1 Kings', 11, 3, 16, 'At that time two prostitutes came to the king and stood before him.'),
  ('BSB', '1 Kings', 11, 3, 17, 'One woman said, “Please, my lord, this woman and I live in the same house, and I gave birth while she was in the house.'),
  ('BSB', '1 Kings', 11, 3, 18, 'On the third day after I gave birth, this woman also had a baby. We were alone, with no one in the house but the two of us.'),
  ('BSB', '1 Kings', 11, 3, 19, 'During the night this woman’s son died because she rolled over on him.'),
  ('BSB', '1 Kings', 11, 3, 20, 'So she got up in the middle of the night and took my son from my side while I was asleep. She laid him in her bosom and put her dead son at my bosom.'),
  ('BSB', '1 Kings', 11, 3, 21, 'The next morning, when I got up to nurse my son, I discovered he was dead. But when I examined him, I realized that he was not the son I had borne.”'),
  ('BSB', '1 Kings', 11, 3, 22, '“No,” said the other woman, “the living one is my son and the dead one is your son.” But the first woman insisted, “No, the dead one is yours and the living one is mine.” So they argued before the king.'),
  ('BSB', '1 Kings', 11, 3, 23, 'Then the king replied, “This woman says, ‘My son is alive and yours is dead,’ but that woman says, ‘No, your son is dead and mine is alive.’”'),
  ('BSB', '1 Kings', 11, 3, 24, 'The king continued, “Bring me a sword.” So they brought him a sword,'),
  ('BSB', '1 Kings', 11, 3, 25, 'and the king declared, “Cut the living child in two and give half to one and half to the other.”'),
  ('BSB', '1 Kings', 11, 3, 26, 'Then the woman whose son was alive spoke to the king because she yearned with compassion for her son. “Please, my lord,” she said, “give her the living baby. Do not kill him!” But the other woman said, “He will be neither mine nor yours. Cut him in two!”'),
  ('BSB', '1 Kings', 11, 3, 27, 'Then the king gave his ruling: “Give the living baby to the first woman. By no means should you kill him; she is his mother.”'),
  ('BSB', '1 Kings', 11, 3, 28, 'When all Israel heard of the judgment the king had given, they stood in awe of him, for they saw that the wisdom of God was in him to administer justice.'),
  ('BSB', '1 Kings', 11, 4, 1, 'So King Solomon ruled over Israel,'),
  ('BSB', '1 Kings', 11, 4, 2, 'and these were his chief officials: Azariah son of Zadok was the priest;'),
  ('BSB', '1 Kings', 11, 4, 3, 'Elihoreph and Ahijah, the sons of Shisha, were secretaries; Jehoshaphat son of Ahilud was the recorder;'),
  ('BSB', '1 Kings', 11, 4, 4, 'Benaiah son of Jehoiada was in charge of the army; Zadok and Abiathar were priests;'),
  ('BSB', '1 Kings', 11, 4, 5, 'Azariah son of Nathan was in charge of the governors; Zabud son of Nathan was a priest and adviser to the king;'),
  ('BSB', '1 Kings', 11, 4, 6, 'Ahishar was in charge of the palace; and Adoniram son of Abda was in charge of the forced labor.'),
  ('BSB', '1 Kings', 11, 4, 7, 'Solomon had twelve governors over all Israel to provide food for the king and his household. Each one would arrange provisions for one month of the year,'),
  ('BSB', '1 Kings', 11, 4, 8, 'and these were their names: Ben-hur in the hill country of Ephraim;'),
  ('BSB', '1 Kings', 11, 4, 9, 'Ben-deker in Makaz, in Shaalbim, in Beth-shemesh, and in Elon-beth-hanan;'),
  ('BSB', '1 Kings', 11, 4, 10, 'Ben-hesed in Arubboth (Socoh and all the land of Hepher belonged to him);'),
  ('BSB', '1 Kings', 11, 4, 11, 'Ben-abinadab in Naphath-dor (Taphath, a daughter of Solomon, was his wife);'),
  ('BSB', '1 Kings', 11, 4, 12, 'Baana son of Ahilud in Taanach, in Megiddo, and in all of Beth-shean next to Zarethan below Jezreel, from Beth-shean to Abel-meholah and on past Jokmeam;'),
  ('BSB', '1 Kings', 11, 4, 13, 'Ben-geber in Ramoth-gilead (the villages of Jair son of Manasseh in Gilead belonged to him, as well as the region of Argob in Bashan with its sixty great cities with walls and bronze bars);'),
  ('BSB', '1 Kings', 11, 4, 14, 'Ahinadab son of Iddo in Mahanaim;'),
  ('BSB', '1 Kings', 11, 4, 15, 'Ahimaaz in Naphtali (he had married Basemath, a daughter of Solomon);'),
  ('BSB', '1 Kings', 11, 4, 16, 'Baana son of Hushai in Asher and in Aloth;'),
  ('BSB', '1 Kings', 11, 4, 17, 'Jehoshaphat son of Paruah in Issachar;'),
  ('BSB', '1 Kings', 11, 4, 18, 'Shimei son of Ela in Benjamin;'),
  ('BSB', '1 Kings', 11, 4, 19, 'Geber son of Uri in the land of Gilead, including the territories of Sihon king of the Amorites and of Og king of Bashan. There was also one governor in the land of Judah.'),
  ('BSB', '1 Kings', 11, 4, 20, 'The people of Judah and Israel were as numerous as the sand on the seashore, and they were eating and drinking and rejoicing.'),
  ('BSB', '1 Kings', 11, 4, 21, 'And Solomon reigned over all the kingdoms from the Euphrates to the land of the Philistines, as far as the border of Egypt. These kingdoms offered tribute and served Solomon all the days of his life.'),
  ('BSB', '1 Kings', 11, 4, 22, 'Solomon’s provisions for a single day were thirty cors of fine flour, sixty cors of meal,'),
  ('BSB', '1 Kings', 11, 4, 23, 'ten fat oxen, twenty range oxen, and a hundred sheep, as well as deer, gazelles, roebucks, and fattened poultry.'),
  ('BSB', '1 Kings', 11, 4, 24, 'For Solomon had dominion over everything west of the Euphrates—over all the kingdoms from Tiphsah to Gaza—and he had peace on all sides.'),
  ('BSB', '1 Kings', 11, 4, 25, 'Throughout the days of Solomon, Judah and Israel dwelt securely from Dan to Beersheba, each man under his own vine and his own fig tree.'),
  ('BSB', '1 Kings', 11, 4, 26, 'Solomon had 4,000 stalls for his chariot horses and 12,000 horses.'),
  ('BSB', '1 Kings', 11, 4, 27, 'Each month the governors in turn provided food for King Solomon and all who came to his table. They saw to it that nothing was lacking.'),
  ('BSB', '1 Kings', 11, 4, 28, 'Each one also brought to the required place their quotas of barley and straw for the chariot horses and other horses.'),
  ('BSB', '1 Kings', 11, 4, 29, 'And God gave Solomon wisdom, exceedingly deep insight, and understanding beyond measure, like the sand on the seashore.'),
  ('BSB', '1 Kings', 11, 4, 30, 'Solomon’s wisdom was greater than that of all the men of the East, greater than all the wisdom of Egypt.'),
  ('BSB', '1 Kings', 11, 4, 31, 'He was wiser than all men—wiser than Ethan the Ezrahite, and wiser than Heman, Calcol, and Darda, the sons of Mahol. And his fame spread throughout the surrounding nations.'),
  ('BSB', '1 Kings', 11, 4, 32, 'Solomon composed three thousand proverbs, and his songs numbered a thousand and five.'),
  ('BSB', '1 Kings', 11, 4, 33, 'He spoke of trees, from the cedar in Lebanon to the hyssop growing in the wall, and he taught about animals, birds, reptiles, and fish.'),
  ('BSB', '1 Kings', 11, 4, 34, 'So men of all nations came to listen to Solomon’s wisdom, sent by all the kings of the earth, who had heard of his wisdom.'),
  ('BSB', '1 Kings', 11, 5, 1, 'Now when Hiram king of Tyre heard that Solomon had been anointed king in his father’s place, he sent envoys to Solomon; for Hiram had always been a friend of David.'),
  ('BSB', '1 Kings', 11, 5, 2, 'And Solomon relayed this message to Hiram:'),
  ('BSB', '1 Kings', 11, 5, 3, '“As you are well aware, due to the wars waged on all sides against my father David, he could not build a house for the Name of the LORD his God until the LORD had put his enemies under his feet.'),
  ('BSB', '1 Kings', 11, 5, 4, 'But now the LORD my God has given me rest on every side, and there is no adversary or crisis.'),
  ('BSB', '1 Kings', 11, 5, 5, 'So behold, I plan to build a house for the Name of the LORD my God, according to what the LORD said to my father David: ‘I will put your son on your throne in your place, and he will build the house for My Name.’'),
  ('BSB', '1 Kings', 11, 5, 6, 'Now therefore, order that cedars of Lebanon be cut down for me. My servants will be with your servants, and I will pay your servants whatever wages you set, for you know that there are none among us as skilled in logging as the Sidonians.”'),
  ('BSB', '1 Kings', 11, 5, 7, 'When Hiram received Solomon’s message, he rejoiced greatly and said, “Blessed be the LORD this day! He has given David a wise son over this great people!”'),
  ('BSB', '1 Kings', 11, 5, 8, 'Then Hiram sent a reply to Solomon, saying: “I have received your message; I will do all you desire regarding the cedar and cypress timber.'),
  ('BSB', '1 Kings', 11, 5, 9, 'My servants will haul the logs from Lebanon to the Sea, and I will float them as rafts by sea to the place you specify. There I will separate the logs, and you can take them away. And in exchange, you can meet my needs by providing my household with food.”'),
  ('BSB', '1 Kings', 11, 5, 10, 'So Hiram provided Solomon with all the cedar and cypress timber he wanted,'),
  ('BSB', '1 Kings', 11, 5, 11, 'and year after year Solomon would provide Hiram with 20,000 cors of wheat as food for his household, as well as 20,000 baths of pure olive oil.'),
  ('BSB', '1 Kings', 11, 5, 12, 'And the LORD gave Solomon wisdom, as He had promised him. There was peace between Hiram and Solomon, and the two of them made a treaty.'),
  ('BSB', '1 Kings', 11, 5, 13, 'Then King Solomon conscripted a labor force of 30,000 men from all Israel.'),
  ('BSB', '1 Kings', 11, 5, 14, 'He sent them to Lebanon in monthly shifts of 10,000 men, so that they would spend one month in Lebanon and two months at home. And Adoniram was in charge of the forced labor.'),
  ('BSB', '1 Kings', 11, 5, 15, 'Solomon had 70,000 porters and 80,000 stonecutters in the mountains,'),
  ('BSB', '1 Kings', 11, 5, 16, 'not including his 3,300 foremen who supervised the workers.'),
  ('BSB', '1 Kings', 11, 5, 17, 'And the king commanded them to quarry large, costly stones to lay the foundation of the temple with dressed stones.'),
  ('BSB', '1 Kings', 11, 5, 18, 'So Solomon’s and Hiram’s builders, along with the Gebalites, quarried the stone and prepared the timber and stone for the construction of the temple.'),
  ('BSB', '1 Kings', 11, 6, 1, 'In the four hundred and eightieth year after the Israelites had come out of the land of Egypt, in the month of Ziv, the second month of the fourth year of Solomon’s reign over Israel, he began to build the house of the LORD.'),
  ('BSB', '1 Kings', 11, 6, 2, 'The house that King Solomon built for the LORD was sixty cubits long, twenty cubits wide, and thirty cubits high.'),
  ('BSB', '1 Kings', 11, 6, 3, 'The portico at the front of the main hall of the temple was twenty cubits long, extending across the width of the temple and projecting out ten cubits in front of the temple.'),
  ('BSB', '1 Kings', 11, 6, 4, 'He also had narrow windows framed high in the temple.'),
  ('BSB', '1 Kings', 11, 6, 5, 'Against the walls of the temple and the inner sanctuary, Solomon built a chambered structure around the temple, in which he constructed the side rooms.'),
  ('BSB', '1 Kings', 11, 6, 6, 'The bottom floor was five cubits wide, the middle floor six cubits, and the third floor seven cubits. He also placed offset ledges around the outside of the temple, so that nothing would be inserted into its walls.'),
  ('BSB', '1 Kings', 11, 6, 7, 'The temple was constructed using finished stones cut at the quarry, so that no hammer or chisel or any other iron tool was heard in the temple while it was being built.'),
  ('BSB', '1 Kings', 11, 6, 8, 'The entrance to the bottom floor was on the south side of the temple. A stairway led up to the middle level, and from there to the third floor.'),
  ('BSB', '1 Kings', 11, 6, 9, 'So Solomon built the temple and finished it, roofing it with beams and planks of cedar.'),
  ('BSB', '1 Kings', 11, 6, 10, 'He built chambers all along the temple, each five cubits high and attached to the temple with beams of cedar.'),
  ('BSB', '1 Kings', 11, 6, 11, 'Then the word of the LORD came to Solomon, saying:'),
  ('BSB', '1 Kings', 11, 6, 12, '“As for this temple you are building, if you walk in My statutes, carry out My ordinances, and keep all My commandments by walking in them, I will fulfill through you the promise I made to your father David.'),
  ('BSB', '1 Kings', 11, 6, 13, 'And I will dwell among the Israelites and will not abandon My people Israel.”'),
  ('BSB', '1 Kings', 11, 6, 14, 'So Solomon built the temple and finished it.'),
  ('BSB', '1 Kings', 11, 6, 15, 'He lined the interior walls with cedar paneling from the floor of the temple to the ceiling, and he covered the floor with cypress boards.'),
  ('BSB', '1 Kings', 11, 6, 16, 'He partitioned off the twenty cubits at the rear of the temple with cedar boards from floor to ceiling to form within the temple an inner sanctuary, the Most Holy Place.'),
  ('BSB', '1 Kings', 11, 6, 17, 'And the main hall in front of this room was forty cubits long.'),
  ('BSB', '1 Kings', 11, 6, 18, 'The cedar paneling inside the temple was carved with gourds and open flowers. Everything was cedar; not a stone could be seen.'),
  ('BSB', '1 Kings', 11, 6, 19, 'Solomon also prepared the inner sanctuary within the temple to set the ark of the covenant of the LORD there.'),
  ('BSB', '1 Kings', 11, 6, 20, 'The inner sanctuary was twenty cubits long, twenty cubits wide, and twenty cubits high. He overlaid the inside with pure gold, and he also overlaid the altar of cedar.'),
  ('BSB', '1 Kings', 11, 6, 21, 'So Solomon overlaid the inside of the temple with pure gold, and he extended gold chains across the front of the inner sanctuary, which was overlaid with gold.'),
  ('BSB', '1 Kings', 11, 6, 22, 'So he overlaid with gold the whole interior of the temple, until everything was completely finished. He also overlaid with gold the entire altar that belonged to the inner sanctuary.'),
  ('BSB', '1 Kings', 11, 6, 23, 'In the inner sanctuary he made two cherubim, each ten cubits high, out of olive wood.'),
  ('BSB', '1 Kings', 11, 6, 24, 'One wing of the first cherub was five cubits long, and the other wing was five cubits long as well. So the full wingspan was ten cubits.'),
  ('BSB', '1 Kings', 11, 6, 25, 'The second cherub also measured ten cubits; both cherubim had the same size and shape,'),
  ('BSB', '1 Kings', 11, 6, 26, 'and the height of each cherub was ten cubits.'),
  ('BSB', '1 Kings', 11, 6, 27, 'And he placed the cherubim inside the innermost room of the temple. Since their wings were spread out, the wing of the first cherub touched one wall, while the wing of the second cherub touched the other wall, and in the middle of the room their wingtips touched.'),
  ('BSB', '1 Kings', 11, 6, 28, 'He also overlaid the cherubim with gold.'),
  ('BSB', '1 Kings', 11, 6, 29, 'Then he carved the walls all around the temple, in both the inner and outer sanctuaries, with carved engravings of cherubim, palm trees, and open flowers.'),
  ('BSB', '1 Kings', 11, 6, 30, 'And he overlaid the temple floor with gold in both the inner and outer sanctuaries.'),
  ('BSB', '1 Kings', 11, 6, 31, 'For the entrance to the inner sanctuary, Solomon constructed doors of olive wood with five-sided doorposts.'),
  ('BSB', '1 Kings', 11, 6, 32, 'The double doors were made of olive wood, and he carved into them cherubim, palm trees, and open flowers and overlaid the cherubim and palm trees with hammered gold.'),
  ('BSB', '1 Kings', 11, 6, 33, 'In the same way he made four-sided doorposts of olive wood for the sanctuary entrance.'),
  ('BSB', '1 Kings', 11, 6, 34, 'The two doors were made of cypress wood, and each had two folding panels.'),
  ('BSB', '1 Kings', 11, 6, 35, 'He carved into them cherubim, palm trees, and open flowers; and he overlaid them with gold, hammered evenly over the carvings.'),
  ('BSB', '1 Kings', 11, 6, 36, 'Solomon built the inner courtyard with three rows of dressed stone and one row of trimmed cedar beams.'),
  ('BSB', '1 Kings', 11, 6, 37, 'The foundation of the house of the LORD was laid in the fourth year of Solomon’s reign, in the month of Ziv.'),
  ('BSB', '1 Kings', 11, 6, 38, 'In his eleventh year and eighth month, the month of Bul, the temple was finished in every detail and according to every specification. So he built the temple in seven years.'),
  ('BSB', '1 Kings', 11, 7, 1, 'Solomon, however, took thirteen years to complete the construction of his entire palace.'),
  ('BSB', '1 Kings', 11, 7, 2, 'He built the House of the Forest of Lebanon a hundred cubits long, fifty cubits wide, and thirty cubits high, with four rows of cedar pillars supporting the cedar beams.'),
  ('BSB', '1 Kings', 11, 7, 3, 'The house was roofed with cedar above the beams that rested on the pillars—forty-five beams, fifteen per row.'),
  ('BSB', '1 Kings', 11, 7, 4, 'There were three rows of high windows facing one another in three tiers.'),
  ('BSB', '1 Kings', 11, 7, 5, 'All the doorways had rectangular frames, with the openings facing one another in three tiers.'),
  ('BSB', '1 Kings', 11, 7, 6, 'Solomon made his colonnade fifty cubits long and thirty cubits wide, with a portico in front of it and a canopy with pillars in front of the portico.'),
  ('BSB', '1 Kings', 11, 7, 7, 'In addition, he built a hall for the throne, the Hall of Justice, where he was to judge. It was paneled with cedar from floor to ceiling.'),
  ('BSB', '1 Kings', 11, 7, 8, 'And the palace where Solomon would live, set further back, was of similar construction. He also made a palace like this hall for Pharaoh’s daughter, whom he had married.'),
  ('BSB', '1 Kings', 11, 7, 9, 'All these buildings were constructed with costly stones, cut to size and trimmed with saws inside and out from the foundation to the eaves, and from the outside to the great courtyard.'),
  ('BSB', '1 Kings', 11, 7, 10, 'The foundations were laid with large, costly stones, some ten cubits long and some eight cubits long.'),
  ('BSB', '1 Kings', 11, 7, 11, 'Above these were high-grade stones, cut to size, and cedar beams.'),
  ('BSB', '1 Kings', 11, 7, 12, 'The great courtyard was surrounded by three rows of dressed stone and a row of trimmed cedar beams, as were the inner courtyard and portico of the house of the LORD.'),
  ('BSB', '1 Kings', 11, 7, 13, 'Now King Solomon sent to bring Huram from Tyre.'),
  ('BSB', '1 Kings', 11, 7, 14, 'He was the son of a widow from the tribe of Naphtali, and his father was a man of Tyre, a craftsman in bronze. Huram had great skill, understanding, and knowledge for every kind of bronze work. So he came to King Solomon and carried out all his work.'),
  ('BSB', '1 Kings', 11, 7, 15, 'He cast two pillars of bronze, each eighteen cubits high and twelve cubits in circumference.'),
  ('BSB', '1 Kings', 11, 7, 16, 'He also made two capitals of cast bronze to set on top of the pillars, each capital five cubits high.'),
  ('BSB', '1 Kings', 11, 7, 17, 'For the capitals on top of the pillars he made a network of lattice, with wreaths of chainwork, seven for each capital.'),
  ('BSB', '1 Kings', 11, 7, 18, 'Likewise, he made the pillars with two rows of pomegranates around each grating to cover each capital atop the pillars.'),
  ('BSB', '1 Kings', 11, 7, 19, 'And the capitals atop the pillars in the portico were shaped like lilies, four cubits high.'),
  ('BSB', '1 Kings', 11, 7, 20, 'On the capitals of both pillars, just above the rounded projection next to the network, were the two hundred pomegranates in rows encircling each capital.'),
  ('BSB', '1 Kings', 11, 7, 21, 'Thus he set up the pillars at the portico of the temple. The pillar to the south he named Jachin, and the pillar to the north he named Boaz.'),
  ('BSB', '1 Kings', 11, 7, 22, 'And the tops of the pillars were shaped like lilies. So the work of the pillars was completed.'),
  ('BSB', '1 Kings', 11, 7, 23, 'He also made the Sea of cast metal. It was circular in shape, measuring ten cubits from rim to rim, five cubits in height, and thirty cubits in circumference.'),
  ('BSB', '1 Kings', 11, 7, 24, 'Below the rim, ornamental buds encircled it, ten per cubit all the way around the Sea, cast in two rows as a part of the Sea.'),
  ('BSB', '1 Kings', 11, 7, 25, 'The Sea stood on twelve oxen, three facing north, three facing west, three facing south, and three facing east. The Sea rested on them, with all their hindquarters toward the center.'),
  ('BSB', '1 Kings', 11, 7, 26, 'It was a handbreadth thick, and its rim was fashioned like the brim of a cup, like a lily blossom. It could hold two thousand baths.'),
  ('BSB', '1 Kings', 11, 7, 27, 'In addition, he made ten movable stands of bronze, each four cubits long, four cubits wide, and three cubits high.'),
  ('BSB', '1 Kings', 11, 7, 28, 'This was the design of the stands: They had side panels attached to uprights,'),
  ('BSB', '1 Kings', 11, 7, 29, 'and on the panels between the uprights were lions, oxen, and cherubim. On the uprights was a pedestal above, and below the lions and oxen were wreaths of beveled work.'),
  ('BSB', '1 Kings', 11, 7, 30, 'Each stand had four bronze wheels with bronze axles and a basin resting on four supports, with wreaths at each side.'),
  ('BSB', '1 Kings', 11, 7, 31, 'The opening to each stand inside the crown at the top was one cubit deep, with a round opening like the design of a pedestal, a cubit and a half wide. And around its opening were engravings, but the panels of the stands were square, not round.'),
  ('BSB', '1 Kings', 11, 7, 32, 'There were four wheels under the panels, and the axles of the wheels were attached to the stand; each wheel was a cubit and a half in diameter.'),
  ('BSB', '1 Kings', 11, 7, 33, 'The wheels were made like chariot wheels; their axles, rims, spokes, and hubs were all of cast metal.'),
  ('BSB', '1 Kings', 11, 7, 34, 'Each stand had four handles, one for each corner, projecting from the stand.'),
  ('BSB', '1 Kings', 11, 7, 35, 'At the top of each stand was a circular band half a cubit high. The supports and panels were cast as a unit with the top of the stand.'),
  ('BSB', '1 Kings', 11, 7, 36, 'He engraved cherubim, lions, and palm trees on the surfaces of the supports and panels, wherever each had space, with wreaths all around.'),
  ('BSB', '1 Kings', 11, 7, 37, 'In this way he made the ten stands, each with the same casting, dimensions, and shape.'),
  ('BSB', '1 Kings', 11, 7, 38, 'He also made ten bronze basins, each holding forty baths and measuring four cubits across, one basin for each of the ten stands.'),
  ('BSB', '1 Kings', 11, 7, 39, 'He set five stands on the south side of the temple and five on the north, and he put the Sea on the south side, at the southeast corner of the temple.'),
  ('BSB', '1 Kings', 11, 7, 40, 'Additionally, Huram made the pots, shovels, and sprinkling bowls. So Huram finished all the work that he had undertaken for King Solomon in the house of the LORD:'),
  ('BSB', '1 Kings', 11, 7, 41, 'the two pillars; the two bowl-shaped capitals atop the pillars; the two sets of network covering both bowls of the capitals atop the pillars;'),
  ('BSB', '1 Kings', 11, 7, 42, 'the four hundred pomegranates for the two sets of network (two rows of pomegranates for each network covering both the bowl-shaped capitals atop the pillars);'),
  ('BSB', '1 Kings', 11, 7, 43, 'the ten stands; the ten basins on the stands;'),
  ('BSB', '1 Kings', 11, 7, 44, 'the Sea; the twelve oxen underneath the Sea;'),
  ('BSB', '1 Kings', 11, 7, 45, 'and the pots, shovels, and sprinkling bowls. All the articles that Huram made for King Solomon in the house of the LORD were made of burnished bronze.'),
  ('BSB', '1 Kings', 11, 7, 46, 'The king had them cast in clay molds in the plain of the Jordan between Succoth and Zarethan.'),
  ('BSB', '1 Kings', 11, 7, 47, 'Solomon left all these articles unweighed, because there were so many. The weight of the bronze could not be determined.'),
  ('BSB', '1 Kings', 11, 7, 48, 'Solomon also made all the furnishings for the house of the LORD: the golden altar; the golden table on which was placed the Bread of the Presence;'),
  ('BSB', '1 Kings', 11, 7, 49, 'the lampstands of pure gold in front of the inner sanctuary, five on the right side and five on the left; the gold flowers, lamps, and tongs;'),
  ('BSB', '1 Kings', 11, 7, 50, 'the pure gold basins, wick trimmers, sprinkling bowls, ladles, and censers; and the gold hinges for the doors of the inner temple (that is, the Most Holy Place) as well as for the doors of the main hall of the temple.'),
  ('BSB', '1 Kings', 11, 7, 51, 'So all the work that King Solomon had performed for the house of the LORD was completed. Then Solomon brought in the items his father David had dedicated—the silver, the gold, and the furnishings—and he placed them in the treasuries of the house of the LORD.'),
  ('BSB', '1 Kings', 11, 8, 1, 'At that time Solomon assembled before him in Jerusalem the elders of Israel—all the tribal heads and family leaders of the Israelites—to bring up the ark of the covenant of the LORD from Zion, the City of David.'),
  ('BSB', '1 Kings', 11, 8, 2, 'And all the men of Israel came together to King Solomon at the feast in the seventh month, the month of Ethanim.'),
  ('BSB', '1 Kings', 11, 8, 3, 'When all the elders of Israel had arrived, the priests took up the ark,'),
  ('BSB', '1 Kings', 11, 8, 4, 'and they brought up the ark of the LORD and the Tent of Meeting with all its sacred furnishings. So the priests and Levites carried them up.'),
  ('BSB', '1 Kings', 11, 8, 5, 'There, before the ark, King Solomon and the whole congregation of Israel who had assembled with him sacrificed so many sheep and oxen that they could not be counted or numbered.'),
  ('BSB', '1 Kings', 11, 8, 6, 'Then the priests brought the ark of the covenant of the LORD to its place in the inner sanctuary of the temple, the Most Holy Place, beneath the wings of the cherubim.'),
  ('BSB', '1 Kings', 11, 8, 7, 'For the cherubim spread their wings over the place of the ark and overshadowed the ark and its poles.'),
  ('BSB', '1 Kings', 11, 8, 8, 'The poles extended far enough that their ends were visible from the Holy Place in front of the inner sanctuary, but not from outside the Holy Place; and they are there to this day.'),
  ('BSB', '1 Kings', 11, 8, 9, 'There was nothing in the ark except the two stone tablets that Moses had placed in it at Horeb, where the LORD had made a covenant with the Israelites after they had come out of the land of Egypt.'),
  ('BSB', '1 Kings', 11, 8, 10, 'And when the priests came out of the Holy Place, the cloud filled the house of the LORD'),
  ('BSB', '1 Kings', 11, 8, 11, 'so that the priests could not stand there to minister because of the cloud; for the glory of the LORD filled the house of the LORD.'),
  ('BSB', '1 Kings', 11, 8, 12, 'Then Solomon declared: “The LORD has said that He would dwell in the thick cloud.'),
  ('BSB', '1 Kings', 11, 8, 13, 'I have indeed built You an exalted house, a place for You to dwell forever.”'),
  ('BSB', '1 Kings', 11, 8, 14, 'And as the whole assembly of Israel stood there, the king turned around and blessed them all'),
  ('BSB', '1 Kings', 11, 8, 15, 'and said: “Blessed be the LORD, the God of Israel, who has fulfilled with His own hand what He spoke with His mouth to my father David, saying,'),
  ('BSB', '1 Kings', 11, 8, 16, '‘Since the day I brought My people Israel out of Egypt, I have not chosen a city from any tribe of Israel in which to build a house so that My Name would be there. But I have chosen David to be over My people Israel.’'),
  ('BSB', '1 Kings', 11, 8, 17, 'Now it was in the heart of my father David to build a house for the Name of the LORD, the God of Israel.'),
  ('BSB', '1 Kings', 11, 8, 18, 'But the LORD said to my father David, ‘Since it was in your heart to build a house for My Name, you have done well to have this in your heart.'),
  ('BSB', '1 Kings', 11, 8, 19, 'Nevertheless, you are not the one to build it; but your son, your own offspring, will build the house for My Name.’'),
  ('BSB', '1 Kings', 11, 8, 20, 'Now the LORD has fulfilled the word that He spoke. I have succeeded my father David, and I sit on the throne of Israel, as the LORD promised. I have built the house for the Name of the LORD, the God of Israel.'),
  ('BSB', '1 Kings', 11, 8, 21, 'And there I have provided a place for the ark, which contains the covenant of the LORD that He made with our fathers when He brought them out of the land of Egypt.”'),
  ('BSB', '1 Kings', 11, 8, 22, 'Then Solomon stood before the altar of the LORD in front of the whole assembly of Israel, spread out his hands toward heaven,'),
  ('BSB', '1 Kings', 11, 8, 23, 'and said: “O LORD, God of Israel, there is no God like You in heaven above or on earth below, keeping Your covenant of loving devotion with Your servants who walk before You with all their hearts.'),
  ('BSB', '1 Kings', 11, 8, 24, 'You have kept Your promise to Your servant, my father David. What You spoke with Your mouth You have fulfilled with Your hand this day.'),
  ('BSB', '1 Kings', 11, 8, 25, 'Therefore now, O LORD, God of Israel, keep for Your servant, my father David, what You promised when You said: ‘You will never fail to have a man to sit before Me on the throne of Israel, if only your descendants guard their way to walk before Me as you have done.’'),
  ('BSB', '1 Kings', 11, 8, 26, 'And now, O God of Israel, please confirm what You promised to Your servant, my father David.'),
  ('BSB', '1 Kings', 11, 8, 27, 'But will God indeed dwell upon the earth? Even heaven, the highest heaven, cannot contain You, much less this temple I have built.'),
  ('BSB', '1 Kings', 11, 8, 28, 'Yet regard the prayer and plea of Your servant, O LORD my God, so that You may hear the cry and the prayer that Your servant is praying before You today.'),
  ('BSB', '1 Kings', 11, 8, 29, 'May Your eyes be open toward this temple night and day, toward the place of which You said, ‘My Name shall be there,’ so that You may hear the prayer that Your servant prays toward this place.'),
  ('BSB', '1 Kings', 11, 8, 30, 'Hear the plea of Your servant and of Your people Israel when they pray toward this place. May You hear from heaven, Your dwelling place. May You hear and forgive.'),
  ('BSB', '1 Kings', 11, 8, 31, 'When a man sins against his neighbor and is required to take an oath, and he comes to take an oath before Your altar in this temple,'),
  ('BSB', '1 Kings', 11, 8, 32, 'then may You hear from heaven and act. May You judge Your servants, condemning the wicked man by bringing down on his own head what he has done, and justifying the righteous man by rewarding him according to his righteousness.'),
  ('BSB', '1 Kings', 11, 8, 33, 'When Your people Israel are defeated before an enemy because they have sinned against You, and they return to You and confess Your name, praying and pleading with You in this temple,'),
  ('BSB', '1 Kings', 11, 8, 34, 'then may You hear from heaven and forgive the sin of Your people Israel. May You restore them to the land You gave to their fathers.'),
  ('BSB', '1 Kings', 11, 8, 35, 'When the skies are shut and there is no rain because Your people have sinned against You, and they pray toward this place and confess Your name, and they turn from their sins because You have afflicted them,'),
  ('BSB', '1 Kings', 11, 8, 36, 'then may You hear from heaven and forgive the sin of Your servants, Your people Israel, so that You may teach them the good way in which they should walk. May You send rain on the land that You gave Your people as an inheritance.'),
  ('BSB', '1 Kings', 11, 8, 37, 'When famine or plague comes upon the land, or blight or mildew or locusts or grasshoppers, or when their enemy besieges them in their cities, whatever plague or sickness may come,'),
  ('BSB', '1 Kings', 11, 8, 38, 'then may whatever prayer or petition Your people Israel make—each knowing his own afflictions and spreading out his hands toward this temple—'),
  ('BSB', '1 Kings', 11, 8, 39, 'be heard by You from heaven, Your dwelling place. And may You forgive and act, and repay each man according to all his ways, since You know his heart—for You alone know the hearts of all men—'),
  ('BSB', '1 Kings', 11, 8, 40, 'so that they may fear You all the days they live in the land that You gave to our fathers.'),
  ('BSB', '1 Kings', 11, 8, 41, 'And as for the foreigner who is not of Your people Israel but has come from a distant land because of Your name—'),
  ('BSB', '1 Kings', 11, 8, 42, 'for they will hear of Your great name and mighty hand and outstretched arm—when he comes and prays toward this temple,'),
  ('BSB', '1 Kings', 11, 8, 43, 'then may You hear from heaven, Your dwelling place, and do according to all for which the foreigner calls to You. Then all the peoples of the earth will know Your name and fear You, as do Your people Israel, and they will know that this house I have built is called by Your Name.'),
  ('BSB', '1 Kings', 11, 8, 44, 'When Your people go to war against their enemies, wherever You send them, and when they pray to the LORD in the direction of the city You have chosen and the house I have built for Your Name,'),
  ('BSB', '1 Kings', 11, 8, 45, 'then may You hear from heaven their prayer and their plea, and may You uphold their cause.'),
  ('BSB', '1 Kings', 11, 8, 46, 'When they sin against You—for there is no one who does not sin—and You become angry with them and deliver them to an enemy who takes them as captives to his own land, whether far or near,'),
  ('BSB', '1 Kings', 11, 8, 47, 'and when they come to their senses in the land to which they were taken, and they repent and plead with You in the land of their captors, saying, ‘We have sinned and done wrong; we have acted wickedly,’'),
  ('BSB', '1 Kings', 11, 8, 48, 'and when they return to You with all their heart and soul in the land of the enemies who took them captive, and when they pray to You in the direction of the land that You gave to their fathers, the city You have chosen, and the house I have built for Your Name,'),
  ('BSB', '1 Kings', 11, 8, 49, 'then may You hear from heaven, Your dwelling place, their prayer and petition, and may You uphold their cause.'),
  ('BSB', '1 Kings', 11, 8, 50, 'May You forgive Your people who have sinned against You and all the transgressions they have committed against You, and may You grant them compassion in the eyes of their captors to show them mercy.'),
  ('BSB', '1 Kings', 11, 8, 51, 'For they are Your people and Your inheritance; You brought them out of Egypt, out of the furnace for iron.'),
  ('BSB', '1 Kings', 11, 8, 52, 'May Your eyes be open to the pleas of Your servant and of Your people Israel, and may You listen to them whenever they call to You.'),
  ('BSB', '1 Kings', 11, 8, 53, 'For You, O Lord GOD, as Your inheritance, have set them apart from all the peoples of the earth, as You spoke through Your servant Moses when You brought our fathers out of Egypt.”'),
  ('BSB', '1 Kings', 11, 8, 54, 'Now when Solomon had finished praying this entire prayer and petition to the LORD, he got up before the altar of the LORD, where he had been kneeling with his hands spread out toward heaven.'),
  ('BSB', '1 Kings', 11, 8, 55, 'And he stood and blessed the whole assembly of Israel in a loud voice, saying:'),
  ('BSB', '1 Kings', 11, 8, 56, '“Blessed be the LORD, who has given rest to His people Israel according to all that He promised. Not one word has failed of all the good promises He made through His servant Moses.'),
  ('BSB', '1 Kings', 11, 8, 57, 'May the LORD our God be with us, as He was with our fathers. May He never leave us nor forsake us.'),
  ('BSB', '1 Kings', 11, 8, 58, 'May He incline our hearts to Himself, to walk in all His ways and to keep the commandments and statutes and ordinances He commanded our fathers.'),
  ('BSB', '1 Kings', 11, 8, 59, 'And may these words with which I have made my petition before the LORD be near to the LORD our God day and night, so that He may uphold the cause of His servant and of His people Israel as each day requires,'),
  ('BSB', '1 Kings', 11, 8, 60, 'so that all the peoples of the earth may know that the LORD is God. There is no other!'),
  ('BSB', '1 Kings', 11, 8, 61, 'So let your heart be fully devoted to the LORD our God, as it is this day, to walk in His statutes and to keep His commandments.”'),
  ('BSB', '1 Kings', 11, 8, 62, 'Then the king and all Israel with him offered sacrifices before the LORD.'),
  ('BSB', '1 Kings', 11, 8, 63, 'And Solomon offered as peace offerings to the LORD 22,000 oxen and 120,000 sheep. So the king and all the Israelites dedicated the house of the LORD.'),
  ('BSB', '1 Kings', 11, 8, 64, 'On that same day the king consecrated the middle of the courtyard in front of the house of the LORD, and there he offered the burnt offerings, the grain offerings, and the fat of the peace offerings, since the bronze altar before the LORD was too small to contain all these offerings.'),
  ('BSB', '1 Kings', 11, 8, 65, 'So at that time Solomon and all Israel with him—a great assembly of people from Lebo-hamath to the Brook of Egypt—kept the feast before the LORD our God for seven days and seven more days—fourteen days in all.'),
  ('BSB', '1 Kings', 11, 8, 66, 'On the fifteenth day Solomon sent the people away. So they blessed the king and went home, joyful and glad in heart for all the good things that the LORD had done for His servant David and for His people Israel.'),
  ('BSB', '1 Kings', 11, 9, 1, 'Now when Solomon had finished building the house of the LORD and the royal palace, and had achieved all that he had desired to do,'),
  ('BSB', '1 Kings', 11, 9, 2, 'the LORD appeared to him a second time, as He had appeared to him at Gibeon.'),
  ('BSB', '1 Kings', 11, 9, 3, 'And the LORD said to him: “I have heard your prayer and petition before Me. I have consecrated this temple you have built by putting My Name there forever; My eyes and My heart will be there for all time.'),
  ('BSB', '1 Kings', 11, 9, 4, 'And as for you, if you walk before Me as your father David walked, with a heart of integrity and uprightness, doing all I have commanded you, and if you keep My statutes and ordinances,'),
  ('BSB', '1 Kings', 11, 9, 5, 'then I will establish your royal throne over Israel forever, as I promised your father David when I said, ‘You will never fail to have a man on the throne of Israel.’'),
  ('BSB', '1 Kings', 11, 9, 6, 'But if indeed you or your sons turn away from following Me and do not keep the commandments and statutes I have set before you, and if you go off to serve and worship other gods,'),
  ('BSB', '1 Kings', 11, 9, 7, 'then I will cut off Israel from the land that I have given them, and I will banish from My presence this temple I have sanctified for My Name. Then Israel will become an object of scorn and ridicule among all peoples.'),
  ('BSB', '1 Kings', 11, 9, 8, 'And when this temple has become a heap of rubble, all who pass by it will be appalled and will hiss and say, ‘Why has the LORD done such a thing to this land and to this temple?’'),
  ('BSB', '1 Kings', 11, 9, 9, 'And others will answer, ‘Because they have forsaken the LORD their God who brought their fathers out of the land of Egypt, and have embraced other gods, worshiping and serving them—because of this, the LORD has brought all this disaster upon them.’”'),
  ('BSB', '1 Kings', 11, 9, 10, 'Now at the end of the twenty years during which Solomon built these two houses, the house of the LORD and the royal palace,'),
  ('BSB', '1 Kings', 11, 9, 11, 'King Solomon gave twenty towns in the land of Galilee to Hiram king of Tyre, who had supplied him with cedar and cypress logs and gold for his every desire.'),
  ('BSB', '1 Kings', 11, 9, 12, 'So Hiram went out from Tyre to inspect the towns that Solomon had given him, but he was not pleased with them.'),
  ('BSB', '1 Kings', 11, 9, 13, '“What are these towns you have given me, my brother?” asked Hiram, and he called them the Land of Cabul, as they are called to this day.'),
  ('BSB', '1 Kings', 11, 9, 14, 'And Hiram had sent the king 120 talents of gold.'),
  ('BSB', '1 Kings', 11, 9, 15, 'This is the account of the forced labor that King Solomon imposed to build the house of the LORD, his own palace, the supporting terraces, and the wall of Jerusalem, as well as Hazor, Megiddo, and Gezer.'),
  ('BSB', '1 Kings', 11, 9, 16, 'Pharaoh king of Egypt had attacked and captured Gezer. He had set it on fire, killed the Canaanites who lived in the city, and given it as a dowry to his daughter, Solomon’s wife.'),
  ('BSB', '1 Kings', 11, 9, 17, 'So Solomon rebuilt Gezer, Lower Beth-horon,'),
  ('BSB', '1 Kings', 11, 9, 18, 'Baalath, and Tamar in the Wilderness of Judah,'),
  ('BSB', '1 Kings', 11, 9, 19, 'as well as all the store cities that Solomon had for his chariots and horses—whatever he desired to build in Jerusalem, Lebanon, and throughout the land of his dominion.'),
  ('BSB', '1 Kings', 11, 9, 20, 'As for all the people who remained of the Amorites, Hittites, Perizzites, Hivites, and Jebusites (the people who were not Israelites)—'),
  ('BSB', '1 Kings', 11, 9, 21, 'their descendants who remained in the land, those whom the Israelites were unable to devote to destruction—Solomon conscripted these people to be forced laborers, as they are to this day.'),
  ('BSB', '1 Kings', 11, 9, 22, 'But Solomon did not consign any of the Israelites to slavery, because they were his men of war, his servants, his officers, his captains, and the commanders of his chariots and cavalry.'),
  ('BSB', '1 Kings', 11, 9, 23, 'They were also the chief officers over Solomon’s projects: 550 supervisors over the people who did the work.'),
  ('BSB', '1 Kings', 11, 9, 24, 'As soon as Pharaoh’s daughter had come up from the City of David to the palace that Solomon had built for her, he built the supporting terraces.'),
  ('BSB', '1 Kings', 11, 9, 25, 'Three times a year Solomon offered burnt offerings and peace offerings on the altar he had built for the LORD, burning incense with them before the LORD. So he completed the temple.'),
  ('BSB', '1 Kings', 11, 9, 26, 'King Solomon also assembled a fleet of ships at Ezion-geber, which is near Eloth in Edom, on the shore of the Red Sea.'),
  ('BSB', '1 Kings', 11, 9, 27, 'And Hiram sent his servants, men who knew the sea, to serve in the fleet with Solomon’s servants.'),
  ('BSB', '1 Kings', 11, 9, 28, 'They sailed to Ophir and imported gold from there—420 talents—and delivered it to Solomon.'),
  ('BSB', '1 Kings', 11, 10, 1, 'Now when the queen of Sheba heard about the fame of Solomon concerning the name of the LORD, she came to test him with difficult questions.'),
  ('BSB', '1 Kings', 11, 10, 2, 'She arrived in Jerusalem with a very large caravan—with camels bearing spices, gold in great abundance, and precious stones. So she came to Solomon and spoke to him all that was on her mind.'),
  ('BSB', '1 Kings', 11, 10, 3, 'And Solomon answered all her questions; nothing was too difficult for the king to explain.'),
  ('BSB', '1 Kings', 11, 10, 4, 'When the queen of Sheba saw all the wisdom of Solomon, the palace he had built,'),
  ('BSB', '1 Kings', 11, 10, 5, 'the food at his table, the seating of his servants, the service and attire of his attendants and cupbearers, and the burnt offerings he presented at the house of the LORD, it took her breath away.'),
  ('BSB', '1 Kings', 11, 10, 6, 'She said to the king, “The report I heard in my own country about your words and wisdom is true.'),
  ('BSB', '1 Kings', 11, 10, 7, 'But I did not believe these things until I came and saw with my own eyes. Indeed, not even half was told to me. Your wisdom and prosperity have far exceeded the report I heard.'),
  ('BSB', '1 Kings', 11, 10, 8, 'How blessed are your men! How blessed are these servants of yours who stand continually before you and hear your wisdom!'),
  ('BSB', '1 Kings', 11, 10, 9, 'Blessed be the LORD your God, who has delighted in you to set you on the throne of Israel. Because of the LORD’s eternal love for Israel, He has made you king to carry out justice and righteousness.”'),
  ('BSB', '1 Kings', 11, 10, 10, 'Then she gave the king 120 talents of gold, a great quantity of spices, and precious stones. Never again was such an abundance of spices brought in as those the queen of Sheba gave to King Solomon.'),
  ('BSB', '1 Kings', 11, 10, 11, '(The fleet of Hiram that brought gold from Ophir also brought from Ophir a great cargo of almug wood and precious stones.'),
  ('BSB', '1 Kings', 11, 10, 12, 'The king made the almug wood into steps for the house of the LORD and for the king’s palace, and into lyres and harps for the singers. Never before had such almug wood been brought in, nor has such been seen to this day.)'),
  ('BSB', '1 Kings', 11, 10, 13, 'King Solomon gave the queen of Sheba all she desired—whatever she asked—besides what he had given her out of his royal bounty. Then she left and returned to her own country, along with her servants.'),
  ('BSB', '1 Kings', 11, 10, 14, 'The weight of gold that came to Solomon each year was 666 talents,'),
  ('BSB', '1 Kings', 11, 10, 15, 'not including the revenue from the merchants, traders, and all the Arabian kings and governors of the land.'),
  ('BSB', '1 Kings', 11, 10, 16, 'King Solomon made two hundred large shields of hammered gold; six hundred shekels of gold went into each shield.'),
  ('BSB', '1 Kings', 11, 10, 17, 'He also made three hundred small shields of hammered gold; three minas of gold went into each shield. And the king put them in the House of the Forest of Lebanon.'),
  ('BSB', '1 Kings', 11, 10, 18, 'Additionally, the king made a great throne of ivory and overlaid it with pure gold.'),
  ('BSB', '1 Kings', 11, 10, 19, 'The throne had six steps, and its back had a rounded top. There were armrests on both sides of the seat, with a lion standing beside each armrest.'),
  ('BSB', '1 Kings', 11, 10, 20, 'Twelve lions stood on the six steps, one at either end of each step. Nothing like this had ever been made for any kingdom.'),
  ('BSB', '1 Kings', 11, 10, 21, 'All King Solomon’s drinking cups were gold, and all the utensils of the House of the Forest of Lebanon were pure gold. There was no silver, because it was accounted as nothing in the days of Solomon.'),
  ('BSB', '1 Kings', 11, 10, 22, 'For the king had the ships of Tarshish at sea with Hiram’s fleet, and once every three years the ships of Tarshish would arrive bearing gold, silver, ivory, apes, and peacocks.'),
  ('BSB', '1 Kings', 11, 10, 23, 'So King Solomon surpassed all the kings of the earth in riches and wisdom.'),
  ('BSB', '1 Kings', 11, 10, 24, 'The whole world sought an audience with Solomon to hear the wisdom that God had put in his heart.'),
  ('BSB', '1 Kings', 11, 10, 25, 'Year after year, each visitor would bring his tribute: articles of silver and gold, clothing, weapons, spices, horses, and mules.'),
  ('BSB', '1 Kings', 11, 10, 26, 'Solomon accumulated 1,400 chariots and 12,000 horses, which he stationed in the chariot cities and also with him in Jerusalem.'),
  ('BSB', '1 Kings', 11, 10, 27, 'The king made silver as common in Jerusalem as stones, and cedar as abundant as sycamore in the foothills.'),
  ('BSB', '1 Kings', 11, 10, 28, 'Solomon’s horses were imported from Egypt and Kue; the royal merchants purchased them from Kue.'),
  ('BSB', '1 Kings', 11, 10, 29, 'A chariot could be imported from Egypt for six hundred shekels of silver, and a horse for a hundred and fifty. Likewise, they exported them to all the kings of the Hittites and to the kings of Aram.'),
  ('BSB', '1 Kings', 11, 11, 1, 'King Solomon, however, loved many foreign women along with the daughter of Pharaoh—women of Moab, Ammon, Edom, and Sidon, as well as Hittite women.'),
  ('BSB', '1 Kings', 11, 11, 2, 'These women were from the nations about which the LORD had told the Israelites, “You must not intermarry with them, for surely they will turn your hearts after their gods.” Yet Solomon clung to these women in love.'),
  ('BSB', '1 Kings', 11, 11, 3, 'He had seven hundred wives of royal birth and three hundred concubines—and his wives turned his heart away.'),
  ('BSB', '1 Kings', 11, 11, 4, 'For when Solomon grew old, his wives turned his heart after other gods, and he was not wholeheartedly devoted to the LORD his God, as his father David had been.'),
  ('BSB', '1 Kings', 11, 11, 5, 'Solomon followed Ashtoreth the goddess of the Sidonians and Milcom the abomination of the Ammonites.'),
  ('BSB', '1 Kings', 11, 11, 6, 'So Solomon did evil in the sight of the LORD; unlike his father David, he did not follow the LORD completely.'),
  ('BSB', '1 Kings', 11, 11, 7, 'At that time on a hill east of Jerusalem, Solomon built a high place for Chemosh the abomination of Moab and for Molech the abomination of the Ammonites.'),
  ('BSB', '1 Kings', 11, 11, 8, 'He did the same for all his foreign wives, who burned incense and sacrificed to their gods.'),
  ('BSB', '1 Kings', 11, 11, 9, 'Now the LORD grew angry with Solomon, because his heart had turned away from the LORD, the God of Israel, who had appeared to him twice.'),
  ('BSB', '1 Kings', 11, 11, 10, 'Although He had warned Solomon explicitly not to follow other gods, Solomon did not keep the LORD’s command.'),
  ('BSB', '1 Kings', 11, 11, 11, 'Then the LORD said to Solomon, “Because you have done this and have not kept My covenant and My statutes, which I have commanded you, I will tear the kingdom away from you and give it to your servant.'),
  ('BSB', '1 Kings', 11, 11, 12, 'Nevertheless, for the sake of your father David, I will not do it during your lifetime; I will tear it out of the hand of your son.'),
  ('BSB', '1 Kings', 11, 11, 13, 'Yet I will not tear the whole kingdom away from him. I will give one tribe to your son for the sake of My servant David and for the sake of Jerusalem, which I have chosen.”'),
  ('BSB', '1 Kings', 11, 11, 14, 'Then the LORD raised up against Solomon an adversary, Hadad the Edomite, from the royal line of Edom.'),
  ('BSB', '1 Kings', 11, 11, 15, 'Earlier, when David was in Edom, Joab the commander of the army had gone to bury the dead and had struck down every male in Edom.'),
  ('BSB', '1 Kings', 11, 11, 16, 'Joab and all Israel had stayed there six months, until he had killed every male in Edom.'),
  ('BSB', '1 Kings', 11, 11, 17, 'But Hadad, still just a young boy, had fled to Egypt, along with some Edomites who were servants of his father.'),
  ('BSB', '1 Kings', 11, 11, 18, 'Hadad and his men set out from Midian and went to Paran. They took men from Paran with them and went to Egypt, to Pharaoh king of Egypt, who gave Hadad a house and land and provided him with food.'),
  ('BSB', '1 Kings', 11, 11, 19, 'There Hadad found such great favor in the sight of Pharaoh that he gave to him in marriage the sister of Queen Tahpenes, his own wife.'),
  ('BSB', '1 Kings', 11, 11, 20, 'And the sister of Tahpenes bore Hadad a son named Genubath. Tahpenes herself weaned him in Pharaoh’s palace, and Genubath lived there among the sons of Pharaoh.'),
  ('BSB', '1 Kings', 11, 11, 21, 'When Hadad heard in Egypt that David had rested with his fathers and that Joab, the commander of the army, was dead, he said to Pharaoh, “Let me go, that I may return to my own country.”'),
  ('BSB', '1 Kings', 11, 11, 22, 'But Pharaoh asked him, “What have you lacked here with me that you suddenly want to go back to your own country?” “Nothing,” Hadad replied, “but please let me go.”'),
  ('BSB', '1 Kings', 11, 11, 23, 'And God raised up against Solomon another adversary, Rezon the son of Eliada, who had fled from his master, Hadadezer king of Zobah,'),
  ('BSB', '1 Kings', 11, 11, 24, 'and had gathered men to himself. When David killed the Zobaites, Rezon captained a band of raiders and went to Damascus, where they settled and gained control.'),
  ('BSB', '1 Kings', 11, 11, 25, 'Rezon was Israel’s enemy throughout the days of Solomon, adding to the trouble caused by Hadad. So Rezon ruled over Aram with hostility toward Israel.'),
  ('BSB', '1 Kings', 11, 11, 26, 'Now Jeroboam son of Nebat was an Ephraimite from Zeredah whose mother was a widow named Zeruah. Jeroboam was a servant of Solomon, but he rebelled against the king,'),
  ('BSB', '1 Kings', 11, 11, 27, 'and this is the account of his rebellion against the king. Solomon had built the supporting terraces and repaired the gap in the wall of the city of his father David.'),
  ('BSB', '1 Kings', 11, 11, 28, 'Now Jeroboam was a mighty man of valor. So when Solomon noticed that the young man was industrious, he put him in charge of the whole labor force of the house of Joseph.'),
  ('BSB', '1 Kings', 11, 11, 29, 'During that time, the prophet Ahijah the Shilonite met Jeroboam on the road as he was going out of Jerusalem. Now Ahijah had wrapped himself in a new cloak, and the two of them were alone in the open field.'),
  ('BSB', '1 Kings', 11, 11, 30, 'And Ahijah took hold of the new cloak he was wearing, tore it into twelve pieces,'),
  ('BSB', '1 Kings', 11, 11, 31, 'and said to Jeroboam, “Take ten pieces for yourself, for this is what the LORD, the God of Israel, says: ‘Behold, I will tear the kingdom out of the hand of Solomon, and I will give you ten tribes.'),
  ('BSB', '1 Kings', 11, 11, 32, 'But one tribe will remain for the sake of My servant David and for the sake of Jerusalem, the city I have chosen out of all the tribes of Israel.'),
  ('BSB', '1 Kings', 11, 11, 33, 'For they have forsaken Me to worship Ashtoreth the goddess of the Sidonians, Chemosh the god of the Moabites, and Milcom the god of the Ammonites. They have not walked in My ways, nor done what is right in My eyes, nor kept My statutes and judgments, as Solomon’s father David did.'),
  ('BSB', '1 Kings', 11, 11, 34, 'Nevertheless, I will not take the whole kingdom out of Solomon’s hand, because I have made him ruler all the days of his life for the sake of David My servant, whom I chose because he kept My commandments and statutes.'),
  ('BSB', '1 Kings', 11, 11, 35, 'But I will take ten tribes of the kingdom from the hand of his son and give them to you.'),
  ('BSB', '1 Kings', 11, 11, 36, 'I will give one tribe to his son, so that My servant David will always have a lamp before Me in Jerusalem, the city where I chose to put My Name.'),
  ('BSB', '1 Kings', 11, 11, 37, 'But as for you, I will take you, and you shall reign over all that your heart desires, and you will be king over Israel.'),
  ('BSB', '1 Kings', 11, 11, 38, 'If you listen to all that I command you, walk in My ways, and do what is right in My sight in order to keep My statutes and commandments as My servant David did, then I will be with you. I will build you a lasting dynasty just as I built for David, and I will give Israel to you.'),
  ('BSB', '1 Kings', 11, 11, 39, 'Because of this, I will humble David’s descendants—but not forever.’”'),
  ('BSB', '1 Kings', 11, 11, 40, 'Solomon therefore sought to kill Jeroboam. But Jeroboam arose and fled to Egypt, to Shishak king of Egypt, where he remained until the death of Solomon.'),
  ('BSB', '1 Kings', 11, 11, 41, 'As for the rest of the acts of Solomon—all that he did, as well as his wisdom—are they not written in the Book of the Acts of Solomon?'),
  ('BSB', '1 Kings', 11, 11, 42, 'Thus the time that Solomon reigned in Jerusalem over all Israel was forty years.'),
  ('BSB', '1 Kings', 11, 11, 43, 'And Solomon rested with his fathers and was buried in the city of his father David. And his son Rehoboam reigned in his place.'),
  ('BSB', '1 Kings', 11, 12, 1, 'Then Rehoboam went to Shechem, for all Israel had gone there to make him king.'),
  ('BSB', '1 Kings', 11, 12, 2, 'When Jeroboam son of Nebat heard about this, he was still in Egypt where he had fled from King Solomon and had been living ever since.'),
  ('BSB', '1 Kings', 11, 12, 3, 'So they sent for Jeroboam, and he and the whole assembly of Israel came to Rehoboam and said,'),
  ('BSB', '1 Kings', 11, 12, 4, '“Your father put a heavy yoke on us. But now you should lighten the burden of your father’s service and the heavy yoke he put on us, and we will serve you.”'),
  ('BSB', '1 Kings', 11, 12, 5, 'Rehoboam answered, “Go away for three days and then return to me.” So the people departed.'),
  ('BSB', '1 Kings', 11, 12, 6, 'Then King Rehoboam consulted with the elders who had served his father Solomon during his lifetime. “How do you advise me to respond to these people?” he asked.'),
  ('BSB', '1 Kings', 11, 12, 7, 'They replied, “If you will be a servant to these people and serve them this day, and if you will respond by speaking kind words to them, they will be your servants forever.”'),
  ('BSB', '1 Kings', 11, 12, 8, 'But Rehoboam rejected the advice of the elders; instead, he consulted the young men who had grown up with him and served him.'),
  ('BSB', '1 Kings', 11, 12, 9, 'He asked them, “What message do you advise that we send back to these people who have spoken to me, saying, ‘Lighten the yoke your father put on us’?”'),
  ('BSB', '1 Kings', 11, 12, 10, 'The young men who had grown up with him replied, “This is how you should answer these people who said to you, ‘Your father made our yoke heavy, but you should make it lighter.’ This is what you should tell them: ‘My little finger is thicker than my father’s waist!'),
  ('BSB', '1 Kings', 11, 12, 11, 'Whereas my father burdened you with a heavy yoke, I will add to your yoke. Whereas my father scourged you with whips, I will scourge you with scorpions.’”'),
  ('BSB', '1 Kings', 11, 12, 12, 'After three days, Jeroboam and all the people returned to Rehoboam, since the king had said, “Come back to me on the third day.”'),
  ('BSB', '1 Kings', 11, 12, 13, 'And the king answered the people harshly. He rejected the advice of the elders'),
  ('BSB', '1 Kings', 11, 12, 14, 'and spoke to them as the young men had advised, saying, “Whereas my father made your yoke heavy, I will add to your yoke. Whereas my father scourged you with whips, I will scourge you with scorpions.”'),
  ('BSB', '1 Kings', 11, 12, 15, 'So the king did not listen to the people, and indeed this turn of events was from the LORD, to fulfill the word He had spoken to Jeroboam son of Nebat through Ahijah the Shilonite.'),
  ('BSB', '1 Kings', 11, 12, 16, 'When all Israel saw that the king had refused to listen to them, they answered the king: “What portion do we have in David, and what inheritance in the son of Jesse? To your tents, O Israel! Look now to your own house, O David!” So the Israelites went home,'),
  ('BSB', '1 Kings', 11, 12, 17, 'but Rehoboam still reigned over the Israelites living in the cities of Judah.'),
  ('BSB', '1 Kings', 11, 12, 18, 'Then King Rehoboam sent out Adoram, who was in charge of the forced labor, but all Israel stoned him to death. And King Rehoboam mounted his chariot in haste and escaped to Jerusalem.'),
  ('BSB', '1 Kings', 11, 12, 19, 'So to this day Israel has been in rebellion against the house of David.'),
  ('BSB', '1 Kings', 11, 12, 20, 'When all Israel heard that Jeroboam had returned, they summoned him to the assembly and made him king over all Israel. Only the tribe of Judah followed the house of David.'),
  ('BSB', '1 Kings', 11, 12, 21, 'And when Rehoboam arrived in Jerusalem, he mobilized the whole house of Judah and the tribe of Benjamin—180,000 chosen warriors—to fight against the house of Israel and restore the kingdom to Rehoboam son of Solomon.'),
  ('BSB', '1 Kings', 11, 12, 22, 'But the word of God came to Shemaiah the man of God:'),
  ('BSB', '1 Kings', 11, 12, 23, '“Tell Rehoboam son of Solomon king of Judah, all the house of Judah and Benjamin, and the rest of the people'),
  ('BSB', '1 Kings', 11, 12, 24, 'that this is what the LORD says: ‘You are not to go up and fight against your brothers, the Israelites. Each of you must return home, for this word is from Me.’” So they listened to the word of the LORD and turned back according to the word of the LORD.'),
  ('BSB', '1 Kings', 11, 12, 25, 'Then Jeroboam built Shechem in the hill country of Ephraim and lived there. And from there he went out and built Penuel.'),
  ('BSB', '1 Kings', 11, 12, 26, 'Jeroboam said in his heart, “Now the kingdom might revert to the house of David.'),
  ('BSB', '1 Kings', 11, 12, 27, 'If these people go up to offer sacrifices in the house of the LORD at Jerusalem, their hearts will return to their lord, Rehoboam king of Judah; then they will kill me and return to Rehoboam king of Judah.”'),
  ('BSB', '1 Kings', 11, 12, 28, 'After seeking advice, the king made two golden calves and said to the people, “Going up to Jerusalem is too much for you. Here, O Israel, are your gods, who brought you up out of the land of Egypt.”'),
  ('BSB', '1 Kings', 11, 12, 29, 'One calf he set up in Bethel, and the other in Dan.'),
  ('BSB', '1 Kings', 11, 12, 30, 'And this thing became a sin; the people walked as far as Dan to worship before one of the calves.'),
  ('BSB', '1 Kings', 11, 12, 31, 'Jeroboam also built shrines on the high places and appointed from every class of people priests who were not Levites.'),
  ('BSB', '1 Kings', 11, 12, 32, 'And Jeroboam ordained a feast on the fifteenth day of the eighth month, like the feast that was in Judah, and he offered sacrifices on the altar; he made this offering in Bethel to sacrifice to the calves he had set up, and he installed priests in Bethel for the high places he had set up.'),
  ('BSB', '1 Kings', 11, 12, 33, 'On the fifteenth day of the eighth month, a month of his own choosing, Jeroboam offered sacrifices on the altar he had set up in Bethel. So he ordained a feast for the Israelites, offered sacrifices on the altar, and burned incense.'),
  ('BSB', '1 Kings', 11, 13, 1, 'Suddenly, as Jeroboam was standing beside the altar to burn incense, there came a man of God from Judah to Bethel by the word of the LORD.'),
  ('BSB', '1 Kings', 11, 13, 2, 'And he cried out against the altar by the word of the LORD, “O altar, O altar, this is what the LORD says: ‘A son named Josiah will be born to the house of David, and upon you he will sacrifice the priests of the high places who burn incense upon you, and human bones will be burned upon you.’”'),
  ('BSB', '1 Kings', 11, 13, 3, 'That day the man of God gave a sign, saying, “The LORD has spoken this sign: ‘Surely the altar will be split apart, and the ashes upon it will be poured out.’”'),
  ('BSB', '1 Kings', 11, 13, 4, 'Now when King Jeroboam, who was at the altar in Bethel, heard the word that the man of God had cried out against it, he stretched out his hand and said, “Seize him!” But the hand he stretched out toward him withered, so that he could not pull it back.'),
  ('BSB', '1 Kings', 11, 13, 5, 'And the altar was split apart, and the ashes poured out, according to the sign that the man of God had given by the word of the LORD.'),
  ('BSB', '1 Kings', 11, 13, 6, 'Then the king responded to the man of God, “Intercede with the LORD your God and pray that my hand may be restored.” So the man of God interceded with the LORD, and the king’s hand was restored to him as it was before.'),
  ('BSB', '1 Kings', 11, 13, 7, 'Then the king said to the man of God, “Come home with me and refresh yourself, and I will give you a reward.”'),
  ('BSB', '1 Kings', 11, 13, 8, 'But the man of God replied, “If you were to give me half your possessions, I still would not go with you, nor would I eat bread or drink water in this place.'),
  ('BSB', '1 Kings', 11, 13, 9, 'For this is what I was commanded by the word of the LORD: ‘You must not eat bread or drink water or return by the way you came.’”'),
  ('BSB', '1 Kings', 11, 13, 10, 'So the man of God went another way and did not return by the way he had come to Bethel.'),
  ('BSB', '1 Kings', 11, 13, 11, 'Now a certain old prophet was living in Bethel, and his sons came and told him all the deeds that the man of God had done that day in Bethel. They also told their father the words that the man had spoken to the king.'),
  ('BSB', '1 Kings', 11, 13, 12, '“Which way did he go?” their father asked. And his sons showed him the way taken by the man of God, who had come from Judah.'),
  ('BSB', '1 Kings', 11, 13, 13, 'So the prophet said to his sons, “Saddle the donkey for me.” Then they saddled the donkey for him, and he mounted it'),
  ('BSB', '1 Kings', 11, 13, 14, 'and went after the man of God. He found him sitting under an oak tree and asked, “Are you the man of God who came from Judah?” “I am,” he replied.'),
  ('BSB', '1 Kings', 11, 13, 15, 'So the prophet said to the man of God, “Come home with me and eat some bread.”');
insert into control_room_bible (version, book, book_num, chapter, verse, text) values
  ('BSB', '1 Kings', 11, 13, 16, 'But the man replied, “I cannot return with you or eat bread or drink water with you in this place.'),
  ('BSB', '1 Kings', 11, 13, 17, 'For I have been told by the word of the LORD: ‘You must not eat bread or drink water there or return by the way you came.’”'),
  ('BSB', '1 Kings', 11, 13, 18, 'Then the prophet replied, “I too am a prophet like you, and an angel spoke to me by the word of the LORD, saying, ‘Bring him back with you to your house, so that he may eat bread and drink water.’” The old prophet was lying to him,'),
  ('BSB', '1 Kings', 11, 13, 19, 'but the man of God went back with him, ate bread in his house, and drank water.'),
  ('BSB', '1 Kings', 11, 13, 20, 'While they were sitting at the table, the word of the LORD came to the prophet who had brought him back,'),
  ('BSB', '1 Kings', 11, 13, 21, 'and the prophet cried out to the man of God who had come from Judah, “This is what the LORD says: ‘Because you have defied the word of the LORD and have not kept the commandment that the LORD your God gave you,'),
  ('BSB', '1 Kings', 11, 13, 22, 'but you went back and ate bread and drank water in the place where He told you not to do so, your body shall never reach the tomb of your fathers.’”'),
  ('BSB', '1 Kings', 11, 13, 23, 'And after the man of God had finished eating and drinking, the old prophet who had brought him back saddled the donkey for him.'),
  ('BSB', '1 Kings', 11, 13, 24, 'As he went on his way, a lion met him on the road and killed him, and his body was left lying in the road, with the donkey and the lion standing beside it.'),
  ('BSB', '1 Kings', 11, 13, 25, 'And there were men passing by who saw the body lying in the road with the lion standing beside it, and they went and reported this in the city where the old prophet lived.'),
  ('BSB', '1 Kings', 11, 13, 26, 'When the prophet who had brought him back from his journey heard this, he said, “It is the man of God who disobeyed the command of the LORD. Therefore the LORD has delivered him to the lion, and it has mauled him and killed him, according to the word that the LORD had spoken to him.”'),
  ('BSB', '1 Kings', 11, 13, 27, 'Then the old prophet instructed his sons, “Saddle the donkey for me.” So they saddled it,'),
  ('BSB', '1 Kings', 11, 13, 28, 'and he went and found the body lying in the road, with the donkey and the lion standing beside it. The lion had not eaten the body or mauled the donkey.'),
  ('BSB', '1 Kings', 11, 13, 29, 'So the old prophet lifted up the body of the man of God, laid it on the donkey, and brought it back to his own city to mourn for him and bury him.'),
  ('BSB', '1 Kings', 11, 13, 30, 'Then he laid the body in his own tomb, and they lamented over him, “Oh, my brother!”'),
  ('BSB', '1 Kings', 11, 13, 31, 'After he had buried him, the prophet said to his sons, “When I die, you must bury me in the tomb where the man of God is buried. Lay my bones beside his bones,'),
  ('BSB', '1 Kings', 11, 13, 32, 'for the message that he cried out by the word of the LORD against the altar in Bethel and against all the shrines on the high places in the cities of Samaria will surely come to pass.”'),
  ('BSB', '1 Kings', 11, 13, 33, 'Even after these events, Jeroboam did not repent of his evil ways, but again he appointed priests for the high places from every class of people. He ordained anyone who desired to be a priest of the high places.'),
  ('BSB', '1 Kings', 11, 13, 34, 'And this was the sin of the house of Jeroboam that led to its extermination and destruction from the face of the earth.'),
  ('BSB', '1 Kings', 11, 14, 1, 'At that time Abijah son of Jeroboam became ill,'),
  ('BSB', '1 Kings', 11, 14, 2, 'and Jeroboam said to his wife, “Now get up, disguise yourself so they will not recognize you as my wife, and go to Shiloh. For Ahijah the prophet is there; it was he who spoke about my kingship over this people.'),
  ('BSB', '1 Kings', 11, 14, 3, 'Take with you ten loaves of bread, some cakes, and a jar of honey, and go to him. He will tell you what will become of the boy.”'),
  ('BSB', '1 Kings', 11, 14, 4, 'Jeroboam’s wife did as instructed; she arose and went to Shiloh and arrived at Ahijah’s house. Now Ahijah could not see, for his eyes were dim because of his age.'),
  ('BSB', '1 Kings', 11, 14, 5, 'But the LORD had said to Ahijah, “Behold, the wife of Jeroboam is coming to ask you about her son, for he is ill. You are to say such and such to her, because when she arrives, she will be disguised.”'),
  ('BSB', '1 Kings', 11, 14, 6, 'So when Ahijah heard the sound of her feet entering the door, he said, “Come in, wife of Jeroboam! Why are you disguised? For I have been sent to you with bad news.'),
  ('BSB', '1 Kings', 11, 14, 7, 'Go, tell Jeroboam that this is what the LORD, the God of Israel, says: ‘I raised you up from among the people and appointed you ruler over My people Israel.'),
  ('BSB', '1 Kings', 11, 14, 8, 'I tore the kingdom away from the house of David and gave it to you. But you were not like My servant David, who kept My commandments and followed Me with all his heart, doing only what was right in My eyes.'),
  ('BSB', '1 Kings', 11, 14, 9, 'You have done more evil than all who came before you. You have proceeded to make for yourself other gods and molten images to provoke Me, and you have flung Me behind your back.'),
  ('BSB', '1 Kings', 11, 14, 10, 'Because of all this, behold, I am bringing disaster on the house of Jeroboam: I will cut off from Jeroboam every male, both slave and free, in Israel; I will burn up the house of Jeroboam as one burns up dung until it is gone!'),
  ('BSB', '1 Kings', 11, 14, 11, 'Anyone belonging to Jeroboam who dies in the city will be eaten by dogs, and anyone who dies in the field will be eaten by the birds of the air.’ For the LORD has spoken.'),
  ('BSB', '1 Kings', 11, 14, 12, 'As for you, get up and go home. When your feet enter the city, the child will die.'),
  ('BSB', '1 Kings', 11, 14, 13, 'All Israel will mourn for him and bury him. For this is the only one belonging to Jeroboam who will receive a proper burial, because only in him has the LORD, the God of Israel, found any good in the house of Jeroboam.'),
  ('BSB', '1 Kings', 11, 14, 14, 'Moreover, the LORD will raise up for Himself a king over Israel who will cut off the house of Jeroboam. This is the day—yes, even today!'),
  ('BSB', '1 Kings', 11, 14, 15, 'For the LORD will strike Israel as a reed is shaken in the water. He will uproot Israel from this good land that He gave their fathers, and He will scatter them beyond the Euphrates, because they have made their Asherah poles, provoking the LORD to anger.'),
  ('BSB', '1 Kings', 11, 14, 16, 'So He will give Israel over on account of the sins Jeroboam has committed and has caused Israel to commit.”'),
  ('BSB', '1 Kings', 11, 14, 17, 'Then Jeroboam’s wife got up and departed for Tirzah, and as soon as she stepped over the threshold of the house, the boy died.'),
  ('BSB', '1 Kings', 11, 14, 18, 'And they buried him, and all Israel mourned for him, according to the word that the LORD had spoken through His servant Ahijah the prophet.'),
  ('BSB', '1 Kings', 11, 14, 19, 'As for the rest of the acts of Jeroboam, how he waged war and how he reigned, they are indeed written in the Book of the Chronicles of the Kings of Israel.'),
  ('BSB', '1 Kings', 11, 14, 20, 'And the length of Jeroboam’s reign was twenty-two years, and he rested with his fathers, and his son Nadab reigned in his place.'),
  ('BSB', '1 Kings', 11, 14, 21, 'Meanwhile, Rehoboam son of Solomon reigned in Judah. He was forty-one years old when he became king, and he reigned seventeen years in Jerusalem, the city the LORD had chosen from all the tribes of Israel in which to put His Name. His mother’s name was Naamah the Ammonite.'),
  ('BSB', '1 Kings', 11, 14, 22, 'And Judah did evil in the sight of the LORD, and by the sins they committed they provoked Him to jealous anger more than all their fathers had done.'),
  ('BSB', '1 Kings', 11, 14, 23, 'They also built for themselves high places, sacred pillars, and Asherah poles on every high hill and under every green tree.'),
  ('BSB', '1 Kings', 11, 14, 24, 'There were even male shrine prostitutes in the land. They imitated all the abominations of the nations the LORD had driven out before the Israelites.'),
  ('BSB', '1 Kings', 11, 14, 25, 'In the fifth year of Rehoboam’s reign, Shishak king of Egypt came up and attacked Jerusalem.'),
  ('BSB', '1 Kings', 11, 14, 26, 'He seized the treasures of the house of the LORD and of the royal palace. He took everything, including all the gold shields that Solomon had made.'),
  ('BSB', '1 Kings', 11, 14, 27, 'Then King Rehoboam made bronze shields in their place and committed them to the care of the captains of the guard on duty at the entrance to the royal palace.'),
  ('BSB', '1 Kings', 11, 14, 28, 'And whenever the king entered the house of the LORD, the guards would bear the shields, and later they would return them to the guardroom.'),
  ('BSB', '1 Kings', 11, 14, 29, 'As for the rest of the acts of Rehoboam, along with all that he did, are they not written in the Book of the Chronicles of the Kings of Judah?'),
  ('BSB', '1 Kings', 11, 14, 30, 'There was war between Rehoboam and Jeroboam throughout their days.'),
  ('BSB', '1 Kings', 11, 14, 31, 'And Rehoboam rested with his fathers and was buried with them in the City of David; his mother’s name was Naamah the Ammonite. And his son Abijam reigned in his place.'),
  ('BSB', '1 Kings', 11, 15, 1, 'In the eighteenth year of the reign of Jeroboam son of Nebat, Abijam became king of Judah,'),
  ('BSB', '1 Kings', 11, 15, 2, 'and he reigned in Jerusalem three years. His mother’s name was Maacah daughter of Abishalom.'),
  ('BSB', '1 Kings', 11, 15, 3, 'And Abijam walked in all the sins that his father before him had committed, and his heart was not as fully devoted to the LORD his God as the heart of David his forefather had been.'),
  ('BSB', '1 Kings', 11, 15, 4, 'Nevertheless, for the sake of David, the LORD his God gave him a lamp in Jerusalem by raising up a son to succeed him and to make Jerusalem strong.'),
  ('BSB', '1 Kings', 11, 15, 5, 'For David had done what was right in the eyes of the LORD and had not turned aside from anything the LORD commanded all the days of his life, except in the matter of Uriah the Hittite.'),
  ('BSB', '1 Kings', 11, 15, 6, 'And there was war between the houses of Rehoboam and Jeroboam all the days of Abijam’s life.'),
  ('BSB', '1 Kings', 11, 15, 7, 'As for the rest of the acts of Abijam, along with all his accomplishments, are they not written in the Book of the Chronicles of the Kings of Judah? And there was war between Abijam and Jeroboam.'),
  ('BSB', '1 Kings', 11, 15, 8, 'And Abijam rested with his fathers and was buried in the City of David, and his son Asa reigned in his place.'),
  ('BSB', '1 Kings', 11, 15, 9, 'In the twentieth year of Jeroboam’s reign over Israel, Asa became king of Judah,'),
  ('BSB', '1 Kings', 11, 15, 10, 'and he reigned in Jerusalem forty-one years. His grandmother’s name was Maacah daughter of Abishalom.'),
  ('BSB', '1 Kings', 11, 15, 11, 'And Asa did what was right in the eyes of the LORD, as his father David had done.'),
  ('BSB', '1 Kings', 11, 15, 12, 'He banished the male shrine prostitutes from the land and removed all the idols that his fathers had made.'),
  ('BSB', '1 Kings', 11, 15, 13, 'He also removed his grandmother Maacah from her position as queen mother because she had made a detestable Asherah pole. Asa chopped down the pole and burned it in the Kidron Valley.'),
  ('BSB', '1 Kings', 11, 15, 14, 'The high places were not removed, but Asa’s heart was fully devoted to the LORD all his days.'),
  ('BSB', '1 Kings', 11, 15, 15, 'And he brought into the house of the LORD the silver and gold and other articles that he and his father had dedicated.'),
  ('BSB', '1 Kings', 11, 15, 16, 'Now there was war between Asa and Baasha king of Israel throughout their days.'),
  ('BSB', '1 Kings', 11, 15, 17, 'Baasha king of Israel went to war against Judah and fortified Ramah to prevent anyone from leaving or entering the territory of Asa king of Judah.'),
  ('BSB', '1 Kings', 11, 15, 18, 'So Asa withdrew all the silver and gold that remained in the treasuries of the house of the LORD and the royal palace. He entrusted it to his servants and sent them with this message to Ben-hadad son of Tabrimmon, the son of Hezion king of Aram, who was ruling in Damascus:'),
  ('BSB', '1 Kings', 11, 15, 19, '“Let there be a treaty between me and you, between my father and your father. See, I have sent you a gift of silver and gold. Now go and break your treaty with Baasha king of Israel, so that he will withdraw from me.”'),
  ('BSB', '1 Kings', 11, 15, 20, 'And Ben-hadad listened to King Asa and sent the commanders of his armies against the cities of Israel, conquering Ijon, Dan, Abel-beth-maacah, and the whole land of Naphtali, including the region of Chinnereth.'),
  ('BSB', '1 Kings', 11, 15, 21, 'When Baasha learned of this, he stopped fortifying Ramah and withdrew to Tirzah.'),
  ('BSB', '1 Kings', 11, 15, 22, 'Then King Asa summoned all the men of Judah, with no exceptions, and they carried away the stones of Ramah and the timbers Baasha had used for building. And with these materials King Asa built up Geba of Benjamin, as well as Mizpah.'),
  ('BSB', '1 Kings', 11, 15, 23, 'Now the rest of the acts of Asa, along with all his might, all his accomplishments, and the cities he built, are they not written in the Book of the Chronicles of the Kings of Judah? In his old age, however, he became diseased in his feet.'),
  ('BSB', '1 Kings', 11, 15, 24, 'And Asa rested with his fathers and was buried with them in the city of his father David, and his son Jehoshaphat reigned in his place.'),
  ('BSB', '1 Kings', 11, 15, 25, 'In the second year of Asa’s reign over Judah, Nadab son of Jeroboam became king of Israel, and he reigned two years.'),
  ('BSB', '1 Kings', 11, 15, 26, 'And he did evil in the sight of the LORD and walked in the way of his father and in his sin, which he had caused Israel to commit.'),
  ('BSB', '1 Kings', 11, 15, 27, 'Then Baasha son of Ahijah of the house of Issachar conspired against Nadab, and Baasha struck him down at Gibbethon of the Philistines while Nadab and all Israel were besieging the city.'),
  ('BSB', '1 Kings', 11, 15, 28, 'In the third year of Asa’s reign over Judah, Baasha killed Nadab and reigned in his place.'),
  ('BSB', '1 Kings', 11, 15, 29, 'As soon as Baasha became king, he struck down the entire household of Jeroboam. He did not leave to Jeroboam anyone that breathed, but destroyed them all according to the word that the LORD had spoken through His servant Ahijah the Shilonite,'),
  ('BSB', '1 Kings', 11, 15, 30, 'because of the sins Jeroboam had committed and had caused Israel to commit, and because he had provoked the LORD, the God of Israel, to anger.'),
  ('BSB', '1 Kings', 11, 15, 31, 'As for the rest of the acts of Nadab, along with all his accomplishments, are they not written in the Book of the Chronicles of the Kings of Israel?'),
  ('BSB', '1 Kings', 11, 15, 32, 'And there was war between Asa and Baasha king of Israel throughout their days.'),
  ('BSB', '1 Kings', 11, 15, 33, 'In the third year of Asa’s reign over Judah, Baasha son of Ahijah became king of all Israel, and he reigned in Tirzah twenty-four years.'),
  ('BSB', '1 Kings', 11, 15, 34, 'And Baasha did evil in the sight of the LORD and walked in the way of Jeroboam and in his sin, which he had caused Israel to commit.'),
  ('BSB', '1 Kings', 11, 16, 1, 'Then the word of the LORD came to Jehu son of Hanani against Baasha, saying:'),
  ('BSB', '1 Kings', 11, 16, 2, '“Even though I lifted you out of the dust and made you ruler over My people Israel, you have walked in the way of Jeroboam and have caused My people Israel to sin and to provoke Me to anger by their sins.'),
  ('BSB', '1 Kings', 11, 16, 3, 'So now I will consume Baasha and his house, and I will make your house like that of Jeroboam son of Nebat:'),
  ('BSB', '1 Kings', 11, 16, 4, 'Anyone belonging to Baasha who dies in the city will be eaten by dogs, and anyone who dies in the field will be eaten by the birds of the air.”'),
  ('BSB', '1 Kings', 11, 16, 5, 'As for the rest of the acts of Baasha, along with his accomplishments and might, are they not written in the Book of the Chronicles of the Kings of Israel?'),
  ('BSB', '1 Kings', 11, 16, 6, 'And Baasha rested with his fathers and was buried in Tirzah, and his son Elah reigned in his place.'),
  ('BSB', '1 Kings', 11, 16, 7, 'Moreover, the word of the LORD came through the prophet Jehu son of Hanani against Baasha and his house, because of all the evil he had done in the sight of the LORD, provoking Him to anger with the work of his hands and becoming like the house of Jeroboam, and also because Baasha had struck down the house of Jeroboam.'),
  ('BSB', '1 Kings', 11, 16, 8, 'In the twenty-sixth year of Asa’s reign over Judah, Elah son of Baasha became king of Israel, and he reigned in Tirzah two years.'),
  ('BSB', '1 Kings', 11, 16, 9, 'However, while Elah was in Tirzah getting drunk in the house of Arza the steward of his household there, Elah’s servant Zimri, the commander of half his chariots, conspired against him.'),
  ('BSB', '1 Kings', 11, 16, 10, 'So in the twenty-seventh year of Asa’s reign over Judah, Zimri went in, struck Elah down, and killed him. And Zimri reigned in his place.'),
  ('BSB', '1 Kings', 11, 16, 11, 'As soon as Zimri began to reign and was seated on the throne, he struck down the entire household of Baasha. He did not leave a single male, whether a kinsman or friend.'),
  ('BSB', '1 Kings', 11, 16, 12, 'So Zimri destroyed the entire household of Baasha, according to the word that the LORD had spoken against Baasha through Jehu the prophet.'),
  ('BSB', '1 Kings', 11, 16, 13, 'This happened because of all the sins Baasha and his son Elah had committed and had caused Israel to commit, provoking the LORD, the God of Israel, to anger with their worthless idols.'),
  ('BSB', '1 Kings', 11, 16, 14, 'As for the rest of the acts of Elah, along with all his accomplishments, are they not written in the Book of the Chronicles of the Kings of Israel?'),
  ('BSB', '1 Kings', 11, 16, 15, 'In the twenty-seventh year of Asa’s reign over Judah, Zimri reigned in Tirzah for seven days. Now the troops were encamped against Gibbethon of the Philistines,'),
  ('BSB', '1 Kings', 11, 16, 16, 'and the people in the camp heard that Zimri had not only conspired but had also struck down the king. So there in the camp that very day, all Israel proclaimed Omri, the commander of the army, king over Israel.'),
  ('BSB', '1 Kings', 11, 16, 17, 'Then Omri and all the Israelites marched up from Gibbethon and besieged Tirzah.'),
  ('BSB', '1 Kings', 11, 16, 18, 'When Zimri saw that the city was captured, he entered the citadel of the royal palace and burned it down upon himself. So he died'),
  ('BSB', '1 Kings', 11, 16, 19, 'because of the sins he had committed, doing evil in the sight of the LORD and following the example of Jeroboam and the sin he had committed and had caused Israel to commit.'),
  ('BSB', '1 Kings', 11, 16, 20, 'As for the rest of the acts of Zimri and the treason he committed, are they not written in the Book of the Chronicles of the Kings of Israel?'),
  ('BSB', '1 Kings', 11, 16, 21, 'At that time the people of Israel were divided: Half of the people supported Tibni son of Ginath as king, and half supported Omri.'),
  ('BSB', '1 Kings', 11, 16, 22, 'But the followers of Omri proved stronger than those of Tibni son of Ginath. So Tibni died and Omri became king.'),
  ('BSB', '1 Kings', 11, 16, 23, 'In the thirty-first year of Asa’s reign over Judah, Omri became king of Israel, and he reigned twelve years, six of them in Tirzah.'),
  ('BSB', '1 Kings', 11, 16, 24, 'He bought the hill of Samaria from Shemer for two talents of silver and built a city there, calling it Samaria after the name of Shemer, who had owned the hill.'),
  ('BSB', '1 Kings', 11, 16, 25, 'But Omri did evil in the sight of the LORD and acted more wickedly than all who were before him.'),
  ('BSB', '1 Kings', 11, 16, 26, 'For he walked in all the ways of Jeroboam son of Nebat and in his sins, which he caused Israel to commit, provoking the LORD, the God of Israel, to anger with their worthless idols.'),
  ('BSB', '1 Kings', 11, 16, 27, 'As for the rest of the acts of Omri, along with his accomplishments and the might he exercised, are they not written in the Book of the Chronicles of the Kings of Israel?'),
  ('BSB', '1 Kings', 11, 16, 28, 'And Omri rested with his fathers and was buried in Samaria, and his son Ahab reigned in his place.'),
  ('BSB', '1 Kings', 11, 16, 29, 'In the thirty-eighth year of Asa’s reign over Judah, Ahab son of Omri became king of Israel, and he reigned in Samaria twenty-two years.'),
  ('BSB', '1 Kings', 11, 16, 30, 'However, Ahab son of Omri did evil in the sight of the LORD, more than all who were before him.'),
  ('BSB', '1 Kings', 11, 16, 31, 'And as if it were not enough for him to walk in the sins of Jeroboam son of Nebat, he even married Jezebel the daughter of Ethbaal king of the Sidonians, and he then proceeded to serve and worship Baal.'),
  ('BSB', '1 Kings', 11, 16, 32, 'First, Ahab set up an altar for Baal in the temple of Baal that he had built in Samaria.'),
  ('BSB', '1 Kings', 11, 16, 33, 'Then he set up an Asherah pole. Thus Ahab did more to provoke the LORD, the God of Israel, to anger than all the kings of Israel before him.'),
  ('BSB', '1 Kings', 11, 16, 34, 'In Ahab’s days, Hiel the Bethelite rebuilt Jericho. At the cost of Abiram his firstborn he laid its foundation, and at the cost of Segub his youngest he set up its gates, according to the word that the LORD had spoken through Joshua son of Nun.'),
  ('BSB', '1 Kings', 11, 17, 1, 'Now Elijah the Tishbite, who was among the settlers of Gilead, said to Ahab, “As surely as the LORD lives—the God of Israel before whom I stand—there will be neither dew nor rain in these years except at my word!”'),
  ('BSB', '1 Kings', 11, 17, 2, 'Then a revelation from the LORD came to Elijah:'),
  ('BSB', '1 Kings', 11, 17, 3, '“Leave here, turn eastward, and hide yourself by the Brook of Cherith, east of the Jordan.'),
  ('BSB', '1 Kings', 11, 17, 4, 'And you are to drink from the brook, and I have commanded the ravens to feed you there.”'),
  ('BSB', '1 Kings', 11, 17, 5, 'So Elijah did what the LORD had told him, and he went and lived by the Brook of Cherith, east of the Jordan.'),
  ('BSB', '1 Kings', 11, 17, 6, 'The ravens would bring him bread and meat in the morning and evening, and he would drink from the brook.'),
  ('BSB', '1 Kings', 11, 17, 7, 'Some time later, however, the brook dried up because there had been no rain in the land.'),
  ('BSB', '1 Kings', 11, 17, 8, 'Then the word of the LORD came to Elijah:'),
  ('BSB', '1 Kings', 11, 17, 9, '“Get up and go to Zarephath of Sidon, and stay there. Behold, I have commanded a widow there to provide for you.”'),
  ('BSB', '1 Kings', 11, 17, 10, 'So Elijah got up and went to Zarephath. When he arrived at the city gate, there was a widow gathering sticks. Elijah called to her and said, “Please bring me a little water in a cup, so that I may drink.”'),
  ('BSB', '1 Kings', 11, 17, 11, 'And as she was going to get it, he called to her and said, “Please bring me a piece of bread.”'),
  ('BSB', '1 Kings', 11, 17, 12, 'But she replied, “As surely as the LORD your God lives, I have no bread—only a handful of flour in a jar and a little oil in a jug. Look, I am gathering a couple of sticks to take home and prepare a meal for myself and my son, so that we may eat it and die.”'),
  ('BSB', '1 Kings', 11, 17, 13, '“Do not be afraid,” Elijah said to her. “Go and do as you have said. But first make me a small cake of bread from what you have, and bring it out to me. Afterward, make some for yourself and your son,'),
  ('BSB', '1 Kings', 11, 17, 14, 'for this is what the LORD, the God of Israel, says: ‘The jar of flour will not be exhausted and the jug of oil will not run dry until the day the LORD sends rain upon the face of the earth.’”'),
  ('BSB', '1 Kings', 11, 17, 15, 'So she went and did according to the word of Elijah, and there was food every day for Elijah and the woman and her household.'),
  ('BSB', '1 Kings', 11, 17, 16, 'The jar of flour was not exhausted and the jug of oil did not run dry, according to the word that the LORD had spoken through Elijah.'),
  ('BSB', '1 Kings', 11, 17, 17, 'Later, the son of the woman who owned the house became ill, and his sickness grew worse and worse, until no breath remained in him.'),
  ('BSB', '1 Kings', 11, 17, 18, '“O man of God,” said the woman to Elijah, “what have you done to me? Have you come to remind me of my iniquity and cause the death of my son?”'),
  ('BSB', '1 Kings', 11, 17, 19, 'But Elijah said to her, “Give me your son.” So he took him from her arms, carried him to the upper room where he was staying, and laid him on his own bed.'),
  ('BSB', '1 Kings', 11, 17, 20, 'Then he cried out to the LORD, “O LORD my God, have You also brought tragedy on this widow who has opened her home to me, by causing her son to die?”'),
  ('BSB', '1 Kings', 11, 17, 21, 'Then he stretched himself out over the child three times and cried out to the LORD, “O LORD my God, please let this boy’s life return to him!”'),
  ('BSB', '1 Kings', 11, 17, 22, 'And the LORD listened to the voice of Elijah, and the child’s life returned to him, and he lived.'),
  ('BSB', '1 Kings', 11, 17, 23, 'Then Elijah took the child, brought him down from the upper room into the house, and gave him to his mother. “Look, your son is alive,” Elijah declared.'),
  ('BSB', '1 Kings', 11, 17, 24, 'Then the woman said to Elijah, “Now I know that you are a man of God and that the word of the LORD from your mouth is truth.”'),
  ('BSB', '1 Kings', 11, 18, 1, 'After a long time, in the third year of the drought, the word of the LORD came to Elijah: “Go and present yourself to Ahab, and I will send rain upon the face of the earth.”'),
  ('BSB', '1 Kings', 11, 18, 2, 'So Elijah went to present himself to Ahab. The famine was severe in Samaria,'),
  ('BSB', '1 Kings', 11, 18, 3, 'and Ahab summoned Obadiah, who was in charge of the palace. (Now Obadiah greatly feared the LORD,'),
  ('BSB', '1 Kings', 11, 18, 4, 'for when Jezebel had slaughtered the prophets of the LORD, Obadiah had taken a hundred prophets and hidden them, fifty men per cave, providing them with food and water.)'),
  ('BSB', '1 Kings', 11, 18, 5, 'Then Ahab said to Obadiah, “Go throughout the land to every spring and every valley. Perhaps we will find grass to keep the horses and mules alive so that we will not have to destroy any livestock.”'),
  ('BSB', '1 Kings', 11, 18, 6, 'So they divided the land to explore. Ahab went one way by himself, and Obadiah went the other way by himself.'),
  ('BSB', '1 Kings', 11, 18, 7, 'Now as Obadiah went on his way, Elijah suddenly met him. When Obadiah recognized him, he fell facedown and said, “Is it you, my lord Elijah?”'),
  ('BSB', '1 Kings', 11, 18, 8, '“It is I,” he answered. “Go tell your master, ‘Elijah is here!’”'),
  ('BSB', '1 Kings', 11, 18, 9, 'But Obadiah replied, “How have I sinned, that you are handing your servant over to Ahab to put me to death?'),
  ('BSB', '1 Kings', 11, 18, 10, 'As surely as the LORD your God lives, there is no nation or kingdom where my lord has not sent someone to search for you. When they said, ‘He is not here,’ he made that kingdom or nation swear that they had not found you.'),
  ('BSB', '1 Kings', 11, 18, 11, 'And now you say, ‘Go tell your master that Elijah is here!’'),
  ('BSB', '1 Kings', 11, 18, 12, 'I do not know where the Spirit of the LORD may carry you off when I leave you. Then when I go and tell Ahab and he does not find you, he will kill me. But I, your servant, have feared the LORD from my youth.'),
  ('BSB', '1 Kings', 11, 18, 13, 'Was it not reported to my lord what I did when Jezebel slaughtered the prophets of the LORD? I hid a hundred prophets of the LORD, fifty men per cave, and I provided them with food and water.'),
  ('BSB', '1 Kings', 11, 18, 14, 'And now you say, ‘Go tell your lord that Elijah is here!’ He will kill me!”'),
  ('BSB', '1 Kings', 11, 18, 15, 'Then Elijah said, “As surely as the LORD of Hosts lives, before whom I stand, I will present myself to Ahab today.”'),
  ('BSB', '1 Kings', 11, 18, 16, 'So Obadiah went to inform Ahab, who went to meet Elijah.'),
  ('BSB', '1 Kings', 11, 18, 17, 'When Ahab saw Elijah, he said to him, “Is that you, O troubler of Israel?”'),
  ('BSB', '1 Kings', 11, 18, 18, '“I have not troubled Israel,” Elijah replied, “but you and your father’s house have, for you have forsaken the commandments of the LORD and have followed the Baals.'),
  ('BSB', '1 Kings', 11, 18, 19, 'Now summon all Israel to meet me on Mount Carmel, along with the four hundred and fifty prophets of Baal and the four hundred prophets of Asherah who eat at Jezebel’s table.”'),
  ('BSB', '1 Kings', 11, 18, 20, 'So Ahab summoned all the Israelites and assembled the prophets on Mount Carmel.'),
  ('BSB', '1 Kings', 11, 18, 21, 'Then Elijah approached all the people and said, “How long will you waver between two opinions? If the LORD is God, follow Him. But if Baal is God, follow him.” But the people did not answer a word.'),
  ('BSB', '1 Kings', 11, 18, 22, 'Then Elijah said to the people, “I am the only remaining prophet of the LORD, but Baal has four hundred and fifty prophets.'),
  ('BSB', '1 Kings', 11, 18, 23, 'Get two bulls for us. Let the prophets of Baal choose one bull for themselves, cut it into pieces, and place it on the wood but not light the fire. And I will prepare the other bull and place it on the wood but not light the fire.'),
  ('BSB', '1 Kings', 11, 18, 24, 'Then you may call on the name of your god, and I will call on the name of the LORD. The God who answers by fire, He is God.” And all the people answered, “What you say is good.”'),
  ('BSB', '1 Kings', 11, 18, 25, 'Then Elijah said to the prophets of Baal, “Since you are so numerous, choose for yourselves one bull and prepare it first. Then call on the name of your god, but do not light the fire.”'),
  ('BSB', '1 Kings', 11, 18, 26, 'And they took the bull that was given them, prepared it, and called on the name of Baal from morning until noon, shouting, “O Baal, answer us!” But there was no sound, and no one answered as they leaped around the altar they had made.'),
  ('BSB', '1 Kings', 11, 18, 27, 'At noon Elijah began to taunt them, saying, “Shout louder, for he is a god! Perhaps he is deep in thought, or occupied, or on a journey. Perhaps he is sleeping and must be awakened!”'),
  ('BSB', '1 Kings', 11, 18, 28, 'So they shouted louder and cut themselves with knives and lances, as was their custom, until the blood gushed over them.'),
  ('BSB', '1 Kings', 11, 18, 29, 'Midday passed, and they kept on raving until the time of the evening sacrifice. But there was no response; no one answered, no one paid attention.'),
  ('BSB', '1 Kings', 11, 18, 30, 'Then Elijah said to all the people, “Come near to me.” So all the people approached him, and he repaired the altar of the LORD that had been torn down.'),
  ('BSB', '1 Kings', 11, 18, 31, 'And Elijah took twelve stones, one for each tribe of the sons of Jacob, to whom the word of the LORD had come and said, “Israel shall be your name.”'),
  ('BSB', '1 Kings', 11, 18, 32, 'And with the stones, Elijah built an altar in the name of the LORD. Then he dug a trench around the altar large enough to hold two seahs of seed.'),
  ('BSB', '1 Kings', 11, 18, 33, 'Next, he arranged the wood, cut up the bull, placed it on the wood,'),
  ('BSB', '1 Kings', 11, 18, 34, 'and said, “Fill four waterpots and pour the water on the offering and on the wood.” “Do it a second time,” he said, and they did it a second time. “Do it a third time,” he said, and they did it a third time.'),
  ('BSB', '1 Kings', 11, 18, 35, 'So the water ran down around the altar and even filled the trench.'),
  ('BSB', '1 Kings', 11, 18, 36, 'At the time of the evening sacrifice, Elijah the prophet approached the altar and said, “O LORD, God of Abraham, Isaac, and Israel, let it be known this day that You are God in Israel and that I am Your servant and have done all these things at Your command.'),
  ('BSB', '1 Kings', 11, 18, 37, 'Answer me, O LORD! Answer me, so that this people will know that You, the LORD, are God, and that You have turned their hearts back again.”'),
  ('BSB', '1 Kings', 11, 18, 38, 'Then the fire of the LORD fell and consumed the sacrifice, the wood, the stones, and the dust, and it licked up the water in the trench.'),
  ('BSB', '1 Kings', 11, 18, 39, 'When all the people saw this, they fell facedown and said, “The LORD, He is God! The LORD, He is God!”'),
  ('BSB', '1 Kings', 11, 18, 40, 'Then Elijah ordered them, “Seize the prophets of Baal! Do not let a single one escape.” So they seized them, and Elijah brought them down to the Kishon Valley and slaughtered them there.'),
  ('BSB', '1 Kings', 11, 18, 41, 'And Elijah said to Ahab, “Go up, eat and drink, for there is the sound of a heavy rain.”'),
  ('BSB', '1 Kings', 11, 18, 42, 'So Ahab went up to eat and drink. But Elijah climbed to the summit of Carmel, bent down on the ground, and put his face between his knees.'),
  ('BSB', '1 Kings', 11, 18, 43, '“Go and look toward the sea,” he said to his servant. So the servant went and looked, and he said, “There is nothing there.” Seven times Elijah said, “Go back.”'),
  ('BSB', '1 Kings', 11, 18, 44, 'On the seventh time the servant reported, “There is a cloud as small as a man’s hand rising from the sea.” And Elijah replied, “Go and tell Ahab, ‘Prepare your chariot and go down before the rain stops you.’”'),
  ('BSB', '1 Kings', 11, 18, 45, 'Meanwhile, the sky grew dark with clouds and wind, and a heavy rain began to fall. So Ahab rode away and went to Jezreel.'),
  ('BSB', '1 Kings', 11, 18, 46, 'And the hand of the LORD came upon Elijah, and he tucked his cloak into his belt and ran ahead of Ahab all the way to Jezreel.'),
  ('BSB', '1 Kings', 11, 19, 1, 'Now Ahab told Jezebel everything that Elijah had done and how he had killed all the prophets with the sword.'),
  ('BSB', '1 Kings', 11, 19, 2, 'So Jezebel sent a messenger to Elijah, saying, “May the gods deal with me, and ever so severely, if by this time tomorrow I do not make your life like the lives of those you killed!”'),
  ('BSB', '1 Kings', 11, 19, 3, 'And Elijah was afraid and ran for his life. When he came to Beersheba in Judah, he left his servant there,'),
  ('BSB', '1 Kings', 11, 19, 4, 'while he himself traveled on a day’s journey into the wilderness. He sat down under a broom tree and prayed that he might die. “I have had enough, LORD,” he said. “Take my life, for I am no better than my fathers.”'),
  ('BSB', '1 Kings', 11, 19, 5, 'Then he lay down under the broom tree and fell asleep. Suddenly an angel touched him and said, “Get up and eat.”'),
  ('BSB', '1 Kings', 11, 19, 6, 'And he looked around, and there by his head was a cake of bread baked over hot coals, and a jar of water. So he ate and drank and lay down again.'),
  ('BSB', '1 Kings', 11, 19, 7, 'A second time the angel of the LORD returned and touched him, saying, “Get up and eat, or the journey will be too much for you.”'),
  ('BSB', '1 Kings', 11, 19, 8, 'So he got up and ate and drank. And strengthened by that food, he walked forty days and forty nights until he reached Horeb, the mountain of God.'),
  ('BSB', '1 Kings', 11, 19, 9, 'There Elijah entered a cave and spent the night. And the word of the LORD came to him, saying, “What are you doing here, Elijah?”'),
  ('BSB', '1 Kings', 11, 19, 10, '“I have been very zealous for the LORD, the God of Hosts,” he replied, “but the Israelites have forsaken Your covenant, torn down Your altars, and killed Your prophets with the sword. I am the only one left, and they are seeking my life as well.”'),
  ('BSB', '1 Kings', 11, 19, 11, 'Then the LORD said, “Go out and stand on the mountain before the LORD. Behold, the LORD is about to pass by.” And a great and mighty wind tore into the mountains and shattered the rocks before the LORD, but the LORD was not in the wind. After the wind there was an earthquake, but the LORD was not in the earthquake.'),
  ('BSB', '1 Kings', 11, 19, 12, 'After the earthquake there was a fire, but the LORD was not in the fire. And after the fire came a still, small voice.'),
  ('BSB', '1 Kings', 11, 19, 13, 'When Elijah heard it, he wrapped his face in his cloak and went out and stood at the mouth of the cave. Suddenly a voice came to him and said, “What are you doing here, Elijah?”'),
  ('BSB', '1 Kings', 11, 19, 14, '“I have been very zealous for the LORD, the God of Hosts,” he replied, “but the Israelites have forsaken Your covenant, torn down Your altars, and killed Your prophets with the sword. I am the only one left, and they are seeking my life as well.”'),
  ('BSB', '1 Kings', 11, 19, 15, 'Then the LORD said to him, “Go back by the way you came, and go to the Desert of Damascus. When you arrive, you are to anoint Hazael as king over Aram.'),
  ('BSB', '1 Kings', 11, 19, 16, 'You are also to anoint Jehu son of Nimshi as king over Israel and Elisha son of Shaphat from Abel-meholah to succeed you as prophet.'),
  ('BSB', '1 Kings', 11, 19, 17, 'Then Jehu will put to death whoever escapes the sword of Hazael, and Elisha will put to death whoever escapes the sword of Jehu.'),
  ('BSB', '1 Kings', 11, 19, 18, 'Nevertheless, I have reserved seven thousand in Israel—all whose knees have not bowed to Baal and whose mouths have not kissed him.”'),
  ('BSB', '1 Kings', 11, 19, 19, 'So Elijah departed and found Elisha son of Shaphat. He was plowing with twelve teams of oxen, and he was with the twelfth team. Elijah passed by him and threw his cloak around him.'),
  ('BSB', '1 Kings', 11, 19, 20, 'So Elisha left the oxen, ran after Elijah, and said, “Please let me kiss my father and mother goodbye, and then I will follow you.” “Go on back,” Elijah replied, “for what have I done to you?”'),
  ('BSB', '1 Kings', 11, 19, 21, 'So Elisha turned back from him, took his pair of oxen, and slaughtered them. With the oxen’s equipment, he cooked the meat and gave it to the people, and they ate. Then he set out to follow and serve Elijah.'),
  ('BSB', '1 Kings', 11, 20, 1, 'Now Ben-hadad king of Aram assembled his entire army. Accompanied by thirty-two kings with their horses and chariots, he marched up, besieged Samaria, and waged war against it.'),
  ('BSB', '1 Kings', 11, 20, 2, 'Then he sent messengers into the city to Ahab king of Israel,'),
  ('BSB', '1 Kings', 11, 20, 3, 'saying, “This is what Ben-hadad says: ‘Your silver and gold are mine, and your best wives and children are mine!’”'),
  ('BSB', '1 Kings', 11, 20, 4, 'And the king of Israel replied, “Just as you say, my lord the king: I am yours, along with all that I have.”'),
  ('BSB', '1 Kings', 11, 20, 5, 'The messengers came back and said, “This is what Ben-hadad says: ‘I have sent to you to demand your silver, your gold, your wives, and your children.'),
  ('BSB', '1 Kings', 11, 20, 6, 'But about this time tomorrow I will send my servants to search your palace and the houses of your servants. They will seize and carry away all that is precious to you.’”'),
  ('BSB', '1 Kings', 11, 20, 7, 'Then the king of Israel summoned all the elders of the land and said, “Please take note and see that this man is looking for trouble, for when he demanded my wives, my children, my silver, and my gold, I did not deny him.”'),
  ('BSB', '1 Kings', 11, 20, 8, 'And the elders and the people all said, “Do not listen to him or consent to his terms.”'),
  ('BSB', '1 Kings', 11, 20, 9, 'So Ahab answered the messengers of Ben-hadad, “Tell my lord the king, ‘All that you demanded of your servant the first time I will do, but this thing I cannot do.’” So the messengers departed and relayed the message to Ben-hadad.'),
  ('BSB', '1 Kings', 11, 20, 10, 'Then Ben-hadad sent another message to Ahab: “May the gods deal with me, and ever so severely, if enough dust remains of Samaria for each of my men to have a handful.”'),
  ('BSB', '1 Kings', 11, 20, 11, 'And the king of Israel replied, “Tell him: ‘The one putting on his armor should not boast like one taking it off.’”'),
  ('BSB', '1 Kings', 11, 20, 12, 'Ben-hadad received this message while he and the kings were drinking in their tents, and he said to his servants, “Take your positions.” So they stationed themselves against the city.'),
  ('BSB', '1 Kings', 11, 20, 13, 'Meanwhile a prophet approached Ahab king of Israel and declared, “This is what the LORD says: ‘Do you see this entire great army? Behold, I will deliver it into your hand this very day, and you will know that I am the LORD.’”'),
  ('BSB', '1 Kings', 11, 20, 14, '“By whom?” Ahab asked. And the prophet replied, “This is what the LORD says: ‘By the young officers of the district governors.’” “Who will start the battle?” asked Ahab. “You will,” answered the prophet.'),
  ('BSB', '1 Kings', 11, 20, 15, 'So Ahab assembled the young officers of the district governors, and there were 232 men. And after them, he assembled the rest of the Israelite troops, 7,000 in all.'),
  ('BSB', '1 Kings', 11, 20, 16, 'They marched out at noon while Ben-hadad and the 32 kings allied with him were in their tents getting drunk.'),
  ('BSB', '1 Kings', 11, 20, 17, 'And the young officers of the district governors marched out first. Now Ben-hadad had sent out scouts, who reported to him, “Men are marching out of Samaria.”'),
  ('BSB', '1 Kings', 11, 20, 18, '“If they have marched out in peace,” he said, “take them alive. Even if they have marched out for war, take them alive.”'),
  ('BSB', '1 Kings', 11, 20, 19, 'Meanwhile, these young officers of the district governors marched out of the city, with the army behind them,'),
  ('BSB', '1 Kings', 11, 20, 20, 'and each one struck down his opponent. So the Arameans fled, with the Israelites in pursuit. But Ben-hadad king of Aram escaped on horseback with the cavalry.'),
  ('BSB', '1 Kings', 11, 20, 21, 'Then the king of Israel marched out and attacked the horses and chariots, inflicting a great slaughter on the Arameans.'),
  ('BSB', '1 Kings', 11, 20, 22, 'Afterward, the prophet approached the king of Israel and said, “Go and strengthen your position, and take note what you must do, for in the spring the king of Aram will come up against you.”'),
  ('BSB', '1 Kings', 11, 20, 23, 'Meanwhile, the servants of the king of Aram said to him, “Their gods are gods of the hills. That is why they prevailed over us. Instead, we should fight them on the plains; surely then we will prevail.'),
  ('BSB', '1 Kings', 11, 20, 24, 'So do this: Dismiss all the kings from their positions and replace them with other officers.'),
  ('BSB', '1 Kings', 11, 20, 25, 'And you must raise an army like the one you have lost—horse for horse and chariot for chariot—so we can fight the Israelites on the plain, where we will surely prevail.” And the king approved their plan and acted accordingly.'),
  ('BSB', '1 Kings', 11, 20, 26, 'In the spring, Ben-hadad mobilized the Arameans and went up to Aphek to fight against Israel.'),
  ('BSB', '1 Kings', 11, 20, 27, 'The Israelites also mobilized, gathered supplies, and marched out to meet them. The Israelites camped before them like two small flocks of goats, while the Arameans covered the countryside.'),
  ('BSB', '1 Kings', 11, 20, 28, 'Then the man of God approached the king of Israel and said, “This is what the LORD says: ‘Because the Arameans think the LORD is a god of the hills and not of the valleys, I will deliver all this great army into your hand. Then you will know that I am the LORD.’”'),
  ('BSB', '1 Kings', 11, 20, 29, 'For seven days the armies camped opposite each other, and on the seventh day the battle ensued, and the Israelites struck down the Arameans—a hundred thousand foot soldiers in one day.'),
  ('BSB', '1 Kings', 11, 20, 30, 'The rest of them fled into the city of Aphek, where the wall fell on twenty-seven thousand of the remaining men. Ben-hadad also fled to the city and hid in an inner room.'),
  ('BSB', '1 Kings', 11, 20, 31, 'Then the servants of Ben-hadad said to him, “Look now, we have heard that the kings of the house of Israel are merciful. Let us go out to the king of Israel with sackcloth around our waists and ropes around our heads. Perhaps he will spare your life.”'),
  ('BSB', '1 Kings', 11, 20, 32, 'So with sackcloth around their waists and ropes around their heads, they went to the king of Israel and said, “Your servant Ben-hadad says, ‘Please spare my life.’” And the king answered, “Is he still alive? He is my brother.”'),
  ('BSB', '1 Kings', 11, 20, 33, 'Now the men were looking for a sign of hope, and they quickly grasped at this word and replied, “Yes, your brother Ben-hadad.” “Go and get him!” said the king. Then Ben-hadad came out, and Ahab had him come up into his chariot.'),
  ('BSB', '1 Kings', 11, 20, 34, 'Ben-hadad said to him, “I will restore the cities my father took from your father; you may set up your own marketplaces in Damascus, as my father did in Samaria.” “By this treaty I release you,” Ahab replied. So he made a treaty with him and sent him away.'),
  ('BSB', '1 Kings', 11, 20, 35, 'Meanwhile, by the word of the LORD, one of the sons of the prophets said to his companion, “Strike me, please!” But the man refused to strike him.'),
  ('BSB', '1 Kings', 11, 20, 36, 'Then the prophet said to him, “Because you have not obeyed the voice of the LORD, as soon as you depart from me a lion will kill you.” And when he left, a lion found him and killed him.'),
  ('BSB', '1 Kings', 11, 20, 37, 'Then the prophet found another man and said, “Strike me, please!” So the man struck him and wounded him,'),
  ('BSB', '1 Kings', 11, 20, 38, 'and the prophet went and waited on the road for the king, disguising himself with a bandage over his eyes.'),
  ('BSB', '1 Kings', 11, 20, 39, 'As the king passed by, he cried out to the king: “Your servant had marched out into the middle of the battle, when suddenly a man came over with a captive and told me, ‘Guard this man! If he goes missing for any reason, your life will be exchanged for his life, or you will weigh out a talent of silver.’'),
  ('BSB', '1 Kings', 11, 20, 40, 'But while your servant was busy here and there, the man disappeared.” And the king of Israel said to him, “So shall your judgment be; you have pronounced it on yourself.”'),
  ('BSB', '1 Kings', 11, 20, 41, 'Then the prophet quickly removed the bandage from his eyes, and the king of Israel recognized him as one of the prophets.'),
  ('BSB', '1 Kings', 11, 20, 42, 'And the prophet said to the king, “This is what the LORD says: ‘Because you have let slip from your hand the man I had devoted to destruction, your life will be exchanged for his life, and your people for his people.’”'),
  ('BSB', '1 Kings', 11, 20, 43, 'Sullen and angry, the king of Israel went home to Samaria.'),
  ('BSB', '1 Kings', 11, 21, 1, 'Some time later, Naboth the Jezreelite happened to own a vineyard in Jezreel next to the palace of Ahab king of Samaria.'),
  ('BSB', '1 Kings', 11, 21, 2, 'So Ahab said to Naboth, “Give me your vineyard to use as a vegetable garden, since it is next to my palace. I will give you a better vineyard in its place—or if you prefer, I will give you its value in silver.”'),
  ('BSB', '1 Kings', 11, 21, 3, 'But Naboth replied, “The LORD forbid that I should give you the inheritance of my fathers.”'),
  ('BSB', '1 Kings', 11, 21, 4, 'So Ahab went to his palace, sullen and angry because Naboth the Jezreelite had told him, “I will not give you the inheritance of my fathers.” He lay down on his bed, turned his face away, and refused to eat.'),
  ('BSB', '1 Kings', 11, 21, 5, 'Soon his wife Jezebel came in and asked, “Why are you so sullen that you refuse to eat?”'),
  ('BSB', '1 Kings', 11, 21, 6, 'Ahab answered, “Because I spoke to Naboth the Jezreelite and told him, ‘Give me your vineyard for silver, or if you wish, I will give you another vineyard in its place.’ And he replied, ‘I will not give you my vineyard!’”'),
  ('BSB', '1 Kings', 11, 21, 7, 'But his wife Jezebel said to him, “Do you not reign over Israel? Get up, eat some food, and be cheerful, for I will get you the vineyard of Naboth the Jezreelite.”'),
  ('BSB', '1 Kings', 11, 21, 8, 'Then Jezebel wrote letters in Ahab’s name, sealed them with his seal, and sent them to the elders and nobles who lived with Naboth in his city.'),
  ('BSB', '1 Kings', 11, 21, 9, 'In the letters she wrote: “Proclaim a fast and give Naboth a seat of honor among the people.'),
  ('BSB', '1 Kings', 11, 21, 10, 'But seat two scoundrels opposite him and have them testify, ‘You have cursed both God and the king!’ Then take him out and stone him to death.”'),
  ('BSB', '1 Kings', 11, 21, 11, 'So the elders and nobles who lived in Naboth’s city did as Jezebel had instructed in the letters she had written to them.'),
  ('BSB', '1 Kings', 11, 21, 12, 'They proclaimed a fast and gave Naboth a seat of honor among the people.'),
  ('BSB', '1 Kings', 11, 21, 13, 'And the two scoundrels came in and sat opposite Naboth, and these men testified against him before the people, saying, “Naboth has cursed both God and the king!” So they took him outside the city and stoned him to death.'),
  ('BSB', '1 Kings', 11, 21, 14, 'Then they sent word to Jezebel: “Naboth has been stoned to death.”'),
  ('BSB', '1 Kings', 11, 21, 15, 'When Jezebel heard that Naboth had been stoned to death, she said to Ahab, “Get up and take possession of the vineyard of Naboth the Jezreelite, who refused to give it to you for silver. For Naboth is no longer alive, but dead.”'),
  ('BSB', '1 Kings', 11, 21, 16, 'And when Ahab heard that Naboth was dead, he got up and went down to take possession of the vineyard of Naboth the Jezreelite.'),
  ('BSB', '1 Kings', 11, 21, 17, 'Then the word of the LORD came to Elijah the Tishbite, saying,'),
  ('BSB', '1 Kings', 11, 21, 18, '“Get up and go down to meet Ahab king of Israel, who is in Samaria. See, he is in the vineyard of Naboth, of which he has gone to take possession.'),
  ('BSB', '1 Kings', 11, 21, 19, 'Tell him that this is what the LORD says: ‘Have you not murdered a man and seized his land?’ Then tell him that this is also what the LORD says: ‘In the place where the dogs licked up the blood of Naboth, there also the dogs will lick up your blood—yes, yours!’”'),
  ('BSB', '1 Kings', 11, 21, 20, 'When Elijah arrived, Ahab said to him, “So you have found me out, my enemy.” He replied, “I have found you out because you have sold yourself to do evil in the sight of the LORD.'),
  ('BSB', '1 Kings', 11, 21, 21, 'This is what the LORD says: ‘I will bring calamity on you and consume your descendants; I will cut off from Ahab every male in Israel, both slave and free.'),
  ('BSB', '1 Kings', 11, 21, 22, 'I will make your house like that of Jeroboam son of Nebat and like that of Baasha son of Ahijah, because you have provoked My anger and caused Israel to sin.’'),
  ('BSB', '1 Kings', 11, 21, 23, 'And the LORD also speaks concerning Jezebel: ‘The dogs will devour Jezebel by the wall of Jezreel.’'),
  ('BSB', '1 Kings', 11, 21, 24, 'Anyone belonging to Ahab who dies in the city will be eaten by dogs, and anyone who dies in the field will be eaten by the birds of the air.”'),
  ('BSB', '1 Kings', 11, 21, 25, '(Surely there was never one like Ahab, who sold himself to do evil in the sight of the LORD, incited by his wife Jezebel.'),
  ('BSB', '1 Kings', 11, 21, 26, 'He committed the most detestable acts by going after idols, just like the Amorites whom the LORD had driven out before the Israelites.)'),
  ('BSB', '1 Kings', 11, 21, 27, 'When Ahab heard these words, he tore his clothes, put on sackcloth, and fasted. He lay down in sackcloth and walked around meekly.'),
  ('BSB', '1 Kings', 11, 21, 28, 'Then the word of the LORD came to Elijah the Tishbite, saying:'),
  ('BSB', '1 Kings', 11, 21, 29, '“Have you seen how Ahab has humbled himself before Me? Because he has humbled himself before Me, I will not bring the calamity during his days, but I will bring it upon his house in the days of his son.”'),
  ('BSB', '1 Kings', 11, 22, 1, 'Then three years passed without war between Aram and Israel.'),
  ('BSB', '1 Kings', 11, 22, 2, 'However, in the third year, Jehoshaphat king of Judah went down to visit the king of Israel,'),
  ('BSB', '1 Kings', 11, 22, 3, 'who said to his servants, “Do you not know that Ramoth-gilead is ours, but we have failed to take it from the hand of the king of Aram?”'),
  ('BSB', '1 Kings', 11, 22, 4, 'So he asked Jehoshaphat, “Will you go with me to fight against Ramoth-gilead?” Jehoshaphat answered the king of Israel, “I am like you, my people are your people, and my horses are your horses.”'),
  ('BSB', '1 Kings', 11, 22, 5, 'But Jehoshaphat also said to the king of Israel, “Please inquire first for the word of the LORD.”'),
  ('BSB', '1 Kings', 11, 22, 6, 'So the king of Israel assembled the prophets, about four hundred men, and asked them, “Should I go to war against Ramoth-gilead, or should I refrain?” “Go up,” they replied, “and the Lord will deliver it into the hand of the king.”'),
  ('BSB', '1 Kings', 11, 22, 7, 'But Jehoshaphat asked, “Is there not still a prophet of the LORD here of whom we can inquire?”'),
  ('BSB', '1 Kings', 11, 22, 8, 'The king of Israel answered, “There is still one man who can ask the LORD, but I hate him because he never prophesies anything good for me, but only bad. He is Micaiah son of Imlah.” “The king should not say that!” Jehoshaphat replied.'),
  ('BSB', '1 Kings', 11, 22, 9, 'So the king of Israel called one of his officials and said, “Bring Micaiah son of Imlah at once.”'),
  ('BSB', '1 Kings', 11, 22, 10, 'Dressed in royal attire, the king of Israel and Jehoshaphat king of Judah were sitting on their thrones at the threshing floor by the entrance of the gate of Samaria, with all the prophets prophesying before them.'),
  ('BSB', '1 Kings', 11, 22, 11, 'Now Zedekiah son of Chenaanah had made for himself iron horns and declared, “This is what the LORD says: ‘With these you shall gore the Arameans until they are finished off.’”'),
  ('BSB', '1 Kings', 11, 22, 12, 'And all the prophets were prophesying the same, saying, “Go up to Ramoth-gilead and prosper, for the LORD will deliver it into the hand of the king.”'),
  ('BSB', '1 Kings', 11, 22, 13, 'Then the messenger who had gone to call Micaiah instructed him, “Behold now, with one accord the words of the prophets are favorable to the king. So please let your words be like theirs, and speak favorably.”'),
  ('BSB', '1 Kings', 11, 22, 14, 'But Micaiah said, “As surely as the LORD lives, I will speak whatever the LORD tells me.”'),
  ('BSB', '1 Kings', 11, 22, 15, 'When Micaiah arrived, the king asked him, “Micaiah, should we go to war against Ramoth-gilead, or should we refrain?” “Go up and triumph,” Micaiah replied, “for the LORD will give it into the hand of the king.”'),
  ('BSB', '1 Kings', 11, 22, 16, 'But the king said to him, “How many times must I make you swear not to tell me anything but the truth in the name of the LORD?”'),
  ('BSB', '1 Kings', 11, 22, 17, 'So Micaiah declared: “I saw all Israel scattered on the hills like sheep without a shepherd. And the LORD said, ‘These people have no master; let each one return home in peace.’”'),
  ('BSB', '1 Kings', 11, 22, 18, 'Then the king of Israel said to Jehoshaphat, “Did I not tell you that he never prophesies good for me, but only bad?”'),
  ('BSB', '1 Kings', 11, 22, 19, 'Micaiah continued, “Therefore hear the word of the LORD: I saw the LORD sitting on His throne, and all the host of heaven standing by Him on His right and on His left.'),
  ('BSB', '1 Kings', 11, 22, 20, 'And the LORD said, ‘Who will entice Ahab to march up and fall at Ramoth-gilead?’ And one suggested this, and another that.'),
  ('BSB', '1 Kings', 11, 22, 21, 'Then a spirit came forward, stood before the LORD, and said, ‘I will entice him.’ ‘By what means?’ asked the LORD.'),
  ('BSB', '1 Kings', 11, 22, 22, 'And he replied, ‘I will go out and be a lying spirit in the mouths of all his prophets.’ ‘You will surely entice him and prevail,’ said the LORD. ‘Go and do it.’'),
  ('BSB', '1 Kings', 11, 22, 23, 'So you see, the LORD has put a lying spirit in the mouths of all these prophets of yours, and the LORD has pronounced disaster against you.”'),
  ('BSB', '1 Kings', 11, 22, 24, 'Then Zedekiah son of Chenaanah went up, struck Micaiah in the face, and demanded, “Which way did the Spirit of the LORD go when He departed from me to speak with you?”'),
  ('BSB', '1 Kings', 11, 22, 25, 'Micaiah replied, “You will soon see, on that day when you go and hide in an inner room.”'),
  ('BSB', '1 Kings', 11, 22, 26, 'And the king of Israel declared, “Take Micaiah and return him to Amon the governor of the city and to Joash the king’s son,'),
  ('BSB', '1 Kings', 11, 22, 27, 'and tell them that this is what the king says: ‘Put this man in prison and feed him only bread and water until I return safely.’”'),
  ('BSB', '1 Kings', 11, 22, 28, 'But Micaiah replied, “If you ever return safely, the LORD has not spoken through me.” Then he added, “Take heed, all you people!”'),
  ('BSB', '1 Kings', 11, 22, 29, 'So the king of Israel and Jehoshaphat king of Judah went up to Ramoth-gilead.'),
  ('BSB', '1 Kings', 11, 22, 30, 'And the king of Israel said to Jehoshaphat, “I will disguise myself and go into battle, but you wear your royal robes.” So the king of Israel disguised himself and went into battle.'),
  ('BSB', '1 Kings', 11, 22, 31, 'Now the king of Aram had ordered his thirty-two chariot commanders, “Do not fight with anyone, small or great, except the king of Israel.”'),
  ('BSB', '1 Kings', 11, 22, 32, 'When the chariot commanders saw Jehoshaphat, they said, “Surely this is the king of Israel!” So they turned to fight against him, but Jehoshaphat cried out.'),
  ('BSB', '1 Kings', 11, 22, 33, 'And when the chariot commanders saw that he was not the king of Israel, they turned back from pursuing him.'),
  ('BSB', '1 Kings', 11, 22, 34, 'However, a certain man drew his bow without taking special aim, and he struck the king of Israel between the joints of his armor. So the king said to his charioteer, “Turn around and take me out of the battle, for I am badly wounded!”'),
  ('BSB', '1 Kings', 11, 22, 35, 'The battle raged throughout that day, and the king was propped up in his chariot facing the Arameans. And the blood from his wound ran out onto the floor of the chariot, and that evening he died.'),
  ('BSB', '1 Kings', 11, 22, 36, 'As the sun was setting, the cry rang out in the army: “Every man to his own city, and every man to his own land!”'),
  ('BSB', '1 Kings', 11, 22, 37, 'So the king died and was brought to Samaria, where they buried him.'),
  ('BSB', '1 Kings', 11, 22, 38, 'And the chariot was washed at the pool of Samaria where the prostitutes bathed, and the dogs licked up Ahab’s blood, according to the word that the LORD had spoken.'),
  ('BSB', '1 Kings', 11, 22, 39, 'As for the rest of the acts of Ahab, along with all his accomplishments and the ivory palace and all the cities he built, are they not written in the Book of the Chronicles of the Kings of Israel?'),
  ('BSB', '1 Kings', 11, 22, 40, 'And Ahab rested with his fathers, and his son Ahaziah reigned in his place.'),
  ('BSB', '1 Kings', 11, 22, 41, 'In the fourth year of Ahab’s reign over Israel, Jehoshaphat son of Asa became king of Judah.'),
  ('BSB', '1 Kings', 11, 22, 42, 'Jehoshaphat was thirty-five years old when he became king, and he reigned in Jerusalem twenty-five years. His mother’s name was Azubah daughter of Shilhi.'),
  ('BSB', '1 Kings', 11, 22, 43, 'And Jehoshaphat walked in all the ways of his father Asa; he did not turn away from them, but did what was right in the eyes of the LORD. The high places, however, were not removed; the people still sacrificed and burned incense on the high places.'),
  ('BSB', '1 Kings', 11, 22, 44, 'Jehoshaphat also made peace with the king of Israel.'),
  ('BSB', '1 Kings', 11, 22, 45, 'As for the rest of the acts of Jehoshaphat, along with the might he exercised and how he waged war, are they not written in the Book of the Chronicles of the Kings of Judah?'),
  ('BSB', '1 Kings', 11, 22, 46, 'He banished from the land the male shrine prostitutes who remained from the days of his father Asa.'),
  ('BSB', '1 Kings', 11, 22, 47, 'And there was no king in Edom; a deputy served as king.'),
  ('BSB', '1 Kings', 11, 22, 48, 'Jehoshaphat built ships of Tarshish to go to Ophir for gold, but they never set sail, because they were wrecked at Ezion-geber.'),
  ('BSB', '1 Kings', 11, 22, 49, 'At that time Ahaziah son of Ahab said to Jehoshaphat, “Let my servants sail with your servants,” but Jehoshaphat refused.'),
  ('BSB', '1 Kings', 11, 22, 50, 'And Jehoshaphat rested with his fathers and was buried with them in the city of his father David. And his son Jehoram reigned in his place.'),
  ('BSB', '1 Kings', 11, 22, 51, 'In the seventeenth year of Jehoshaphat’s reign over Judah, Ahaziah son of Ahab became king of Israel, and he reigned in Samaria two years.'),
  ('BSB', '1 Kings', 11, 22, 52, 'And he did evil in the sight of the LORD and walked in the ways of his father and mother and of Jeroboam son of Nebat, who had caused Israel to sin.'),
  ('BSB', '1 Kings', 11, 22, 53, 'Ahaziah served and worshiped Baal, provoking the LORD, the God of Israel, to anger, just as his father had done.'),
  ('BSB', '2 Kings', 12, 1, 1, 'After the death of Ahab, Moab rebelled against Israel.'),
  ('BSB', '2 Kings', 12, 1, 2, 'Now Ahaziah had fallen through the lattice of his upper room in Samaria and injured himself. So he sent messengers and instructed them: “Go inquire of Baal-zebub, the god of Ekron, whether I will recover from this injury.”'),
  ('BSB', '2 Kings', 12, 1, 3, 'But the angel of the LORD said to Elijah the Tishbite, “Go up to meet the messengers of the king of Samaria and ask them, ‘Is it because there is no God in Israel that you are on your way to inquire of Baal-zebub, the god of Ekron?’'),
  ('BSB', '2 Kings', 12, 1, 4, 'Therefore this is what the LORD says: ‘You will not get up from the bed on which you are lying. You will surely die.’” So Elijah departed.'),
  ('BSB', '2 Kings', 12, 1, 5, 'When the messengers returned to the king, he asked them, “Why have you returned?”'),
  ('BSB', '2 Kings', 12, 1, 6, 'They replied, “A man came up to meet us and said, ‘Go back to the king who sent you and tell him that this is what the LORD says: Is it because there is no God in Israel that you are sending these men to inquire of Baal-zebub, the god of Ekron? Therefore you will not get up from the bed on which you are lying. You will surely die.’”'),
  ('BSB', '2 Kings', 12, 1, 7, 'The king asked them, “What sort of man came up to meet you and spoke these words to you?”'),
  ('BSB', '2 Kings', 12, 1, 8, '“He was a hairy man,” they answered, “with a leather belt around his waist.” “It was Elijah the Tishbite,” said the king.'),
  ('BSB', '2 Kings', 12, 1, 9, 'Then King Ahaziah sent to Elijah a captain with his company of fifty men. So the captain went up to Elijah, who was sitting on top of a hill, and said to him, “Man of God, the king declares, ‘Come down!’”'),
  ('BSB', '2 Kings', 12, 1, 10, 'Elijah answered the captain, “If I am a man of God, may fire come down from heaven and consume you and your fifty men.” And fire came down from heaven and consumed the captain and his fifty men.'),
  ('BSB', '2 Kings', 12, 1, 11, 'So the king sent to Elijah another captain with his fifty men. And the captain said to Elijah, “Man of God, the king declares, ‘Come down at once!’”'),
  ('BSB', '2 Kings', 12, 1, 12, 'Again Elijah replied, “If I am a man of God, may fire come down from heaven and consume you and your fifty men.” And the fire of God came down from heaven and consumed the captain and his fifty men.'),
  ('BSB', '2 Kings', 12, 1, 13, 'So the king sent a third captain with his fifty men. And the third captain went up, fell on his knees before Elijah, and begged him, “Man of God, may my life and the lives of these fifty servants please be precious in your sight.'),
  ('BSB', '2 Kings', 12, 1, 14, 'Behold, fire has come down from heaven and consumed the first two captains of fifty, with all their men. But now may my life be precious in your sight.”'),
  ('BSB', '2 Kings', 12, 1, 15, 'Then the angel of the LORD said to Elijah, “Go down with him. Do not be afraid of him.” So Elijah got up and went down with him to the king.'),
  ('BSB', '2 Kings', 12, 1, 16, 'And Elijah said to King Ahaziah, “This is what the LORD says: Is there really no God in Israel for you to inquire of His word? Is that why you have sent messengers to inquire of Baal-zebub, the god of Ekron? Therefore you will not get up from the bed on which you are lying. You will surely die.”'),
  ('BSB', '2 Kings', 12, 1, 17, 'So Ahaziah died according to the word of the LORD that Elijah had spoken. And since he had no son, Jehoram succeeded him in the second year of the reign of Jehoram son of Jehoshaphat over Judah.'),
  ('BSB', '2 Kings', 12, 1, 18, 'As for the rest of the acts of Ahaziah, along with his accomplishments, are they not written in the Book of the Chronicles of the Kings of Israel?'),
  ('BSB', '2 Kings', 12, 2, 1, 'Shortly before the LORD took Elijah up to heaven in a whirlwind, Elijah and Elisha were on their way from Gilgal,'),
  ('BSB', '2 Kings', 12, 2, 2, 'and Elijah said to Elisha, “Please stay here, for the LORD has sent me on to Bethel.” But Elisha replied, “As surely as the LORD lives and as you yourself live, I will not leave you.” So they went down to Bethel.'),
  ('BSB', '2 Kings', 12, 2, 3, 'Then the sons of the prophets at Bethel came out to Elisha and said, “Do you know that the LORD will take your master away from you today?” “Yes, I know,” he replied. “Do not speak of it.”'),
  ('BSB', '2 Kings', 12, 2, 4, 'And Elijah said to Elisha, “Please stay here, for the LORD has sent me on to Jericho.” But Elisha replied, “As surely as the LORD lives and as you yourself live, I will not leave you.” So they went to Jericho.'),
  ('BSB', '2 Kings', 12, 2, 5, 'Then the sons of the prophets at Jericho came up to Elisha and said, “Do you know that the LORD will take your master away from you today?” “Yes, I know,” he replied. “Do not speak of it.”'),
  ('BSB', '2 Kings', 12, 2, 6, 'And Elijah said to Elisha, “Please stay here, for the LORD has sent me on to the Jordan.” But Elisha replied, “As surely as the LORD lives and as you yourself live, I will not leave you.” So the two of them went on.'),
  ('BSB', '2 Kings', 12, 2, 7, 'Then a company of fifty of the sons of the prophets went and stood at a distance, facing Elijah and Elisha as the two of them stood by the Jordan.'),
  ('BSB', '2 Kings', 12, 2, 8, 'And Elijah took his cloak, rolled it up, and struck the waters, which parted to the right and to the left, so that the two of them crossed over on dry ground.'),
  ('BSB', '2 Kings', 12, 2, 9, 'After they had crossed over, Elijah said to Elisha, “Tell me, what can I do for you before I am taken away from you?” “Please, let me inherit a double portion of your spirit,” Elisha replied.'),
  ('BSB', '2 Kings', 12, 2, 10, '“You have requested a difficult thing,” said Elijah. “Nevertheless, if you see me as I am taken from you, it will be yours. But if not, then it will not be so.”'),
  ('BSB', '2 Kings', 12, 2, 11, 'As they were walking along and talking together, suddenly a chariot of fire with horses of fire appeared and separated the two of them, and Elijah went up into heaven in a whirlwind.'),
  ('BSB', '2 Kings', 12, 2, 12, 'As Elisha watched, he cried out, “My father, my father, the chariots and horsemen of Israel!” And he saw Elijah no more. So taking hold of his own clothes, he tore them in two.'),
  ('BSB', '2 Kings', 12, 2, 13, 'Elisha also picked up the cloak that had fallen from Elijah, and he went back and stood on the bank of the Jordan.'),
  ('BSB', '2 Kings', 12, 2, 14, 'Then he took the cloak of Elijah that had fallen from him and struck the waters. “Where now is the LORD, the God of Elijah?” he asked. And when he had struck the waters, they parted to the right and to the left, and Elisha crossed over.'),
  ('BSB', '2 Kings', 12, 2, 15, 'When the sons of the prophets who were facing him from Jericho saw what had happened, they said, “The spirit of Elijah rests on Elisha.” And they went to meet him and bowed down to the ground before him.'),
  ('BSB', '2 Kings', 12, 2, 16, '“Look now,” they said to Elisha, “we your servants have fifty valiant men. Please let them go and search for your master. Perhaps the Spirit of the LORD has taken him up and put him on one of the mountains or in one of the valleys.” “Do not send them,” Elisha replied.'),
  ('BSB', '2 Kings', 12, 2, 17, 'But when they pressed him to the point of embarrassment, he said, “Send them.” And they sent fifty men, who searched for three days but did not find Elijah.'),
  ('BSB', '2 Kings', 12, 2, 18, 'When they returned to Elisha, who was staying in Jericho, he said to them, “Didn’t I tell you not to go?”'),
  ('BSB', '2 Kings', 12, 2, 19, 'Then the men of the city said to Elisha, “Please note, our lord, that the city’s location is good, as you can see. But the water is bad and the land is unfruitful.”'),
  ('BSB', '2 Kings', 12, 2, 20, '“Bring me a new bowl,” he replied, “and put some salt in it.” So they brought it to him,'),
  ('BSB', '2 Kings', 12, 2, 21, 'and Elisha went out to the spring, cast the salt into it, and said, “This is what the LORD says: ‘I have healed this water. No longer will it cause death or unfruitfulness.’”'),
  ('BSB', '2 Kings', 12, 2, 22, 'And the waters there have been healthy to this day, according to the word spoken by Elisha.'),
  ('BSB', '2 Kings', 12, 2, 23, 'From there, Elisha went up to Bethel, and as he was walking up the road, a group of boys came out of the city and jeered at him, chanting, “Go up, you baldhead! Go up, you baldhead!”'),
  ('BSB', '2 Kings', 12, 2, 24, 'Then he turned around, looked at them, and called down a curse on them in the name of the LORD. Suddenly two female bears came out of the woods and mauled forty-two of the boys.'),
  ('BSB', '2 Kings', 12, 2, 25, 'And Elisha went on to Mount Carmel, and from there he returned to Samaria.'),
  ('BSB', '2 Kings', 12, 3, 1, 'In the eighteenth year of Jehoshaphat’s reign over Judah, Jehoram son of Ahab became king of Israel, and he reigned in Samaria twelve years.'),
  ('BSB', '2 Kings', 12, 3, 2, 'And he did evil in the sight of the LORD, but not as his father and mother had done. He removed the sacred pillar of Baal that his father had made.'),
  ('BSB', '2 Kings', 12, 3, 3, 'Nevertheless, he clung to the sins that Jeroboam son of Nebat had caused Israel to commit; he did not turn away from them.'),
  ('BSB', '2 Kings', 12, 3, 4, 'Now Mesha king of Moab was a sheep breeder, and he would render to the king of Israel a hundred thousand lambs and the wool of a hundred thousand rams.'),
  ('BSB', '2 Kings', 12, 3, 5, 'But after the death of Ahab, the king of Moab rebelled against the king of Israel.'),
  ('BSB', '2 Kings', 12, 3, 6, 'So at that time King Jehoram set out from Samaria and mobilized all Israel.'),
  ('BSB', '2 Kings', 12, 3, 7, 'And he sent a message to Jehoshaphat king of Judah: “The king of Moab has rebelled against me. Will you go with me to fight against Moab?” “I will go,” replied Jehoshaphat. “I am like you, my people are your people, and my horses are your horses.”'),
  ('BSB', '2 Kings', 12, 3, 8, 'Then he asked, “Which way shall we go up?” “By way of the Desert of Edom,” replied Joram.'),
  ('BSB', '2 Kings', 12, 3, 9, 'So the king of Israel, the king of Judah, and the king of Edom set out, and after they had traveled a roundabout route for seven days, they had no water for their army or for their animals.'),
  ('BSB', '2 Kings', 12, 3, 10, '“Alas,” said the king of Israel, “for the LORD has summoned these three kings to deliver them into the hand of Moab!”'),
  ('BSB', '2 Kings', 12, 3, 11, 'But Jehoshaphat asked, “Is there no prophet of the LORD here? Let us inquire of the LORD through him.” And one of the servants of the king of Israel answered, “Elisha son of Shaphat is here. He used to pour water on the hands of Elijah.”'),
  ('BSB', '2 Kings', 12, 3, 12, 'Jehoshaphat affirmed, “The word of the LORD is with him.” So the king of Israel and Jehoshaphat and the king of Edom went down to him.'),
  ('BSB', '2 Kings', 12, 3, 13, 'Elisha, however, said to the king of Israel, “What have we to do with each other? Go to the prophets of your father and of your mother!” “No,” replied the king of Israel, “for it is the LORD who has summoned these three kings to deliver them into the hand of Moab.”'),
  ('BSB', '2 Kings', 12, 3, 14, 'Then Elisha said, “As surely as the LORD of Hosts lives, before whom I stand, were it not for my regard for the presence of Jehoshaphat king of Judah, I would not look at you or acknowledge you.'),
  ('BSB', '2 Kings', 12, 3, 15, 'But now, bring me a harpist.” And while the harpist played, the hand of the LORD came upon Elisha'),
  ('BSB', '2 Kings', 12, 3, 16, 'and he said, “This is what the LORD says: ‘Dig this valley full of ditches.’'),
  ('BSB', '2 Kings', 12, 3, 17, 'For the LORD says, ‘You will not see wind or rain, but the valley will be filled with water, and you will drink—you and your cattle and your animals.’'),
  ('BSB', '2 Kings', 12, 3, 18, 'This is a simple matter in the sight of the LORD, and He will also deliver the Moabites into your hand.'),
  ('BSB', '2 Kings', 12, 3, 19, 'And you shall attack every fortified city and every city of importance. You shall cut down every good tree, stop up every spring, and ruin every good field with stones.”'),
  ('BSB', '2 Kings', 12, 3, 20, 'The next morning, at the time of the morning sacrifice, water suddenly flowed from the direction of Edom and filled the land.'),
  ('BSB', '2 Kings', 12, 3, 21, 'Now all the Moabites had heard that the kings had come up to fight against them. So all who could bear arms, young and old, were summoned and stationed at the border.'),
  ('BSB', '2 Kings', 12, 3, 22, 'When they got up early in the morning, the sun was shining on the water, and it looked as red as blood to the Moabites across the way.'),
  ('BSB', '2 Kings', 12, 3, 23, '“This is blood!” they exclaimed. “The kings have clashed swords and slaughtered one another. Now to the plunder, Moab!”');
insert into control_room_bible (version, book, book_num, chapter, verse, text) values
  ('BSB', '2 Kings', 12, 3, 24, 'But when the Moabites came to the camp of Israel, the Israelites rose up and attacked them, and they fled before them. So the Israelites invaded their land and struck down the Moabites.'),
  ('BSB', '2 Kings', 12, 3, 25, 'They destroyed the cities, and each man threw stones on every good field until it was covered. They stopped up every spring and cut down every good tree. Only Kir-haraseth was left with stones in place, but men with slings surrounded it and attacked it as well.'),
  ('BSB', '2 Kings', 12, 3, 26, 'When the king of Moab saw that the battle was too fierce for him, he took with him seven hundred swordsmen to break through to the king of Edom, but they could not prevail.'),
  ('BSB', '2 Kings', 12, 3, 27, 'So he took his firstborn son, who was to succeed him, and offered him as a burnt offering on the city wall. And there was great fury against the Israelites, so they withdrew and returned to their own land.'),
  ('BSB', '2 Kings', 12, 4, 1, 'Now the wife of one of the sons of the prophets cried out to Elisha, “Your servant, my husband, is dead, and you know that your servant feared the LORD. And now his creditor is coming to take my two children as his slaves!”'),
  ('BSB', '2 Kings', 12, 4, 2, '“How can I help you?” asked Elisha. “Tell me, what do you have in the house?” She answered, “Your servant has nothing in the house but a jar of oil.”'),
  ('BSB', '2 Kings', 12, 4, 3, '“Go,” said Elisha, “borrow jars, even empty ones, from all your neighbors. Do not gather just a few.'),
  ('BSB', '2 Kings', 12, 4, 4, 'Then go inside, shut the door behind you and your sons, and pour oil into all these jars, setting the full ones aside.”'),
  ('BSB', '2 Kings', 12, 4, 5, 'So she left him, and after she had shut the door behind her and her sons, they kept bringing jars to her, and she kept pouring.'),
  ('BSB', '2 Kings', 12, 4, 6, 'When all the jars were full, she said to her son, “Bring me another.” But he replied, “There are no more jars.” Then the oil stopped flowing.'),
  ('BSB', '2 Kings', 12, 4, 7, 'She went and told the man of God, and he said, “Go, sell the oil, and pay your debt. Then you and your sons can live on the remainder.”'),
  ('BSB', '2 Kings', 12, 4, 8, 'One day Elisha went to Shunem, and a prominent woman who lived there persuaded him to have a meal. So whenever he would pass by, he would stop there to eat.'),
  ('BSB', '2 Kings', 12, 4, 9, 'Then the woman said to her husband, “Behold, now I know that the one who often comes our way is a holy man of God.'),
  ('BSB', '2 Kings', 12, 4, 10, 'Please let us make a small room upstairs and put in it a bed, a table, a chair, and a lamp for him. Then when he comes to us, he can stay there.”'),
  ('BSB', '2 Kings', 12, 4, 11, 'One day Elisha came to visit and went to his upper room to lie down.'),
  ('BSB', '2 Kings', 12, 4, 12, 'And he said to Gehazi his servant, “Call the Shunammite woman.” And when he had called her, she stood before him,'),
  ('BSB', '2 Kings', 12, 4, 13, 'and Elisha said to Gehazi, “Now tell her, ‘Look, you have gone to all this trouble for us. What can we do for you? Can we speak on your behalf to the king or the commander of the army?’” “I have a home among my own people,” she replied.'),
  ('BSB', '2 Kings', 12, 4, 14, 'So he asked, “Then what should be done for her?” “Well, she has no son,” Gehazi replied, “and her husband is old.”'),
  ('BSB', '2 Kings', 12, 4, 15, '“Call her,” said Elisha. So Gehazi called her, and she stood in the doorway.'),
  ('BSB', '2 Kings', 12, 4, 16, 'And Elisha declared, “At this time next year, you will hold a son in your arms.” “No, my lord,” she said. “Do not lie to your maidservant, O man of God.”'),
  ('BSB', '2 Kings', 12, 4, 17, 'But the woman did conceive, and at that time the next year she gave birth to a son, just as Elisha had told her.'),
  ('BSB', '2 Kings', 12, 4, 18, 'And the child grew, and one day he went out to his father, who was with the harvesters.'),
  ('BSB', '2 Kings', 12, 4, 19, '“My head! My head!” he complained to his father. So his father told a servant, “Carry him to his mother.”'),
  ('BSB', '2 Kings', 12, 4, 20, 'After the servant had picked him up and carried him to his mother, the boy sat on her lap until noon, and then he died.'),
  ('BSB', '2 Kings', 12, 4, 21, 'And she went up and laid him on the bed of the man of God. Then she shut the door and went out.'),
  ('BSB', '2 Kings', 12, 4, 22, 'And the woman called her husband and said, “Please send me one of the servants and one of the donkeys, that I may go quickly to the man of God and return.”'),
  ('BSB', '2 Kings', 12, 4, 23, '“Why would you go to him today?” he replied. “It is not a New Moon or a Sabbath.” “Everything is all right,” she said.'),
  ('BSB', '2 Kings', 12, 4, 24, 'Then she saddled the donkey and told her servant, “Drive onward; do not slow the pace for me unless I tell you.”'),
  ('BSB', '2 Kings', 12, 4, 25, 'So she set out and went to the man of God at Mount Carmel. When the man of God saw her at a distance, he said to his servant Gehazi, “Look, there is the Shunammite woman.'),
  ('BSB', '2 Kings', 12, 4, 26, 'Please run out now to meet her and ask, ‘Are you all right? Is your husband all right? Is your child all right?’” And she answered, “Everything is all right.”'),
  ('BSB', '2 Kings', 12, 4, 27, 'When she reached the man of God at the mountain, she clung to his feet. Gehazi came over to push her away, but the man of God said, “Leave her alone, for her soul is in deep distress, and the LORD has hidden it from me and has not told me.”'),
  ('BSB', '2 Kings', 12, 4, 28, 'Then she said, “Did I ask you for a son, my lord? Didn’t I say, ‘Do not deceive me?’”'),
  ('BSB', '2 Kings', 12, 4, 29, 'So Elisha said to Gehazi, “Tie up your garment, take my staff in your hand, and go! If you meet anyone, do not greet him, and if anyone greets you, do not answer him. Then lay my staff on the boy’s face.”'),
  ('BSB', '2 Kings', 12, 4, 30, 'And the mother of the boy said, “As surely as the LORD lives and as you yourself live, I will not leave you.” So he got up and followed her.'),
  ('BSB', '2 Kings', 12, 4, 31, 'Gehazi went on ahead of them and laid the staff on the boy’s face, but there was no sound or response. So he went back to meet Elisha and told him, “The boy has not awakened.”'),
  ('BSB', '2 Kings', 12, 4, 32, 'When Elisha reached the house, there was the boy lying dead on his bed.'),
  ('BSB', '2 Kings', 12, 4, 33, 'So he went in, closed the door behind the two of them, and prayed to the LORD.'),
  ('BSB', '2 Kings', 12, 4, 34, 'Then Elisha got on the bed and lay on the boy, mouth to mouth, eye to eye, and hand to hand. As he stretched himself out over him, the boy’s body became warm.'),
  ('BSB', '2 Kings', 12, 4, 35, 'Elisha turned away and paced back and forth across the room. Then he got on the bed and stretched himself out over the boy again, and the boy sneezed seven times and opened his eyes.'),
  ('BSB', '2 Kings', 12, 4, 36, 'Elisha summoned Gehazi and said, “Call the Shunammite woman.” So he called her and she came. Then Elisha said, “Pick up your son.”'),
  ('BSB', '2 Kings', 12, 4, 37, 'She came in, fell at his feet, and bowed to the ground. Then she picked up her son and went out.'),
  ('BSB', '2 Kings', 12, 4, 38, 'When Elisha returned to Gilgal, there was a famine in the land. As the sons of the prophets were sitting at his feet, he said to his attendant, “Put on the large pot and boil some stew for the sons of the prophets.”'),
  ('BSB', '2 Kings', 12, 4, 39, 'One of them went out to the field to gather herbs, and he found a wild vine from which he gathered as many wild gourds as his garment could hold. Then he came back and cut them up into the pot of stew, though no one knew what they were.'),
  ('BSB', '2 Kings', 12, 4, 40, 'And they poured it out for the men to eat, but when they tasted the stew they cried out, “There is death in the pot, O man of God!” And they could not eat it.'),
  ('BSB', '2 Kings', 12, 4, 41, 'Then Elisha said, “Get some flour.” He threw it into the pot and said, “Pour it out for the people to eat.” And there was nothing harmful in the pot.'),
  ('BSB', '2 Kings', 12, 4, 42, 'Now a man from Baal-shalishah came to the man of God with a sack of twenty loaves of barley bread from the first ripe grain. “Give it to the people to eat,” said Elisha.'),
  ('BSB', '2 Kings', 12, 4, 43, 'But his servant asked, “How am I to set twenty loaves before a hundred men?” “Give it to the people to eat,” said Elisha, “for this is what the LORD says: ‘They will eat and have some left over.’”'),
  ('BSB', '2 Kings', 12, 4, 44, 'So he set it before them, and they ate and had some left over, according to the word of the LORD.'),
  ('BSB', '2 Kings', 12, 5, 1, 'Now Naaman, the commander of the army of the king of Aram, was a great man in his master’s sight and highly regarded, for through him the LORD had given victory to Aram. And he was a mighty man of valor, but he was a leper.'),
  ('BSB', '2 Kings', 12, 5, 2, 'At this time the Arameans had gone out in bands and had taken a young girl from the land of Israel, and she was serving Naaman’s wife.'),
  ('BSB', '2 Kings', 12, 5, 3, 'She said to her mistress, “If only my master would go to the prophet who is in Samaria, he would cure him of his leprosy.”'),
  ('BSB', '2 Kings', 12, 5, 4, 'And Naaman went and told his master what the girl from the land of Israel had said.'),
  ('BSB', '2 Kings', 12, 5, 5, '“Go now,” said the king of Aram, “and I will send you with a letter to the king of Israel.” So Naaman departed, taking with him ten talents of silver, six thousand shekels of gold, and ten sets of clothing.'),
  ('BSB', '2 Kings', 12, 5, 6, 'And the letter that he took to the king of Israel stated: “With this letter I am sending my servant Naaman, so that you may cure him of his leprosy.”'),
  ('BSB', '2 Kings', 12, 5, 7, 'When the king of Israel read the letter, he tore his clothes and asked, “Am I God, killing and giving life, that this man expects me to cure a leper? Surely you can see that he is seeking a quarrel with me!”'),
  ('BSB', '2 Kings', 12, 5, 8, 'Now when Elisha the man of God heard that the king of Israel had torn his clothes, he sent a message to the king: “Why have you torn your clothes? Please let the man come to me, and he will know that there is a prophet in Israel.”'),
  ('BSB', '2 Kings', 12, 5, 9, 'So Naaman came with his horses and chariots and stood at the door of Elisha’s house.'),
  ('BSB', '2 Kings', 12, 5, 10, 'Then Elisha sent him a messenger, who said, “Go and wash yourself seven times in the Jordan, and your flesh will be restored, and you will be clean.”'),
  ('BSB', '2 Kings', 12, 5, 11, 'But Naaman went away angry, saying, “I thought that he would surely come out, stand and call on the name of the LORD his God, and wave his hand over the spot to cure my leprosy.'),
  ('BSB', '2 Kings', 12, 5, 12, 'Are not the Abanah and Pharpar, the rivers of Damascus, better than all the waters of Israel? Could I not have washed in them and been cleansed?” So he turned and went away in a rage.'),
  ('BSB', '2 Kings', 12, 5, 13, 'Naaman’s servants, however, approached him and said, “My father, if the prophet had told you to do some great thing, would you not have done it? How much more, then, when he tells you, ‘Wash and be cleansed’?”'),
  ('BSB', '2 Kings', 12, 5, 14, 'So Naaman went down and dipped himself in the Jordan seven times, according to the word of the man of God, and his flesh was restored and became like that of a little child, and he was clean.'),
  ('BSB', '2 Kings', 12, 5, 15, 'Then Naaman and all his attendants went back to the man of God, stood before him, and declared, “Now I know for sure that there is no God in all the earth except in Israel. So please accept a gift from your servant.”'),
  ('BSB', '2 Kings', 12, 5, 16, 'But Elisha replied, “As surely as the LORD lives, before whom I stand, I will not accept it.” And although Naaman urged him to accept it, he refused.'),
  ('BSB', '2 Kings', 12, 5, 17, '“If you will not,” said Naaman, “please let me, your servant, be given as much soil as a pair of mules can carry. For your servant will never again make a burnt offering or a sacrifice to any other god but the LORD.'),
  ('BSB', '2 Kings', 12, 5, 18, 'Yet may the LORD forgive your servant this one thing: When my master goes into the temple of Rimmon to worship there, and he leans on my arm, and I bow down in the temple of Rimmon, may the LORD forgive your servant in this matter.”'),
  ('BSB', '2 Kings', 12, 5, 19, '“Go in peace,” said Elisha. But after Naaman had traveled a short distance,'),
  ('BSB', '2 Kings', 12, 5, 20, 'Gehazi, the servant of Elisha the man of God, said, “Look, my master has spared this Aramean, Naaman, while not accepting what he brought. As surely as the LORD lives, I will run after him and get something from him.”'),
  ('BSB', '2 Kings', 12, 5, 21, 'So Gehazi pursued Naaman. And when Naaman saw him running toward him, he got down from the chariot to meet him and asked, “Is everything all right?”'),
  ('BSB', '2 Kings', 12, 5, 22, '“Everything is all right,” Gehazi replied. “My master has sent me to say, ‘I have just now discovered that two young men from the sons of the prophets have come to me from the hill country of Ephraim. Please give them a talent of silver and two sets of clothing.’”'),
  ('BSB', '2 Kings', 12, 5, 23, 'But Naaman insisted, “Please, take two talents.” And he urged Gehazi to accept them. Then he tied up two talents of silver in two bags along with two sets of clothing and gave them to two of his servants, who carried them ahead of Gehazi.'),
  ('BSB', '2 Kings', 12, 5, 24, 'When Gehazi came to the hill, he took the gifts from the servants and stored them in the house. Then he dismissed the men, and they departed.'),
  ('BSB', '2 Kings', 12, 5, 25, 'When Gehazi went in and stood before his master, Elisha asked him, “Gehazi, where have you been?” “Your servant did not go anywhere,” he replied.'),
  ('BSB', '2 Kings', 12, 5, 26, 'But Elisha questioned him, “Did not my spirit go with you when the man got down from his chariot to meet you? Is this the time to accept money and clothing, olive groves and vineyards, sheep and oxen, menservants and maidservants?'),
  ('BSB', '2 Kings', 12, 5, 27, 'Therefore, the leprosy of Naaman will cling to you and your descendants forever!” And as Gehazi left his presence, he was leprous—as white as snow.'),
  ('BSB', '2 Kings', 12, 6, 1, 'Now the sons of the prophets said to Elisha, “Please take note that the place where we meet with you is too small for us.'),
  ('BSB', '2 Kings', 12, 6, 2, 'Please let us go to the Jordan, where each of us can get a log so we can build ourselves a place to live there.” “Go,” said Elisha.'),
  ('BSB', '2 Kings', 12, 6, 3, 'Then one of them said, “Please come with your servants.” “I will come,” he replied.'),
  ('BSB', '2 Kings', 12, 6, 4, 'So Elisha went with them, and when they came to the Jordan, they began to cut down some trees.'),
  ('BSB', '2 Kings', 12, 6, 5, 'As one of them was cutting down a tree, the iron axe head fell into the water. “Oh, my master,” he cried out, “it was borrowed!”'),
  ('BSB', '2 Kings', 12, 6, 6, '“Where did it fall?” asked the man of God. And when he showed him the place, the man of God cut a stick, threw it there, and made the iron float.'),
  ('BSB', '2 Kings', 12, 6, 7, '“Lift it out,” he said, and the man reached out his hand and took it.'),
  ('BSB', '2 Kings', 12, 6, 8, 'Now the king of Aram was at war against Israel. After consulting with his servants, he said, “My camp will be in such and such a place.”'),
  ('BSB', '2 Kings', 12, 6, 9, 'Then the man of God sent word to the king of Israel: “Be careful passing by this place, for the Arameans are going down there.”'),
  ('BSB', '2 Kings', 12, 6, 10, 'So the king of Israel sent word to the place the man of God had pointed out. Time and again Elisha warned the king, so that he was on his guard in such places.'),
  ('BSB', '2 Kings', 12, 6, 11, 'For this reason the king of Aram became enraged and called his servants to demand of them, “Tell me, which one of us is on the side of the king of Israel?”'),
  ('BSB', '2 Kings', 12, 6, 12, 'But one of his servants replied, “No one, my lord the king. For Elisha, the prophet in Israel, tells the king of Israel the very words you speak in your bedroom.”'),
  ('BSB', '2 Kings', 12, 6, 13, 'So the king said, “Go and see where he is, that I may send men to capture him.” On receiving the report, “Elisha is in Dothan,”'),
  ('BSB', '2 Kings', 12, 6, 14, 'the king of Aram sent horses, chariots, and a great army. They went there by night and surrounded the city.'),
  ('BSB', '2 Kings', 12, 6, 15, 'When the servant of the man of God got up and went out early in the morning, an army with horses and chariots had surrounded the city. So he asked Elisha, “Oh, my master, what are we to do?”'),
  ('BSB', '2 Kings', 12, 6, 16, '“Do not be afraid,” Elisha answered, “for those who are with us are more than those who are with them.”'),
  ('BSB', '2 Kings', 12, 6, 17, 'Then Elisha prayed, “O LORD, please open his eyes that he may see.” And the LORD opened the eyes of the young man, and he saw that the hills were full of horses and chariots of fire all around Elisha.'),
  ('BSB', '2 Kings', 12, 6, 18, 'As the Arameans came down against him, Elisha prayed to the LORD, “Please strike these people with blindness.” So He struck them with blindness, according to the word of Elisha.'),
  ('BSB', '2 Kings', 12, 6, 19, 'And Elisha told them, “This is not the way, and this is not the city. Follow me, and I will take you to the man you are seeking.” And he led them to Samaria.'),
  ('BSB', '2 Kings', 12, 6, 20, 'When they had entered Samaria, Elisha said, “O LORD, open the eyes of these men that they may see.” Then the LORD opened their eyes, and they looked around and discovered that they were in Samaria.'),
  ('BSB', '2 Kings', 12, 6, 21, 'And when the king of Israel saw them, he asked Elisha, “My father, shall I kill them? Shall I kill them?”'),
  ('BSB', '2 Kings', 12, 6, 22, '“Do not kill them,” he replied. “Would you kill those you have captured with your own sword or bow? Set food and water before them, that they may eat and drink and then return to their master.”'),
  ('BSB', '2 Kings', 12, 6, 23, 'So the king prepared a great feast for them, and after they had finished eating and drinking, he sent them away, and they returned to their master. And the Aramean raiders did not come into the land of Israel again.'),
  ('BSB', '2 Kings', 12, 6, 24, 'Some time later, Ben-hadad king of Aram assembled his entire army and marched up to besiege Samaria.'),
  ('BSB', '2 Kings', 12, 6, 25, 'So there was a great famine in Samaria. Indeed, they besieged the city so long that a donkey’s head sold for eighty shekels of silver, and a quarter cab of dove’s dung sold for five shekels of silver.'),
  ('BSB', '2 Kings', 12, 6, 26, 'As the king of Israel was passing by on the wall, a woman cried out to him, “Help me, my lord the king!”'),
  ('BSB', '2 Kings', 12, 6, 27, 'He answered, “If the LORD does not help you, where can I find help for you? From the threshing floor or the winepress?”'),
  ('BSB', '2 Kings', 12, 6, 28, 'Then the king asked her, “What is the matter?” And she answered, “This woman said to me, ‘Give up your son, that we may eat him, and tomorrow we will eat my son.’'),
  ('BSB', '2 Kings', 12, 6, 29, 'So we boiled my son and ate him, and the next day I said to her, ‘Give up your son, that we may eat him.’ But she had hidden her son.”'),
  ('BSB', '2 Kings', 12, 6, 30, 'When the king heard the words of the woman, he tore his clothes. And as he passed by on the wall, the people saw the sackcloth under his clothes next to his skin.'),
  ('BSB', '2 Kings', 12, 6, 31, 'He announced, “May God punish me, and ever so severely, if the head of Elisha son of Shaphat remains on his shoulders through this day!”'),
  ('BSB', '2 Kings', 12, 6, 32, 'Now Elisha was sitting in his house, and the elders were sitting with him. The king sent a messenger ahead, but before he arrived, Elisha said to the elders, “Do you see how this murderer has sent someone to cut off my head? Look, when the messenger comes, shut the door to keep him out. Is not the sound of his master’s footsteps behind him?”'),
  ('BSB', '2 Kings', 12, 6, 33, 'While Elisha was still speaking with them, the messenger came down to him. And the king said, “This calamity is from the LORD. Why should I wait for the LORD any longer?”'),
  ('BSB', '2 Kings', 12, 7, 1, 'Then Elisha said, “Hear the word of the LORD! This is what the LORD says: ‘About this time tomorrow at the gate of Samaria, a seah of fine flour will sell for a shekel, and two seahs of barley will sell for a shekel.’”'),
  ('BSB', '2 Kings', 12, 7, 2, 'But the officer on whose arm the king leaned answered the man of God, “Look, even if the LORD were to make windows in heaven, could this really happen?” “You will see it with your own eyes,” replied Elisha, “but you will not eat any of it.”'),
  ('BSB', '2 Kings', 12, 7, 3, 'Now there were four men with leprosy at the entrance of the city gate, and they said to one another, “Why just sit here until we die?'),
  ('BSB', '2 Kings', 12, 7, 4, 'If we say, ‘Let us go into the city,’ we will die there from the famine in the city; but if we sit here, we will also die. So come now, let us go over to the camp of the Arameans. If they let us live, we will live; if they kill us, we will die.”'),
  ('BSB', '2 Kings', 12, 7, 5, 'So they arose at twilight and went to the camp of the Arameans. But when they came to the outskirts of the camp, there was not a man to be found.'),
  ('BSB', '2 Kings', 12, 7, 6, 'For the Lord had caused the Arameans to hear the sound of chariots, horses, and a great army, so that they said to one another, “Look, the king of Israel must have hired the kings of the Hittites and Egyptians to attack us.”'),
  ('BSB', '2 Kings', 12, 7, 7, 'Thus the Arameans had arisen and fled at twilight, abandoning their tents and horses and donkeys. The camp was intact, and they had run for their lives.'),
  ('BSB', '2 Kings', 12, 7, 8, 'When the lepers reached the edge of the camp, they went into a tent to eat and drink. Then they carried off the silver, gold, and clothing, and went and hid them. On returning, they entered another tent, carried off some items from there, and hid them.'),
  ('BSB', '2 Kings', 12, 7, 9, 'Finally, they said to one another, “We are not doing what is right. Today is a day of good news. If we are silent and wait until morning light, our sin will overtake us. Now, therefore, let us go and tell the king’s household.”'),
  ('BSB', '2 Kings', 12, 7, 10, 'So they went and called out to the gatekeepers of the city, saying, “We went to the Aramean camp and no one was there—not a trace—only tethered horses and donkeys, and the tents were intact.”'),
  ('BSB', '2 Kings', 12, 7, 11, 'The gatekeepers shouted the news, and it was reported to the king’s household.'),
  ('BSB', '2 Kings', 12, 7, 12, 'So the king got up in the night and said to his servants, “Let me tell you what the Arameans have done to us. They know we are starving, so they have left the camp to hide in the field, thinking, ‘When they come out of the city, we will take them alive and enter the city.’”'),
  ('BSB', '2 Kings', 12, 7, 13, 'But one of his servants replied, “Please, have scouts take five of the horses that remain in the city. Their plight will be no worse than all the Israelites who are left here. You can see that all the Israelites here are doomed. So let us send them and find out.”'),
  ('BSB', '2 Kings', 12, 7, 14, 'Then the scouts took two chariots with horses, and the king sent them after the Aramean army, saying, “Go and see.”'),
  ('BSB', '2 Kings', 12, 7, 15, 'And they tracked them as far as the Jordan, and indeed, the whole way was littered with the clothing and equipment the Arameans had thrown off in haste. So the scouts returned and told the king.'),
  ('BSB', '2 Kings', 12, 7, 16, 'Then the people went out and plundered the camp of the Arameans. It was then that a seah of fine flour sold for a shekel, and two seahs of barley sold for a shekel, according to the word of the LORD.'),
  ('BSB', '2 Kings', 12, 7, 17, 'Now the king had appointed the officer on whose arm he leaned to be in charge of the gate, but the people trampled him in the gateway, and he died, just as the man of God had foretold when the king had come to him.'),
  ('BSB', '2 Kings', 12, 7, 18, 'It happened just as the man of God had told the king: “About this time tomorrow at the gate of Samaria, two seahs of barley will sell for a shekel, and a seah of fine flour will sell for a shekel.”'),
  ('BSB', '2 Kings', 12, 7, 19, 'And the officer had answered the man of God, “Look, even if the LORD were to make windows in heaven, could this really happen?” So Elisha had replied, “You will see it with your own eyes, but you will not eat any of it!”'),
  ('BSB', '2 Kings', 12, 7, 20, 'And that is just what happened to him. The people trampled him in the gateway, and he died.'),
  ('BSB', '2 Kings', 12, 8, 1, 'Now Elisha had said to the woman whose son he had restored to life, “Arise, you and your household; go and live as a foreigner wherever you can. For the LORD has decreed a seven-year famine, and it has already come to the land.”'),
  ('BSB', '2 Kings', 12, 8, 2, 'So the woman had proceeded to do as the man of God had instructed. And she and her household lived as foreigners for seven years in the land of the Philistines.'),
  ('BSB', '2 Kings', 12, 8, 3, 'At the end of seven years, when the woman returned from the land of the Philistines, she went to the king to appeal for her house and her land.'),
  ('BSB', '2 Kings', 12, 8, 4, 'Now the king had been speaking to Gehazi, the servant of the man of God, saying, “Please relate to me all the great things Elisha has done.”'),
  ('BSB', '2 Kings', 12, 8, 5, 'And Gehazi was telling the king how Elisha had brought the dead back to life. Just then the woman whose son Elisha had revived came to appeal to the king for her house and her land. So Gehazi said, “My lord the king, this is the woman, and this is the son Elisha restored to life.”'),
  ('BSB', '2 Kings', 12, 8, 6, 'When the king asked the woman, she confirmed it. So the king appointed for her an officer, saying, “Restore all that was hers, along with all the proceeds of the field from the day that she left the country until now.”'),
  ('BSB', '2 Kings', 12, 8, 7, 'Then Elisha came to Damascus while Ben-hadad king of Aram was sick, and the king was told, “The man of God has come here.”'),
  ('BSB', '2 Kings', 12, 8, 8, 'So the king said to Hazael, “Take a gift in your hand, go to meet the man of God, and inquire of the LORD through him, ‘Will I recover from this illness?’”'),
  ('BSB', '2 Kings', 12, 8, 9, 'So Hazael went to meet Elisha, taking with him a gift of forty camel loads of every good thing from Damascus. And he went in and stood before him and said, “Your son Ben-hadad king of Aram has sent me to ask, ‘Will I recover from this illness?’”'),
  ('BSB', '2 Kings', 12, 8, 10, 'Elisha answered, “Go and tell him, ‘You will surely recover.’ But the LORD has shown me that in fact he will die.”'),
  ('BSB', '2 Kings', 12, 8, 11, 'Elisha fixed his gaze steadily on him until Hazael became uncomfortable. Then the man of God began to weep.'),
  ('BSB', '2 Kings', 12, 8, 12, '“Why is my lord weeping?” asked Hazael. “Because I know the evil you will do to the Israelites,” Elisha replied. “You will set fire to their fortresses, kill their young men with the sword, dash their little ones to pieces, and rip open their pregnant women.”'),
  ('BSB', '2 Kings', 12, 8, 13, '“But how could your servant, a mere dog, do such a monstrous thing?” said Hazael. And Elisha answered, “The LORD has shown me that you will be king over Aram.”'),
  ('BSB', '2 Kings', 12, 8, 14, 'So Hazael left Elisha and went to his master, who asked him, “What did Elisha say to you?” And he replied, “He told me that you would surely recover.”'),
  ('BSB', '2 Kings', 12, 8, 15, 'But the next day Hazael took a thick cloth, dipped it in water, and spread it over the king’s face. So Ben-hadad died, and Hazael reigned in his place.'),
  ('BSB', '2 Kings', 12, 8, 16, 'In the fifth year of the reign of Joram son of Ahab over Israel, Jehoram son of Jehoshaphat succeeded his father as king of Judah.'),
  ('BSB', '2 Kings', 12, 8, 17, 'Jehoram was thirty-two years old when he became king, and he reigned in Jerusalem eight years.'),
  ('BSB', '2 Kings', 12, 8, 18, 'And Jehoram walked in the ways of the kings of Israel, just as the house of Ahab had done. For he married a daughter of Ahab and did evil in the sight of the LORD.'),
  ('BSB', '2 Kings', 12, 8, 19, 'Yet for the sake of His servant David, the LORD was unwilling to destroy Judah, since He had promised to maintain a lamp for David and his descendants forever.'),
  ('BSB', '2 Kings', 12, 8, 20, 'In the days of Jehoram, Edom rebelled against the hand of Judah and appointed their own king.'),
  ('BSB', '2 Kings', 12, 8, 21, 'So Jehoram crossed over to Zair with all his chariots. When the Edomites surrounded him and his chariot commanders, he rose up and attacked by night. His troops, however, fled to their homes.'),
  ('BSB', '2 Kings', 12, 8, 22, 'So to this day Edom has been in rebellion against the hand of Judah. Likewise, Libnah rebelled at the same time.'),
  ('BSB', '2 Kings', 12, 8, 23, 'As for the rest of the acts of Jehoram, along with all his accomplishments, are they not written in the book of the Chronicles of the Kings of Judah?'),
  ('BSB', '2 Kings', 12, 8, 24, 'And Jehoram rested with his fathers and was buried with them in the City of David. And his son Ahaziah reigned in his place.'),
  ('BSB', '2 Kings', 12, 8, 25, 'In the twelfth year of the reign of Joram son of Ahab over Israel, Ahaziah son of Jehoram became king of Judah.'),
  ('BSB', '2 Kings', 12, 8, 26, 'Ahaziah was twenty-two years old when he became king, and he reigned in Jerusalem one year. His mother’s name was Athaliah, the granddaughter of Omri king of Israel.'),
  ('BSB', '2 Kings', 12, 8, 27, 'And Ahaziah walked in the ways of the house of Ahab and did evil in the sight of the LORD like the house of Ahab, for he was a son-in-law of the house of Ahab.'),
  ('BSB', '2 Kings', 12, 8, 28, 'Then Ahaziah went with Joram son of Ahab to fight against Hazael king of Aram at Ramoth-gilead, and the Arameans wounded Joram.'),
  ('BSB', '2 Kings', 12, 8, 29, 'So King Joram returned to Jezreel to recover from the wounds that the Arameans had inflicted on him at Ramah when he fought against Hazael king of Aram. Then Ahaziah son of Jehoram king of Judah went down to Jezreel to visit Joram son of Ahab, because Joram had been wounded.'),
  ('BSB', '2 Kings', 12, 9, 1, 'Now Elisha the prophet summoned one of the sons of the prophets and said to him, “Tuck your cloak under your belt, take this flask of oil, and go to Ramoth-gilead.'),
  ('BSB', '2 Kings', 12, 9, 2, 'When you arrive, look for Jehu son of Jehoshaphat, the son of Nimshi. Go in, get him away from his companions, and take him to an inner room.'),
  ('BSB', '2 Kings', 12, 9, 3, 'Then take the flask of oil, pour it on his head, and declare, ‘This is what the LORD says: I anoint you king over Israel.’ Then open the door and run. Do not delay!”'),
  ('BSB', '2 Kings', 12, 9, 4, 'So the young prophet went to Ramoth-gilead,'),
  ('BSB', '2 Kings', 12, 9, 5, 'and when he arrived, the army commanders were sitting there. “I have a message for you, commander,” he said. “For which of us?” asked Jehu. “For you, commander,” he replied.'),
  ('BSB', '2 Kings', 12, 9, 6, 'So Jehu got up and went into the house, where the young prophet poured the oil on his head and declared, “This is what the LORD, the God of Israel, says: ‘I anoint you king over the LORD’s people Israel.'),
  ('BSB', '2 Kings', 12, 9, 7, 'And you are to strike down the house of your master Ahab, so that I may avenge the blood of My servants the prophets and the blood of all the servants of the LORD shed by the hand of Jezebel.'),
  ('BSB', '2 Kings', 12, 9, 8, 'The whole house of Ahab will perish, and I will cut off from Ahab every male, both slave and free, in Israel.'),
  ('BSB', '2 Kings', 12, 9, 9, 'I will make the house of Ahab like the houses of Jeroboam son of Nebat and Baasha son of Ahijah.'),
  ('BSB', '2 Kings', 12, 9, 10, 'And on the plot of ground at Jezreel the dogs will devour Jezebel, and there will be no one to bury her.’” Then the young prophet opened the door and ran.'),
  ('BSB', '2 Kings', 12, 9, 11, 'When Jehu went out to the servants of his master, they asked, “Is everything all right? Why did this madman come to you?” “You know his kind and their babble,” he replied.'),
  ('BSB', '2 Kings', 12, 9, 12, '“That is a lie!” they said. “Tell us now!” So Jehu answered, “He talked to me about this and that, and he said, ‘This is what the LORD says: I anoint you king over Israel.’”'),
  ('BSB', '2 Kings', 12, 9, 13, 'Quickly, each man took his garment and put it under Jehu on the bare steps. Then they blew the ram’s horn and proclaimed, “Jehu is king!”'),
  ('BSB', '2 Kings', 12, 9, 14, 'Thus Jehu son of Jehoshaphat, the son of Nimshi, conspired against Joram. (Now Joram and all Israel had been defending Ramoth-gilead against Hazael king of Aram,'),
  ('BSB', '2 Kings', 12, 9, 15, 'but King Joram had returned to Jezreel to recover from the wounds he had suffered at the hands of the Arameans in the battle against Hazael their king.) So Jehu said, “If you commanders wish to make me king, then do not let anyone escape from the city to go and tell it in Jezreel.”'),
  ('BSB', '2 Kings', 12, 9, 16, 'Then Jehu got into his chariot and went to Jezreel, because Joram was laid up there and Ahaziah king of Judah had gone down to see him.'),
  ('BSB', '2 Kings', 12, 9, 17, 'Now the watchman standing on the tower in Jezreel saw Jehu’s troops approaching, and he called out, “I see a company of troops!” “Choose a rider,” Joram commanded. “Send him out to meet them and ask, ‘Have you come in peace?’”'),
  ('BSB', '2 Kings', 12, 9, 18, 'So a horseman rode off to meet Jehu and said, “This is what the king asks: ‘Have you come in peace?’” “What do you know about peace?” Jehu replied. “Fall in behind me.” And the watchman reported, “The messenger reached them, but he is not coming back.”'),
  ('BSB', '2 Kings', 12, 9, 19, 'So the king sent out a second horseman, who went to them and said, “This is what the king asks: ‘Have you come in peace?’” “What do you know about peace?” Jehu replied. “Fall in behind me.”'),
  ('BSB', '2 Kings', 12, 9, 20, 'Again the watchman reported, “He reached them, but he is not coming back. And the charioteer is driving like Jehu son of Nimshi—he is driving like a madman!”'),
  ('BSB', '2 Kings', 12, 9, 21, '“Harness!” Joram shouted, and they harnessed his chariot. Then Joram king of Israel and Ahaziah king of Judah set out, each in his own chariot, and met Jehu on the property of Naboth the Jezreelite.'),
  ('BSB', '2 Kings', 12, 9, 22, 'When Joram saw Jehu, he asked, “Have you come in peace, Jehu?” “How can there be peace,” he replied, “as long as the idolatry and witchcraft of your mother Jezebel abound?”'),
  ('BSB', '2 Kings', 12, 9, 23, 'Joram turned around and fled, calling out to Ahaziah, “Treachery, Ahaziah!”'),
  ('BSB', '2 Kings', 12, 9, 24, 'Then Jehu drew his bow and shot Joram between the shoulders. The arrow pierced his heart, and he slumped down in his chariot.'),
  ('BSB', '2 Kings', 12, 9, 25, 'And Jehu said to Bidkar his officer, “Pick him up and throw him into the field of Naboth the Jezreelite. For remember that when you and I were riding together behind his father Ahab, the LORD lifted up this burden against him:'),
  ('BSB', '2 Kings', 12, 9, 26, '‘As surely as I saw the blood of Naboth and the blood of his sons yesterday, declares the LORD, so will I repay you on this plot of ground, declares the LORD.’ Now then, according to the word of the LORD, pick him up and throw him on the plot of ground.”'),
  ('BSB', '2 Kings', 12, 9, 27, 'When King Ahaziah of Judah saw this, he fled up the road toward Beth-haggan. And Jehu pursued him, shouting, “Shoot him too!” So they shot Ahaziah in his chariot on the Ascent of Gur, near Ibleam, and he fled to Megiddo and died there.'),
  ('BSB', '2 Kings', 12, 9, 28, 'Then his servants carried him by chariot to Jerusalem and buried him with his fathers in his tomb in the City of David.'),
  ('BSB', '2 Kings', 12, 9, 29, '(In the eleventh year of Joram son of Ahab, Ahaziah had become king over Judah.)'),
  ('BSB', '2 Kings', 12, 9, 30, 'Now when Jehu arrived in Jezreel, Jezebel heard of it. So she painted her eyes, adorned her head, and looked down from a window.'),
  ('BSB', '2 Kings', 12, 9, 31, 'And as Jehu entered the gate, she asked, “Have you come in peace, O Zimri, murderer of your master?”'),
  ('BSB', '2 Kings', 12, 9, 32, 'He looked up at the window and called out, “Who is on my side? Who?” And two or three eunuchs looked down at him.'),
  ('BSB', '2 Kings', 12, 9, 33, '“Throw her down!” yelled Jehu. So they threw her down, and her blood splattered on the wall and on the horses as they trampled her underfoot.'),
  ('BSB', '2 Kings', 12, 9, 34, 'Then Jehu went in and ate and drank. “Take care of this cursed woman,” he said, “and bury her, for she was the daughter of a king.”'),
  ('BSB', '2 Kings', 12, 9, 35, 'But when they went out to bury her, they found nothing but her skull, her feet, and the palms of her hands.'),
  ('BSB', '2 Kings', 12, 9, 36, 'So they went back and told Jehu, who replied, “This is the word of the LORD, which He spoke through His servant Elijah the Tishbite: ‘On the plot of ground at Jezreel the dogs will devour the flesh of Jezebel.'),
  ('BSB', '2 Kings', 12, 9, 37, 'And Jezebel’s body will lie like dung in the field on the plot of ground at Jezreel, so that no one can say: This is Jezebel.’”'),
  ('BSB', '2 Kings', 12, 10, 1, 'Now Ahab had seventy sons in Samaria. So Jehu wrote letters and sent them to Samaria to the officials of Jezreel, to the elders, and to the guardians of the sons of Ahab, saying:'),
  ('BSB', '2 Kings', 12, 10, 2, '“When this letter arrives, since your master’s sons are with you and you have chariots and horses, a fortified city and weaponry,'),
  ('BSB', '2 Kings', 12, 10, 3, 'select the best and most worthy son of your master, set him on his father’s throne, and fight for your master’s house.”'),
  ('BSB', '2 Kings', 12, 10, 4, 'But they were terrified and reasoned, “If two kings could not stand against him, how can we?”'),
  ('BSB', '2 Kings', 12, 10, 5, 'So the palace administrator, the overseer of the city, the elders, and the guardians sent a message to Jehu: “We are your servants, and we will do whatever you say. We will not make anyone king. Do whatever is good in your sight.”'),
  ('BSB', '2 Kings', 12, 10, 6, 'Then Jehu wrote them a second letter and said: “If you are on my side, and if you will obey me, then bring the heads of your master’s sons to me at Jezreel by this time tomorrow.” Now the sons of the king, seventy in all, were being brought up by the leading men of the city.'),
  ('BSB', '2 Kings', 12, 10, 7, 'And when the letter arrived, they took the sons of the king and slaughtered all seventy of them. They put their heads in baskets and sent them to Jehu at Jezreel.'),
  ('BSB', '2 Kings', 12, 10, 8, 'When the messenger arrived, he told Jehu, “They have brought the heads of the sons of the king.” And Jehu ordered, “Pile them in two heaps at the entrance of the gate until morning.”'),
  ('BSB', '2 Kings', 12, 10, 9, 'The next morning, Jehu went out and stood before all the people and said, “You are innocent. It was I who conspired against my master and killed him. But who killed all these?'),
  ('BSB', '2 Kings', 12, 10, 10, 'Know, then, that not a word the LORD has spoken against the house of Ahab will fail, for the LORD has done what He promised through His servant Elijah.”'),
  ('BSB', '2 Kings', 12, 10, 11, 'So Jehu killed everyone in Jezreel who remained of the house of Ahab, as well as all his great men and close friends and priests, leaving him without a single survivor.'),
  ('BSB', '2 Kings', 12, 10, 12, 'Then Jehu set out toward Samaria. At Beth-eked of the Shepherds,'),
  ('BSB', '2 Kings', 12, 10, 13, 'Jehu met some relatives of Ahaziah king of Judah and asked, “Who are you?” “We are relatives of Ahaziah,” they answered, “and we have come down to greet the sons of the king and of the queen mother.”'),
  ('BSB', '2 Kings', 12, 10, 14, 'Then Jehu ordered, “Take them alive.” So his men took them alive, then slaughtered them at the well of Beth-eked—forty-two men. He spared none of them.'),
  ('BSB', '2 Kings', 12, 10, 15, 'When he left there, he found Jehonadab son of Rechab, who was coming to meet him. Jehu greeted him and asked, “Is your heart as true to mine as my heart is to yours?” “It is!” Jehonadab replied. “If it is,” said Jehu, “give me your hand.” So he gave him his hand, and Jehu helped him into his chariot,'),
  ('BSB', '2 Kings', 12, 10, 16, 'saying, “Come with me and see my zeal for the LORD!” So he had him ride in his chariot.'),
  ('BSB', '2 Kings', 12, 10, 17, 'When Jehu came to Samaria, he struck down everyone belonging to Ahab who remained there, until he had destroyed them, according to the word that the LORD had spoken to Elijah.'),
  ('BSB', '2 Kings', 12, 10, 18, 'Then Jehu brought all the people together and said, “Ahab served Baal a little, but Jehu will serve him a lot.'),
  ('BSB', '2 Kings', 12, 10, 19, 'Now, therefore, summon to me all the prophets of Baal, all his servants, and all his priests. See that no one is missing, for I have a great sacrifice for Baal. Whoever is missing will not live.” But Jehu was acting deceptively in order to destroy the servants of Baal.'),
  ('BSB', '2 Kings', 12, 10, 20, 'And Jehu commanded, “Proclaim a solemn assembly for Baal.” So they announced it.'),
  ('BSB', '2 Kings', 12, 10, 21, 'Then Jehu sent word throughout Israel, and all the servants of Baal came; there was not a man who failed to show. They entered the temple of Baal, and it was filled from end to end.'),
  ('BSB', '2 Kings', 12, 10, 22, 'And Jehu said to the keeper of the wardrobe, “Bring out garments for all the servants of Baal.” So he brought out garments for them.'),
  ('BSB', '2 Kings', 12, 10, 23, 'Next, Jehu and Jehonadab son of Rechab entered the temple of Baal, and Jehu said to the servants of Baal, “Look around to see that there are no servants of the LORD here among you—only servants of Baal.”'),
  ('BSB', '2 Kings', 12, 10, 24, 'And they went in to offer sacrifices and burnt offerings. Now Jehu had stationed eighty men outside and warned them, “If anyone allows one of the men I am delivering into your hands to escape, he will forfeit his life for theirs.”'),
  ('BSB', '2 Kings', 12, 10, 25, 'When he had finished making the burnt offering, Jehu said to the guards and officers, “Go in and kill them. Do not let anyone out.” So the guards and officers put them to the sword, threw the bodies out, and went into the inner room of the temple of Baal.'),
  ('BSB', '2 Kings', 12, 10, 26, 'They brought out the sacred pillar of the temple of Baal and burned it.'),
  ('BSB', '2 Kings', 12, 10, 27, 'They also demolished the sacred pillar of Baal. Then they tore down the temple of Baal and made it into a latrine, which it is to this day.'),
  ('BSB', '2 Kings', 12, 10, 28, 'Thus Jehu eradicated Baal from Israel,'),
  ('BSB', '2 Kings', 12, 10, 29, 'but he did not turn away from the sins that Jeroboam son of Nebat had caused Israel to commit—the worship of the golden calves at Bethel and Dan.'),
  ('BSB', '2 Kings', 12, 10, 30, 'Nevertheless, the LORD said to Jehu, “Because you have done well in carrying out what is right in My sight and have done to the house of Ahab all that was in My heart, four generations of your sons will sit on the throne of Israel.”'),
  ('BSB', '2 Kings', 12, 10, 31, 'Yet Jehu was not careful to follow the instruction of the LORD, the God of Israel, with all his heart. He did not turn away from the sins that Jeroboam had caused Israel to commit.'),
  ('BSB', '2 Kings', 12, 10, 32, 'In those days the LORD began to reduce the size of Israel. Hazael defeated the Israelites throughout their territory'),
  ('BSB', '2 Kings', 12, 10, 33, 'from the Jordan eastward through all the land of Gilead (the region of Gad, Reuben, and Manasseh), and from Aroer by the Arnon Valley through Gilead to Bashan.'),
  ('BSB', '2 Kings', 12, 10, 34, 'As for the rest of the acts of Jehu, along with all his accomplishments and all his might, are they not written in the Book of the Chronicles of the Kings of Israel?'),
  ('BSB', '2 Kings', 12, 10, 35, 'And Jehu rested with his fathers and was buried in Samaria, and his son Jehoahaz reigned in his place.'),
  ('BSB', '2 Kings', 12, 10, 36, 'So the duration of Jehu’s reign over Israel in Samaria was twenty-eight years.'),
  ('BSB', '2 Kings', 12, 11, 1, 'When Athaliah the mother of Ahaziah saw that her son was dead, she proceeded to annihilate all the royal heirs.'),
  ('BSB', '2 Kings', 12, 11, 2, 'But Jehosheba daughter of King Joram, the sister of Ahaziah, took Joash son of Ahaziah and stole him away from among the sons of the king who were being murdered. She put him and his nurse in a bedroom to hide him from Athaliah, and he was not killed.'),
  ('BSB', '2 Kings', 12, 11, 3, 'And Joash remained hidden with his nurse in the house of the LORD for six years while Athaliah ruled the land.'),
  ('BSB', '2 Kings', 12, 11, 4, 'Then in the seventh year, Jehoiada sent for the commanders of hundreds, the Carites, and the guards, and had them brought into the house of the LORD. There he made a covenant with them and put them under oath. He showed them the king’s son'),
  ('BSB', '2 Kings', 12, 11, 5, 'and commanded them, “This is what you are to do: A third of you who come on duty on the Sabbath shall guard the royal palace,'),
  ('BSB', '2 Kings', 12, 11, 6, 'a third shall be at the gate of Sur, and a third at the gate behind the guards. You are to take turns guarding the temple—'),
  ('BSB', '2 Kings', 12, 11, 7, 'the two divisions that would go off duty on the Sabbath are to guard the house of the LORD for the king.'),
  ('BSB', '2 Kings', 12, 11, 8, 'You must surround the king with weapons in hand, and anyone who approaches the ranks must be put to death. You must stay close to the king wherever he goes.”'),
  ('BSB', '2 Kings', 12, 11, 9, 'So the commanders of hundreds did everything that Jehoiada the priest had ordered. Each of them took his men—those coming on duty on the Sabbath and those going off duty—and came to Jehoiada the priest.'),
  ('BSB', '2 Kings', 12, 11, 10, 'Then the priest gave to the commanders of hundreds the spears and shields of King David from the house of the LORD.'),
  ('BSB', '2 Kings', 12, 11, 11, 'And the guards stood with weapons in hand surrounding the king by the altar and the temple, from the south side to the north side of the temple.'),
  ('BSB', '2 Kings', 12, 11, 12, 'Then Jehoiada brought out the king’s son, put the crown on him, presented him with the Testimony, and proclaimed him king. They anointed him, and the people clapped their hands and declared, “Long live the king!”'),
  ('BSB', '2 Kings', 12, 11, 13, 'When Athaliah heard the noise from the guards and the people, she went out to the people in the house of the LORD.'),
  ('BSB', '2 Kings', 12, 11, 14, 'And she looked out and saw the king standing by the pillar, according to the custom. The officers and trumpeters were beside the king, and all the people of the land were rejoicing and blowing trumpets. Then Athaliah tore her clothes and screamed, “Treason! Treason!”'),
  ('BSB', '2 Kings', 12, 11, 15, 'And Jehoiada the priest ordered the commanders of hundreds in charge of the army, “Bring her out between the ranks, and put to the sword anyone who follows her.” For the priest had said, “She must not be put to death in the house of the LORD.”'),
  ('BSB', '2 Kings', 12, 11, 16, 'So they seized Athaliah as she reached the horses’ entrance to the palace grounds, and there she was put to death.'),
  ('BSB', '2 Kings', 12, 11, 17, 'Then Jehoiada made a covenant between the LORD and the king and the people that they would be the LORD’s people. He also made a covenant between the king and the people.'),
  ('BSB', '2 Kings', 12, 11, 18, 'So all the people of the land went to the temple of Baal and tore it down. They smashed the altars and idols to pieces, and they killed Mattan the priest of Baal in front of the altars. And Jehoiada the priest posted guards for the house of the LORD.'),
  ('BSB', '2 Kings', 12, 11, 19, 'He took with him the commanders of hundreds, the Carites, the guards, and all the people of the land, and they brought the king down from the house of the LORD and entered the royal palace by way of the Gate of the Guards. Then Joash took his seat on the royal throne,'),
  ('BSB', '2 Kings', 12, 11, 20, 'and all the people of the land rejoiced. And the city was quiet, because Athaliah had been put to the sword at the royal palace.'),
  ('BSB', '2 Kings', 12, 11, 21, 'Joash was seven years old when he became king.'),
  ('BSB', '2 Kings', 12, 12, 1, 'In the seventh year of Jehu, Joash became king, and he reigned in Jerusalem forty years. His mother’s name was Zibiah; she was from Beersheba.'),
  ('BSB', '2 Kings', 12, 12, 2, 'And Joash did what was right in the eyes of the LORD all the days he was instructed by Jehoiada the priest.'),
  ('BSB', '2 Kings', 12, 12, 3, 'Nevertheless, the high places were not removed; the people continued sacrificing and burning incense there.'),
  ('BSB', '2 Kings', 12, 12, 4, 'Then Joash said to the priests, “Collect all the money brought as sacred gifts into the house of the LORD—the census money, the money from vows, and the money brought voluntarily into the house of the LORD.'),
  ('BSB', '2 Kings', 12, 12, 5, 'Let every priest receive it from his constituency, and let it be used to repair any damage found in the temple.”'),
  ('BSB', '2 Kings', 12, 12, 6, 'By the twenty-third year of the reign of Joash, however, the priests had not yet repaired the damage to the temple.'),
  ('BSB', '2 Kings', 12, 12, 7, 'So King Joash called Jehoiada and the other priests and said, “Why have you not repaired the damage to the temple? Now, therefore, take no more money from your constituency, but hand it over for the repair of the temple.”'),
  ('BSB', '2 Kings', 12, 12, 8, 'So the priests agreed that they would not receive money from the people and that they would not repair the temple themselves.'),
  ('BSB', '2 Kings', 12, 12, 9, 'Then Jehoiada the priest took a chest, bored a hole in its lid, and set it beside the altar on the right side as one enters the house of the LORD. There the priests who guarded the threshold put all the money brought into the house of the LORD.'),
  ('BSB', '2 Kings', 12, 12, 10, 'Whenever they saw that there was a large amount of money in the chest, the royal scribe and the high priest would go up, count the money brought into the house of the LORD, and tie it up in bags.'),
  ('BSB', '2 Kings', 12, 12, 11, 'Then they would put the counted money into the hands of those who supervised the work on the house of the LORD, who in turn would pay those doing the work—the carpenters, builders,'),
  ('BSB', '2 Kings', 12, 12, 12, 'masons, and stonecutters. They also purchased timber and dressed stone to repair the damage to the house of the LORD, and they paid the other expenses of the temple repairs.'),
  ('BSB', '2 Kings', 12, 12, 13, 'However, the money brought into the house of the LORD was not used for making silver basins, wick trimmers, sprinkling bowls, trumpets, or any articles of gold or silver for the house of the LORD.'),
  ('BSB', '2 Kings', 12, 12, 14, 'Instead, it was paid to those doing the work, and with it they repaired the house of the LORD.'),
  ('BSB', '2 Kings', 12, 12, 15, 'No accounting was required from the men who received the money to pay the workmen, because they acted with integrity.'),
  ('BSB', '2 Kings', 12, 12, 16, 'The money from the guilt offerings and sin offerings was not brought into the house of the LORD; it belonged to the priests.'),
  ('BSB', '2 Kings', 12, 12, 17, 'At that time Hazael king of Aram marched up and fought against Gath and captured it. Then he decided to attack Jerusalem.'),
  ('BSB', '2 Kings', 12, 12, 18, 'So King Joash of Judah took all the sacred objects dedicated by his fathers—Jehoshaphat, Jehoram, and Ahaziah, the kings of Judah—along with his own consecrated items and all the gold found in the treasuries of the house of the LORD and the royal palace, and he sent them to Hazael king of Aram. So Hazael withdrew from Jerusalem.'),
  ('BSB', '2 Kings', 12, 12, 19, 'As for the rest of the acts of Joash, along with all his accomplishments, are they not written in the Book of the Chronicles of the Kings of Judah?'),
  ('BSB', '2 Kings', 12, 12, 20, 'And the servants of Joash rose up and formed a conspiracy and killed him at Beth-millo, on the road down to Silla.'),
  ('BSB', '2 Kings', 12, 12, 21, 'His servants Jozabad son of Shimeath and Jehozabad son of Shomer struck him down, and he died. And they buried him with his fathers in the City of David, and his son Amaziah reigned in his place.'),
  ('BSB', '2 Kings', 12, 13, 1, 'In the twenty-third year of the reign of Joash son of Ahaziah over Judah, Jehoahaz son of Jehu became king of Israel, and he reigned in Samaria seventeen years.'),
  ('BSB', '2 Kings', 12, 13, 2, 'And he did evil in the sight of the LORD and followed the sins that Jeroboam son of Nebat had caused Israel to commit; he did not turn away from them.'),
  ('BSB', '2 Kings', 12, 13, 3, 'So the anger of the LORD burned against Israel, and He delivered them continually into the hands of Hazael king of Aram and his son Ben-hadad.'),
  ('BSB', '2 Kings', 12, 13, 4, 'Then Jehoahaz sought the favor of the LORD, and the LORD listened to him because He saw the oppression that the king of Aram had inflicted on Israel.'),
  ('BSB', '2 Kings', 12, 13, 5, 'So the LORD gave Israel a deliverer, and they escaped the power of the Arameans. Then the people of Israel lived in their own homes as they had before.'),
  ('BSB', '2 Kings', 12, 13, 6, 'Nevertheless, they did not turn away from the sins that the house of Jeroboam had caused Israel to commit, but they continued to walk in them. The Asherah pole even remained standing in Samaria.'),
  ('BSB', '2 Kings', 12, 13, 7, 'Jehoahaz had no army left, except fifty horsemen, ten chariots, and ten thousand foot soldiers, because the king of Aram had destroyed them and made them like the dust at threshing.'),
  ('BSB', '2 Kings', 12, 13, 8, 'As for the rest of the acts of Jehoahaz, along with all his accomplishments and his might, are they not written in the Book of the Chronicles of the Kings of Israel?'),
  ('BSB', '2 Kings', 12, 13, 9, 'And Jehoahaz rested with his fathers and was buried in Samaria. And his son Jehoash reigned in his place.'),
  ('BSB', '2 Kings', 12, 13, 10, 'In the thirty-seventh year of the reign of Joash over Judah, Jehoash son of Jehoahaz became king of Israel in Samaria, and he reigned sixteen years.'),
  ('BSB', '2 Kings', 12, 13, 11, 'And he did evil in the sight of the LORD and did not turn away from all the sins that Jeroboam son of Nebat had caused Israel to commit, but he walked in them.'),
  ('BSB', '2 Kings', 12, 13, 12, 'As for the rest of the acts of Jehoash, along with all his accomplishments and his might, including his war against Amaziah king of Judah, are they not written in the Book of the Chronicles of the Kings of Israel?'),
  ('BSB', '2 Kings', 12, 13, 13, 'And Jehoash rested with his fathers, and Jeroboam succeeded him on the throne. Jehoash was buried in Samaria with the kings of Israel.'),
  ('BSB', '2 Kings', 12, 13, 14, 'When Elisha had fallen sick with the illness from which he would die, Jehoash king of Israel came down to him and wept over him, saying, “My father, my father, the chariots and horsemen of Israel!”'),
  ('BSB', '2 Kings', 12, 13, 15, 'Elisha told him, “Take a bow and some arrows.” So Jehoash took a bow and some arrows.'),
  ('BSB', '2 Kings', 12, 13, 16, 'Then Elisha said to the king of Israel, “Put your hand on the bow.” So the king put his hand on the bow, and Elisha put his hands on the king’s hands.'),
  ('BSB', '2 Kings', 12, 13, 17, '“Open the east window,” said Elisha. So he opened it and Elisha said, “Shoot!” So he shot. And Elisha declared: “This is the LORD’s arrow of victory, the arrow of victory over Aram, for you shall strike the Arameans in Aphek until you have put an end to them.”'),
  ('BSB', '2 Kings', 12, 13, 18, 'Then Elisha said, “Take the arrows!” So he took them, and Elisha said to the king of Israel, “Strike the ground!” So he struck the ground three times and stopped.'),
  ('BSB', '2 Kings', 12, 13, 19, 'But the man of God was angry with him and said, “You should have struck the ground five or six times. Then you would have struck down Aram until you had put an end to it. But now you will strike down Aram only three times.”'),
  ('BSB', '2 Kings', 12, 13, 20, 'And Elisha died and was buried. Now the Moabite raiders used to come into the land every spring.'),
  ('BSB', '2 Kings', 12, 13, 21, 'Once, as the Israelites were burying a man, suddenly they saw a band of raiders, so they threw the man’s body into Elisha’s tomb. And as soon as his body touched the bones of Elisha, the man was revived and stood up on his feet.'),
  ('BSB', '2 Kings', 12, 13, 22, 'And Hazael king of Aram oppressed Israel throughout the reign of Jehoahaz.'),
  ('BSB', '2 Kings', 12, 13, 23, 'But the LORD was gracious to Israel and had compassion on them, and He turned toward them because of His covenant with Abraham, Isaac, and Jacob. And to this day, the LORD has been unwilling to destroy them or cast them from His presence.'),
  ('BSB', '2 Kings', 12, 13, 24, 'When Hazael king of Aram died, his son Ben-hadad reigned in his place.'),
  ('BSB', '2 Kings', 12, 13, 25, 'Then Jehoash son of Jehoahaz took back from Ben-hadad son of Hazael the cities that Hazael had taken in battle from his father Jehoahaz. Jehoash defeated Ben-hadad three times, and so recovered the cities of Israel.'),
  ('BSB', '2 Kings', 12, 14, 1, 'In the second year of the reign of Jehoash son of Jehoahaz over Israel, Amaziah son of Joash became king of Judah.'),
  ('BSB', '2 Kings', 12, 14, 2, 'He was twenty-five years old when he became king, and he reigned in Jerusalem twenty-nine years. His mother’s name was Jehoaddan; she was from Jerusalem.'),
  ('BSB', '2 Kings', 12, 14, 3, 'And he did what was right in the eyes of the LORD, but not as his father David had done. He did everything as his father Joash had done.'),
  ('BSB', '2 Kings', 12, 14, 4, 'Nevertheless, the high places were not taken away, and the people continued sacrificing and burning incense on the high places.'),
  ('BSB', '2 Kings', 12, 14, 5, 'As soon as the kingdom was firmly in his grasp, Amaziah executed the servants who had murdered his father the king.'),
  ('BSB', '2 Kings', 12, 14, 6, 'Yet he did not put the sons of the murderers to death, but acted according to what is written in the Book of the Law of Moses, where the LORD commanded: “Fathers must not be put to death for their children, and children must not be put to death for their fathers; each is to die for his own sin.”'),
  ('BSB', '2 Kings', 12, 14, 7, 'Amaziah struck down 10,000 Edomites in the Valley of Salt. He took Sela in battle and called it Joktheel, which is its name to this very day.'),
  ('BSB', '2 Kings', 12, 14, 8, 'Then Amaziah sent messengers to the king of Israel Jehoash son of Jehoahaz, the son of Jehu. “Come, let us meet face to face,” he said.'),
  ('BSB', '2 Kings', 12, 14, 9, 'But Jehoash king of Israel replied to Amaziah king of Judah: “A thistle in Lebanon sent a message to a cedar in Lebanon, saying, ‘Give your daughter to my son in marriage.’ Then a wild beast in Lebanon came along and trampled the thistle.'),
  ('BSB', '2 Kings', 12, 14, 10, 'You have indeed defeated Edom, and your heart has become proud. Glory in that and stay at home. Why should you stir up trouble so that you fall—you and Judah with you?”'),
  ('BSB', '2 Kings', 12, 14, 11, 'But Amaziah would not listen, and Jehoash king of Israel advanced. He and King Amaziah of Judah faced each other at Beth-shemesh in Judah.'),
  ('BSB', '2 Kings', 12, 14, 12, 'And Judah was routed before Israel, and every man fled to his home.'),
  ('BSB', '2 Kings', 12, 14, 13, 'There at Beth-shemesh, Jehoash king of Israel captured Amaziah king of Judah, the son of Joash, the son of Ahaziah. Then Jehoash went to Jerusalem and broke down the wall of Jerusalem from the Ephraim Gate to the Corner Gate—a section of four hundred cubits.'),
  ('BSB', '2 Kings', 12, 14, 14, 'He took all the gold and silver and all the articles found in the house of the LORD and in the treasuries of the royal palace, as well as some hostages. Then he returned to Samaria.'),
  ('BSB', '2 Kings', 12, 14, 15, 'As for the rest of the acts of Jehoash, along with his accomplishments, his might, and how he waged war against Amaziah king of Judah, are they not written in the Book of the Chronicles of the Kings of Israel?'),
  ('BSB', '2 Kings', 12, 14, 16, 'And Jehoash rested with his fathers and was buried in Samaria with the kings of Israel. And his son Jeroboam reigned in his place.'),
  ('BSB', '2 Kings', 12, 14, 17, 'Amaziah son of Joash king of Judah lived for fifteen years after the death of Jehoash son of Jehoahaz king of Israel.'),
  ('BSB', '2 Kings', 12, 14, 18, 'As for the rest of the acts of Amaziah, are they not written in the Book of the Chronicles of the Kings of Judah?'),
  ('BSB', '2 Kings', 12, 14, 19, 'And conspirators plotted against Amaziah in Jerusalem, and he fled to Lachish. But men were sent after him to Lachish, and they killed him there.'),
  ('BSB', '2 Kings', 12, 14, 20, 'They carried him back on horses and buried him in Jerusalem with his fathers in the City of David.'),
  ('BSB', '2 Kings', 12, 14, 21, 'Then all the people of Judah took Azariah, who was sixteen years old, and made him king in place of his father Amaziah.'),
  ('BSB', '2 Kings', 12, 14, 22, 'Azariah was the one who rebuilt Elath and restored it to Judah after King Amaziah rested with his fathers.'),
  ('BSB', '2 Kings', 12, 14, 23, 'In the fifteenth year of the reign of Amaziah son of Joash over Judah, Jeroboam son of Jehoash became king of Israel, and he reigned in Samaria forty-one years.'),
  ('BSB', '2 Kings', 12, 14, 24, 'And he did evil in the sight of the LORD and did not turn away from all the sins that Jeroboam son of Nebat had caused Israel to commit.'),
  ('BSB', '2 Kings', 12, 14, 25, 'This Jeroboam restored the boundary of Israel from Lebo-hamath to the Sea of the Arabah, according to the word that the LORD, the God of Israel, had spoken through His servant Jonah son of Amittai, the prophet from Gath-hepher.'),
  ('BSB', '2 Kings', 12, 14, 26, 'For the LORD saw that the affliction of the Israelites, both slave and free, was very bitter. There was no one to help Israel,'),
  ('BSB', '2 Kings', 12, 14, 27, 'and since the LORD had said that He would not blot out the name of Israel from under heaven, He saved them by the hand of Jeroboam son of Jehoash.'),
  ('BSB', '2 Kings', 12, 14, 28, 'As for the rest of the acts of Jeroboam, along with all his accomplishments and might, and how he waged war and recovered both Damascus and Hamath for Israel from Judah, are they not written in the Book of the Chronicles of the Kings of Israel?'),
  ('BSB', '2 Kings', 12, 14, 29, 'And Jeroboam rested with his fathers, the kings of Israel. And his son Zechariah reigned in his place.'),
  ('BSB', '2 Kings', 12, 15, 1, 'In the twenty-seventh year of Jeroboam’s reign over Israel, Azariah son of Amaziah became king of Judah.'),
  ('BSB', '2 Kings', 12, 15, 2, 'He was sixteen years old when he became king, and he reigned in Jerusalem fifty-two years. His mother’s name was Jecoliah; she was from Jerusalem.'),
  ('BSB', '2 Kings', 12, 15, 3, 'And he did what was right in the eyes of the LORD, just as his father Amaziah had done.'),
  ('BSB', '2 Kings', 12, 15, 4, 'Nevertheless, the high places were not taken away; the people continued sacrificing and burning incense there.'),
  ('BSB', '2 Kings', 12, 15, 5, 'And the LORD afflicted the king with leprosy until the day he died, so that he lived in a separate house while his son Jotham had charge of the palace and governed the people of the land.'),
  ('BSB', '2 Kings', 12, 15, 6, 'As for the rest of the acts of Azariah, along with all his accomplishments, are they not written in the Book of the Chronicles of the Kings of Judah?'),
  ('BSB', '2 Kings', 12, 15, 7, 'And Azariah rested with his fathers and was buried near them in the City of David. And his son Jotham reigned in his place.'),
  ('BSB', '2 Kings', 12, 15, 8, 'In the thirty-eighth year of Azariah’s reign over Judah, Zechariah son of Jeroboam became king of Israel, and he reigned in Samaria six months.'),
  ('BSB', '2 Kings', 12, 15, 9, 'And he did evil in the sight of the LORD, as his fathers had done. He did not turn away from the sins that Jeroboam son of Nebat had caused Israel to commit.'),
  ('BSB', '2 Kings', 12, 15, 10, 'Then Shallum son of Jabesh conspired against Zechariah, struck him down and killed him in front of the people, and reigned in his place.'),
  ('BSB', '2 Kings', 12, 15, 11, 'As for the rest of the acts of Zechariah, they are indeed written in the Book of the Chronicles of the Kings of Israel.'),
  ('BSB', '2 Kings', 12, 15, 12, 'So the word of the LORD spoken to Jehu was fulfilled: “Four generations of your sons will sit on the throne of Israel.”'),
  ('BSB', '2 Kings', 12, 15, 13, 'In the thirty-ninth year of Uzziah’s reign over Judah, Shallum son of Jabesh became king, and he reigned in Samaria one full month.'),
  ('BSB', '2 Kings', 12, 15, 14, 'Then Menahem son of Gadi went up from Tirzah to Samaria, struck down and killed Shallum son of Jabesh, and reigned in his place.'),
  ('BSB', '2 Kings', 12, 15, 15, 'As for the rest of the acts of Shallum, along with the conspiracy he led, they are indeed written in the Book of the Chronicles of the Kings of Israel.'),
  ('BSB', '2 Kings', 12, 15, 16, 'At that time Menahem, starting from Tirzah, attacked Tiphsah and everyone in its vicinity, because they would not open their gates. So he attacked Tiphsah and ripped open all the pregnant women.'),
  ('BSB', '2 Kings', 12, 15, 17, 'In the thirty-ninth year of Azariah’s reign over Judah, Menahem son of Gadi became king of Israel, and he reigned in Samaria ten years.'),
  ('BSB', '2 Kings', 12, 15, 18, 'And he did evil in the sight of the LORD, and throughout his reign he did not turn away from the sins that Jeroboam son of Nebat had caused Israel to commit.'),
  ('BSB', '2 Kings', 12, 15, 19, 'Then Pul king of Assyria invaded the land, and Menahem gave Pul a thousand talents of silver in order to gain his support and strengthen his own grip on the kingdom.'),
  ('BSB', '2 Kings', 12, 15, 20, 'Menahem exacted this money from each of the wealthy men of Israel—fifty shekels of silver from each man—to give to the king of Assyria. So the king of Assyria withdrew and did not remain in the land.'),
  ('BSB', '2 Kings', 12, 15, 21, 'As for the rest of the acts of Menahem, along with all his accomplishments, are they not written in the Book of the Chronicles of the Kings of Israel?'),
  ('BSB', '2 Kings', 12, 15, 22, 'And Menahem rested with his fathers, and his son Pekahiah reigned in his place.'),
  ('BSB', '2 Kings', 12, 15, 23, 'In the fiftieth year of Azariah’s reign over Judah, Pekahiah son of Menahem became king of Israel and reigned in Samaria two years.'),
  ('BSB', '2 Kings', 12, 15, 24, 'And he did evil in the sight of the LORD and did not turn away from the sins that Jeroboam son of Nebat had caused Israel to commit.'),
  ('BSB', '2 Kings', 12, 15, 25, 'Then his officer, Pekah son of Remaliah, conspired against him along with Argob, Arieh, and fifty men of Gilead. And at the citadel of the king’s palace in Samaria, Pekah struck down and killed Pekahiah and reigned in his place.'),
  ('BSB', '2 Kings', 12, 15, 26, 'As for the rest of the acts of Pekahiah, along with all his accomplishments, they are indeed written in the Book of the Chronicles of the Kings of Israel.'),
  ('BSB', '2 Kings', 12, 15, 27, 'In the fifty-second year of Azariah’s reign over Judah, Pekah son of Remaliah became king of Israel, and he reigned in Samaria twenty years.'),
  ('BSB', '2 Kings', 12, 15, 28, 'And he did evil in the sight of the LORD and did not turn away from the sins that Jeroboam son of Nebat had caused Israel to commit.'),
  ('BSB', '2 Kings', 12, 15, 29, 'In the days of Pekah king of Israel, Tiglath-pileser king of Assyria came and captured Ijon, Abel-beth-maacah, Janoah, Kedesh, Hazor, Gilead, and Galilee, including all the land of Naphtali, and he took the people as captives to Assyria.'),
  ('BSB', '2 Kings', 12, 15, 30, 'Then Hoshea son of Elah led a conspiracy against Pekah son of Remaliah. In the twentieth year of Jotham son of Uzziah, Hoshea attacked Pekah, killed him, and reigned in his place.'),
  ('BSB', '2 Kings', 12, 15, 31, 'As for the rest of the acts of Pekah, along with all his accomplishments, they are indeed written in the Book of the Chronicles of the Kings of Israel.'),
  ('BSB', '2 Kings', 12, 15, 32, 'In the second year of the reign of Pekah son of Remaliah over Israel, Jotham son of Uzziah became king of Judah.'),
  ('BSB', '2 Kings', 12, 15, 33, 'He was twenty-five years old when he became king, and he reigned in Jerusalem sixteen years. His mother’s name was Jerusha daughter of Zadok.'),
  ('BSB', '2 Kings', 12, 15, 34, 'And he did what was right in the eyes of the LORD, just as his father Uzziah had done.'),
  ('BSB', '2 Kings', 12, 15, 35, 'Nevertheless, the high places were not taken away; the people continued sacrificing and burning incense there. Jotham rebuilt the Upper Gate of the house of the LORD.'),
  ('BSB', '2 Kings', 12, 15, 36, 'As for the rest of the acts of Jotham, along with his accomplishments, are they not written in the Book of the Chronicles of the Kings of Judah?'),
  ('BSB', '2 Kings', 12, 15, 37, '(In those days the LORD began to send Rezin king of Aram and Pekah son of Remaliah against Judah.)'),
  ('BSB', '2 Kings', 12, 15, 38, 'And Jotham rested with his fathers and was buried with them in the City of David his father. And his son Ahaz reigned in his place.'),
  ('BSB', '2 Kings', 12, 16, 1, 'In the seventeenth year of Pekah son of Remaliah, Ahaz son of Jotham became king of Judah.'),
  ('BSB', '2 Kings', 12, 16, 2, 'Ahaz was twenty years old when he became king, and he reigned in Jerusalem sixteen years. And unlike David his father, he did not do what was right in the eyes of the LORD his God.'),
  ('BSB', '2 Kings', 12, 16, 3, 'Instead, he walked in the ways of the kings of Israel and even sacrificed his son in the fire, according to the abominations of the nations that the LORD had driven out before the Israelites.'),
  ('BSB', '2 Kings', 12, 16, 4, 'And he sacrificed and burned incense on the high places, on the hills, and under every green tree.'),
  ('BSB', '2 Kings', 12, 16, 5, 'Then Rezin king of Aram and Pekah son of Remaliah king of Israel came up to wage war against Jerusalem. They besieged Ahaz but could not overcome him.'),
  ('BSB', '2 Kings', 12, 16, 6, 'At that time Rezin king of Aram recovered Elath for Aram, drove out the men of Judah, and sent the Edomites into Elath, where they live to this day.'),
  ('BSB', '2 Kings', 12, 16, 7, 'So Ahaz sent messengers to Tiglath-pileser king of Assyria, saying, “I am your servant and your son. Come up and save me from the hands of the kings of Aram and Israel, who are rising up against me.”'),
  ('BSB', '2 Kings', 12, 16, 8, 'Ahaz also took the silver and gold found in the house of the LORD and in the treasuries of the king’s palace, and he sent it as a gift to the king of Assyria.'),
  ('BSB', '2 Kings', 12, 16, 9, 'So the king of Assyria responded to him, marched up to Damascus, and captured it. He took its people to Kir as captives and put Rezin to death.'),
  ('BSB', '2 Kings', 12, 16, 10, 'Then King Ahaz went to Damascus to meet Tiglath-pileser king of Assyria. On seeing the altar in Damascus, King Ahaz sent Uriah the priest a model of the altar and complete plans for its construction.'),
  ('BSB', '2 Kings', 12, 16, 11, 'And Uriah the priest built the altar according to all the instructions King Ahaz had sent from Damascus, and he completed it by the time King Ahaz had returned.'),
  ('BSB', '2 Kings', 12, 16, 12, 'When the king came back from Damascus and saw the altar, he approached it and presented offerings on it.'),
  ('BSB', '2 Kings', 12, 16, 13, 'He offered his burnt offering and his grain offering, poured out his drink offering, and sprinkled the blood of his peace offerings on the altar.'),
  ('BSB', '2 Kings', 12, 16, 14, 'He also took the bronze altar that stood before the LORD from the front of the temple (between the new altar and the house of the LORD) and he put it on the north side of the new altar.'),
  ('BSB', '2 Kings', 12, 16, 15, 'Then King Ahaz commanded Uriah the priest, “Offer on the great altar the morning burnt offering, the evening grain offering, and the king’s burnt offering and grain offering, as well as the burnt offerings, grain offerings, and drink offerings of all the people of the land. Sprinkle on the altar all the blood of the burnt offerings and sacrifices. But I will use the bronze altar to seek guidance.”'),
  ('BSB', '2 Kings', 12, 16, 16, 'So Uriah the priest did just as King Ahaz had commanded.'),
  ('BSB', '2 Kings', 12, 16, 17, 'King Ahaz also cut off the frames of the movable stands and removed the bronze basin from each of them. He took down the Sea from the bronze oxen that were under it and put it on a stone base.'),
  ('BSB', '2 Kings', 12, 16, 18, 'And on account of the king of Assyria, he removed the Sabbath canopy they had built in the temple and closed the royal entryway outside the house of the LORD.'),
  ('BSB', '2 Kings', 12, 16, 19, 'As for the rest of the acts of Ahaz, along with his accomplishments, are they not written in the Book of the Chronicles of the Kings of Judah?'),
  ('BSB', '2 Kings', 12, 16, 20, 'And Ahaz rested with his fathers and was buried with them in the City of David, and his son Hezekiah reigned in his place.'),
  ('BSB', '2 Kings', 12, 17, 1, 'In the twelfth year of the reign of Ahaz over Judah, Hoshea son of Elah became king of Israel, and he reigned in Samaria nine years.'),
  ('BSB', '2 Kings', 12, 17, 2, 'And he did evil in the sight of the LORD, but not like the kings of Israel who preceded him.'),
  ('BSB', '2 Kings', 12, 17, 3, 'Shalmaneser king of Assyria attacked him, and Hoshea became his vassal and paid him tribute.'),
  ('BSB', '2 Kings', 12, 17, 4, 'But the king of Assyria discovered that Hoshea had conspired to send envoys to King So of Egypt, and that he had not paid tribute to the king of Assyria as in previous years. Therefore the king of Assyria arrested Hoshea and put him in prison.'),
  ('BSB', '2 Kings', 12, 17, 5, 'Then the king of Assyria invaded the whole land, marched up to Samaria, and besieged it for three years.'),
  ('BSB', '2 Kings', 12, 17, 6, 'In the ninth year of Hoshea, the king of Assyria captured Samaria and carried away the Israelites to Assyria, where he settled them in Halah, in Gozan by the Habor River, and in the cities of the Medes.'),
  ('BSB', '2 Kings', 12, 17, 7, 'All this happened because the people of Israel had sinned against the LORD their God, who had brought them out of the land of Egypt from under the hand of Pharaoh king of Egypt. They had worshiped other gods'),
  ('BSB', '2 Kings', 12, 17, 8, 'and walked in the customs of the nations that the LORD had driven out before the Israelites, as well as in the practices introduced by the kings of Israel.'),
  ('BSB', '2 Kings', 12, 17, 9, 'The Israelites secretly did things against the LORD their God that were not right. From watchtower to fortified city, they built high places in all their cities.'),
  ('BSB', '2 Kings', 12, 17, 10, 'They set up for themselves sacred pillars and Asherah poles on every high hill and under every green tree.'),
  ('BSB', '2 Kings', 12, 17, 11, 'They burned incense on all the high places like the nations that the LORD had driven out before them. They did wicked things, provoking the LORD to anger.'),
  ('BSB', '2 Kings', 12, 17, 12, 'They served idols, although the LORD had told them, “You shall not do this thing.”'),
  ('BSB', '2 Kings', 12, 17, 13, 'Yet through all His prophets and seers, the LORD warned Israel and Judah, saying, “Turn from your wicked ways and keep My commandments and statutes, according to the entire Law that I commanded your fathers and delivered to you through My servants the prophets.”'),
  ('BSB', '2 Kings', 12, 17, 14, 'But they would not listen, and they stiffened their necks like their fathers, who did not believe the LORD their God.'),
  ('BSB', '2 Kings', 12, 17, 15, 'They rejected His statutes and the covenant He had made with their fathers, as well as the decrees He had given them. They pursued worthless idols and themselves became worthless, going after the surrounding nations that the LORD had commanded them not to imitate.'),
  ('BSB', '2 Kings', 12, 17, 16, 'They abandoned all the commandments of the LORD their God and made for themselves two cast idols of calves and an Asherah pole. They bowed down to all the host of heaven and served Baal.');
insert into control_room_bible (version, book, book_num, chapter, verse, text) values
  ('BSB', '2 Kings', 12, 17, 17, 'They sacrificed their sons and daughters in the fire and practiced divination and soothsaying. They devoted themselves to doing evil in the sight of the LORD, provoking Him to anger.'),
  ('BSB', '2 Kings', 12, 17, 18, 'So the LORD was very angry with Israel, and He removed them from His presence. Only the tribe of Judah remained,'),
  ('BSB', '2 Kings', 12, 17, 19, 'and even Judah did not keep the commandments of the LORD their God, but lived according to the customs Israel had introduced.'),
  ('BSB', '2 Kings', 12, 17, 20, 'So the LORD rejected all the descendants of Israel. He afflicted them and delivered them into the hands of plunderers, until He had banished them from His presence.'),
  ('BSB', '2 Kings', 12, 17, 21, 'When the LORD had torn Israel away from the house of David, they made Jeroboam son of Nebat king, and Jeroboam led Israel away from following the LORD and caused them to commit a great sin.'),
  ('BSB', '2 Kings', 12, 17, 22, 'The Israelites persisted in all the sins that Jeroboam had committed and did not turn away from them.'),
  ('BSB', '2 Kings', 12, 17, 23, 'Finally, the LORD removed Israel from His presence, as He had declared through all His servants the prophets. So Israel was exiled from their homeland into Assyria, where they are to this day.'),
  ('BSB', '2 Kings', 12, 17, 24, 'Then the king of Assyria brought people from Babylon, Cuthah, Avva, Hamath, and Sepharvaim and settled them in the towns of Samaria to replace the Israelites. They took possession of Samaria and lived in its towns.'),
  ('BSB', '2 Kings', 12, 17, 25, 'Now when the settlers first lived there, they did not worship the LORD, so He sent lions among them, which killed some of them.'),
  ('BSB', '2 Kings', 12, 17, 26, 'So they spoke to the king of Assyria, saying, “The peoples that you have removed and placed in the cities of Samaria do not know the requirements of the God of the land. Because of this, He has sent lions among them, which are indeed killing them off.”'),
  ('BSB', '2 Kings', 12, 17, 27, 'Then the king of Assyria commanded: “Send back one of the priests you carried off from Samaria, and have him go back to live there and teach the requirements of the God of the land.”'),
  ('BSB', '2 Kings', 12, 17, 28, 'Thus one of the priests they had carried away came and lived in Bethel, and he began to teach them how they should worship the LORD.'),
  ('BSB', '2 Kings', 12, 17, 29, 'Nevertheless, the people of each nation continued to make their own gods in the cities where they had settled, and they set them up in the shrines that the people of Samaria had made on the high places.'),
  ('BSB', '2 Kings', 12, 17, 30, 'The men of Babylon made Succoth-benoth, the men of Cuth made Nergal, the men of Hamath made Ashima,'),
  ('BSB', '2 Kings', 12, 17, 31, 'the Avvites made Nibhaz and Tartak, and the Sepharvites burned their children in the fire to Adrammelech and Anammelech the gods of Sepharvaim.'),
  ('BSB', '2 Kings', 12, 17, 32, 'So the new residents worshiped the LORD, but they also appointed for themselves priests of all sorts to serve in the shrines of the high places.'),
  ('BSB', '2 Kings', 12, 17, 33, 'They worshiped the LORD, but they also served their own gods according to the customs of the nations from which they had been carried away.'),
  ('BSB', '2 Kings', 12, 17, 34, 'To this day they are still practicing their former customs. None of them worship the LORD or observe the statutes, ordinances, laws, and commandments that the LORD gave the descendants of Jacob, whom He named Israel.'),
  ('BSB', '2 Kings', 12, 17, 35, 'For the LORD had made a covenant with the Israelites and commanded them, “Do not worship other gods or bow down to them; do not serve them or sacrifice to them.'),
  ('BSB', '2 Kings', 12, 17, 36, 'Instead, worship the LORD, who brought you out of the land of Egypt with great power and an outstretched arm. You are to bow down to Him and offer sacrifices to Him.'),
  ('BSB', '2 Kings', 12, 17, 37, 'And you must always be careful to observe the statutes, ordinances, laws, and commandments He wrote for you. Do not worship other gods.'),
  ('BSB', '2 Kings', 12, 17, 38, 'Do not forget the covenant I have made with you. Do not worship other gods,'),
  ('BSB', '2 Kings', 12, 17, 39, 'but worship the LORD your God, and He will deliver you from the hands of all your enemies.”'),
  ('BSB', '2 Kings', 12, 17, 40, 'But they would not listen, and they persisted in their former customs.'),
  ('BSB', '2 Kings', 12, 17, 41, 'So these nations worshiped the LORD but also served their idols, and to this day their children and grandchildren continue to do as their fathers did.'),
  ('BSB', '2 Kings', 12, 18, 1, 'In the third year of the reign of Hoshea son of Elah over Israel, Hezekiah son of Ahaz became king of Judah.'),
  ('BSB', '2 Kings', 12, 18, 2, 'He was twenty-five years old when he became king, and he reigned in Jerusalem twenty-nine years. His mother’s name was Abi, the daughter of Zechariah.'),
  ('BSB', '2 Kings', 12, 18, 3, 'And he did what was right in the eyes of the LORD, just as his father David had done.'),
  ('BSB', '2 Kings', 12, 18, 4, 'He removed the high places, shattered the sacred pillars, and cut down the Asherah poles. He also demolished the bronze snake called Nehushtan that Moses had made, for up to that time the Israelites had burned incense to it.'),
  ('BSB', '2 Kings', 12, 18, 5, 'Hezekiah trusted in the LORD, the God of Israel. No king of Judah was like him, either before him or after him.'),
  ('BSB', '2 Kings', 12, 18, 6, 'He remained faithful to the LORD and did not turn from following Him; he kept the commandments that the LORD had given Moses.'),
  ('BSB', '2 Kings', 12, 18, 7, 'And the LORD was with Hezekiah, and he prospered wherever he went. He rebelled against the king of Assyria and refused to serve him.'),
  ('BSB', '2 Kings', 12, 18, 8, 'He defeated the Philistines as far as Gaza and its borders, from watchtower to fortified city.'),
  ('BSB', '2 Kings', 12, 18, 9, 'In the fourth year of Hezekiah’s reign, which was the seventh year of the reign of Hoshea son of Elah over Israel, Shalmaneser king of Assyria marched against Samaria and besieged it.'),
  ('BSB', '2 Kings', 12, 18, 10, 'And at the end of three years, the Assyrians captured it. So Samaria was captured in the sixth year of Hezekiah, which was the ninth year of Hoshea king of Israel.'),
  ('BSB', '2 Kings', 12, 18, 11, 'The king of Assyria exiled the Israelites to Assyria and settled them in Halah, in Gozan by the Habor River, and in the cities of the Medes.'),
  ('BSB', '2 Kings', 12, 18, 12, 'This happened because they did not listen to the voice of the LORD their God, but violated His covenant—all that Moses the servant of the LORD had commanded—and would neither listen nor obey.'),
  ('BSB', '2 Kings', 12, 18, 13, 'In the fourteenth year of Hezekiah’s reign, Sennacherib king of Assyria attacked and captured all the fortified cities of Judah.'),
  ('BSB', '2 Kings', 12, 18, 14, 'So Hezekiah king of Judah sent word to the king of Assyria at Lachish, saying, “I have done wrong; withdraw from me, and I will pay whatever you demand from me.” And the king of Assyria exacted from Hezekiah king of Judah three hundred talents of silver and thirty talents of gold.'),
  ('BSB', '2 Kings', 12, 18, 15, 'Hezekiah gave him all the silver that was found in the house of the LORD and in the treasuries of the royal palace.'),
  ('BSB', '2 Kings', 12, 18, 16, 'At that time Hezekiah stripped the gold with which he had plated the doors and doorposts of the temple of the LORD, and he gave it to the king of Assyria.'),
  ('BSB', '2 Kings', 12, 18, 17, 'Nevertheless, the king of Assyria sent the Tartan, the Rabsaris, and the Rabshakeh, along with a great army, from Lachish to King Hezekiah at Jerusalem. They advanced up to Jerusalem and stationed themselves by the aqueduct of the upper pool, on the road to the Launderer’s Field.'),
  ('BSB', '2 Kings', 12, 18, 18, 'Then they called for the king; and Eliakim son of Hilkiah the palace administrator, Shebnah the scribe, and Joah son of Asaph the recorder, went out to them.'),
  ('BSB', '2 Kings', 12, 18, 19, 'The Rabshakeh said to them, “Tell Hezekiah that this is what the great king, the king of Assyria, says: What is the basis of this confidence of yours?'),
  ('BSB', '2 Kings', 12, 18, 20, 'You claim to have a strategy and strength for war, but these are empty words. In whom are you now trusting, that you have rebelled against me?'),
  ('BSB', '2 Kings', 12, 18, 21, 'Look now, you are trusting in Egypt, that splintered reed of a staff that will pierce the hand of anyone who leans on it. Such is Pharaoh king of Egypt to all who trust in him.'),
  ('BSB', '2 Kings', 12, 18, 22, 'But if you say to me, ‘We trust in the LORD our God,’ is He not the One whose high places and altars Hezekiah has removed, saying to Judah and Jerusalem: ‘You must worship before this altar in Jerusalem’?'),
  ('BSB', '2 Kings', 12, 18, 23, 'Now, therefore, make a bargain with my master, the king of Assyria. I will give you two thousand horses—if you can put riders on them!'),
  ('BSB', '2 Kings', 12, 18, 24, 'For how can you repel a single officer among the least of my master’s servants when you depend on Egypt for chariots and horsemen?'),
  ('BSB', '2 Kings', 12, 18, 25, 'So now, was it apart from the LORD that I have come up against this place to destroy it? The LORD Himself said to me, ‘Go up against this land and destroy it.’”'),
  ('BSB', '2 Kings', 12, 18, 26, 'Then Eliakim son of Hilkiah, along with Shebnah and Joah, said to the Rabshakeh, “Please speak to your servants in Aramaic, since we understand it. Do not speak with us in Hebrew in the hearing of the people on the wall.”'),
  ('BSB', '2 Kings', 12, 18, 27, 'But the Rabshakeh replied, “Has my master sent me to speak these words only to you and your master, and not to the men sitting on the wall, who are destined with you to eat their own dung and drink their own urine?”'),
  ('BSB', '2 Kings', 12, 18, 28, 'Then the Rabshakeh stood and called out loudly in Hebrew: “Hear the word of the great king, the king of Assyria!'),
  ('BSB', '2 Kings', 12, 18, 29, 'This is what the king says: Do not let Hezekiah deceive you; he cannot deliver you from my hand.'),
  ('BSB', '2 Kings', 12, 18, 30, 'Do not let Hezekiah persuade you to trust in the LORD when he says, ‘The LORD will surely deliver us; this city will not be given into the hand of the king of Assyria.’'),
  ('BSB', '2 Kings', 12, 18, 31, 'Do not listen to Hezekiah, for this is what the king of Assyria says: Make peace with me and come out to me. Then every one of you will eat from his own vine and his own fig tree, and drink water from his own cistern,'),
  ('BSB', '2 Kings', 12, 18, 32, 'until I come and take you away to a land like your own—a land of grain and new wine, a land of bread and vineyards, a land of olive trees and honey—so that you may live and not die. But do not listen to Hezekiah, for he misleads you when he says, ‘The LORD will deliver us.’'),
  ('BSB', '2 Kings', 12, 18, 33, 'Has the god of any nation ever delivered his land from the hand of the king of Assyria?'),
  ('BSB', '2 Kings', 12, 18, 34, 'Where are the gods of Hamath and Arpad? Where are the gods of Sepharvaim, Hena, and Ivvah? Have they delivered Samaria from my hand?'),
  ('BSB', '2 Kings', 12, 18, 35, 'Who among all the gods of these lands has delivered his land from my hand? How then can the LORD deliver Jerusalem from my hand?”'),
  ('BSB', '2 Kings', 12, 18, 36, 'But the people remained silent and did not answer a word, for Hezekiah had commanded, “Do not answer him.”'),
  ('BSB', '2 Kings', 12, 18, 37, 'Then Hilkiah’s son Eliakim the palace administrator, Shebna the scribe, and Asaph’s son Joah the recorder came to Hezekiah with their clothes torn, and they relayed to him the words of the Rabshakeh.'),
  ('BSB', '2 Kings', 12, 19, 1, 'On hearing this report, King Hezekiah tore his clothes, put on sackcloth, and entered the house of the LORD.'),
  ('BSB', '2 Kings', 12, 19, 2, 'And he sent Eliakim the palace administrator, Shebna the scribe, and the leading priests, all wearing sackcloth, to the prophet Isaiah son of Amoz'),
  ('BSB', '2 Kings', 12, 19, 3, 'to tell him, “This is what Hezekiah says: Today is a day of distress, rebuke, and disgrace; for children have come to the point of birth, but there is no strength to deliver them.'),
  ('BSB', '2 Kings', 12, 19, 4, 'Perhaps the LORD your God will hear all the words of the Rabshakeh, whom his master the king of Assyria has sent to defy the living God, and He will rebuke him for the words that the LORD your God has heard. Therefore lift up a prayer for the remnant that still survives.”'),
  ('BSB', '2 Kings', 12, 19, 5, 'So the servants of King Hezekiah went to Isaiah,'),
  ('BSB', '2 Kings', 12, 19, 6, 'who replied, “Tell your master that this is what the LORD says: ‘Do not be afraid of the words you have heard, with which the servants of the king of Assyria have blasphemed Me.'),
  ('BSB', '2 Kings', 12, 19, 7, 'Behold, I will put a spirit in him so that he will hear a rumor and return to his own land, where I will cause him to fall by the sword.’”'),
  ('BSB', '2 Kings', 12, 19, 8, 'When the Rabshakeh heard that the king of Assyria had left Lachish, he withdrew and found the king fighting against Libnah.'),
  ('BSB', '2 Kings', 12, 19, 9, 'Now Sennacherib had been warned about Tirhakah king of Cush: “Look, he has set out to fight against you.” So Sennacherib again sent messengers to Hezekiah, saying,'),
  ('BSB', '2 Kings', 12, 19, 10, '“Give this message to Hezekiah king of Judah: ‘Do not let your God, in whom you trust, deceive you by saying that Jerusalem will not be delivered into the hand of the king of Assyria.'),
  ('BSB', '2 Kings', 12, 19, 11, 'Surely you have heard what the kings of Assyria have done to all the other countries, devoting them to destruction. Will you then be spared?'),
  ('BSB', '2 Kings', 12, 19, 12, 'Did the gods of the nations destroyed by my fathers rescue those nations—the gods of Gozan, Haran, and Rezeph, and of the people of Eden in Telassar?'),
  ('BSB', '2 Kings', 12, 19, 13, 'Where are the kings of Hamath, Arpad, Sepharvaim, Hena, and Ivvah?’”'),
  ('BSB', '2 Kings', 12, 19, 14, 'So Hezekiah received the letter from the messengers, read it, and went up to the house of the LORD and spread it out before the LORD.'),
  ('BSB', '2 Kings', 12, 19, 15, 'And Hezekiah prayed before the LORD: “O LORD, God of Israel, enthroned between the cherubim, You alone are God over all the kingdoms of the earth. You made the heavens and the earth.'),
  ('BSB', '2 Kings', 12, 19, 16, 'Incline Your ear, O LORD, and hear; open Your eyes, O LORD, and see. Listen to the words that Sennacherib has sent to defy the living God.'),
  ('BSB', '2 Kings', 12, 19, 17, 'Truly, O LORD, the kings of Assyria have laid waste these nations and their lands.'),
  ('BSB', '2 Kings', 12, 19, 18, 'They have cast their gods into the fire and destroyed them, for they were not gods, but only wood and stone—the work of human hands.'),
  ('BSB', '2 Kings', 12, 19, 19, 'And now, O LORD our God, please save us from his hand, so that all the kingdoms of the earth may know that You alone, O LORD, are God.”'),
  ('BSB', '2 Kings', 12, 19, 20, 'Then Isaiah son of Amoz sent a message to Hezekiah: “This is what the LORD, the God of Israel, says: I have heard your prayer concerning Sennacherib king of Assyria.'),
  ('BSB', '2 Kings', 12, 19, 21, 'This is the word that the LORD has spoken against him: ‘The Virgin Daughter of Zion despises you and mocks you; the Daughter of Jerusalem shakes her head behind you.'),
  ('BSB', '2 Kings', 12, 19, 22, 'Whom have you taunted and blasphemed? Against whom have you raised your voice and lifted your eyes in pride? Against the Holy One of Israel!'),
  ('BSB', '2 Kings', 12, 19, 23, 'Through your servants you have taunted the Lord, and you have said: “With my many chariots I have ascended to the heights of the mountains, to the remote peaks of Lebanon. I have cut down its tallest cedars, the finest of its cypresses. I have reached its farthest outposts, the densest of its forests.'),
  ('BSB', '2 Kings', 12, 19, 24, 'I have dug wells and drunk foreign waters. With the soles of my feet I have dried up all the streams of Egypt.”'),
  ('BSB', '2 Kings', 12, 19, 25, 'Have you not heard? Long ago I ordained it; in days of old I planned it. Now I have brought it to pass, that you should crush fortified cities into piles of rubble.'),
  ('BSB', '2 Kings', 12, 19, 26, 'Therefore their inhabitants, devoid of power, are dismayed and ashamed. They are like plants in the field, tender green shoots, grass on the rooftops, scorched before it is grown.'),
  ('BSB', '2 Kings', 12, 19, 27, 'But I know your sitting down, your going out and coming in, and your raging against Me.'),
  ('BSB', '2 Kings', 12, 19, 28, 'Because your rage and arrogance against Me have reached My ears, I will put My hook in your nose and My bit in your mouth; I will send you back the way you came.’'),
  ('BSB', '2 Kings', 12, 19, 29, 'And this will be a sign to you, O Hezekiah: This year you will eat what grows on its own, and in the second year what springs from the same. But in the third year you will sow and reap; you will plant vineyards and eat their fruit.'),
  ('BSB', '2 Kings', 12, 19, 30, 'And the surviving remnant of the house of Judah will again take root below and bear fruit above.'),
  ('BSB', '2 Kings', 12, 19, 31, 'For a remnant will go forth from Jerusalem, and survivors from Mount Zion. The zeal of the LORD of Hosts will accomplish this.'),
  ('BSB', '2 Kings', 12, 19, 32, 'So this is what the LORD says about the king of Assyria: ‘He will not enter this city or shoot an arrow into it. He will not come before it with a shield or build up a siege ramp against it.'),
  ('BSB', '2 Kings', 12, 19, 33, 'He will go back the way he came, and he will not enter this city,’ declares the LORD.'),
  ('BSB', '2 Kings', 12, 19, 34, '‘I will defend this city and save it for My own sake and for the sake of My servant David.’”'),
  ('BSB', '2 Kings', 12, 19, 35, 'And that very night the angel of the LORD went out and struck down 185,000 men in the camp of the Assyrians. When the people got up the next morning, there were all the dead bodies!'),
  ('BSB', '2 Kings', 12, 19, 36, 'So Sennacherib king of Assyria broke camp and withdrew. He returned to Nineveh and stayed there.'),
  ('BSB', '2 Kings', 12, 19, 37, 'One day, while he was worshiping in the temple of his god Nisroch, his sons Adrammelech and Sharezer put him to the sword and escaped to the land of Ararat. And his son Esar-haddon reigned in his place.'),
  ('BSB', '2 Kings', 12, 20, 1, 'In those days Hezekiah became mortally ill. The prophet Isaiah son of Amoz came to him and said, “This is what the LORD says: ‘Put your house in order, for you are about to die; you will not recover.’”'),
  ('BSB', '2 Kings', 12, 20, 2, 'Then Hezekiah turned his face to the wall and prayed to the LORD, saying,'),
  ('BSB', '2 Kings', 12, 20, 3, '“Please, O LORD, remember how I have walked before You faithfully and with wholehearted devotion; I have done what was good in Your sight.” And Hezekiah wept bitterly.'),
  ('BSB', '2 Kings', 12, 20, 4, 'Before Isaiah had left the middle courtyard, the word of the LORD came to him, saying,'),
  ('BSB', '2 Kings', 12, 20, 5, '“Go back and tell Hezekiah the leader of My people that this is what the LORD, the God of your father David, says: ‘I have heard your prayer; I have seen your tears. I will surely heal you. On the third day from now you will go up to the house of the LORD.'),
  ('BSB', '2 Kings', 12, 20, 6, 'I will add fifteen years to your life. And I will deliver you and this city from the hand of the king of Assyria. I will defend this city for My sake and for the sake of My servant David.’”'),
  ('BSB', '2 Kings', 12, 20, 7, 'Then Isaiah said, “Prepare a poultice of figs.” So they brought it and applied it to the boil, and Hezekiah recovered.'),
  ('BSB', '2 Kings', 12, 20, 8, 'Now Hezekiah had asked Isaiah, “What will be the sign that the LORD will heal me and that I will go up to the house of the LORD on the third day?”'),
  ('BSB', '2 Kings', 12, 20, 9, 'And Isaiah had replied, “This will be a sign to you from the LORD that He will do what He has promised: Would you like the shadow to go forward ten steps, or back ten steps?”'),
  ('BSB', '2 Kings', 12, 20, 10, '“It is easy for the shadow to lengthen ten steps,” answered Hezekiah, “but not for it to go back ten steps.”'),
  ('BSB', '2 Kings', 12, 20, 11, 'So Isaiah the prophet called out to the LORD, and He brought the shadow back the ten steps it had descended on the stairway of Ahaz.'),
  ('BSB', '2 Kings', 12, 20, 12, 'At that time Merodach-baladan son of Baladan king of Babylon sent letters and a gift to Hezekiah, for he had heard about Hezekiah’s illness.'),
  ('BSB', '2 Kings', 12, 20, 13, 'And Hezekiah received the envoys and showed them all that was in his treasure house—the silver, the gold, the spices, and the precious oil, as well as his armory—all that was found in his storehouses. There was nothing in his palace or in all his dominion that Hezekiah did not show them.'),
  ('BSB', '2 Kings', 12, 20, 14, 'Then the prophet Isaiah went to King Hezekiah and asked, “Where did those men come from, and what did they say to you?” “They came from a distant land,” Hezekiah replied, “from Babylon.”'),
  ('BSB', '2 Kings', 12, 20, 15, '“What have they seen in your palace?” Isaiah asked. “They have seen everything in my palace,” answered Hezekiah. “There is nothing among my treasures that I did not show them.”'),
  ('BSB', '2 Kings', 12, 20, 16, 'Then Isaiah said to Hezekiah, “Hear the word of the LORD:'),
  ('BSB', '2 Kings', 12, 20, 17, 'The time will surely come when everything in your palace and all that your fathers have stored up until this day will be carried off to Babylon. Nothing will be left, says the LORD.'),
  ('BSB', '2 Kings', 12, 20, 18, 'And some of your descendants, your own flesh and blood, will be taken away to be eunuchs in the palace of the king of Babylon.”'),
  ('BSB', '2 Kings', 12, 20, 19, 'But Hezekiah said to Isaiah, “The word of the LORD that you have spoken is good.” For he thought, “Will there not at least be peace and security in my lifetime?”'),
  ('BSB', '2 Kings', 12, 20, 20, 'As for the rest of the acts of Hezekiah, along with all his might and how he constructed the pool and the tunnel to bring water into the city, are they not written in the Book of the Chronicles of the Kings of Judah?'),
  ('BSB', '2 Kings', 12, 20, 21, 'And Hezekiah rested with his fathers, and his son Manasseh reigned in his place.'),
  ('BSB', '2 Kings', 12, 21, 1, 'Manasseh was twelve years old when he became king, and he reigned in Jerusalem fifty-five years. His mother’s name was Hephzibah.'),
  ('BSB', '2 Kings', 12, 21, 2, 'And he did evil in the sight of the LORD by following the abominations of the nations that the LORD had driven out before the Israelites.'),
  ('BSB', '2 Kings', 12, 21, 3, 'For he rebuilt the high places that his father Hezekiah had destroyed, and he raised up altars for Baal. He made an Asherah pole, as King Ahab of Israel had done, and he worshiped and served all the host of heaven.'),
  ('BSB', '2 Kings', 12, 21, 4, 'Manasseh also built altars in the house of the LORD, of which the LORD had said, “In Jerusalem I will put My Name.”'),
  ('BSB', '2 Kings', 12, 21, 5, 'In both courtyards of the house of the LORD, he built altars to all the host of heaven.'),
  ('BSB', '2 Kings', 12, 21, 6, 'He sacrificed his own son in the fire, practiced sorcery and divination, and consulted mediums and spiritists. He did great evil in the sight of the LORD, provoking Him to anger.'),
  ('BSB', '2 Kings', 12, 21, 7, 'Manasseh even took the carved Asherah pole he had made and set it up in the temple, of which the LORD had said to David and his son Solomon, “In this temple and in Jerusalem, which I have chosen out of all the tribes of Israel, I will establish My Name forever.'),
  ('BSB', '2 Kings', 12, 21, 8, 'I will never again cause the feet of the Israelites to wander from the land that I gave to their fathers, if only they are careful to do all I have commanded them—the whole Law that My servant Moses commanded them.”'),
  ('BSB', '2 Kings', 12, 21, 9, 'But the people did not listen and Manasseh led them astray, so that they did greater evil than the nations that the LORD had destroyed before the Israelites.'),
  ('BSB', '2 Kings', 12, 21, 10, 'And the LORD spoke through His servants the prophets, saying,'),
  ('BSB', '2 Kings', 12, 21, 11, '“Since Manasseh king of Judah has committed all these abominations, acting more wickedly than the Amorites who preceded him, and with his idols has caused Judah to sin,'),
  ('BSB', '2 Kings', 12, 21, 12, 'this is what the LORD, the God of Israel, says: ‘Behold, I am bringing such calamity upon Jerusalem and Judah that the news will reverberate in the ears of all who hear it.'),
  ('BSB', '2 Kings', 12, 21, 13, 'I will stretch out over Jerusalem the measuring line used against Samaria and the plumb line used against the house of Ahab, and I will wipe out Jerusalem as one wipes out a bowl—wiping it and turning it upside down.'),
  ('BSB', '2 Kings', 12, 21, 14, 'So I will forsake the remnant of My inheritance and deliver them into the hands of their enemies. And they will become plunder and spoil to all their enemies,'),
  ('BSB', '2 Kings', 12, 21, 15, 'because they have done evil in My sight and have provoked Me to anger from the day their fathers came out of Egypt until this day.’”'),
  ('BSB', '2 Kings', 12, 21, 16, 'Moreover, Manasseh shed so much innocent blood that he filled Jerusalem from end to end, in addition to the sin that he had caused Judah to commit, doing evil in the sight of the LORD.'),
  ('BSB', '2 Kings', 12, 21, 17, 'As for the rest of the acts of Manasseh, along with all his accomplishments and the sin that he committed, are they not written in the Book of the Chronicles of the Kings of Judah?'),
  ('BSB', '2 Kings', 12, 21, 18, 'And Manasseh rested with his fathers and was buried in his palace garden, the garden of Uzza. And his son Amon reigned in his place.'),
  ('BSB', '2 Kings', 12, 21, 19, 'Amon was twenty-two years old when he became king, and he reigned in Jerusalem two years. His mother’s name was Meshullemeth daughter of Haruz; she was from Jotbah.'),
  ('BSB', '2 Kings', 12, 21, 20, 'And he did evil in the sight of the LORD, as his father Manasseh had done.'),
  ('BSB', '2 Kings', 12, 21, 21, 'He walked in all the ways of his father, and he served and worshiped the idols his father had served.'),
  ('BSB', '2 Kings', 12, 21, 22, 'He abandoned the LORD, the God of his fathers, and did not walk in the way of the LORD.'),
  ('BSB', '2 Kings', 12, 21, 23, 'Then the servants of Amon conspired against him and killed the king in his palace.'),
  ('BSB', '2 Kings', 12, 21, 24, 'But the people of the land killed all those who had conspired against King Amon, and they made his son Josiah king in his place.'),
  ('BSB', '2 Kings', 12, 21, 25, 'As for the rest of the acts of Amon, along with his accomplishments, are they not written in the Book of the Chronicles of the Kings of Judah?'),
  ('BSB', '2 Kings', 12, 21, 26, 'And he was buried in his tomb in the garden of Uzza, and his son Josiah reigned in his place.'),
  ('BSB', '2 Kings', 12, 22, 1, 'Josiah was eight years old when he became king, and he reigned in Jerusalem thirty-one years. His mother’s name was Jedidah daughter of Adaiah; she was from Bozkath.'),
  ('BSB', '2 Kings', 12, 22, 2, 'And he did what was right in the eyes of the LORD and walked in all the ways of his father David; he did not turn aside to the right or to the left.'),
  ('BSB', '2 Kings', 12, 22, 3, 'Now in the eighteenth year of his reign, King Josiah sent the scribe, Shaphan son of Azaliah, the son of Meshullam, to the house of the LORD, saying,'),
  ('BSB', '2 Kings', 12, 22, 4, '“Go up to Hilkiah the high priest and have him count the money that has been brought into the house of the LORD, which the doorkeepers have collected from the people.'),
  ('BSB', '2 Kings', 12, 22, 5, 'And let them deliver it into the hands of the supervisors of those doing the work on the house of the LORD, who in turn are to give it to the workmen repairing the damages to the house of the LORD—'),
  ('BSB', '2 Kings', 12, 22, 6, 'to the carpenters, builders, and masons—to buy timber and dressed stone to repair the temple.'),
  ('BSB', '2 Kings', 12, 22, 7, 'But they need not account for the money put into their hands, since they work with integrity.”'),
  ('BSB', '2 Kings', 12, 22, 8, 'Then Hilkiah the high priest said to Shaphan the scribe, “I have found the Book of the Law in the house of the LORD!” And he gave it to Shaphan, who read it.'),
  ('BSB', '2 Kings', 12, 22, 9, 'And Shaphan the scribe went to the king and reported, “Your servants have paid out the money that was found in the temple and have put it into the hands of the workers and supervisors of the house of the LORD.”'),
  ('BSB', '2 Kings', 12, 22, 10, 'Moreover, Shaphan the scribe told the king, “Hilkiah the priest has given me a book.” And Shaphan read it in the presence of the king.'),
  ('BSB', '2 Kings', 12, 22, 11, 'When the king heard the words of the Book of the Law, he tore his clothes'),
  ('BSB', '2 Kings', 12, 22, 12, 'and commanded Hilkiah the priest, Ahikam son of Shaphan, Achbor son of Micaiah, Shaphan the scribe, and Asaiah the servant of the king:'),
  ('BSB', '2 Kings', 12, 22, 13, '“Go and inquire of the LORD for me, for the people, and for all Judah concerning the words in this book that has been found. For great is the wrath of the LORD that burns against us because our fathers have not obeyed the words of this book by doing all that is written about us.”'),
  ('BSB', '2 Kings', 12, 22, 14, 'So Hilkiah the priest, Ahikam, Achbor, Shaphan, and Asaiah went and spoke to Huldah the prophetess, the wife of Shallum son of Tikvah, the son of Harhas, the keeper of the wardrobe. She lived in Jerusalem, in the Second District.'),
  ('BSB', '2 Kings', 12, 22, 15, 'And Huldah said to them, “This is what the LORD, the God of Israel, says: ‘Tell the man who sent you'),
  ('BSB', '2 Kings', 12, 22, 16, 'that this is what the LORD says: I am about to bring calamity on this place and on its people, according to all the words of the book that the king of Judah has read,'),
  ('BSB', '2 Kings', 12, 22, 17, 'because they have forsaken Me and burned incense to other gods, that they might provoke Me to anger with all the works of their hands. My wrath will be kindled against this place and will not be quenched.’'),
  ('BSB', '2 Kings', 12, 22, 18, 'But as for the king of Judah, who sent you to inquire of the LORD, tell him that this is what the LORD, the God of Israel, says: ‘As for the words that you heard,'),
  ('BSB', '2 Kings', 12, 22, 19, 'because your heart was tender and you humbled yourself before the LORD when you heard what I spoke against this place and against its people, that they would become a desolation and a curse, and because you have torn your clothes and wept before Me, I have heard you,’ declares the LORD.'),
  ('BSB', '2 Kings', 12, 22, 20, '‘Therefore I will indeed gather you to your fathers, and you will be gathered to your grave in peace. Your eyes will not see all the calamity that I will bring on this place.’” So they brought her answer back to the king.'),
  ('BSB', '2 Kings', 12, 23, 1, 'Then the king summoned all the elders of Judah and Jerusalem.'),
  ('BSB', '2 Kings', 12, 23, 2, 'And he went up to the house of the LORD with all the people of Judah and Jerusalem, as well as the priests and the prophets—all the people small and great—and in their hearing he read all the words of the Book of the Covenant that had been found in the house of the LORD.'),
  ('BSB', '2 Kings', 12, 23, 3, 'So the king stood by the pillar and made a covenant before the LORD to follow the LORD and to keep His commandments, decrees, and statutes with all his heart and all his soul, and to carry out the words of this covenant that were written in this book. And all the people entered into the covenant.'),
  ('BSB', '2 Kings', 12, 23, 4, 'Then the king commanded Hilkiah the high priest, the priests second in rank, and the doorkeepers to remove from the temple of the LORD all the articles made for Baal, Asherah, and all the host of heaven. And he burned them outside Jerusalem in the fields of Kidron and carried their ashes to Bethel.'),
  ('BSB', '2 Kings', 12, 23, 5, 'Josiah also did away with the idolatrous priests ordained by the kings of Judah to burn incense on the high places of the cities of Judah and in the places all around Jerusalem—those who had burned incense to Baal, to the sun and moon, to the constellations, and to all the host of heaven.'),
  ('BSB', '2 Kings', 12, 23, 6, 'He brought the Asherah pole from the house of the LORD to the Kidron Valley outside Jerusalem, and there he burned it, ground it to powder, and threw its dust on the graves of the common people.'),
  ('BSB', '2 Kings', 12, 23, 7, 'He also tore down the quarters of the male shrine prostitutes that were in the house of the LORD, where the women had woven tapestries for Asherah.'),
  ('BSB', '2 Kings', 12, 23, 8, 'Then Josiah brought all the priests from the cities of Judah and desecrated the high places, from Geba to Beersheba, where the priests had burned incense. He tore down the high places of the gates at the entrance of the gate of Joshua the governor of the city, which was to the left of the city gate.'),
  ('BSB', '2 Kings', 12, 23, 9, 'Although the priests of the high places did not come up to the altar of the LORD in Jerusalem, they ate unleavened bread with their fellow priests.'),
  ('BSB', '2 Kings', 12, 23, 10, 'He also desecrated Topheth in the Valley of Ben-hinnom so that no one could sacrifice his son or daughter in the fire to Molech.'),
  ('BSB', '2 Kings', 12, 23, 11, 'And he removed from the entrance to the house of the LORD the horses that the kings of Judah had dedicated to the sun. They were in the court near the chamber of an official named Nathan-melech. And Josiah burned up the chariots of the sun.'),
  ('BSB', '2 Kings', 12, 23, 12, 'He pulled down the altars that the kings of Judah had set up on the roof near the upper chamber of Ahaz, and the altars that Manasseh had set up in the two courtyards of the house of the LORD. The king pulverized them there and threw their dust into the Kidron Valley.'),
  ('BSB', '2 Kings', 12, 23, 13, 'The king also desecrated the high places east of Jerusalem, to the south of the Mount of Corruption, which King Solomon of Israel had built for Ashtoreth the abomination of the Sidonians, for Chemosh the abomination of the Moabites, and for Milcom the abomination of the Ammonites.'),
  ('BSB', '2 Kings', 12, 23, 14, 'He smashed the sacred pillars to pieces, cut down the Asherah poles, and covered the sites with human bones.'),
  ('BSB', '2 Kings', 12, 23, 15, 'He even pulled down the altar at Bethel, the high place set up by Jeroboam son of Nebat, who had caused Israel to sin. Then he burned the high place, ground it to powder, and burned the Asherah pole.'),
  ('BSB', '2 Kings', 12, 23, 16, 'And as Josiah turned, he saw the tombs there on the hillside, and he sent someone to take the bones out of the tombs, and he burned them on the altar to defile it, according to the word of the LORD proclaimed by the man of God who had foretold these things.'),
  ('BSB', '2 Kings', 12, 23, 17, 'Then the king asked, “What is this monument I see?” And the men of the city replied, “It is the tomb of the man of God who came from Judah and pronounced these things that you have done to the altar of Bethel.”'),
  ('BSB', '2 Kings', 12, 23, 18, '“Let him rest,” said Josiah. “Do not let anyone disturb his bones.” So they left his bones undisturbed, along with those of the prophet who had come from Samaria.'),
  ('BSB', '2 Kings', 12, 23, 19, 'Just as Josiah had done at Bethel, so also in the cities of Samaria he removed all the shrines of the high places set up by the kings of Israel who had provoked the LORD to anger.'),
  ('BSB', '2 Kings', 12, 23, 20, 'On the altars he slaughtered all the priests of the high places, and he burned human bones on them. Then he returned to Jerusalem.'),
  ('BSB', '2 Kings', 12, 23, 21, 'The king commanded all the people, “Keep the Passover of the LORD your God, as it is written in this Book of the Covenant.”'),
  ('BSB', '2 Kings', 12, 23, 22, 'No such Passover had been observed from the days of the judges who had governed Israel through all the days of the kings of Israel and Judah.'),
  ('BSB', '2 Kings', 12, 23, 23, 'But in the eighteenth year of Josiah’s reign, this Passover was observed to the LORD in Jerusalem.'),
  ('BSB', '2 Kings', 12, 23, 24, 'Furthermore, Josiah removed the mediums and spiritists, the household gods and idols, and all the abominations that were seen in the land of Judah and in Jerusalem. He did this to carry out the words of the law written in the book that Hilkiah the priest had found in the house of the LORD.'),
  ('BSB', '2 Kings', 12, 23, 25, 'Neither before nor after Josiah was there any king like him, who turned to the LORD with all his heart and with all his soul and with all his strength, according to all the Law of Moses.'),
  ('BSB', '2 Kings', 12, 23, 26, 'Nevertheless, the LORD did not turn away from the fury of His burning anger, which was kindled against Judah because of all that Manasseh had done to provoke Him to anger.'),
  ('BSB', '2 Kings', 12, 23, 27, 'For the LORD had said, “I will remove Judah from My sight, just as I removed Israel. I will reject this city Jerusalem, which I chose, and the temple of which I said, ‘My Name shall be there.’”'),
  ('BSB', '2 Kings', 12, 23, 28, 'As for the rest of the acts of Josiah, along with all his accomplishments, are they not written in the Book of the Chronicles of the Kings of Judah?'),
  ('BSB', '2 Kings', 12, 23, 29, 'At the end of Josiah’s reign, Pharaoh Neco king of Egypt marched up to help the king of Assyria at the Euphrates River. King Josiah went out to confront him, but Neco faced him and killed him at Megiddo.'),
  ('BSB', '2 Kings', 12, 23, 30, 'From Megiddo his servants carried his body in a chariot, brought him to Jerusalem, and buried him in his own tomb. Then the people of the land took Jehoahaz son of Josiah, anointed him, and made him king in place of his father.'),
  ('BSB', '2 Kings', 12, 23, 31, 'Jehoahaz was twenty-three years old when he became king, and he reigned in Jerusalem three months. His mother’s name was Hamutal daughter of Jeremiah; she was from Libnah.'),
  ('BSB', '2 Kings', 12, 23, 32, 'And he did evil in the sight of the LORD, just as his fathers had done.'),
  ('BSB', '2 Kings', 12, 23, 33, 'And Pharaoh Neco imprisoned Jehoahaz at Riblah in the land of Hamath so that he could not reign in Jerusalem, and he imposed on Judah a levy of a hundred talents of silver and a talent of gold.'),
  ('BSB', '2 Kings', 12, 23, 34, 'Then Pharaoh Neco made Eliakim son of Josiah king in place of his father Josiah, and he changed Eliakim’s name to Jehoiakim. But Neco took Jehoahaz and carried him off to Egypt, where he died.'),
  ('BSB', '2 Kings', 12, 23, 35, 'So Jehoiakim paid the silver and gold to Pharaoh Neco, but to meet Pharaoh’s demand he taxed the land and exacted the silver and the gold from the people, each according to his wealth.'),
  ('BSB', '2 Kings', 12, 23, 36, 'Jehoiakim was twenty-five years old when he became king, and he reigned in Jerusalem eleven years. His mother’s name was Zebidah daughter of Pedaiah; she was from Rumah.'),
  ('BSB', '2 Kings', 12, 23, 37, 'And he did evil in the sight of the LORD, just as his fathers had done.'),
  ('BSB', '2 Kings', 12, 24, 1, 'During Jehoiakim’s reign, Nebuchadnezzar king of Babylon invaded. So Jehoiakim became his vassal for three years, until he turned and rebelled against Nebuchadnezzar.'),
  ('BSB', '2 Kings', 12, 24, 2, 'And the LORD sent Chaldean, Aramean, Moabite, and Ammonite raiders against Jehoiakim in order to destroy Judah, according to the word that the LORD had spoken through His servants the prophets.'),
  ('BSB', '2 Kings', 12, 24, 3, 'Surely this happened to Judah at the LORD’s command, to remove them from His presence because of the sins of Manasseh and all that he had done,'),
  ('BSB', '2 Kings', 12, 24, 4, 'and also for the innocent blood he had shed. For he had filled Jerusalem with innocent blood, and the LORD was unwilling to forgive.'),
  ('BSB', '2 Kings', 12, 24, 5, 'As for the rest of the acts of Jehoiakim, along with all his accomplishments, are they not written in the Book of the Chronicles of the Kings of Judah?'),
  ('BSB', '2 Kings', 12, 24, 6, 'And Jehoiakim rested with his fathers, and his son Jehoiachin reigned in his place.'),
  ('BSB', '2 Kings', 12, 24, 7, 'Now the king of Egypt did not march out of his land again, because the king of Babylon had taken all his territory, from the Brook of Egypt to the Euphrates River.'),
  ('BSB', '2 Kings', 12, 24, 8, 'Jehoiachin was eighteen years old when he became king, and he reigned in Jerusalem three months. His mother’s name was Nehushta daughter of Elnathan; she was from Jerusalem.'),
  ('BSB', '2 Kings', 12, 24, 9, 'And he did evil in the sight of the LORD, just as his father had done.'),
  ('BSB', '2 Kings', 12, 24, 10, 'At that time the servants of Nebuchadnezzar king of Babylon marched up to Jerusalem, and the city came under siege.'),
  ('BSB', '2 Kings', 12, 24, 11, 'And Nebuchadnezzar king of Babylon came to the city while his servants were besieging it.'),
  ('BSB', '2 Kings', 12, 24, 12, 'Jehoiachin king of Judah, his mother, his servants, his commanders, and his officials all surrendered to the king of Babylon. So in the eighth year of his reign, the king of Babylon took him captive.'),
  ('BSB', '2 Kings', 12, 24, 13, 'As the LORD had declared, Nebuchadnezzar also carried off all the treasures from the house of the LORD and the royal palace, and he cut into pieces all the gold articles that Solomon king of Israel had made in the temple of the LORD.'),
  ('BSB', '2 Kings', 12, 24, 14, 'He carried into exile all Jerusalem—all the commanders and mighty men of valor, all the craftsmen and metalsmiths—ten thousand captives in all. Only the poorest people of the land remained.'),
  ('BSB', '2 Kings', 12, 24, 15, 'Nebuchadnezzar carried away Jehoiachin to Babylon, as well as the king’s mother, his wives, his officials, and the leading men of the land. He took them into exile from Jerusalem to Babylon.'),
  ('BSB', '2 Kings', 12, 24, 16, 'The king of Babylon also brought into exile to Babylon all seven thousand men of valor and a thousand craftsmen and metalsmiths—all strong and fit for battle.'),
  ('BSB', '2 Kings', 12, 24, 17, 'Then the king of Babylon made Mattaniah, Jehoiachin’s uncle, king in his place and changed his name to Zedekiah.'),
  ('BSB', '2 Kings', 12, 24, 18, 'Zedekiah was twenty-one years old when he became king, and he reigned in Jerusalem eleven years. His mother’s name was Hamutal daughter of Jeremiah; she was from Libnah.'),
  ('BSB', '2 Kings', 12, 24, 19, 'And Zedekiah did evil in the sight of the LORD, just as Jehoiakim had done.'),
  ('BSB', '2 Kings', 12, 24, 20, 'For because of the anger of the LORD, all this happened in Jerusalem and Judah, until He finally banished them from His presence. And Zedekiah also rebelled against the king of Babylon.'),
  ('BSB', '2 Kings', 12, 25, 1, 'So in the ninth year of Zedekiah’s reign, on the tenth day of the tenth month, Nebuchadnezzar king of Babylon marched against Jerusalem with his entire army. They encamped outside the city and built a siege wall all around it.'),
  ('BSB', '2 Kings', 12, 25, 2, 'And the city was kept under siege until King Zedekiah’s eleventh year.'),
  ('BSB', '2 Kings', 12, 25, 3, 'By the ninth day of the fourth month, the famine in the city was so severe that the people of the land had no food.'),
  ('BSB', '2 Kings', 12, 25, 4, 'Then the city was breached; and though the Chaldeans had surrounded the city, all the men of war fled by night by way of the gate between the two walls near the king’s garden. They headed toward the Arabah,'),
  ('BSB', '2 Kings', 12, 25, 5, 'but the army of the Chaldeans pursued the king and overtook him in the plains of Jericho, and all his army was separated from him.'),
  ('BSB', '2 Kings', 12, 25, 6, 'The Chaldeans seized the king and brought him up to the king of Babylon at Riblah, where they pronounced judgment on him.'),
  ('BSB', '2 Kings', 12, 25, 7, 'And they slaughtered the sons of Zedekiah before his eyes. Then they put out his eyes, bound him with bronze shackles, and took him to Babylon.'),
  ('BSB', '2 Kings', 12, 25, 8, 'On the seventh day of the fifth month, in the nineteenth year of Nebuchadnezzar’s reign over Babylon, Nebuzaradan captain of the guard, a servant of the king of Babylon, entered Jerusalem.'),
  ('BSB', '2 Kings', 12, 25, 9, 'He burned down the house of the LORD, the royal palace, and all the houses of Jerusalem—every significant building.'),
  ('BSB', '2 Kings', 12, 25, 10, 'And the whole army of the Chaldeans under the captain of the guard broke down the walls around Jerusalem.'),
  ('BSB', '2 Kings', 12, 25, 11, 'Then Nebuzaradan captain of the guard carried into exile the people who remained in the city, along with the deserters who had defected to the king of Babylon and the rest of the population.'),
  ('BSB', '2 Kings', 12, 25, 12, 'But the captain of the guard left behind some of the poorest of the land to tend the vineyards and fields.'),
  ('BSB', '2 Kings', 12, 25, 13, 'Moreover, the Chaldeans broke up the bronze pillars and stands and the bronze Sea in the house of the LORD, and they carried the bronze to Babylon.'),
  ('BSB', '2 Kings', 12, 25, 14, 'They also took away the pots, shovels, wick trimmers, dishes, and all the articles of bronze used in the temple service.'),
  ('BSB', '2 Kings', 12, 25, 15, 'The captain of the guard also took away the censers and sprinkling bowls—anything made of pure gold or fine silver.'),
  ('BSB', '2 Kings', 12, 25, 16, 'As for the two pillars, the Sea, and the movable stands that Solomon had made for the house of the LORD, the weight of the bronze from all these articles was beyond measure.'),
  ('BSB', '2 Kings', 12, 25, 17, 'Each pillar was eighteen cubits tall. The bronze capital atop one pillar was three cubits high, with a network of bronze pomegranates all around. The second pillar, with its network, was similar.'),
  ('BSB', '2 Kings', 12, 25, 18, 'The captain of the guard also took away Seraiah the chief priest, Zephaniah the priest of second rank, and the three doorkeepers.'),
  ('BSB', '2 Kings', 12, 25, 19, 'Of those still in the city, he took a court official who had been appointed over the men of war, as well as five royal advisors. He also took the scribe of the captain of the army, who had enlisted the people of the land, and sixty men who were found in the city.'),
  ('BSB', '2 Kings', 12, 25, 20, 'Nebuzaradan captain of the guard took them and brought them to the king of Babylon at Riblah.'),
  ('BSB', '2 Kings', 12, 25, 21, 'There at Riblah in the land of Hamath, the king of Babylon struck them down and put them to death. So Judah was taken into exile, away from its own land.'),
  ('BSB', '2 Kings', 12, 25, 22, 'Nebuchadnezzar king of Babylon appointed Gedaliah son of Ahikam, the son of Shaphan, over the people he had left behind in the land of Judah.'),
  ('BSB', '2 Kings', 12, 25, 23, 'When all the commanders of the armies and their men heard that the king of Babylon had appointed Gedaliah as governor, they came to Gedaliah at Mizpah—Ishmael son of Nethaniah, Johanan son of Kareah, Seraiah son of Tanhumeth the Netophathite, and Jaazaniah son of the Maacathite, as well as their men.'),
  ('BSB', '2 Kings', 12, 25, 24, 'And Gedaliah took an oath before them and their men, assuring them, “Do not be afraid of the servants of the Chaldeans. Live in the land and serve the king of Babylon, and it will be well with you.”'),
  ('BSB', '2 Kings', 12, 25, 25, 'In the seventh month, however, Ishmael son of Nethaniah, the son of Elishama, who was a member of the royal family, came with ten men and struck down and killed Gedaliah, along with the Judeans and Chaldeans who were with him at Mizpah.'),
  ('BSB', '2 Kings', 12, 25, 26, 'Then all the people small and great, together with the commanders of the army, arose and fled to Egypt for fear of the Chaldeans.'),
  ('BSB', '2 Kings', 12, 25, 27, 'On the twenty-seventh day of the twelfth month of the thirty-seventh year of the exile of Judah’s King Jehoiachin, in the year Evil-merodach became king of Babylon, he released King Jehoiachin of Judah from prison.'),
  ('BSB', '2 Kings', 12, 25, 28, 'And he spoke kindly to Jehoiachin and set his throne above the thrones of the other kings who were with him in Babylon.'),
  ('BSB', '2 Kings', 12, 25, 29, 'So Jehoiachin changed out of his prison clothes, and he dined regularly at the king’s table for the rest of his life.'),
  ('BSB', '2 Kings', 12, 25, 30, 'And the king provided Jehoiachin a daily portion for the rest of his life.'),
  ('BSB', '1 Chronicles', 13, 1, 1, 'Adam, Seth, Enosh,'),
  ('BSB', '1 Chronicles', 13, 1, 2, 'Kenan, Mahalalel, Jared,'),
  ('BSB', '1 Chronicles', 13, 1, 3, 'Enoch, Methuselah, Lamech.'),
  ('BSB', '1 Chronicles', 13, 1, 4, 'The sons of Noah: Shem, Ham, and Japheth.'),
  ('BSB', '1 Chronicles', 13, 1, 5, 'The sons of Japheth: Gomer, Magog, Madai, Javan, Tubal, Meshech, and Tiras.'),
  ('BSB', '1 Chronicles', 13, 1, 6, 'The sons of Gomer: Ashkenaz, Riphath, and Togarmah.'),
  ('BSB', '1 Chronicles', 13, 1, 7, 'And the sons of Javan: Elishah, Tarshish, the Kittites, and the Rodanites.'),
  ('BSB', '1 Chronicles', 13, 1, 8, 'The sons of Ham: Cush, Mizraim, Put, and Canaan.'),
  ('BSB', '1 Chronicles', 13, 1, 9, 'The sons of Cush: Seba, Havilah, Sabta, Raamah, and Sabteca. The sons of Raamah: Sheba and Dedan.'),
  ('BSB', '1 Chronicles', 13, 1, 10, 'Cush was the father of Nimrod, who began to be a mighty one on the earth.'),
  ('BSB', '1 Chronicles', 13, 1, 11, 'Mizraim was the father of the Ludites, the Anamites, the Lehabites, the Naphtuhites,'),
  ('BSB', '1 Chronicles', 13, 1, 12, 'the Pathrusites, the Casluhites (from whom the Philistines came), and the Caphtorites.'),
  ('BSB', '1 Chronicles', 13, 1, 13, 'And Canaan was the father of Sidon his firstborn, and of the Hittites,'),
  ('BSB', '1 Chronicles', 13, 1, 14, 'the Jebusites, the Amorites, the Girgashites,'),
  ('BSB', '1 Chronicles', 13, 1, 15, 'the Hivites, the Arkites, the Sinites,'),
  ('BSB', '1 Chronicles', 13, 1, 16, 'the Arvadites, the Zemarites, and the Hamathites.'),
  ('BSB', '1 Chronicles', 13, 1, 17, 'The sons of Shem: Elam, Asshur, Arphaxad, Lud, and Aram. The sons of Aram: Uz, Hul, Gether, and Meshech.'),
  ('BSB', '1 Chronicles', 13, 1, 18, 'Arphaxad was the father of Shelah, and Shelah was the father of Eber.'),
  ('BSB', '1 Chronicles', 13, 1, 19, 'Two sons were born to Eber: One was named Peleg, because in his days the earth was divided, and his brother was named Joktan.'),
  ('BSB', '1 Chronicles', 13, 1, 20, 'And Joktan was the father of Almodad, Sheleph, Hazarmaveth, Jerah,'),
  ('BSB', '1 Chronicles', 13, 1, 21, 'Hadoram, Uzal, Diklah,'),
  ('BSB', '1 Chronicles', 13, 1, 22, 'Obal, Abimael, Sheba,'),
  ('BSB', '1 Chronicles', 13, 1, 23, 'Ophir, Havilah, and Jobab. All these were sons of Joktan.'),
  ('BSB', '1 Chronicles', 13, 1, 24, 'So from Shem came Arphaxad, Shelah,'),
  ('BSB', '1 Chronicles', 13, 1, 25, 'Eber, Peleg, Reu,'),
  ('BSB', '1 Chronicles', 13, 1, 26, 'Serug, Nahor, Terah,'),
  ('BSB', '1 Chronicles', 13, 1, 27, 'and Abram (that is, Abraham).'),
  ('BSB', '1 Chronicles', 13, 1, 28, 'The sons of Abraham were Isaac and Ishmael.'),
  ('BSB', '1 Chronicles', 13, 1, 29, 'These are their genealogies:'),
  ('BSB', '1 Chronicles', 13, 1, 30, 'Nebaioth the firstborn of Ishmael, then Kedar, Adbeel, Mibsam, Mishma, Dumah, Massa, Hadad, Tema,'),
  ('BSB', '1 Chronicles', 13, 1, 31, 'Jetur, Naphish, and Kedemah. These were the sons of Ishmael.'),
  ('BSB', '1 Chronicles', 13, 1, 32, 'The sons born to Keturah, Abraham’s concubine: Zimran, Jokshan, Medan, Midian, Ishbak, and Shuah. The sons of Jokshan: Sheba and Dedan.'),
  ('BSB', '1 Chronicles', 13, 1, 33, 'The sons of Midian: Ephah, Epher, Hanoch, Abida, and Eldaah. All of these were Keturah’s sons.'),
  ('BSB', '1 Chronicles', 13, 1, 34, 'Abraham was the father of Isaac. The sons of Isaac: Esau and Israel.'),
  ('BSB', '1 Chronicles', 13, 1, 35, 'The sons of Esau: Eliphaz, Reuel, Jeush, Jalam, and Korah.'),
  ('BSB', '1 Chronicles', 13, 1, 36, 'The sons of Eliphaz: Teman, Omar, Zepho, Gatam, and Kenaz; and by Timna, Amalek.'),
  ('BSB', '1 Chronicles', 13, 1, 37, 'The sons of Reuel: Nahath, Zerah, Shammah, and Mizzah.'),
  ('BSB', '1 Chronicles', 13, 1, 38, 'The sons of Seir: Lotan, Shobal, Zibeon, Anah, Dishon, Ezer, and Dishan.'),
  ('BSB', '1 Chronicles', 13, 1, 39, 'The sons of Lotan: Hori and Homam. Timna was Lotan’s sister.'),
  ('BSB', '1 Chronicles', 13, 1, 40, 'The sons of Shobal: Alvan, Manahath, Ebal, Shepho, and Onam. The sons of Zibeon: Aiah and Anah.'),
  ('BSB', '1 Chronicles', 13, 1, 41, 'The son of Anah: Dishon. The sons of Dishon: Hemdan, Eshban, Ithran, and Cheran.'),
  ('BSB', '1 Chronicles', 13, 1, 42, 'The sons of Ezer: Bilhan, Zaavan, and Akan. The sons of Dishan: Uz and Aran.'),
  ('BSB', '1 Chronicles', 13, 1, 43, 'These are the kings who reigned in the land of Edom before any king reigned over the Israelites: Bela son of Beor. His city was named Dinhabah.'),
  ('BSB', '1 Chronicles', 13, 1, 44, 'When Bela died, Jobab son of Zerah from Bozrah reigned in his place.'),
  ('BSB', '1 Chronicles', 13, 1, 45, 'When Jobab died, Husham from the land of the Temanites reigned in his place.'),
  ('BSB', '1 Chronicles', 13, 1, 46, 'When Husham died, Hadad son of Bedad, who defeated Midian in the country of Moab, reigned in his place. And the name of his city was Avith.'),
  ('BSB', '1 Chronicles', 13, 1, 47, 'When Hadad died, Samlah from Masrekah reigned in his place.'),
  ('BSB', '1 Chronicles', 13, 1, 48, 'When Samlah died, Shaul from Rehoboth on the Euphrates reigned in his place.'),
  ('BSB', '1 Chronicles', 13, 1, 49, 'When Shaul died, Baal-hanan son of Achbor reigned in his place.'),
  ('BSB', '1 Chronicles', 13, 1, 50, 'When Baal-hanan died, Hadad reigned in his place. His city was named Pau, and his wife’s name was Mehetabel daughter of Matred, the daughter of Me-zahab.'),
  ('BSB', '1 Chronicles', 13, 1, 51, 'Then Hadad died. Now the chiefs of Edom were Timna, Alvah, Jetheth,'),
  ('BSB', '1 Chronicles', 13, 1, 52, 'Oholibamah, Elah, Pinon,'),
  ('BSB', '1 Chronicles', 13, 1, 53, 'Kenaz, Teman, Mibzar,'),
  ('BSB', '1 Chronicles', 13, 1, 54, 'Magdiel, and Iram. These were the chiefs of Edom.'),
  ('BSB', '1 Chronicles', 13, 2, 1, 'These were the sons of Israel:'),
  ('BSB', '1 Chronicles', 13, 2, 2, 'Reuben, Simeon, Levi, Judah, Issachar, Zebulun, Dan, Joseph, Benjamin, Naphtali, Gad, and Asher.'),
  ('BSB', '1 Chronicles', 13, 2, 3, 'The sons of Judah: Er, Onan, and Shelah. These three were born to him by Bath-shua the Canaanite. Er, Judah’s firstborn, was wicked in the sight of the LORD, who put him to death.'),
  ('BSB', '1 Chronicles', 13, 2, 4, 'Tamar, Judah’s daughter-in-law, bore to him Perez and Zerah. Judah had five sons in all.'),
  ('BSB', '1 Chronicles', 13, 2, 5, 'The sons of Perez: Hezron and Hamul.'),
  ('BSB', '1 Chronicles', 13, 2, 6, 'The sons of Zerah: Zimri, Ethan, Heman, Calcol, and Dara—five in all.'),
  ('BSB', '1 Chronicles', 13, 2, 7, 'The son of Carmi: Achar, who brought trouble upon Israel by violating the ban on devoted things.'),
  ('BSB', '1 Chronicles', 13, 2, 8, 'The son of Ethan: Azariah.'),
  ('BSB', '1 Chronicles', 13, 2, 9, 'The sons who were born to Hezron: Jerahmeel, Ram, and Caleb.'),
  ('BSB', '1 Chronicles', 13, 2, 10, 'Ram was the father of Amminadab, and Amminadab was the father of Nahshon, a leader of the descendants of Judah.'),
  ('BSB', '1 Chronicles', 13, 2, 11, 'Nahshon was the father of Salmon, and Salmon was the father of Boaz.'),
  ('BSB', '1 Chronicles', 13, 2, 12, 'Boaz was the father of Obed, and Obed was the father of Jesse.'),
  ('BSB', '1 Chronicles', 13, 2, 13, 'Jesse was the father of Eliab his firstborn; Abinadab was born second, Shimea third,'),
  ('BSB', '1 Chronicles', 13, 2, 14, 'Nethanel fourth, Raddai fifth,'),
  ('BSB', '1 Chronicles', 13, 2, 15, 'Ozem sixth, and David seventh.'),
  ('BSB', '1 Chronicles', 13, 2, 16, 'Their sisters were Zeruiah and Abigail. And the three sons of Zeruiah were Abishai, Joab, and Asahel.'),
  ('BSB', '1 Chronicles', 13, 2, 17, 'Abigail was the mother of Amasa, whose father was Jether the Ishmaelite.'),
  ('BSB', '1 Chronicles', 13, 2, 18, 'Caleb son of Hezron had children by his wife Azubah and by Jerioth. These were the sons of Azubah: Jesher, Shobab, and Ardon.'),
  ('BSB', '1 Chronicles', 13, 2, 19, 'When Azubah died, Caleb married Ephrath, who bore to him Hur.'),
  ('BSB', '1 Chronicles', 13, 2, 20, 'Hur was the father of Uri, and Uri was the father of Bezalel.'),
  ('BSB', '1 Chronicles', 13, 2, 21, 'Later, Hezron slept with the daughter of Machir the father of Gilead. He had married her when he was sixty years old, and she bore to him Segub.'),
  ('BSB', '1 Chronicles', 13, 2, 22, 'Segub was the father of Jair, who had twenty-three cities in the land of Gilead.'),
  ('BSB', '1 Chronicles', 13, 2, 23, 'But Geshur and Aram captured Havvoth-jair, along with Kenath and its sixty surrounding villages. All these were descendants of Machir the father of Gilead.'),
  ('BSB', '1 Chronicles', 13, 2, 24, 'After Hezron died in Caleb-ephrathah, his wife Abijah bore to him Ashhur the father of Tekoa.'),
  ('BSB', '1 Chronicles', 13, 2, 25, 'The sons of Jerahmeel the firstborn of Hezron:'),
  ('BSB', '1 Chronicles', 13, 2, 26, 'Ram his firstborn, Bunah, Oren, Ozem, and Ahijah. Jerahmeel had another wife named Atarah, who was the mother of Onam.'),
  ('BSB', '1 Chronicles', 13, 2, 27, 'The sons of Ram the firstborn of Jerahmeel: Maaz, Jamin, and Eker.'),
  ('BSB', '1 Chronicles', 13, 2, 28, 'The sons of Onam: Shammai and Jada. The sons of Shammai:'),
  ('BSB', '1 Chronicles', 13, 2, 29, 'Nadab and Abishur. Abishur’s wife was named Abihail, and she bore to him Ahban and Molid.'),
  ('BSB', '1 Chronicles', 13, 2, 30, 'The sons of Nadab: Seled and Appaim. Seled died without children.'),
  ('BSB', '1 Chronicles', 13, 2, 31, 'The son of Appaim: Ishi. The son of Ishi: Sheshan. The son of Sheshan: Ahlai.'),
  ('BSB', '1 Chronicles', 13, 2, 32, 'The sons of Jada the brother of Shammai: Jether and Jonathan. Jether died without children.'),
  ('BSB', '1 Chronicles', 13, 2, 33, 'The sons of Jonathan: Peleth and Zaza. These were the descendants of Jerahmeel.'),
  ('BSB', '1 Chronicles', 13, 2, 34, 'Sheshan had no sons, but only daughters; but he did have an Egyptian servant named Jarha.'),
  ('BSB', '1 Chronicles', 13, 2, 35, 'Sheshan gave his daughter in marriage to his servant Jarha, and she bore to him Attai.'),
  ('BSB', '1 Chronicles', 13, 2, 36, 'Attai was the father of Nathan, Nathan was the father of Zabad,'),
  ('BSB', '1 Chronicles', 13, 2, 37, 'Zabad was the father of Ephlal, Ephlal was the father of Obed,'),
  ('BSB', '1 Chronicles', 13, 2, 38, 'Obed was the father of Jehu, Jehu was the father of Azariah,'),
  ('BSB', '1 Chronicles', 13, 2, 39, 'Azariah was the father of Helez, Helez was the father of Elasah,'),
  ('BSB', '1 Chronicles', 13, 2, 40, 'Elasah was the father of Sismai, Sismai was the father of Shallum,'),
  ('BSB', '1 Chronicles', 13, 2, 41, 'Shallum was the father of Jekamiah, and Jekamiah was the father of Elishama.'),
  ('BSB', '1 Chronicles', 13, 2, 42, 'The sons of Caleb the brother of Jerahmeel: Mesha his firstborn, who was the father of Ziph, and Mareshah his second son, who was the father of Hebron.'),
  ('BSB', '1 Chronicles', 13, 2, 43, 'The sons of Hebron:'),
  ('BSB', '1 Chronicles', 13, 2, 44, 'Korah, Tappuah, Rekem, and Shema. Shema was the father of Raham the father of Jorkeam, and Rekem was the father of Shammai.'),
  ('BSB', '1 Chronicles', 13, 2, 45, 'The son of Shammai was Maon, and Maon was the father of Beth-zur.'),
  ('BSB', '1 Chronicles', 13, 2, 46, 'Caleb’s concubine Ephah was the mother of Haran, Moza, and Gazez. Haran was the father of Gazez.'),
  ('BSB', '1 Chronicles', 13, 2, 47, 'The sons of Jahdai: Regem, Jotham, Geshan, Pelet, Ephah, and Shaaph.'),
  ('BSB', '1 Chronicles', 13, 2, 48, 'Caleb’s concubine Maacah was the mother of Sheber and Tirhanah.'),
  ('BSB', '1 Chronicles', 13, 2, 49, 'She was also the mother of Shaaph father of Madmannah, and of Sheva father of Machbenah and Gibea. Caleb’s daughter was Acsah.'),
  ('BSB', '1 Chronicles', 13, 2, 50, 'These were the descendants of Caleb. The sons of Hur the firstborn of Ephrathah:'),
  ('BSB', '1 Chronicles', 13, 2, 51, 'Shobal the father of Kiriath-jearim, Salma the father of Bethlehem, and Hareph the father of Beth-gader.'),
  ('BSB', '1 Chronicles', 13, 2, 52, 'These were the descendants of Shobal the father of Kiriath-jearim:'),
  ('BSB', '1 Chronicles', 13, 2, 53, 'Haroeh, half the Manahathites, and the clans of Kiriath-jearim—the Ithrites, Puthites, Shumathites, and Mishraites. From these descended the Zorathites and Eshtaolites.'),
  ('BSB', '1 Chronicles', 13, 2, 54, 'The descendants of Salma:'),
  ('BSB', '1 Chronicles', 13, 2, 55, 'Bethlehem, the Netophathites, Atroth-beth-joab, half the Manahathites, the Zorites, and the clans of the scribes who lived at Jabez—the Tirathites, Shimeathites, and Sucathites. These are the Kenites who came from Hammath, the father of the house of Rechab.'),
  ('BSB', '1 Chronicles', 13, 3, 1, 'These were the sons of David who were born to him in Hebron: The firstborn was Amnon by Ahinoam of Jezreel; the second was Daniel by Abigail of Carmel;'),
  ('BSB', '1 Chronicles', 13, 3, 2, 'the third was Absalom the son of Maacah daughter of King Talmai of Geshur; the fourth was Adonijah the son of Haggith;'),
  ('BSB', '1 Chronicles', 13, 3, 3, 'the fifth was Shephatiah by Abital; and the sixth was Ithream by his wife Eglah.'),
  ('BSB', '1 Chronicles', 13, 3, 4, 'These six sons were born to David in Hebron, where he reigned seven years and six months. And David reigned in Jerusalem thirty-three years,'),
  ('BSB', '1 Chronicles', 13, 3, 5, 'and these sons were born to him in Jerusalem: Shimea, Shobab, Nathan, and Solomon. These four were born to him by Bathsheba daughter of Ammiel.'),
  ('BSB', '1 Chronicles', 13, 3, 6, 'David’s other sons were Ibhar, Elishua, Eliphelet,'),
  ('BSB', '1 Chronicles', 13, 3, 7, 'Nogah, Nepheg, Japhia,'),
  ('BSB', '1 Chronicles', 13, 3, 8, 'Elishama, Eliada, and Eliphelet—nine in all.'),
  ('BSB', '1 Chronicles', 13, 3, 9, 'These were all the sons of David, besides the sons by his concubines. And Tamar was their sister.'),
  ('BSB', '1 Chronicles', 13, 3, 10, 'Solomon’s son was Rehoboam:'),
  ('BSB', '1 Chronicles', 13, 3, 11, 'Abijah was his son, Asa his son, Jehoshaphat his son, Joram his son, Ahaziah his son, Joash his son,'),
  ('BSB', '1 Chronicles', 13, 3, 12, 'Amaziah his son, Azariah his son, Jotham his son,'),
  ('BSB', '1 Chronicles', 13, 3, 13, 'Ahaz his son, Hezekiah his son, Manasseh his son,'),
  ('BSB', '1 Chronicles', 13, 3, 14, 'Amon his son, and Josiah his son.'),
  ('BSB', '1 Chronicles', 13, 3, 15, 'The sons of Josiah: Johanan was the firstborn, Jehoiakim the second, Zedekiah the third, and Shallum the fourth.'),
  ('BSB', '1 Chronicles', 13, 3, 16, 'The successors of Jehoiakim: Jeconiah his son, and Zedekiah.'),
  ('BSB', '1 Chronicles', 13, 3, 17, 'The descendants of Jeconiah the captive:'),
  ('BSB', '1 Chronicles', 13, 3, 18, 'Shealtiel his son, Malchiram, Pedaiah, Shenazzar, Jekamiah, Hoshama, and Nedabiah.'),
  ('BSB', '1 Chronicles', 13, 3, 19, 'The sons of Pedaiah: Zerubbabel and Shimei. The children of Zerubbabel:'),
  ('BSB', '1 Chronicles', 13, 3, 20, 'Meshullam and Hananiah, their sister Shelomith, and five others: Hashubah, Ohel, Berechiah, Hasadiah, and Jushab-hesed.'),
  ('BSB', '1 Chronicles', 13, 3, 21, 'The descendants of Hananiah: Pelatiah, Jeshaiah, and the sons of Rephaiah, of Arnan, of Obadiah, and of Shecaniah.'),
  ('BSB', '1 Chronicles', 13, 3, 22, 'The six descendants of Shecaniah were Shemaiah and his sons: Hattush, Igal, Bariah, Neariah, and Shaphat.'),
  ('BSB', '1 Chronicles', 13, 3, 23, 'The sons of Neariah: Elioenai, Hizkiah, and Azrikam—three in all.'),
  ('BSB', '1 Chronicles', 13, 3, 24, 'The sons of Elioenai: Hodaviah, Eliashib, Pelaiah, Akkub, Johanan, Delaiah, and Anani—seven in all.'),
  ('BSB', '1 Chronicles', 13, 4, 1, 'The descendants of Judah: Perez, Hezron, Carmi, Hur, and Shobal.'),
  ('BSB', '1 Chronicles', 13, 4, 2, 'Reaiah son of Shobal was the father of Jahath, and Jahath was the father of Ahumai and Lahad. These were the clans of the Zorathites.'),
  ('BSB', '1 Chronicles', 13, 4, 3, 'These were the sons of Etam: Jezreel, Ishma, and Idbash. And their sister was named Hazzelelponi.'),
  ('BSB', '1 Chronicles', 13, 4, 4, 'Penuel was the father of Gedor, and Ezer was the father of Hushah. These were the descendants of Hur, the firstborn of Ephrathah and the father of Bethlehem.'),
  ('BSB', '1 Chronicles', 13, 4, 5, 'Ashhur the father of Tekoa had two wives, Helah and Naarah.'),
  ('BSB', '1 Chronicles', 13, 4, 6, 'Naarah bore to him Ahuzzam, Hepher, Temeni, and Haahashtari. These were the descendants of Naarah.'),
  ('BSB', '1 Chronicles', 13, 4, 7, 'The sons of Helah were Zereth, Zohar, Ethnan,'),
  ('BSB', '1 Chronicles', 13, 4, 8, 'and Koz, who was the father of Anub and Zobebah and of the clans of Aharhel son of Harum.'),
  ('BSB', '1 Chronicles', 13, 4, 9, 'Now Jabez was more honorable than his brothers. His mother had named him Jabez, saying, “Because I bore him in pain.”'),
  ('BSB', '1 Chronicles', 13, 4, 10, 'And Jabez called out to the God of Israel, “If only You would bless me and enlarge my territory! May Your hand be with me and keep me from harm, so that I will be free from pain.” And God granted the request of Jabez.'),
  ('BSB', '1 Chronicles', 13, 4, 11, 'Chelub the brother of Shuhah was the father of Mehir, who was the father of Eshton.'),
  ('BSB', '1 Chronicles', 13, 4, 12, 'Eshton was the father of Beth-rapha, of Paseah, and of Tehinnah the father of Ir-nahash. These were the men of Recah.'),
  ('BSB', '1 Chronicles', 13, 4, 13, 'The sons of Kenaz: Othniel and Seraiah. The sons of Othniel: Hathath and Meonothai.'),
  ('BSB', '1 Chronicles', 13, 4, 14, 'Meonothai was the father of Ophrah, and Seraiah was the father of Joab, the father of those living in Ge-harashim, which was given this name because its people were craftsmen.');
